COPLAS_PIEZA(0, [["rm_t2-n1073",0,"¡Jole con jole con jole!\n¡Jole con jole, salero!\n¡Faitigas me dan de muerte\nCuando beo un cuerpo güeno!",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,12,12,"1073","",0,"","","",3,0,0,[],""],["rm_t2-n1074",0,"¡Jole con jole con jole!\n¡Jole de la nebería!\nÉchel' usté á esa muchacha\nPor mi cuenta lo que pia.",0,0,-1,0,"",0,4,"ia",0,0,-1,0,12,12,"1074","",0,"","","",3,0,0,[],""],["rm_t2-n1075",0,"¡Salero, viva el salero!\n¡Salero, viva la sal!\nQue tiene usté más salero\nQue el salero universal.",0,0,-1,0,"",1,4,"a",1,0,-1,0,12,12,"1075","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1076",0,"¡Salero, viva el salero,\nCarita de serafin!\n¡Cuántas horitas de sueño\nTengo perdidas por tí!",0,0,-1,0,"",0,4,"i",-1,0,-1,0,12,12,"1076","",0,"lafuente_madrid, palau_cantares","","",6,0,0,[],""],["rm_t2-n1077",0,"¡Salero, biba 'r salero!\n¡Salero, biba 'l amó!\n¡Salero, biba la mare,\nSalero, que te parió!",0,0,-1,0,"",0,4,"o",2,0,-1,0,13,13,"1077","",0,"","","",2,0,0,[],""],["rm_t2-n1079",0,"La madre que te parió\nEra una rosa temprana\nY se le cayó una hoja,\nQue eres tú, linda serrana.",0,0,-1,0,"",0,4,"aa",4,0,-1,0,13,13,"1079","",0,"","","",6,0,0,[],""],["rm_t2-n1080",0,"De los piés á la cabeza\nEres un ramo de flores.\n¡Bendita sea la madre\nQue por tí pasó dolores!",0,0,-1,0,"",0,4,"oe",5,0,-1,0,13,13,"1080","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1081",0,"La madre de esta doncella,\n¡Qué contentita estará!\nPues tiene en su casa rosas,\nSin tener ningun rosal.",0,0,-1,0,"",0,4,"a",-1,0,-1,0,13,13,"1081","",0,"","","",1,0,0,[],""],["rm_t2-n1082",0,"¡Qué contentita estará\nLa madre de esta doncella!\nEstando el cielo tan alto,\nTiene en su casa una estrella.",0,0,-1,0,"",0,4,"ea",6,0,-1,0,13,13,"1082","",0,"","","",3,0,0,[],""],["rm_t2-n1083",0,"La madre que te parió\nMerecia parir veinte\nY que yo fuera el diezmero\nY me tocaras en suerte.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,13,13,"1083","",0,"","","",6,0,0,[],""],["rm_t2-n1084",0,"Mal hizo en tenerte sola\nLa bendita de tu madre:\nAngelitos como tú\nSe deben tener á pares.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,14,14,"1084","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1085",0,"En er sielo n' hay faroles,\nQue todas son estreyitas.\n¡Bendita sea la mare\nQue te parió tan bonita!",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,14,14,"1085","",0,"","","",1,0,0,[],""],["rm_t2-n1087",0,"Tendí er pañuelo 'n er prao\nY me se yenó de rosas.\n¡Bendita sea la mare\nQue te parió tan j ermosa!",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,14,14,"1087","",0,"","","",1,0,0,[],""],["rm_t2-n1088",0,"La madre que te parió\nMerecia ser la reina,\nTu padre el duque de Alba\nY yo tu adorada prenda.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,14,14,"1088","",0,"","","",6,0,0,[],""],["rm_t2-n1091",0,"¡And' usté, armasen de grasia,\nCuerpo de corregiora!\nSi yo juera 'r rey d' Holanda\nTe ponia una corona.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,15,15,"1091","",0,"","","",1,0,0,[],""],["rm_t2-n1092",0,"Quisiera ser Dios del cielo,\nReina mia, para darte\nLa corona del Imperio\nY de España el estandarte.",0,0,-1,0,"",0,4,"ae",8,0,-1,0,15,15,"1092","",0,"","","",1,0,0,[],""],["rm_t2-n1093",0,"Á la mia compañera\nLe tengo de regalá\nLa corona con er setro\nPorqu' es presoniya reá.",0,0,-1,0,"",3,4,"a",9,0,-1,0,15,15,"1093","",0,"","","",1,0,0,[],""],["rm_t2-n1094",0,"Con esa gargantillita\nY esos pendientes de lazo\nSe parece usté á la reina\nCuando sale de palacio.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,15,15,"1094","",0,"","","",1,0,0,[],""],["rm_t2-n1095",0,"Cuando te veo en la calle\nHablando con tus amigos,\nPareces el rey de todos,\nDulce espejo en que me miro.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,15,15,"1095","",0,"","","",1,0,0,[],""],["rm_t2-n1096",0,"Al revolver una esquina\nMe dieron tus resplandores\nY por eso vengo, niña,\nA coronarte de flores.",0,0,-1,0,"",0,4,"oe",5,0,-1,0,15,15,"1096","",0,"","","",1,0,0,[],""],["rm_t2-n1097",0,"Los ángeles te coronen\nY te lleven á la gloria\nY te pongan á los piés\nDe la Divina Pastora.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,15,15,"1097","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n1098",0,"Ya viene Marzo con flores\nY con sus rosas Abril\nY Mayo con sus claveles,\nPara coronarte á tí.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,16,16,"1098","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1099",0,"¡Qué linda moza te has hecho!\n¡Qué alta y qué gallardona!\nEl mismo rey coronado\nSe merece tu persona.",0,0,-1,0,"",0,4,"oa",7,0,-1,0,16,16,"1099","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1100",0,"Desde qu' entré por tu caye\nTe bengo yamando reina;\nTraigo para coronarte\nLirios, parmas y asusenas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,16,16,"1100","",0,"","","",1,0,0,[],""],["rm_t2-n1101",0,"Eres reina y más que reina\n—Y en lo dicho me mantengo—\nDesde la punta del pié\nHasta la punta del pelo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,16,16,"1101","",0,"","","",3,0,0,[],""],["rm_t2-n1102",0,"Empiezo por tus cabellos,\nQue son hebras de oro fino,\nQue me tienen prisionero\nY á mis piés les echan grillos.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,16,16,"1102","",0,"","","",1,0,0,[],""],["rm_t2-n1103",0,"Quítate esa manteyina,\nQue te quiero ber er pelo;\nQue para ber una imágen\nPrimero se escorre 'r belo.",0,0,-1,0,"",0,4,"eo",10,0,-1,0,16,16,"1103","",0,"","","",1,0,0,[],""],["rm_t2-n1104",0,"Bendita sea la madre\nQue te parió y te echó al mundo,\nPara encanto de los hombres,\nCon ese pelito rubio.",0,0,-1,0,"",0,4,"uo",-1,0,-1,0,16,16,"1104","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1105",0,"Con ese pelito rubio\nY esa cara tan divina\nEs usté la encantadora\nDe toda la estudiantina.",0,0,-1,0,"",0,4,"ia",11,0,-1,0,17,17,"1105","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1106",0,"Los cabellos de las rubias\nDicen que tienen veneno;\nAunque tengan soliman\nCabellos de rubia quiero.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,17,17,"1106","",0,"","","",4,0,0,[],""],["rm_t2-n1107",0,"Vivan los cabellos rubios,\nVivan los rubios rubiales,\nVivan los de mi rubita,\nQue son como los de nádie.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,17,17,"1107","",0,"","","",2,0,0,[],""],["rm_t2-n1108",0,"De tu pelito, rubita,\nCorté, rubita, un cabello,\nY hice una cadenita,\nRubita, y me la eché al cuello.",0,0,-1,0,"",1,4,"eo",12,0,-1,0,17,17,"1108","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1110",0,"Del cabello más sutil\nQue tienes en tu trenzado\nHe de hacer una cadena\nPara traerte á mi lado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,17,17,"1110","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1111",0,"Es tu pelo cadena\nDe muchas almas\nY cuanto más lo sueltas,\nMejor las atas.\nY como es oro,\nLa prision no hace mella,\nPorque da gozo.",0,0,-1,0,"",4,7,"oo",-1,0,-1,0,17,18,"1111","",0,"","","",2,0,0,[],""],["rm_t2-n1112",0,"Tienes el pelo rubito\nDe perlas claveteado;\nAsí me tienes á mí\nEl corazon traspasado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,18,18,"1112","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1113",0,"Los cabellos de mi rubia\nSe los ha robado al sol\nY á mí me ha robado el alma,\nLa vida y el corazon.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,18,18,"1113","",0,"","","",3,0,0,[],""],["rm_t2-n1114",0,"Tus cabellos son tales,\nHermosa niña,\nQue me matan de amores\nY al sol de envidia.\nPorque por verlos\nMe muero y al sol mismo\nAfrentan ellos.",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,18,18,"1114","",0,"","","",2,0,0,[],""],["rm_t2-n1115",0,"Si yo fuera dorador,\nLo primero que doraba\nEran los negros cabellos\nQue te cuelgan por la espalda.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,18,18,"1115","",0,"","","",1,0,0,[],""],["rm_t2-n1116",0,"Con esos ricitos, niña,\nQue te cuelgan por la frente\nPareces campana de oro\nQue vas llamando la gente.",0,0,-1,0,"",0,4,"ee",15,0,-1,0,18,18,"1116","",0,"","","",1,0,0,[],""],["rm_t2-n1117",0,"Con esa mata de pelo\nQue te cuelga por la espalda\nPareces la Magdalena\nCuando por el mundo andaba.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,18,19,"1117","",0,"","","",3,0,0,[],""],["rm_t2-n1118",0,"Las estrellas y luceros\nQue salen por el Oriente\nLos tengo comparaítos\nCon los rizos de tu frente.",0,0,-1,0,"",0,4,"ee",15,0,-1,0,19,19,"1118","",0,"","","",10,0,0,[],""],["rm_t2-n1119",0,"Er peñon de Gibrartá\nNo tiene tantos cañones\nComo tiene mi morena\nEn er pelo caracoles.",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,19,19,"1119","",0,"","","",1,0,0,[],""],["rm_t2-n1120",0,"Tienes el moño de á libra,\nLos rizos de á cuarteron;\nCon esos ojitos negros\nMe robas el corazon.",0,0,-1,0,"",5,4,"ao",-1,0,-1,0,19,19,"1120","",0,"","","",2,0,0,[],""],["rm_t2-n1121",0,"Esa madeja de pelo\nTe cuelga por las espaldas,\nDe dia, por hermosura;\nDe noche, por almohada.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,19,19,"1121","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1122",0,"Con esa mata de pelo\nY esa cara de sandunga\nTiene usté más hombres muertos\nQue tiene Isabel segunda.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,19,19,"1122","",0,"","","",3,0,0,[],""],["rm_t2-n1123",0,"Forman tus cejas dos arcos\nCon un entrecejo enmedio,\nQue parece Abril y Mayo\nCuando de flor están llenos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,19,19,"1123","",0,"","","",1,0,0,[],""],["rm_t2-n1124",0,"Tiene el moreno que adoro\nEl entrecejo arqueado,\nLos ojos grandes y hermosos\nY es buen mozo y agraciado.",0,0,-1,0,"",3,4,"ao",14,0,-1,0,20,20,"1124","",0,"","","",1,0,0,[],""],["rm_t2-n1125",0,"Todo el mundo traigo andado\nY no he podido encontrar\nOjitos como los tuyos\nNi en Francia ni en Portugal.",0,0,-1,0,"",0,4,"a",-1,0,-1,0,20,20,"1125","",0,"","","",1,0,0,[],""],["rm_t2-n1126",0,"Ojos como los tuyos\nNo van al Prado,\nNi tampoco salero\nTan resalado.",0,0,-1,0,"",6,4,"ao",14,0,-1,0,20,20,"1126","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1127",0,"No hay ojos más hermosos\nQue son los tuyos,\nY más cuando me miras\nCon disimulo.\nY si los pones\nUn poquito dormidos,\n¡Caramba! entónces....",0,0,-1,0,"",4,7,"oe",-1,0,-1,0,20,20,"1127","",0,"","","",3,0,0,[],""],["rm_t2-n1128",0,"Ojos disimulados\nSon los mejores,\nPorque logran á tiempo\nLas ocasiones.",0,0,-1,0,"",6,4,"oe",-1,0,-1,0,20,20,"1128","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1129",0,"Tienes unos ojos, niña,\nQue si los dieras á censo,\nNo faltara quien te diera\nUn veinticinco por ciento.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,20,20,"1129","",0,"palau_cantares, lafuente_madrid","","",13,0,0,[],""],["rm_t2-n1130",0,"Tienes unos ojos, niña,\nTan hechos á la humildad,\nQue cuando vas por la calle\nPareces la Soledad.",0,0,-1,0,"",0,4,"a",16,0,-1,0,21,21,"1130","",0,"palau_cantares, lafuente_madrid","","",13,0,0,[],""],["rm_t2-n1131",0,"Tienes unos ojillos\nMuy halagüeños,\nPorque dan esperanzas\nY nó tormentos.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,21,21,"1131","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n1132",0,"Tienes ojos de paloma,\nMejillas de leche y sangre\nY los cabellitos rubios,\nComo la Virgen del Cármen.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,21,21,"1132","",0,"","","",3,0,0,[],""],["rm_t2-n1134",0,"Lo blanquito de tus ojos\nCon las venillas azules\nSe parecen á los cielos\nCuando se cargan de nubes.",0,0,-1,0,"",0,4,"ue",-1,0,-1,0,21,21,"1134","",0,"","","",1,0,0,[],""],["rm_t2-n1135",0,"Á tus ojos les llaman\nExtremadura,\nPorque son extremados\nEn hermosura.",0,0,-1,0,"",6,4,"ua",17,0,-1,0,21,21,"1135","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1136",0,"Á tus ojos les llaman\nSierra-Bullones,\nPues pelean por ellos\nLos españoles.",0,0,-1,0,"",6,4,"oe",-1,0,-1,0,21,21,"1136","",0,"","","",3,0,0,[],""],["rm_t2-n1137",0,"Esos ojitos azules\nSe los has robado al cielo\nY al cielo le darás cuenta\nDel mal que hiciste con ellos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,22,22,"1137","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1138",0,"Tienes ojos azules,\nOjos de gloria,\nY los mios te piden\nMisericordia.",0,0,-1,0,"",6,4,"oa",-1,0,-1,0,22,22,"1138","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1139",0,"Amarillo es el oro,\nBlanca la plata\nY azules son los ojos\nQue á mí me matan.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,22,22,"1139","",0,"","","",5,0,0,[],""],["rm_t2-n1140",0,"Ojos azules del alma,\nApacibles y risueños,\nDesde el punto que los ví\nMe estoy muriendo por ellos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,22,22,"1140","",0,"","","",1,0,0,[],""],["rm_t2-n1141",0,"Por unos ojos negros\nSe perdió Troya\nY por unos azules\nLa España toda.",0,0,-1,0,"",6,4,"oa",-1,0,-1,0,22,22,"1141","",0,"","","",1,0,0,[],""],["rm_t2-n1143",0,"De nácar es tu frente,\nDe oro tu pelo\nY tus ojos azules\nDe azul de cielo.\nY tus pupilas\nDestilan hermosura\nCuando me miras.",0,0,-1,0,"",4,7,"ia",-1,0,-1,0,22,23,"1143","",0,"","","",1,0,0,[],""],["rm_t2-n1144",0,"Por unos ojos azules\nAlma y vida diera yo;\nPor unos ojitos negros,\nAlma, vida y corazon.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,23,23,"1144","",0,"","","",1,0,0,[],""],["rm_t2-n1145",0,"Si quieres cambiar, cambia;\nYo cambiar quiero\nUnos ojos azules\nPor unos negros.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,23,23,"1145","",0,"","","",1,0,0,[],""],["rm_t2-n1146",0,"Tienes unos ojos, niña,\nMás negros que el azabache\nY una carita más blanca\nQue la leche que mamaste.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,23,23,"1146","",0,"palau_cantares, lafuente_madrid","","",13,0,0,[],""],["rm_t2-n1147",0,"Unos ojos negros ví\nY dije:-¡Válgame el cielo!\n¡Tanto luto para mí!\n¡No sé cómo no me muero!",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,23,23,"1147","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1148",0,"Todo lo negro es feo;\nPero tus ojos\nLo que tienen de negros\nTienen de hermosos.\nLo que es extraño\nQue siendo negros, tengan\nTantos esclavos.",0,0,-1,0,"",4,7,"ao",-1,0,-1,0,23,23,"1148","",0,"","","",1,0,0,[],""],["rm_t2-n1149",0,"A todos los ojos negros\nLos aprisionan mañana;\nTú, morena, que los tienes,\nEcha un empeño á la sala.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,23,24,"1149","",0,"","","",3,0,0,[],""],["rm_t2-n1150",0,"Los ojos de mi niña\nSon de pan tierno\nY los mios de hambre\nSe están muriendo.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,24,24,"1150","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1151",0,"Ojos negros y risueños,\nBoquita de serafin,\nEstoy soñando contigo\nDesde el dia en que te ví.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,24,24,"1151","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1152",0,"Que Amor busque tus ojos\nNo es cosa extraña;\nPues, como ciego, busca\nLo que le falta.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,24,24,"1152","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1153",0,"Tus ojos tienen la culpa\nCuando los flechas, endina,\nDe que tenga yo este cuerpo\nLo mismo que jaletina.",0,0,-1,0,"",0,4,"ia",11,0,-1,0,24,24,"1153","",0,"","","",3,0,0,[],""],["rm_t2-n1154",0,"¡Qué ojos tan atractivos\nTienes, morena!\n¿Quieres que los juguemos\nA la rayuela?\nY si los pierdes,\nAunque malos los mios,\nAquí los tienes.",0,0,-1,0,"",4,7,"ee",-1,0,-1,0,24,24,"1154","",0,"","","",1,0,0,[],""],["rm_t2-n1155",0,"Tienes unos ojitos\nAdormilados,\nQue es preciso quererlos\nA ojos cerrados.",0,0,-1,0,"",6,4,"ao",18,0,-1,0,24,25,"1155","",0,"palau_cantares, fernan_caballero","","",20,0,0,[],""],["rm_t2-n1156",0,"Los ojos de mi niña,\n¡Qué gracia tienen!\nUn poquito dormidos,\nPorque yo vele.\nY aunque dormidos,\nMe tienen bien despierto\nY sin sentido.",0,0,-1,0,"",4,7,"io",-1,0,-1,0,25,25,"1156","",0,"","","",4,0,0,[],""],["rm_t2-n1157",0,"Tus ojos son dos espejos\nEn donde me miro yo;\nNo los cierres, vida mia;\nNo los cierres; ábrelos.",0,0,-1,0,"",5,4,"ao",-1,0,-1,0,25,25,"1157","",0,"","","",1,0,0,[],""],["rm_t2-n1158",0,"De tus hermosos ojos\nNo tengo queja:\nEllos quieren mirarme,\nTú no los dejas.\nDéjalo, ingrato;\nDéjalos que me miren\nSiquiera un rato.",0,0,-1,0,"",4,7,"ao",19,0,-1,0,25,25,"1158","",0,"","","",5,0,0,[],""],["rm_t2-n1159",0,"Del balcon de tus ojos\nDí una caida;\nLevantarme no puedo\nSi no me miras.\nMe he levantado:\nEs señal que tus ojos\nMe habrán mirado.",0,0,-1,0,"",4,7,"ao",14,0,-1,0,25,25,"1159","",0,"","","",1,0,0,[],""],["rm_t2-n1160",0,"Los ojos de mi morena\nNi son chicos ni son grandes;\nSon como acitunas negras\nDe olibaritos gordales.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,25,26,"1160","",0,"","","",23,0,0,[],""],["rm_t2-n1161",0,"Ni son chicos ni son grandes\nLos ojos de mi amadora...\nSon como quesos de Flandes,\nQue entran dos en cada arroba.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,26,26,"1161","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1162",0,"Los ojos de mi morena\nSe parecen á mis males:\nGrandes como mis fatigas,\nNegros como mis pesares.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,26,26,"1162","",0,"fernan_caballero","","",23,0,0,[],""],["rm_t2-n1163",0,"Con ese mô de mirá\nY ese semblante risueño\nBal' usté más pesetitas\nQu' estreyitas tiene 'r sielo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,26,26,"1163","",0,"","","",1,0,0,[],""],["rm_t2-n1165",0,"Tus ojos para soles\nSon muy pequeños;\nPara estrellas son grandes:\nSerán luceros.\nPero en tu cara\nLucen más que el que alumbra\nPor la mañana.",0,0,-1,0,"",4,7,"aa",-1,0,-1,0,26,26,"1165","",0,"","","",2,0,0,[],""],["rm_t2-n1166",0,"Los ojos de mi morena\nSon dos brillantes luceros,\nQue si me miran, me matan;\nSi no me miran, me muero.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,26,26,"1166","",0,"carrizo_salta","","",23,0,0,[],""],["rm_t2-n1167",0,"Los ojos de mi morena\nMe parecieron ayer\nEse lucero que sale\nA eso del amanecer.",0,0,-1,0,"",0,4,"e",20,0,-1,0,27,27,"1167","",0,"palau_cantares, lafuente_madrid","","",23,0,0,[],""],["rm_t2-n1168",0,"Son tus ojos dos luceros\nPuestos en tan alta estima,\nQue en sólo haberlos mirado\nSe me ha turbado la vista.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,27,27,"1168","",0,"lafuente_madrid, palau_cantares","","",8,0,0,[],""],["rm_t2-n1169",0,"Son tus ojos dos luceros,\nTu boca un clavel de Mayo\nY tus mejillas dos rosas;\nHazme dueño de ese ramo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,27,27,"1169","",0,"","","",8,0,0,[],""],["rm_t2-n1170",0,"Son tus ojos dos luceros\nQue iluminan todo el mar;\n¡Quién fuera marinerito,\nPara poder navegar!",0,0,-1,0,"",0,4,"a",21,0,-1,0,27,27,"1170","",0,"","","",8,0,0,[],""],["rm_t2-n1171",0,"Por la estrellita del Norte\nSe guian los marineros;\nYo me guio por tus ojos,\nQue parecen dos luceros.",0,0,-1,0,"",0,4,"eo",22,0,-1,0,27,27,"1171","",0,"","","",1,0,0,[],""],["rm_t2-n1172",0,"Navegando en esos mares,\nNavegando me perdí\nY con la luz de tus ojos\nUn puerto de España ví.",0,0,-1,0,"",0,4,"i",23,0,-1,0,27,27,"1172","",0,"","","",1,0,0,[],""],["rm_t2-n1173",0,"Tus cejas son medias lunas\nY tus ojos dos luceros,\nQue alumbran de noche y dia,\nSiendo más que los del cielo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,27,27,"1173","",0,"","","",3,0,0,[],""],["rm_t2-n1175",0,"A las doce del dia\nVí dos luceros:\nNo te extrañes, pues eran\nTus ojos negros.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,28,28,"1175","",0,"","","",1,0,0,[],""],["rm_t2-n1177",0,"¿Qué es aquello que reluce\nEncima del campanario?\n¿Es estrella, son tus ojos,\nO es la Virgen del Rosario?",0,0,-1,0,"",0,4,"ao",25,0,-1,0,28,28,"1177","",0,"","","",8,0,0,[],""],["rm_t2-n1180",0,"Las estrellitas del cielo\nNo pueden estar cabales,\nPorque en la cara mi niña\nTiene las dos principales.",0,0,-1,0,"",0,4,"ae",26,0,-1,0,28,28,"1180","",0,"carrizo_salta","","",25,0,0,[],""],["rm_t2-n1181",0,"Las estrellas del cielo\nSon ciento doce;\nCon las dos de tu cara,\nCiento catorce.",0,0,-1,0,"",6,4,"oe",-1,0,-1,0,29,29,"1181","",0,"","","",9,0,0,[],""],["rm_t2-n1182",0,"Las estrellas del cielo\nSon mil y siete;\nCon las dos de tu cara,\nSon mil y nueve.",0,0,-1,0,"",6,4,"ee",-1,0,-1,0,29,29,"1182","",0,"palau_cantares, fernan_caballero","","",9,0,0,[],""],["rm_t2-n1183",0,"Las estrellas del cielo\nSon ciento treinta;\nCon las dos de tu cara,\nCiento cuarenta.",0,0,-1,0,"",6,4,"ea",-1,0,-1,0,29,29,"1183","",0,"","","",9,0,0,[],""],["rm_t2-n1184",0,"A San Arcario 'r d' Osuna\nL' alumbran cuatro faroles\nY á mí m' están alumbrando\nDos ojos como dos soles.",0,0,-1,0,"",0,4,"oe",27,0,-1,0,29,29,"1184","",0,"","","",1,0,0,[],""],["rm_t2-n1185",0,"Tus ojos, bella paloma,\nLlevan pleito con el sol,\nPorque el sol es uno solo,\nTus ojos dos soles son.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,29,29,"1185","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t2-n1186",0,"El sol al ver tus ojos\nCorrido huye;\nQue le des luces pide\nQue le desluces.\nPues hay más fuego\nEn tus ojos, morena,\nQue en todo el cielo.",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,29,29,"1186","",0,"","","",2,0,0,[],""],["rm_t2-n1187",0,"Salga el sol, si ha de salir,\nY si no, que nunca salga;\nQue para alumbrarme á mí,\nLa luz de tus ojos basta.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,29,30,"1187","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1188",0,"La luna se va, se va;\nDéjala usté que se vaya;\nLa luna que á mí me alumbra\nEstá en aquella ventana.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,30,30,"1188","",0,"","","",3,0,0,[],""],["rm_t2-n1189",0,"Una noche oscurita\nLloviendo estaba;\nCon la luz de tus ojos\nYo me alumbraba.",0,0,-1,0,"",6,4,"aa",28,0,-1,0,30,30,"1189","",0,"","","",1,0,0,[],""],["rm_t2-n1190",0,"Una tarde nublado\nEntré en tu casa;\nMe senté en una silla\nY el sol me daba.\nPero es de advertir\nQue el sol que á mí me daba\nEra verte á tí.",0,0,-1,0,"",4,7,"i",-1,0,-1,0,30,30,"1190","",0,"","","",2,0,0,[],""],["rm_t2-n1191",0,"Corre, niña, al espejo,\nMira tus ojos,\nQue el sol de medio dia\nNo es tan hermoso.\nMucho lo siento,\nPues de tus ojos nacen\nMis sufrimientos.",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,30,30,"1191","",0,"","","",1,0,0,[],""],["rm_t2-n1192",0,"Al infierno me fuera\nDe buena gana,\nSi la luz de tus ojos\nFueran las llamas.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,30,30,"1192","",0,"","","",1,0,0,[],""],["rm_t2-n1193",0,"Tus ojos despiden chispas;\nTus miradas son de fuego;\nPor Dios, niña, no me mires;\nNo me mires, que me quemo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,31,31,"1193","",0,"","","",1,0,0,[],""],["rm_t2-n1194",0,"Fuego y nieve despiden,\nNiña, tus ojos:\nFuego para quien amas,\nNieve á los otros.\nY yo te ruego\nQue, aunque me hagas cenizas,\nMe arrojen fuego.",0,0,-1,0,"",4,7,"eo",29,0,-1,0,31,31,"1194","",0,"","","",1,0,0,[],""],["rm_t2-n1195",0,"Tienen tus dulces ojos\nTan bellas niñas,\nQue sólo por mirarlas\nPerdí las mías.\nY no pondero:\nQue por haberlas visto\nMe quedé ciego.",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,31,31,"1195","",0,"","","",2,0,0,[],""],["rm_t2-n1196",0,"Cuando paso y te miro\nA la ventana,\nMe parece que asoma\nYa la mañana.\nTe miro y luégo\nA la luz de tus ojos\nMe quedo ciego.",0,0,-1,0,"",4,7,"eo",29,0,-1,0,31,31,"1196","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1197",0,"Sólo tus bellos ojos\nHacer pudieron\nQue algun dia los mios\nQuedasen ciegos.\nPues ciego vivo,\nSé tú, dueño adorado,\nMi lazarillo.",0,0,-1,0,"",4,7,"io",-1,0,-1,0,31,32,"1197","",0,"","","",3,0,0,[],""],["rm_t2-n1198",0,"El objeto adorado\nDe mis desvelos\nSon tus ojos divinos,\nLuz de los cielos.\nY brillan tanto,\nQue me quitas la vista,\nSin dar quebranto.",0,0,-1,0,"",4,7,"ao",30,0,-1,0,32,32,"1198","",0,"","","",2,0,0,[],""],["rm_t2-n1199",0,"Soles abrasadores\nTus ojos fueron,\nQue abrasaron los mios\nCuando te vieron.\nY desde entónces\nHe quedado sujeto\nA tus dos soles.",0,0,-1,0,"",4,7,"oe",-1,0,-1,0,32,32,"1199","",0,"","","",1,0,0,[],""],["rm_t2-n1200",0,"Mi corazon es cera,\nTus ojos soles;\nRepara si me miras\nCómo me pones.\nY es de manera\nQue aunque fuera de bronce,\nLo derritieras.",0,0,-1,0,"",4,7,"ea",-1,0,-1,0,32,32,"1200","",0,"","","",1,0,0,[],""],["rm_t2-n1201",0,"Tu frente es plaza de armas,\nTu nariz es el cañon\nY tus ojitos disparan\nFlechas á mi corazon.",0,0,-1,0,"",0,4,"ao",31,0,-1,0,32,32,"1201","",0,"","","",3,0,0,[],""],["rm_t2-n1202",0,"Son tus ojos cañones\nDe artillería,\nQue le están apuntando\nAl alma mia.",0,0,-1,0,"",6,4,"a",0,0,-1,0,32,33,"1202","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n1203",0,"Los ojos de mi morena\nSon un tren de artillería,\nQue nada dejan derecho\nCuando hacen la puntería.",0,0,-1,0,"",0,4,"ia",0,0,-1,0,33,33,"1203","",0,"palau_cantares, lafuente_madrid","","",23,0,0,[],""],["rm_t2-n1204",0,"Son tus ojos dos cañones\nCargados de municion\nY tus miradas son balas\nQue pasan mi corazon.",0,0,-1,0,"",0,4,"o",31,0,-1,0,33,33,"1204","",0,"","","",3,0,0,[],""],["rm_t2-n1205",0,"Cuando vide tus ojos\nDije á los mios:\n-Ya tenemos enfrente\nLos enemigos.-\nRespondió el alma:\n-Ya están haciendo fuego\nLas avanzadas.",0,0,-1,0,"",4,7,"aa",-1,0,-1,0,33,33,"1205","",0,"","","",1,0,0,[],""],["rm_t2-n1206",0,"A la salida del templo\nUnos ojos negros ví;\nDe quien eran no me acuerdo;\nQue me cautivaron, sí.",0,0,-1,0,"",0,4,"i",23,0,-1,0,33,33,"1206","",0,"","","",1,0,0,[],""],["rm_t2-n1207",0,"Unos ojillos negros\nMe han cautivado:\n¡Quién dirá que los negros\nCautivan blancos!",0,0,-1,0,"",6,4,"ao",-1,0,-1,0,33,33,"1207","",0,"","","",2,0,0,[],""],["rm_t2-n1208",0,"Tan cautivo me tienen\nTus dos luceros,\nQue aunque busco el rescate,\nJamás lo encuentro.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,33,33,"1208","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1209",0,"Toda mi vida en el mar\nNo me cautivaron moros\nY una vez que entré en tu casa\nMe cautivaron tus ojos.",0,0,-1,0,"",0,4,"oo",-1,0,-1,0,34,34,"1209","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1210",0,"Tus ojos me cautivaron,\nBlanca paloma sin hiel;\nTus ojos me cautivaron,\nQue nó los moros de Argel.",0,0,-1,0,"",1,4,"e",32,0,-1,0,34,34,"1210","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1211",0,"Al campo de tu frente\nSalí á pasear;\nMe prendieron dos negros\nDel mismo lugar.\nFueron dos negros....\n¡Ay, Jesús, niña mia,\nTus ojos fueron!",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,34,34,"1211","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1212",0,"Todos los aragoneses\nHan salido de Aragon,\nEn busca de unos ladrones;\nMorena, tus ojos son.",0,0,-1,0,"",0,4,"o",31,0,-1,0,34,34,"1212","",0,"lafuente_madrid, palau_cantares","","",6,0,0,[],""],["rm_t2-n1213",0,"A tu cara le llaman\nSierra-Morena\nY á tus ojos, ladrones\nQue andan por ella.",0,0,-1,0,"",6,4,"ea",-1,0,-1,0,34,34,"1213","",0,"","","",1,0,0,[],""],["rm_t2-n1214",0,"Por la Sierra-Morena\nBienen bajando\nUnos ojiyos negros\nDe contrabando.",0,0,-1,0,"",6,4,"ao",33,0,-1,0,34,34,"1214","",0,"","","",4,0,0,[],""],["rm_t2-n1215",0,"Tienes unos ojos negros\nRetrecheros y ladrones,\nQue salen á los caminos\nA robar los corazones.",0,0,-1,0,"",0,4,"oe",34,0,-1,0,34,35,"1215","",0,"","","",3,0,0,[],""],["rm_t2-n1216",0,"Tus ojos son ladrones,\nQue roban y hurtan;\nTus pestañas el monte\nDonde se ocultan.",0,0,-1,0,"",6,4,"ua",-1,0,-1,0,35,35,"1216","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t2-n1217",0,"Tienes unos ojitos\nDe picaporte;\nCada vez que los cierras\nSiento yo el golpe.\nÉchales llave,\nPorque me mortificas\nCuando los abres.",0,0,-1,0,"",4,7,"ae",-1,0,-1,0,35,35,"1217","",0,"","","",20,0,0,[],""],["rm_t2-n1218",0,"Al mirarme tus ojos,\nBajo los mios:\nQue tus ojos abrasan\nMás que el estío.",0,0,-1,0,"",6,4,"io",-1,0,-1,0,35,35,"1218","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t2-n1219",0,"A la luna como al sol\nMirarlos de frente puedo;\nA tí nó, porque me matas\nCon esos ojillos negros.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,35,35,"1219","",0,"","","",1,0,0,[],""],["rm_t2-n1220",0,"Sin duda que tus ojos\nTienen veneno:\nDesde que me miraste\nMe estoy muriendo:\nVuelve á mirarme,\nA ver si con tu vista\nPuedo aliviarme.",0,0,-1,0,"",4,7,"ae",35,0,-1,0,35,36,"1220","",0,"","","",1,0,0,[],""],["rm_t2-n1221",0,"Con esos ojos gachones,\nSerrana, con que me miras,\nEl corazon me lo partes,\nY el alma me la lastimas.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,36,36,"1221","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1222",0,"Tienes los ojiyos grandes\nComo piedras e molino\nY parten los corasones\nComo graniyos e trigo.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,36,36,"1222","",0,"","","",1,0,0,[],""],["rm_t2-n1223",0,"¿Qué tienen tus ojos,\nQue, cuando me miras,\nLos güesesitos,-mare, de mi cuerpo\nTòs me los lastimas?",0,0,-1,0,"",3,4,"ia",-1,0,-1,0,36,36,"1223","",0,"","","",1,0,0,[],""],["rm_t2-n1224",0,"Ese mirar que tienes\nTan hechicero\nMe tiene rota el alma,\nTambien el cuerpo.\nDile á tus ojos\nQue no me miren tanto;\nSi nó, me enojo.",0,0,-1,0,"",4,7,"oo",-1,0,-1,0,36,36,"1224","",0,"","","",1,0,0,[],""],["rm_t2-n1225",0,"Tienes unos ojitos\nQue me los clavas\nHasta el último centro\nDe mis entrañas.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,36,36,"1225","",0,"","","",20,0,0,[],""],["rm_t2-n1226",0,"Tienes unos ojitos\nDe alcalde mayor,\nQue sentencian á muerte,\nSin apelacion.",0,0,-1,0,"",6,4,"ao",-1,0,-1,0,36,36,"1226","",0,"palau_cantares","","",20,0,0,[],""],["rm_t2-n1227",0,"Son tus ojos dos señores\nJueces de chancillería,\nLos que sentencian el pleito\nY á mí me quitan la vida.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,37,37,"1227","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1228",0,"Tienes unos ojillos\nTan rechuscones,\nQue con una mirada\nMatas á un hombre.",0,0,-1,0,"",6,4,"oe",-1,0,-1,0,37,37,"1228","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n1229",0,"Tiene la Vírgen del Cármen\nUna corona de plata\nY tú tienes, vida mia,\nUnos ojos que me matan.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,37,37,"1229","",0,"","","",2,0,0,[],""],["rm_t2-n1230",0,"Si con el mirar matas,\nNiña, pregunto:\n¿Dónde vas enterrando\nTanto difunto?",0,0,-1,0,"",6,4,"uo",36,0,-1,0,37,37,"1230","",0,"","","",2,0,0,[],""],["rm_t2-n1231",0,"Con ese mirar tuyo\nMatas las almas\nY al reirte haces hoyos\nPara enterrarlas.\nFiera homicida,\nSolamente al que quieres\nDejas la vida.",0,0,-1,0,"",4,7,"ia",37,0,-1,0,37,37,"1231","",0,"","","",1,0,0,[],""],["rm_t2-n1232",0,"Si me miras, me matas;\nSi nó, me muero:\nMírame, vida mia,\nQue morir quiero.",0,0,-1,0,"",6,4,"eo",38,0,-1,0,37,37,"1232","",0,"carrizo_salta, palau_cantares","","",3,0,0,[],""],["rm_t2-n1238",0,"Dame, niña, tus ojos\nPor esta noche,\nPorque quiero con ellos\nMatar á un hombre.\nY no te admire\nQue te pida unas armas\nQue tanto rinden.",0,0,-1,0,"",4,7,"ie",-1,0,-1,0,39,39,"1238","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1239",0,"Al volver una esquina\nMe asesinaron\nY el corazon del pecho\nMe lo arrancaron.\nLos asesinos\nEran los negros ojos\nDe mi cariño.",0,0,-1,0,"",4,7,"io",-1,0,-1,0,39,39,"1239","",0,"","","",1,0,0,[],""],["rm_t2-n1240",0,"Ar reborbé d' una esquina\nDos puñalaitas me dieron;\nCon er fuego de tus ojos\n'Staba templaiyo 'l acero.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,39,39,"1240","",0,"","","",2,0,0,[],""],["rm_t2-n1241",0,"¡Madre, madre, que me matan!\nYo no me puedo valer:\nSon dos negros asesinos\nLos ojos de esta mujer.",0,0,-1,0,"",0,4,"e",20,0,-1,0,39,39,"1241","",0,"","","",3,0,0,[],""],["rm_t2-n1242",0,"Los ojos de mi morena\nTienen un mirar extraño,\nQue matan en una hora\nMás que la muerte en un año.",0,0,-1,0,"",0,4,"ao",40,0,-1,0,39,39,"1242","",0,"palau_cantares, fernan_caballero","","",23,0,0,[],""],["rm_t2-n1243",0,"Ojos negros amadores,\n¿Por qué no vos confesais\nPor las muertes que habeis hecho,\nCorazones que robais?",0,0,-1,0,"",5,4,"oa",-1,0,-1,0,40,40,"1243","",0,"","","",1,0,0,[],""],["rm_t2-n1244",0,"Tus bellos ojos matan,\nRoban, saltean,\nY, con ser malhechores,\nNo hay quien los prenda.\nPorque, homicidas,\nJamás rinden sus armas\nA la justicia.",0,0,-1,0,"",4,7,"ia",-1,0,-1,0,40,40,"1244","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1245",0,"A la sala del crímen\nLlevé tus ojos,\nPorque son dos ladrones\nFacinerosos.\nY cuando entraron,\nSe ha quejado el regente\nQue lo robaron.",0,0,-1,0,"",4,7,"ao",41,0,-1,0,40,40,"1245","",0,"","","",3,0,0,[],""],["rm_t2-n1246",0,"Tienes unos ojitos\nY unas pestañas\nY una boca hechicera\nCon que me engañas.",0,0,-1,0,"",6,4,"aa",42,0,-1,0,40,40,"1246","",0,"","","",20,0,0,[],""],["rm_t2-n1247",0,"Manojitos de alfileres,\nChiquilla, son tus pestañas,\nQue cada vez que me miras\nMe los clavas en el alma.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,40,40,"1247","",0,"","","",5,0,0,[],""],["rm_t2-n1248",0,"Manojos de alfileres\nSon tus pestañas;\nCada vez que me miras\nTodo me clavas.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,40,40,"1248","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1249",0,"Las pestañas de tus ojos\nSon negras como la mora\nY entre pestaña y pestaña\nUna estrellita se asoma.",0,0,-1,0,"",3,4,"oa",-1,0,-1,0,41,41,"1249","",0,"","","",2,0,0,[],""],["rm_t2-n1250",0,"Dame de tus pestañas\nSiquiera un pelo,\nPara que si me embarco\nSirva de remo.\nY por si acaso\nLa lancha se va á pique,\nEcharle un lazo.",0,0,-1,0,"",4,7,"ao",43,0,-1,0,41,41,"1250","",0,"","","",1,0,0,[],""],["rm_t2-n1251",0,"Échame, niña bonita,\nLágrimas en un pañuelo\nY las llevaré á Granada,\nQue las engarce un platero.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,41,41,"1251","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1252",0,"Pequeñita es la boca,\nNegros los ojos,\nSuelto y airoso el talle\nDe la que adoro.",0,0,-1,0,"",6,4,"oo",-1,0,-1,0,41,41,"1252","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1253",0,"Tienes una boca, niña,\nComo un capullo cerrado;\nDe buena gana lo abriera\nCon el soplo de mis labios.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,41,41,"1253","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1254",0,"Tienes una boquita\nTan hechicera,\nQue á batalla de besos\nMe la comiera.",0,0,-1,0,"",6,4,"ea",44,0,-1,0,41,41,"1254","",0,"","","",4,0,0,[],""],["rm_t2-n1255",0,"Tu boquita cárcel es\nSin cerrojos y sin llaves;\nLos prisioneros son perlas\nY las puertas son corales.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,41,42,"1255","",0,"","","",1,0,0,[],""],["rm_t2-n1256",0,"Los ojos y los labios\nDe cierta niña\nSon los depositarios\nDel alma mia.",0,0,-1,0,"",6,4,"a",-1,0,-1,0,42,42,"1256","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1257",0,"Del color y del brillo\nDe los rubíes\nTienes, niña, los labios\nCuando te ries.",0,0,-1,0,"",6,4,"e",-1,0,-1,0,42,42,"1257","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1258",0,"La rosa en tus mejillas\nPerdió su color\nY el clavel en tus labios\nSe disciplinó.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,42,42,"1258","",0,"","","",2,0,0,[],""],["rm_t2-n1259",0,"El encarnado clavel\nViene publicando agravios,\nPorque no lo han hecho á él\nHermoso como tus labios.",0,0,-1,0,"",1,4,"ao",45,0,-1,0,42,42,"1259","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t2-n1260",0,"Tienes, niña, en tus labios\nDos clavelitos;\nÉchales agua fresca,\nQue están marchitos.\nPero si quieres,\nMe darás la licencia\nDe que los riegue.",0,0,-1,0,"",4,7,"ee",-1,0,-1,0,42,42,"1260","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1261",0,"A tus labios rosados,\nDivina diosa,\nVan á buscar almíbar\nLas mariposas.\nDame licencia\nDe que gocen los mios\nLa preferencia.",0,0,-1,0,"",4,7,"ea",46,0,-1,0,42,43,"1261","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n1262",0,"Un pajarillo alegre\nPicó en tu boca,\nPensando que tus labios\nEran dos rosas.",0,0,-1,0,"",6,4,"oa",-1,0,-1,0,43,43,"1262","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1263",0,"No te muerdas los labios,\nQue es mala maña\nY le quitas al oro\nLa filigrana.\nY si le quitas\nLa filigrana al oro,\nNo estás bonita.",0,0,-1,0,"",4,7,"ia",-1,0,-1,0,43,43,"1263","",0,"","","",1,0,0,[],""],["rm_t2-n1264",0,"A dibujar tu cara\nMe puse un dia;\nCuando llegué á tus labios\nYa no podia.\nPorque tus labios\nNo se encuentran pinceles\nPá dibujarlos.",0,0,-1,0,"",4,7,"ao",-1,0,-1,0,43,43,"1264","",0,"","","",1,0,0,[],""],["rm_t2-n1265",0,"Capitanes de guerra\nSon tus dos labios\nY tus menudos dientes\nSon los soldados.\nY yo quisiera\nSer de ese regimiento,\nAunque muriera.",0,0,-1,0,"",4,7,"ea",44,0,-1,0,43,43,"1265","",0,"","","",3,0,0,[],""],["rm_t2-n1266",0,"Sin duda que tu padre\nFué confitero,\nY te hizo los labios\nDe caramelo.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,44,44,"1266","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1267",0,"Son tus dientes confites,\nTurron tu lengua,\nTus labios caramelos....\n¡Quién te comiera!\n¡Ay, qué alegría,\nQue se ha vuelto tu boca\nConfitería!",0,0,-1,0,"",4,7,"ia",0,0,-1,0,44,44,"1267","",0,"","","",1,0,0,[],""],["rm_t2-n1268",0,"Esos dientes y esa boca\nY ese semblante risueño\nY ese modito de andar\nMe tienen, chiquilla, muerto.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,44,44,"1268","",0,"","","",1,0,0,[],""],["rm_t2-n1269",0,"Dame un diente de tu boca,\nDe los que tienes delante;\nMe lo pondré en la pechera\nComo si fuera un diamante.",0,0,-1,0,"",0,4,"ae",47,0,-1,0,44,44,"1269","",0,"","","",5,0,0,[],""],["rm_t2-n1270",0,"Dame un diente de tu boca,\nDe los que tienes enmedio\nY lo engarzaré en diamante\nPara colgármelo al cuello.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,44,44,"1270","",0,"","","",5,0,0,[],""],["rm_t2-n1271",0,"Tus dientes, niña hechicera,\nCadenas de marfil son,\nQue me tienen presa el alma\nY tambien el corazon.",0,0,-1,0,"",0,4,"o",31,0,-1,0,44,44,"1271","",0,"","","",1,0,0,[],""],["rm_t2-n1272",0,"Los dientes de tu boquita.\nMe tienen cautivo y preso;\nEn mi vida he visto yo\nCadenas hechas de hueso.",0,0,-1,0,"",0,4,"eo",48,0,-1,0,45,45,"1272","",0,"palau_cantares, lafuente_madrid, suspiros_amor","","",6,0,0,[],""],["rm_t2-n1273",0,"Los dientes de tu boca\nMe tienen preso;\nNunca he visto cadenas\nHechas de hueso.\nMe tienen así;\nNunca he visto cadenas\nHechas de marfil.",0,0,-1,0,"",4,7,"i",-1,0,-1,0,45,45,"1273","",0,"","","",4,0,0,[],""],["rm_t2-n1274",0,"Son tus ojos ministros\nQue me prendieron\nY tu pecho la cárcel\nQue me metieron.\nTu boca audiencia\nY tu lengua la pluma\nQue me sentencia.",0,0,-1,0,"",4,7,"ea",46,0,-1,0,45,45,"1274","",0,"","","",1,0,0,[],""],["rm_t2-n1275",0,"Tus ojos son dos tinteros,\nTu nariz pluma cortada,\nTus dientes letra menuda,\nTu boca carta cerrada.",0,0,-1,0,"",0,4,"aa",49,0,-1,0,45,45,"1275","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1276",0,"Tienes un hoyo en tu barba,\nQue parece una cunita;\n¿Quieres que me meta en él\nY me cantas la nanita?",0,0,-1,0,"",0,4,"ia",50,0,-1,0,45,45,"1276","",0,"","","",2,0,0,[],""],["rm_t2-n1277",0,"En el hoyo de tu barba\nPuse una confitería;\nLos angelitos del cielo\nPor caramelos venian.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,45,45,"1277","",0,"palau_cantares","","",7,0,0,[],""],["rm_t2-n1278",0,"Si el hoyo de tu barba\nFuera pilita,\nMás de cuatro tomaran\nAgua bendita.",0,0,-1,0,"",6,4,"ia",50,0,-1,0,46,46,"1278","",0,"palau_cantares, suspiros_amor","","",3,0,0,[],""],["rm_t2-n1279",0,"Tienes un hoyo en tu barba\nY lo tienes tan pendiente,\nQue si fuera sepultura\nYo mismo me daba muerte.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,46,46,"1279","",0,"","","",2,0,0,[],""],["rm_t2-n1280",0,"María sé que te yamas;\nTu apeyido no lo sé.\nEr joyito de tu barba\nMi sepurtura ha de ser.",0,0,-1,0,"",0,4,"e",-1,0,-1,0,46,46,"1280","",0,"","","",1,0,0,[],""],["rm_t2-n1281",0,"Dolores sé que te llamas,\nPorque me lo dijo el cura;\nEn el hoyo de tu barba\nTengo yo mi sepultura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,46,46,"1281","",0,"","","",1,0,0,[],""],["rm_t2-n1282",0,"En el hoyo de tu barba\nEstoy mandado enterrar.\n¡Ay, qué muerte tan dichosa!\n¡Quién se hubiera muerto ya!",0,0,-1,0,"",0,4,"a",-1,0,-1,0,46,46,"1282","",0,"lafuente_madrid","","",7,0,0,[],""],["rm_t2-n1283",0,"No te tapes la cara,\nNiña bonita,\nQue el que tapa lo bueno,\nDios se lo quita.",0,0,-1,0,"",6,4,"ia",50,0,-1,0,46,46,"1283","",0,"","","",2,0,0,[],""],["rm_t2-n1284",0,"Morenita agraciada,\nQuítate el manto;\nNó por ser agraciada\nTe tapes tanto.",0,0,-1,0,"",6,4,"ao",30,0,-1,0,46,46,"1284","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1285",0,"¡Mira si he corrido tierras,\nQue he 'stado en Benamejí!\nNo he visto cara más beya\nQue la d' este serafin.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,47,47,"1285","",0,"","","",15,0,0,[],""],["rm_t2-n1286",0,"Ni en toda la Andalucía\nNi en el reino de Aragon\nHe visto cara más linda\nQue la que está en el balcon.",0,0,-1,0,"",0,4,"ao",31,0,-1,0,47,47,"1286","",0,"","","",1,0,0,[],""],["rm_t2-n1287",0,"En todo lo que el sol baña\nY las estrellas cobijan\nNo he visto cara más bella\nNi imágen más peregrina.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,47,47,"1287","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1289",0,"¿Qué pinceles dibujaron,\nChiquiya, tu hermoso rostro\nY tan fino lo sacaron,\nQue á mí no me gusta otro?",0,0,-1,0,"",0,4,"oo",-1,0,-1,0,47,47,"1289","",0,"","","",2,0,0,[],""],["rm_t2-n1290",0,"Un pajarito de oro\nPuesto en una verde rama,\nMira si estará bonito;\nPero tu cara le gana.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,47,47,"1290","",0,"","","",3,0,0,[],""],["rm_t2-n1291",0,"¿Con qué te lavas la cara,\nOjitos de palomita?\n¿Con qué te lavas la cara,\nQue la tienes tan bonita?",0,0,-1,0,"",1,4,"ia",50,0,-1,0,47,47,"1291","",0,"lafuente_madrid, palau_cantares","","",9,0,0,[],""],["rm_t2-n1292",0,"-¿Con qué te lavas la cara,\nQue tan colorada estás?\n-Me lavo con agua clara\nY Dios pone lo demás.",0,0,-1,0,"",1,4,"a",51,0,-1,0,48,48,"1292","",0,"lafuente_madrid, palau_cantares","","",9,0,0,[],""],["rm_t2-n1294",0,"La nieve por tu cara\nPasó diciendo:\n—En donde no hago falta\nNo me detengo.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,48,48,"1294","",0,"","","",3,0,0,[],""],["rm_t2-n1295",0,"Copos· de nieve en tu cara\nParece que van cayendo:\nMientras más te voy mirando,\nMejor me vas pareciendo.",0,0,-1,0,"",0,4,"eo",52,0,-1,0,48,48,"1295","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1296",0,"Entre la nieve y la grana\nSe formaron tus mejillas;\nY como la nieve es blanca,\nLo encarnado es lo que brilla.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,48,48,"1296","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1297",0,"A la luz del cigarro\nTe ví la cara;\nNo he visto clavellina\nMás encarnada.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,48,48,"1297","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1298",0,"¿Para qué vas por lumbre\nLa calle arriba,\nSi sale de tu cara\nLa llama viva?",0,0,-1,0,"",6,4,"ia",53,0,-1,0,48,48,"1298","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1299",0,"Tienes en tu cara, niña,\nLo mejor de cielo y tierra:\nDos rosas en tus mejillas\nY en tus ojos dos estrellas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,49,49,"1299","",0,"","","",1,0,0,[],""],["rm_t2-n1300",0,"Ese garbo y hermosura\nY ese rostro tan salado\nLo comparo, vida mia,\nCon las rositas de Mayo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,49,49,"1300","",0,"","","",2,0,0,[],""],["rm_t2-n1301",0,"Es tu cara una rosa\nQue colorea\nY tu cintura el tallo\nQue la menea.",0,0,-1,0,"",6,4,"ea",54,0,-1,0,49,49,"1301","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1302",0,"Muchas veces estoy viendo\nLas rosas de tu ventana\nY muchas veces me engaño,\nPensando que son tu cara.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,49,49,"1302","",0,"","","",3,0,0,[],""],["rm_t2-n1303",0,"Los colores que asoman\nA tus carrillos\nParecen amapolas\nDe un verde trigo.",0,0,-1,0,"",6,4,"io",-1,0,-1,0,49,49,"1303","",0,"","","",1,0,0,[],""],["rm_t2-n1304",0,"Las rosas y los claveles\nSe dieron una batalla\nY los claveles ganaron,\nPorque reinan en tu cara.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,49,49,"1304","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1305",0,"En Enero no hay claveles,\nPorque los marchita el hielo;\nEn tu cara los hay siempre,\nPorque lo permite el cielo.",0,0,-1,0,"",0,4,"eo",10,0,-1,0,49,49,"1305","",0,"carrizo_salta, palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t2-n1306",0,"Sale el sol por la mañana\nY relumbran las paderes;\nAsí relumbra tu cara\nEntre todas las mujeres.",0,0,-1,0,"",0,4,"ee",55,0,-1,0,50,50,"1306","",0,"","","",5,0,0,[],""],["rm_t2-n1307",0,"Cuando sales al campo,\nMorena mia,\nHasta los ruiseñores\nSe despepitan.\nPorque tu cara\nEl sol se les figura\nDe la mañana.",0,0,-1,0,"",4,7,"aa",-1,0,-1,0,50,50,"1307","",0,"","","",1,0,0,[],""],["rm_t2-n1308",0,"Es tu cara para mí\nUn rayo de sol dorado\nY tus ojos dos luceros\nQue siempre me han alumbrado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,50,50,"1308","",0,"","","",1,0,0,[],""],["rm_t2-n1309",0,"Es tu pecho madeja\nDe seda blanca;\nEs la luna tu frente\nY el sol tu cara.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,50,50,"1309","",0,"","","",1,0,0,[],""],["rm_t2-n1310",0,"De tu cara sale el sol,\nDe tu garganta la luna;\nMorenas he visto yo;\nPero como tú, ninguna.",0,0,-1,0,"",0,4,"ua",56,0,-1,0,50,50,"1310","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1311",0,"Es tu cara lo mismo\nQue luna blanca\nY tus ojos, luceros\nQue la acompañan.",0,0,-1,0,"",6,4,"aa",-1,0,-1,0,50,50,"1311","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1312",0,"Es tu cara la luna,\nLa redondita,\nY tus ojos luceros\nQue la visitan.",0,0,-1,0,"",6,4,"ia",-1,0,-1,0,50,51,"1312","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1313",0,"En la raya de tu pelo\nSe paró la luna clara\nY no la dejó salir\nLa hermosura de tu cara.",0,0,-1,0,"",0,4,"aa",57,0,-1,0,51,51,"1313","",0,"","","",1,0,0,[],""],["rm_t2-n1314",0,"Tengo yo comparado,\nNiña, tu rostro\nCon la luna de Enero\nY el sol de Agosto.",0,0,-1,0,"",6,4,"oo",-1,0,-1,0,51,51,"1314","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1316",0,"Estrellas y luceros\nVan con la luna;\nPero como tu cara\nNo va ninguna.",0,0,-1,0,"",6,4,"ua",56,0,-1,0,51,51,"1316","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1317",0,"Pecosita de viruelas,\nA tí no te dé cuidado;\nQue con estrellas el cielo\nEstá muy bien adornado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,51,51,"1317","",0,"","","",1,0,0,[],""],["rm_t2-n1318",0,"Hoyos tienes en la cara\nDe viruelas que te han dado;\nEn cada hoyo una rosa\nY un clavel disciplinado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,51,51,"1318","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1319",0,"Tienes en tu cara pecas,\nY en tus carrillos colores,\nY en tu cuello gargantillas,\nY en tu corazon amores.",0,0,-1,0,"",0,4,"oe",5,0,-1,0,52,52,"1319","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1320",0,"Tienes la cara pecosa\nComo huevo de perdiz;\nEn cada peca una rosa\nY enmedio una flor de lís.",0,0,-1,0,"",1,4,"i",58,0,-1,0,52,52,"1320","",0,"","","",3,0,0,[],""],["rm_t2-n1321",0,"Tienes en tu cara pecas,\nY en tu garganta lunares,\nY en tu pecho más virtudes\nQue rosas en los rosales.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,52,52,"1321","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1322",0,"Si dispone de bender,\nSeñora, usté, ese lunar,\nPor dineros que otro dé,\nYo estoy en primer lugar.",0,0,-1,0,"",0,4,"a",21,0,-1,0,52,52,"1322","",0,"","","",1,0,0,[],""],["rm_t2-n1323",0,"Ese lunar que tienes\nJunto á la boca,\nNo se lo des á nádie,\nQue á mí me toca.\nJunto á la nariz,\nNo se lo des á nádie,\nQue me toca á mí.",0,0,-1,0,"",4,7,"i",-1,0,-1,0,52,52,"1323","",0,"","","",3,0,0,[],""],["rm_t2-n1324",0,"Cuando Dios te hizo, quiso\nPonerte un lunar por firma;\nCogió el sello de su gracia\nY lo plantó en tu mejilla.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,52,52,"1324","",0,"","","",1,0,0,[],""],["rm_t2-n1325",0,"¡Vale más con la gracia\nQue dan los cielos\nEn una cara blanca\nUn lunar negro...!\nQue los cielos dan\nEn una cara blanca\nUn negro lunar...!",0,0,-1,0,"",4,7,"a",-1,0,-1,0,52,53,"1325","",0,"","","",1,0,0,[],""],["rm_t2-n1326",0,"Tiene la prenda que adoro\nUn lunar en un carrillo,\nQue me tiene prisionero,\nSin haberme echado grillos.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,53,53,"1326","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n1327",0,"Cuatro lunares tienes,\nNiña, en tu rostro:\nTienes Abril y Mayo,\nJulio y Agosto.\nDe tal manera,\nTienes los cuatro meses\nDe primavera.",0,0,-1,0,"",4,7,"ea",44,0,-1,0,53,53,"1327","",0,"","","",2,0,0,[],""],["rm_t2-n1329",0,"Mientras tú tengas lunares\nEn esa cara morena,\nNo t' han de fartar amores\nNi en tu tierra ni en l' ajena.",0,0,-1,0,"",0,4,"ea",59,0,-1,0,53,53,"1329","",0,"","","",1,0,0,[],""],["rm_t2-n1330",0,"Mira cómo corre el agua\nPor debajo del peñon;\nAsí corre por tu cara\nToda la gracia de Dios.",0,0,-1,0,"",5,4,"o",-1,0,-1,0,53,53,"1330","",0,"carrizo_salta","","",8,0,0,[],""],["rm_t2-n1332",0,"Mira cómo corre el agua\nPor la pendiente del rio;\nAsí corre por tu cara\nLa gracia de Dios, bien mio.",0,0,-1,0,"",0,4,"o",3,0,-1,0,54,54,"1332","",0,"","","",8,0,0,[],""],["rm_t2-n1333",0,"Mira cómo corre el agua\nPor debajo del laurel;\nAsí corre la hermosura\nPor tu carita, Isabel.",0,0,-1,0,"",0,4,"e",32,0,-1,0,54,54,"1333","",0,"","","",8,0,0,[],""],["rm_t2-n1334",0,"Tienes cuello de marfil,\nCinturita de campana;\nCatorce leguas de aquí\nTiene tu hermosura fama.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,54,54,"1334","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1335",0,"Con lo blanco de tu cuello,\nSalada, me cautivaste;\nÁtame con un cabello,\nHasta que venga el rescate.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,54,54,"1335","",0,"","","",3,0,0,[],""],["rm_t2-n1336",0,"Dicen que la golondrina\nTiene la pechuga blanca,\nY mi serranilla tiene\nLa pechuga y la garganta.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,54,54,"1336","",0,"palau_cantares, lafuente_madrid, suspiros_amor","","",12,0,0,[],""],["rm_t2-n1337",0,"De marfil torneado\nTienes el pecho\nY con venas azules\nDe trecho en trecho.",0,0,-1,0,"",6,4,"eo",60,0,-1,0,54,54,"1337","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1338",0,"Rubita, sol de los soles,\nTu cara es una custodia\nY tu pecho la escalera\nPara subir á la gloria.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,54,55,"1338","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1339",0,"Es tu pecho una alcobita\nHecha con tanto primor,\nQue parece que allí habitan\nLos resplandores del sol.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,55,55,"1339","",0,"","","",3,0,0,[],""],["rm_t2-n1340",0,"Bendito el pintor de gracia\nY aquel Divino Maestro\nQue pintó la rosa blanca\nPor el color de tu pecho.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,55,55,"1340","",0,"","","",1,0,0,[],""],["rm_t2-n1341",0,"-¿Qué tienes en ese pecho,\nQue tanto trasmina y huele?\n-Albahaca de las Indias,\nMata de romero verde.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,55,55,"1341","",0,"","","",1,0,0,[],""],["rm_t2-n1342",0,"-¿Qué tienes en el pecho,\nQue tanto huele?\n-Azahar de las Indias,\nRomero verde.\n-Que huele tanto?\n-Azahar de las Indias,\nRomero blanco.",0,0,-1,0,"",4,7,"ao",-1,0,-1,0,55,55,"1342","",0,"","","",1,0,0,[],""],["rm_t2-n1344",0,"-A tomillo y romero\nMe hueles, niña.\n--Como vengo del campo,\nNo es maravilla.",0,0,-1,0,"",6,4,"ia",-1,0,-1,0,55,55,"1344","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1345",0,"A la flor de la violeta\nMezclada con el jazmin,\nA eso me huele tu cuerpo,\nCuando estoy cérca de tí.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,56,56,"1345","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1346",0,"¡Ay, qué olor ha venido\nA rosas finas!\n¡Si será mi moreno,\nQue está en la esquina!\nA violetas!\n¡Si será mi moreno,\nQue está en la puerta!",0,0,-1,0,"",4,7,"ea",-1,0,-1,0,56,56,"1346","",0,"","","",1,0,0,[],""],["rm_t2-n1347",0,"Dicen que espinan tus manos;\nPara mí son amorosas;\nMás espinan los rosales\nY se le cortan las rosas.",0,0,-1,0,"",0,4,"oa",61,0,-1,0,56,56,"1347","",0,"","","",2,0,0,[],""],["rm_t2-n1348",0,"Son tus manos palmas reales;\nTus dedos, diez azucenas;\nTus labios, finos corales;\nTus dientes, menudas perlas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,56,56,"1348","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1349",0,"Son tus dedos diez claveles\nY tus manos dos macetas;\nY las niñas de tus ojos\nTienen á las 'mias muertas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,56,56,"1349","",0,"","","",1,0,0,[],""],["rm_t2-n1350",0,"Ya no se llaman dedos\nLos de tus manos:\nQue se llaman claveles\nDe cinco en ramo.",0,0,-1,0,"",6,4,"ao",-1,0,-1,0,56,56,"1350","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t2-n1351",0,"Tienes tus blancas manos\nLlenas de anillos;\nPara mí son prisiones,\nCadena y grillos.\nDe anillos llenas;\nPara mí son prisiones,\nGrillo y cadenas.",0,0,-1,0,"",4,7,"ea",62,0,-1,0,57,57,"1351","",0,"","","",1,0,0,[],""],["rm_t2-n1352",0,"¡Ay, qué dedos para anillos!\n¡Qué pecho para un diamante!\n¡Qué orejas para zarcillos!\n¡Qué niña para un amante!",0,0,-1,0,"",1,4,"ae",47,0,-1,0,57,57,"1352","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1353",0,"¡Qué manitas para guantes!\nPara sortijas, ¡qué dedos!\n¡Qué cuello para un collar!\n¡Qué boquita para un beso!",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,57,57,"1353","",0,"","","",3,0,0,[],""],["rm_t2-n1354",0,"Niña que vas á lavar\nAl rio de Manzanares,\n¿Para qué quieres jabon,\nSi tus dedos son cristales?",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,57,57,"1354","",0,"","","",2,0,0,[],""],["rm_t2-n1355",0,"¡Bendito Dios, morenita,\nQué buena moza te has hecho!\nDelgadita de cintura\nY abultadita de pecho.",0,0,-1,0,"",0,4,"eo",60,0,-1,0,57,57,"1355","",0,"","","",1,0,0,[],""],["rm_t2-n1356",0,"EreR delgada de talle\nComo junco de ribera;\nDe todas las de tu calle\nTú te llevas la bandera.",0,0,-1,0,"",1,4,"ea",44,0,-1,0,57,57,"1356","",0,"","","",1,0,0,[],""],["rm_t2-n1357",0,"Delgadita de cintura\nComo junco marinero,\nNi eres alta ni eres baja,\nQue eres como yo te quiero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,57,58,"1357","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1358",0,"Delgadita de cintura\nComo junco de la mar,\nLo que es tocante á hermosura\nBien te puedes alabar.",0,0,-1,0,"",1,4,"a",21,0,-1,0,58,58,"1358","",0,"","","",6,0,0,[],""],["rm_t2-n1359",0,"Tienes las mismas facciones\nQue tiene la Magdalena:\nDelgadita de cintura\nY de carita morena.",0,0,-1,0,"",0,4,"ea",59,0,-1,0,58,58,"1359","",0,"","","",1,0,0,[],""],["rm_t2-n1360",0,"Tu cintura y un junco\nFormaron pleito\nY, mira, aquí te traigo\nEl pedimento.\nY de la sala\nSalió que tu cintura\nEs más delgada.",0,0,-1,0,"",4,7,"aa",-1,0,-1,0,58,58,"1360","",0,"","","",1,0,0,[],""],["rm_t2-n1361",0,"Tienes una cinturita\nTan delgada y tan donosa,\nQue la vengo á comparar\nAl capullo de la rosa.",0,0,-1,0,"",0,4,"oa",63,0,-1,0,58,58,"1361","",0,"lafuente_madrid","","",14,0,0,[],""],["rm_t2-n1362",0,"Tienes una cinturita,\nQue anoche te la medí;\nCon bara y media de guita\nCatorce bueltas te dí\n[Y me sobró una poquita].",0,0,-1,0,"",7,5,"ia",50,0,-1,0,58,58,"1362","",0,"","","",14,0,0,[],""],["rm_t2-n1363",0,"Tienes una cinturita\nTan delgada, que parece\nEl clavel en la maceta,\nQue con el aire se mece.",0,0,-1,0,"",0,4,"ee",64,0,-1,0,58,59,"1363","",0,"","","",14,0,0,[],""],["rm_t2-n1364",0,"Tienes una sintura\nQue se parese\nAr clabé 'n la maseta\nCuando se mese.",0,0,-1,0,"",6,4,"ee",65,0,-1,0,59,59,"1364","",0,"","","",1,0,0,[],""],["rm_t2-n1365",0,"Tienes una cinturita\nDe justillo madrileño;\n¡Viva quien tiene sandunga\nY la gasta con salero!",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,59,59,"1365","",0,"lafuente_madrid","","",14,0,0,[],""],["rm_t2-n1366",0,"Tienes una cinturita\nQue parece contrabando;\nYo, como contrabandista,\nPor ella vengo penando.",0,0,-1,0,"",0,4,"ao",33,0,-1,0,59,59,"1366","",0,"palau_cantares, lafuente_madrid","","",14,0,0,[],""],["rm_t2-n1367",0,"Tienes una cinturita\nQue parece un jubileo;\nYo jago mir imposibles\nPor arcanzarla y no pueo.",0,0,-1,0,"",0,4,"eo",66,0,-1,0,59,59,"1367","",0,"","","",14,0,0,[],""],["rm_t2-n1368",0,"De la Veracruz salieron\nTres navíos para España,\nCargados de cinturones\nPara tu talle, serrana.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,59,59,"1368","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1369",0,"En el valle no hay un talle\nComo el que tiene mi prima,\nNi cuerpo más sandunguero,\nNi cara más peregrina.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,59,59,"1369","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1370",0,"Ese cuerpo y ese talle\nY esa delgada cintura\nSon buenos para un enfermo:\nYa tengo yo calentura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,59,60,"1370","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1371",0,"Eres alta y delgada,\nCenceña y lisa;\nEres como la vara\nDe la justicia.",0,0,-1,0,"",6,4,"ia",-1,0,-1,0,60,60,"1371","",0,"carrizo_salta, palau_cantares","","",4,0,0,[],""],["rm_t2-n1372",0,"Parece tu cuerpo un junco,\nTu cabeza una naranja,\nTu pecho un jardin de flores,\nDonde descansa mi alma.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,60,60,"1372","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1373",0,"Tienes cuerpo de marquesa;\nSin duda que lo serás.\n¡Quién pudiera ser marqués,\nPara poderte igualar!",0,0,-1,0,"",0,4,"a",-1,0,-1,0,60,60,"1373","",0,"","","",1,0,0,[],""],["rm_t2-n1374",0,"La sirenita del mar\nEncanta á los marineros\nY á mí me tiene encantado\nEse saleroso cuerpo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,60,60,"1374","",0,"","","",2,0,0,[],""],["rm_t2-n1375",0,"Son tus piernas dos columnas\nDe las del altar mayor\nY tus ojos dos luceros\nQue estoy adorando yo.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,60,60,"1375","",0,"","","",1,0,0,[],""],["rm_t2-n1376",0,"Dos columnas de alabastro\nHechas con arquitectura\nEstán manteniendo el garbo\nDe tu pulida cintura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,60,60,"1376","",0,"","","",2,0,0,[],""],["rm_t2-n1377",0,"Los zapatos que mantienen\nEl garbo de esa deidá,\nMerecian ser de oro\nEn lugar de cordoban.",0,0,-1,0,"",5,4,"oa",-1,0,-1,0,60,61,"1377","",0,"","","",2,0,0,[],""],["rm_t2-n1378",0,"-Esos zapatos blancos\nQue llevas, Juana,\n¿Cómo demonio pisas,\nQue no los manchas?-\nY ella responde:\n-Es porque voy pisando\nLos corazones.",0,0,-1,0,"",4,7,"oe",-1,0,-1,0,61,61,"1378","",0,"","","",2,0,0,[],""],["rm_t2-n1379",0,"Desde que te ví, morena,\nAl andar tu lindo pié,\nMe relamo yo la boca,\nComo si tuviera miel.",0,0,-1,0,"",0,4,"e",-1,0,-1,0,61,61,"1379","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n1380",0,"Con ese pié pulidito\nY ese modito de andar\nTiene usté más hombres muertos\nQue arenas tiene la mar.",0,0,-1,0,"",0,4,"a",21,0,-1,0,61,61,"1380","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1381",0,"Cada vez que te veo\nQuisiera echarte\nAl cuello una cadena\nY aprisionarte.\n¡Bendita seas,\nCon ese meneito\nQue te meneas!",0,0,-1,0,"",4,7,"ea",67,0,-1,0,61,61,"1381","",0,"","","",6,0,0,[],""],["rm_t2-n1383",0,"Al pasar por tu puerta\nVí pelearse\nDos piedras, pretendiendo\nQue las pisases.\nYo dije entónces:\n-Si hacen esto las piedras,\n¿Qué harán los hombres?",0,0,-1,0,"",4,7,"oe",-1,0,-1,0,62,62,"1383","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1384",0,"Parece mi morena\nCuando va á misa\nPajarita de nieve\nQue anda y no pisa.",0,0,-1,0,"",6,4,"ia",68,0,-1,0,62,62,"1384","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1385",0,"Mariquita, María\nLa de mi barrio,\nHasta el agua bendita\nToma con garbo.",0,0,-1,0,"",6,4,"ao",-1,0,-1,0,62,62,"1385","",0,"palau_cantares, fernan_caballero","","",12,0,0,[],""],["rm_t2-n1386",0,"Voy á misa y me pongo\nPor los canceles,\nPara ber con er garbo\nQue á misa biene.\nMe meto dentro,\nPara ber con er garbo\nQu' entra 'n er templo.",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,62,62,"1386","",0,"","","",1,0,0,[],""],["rm_t2-n1387",0,"Tienes el rostro serio\nY el mirar grave\nY en el andar sereno\nPareces ave.",0,0,-1,0,"",6,4,"ae",69,0,-1,0,62,62,"1387","",0,"","","",2,0,0,[],""],["rm_t2-n1388",0,"La luna por el cielo\nVa serenita;\nAsí va por la calle\nMi morenita.",0,0,-1,0,"",6,4,"ia",50,0,-1,0,62,62,"1388","",0,"carrizo_salta, palau_cantares","","",3,0,0,[],""],["rm_t2-n1390",0,"Me dice mi moreno\nQue cuando ando\nLa sar de los saleros\nBoy derramando.",0,0,-1,0,"",6,4,"ao",33,0,-1,0,63,63,"1390","",0,"","","",1,0,0,[],""],["rm_t2-n1391",0,"Cuatro cosas me encantan\nDe mi morena:\nLa cintura, la cara,\nEl pié y la pierna.\nY además tiene\nOtras cosas que callo,\nPorque conviene.",0,0,-1,0,"",4,7,"ee",70,0,-1,0,63,63,"1391","",0,"","","",1,0,0,[],""],["rm_t2-n1392",0,"¿Quién habla mal de lo chico?\nPor lo chico muero yo:\nTengo yo un amor chiquito\nDentro de mi corazon.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,63,63,"1392","",0,"","","",1,0,0,[],""],["rm_t2-n1393",0,"La pimienta es chica y pica\nY sasona los guisaos;\nTú eres chiquita y me tienes\nEr cuerpo esasonao.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,63,63,"1393","",0,"","","",5,0,0,[],""],["rm_t2-n1394",0,"Por lo chiquita y reonda\nTe pusieron «la sandía.»\n¡Qué lindo parmito tienes!\n¡Quién pudiera decir: «Mia!»",0,0,-1,0,"",0,4,"ia",0,0,-1,0,63,63,"1394","",0,"","","",1,0,0,[],""],["rm_t2-n1395",0,"¡Válgame Dios, qué dicha\nSi yo la logro:\nUna mujer que apénas\nMe llega al hombro!",0,0,-1,0,"",6,4,"oo",-1,0,-1,0,63,63,"1395","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1396",0,"Vale más onza que libra\nEn algunas ocasiones:\nVale más un cuerpo chico\nQue nó algunos corpachones.",0,0,-1,0,"",0,4,"oe",34,0,-1,0,64,64,"1396","",0,"","","",1,0,0,[],""],["rm_t2-n1397",0,"La mujer chiquitita\nEs un regalo:\nMás vale poco y bueno\nQue mucho y malo.",0,0,-1,0,"",6,4,"ao",71,0,-1,0,64,64,"1397","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t2-n1398",0,"Mientras la flor más chiquita,\nMás fino tiene el olor;\nPor eso estoy yo queriendo\nA una chiquitita flor.",0,0,-1,0,"",0,4,"o",72,0,-1,0,64,64,"1398","",0,"","","",1,0,0,[],""],["rm_t2-n1399",0,"Aunque seas chiquitita,\nA tí no te dé cuidado:\nPorque el árbol chiquitito\nCría fruto regalado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,64,64,"1399","",0,"","","",3,0,0,[],""],["rm_t2-n1400",0,"Eres como la avellana,\nChiquita y llena de carne,\nChiquita y apañadita,\nComo te quiere tu amante.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,64,64,"1400","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1402",0,"Eres chiquita y bonita,\nEres como yo te quiero;\nPareces campanillita\nHecha á mano de un platero.",0,0,-1,0,"",1,4,"eo",38,0,-1,0,64,64,"1402","",0,"palau_cantares, lafuente_madrid","","",12,0,0,[],""],["rm_t2-n1403",0,"Todas las cosas chiquitas\nLas miro con aficion,\nPorque chiquita es la prenda\nQue adora mi corazon.",0,0,-1,0,"",0,4,"o",31,0,-1,0,65,65,"1403","",0,"","","",1,0,0,[],""],["rm_t2-n1404",0,"Unos dicen que lo blanco,\nOtros dicen que lo negro,\nOtros que lo colorado:\nYo digo que lo moreno.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,65,65,"1404","",0,"","","",3,0,0,[],""],["rm_t2-n1405",0,"De los tres col ores, madre\nLo moreno es lo bonito:\nMorenos fueron los clavos\nQue le pusieron á Cristo.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,65,65,"1405","",0,"","","",1,0,0,[],""],["rm_t2-n1406",0,"Morena tiene que ser\nLa tierra para ser buena\nY la mujer para el hombre\nTambien ha de ser morena.",0,0,-1,0,"",0,4,"ea",59,0,-1,0,65,65,"1406","",0,"carrizo_salta, palau_cantares, murciano_antiguo","","",9,0,0,[],""],["rm_t2-n1407",0,"Morena tiene que ser\nLa tierra para claveles\nY la mujer para el hombre,\nMorenita y con desdenes.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,65,65,"1407","",0,"lafuente_madrid, fernan_caballero","","",9,0,0,[],""],["rm_t2-n1408",0,"Mi amante es alto y moreno;\nPor eso lo quiero tanto:\nPorque la tierra morena\nSe enseñorea en el campo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,65,65,"1408","",0,"","","",1,0,0,[],""],["rm_t2-n1409",0,"Morena es la cebada,\nMoreno el trigo,\nMoreno es el espejo\nEn que me miro.",0,0,-1,0,"",6,4,"io",-1,0,-1,0,65,66,"1409","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1410",0,"Un moreno agraciado\nTiene la birtú\nQue á todas las enfermas\nLe da la salú.",0,0,-1,0,"",0,4,"u",73,0,-1,0,66,66,"1410","",0,"","","",1,0,0,[],""],["rm_t2-n1411",0,"Bien puede una morena\nCon sus suspiros\nResucitar á un muerto,\nDar muerte á un vivo.",0,0,-1,0,"",6,4,"io",-1,0,-1,0,66,66,"1411","",0,"","","",1,0,0,[],""],["rm_t2-n1412",0,"Puede una mujer morena\nCon una mirada que eche\nPoner á un hombre en la cama\nY en un hospital diez meses.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,66,66,"1412","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1413",0,"Morena, morena eres;\n¡Mal haya tu morenura!\nQue me tienes en la cama,\nSin frío ni calentura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,66,66,"1413","",0,"","","",3,0,0,[],""],["rm_t2-n1414",0,"Er que muere sin probá\nEr queré d' una morena\nSe ba d' este mundo al otro\nSin sabé lo qu' es canela.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,66,66,"1414","",0,"","","",1,0,0,[],""],["rm_t2-n1416",0,"Lo moreno lo hizo Dios,\nLo blanco lo hizo un platero:\nTome lo blanco el que quiera;\nYo por lo moreno muero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,66,66,"1416","",0,"palau_cantares","","",6,0,0,[],""],["rm_t2-n1417",0,"No desprecies lo moreno,\nQue vale más que la plata;\nPorque morenita-es\nLa prenda que á mí me mata.",0,0,-1,0,"",0,4,"aa",74,0,-1,0,67,67,"1417","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1418",0,"Vale más lo moreno\nDe mi morena\nQue toda la blancura\nDe la azucena.",0,0,-1,0,"",6,4,"ea",59,0,-1,0,67,67,"1418","",0,"carrizo_salta, palau_cantares, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1419",0,"Quien dijere que Vénus\nHa sido blanca\nNo ha estudiado las artes\nPor Salamanca.",0,0,-1,0,"",6,4,"aa",75,0,-1,0,67,67,"1419","",0,"","","",1,0,0,[],""],["rm_t2-n1420",0,"Lo blanco y lo moreno\nPléito formaron\nY ganó lo moreno,\nPor lo agraciado.\nFormaron pleito;\nLo moreno ha ganado,\nPor lo discreto.",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,67,67,"1420","",0,"","","",1,0,0,[],""],["rm_t2-n1421",0,"Lo blanco ya no se usa,\nLo moreno está de moda:\nPor eso estoy yo queriendo\nA una morenita ahora.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,67,67,"1421","",0,"","","",1,0,0,[],""],["rm_t2-n1422",0,"Con la sal que una morena\nDerrama de mala gana\nTiene para mantenerse\nUna rubia una semana.",0,0,-1,0,"",0,4,"aa",4,0,-1,0,67,67,"1422","",0,"","","",1,0,0,[],""],["rm_t2-n1423",0,"Con la sar que derrama\nUna morena\nSe mantiene una blanca\nSemana y media.\n¡Biba 'r salero!\n¡Biba la sar grasiosa\nDe lo moreno!",0,0,-1,0,"",4,7,"eo",-1,0,-1,0,67,68,"1423","",0,"","","",1,0,0,[],""],["rm_t2-n1424",0,"Una morena con sal\nPuede salir á la calle;\nY una blanca, siendo sosa,\nDonde no la vea nádie.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,68,68,"1424","",0,"","","",1,0,0,[],""],["rm_t2-n1425",0,"Una morena está en venta;\nDicen los apreciadores\nQue la sal de una morena\nNo es pagada con doblones.",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,68,68,"1425","",0,"","","",1,0,0,[],""],["rm_t2-n1426",0,"¡Viva todo lo moreno,\nLo moreno amorenado!\nLo moreno de tu cara\nEs lo que á mí me ha gustado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,68,68,"1426","",0,"","","",5,0,0,[],""],["rm_t2-n1427",0,"¡Biban los aires morenos!\n¡Biban los morenos aires!\n¡Biban los e mi morena\nQue son como los e naide!",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,68,68,"1427","",0,"","","",1,0,0,[],""],["rm_t2-n1428",0,"¡Viva todo lo moreno,\nLo moreno de buen aire!\nLo digo porque me toca\nDe lo morenito parte.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,68,68,"1428","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n1429",0,"¡Ay, que se me lleva el aire!\n¡Ay, que el aire se me lleva!\n¡Ay, que se me lleva el aire,\nEl aire de mi morena!",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,68,68,"1429","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1430",0,"¡Biba Osuna, qu' es mi tierra,\nSan Arcario mi patron!\n¡Biba la gente morena,\nQue morenita soy yo!.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,69,69,"1430","",0,"","","",1,0,0,[],""],["rm_t2-n1431",0,"Moreno pintan á Cristo,\nMorena á la Madalena,\nMoreno eser bien qu' adoro;\n¡Biba la gente morena!",0,0,-1,0,"",0,4,"ea",59,0,-1,0,69,69,"1431","",0,"","","",10,0,0,[],""],["rm_t2-n1432",0,"Morenito es mi amante,\nMorenita yo;\nColor de chocolate\nTenemos los dos.\n¡Biba quien tiene\nColor de chocolate,\nQue nunca pierde!",0,0,-1,0,"",4,7,"ee",-1,0,-1,0,69,69,"1432","",0,"","","",1,0,0,[],""],["rm_t2-n1433",0,"Si fuera presidente\nDe la rear sala,\nA ningun morenito\nLo sentensiara.\nAntes le diera\nLibertar arsoluta\nMientras bibiera.",0,0,-1,0,"",4,7,"ea",44,0,-1,0,69,69,"1433","",0,"","","",1,0,0,[],""],["rm_t2-n1434",0,"Es mi amante morenito\nComo er triguito tremés,\nQuejace 'r pan escurito,\nGustosito de comer.",0,0,-1,0,"",0,4,"e",-1,0,-1,0,69,69,"1434","",0,"","","",2,0,0,[],""],["rm_t2-n1435",0,"No soy bonita que espante,\nNi fea que cause horror;\nTengo un moreno agraciado\nY así me quiere mi amor.",0,0,-1,0,"",0,4,"o",72,0,-1,0,69,69,"1435","",0,"","","",1,0,0,[],""],["rm_t2-n1436",0,"No soy bonita que asombre,\nNi fea que cause miedo;\nSoy morenita y con gracia\nY así me quiere mi dueño.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,70,70,"1436","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1437",0,"Morenita y con gracia\nMe llama el conde;\nHasta su señoría\nSabe mi nombre.",0,0,-1,0,"",6,4,"oe",-1,0,-1,0,70,70,"1437","",0,"","","",1,0,0,[],""],["rm_t2-n1438",0,"Morenita resalada\nMe llaman los marineros;\nOtra vez que me lo digan\nMe voy al muelle con ellos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,70,70,"1438","",0,"","","",3,0,0,[],""],["rm_t2-n1439",0,"No te quiero por bonita,\nQue bonita no lo eres;\nTe quiero por morenita\nY por la gracia que tienes.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,70,70,"1439","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t2-n1440",0,"Por tres cosas te he querido:\nPor morena, por alegre\nY por los ojos dormidos,\nQue aprisionados me tienen.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,70,70,"1440","",0,"","","",3,0,0,[],""],["rm_t2-n1441",0,"Yo nací en Sierra Morena\nY á una morenita quiero;\nLo moreno es de mi gusto;\nYo por lo moreno muero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,70,70,"1441","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1442",0,"Mira si he corrido tierras,\nQue he estado en la gran Turquía;\nEn ninguna parte ví\nMorena como la mia.",0,0,-1,0,"",0,4,"ia",0,0,-1,0,70,70,"1442","",0,"palau_cantares, lafuente_madrid","","",15,0,0,[],""],["rm_t2-n1443",0,"Todo lo moreno es feo;\nLo moreno tuyo nó,\nPorque lo moreno tuyo\nTiene la gracia de Dios.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,71,71,"1443","",0,"","","",1,0,0,[],""],["rm_t2-n1444",0,"El que quisiere á una rubia\nHa de dormir al sereno;\nQue no se gana una rubia\nCon las manos en el seno.",0,0,-1,0,"",1,4,"eo",76,0,-1,0,71,71,"1444","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1445",0,"Eres rubia como er l' oro\nY blanca como er papé,\nColorâ como la grana\nY hermosa como er clabé.",0,0,-1,0,"",0,4,"e",77,0,-1,0,71,71,"1445","",0,"","","",1,0,0,[],""],["rm_t2-n1446",0,"Eres como el trigo rubio\nEscogido grano á grano;\nEres la rubia más linda\nQue mis ojos han mirado.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,71,71,"1446","",0,"","","",3,0,0,[],""],["rm_t2-n1447",0,"Palidita es mi dama\nY así la quiero;\nQue una estrella amarilla\nBrilla en el cielo.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,71,71,"1447","",0,"","","",1,0,0,[],""],["rm_t2-n1448",0,"Ni la estreyita de Bénus\nTenía mejon coló\nQue tenía mi morena\nLa noche que me dejó.",0,0,-1,0,"",0,4,"o",2,0,-1,0,71,71,"1448","",0,"","","",1,0,0,[],""],["rm_t2-n1449",0,"Ayer pasé por tu caye\nY te bide 'n er barcon:\nSiempre que se mira 'r sielo\nSe be la grasia de Dios.",0,0,-1,0,"",5,4,"o",-1,0,-1,0,71,71,"1449","",0,"","","",1,0,0,[],""],["rm_t2-n1450",0,"En la soleá der campo\nMe puse á considerá\nLos pesos duros que bale\nUna morena con sá.",0,0,-1,0,"",0,4,"a",9,0,-1,0,72,72,"1450","",0,"","","",2,0,0,[],""],["rm_t2-n1451",0,"Vale más la sal que tienes\nEn esa cara morena\nQue la torre de Serranos\nY el martinete de Heredia.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,72,72,"1451","",0,"","","",3,0,0,[],""],["rm_t2-n1452",0,"Bale más de mi Consuelo\nLa grasia, sandunga y garbo\nQue los tesoros que tiene\nEr rey d' España enserraos.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,72,72,"1452","",0,"","","",1,0,0,[],""],["rm_t2-n1453",0,"Mi moreno es tan moreno,\nQue me parese un gitano;\nPero tiene mi moreno\nLa sar molía en sus labios.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,72,72,"1453","",0,"","","",2,0,0,[],""],["rm_t2-n1454",0,"No importa, niña, que seas\nMorenita de color,\nSi tienes en esa cara\nToda la gracia de Dios.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,72,72,"1454","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1455",0,"La Macarena y todo\nLo traigo andado;\nSalero como er tuyo\nNo l' he 'ncontrado.",0,0,-1,0,"",6,4,"ao",14,0,-1,0,72,72,"1455","",0,"","","",1,0,0,[],""],["rm_t2-n1456",0,"Eres paloma en lo blanco\nY tórtola en el arrullo;\nEn el mundo no se encuentra\nUn salero como el tuyo.",0,0,-1,0,"",0,4,"uo",78,0,-1,0,72,72,"1456","",0,"","","",2,0,0,[],""],["rm_t2-n1457",0,"En el mar de la gracia\nTe bautizaron\nY salieron los peces,\nLa sal te echaron.",0,0,-1,0,"",6,4,"ao",41,0,-1,0,73,73,"1457","",0,"","","",1,0,0,[],""],["rm_t2-n1458",0,"Salero, por tu salero\nA la mar me arrojaria;\nPero por otro s'alero\nEn mi casa me estaria.",0,0,-1,0,"",1,4,"aa",79,0,-1,0,73,73,"1458","",0,"","","",4,0,0,[],""],["rm_t2-n1459",0,"Debajo de tu ventana\nMe puse á contar dinero\nY así que llegué á los quince\nMe acordé de tí, salero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,73,73,"1459","",0,"","","",29,0,0,[],""],["rm_t2-n1460",0,"En las montañas de Jaca\nMe acordé de tí, salero,\nPorque me faltó la sal,\nCuando estaba de ranchero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,73,73,"1460","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1461",0,"Para guisar esta liebre\nSólo me farta la sá;\nUsté que la tiene e sobra,\n¿Me la quier' usté 'mprestá?",0,0,-1,0,"",0,4,"a",9,0,-1,0,73,73,"1461","",0,"","","",3,0,0,[],""],["rm_t2-n1462",0,"En Málaga sen té plaza\nY en Sebiya m' acorde\nDer garbo de tu persona\nY ar punto me deserté.",0,0,-1,0,"",0,4,"e",77,0,-1,0,73,73,"1462","",0,"","","",1,0,0,[],""],["rm_t2-n1463",0,"La campana de la Bela\nNo tiene tanta balumba\nComo tienes tú, morena,\nEn ese cuerpo sandunga.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,73,73,"1463","",0,"","","",1,0,0,[],""],["rm_t2-n1464",0,"Sangre bibita, bibita,\nSangre bibita la quiero,\nPorque la sangre bibita\nTiene sandunga y salero.",0,0,-1,0,"",1,4,"eo",38,0,-1,0,74,74,"1464","",0,"","","",1,0,0,[],""],["rm_t2-n1465",0,"Antiguamente eran durses\nLas agüiyas de la má,\nPero escupió mi morena\nY se gorbieron salâs.",0,0,-1,0,"",0,4,"a",-1,0,-1,0,74,74,"1465","",0,"","","",1,0,0,[],""],["rm_t2-n1466",0,"En pasando mi morena\nTrompiesa tô 'r que ba etrás;\nQue ba yenando la caye\nE terronsiyos e sa.",0,0,-1,0,"",0,4,"a",-1,0,-1,0,74,74,"1466","",0,"","","",2,0,0,[],""],["rm_t2-n1467",0,"Ven acá, almacen de gracia,\nCuerpo de sal y salero;\nQue eres más agraciadita\nQue la flor que echa el romero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,74,74,"1467","",0,"","","",1,0,0,[],""],["rm_t2-n1469",0,"Cuando en ancas de mi potro\nYo te yebe á Gibartá\nDirán los mozos ar berte:\n—¡Baya una jembra salâ!",0,0,-1,0,"",0,4,"a",-1,0,-1,0,74,74,"1469","",0,"","","",2,0,0,[],""],["rm_t2-n1470",0,"Biban las mosas juncales\nQue se pasean con rumbo;\nLas que quieren á sus guapos\nCon er salero der mundo.",0,0,-1,0,"",0,4,"uo",-1,0,-1,0,74,74,"1470","",0,"","","",1,0,0,[],""],["rm_t2-n1472",0,"Biba er lujo y quien lo trujo\nY tamien quien lo mantiene;\nY tamien digo que biba\nEr salero y quien lo tiene.",0,0,-1,0,"",0,4,"ee",70,0,-1,0,75,75,"1472","",0,"","","",1,0,0,[],""],["rm_t2-n1473",0,"Eres perla de las perlas,\nLusero de los luseros;\nEres parma de las parmas,\nSalero de los saleros.",0,0,-1,0,"",0,4,"eo",22,0,-1,0,75,75,"1473","",0,"","","",3,0,0,[],""],["rm_t2-n1474",0,"Eres er sé de los séres,\nEres sirena der má,\nEres morenita y tienes\nSalero, sandunga y sá.",0,0,-1,0,"",0,4,"a",9,0,-1,0,75,75,"1474","",0,"","","",1,0,0,[],""],["rm_t2-n1475",0,"Eres buena moza y tienes\nSalero real y corona;\nEnvidia le tengo al hombre\nQue se lleve tu persona.",0,0,-1,0,"",0,4,"oa",7,0,-1,0,75,75,"1475","",0,"","","",2,0,0,[],""],["rm_t2-n1476",0,"Envidia tengo á la tierra\nY tambien á los gusanos,\nQue se tienen de comer\nEse cuerpo tan gitano.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,75,75,"1476","",0,"","","",6,0,0,[],""],["rm_t2-n1477",0,"Envidia tengo á la tierra\nY tambien á los bichitos,\nQue se tienen de comer\nEse cuerpo tan bonito.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,75,75,"1477","",0,"","","",6,0,0,[],""],["rm_t2-n1478",0,"Hermosa clabeyinita,\nCriada ar pié de la sierra,\n¡Qué lástima de carita\nQue se la coma la tierra!",0,0,-1,0,"",1,4,"ea",80,0,-1,0,76,76,"1478","",0,"","","",1,0,0,[],""],["rm_t2-n1479",0,"¡Qué lástima de carita\nQue se la coma la tierra,\nPudiéndosela comer\nUn soldado de la reina!",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,76,76,"1479","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n1480",0,"¡Qué lástima de carita,\nQue fuese para un paisano,\nPudiéndosela llebar\nUn sordado beterano!",0,0,-1,0,"",0,4,"ao",81,0,-1,0,76,76,"1480","",0,"","","",4,0,0,[],""],["rm_t2-n1482",0,"¡Cuidado, que eres hermosa\nY te vas contoneando!\nDe todas las buenas mozas\nLa palma te vas llevando.",0,0,-1,0,"",0,4,"ao",33,0,-1,0,76,76,"1482","",0,"","","",1,0,0,[],""],["rm_t2-n1483",0,"De todas las de tu calle\nEres tú la más hermosa.\n¿Cómo no pones bandera,\nCapitana generosa?",0,0,-1,0,"",0,4,"oa",63,0,-1,0,76,76,"1483","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1484",0,"Toda la calle Mayor\nHe venido preguntan do\nDónde habita la hermosura\nY aquí me han encaminado.",0,0,-1,0,"",3,4,"ao",-1,0,-1,0,76,76,"1484","",0,"","","",3,0,0,[],""],["rm_t2-n1485",0,"En la calle donde vives\nTodos te llaman «la diosa»\nY yo, por engrandecerte,\nTe llamo «perla preciosa.»",0,0,-1,0,"",0,4,"oa",63,0,-1,0,77,77,"1485","",0,"","","",3,0,0,[],""],["rm_t2-n1486",0,"En la calle donde vives\nNo hay hermosa sino es tú;\nPor donde quiera que vayas\nEl Señor te dé salú.",0,0,-1,0,"",0,4,"u",73,0,-1,0,77,77,"1486","",0,"","","",3,0,0,[],""],["rm_t2-n1487",0,"La hermosura de los cielos\nCuando Dios la repartió\nNo andarias tú muy léjos,\nCuando tanta te tocó.",0,0,-1,0,"",0,4,"o",2,0,-1,0,77,77,"1487","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1488",0,"Eres hermosa en extremo;\nTu color no tiene igual:\nTu cuerpo se gallardea\nComo barquillo en el mar.",0,0,-1,0,"",0,4,"a",-1,0,-1,0,77,77,"1488","",0,"","","",7,0,0,[],""],["rm_t2-n1489",0,"Eres hermosa en extremo;\nContigo no iguala nádie;\nQue lo que tú te mereces\nNo se lo merece nádie.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,77,77,"1489","",0,"","","",7,0,0,[],""],["rm_t2-n1490",0,"La flor del' aderfa es\nLa más hermosa del rio\nY tú eres la más hermosa\nQue de mujer ha nasío.",0,0,-1,0,"",0,4,"io",3,0,-1,0,77,77,"1490","",0,"","","",1,0,0,[],""],["rm_t2-n1492",0,"En tu puerta me senté\nA comerme una lechuga\nY en el cogollo encontré\nUn ramo de tu hermosura.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,78,78,"1492","",0,"","","",2,0,0,[],""],["rm_t2-n1495",0,"Me puse á dibujarte;\nPero puso Dios\nEn tí más hermosura\nQue en mí discrecion.",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,78,78,"1495","",0,"","","",1,0,0,[],""],["rm_t2-n1496",0,"En tu abanico, niña,\nQuiero pintarte,\nPara que tu retrato\nTe dé algun aire.\nPorque no hay pintor\nQue dibuje con aire\nTu gracia y primor.",0,0,-1,0,"",4,7,"o",72,0,-1,0,78,78,"1496","",0,"","","",2,0,0,[],""],["rm_t2-n1497",0,"Debajo de tu ventana,\nPor pintarte á tí, pinté\nUna rosa catalana\nY un clavel aragonés.",0,0,-1,0,"",0,4,"e",-1,0,-1,0,78,78,"1497","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",29,0,0,[],""],["rm_t2-n1498",0,"Gitana caracolera,\nRamiyete d' hermosura,\nSupuesto qu' eres gitana,\nDime la güenabentura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,78,78,"1498","",0,"","","",1,0,0,[],""],["rm_t2-n1499",0,"Cada bes que boy á Cáis\nY paso por la estrechura\nY beo la niebe blanca,\nM' acuerdo de tu hermosura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,79,79,"1499","",0,"","","",1,0,0,[],""],["rm_t2-n1500",0,"Cuando el poderoso Dios\nBajó del cielo á la tierra\nDejó aquí la semillita\nPara que tú florecieras.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,79,79,"1500","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1501",0,"El dia que tú nacistes\nNacieron todas las flores\nY en la pila del bautismo\nCantaron los ruiseñores.",0,0,-1,0,"",0,4,"oe",5,0,-1,0,79,79,"1501","",0,"","","",7,0,0,[],""],["rm_t2-n1502",0,"Rosa e primabera\nE las más trempanas;\nComo recoges—en er mes d' Enero\nLas primeras aguas.",0,0,-1,0,"",3,4,"aa",-1,0,-1,0,79,79,"1502","",0,"","","",1,0,0,[],""],["rm_t2-n1503",0,"¿En qué jardin te has criado,\nBella maceta de flores,\nQue no tienes quince años\nY cautivas á los hombres?",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,79,79,"1503","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1504",0,"Rosa, clavellina y dalia\nMe has parecido al mirarte\nY tambien me has parecido\nPerla engastada en diamante.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,79,79,"1504","",0,"","","",3,0,0,[],""],["rm_t2-n1505",0,"No he visto rosa más bella,\nNi clavel más encarnado,\nNi mujer más á mi gusto\nQue ésta que tengo á mi lado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,79,79,"1505","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1506",0,"En el mar se crian peces\nY en la orilla caracoles\nY en el jardin de mi dama\nClavellinas á montones.",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,80,80,"1506","",0,"","","",1,0,0,[],""],["rm_t2-n1507",0,"¡Qué linda clavellinera\nQue estoy viendo desde aquí!\nComo soy forasterito,\nNo hay un clavel para mí.",0,0,-1,0,"",0,4,"i",23,0,-1,0,80,80,"1507","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1508",0,"Dame una clavellina\nDe tus claveles;\nDámela tan hermosa\nComo tú eres.",0,0,-1,0,"",6,4,"ee",-1,0,-1,0,80,80,"1508","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1509",0,"Dame una rosa, Maria,\nY cógela con tu mano,\nQue me han dicho que tú tienes\nUn rosalito temprano.",0,0,-1,0,"",0,4,"ao",81,0,-1,0,80,80,"1509","",0,"","","",3,0,0,[],""],["rm_t2-n1510",0,"-Malagueñita pulida,\nDame de tu pecho un ramo.\n-¿Quién te ha dicho, picaron,\nQue malagueña me llamo?",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,80,80,"1510","",0,"","","",1,0,0,[],""],["rm_t2-n1511",0,"Clavellina colorada,\nNacida en el mes de Enero,\n¿Quién ha visto nacer flores\nEn el rigor del invierno?",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,80,80,"1511","",0,"","","",3,0,0,[],""],["rm_t2-n1512",0,"Su color te dió la rosa,\nEl cielo su azul turquí,\nTe dió su talle la palma\nY su blancura el jazmín.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,80,80,"1512","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1513",0,"El naranjo de tu patio\nCuando te acercas á él\nSe desprende de sus flores\nY te las echa á los piés.",0,0,-1,0,"",0,4,"e",-1,0,-1,0,81,81,"1513","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t2-n1514",0,"Al verte las flores lloran\nCuando entran en tu jardín,\nPorque las flores quisieran\nTodas parecerse á tí.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,81,81,"1514","",0,"","","",3,0,0,[],""],["rm_t2-n1515",0,"Tu hermosura avasalla\nTodas las flores;\nNi Vénus te aventaja\nCon sus primores.",0,0,-1,0,"",6,4,"oe",5,0,-1,0,81,81,"1515","",0,"","","",1,0,0,[],""],["rm_t2-n1516",0,"No vale lo que tu vales\nLa blanca flor del almendro,\nNi las mañanas de Mayo,\nNi el prado de rosas lleno.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,81,81,"1516","",0,"","","",1,0,0,[],""],["rm_t2-n1517",0,"Cuando te pones, morena,\nEn la puerta de la calle,\nPareces naranjo verde\nQue lo bambolea el aire.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,81,81,"1517","",0,"","","",2,0,0,[],""],["rm_t2-n1518",0,"Sordado d' á cabayo,\nPonte la gorra,\nQue pareses sin eya\nClaber sin hojas.\nYa te l' has puesto,\nY pareses con eya\nClaber compuesto.",0,0,-1,0,"",4,7,"eo",83,0,-1,0,81,81,"1518","",0,"","","",1,0,0,[],""],["rm_t2-n1519",0,"-Soldadito, soldadito,\n¡Qué bien te sienta la gorra!\n¿De qué regimiento eres?\n-De la Infanta soy, señora.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,81,82,"1519","",0,"","","",4,0,0,[],""],["rm_t2-n1520",0,"Si la casaca del rey\nNo tuviera las resultas,\nVale más un soldadito\nQue toda la España junta.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,82,82,"1520","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1521",0,"A tu puerta llaman puerta\nY á tu ventana ventana;\nA tu madre jardinera\nY á tí rosita encarnada.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,82,82,"1521","",0,"","","",1,0,0,[],""],["rm_t2-n1522",0,"Esta calle es un jardin,\nLas muchachas son las rosas\nY yo, como jardinero,\nEscogí la más hermosa.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,82,82,"1522","",0,"","","",1,0,0,[],""],["rm_t2-n1523",0,"Tus colchones son jazmines\nY tus sábanas mosquetas,\nAzucena tu almohada\nY tú rosa que te acuestas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,82,82,"1523","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1528",0,"Siemprebiba te diré\nY lirio der campo nó:\nQue los lirios se marchitan\nY la siemprebiba nó.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,83,83,"1528","",0,"","","",1,0,0,[],""],["rm_t2-n1529",0,"Señores, mi novia es\nLa palma de la hermosura,\nEl más hermoso clavel\nY la más bella pintura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,83,83,"1529","",0,"","","",1,0,0,[],""],["rm_t2-n1530",0,"Eres la flor de las flores,\nEres rosa entre las rosas,\nEres la que estimo y amo,\nEres tú la más hermosa.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,83,83,"1530","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1531",0,"Eres la flor de las flores,\nMaravilla de las Indias,\nCara de quitapesares,\nRamillete de celindas.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,83,83,"1531","",0,"","","",4,0,0,[],""],["rm_t2-n1532",0,"Eres el clavel de Abril\nY la rosita de Mayo,\nLa hermosa luna de Enero,\nQue me tienes hechizado.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,83,83,"1532","",0,"","","",1,0,0,[],""],["rm_t2-n1533",0,"Eres una clavellina\nRodeada de claveles;\nComo eres tan peregrina,\nHechizadito me tienes\n[Hermosa prenda divina].",0,0,-1,0,"",7,5,"ia",11,0,-1,0,83,83,"1533","",0,"","","",3,0,0,[],""],["rm_t2-n1534",0,"Eres rosa de pasion,\nNiña, porque me apasiona\nLa hermosura de tu cara\nY el garbo de tu persona.",0,0,-1,0,"",0,4,"oa",7,0,-1,0,84,84,"1534","",0,"","","",1,0,0,[],""],["rm_t2-n1535",0,"Eres mosqueta olorosa,\nEres el blanco jazmin,\nEres la rosa fragante\nEn la floresta de Abril.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,84,84,"1535","",0,"","","",4,0,0,[],""],["rm_t2-n1536",0,"Eres más apetecible\nQue el fresco de la mañana\nY más hermosa y más bella\nQue rosa de Abril temprana.",0,0,-1,0,"",0,4,"aa",4,0,-1,0,84,84,"1536","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1537",0,"Eres el mejor clavel\nDe las orillas del Darro,\nQue se abrió con el rocío\nEn las mañanas de Mayo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,84,84,"1537","",0,"","","",3,0,0,[],""],["rm_t2-n1538",0,"Eres la palma gallarda\nY hermosísimo laurel:\nEres azucena blanca\nY bellísimo clavel.",0,0,-1,0,"",0,4,"e",32,0,-1,0,84,84,"1538","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1539",0,"Eres más apañadita\nQue la nieve en el barranco,\nQue el clavel en la maceta\nY la azucena en el campo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,84,84,"1539","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1540",0,"Eres la parma gayarda\nQu' ar sielo t' has de subí\nA 'bitá con las estreyas,\nBeyísimo serafin.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,84,84,"1540","",0,"","","",1,0,0,[],""],["rm_t2-n1541",0,"Eres más rubia que el sol\nY más blanca que la nieve;\nEres rosa alejandrina\nQue todo el año florece.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,85,85,"1541","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1542",0,"Eres parma, roble y pino,\nOlibo, armendro y perá;\nNacites para 'siprés\nY t' has buerto naranjá.",0,0,-1,0,"",0,4,"a",9,0,-1,0,85,85,"1542","",0,"","","",1,0,0,[],""],["rm_t2-n1543",0,"Eres como la verbena\nQue en el campo verde nace;\nEres como el caramelo\nQue en la boca se deshace.",0,0,-1,0,"",0,4,"ae",84,0,-1,0,85,85,"1543","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1544",0,"Eres el oro molido\nY la plata por sellar,\nEres el carro triunfante\nY sirenita del mar.",0,0,-1,0,"",0,4,"a",21,0,-1,0,85,85,"1544","",0,"","","",1,0,0,[],""],["rm_t2-n1545",0,"Eres la plata labrada,\nEres del oro la espuma,\nEres la rosa encarnada,\nNo tienes falta ninguna.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,85,85,"1545","",0,"","","",2,0,0,[],""],["rm_t2-n1546",0,"Eres un grano d' esensia\nY m' arbiertes lo que inoro:\nQue contra más guardadito,\nMás reluciente 'stá el oro.",0,0,-1,0,"",0,4,"oo",85,0,-1,0,85,85,"1546","",0,"","","",1,0,0,[],""],["rm_t2-n1547",0,"Eres un confite blanco\nMetido en una redoma;\nSólo te faltan las alas\nPara ser blanca paloma.",0,0,-1,0,"",0,4,"oa",86,0,-1,0,85,85,"1547","",0,"","","",1,0,0,[],""],["rm_t2-n1548",0,"María, para paloma\nSólo te faltan las alas\nY á mí para gavilan\nLas patitas coloradas.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,86,86,"1548","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1549",0,"Ojos de blanca paloma,\nSerafin idolatrado,\nBenditas tus perfecciones,\nQue me tienes hechizado.",0,0,-1,0,"",0,4,"ao",14,0,-1,0,86,86,"1549","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1550",0,"Eres como la berbenia (?)\nQue ba á la mar y se baña,\nClaba 'r piquito en l' arena,\nLa bebe y no enturbia 'l agua.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,86,86,"1550","",0,"","","",1,0,0,[],""],["rm_t2-n1551",0,"Eres águila rëal\nQue en el pico llevas flores,\nEn las alas azucenas\nY en el corazon amores.",0,0,-1,0,"",0,4,"oe",5,0,-1,0,86,86,"1551","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n1552",0,"Eres águila rëal\nQue en el pinar se paró;\nEres más linda que el alba\nCuando va saliendo el sol.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,86,86,"1552","",0,"","","",5,0,0,[],""],["rm_t2-n1553",0,"Eres estrellita de oro,\nEres perla dibujada,\nEres el mejor canario\nQue canta de madrugada.",0,0,-1,0,"",0,4,"aa",49,0,-1,0,86,86,"1553","",0,"","","",1,0,0,[],""],["rm_t2-n1554",0,"En la ciudá d' Alicante,\nNiña, m' acordé de tí;\nQue relumbraba una estreya\nY se parecia á tí.",0,0,-1,0,"",0,4,"i",-1,0,-1,0,86,86,"1554","",0,"","","",1,0,0,[],""],["rm_t2-n1555",0,"Las estrellas fuí contando\nY á la del Norte llegué;\nComo la ví tan hermosa,\nContigo la comparé\n[Clavellina primorosa].",0,0,-1,0,"",7,5,"oa",63,0,-1,0,87,87,"1555","",0,"","","",1,0,0,[],""],["rm_t2-n1556",0,"Eres la estrella del Norte\nQue á los marineros guia,\nDesde que se hace de noche\nHasta que se hace de dia.",0,0,-1,0,"",0,4,"a",0,0,-1,0,87,87,"1556","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1557",0,"Eres la blanca azucena\nY el encarnado clavel,\nEres la estrella del Norte,\nLucero al amanecer.",0,0,-1,0,"",0,4,"e",-1,0,-1,0,87,87,"1557","",0,"","","",1,0,0,[],""],["rm_t2-n1558",0,"Tengo yo una cuñada\nQue se parece\nAl lucero del alba\nCuando amanece.",0,0,-1,0,"",6,4,"ee",64,0,-1,0,87,87,"1558","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1559",0,"Las estrellitas del cielo\nEstán quejosas de Dios,\nPorque no las ha criado\nTan hermosas como vos.",0,0,-1,0,"",0,4,"o",87,0,-1,0,87,87,"1559","",0,"palau_cantares","","",25,0,0,[],""],["rm_t2-n1560",0,"Una estrella se ha perdido\nY en el cielo no parece;\nEn tu cuarto se ha metido\nY en tu cara resplandece.",0,0,-1,0,"",1,4,"ee",64,0,-1,0,87,87,"1560","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1561",0,"De dos hermanas que son\nNo hay diferencia ninguna;\nEs la una como el sol\nY la otra como la luna.",0,0,-1,0,"",0,4,"ua",56,0,-1,0,87,87,"1561","",0,"","","",3,0,0,[],""],["rm_t2-n1562",0,"¿Sabes á quién te pareces?\n¿Sabes á quién le das aire?\nAl sol cuando resplandece\nY á la luna cuando sale.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,88,88,"1562","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1563",0,"Eres tú la que le quitas\nTodos los rayos al sol,\nA la nieve la blancura\nY á la luna el resplandor.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,88,88,"1563","",0,"","","",4,0,0,[],""],["rm_t2-n1564",0,"Más hermosa eres que el sol,\nQue la nieve en el desierto,\nQue la rosa en el rosal\nY la azucena en el huerto.",0,0,-1,0,"",0,4,"eo",88,0,-1,0,88,88,"1564","",0,"","","",4,0,0,[],""],["rm_t2-n1565",0,"Más hermosa eres que el sol\nCuando sus rayos dispara;\nMás hermosa que la luna\nCuando va serena y clara.",0,0,-1,0,"",0,4,"aa",57,0,-1,0,88,88,"1565","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t2-n1566",0,"Eres hermana del sol,\nPrima hermana de la luna,\nSobrina del alabastro,\nDel alba prima segunda.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,88,88,"1566","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n1567",0,"Ere' 'r só que yo idolatro\nY la luna 'n quien benero;\nEres cadena d' amó\nQue me tienes prisionero.",0,0,-1,0,"",0,4,"eo",38,0,-1,0,88,88,"1567","",0,"","","",1,0,0,[],""],["rm_t2-n1568",0,"Con la L eres la luna,\nCon la S eres er só\nY con la P eres Perico,\nPrenda de mi corason.",0,0,-1,0,"",5,4,"ao",-1,0,-1,0,88,88,"1568","",0,"","","",1,0,0,[],""],["rm_t2-n1569",0,"Las cortinas de tu cuarto\nSon de terciopelo azul\nY entre cortina y cortina\nUn sol me pareces tú.",0,0,-1,0,"",3,4,"u",-1,0,-1,0,89,89,"1569","",0,"","","",1,0,0,[],""],["rm_t2-n1570",0,"Yo creí que era la luna\nLa que estaba en el balcon;\nYo creí que era la luna\nY era la luna y el sol.",0,0,-1,0,"",3,4,"o",-1,0,-1,0,89,89,"1570","",0,"leonesas_diez","","",4,0,0,[],""],["rm_t2-n1571",0,"Yo creí que era la luna\nLa que estaba en el balcon\nY salió la capitana\nDe Navarra y Aragon.",0,0,-1,0,"",0,4,"ao",31,0,-1,0,89,89,"1571","",0,"","","",4,0,0,[],""],["rm_t2-n1572",0,"Yo nací blanco y diré\nLa causa de ser moreno:\nEstoy adorando á un sol\nY con sus rayos me quemo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,89,89,"1572","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n1573",0,"La luna se ha parado\nEn su carrera,\nArmirada de berte\nTan hechicera.",0,0,-1,0,"",6,4,"ea",44,0,-1,0,89,89,"1573","",0,"","","",2,0,0,[],""],["rm_t2-n1574",0,"La luz del amanecer\nAl verte se quedó tibia\nY atrás se quiso volver,\nPorque le has causado envidia.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,89,89,"1574","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1575",0,"Astros, cielo, sor y luna\nSe oscurecen, por no ber\nEn mi casa aquer retrato\nQue yo tengo por mujer.",0,0,-1,0,"",0,4,"e",20,0,-1,0,89,89,"1575","",0,"","","",1,0,0,[],""],["rm_t2-n1576",0,"Sale el sol por la mañana\nY oscurece las estrellas\nY tú oscureces al sol\nCuando sales á tu puerta.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,90,90,"1576","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1577",0,"La luna clara salió\nY, viendo que le ganabas,\nTras un nublo se metió,\nCorrida y avergonzada.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,90,90,"1577","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1578",0,"El sol se quedó eclipsado,\nEnternecido de amores;\nCuando el sol se ha enamorado,\nNiña, ¿qué serán los hombres?",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,90,90,"1578","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n1579",0,"El dia que tú nacistes,\n¡Qué triste estaria el sol,\nAl ver que otro sol salia\nCon mucho más resplandor!",0,0,-1,0,"",0,4,"o",-1,0,-1,0,90,90,"1579","",0,"carrizo_salta","","",7,0,0,[],""],["rm_t2-n1580",0,"Si digo luna te ofendo;\nSi digo sol te maltrato;\nY si te digo lucero\nMe parece que te mato.",0,0,-1,0,"",0,4,"ao",19,0,-1,0,90,90,"1580","",0,"","","",1,0,0,[],""],["rm_t2-n1581",0,"No te diré sol ni luna,\nPero te diré diamante;\nQue la luna crece y mengua\nY en tí no cabe menguante.",0,0,-1,0,"",0,4,"ae",47,0,-1,0,90,90,"1581","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n1582",0,"Si la luna no menguara,\nTe comparara con ella;\nPero te compararé\nCon el sol y las estrellas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,90,90,"1582","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t2-n1583",0,"Es tan grande el resplandor\nQue por tu ventana sale,\nQue creí que era la luna\nY eran las dos de la tarde.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,91,91,"1583","",0,"","","",2,0,0,[],""],["rm_t2-n1584",0,"Es tanta la claridad\nQue por tu ventana sale,\nQue dice la vecindad:\n-Ya está la luna en la calle.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,91,91,"1584","",0,"","","",3,0,0,[],""],["rm_t2-n1585",0,"Es tan grande el resplandor\nQue por tu ventana sale,\nQue es menester quitasol\nPara pasear tu calle.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,91,91,"1585","",0,"","","",2,0,0,[],""],["rm_t2-n1586",0,"Apénas entré en tu calle,\nCuando me dió el resplandor;\nLe dije á un amigo mio:\n-En esta calle está el sol.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,91,91,"1586","",0,"","","",2,0,0,[],""],["rm_t2-n1587",0,"En la ventana te ví,\nNiña, como el sol que sale;\nMe quité el sombrero y dije:\n-Morenilla, Dios te guarde.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,91,91,"1587","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1588",0,"En todas partes del mundo\nSale el sol por la mañana\nY á mí me sale de noche,\nCuando estoy en tu ventana.",0,0,-1,0,"",0,4,"aa",4,0,-1,0,91,91,"1588","",0,"","","",2,0,0,[],""],["rm_t2-n1589",0,"¿Cómo quieres que el sol salga,\nSi lo tienes en prisiones,\nHasta que tú te levantes\nY á la ventana te asomes?",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,91,91,"1589","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1590",0,"Al sol de los siete soles\nY á la luna de Aragon\nComparo yo tus colores\nCuando sales al balcon.",0,0,-1,0,"",0,4,"ao",31,0,-1,0,92,92,"1590","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1591",0,"Ni er só de cuarenta soles\nNi la luna de l' Habana\nSe igualan á tus colores\nCuando sales de la cama.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,92,92,"1591","",0,"","","",1,0,0,[],""],["rm_t2-n1592",0,"Ya sale el sol de los soles,\nYa sale la luna llena;\nYa veo los resplandores\nDe tu carita morena.",0,0,-1,0,"",0,4,"ea",59,0,-1,0,92,92,"1592","",0,"","","",1,0,0,[],""],["rm_t2-n1593",0,"El marco de tu ventana\nTodo está lleno de estrellas;\nY así que te asomas tú\nSale el sol y se van ellas.",0,0,-1,0,"",0,4,"ea",89,0,-1,0,92,92,"1593","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1594",0,"Abre, niña, esa bentana,\nAbre la mitá siquiera,\nY entrará la media luna\nDonde 'stá la luna entera.",0,0,-1,0,"",0,4,"ea",44,0,-1,0,92,92,"1594","",0,"","","",1,0,0,[],""],["rm_t2-n1595",0,"Enfrente del sol que sale\nTiene mi niña la cama;\nSale el sol y la despierta,\nSale la luna y la llama.",0,0,-1,0,"",0,4,"aa",90,0,-1,0,92,92,"1595","",0,"","","",2,0,0,[],""],["rm_t2-n1596",0,"Enfrente del sol que sale\nTiene mi niña el balcon;\nSale el sol, sale mi niña,\nSale mi niña y el sol.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,92,92,"1596","",0,"","","",2,0,0,[],""],["rm_t2-n1597",0,"Cuando mi niña se pone\nLa saya para ir á misa,\nSale el sol y se oscurece,\nSale la luna y se eclisa.",0,0,-1,0,"",0,4,"ia",68,0,-1,0,93,93,"1597","",0,"","","",3,0,0,[],""],["rm_t2-n1598",0,"La luna cuando se llena\nNo tiene tanto rigor\nComo tiene mi morena\nCuando va á misa mayor.",0,0,-1,0,"",1,4,"o",72,0,-1,0,93,93,"1598","",0,"","","",1,0,0,[],""],["rm_t2-n1599",0,"Cuando ba mi niña á misa\nLa ilesia se resplandese;\nHasta la yerba que pisa,\nSi está seca, reberdese.",0,0,-1,0,"",1,4,"ee",65,0,-1,0,93,93,"1599","",0,"","","",1,0,0,[],""],["rm_t2-n1600",0,"La iglesia se ilumina\nCuando tú entras\nY se llena de flores\nDonde te sientas.\nYa te salistes\nY se quedó la iglesia\nSolita y triste.",0,0,-1,0,"",4,7,"ie",-1,0,-1,0,93,93,"1600","",0,"","","",2,0,0,[],""],["rm_t2-n1601",0,"Con la luz te comparo;\n¡Mira qué dicha!\nSin la luz no se puede\nDecir la misa.",0,0,-1,0,"",6,4,"ia",-1,0,-1,0,93,93,"1601","",0,"","","",3,0,0,[],""],["rm_t2-n1602",0,"Con la luz te he comparado;\n¡Mira qué dicha has tenido!\nQue sin la luz no se puede\nCelebrar misa, bien mio.",0,0,-1,0,"",0,4,"io",-1,0,-1,0,93,93,"1602","",0,"","","",5,0,0,[],""],["rm_t2-n1603",0,"Con la luz te he comparado;\n¡Mira qué comparacion!\nQue sin la luz no se puede\nDecir la misa mayor.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,94,94,"1603","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1604",0,"Te comparo con la luna,\nCon el sol y los luceros\nY si no fuera pecado,\nCon la Reina de los cielos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,94,94,"1604","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1605",0,"Con la luna te comparo,\nCon los luceros y el sol\nY, si no fuera pecado,\nTe comparara con Dios.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,94,94,"1605","",0,"","","",2,0,0,[],""],["rm_t2-n1606",0,"Te quisiera comparar\n(Pero nó, que me condeno)\nCon la Vírgen del Pilar;\nEres un poquito ménos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,94,94,"1606","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1607",0,"Tan sólo en el mundo hay una\nCon quien poder compararte\nY la encontré, por fortuna,\nPintada en un estandarte.",0,0,-1,0,"",1,4,"ae",8,0,-1,0,94,94,"1607","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1609",0,"Tu cara morena,\nTus sacais negros,\nMe paresites—la Bínge der Baye,\nLa qu' está 'n San Termo.",0,0,-1,0,"",3,4,"eo",-1,0,-1,0,94,94,"1609","",0,"","","",1,0,0,[],""],["rm_t2-n1610",0,"A la Samaritana\nMe paresistes;\nTe pedí un jarro d' agua\nY me lo distes.",0,0,-1,0,"",6,4,"ie",91,0,-1,0,95,95,"1610","",0,"","","",3,0,0,[],""],["rm_t2-n1611",0,"Bendita sea tu casa\nY 'l arbañí que la jiso:\nQue por dentro 'stá la gloria\nY por fuera 'r paraiso.",0,0,-1,0,"",0,4,"io",92,0,-1,0,95,95,"1611","",0,"","","",3,0,0,[],""],["rm_t2-n1612",0,"En la puerta de tu casa\nHe de poner un letrero\nCon letras de oro que digan:\n—Por aquí se sube al cielo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,95,95,"1612","",0,"","","",13,0,0,[],""],["rm_t2-n1613",0,"El dia que tú nacistes\nCayó un pedazo de cielo;\nHasta que tú no te mueras\nNo se tapa el agujero.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,95,95,"1613","",0,"","","",7,0,0,[],""],["rm_t2-n1614",0,"Er dia que tú nasites\nLas campanas reoblaron,\nLas sepurturas s' abrieron,\nLos muertos resusitaron.",0,0,-1,0,"",0,4,"ao",41,0,-1,0,95,95,"1614","",0,"","","",1,0,0,[],""],["rm_t2-n1615",0,"En el cielo de tu casa\nTe ví, salada, ayer tarde;\nBien puedo llamarla cielo,\nPorque en ella vive un ángel.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,95,95,"1615","",0,"","","",3,0,0,[],""],["rm_t2-n1616",0,"La primer vez que te ví\nMe parecistes lucero\nY ahora me has parecido\nAngel bajado del cielo.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,95,95,"1616","",0,"","","",7,0,0,[],""],["rm_t2-n1617",0,"No llores, ángel humano,\nAunque veas que me muero,\nPorque si te ven llorar,\nPensarán que me condeno.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,96,96,"1617","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1618",0,"Que en el cielo hay ladrones\nNo dude nádie,\nPorque á mí me ha robado\nLa vida un ángel.",0,0,-1,0,"",6,4,"ae",-1,0,-1,0,96,96,"1618","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1619",0,"Eres hermosa y robas\nLos corazones;\n¿Dónde pondré yo el mio,\nQue no lo robes?",0,0,-1,0,"",6,4,"oe",-1,0,-1,0,96,96,"1619","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t2-n1620",0,"Hermosísima paloma,\nCara de cielo español,\nCon tu mirar retrechero\nMe robas el corazon.",0,0,-1,0,"",0,4,"o",-1,0,-1,0,96,96,"1620","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1621",0,"Con ese delantar blanco\nY esas naguas de indianiya\nEr corason m' has robado,\nPícara retrecheriya.",0,0,-1,0,"",0,4,"ia",93,0,-1,0,96,96,"1621","",0,"","","",1,0,0,[],""],["rm_t2-n1622",0,"Debias tú por ladrona\nEstar en la corrersion,\nPorque m' has robado á un tiempo\nArma, bida y corason.",0,0,-1,0,"",5,4,"ao",-1,0,-1,0,96,96,"1622","",0,"","","",1,0,0,[],""],["rm_t2-n1623",0,"Eres una ladrona,\nQue me has robado\nTodo el entendimiento\nQue Dios me ha dado.",0,0,-1,0,"",6,4,"ao",14,0,-1,0,96,96,"1623","",0,"","","",1,0,0,[],""],["rm_t2-n1624",0,"El alma me robastes\nEn el convento:\n¡Quién ha visto ladrones\nDentro del templo!",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,97,97,"1624","",0,"","","",1,0,0,[],""],["rm_t2-n1625",0,"Señor alcalde mayor,\nNo prenda usté á los ladrones,\nPorque tiene usté una hija\nQue roba los corazones.",0,0,-1,0,"",0,4,"oe",34,0,-1,0,97,97,"1625","",0,"lafuente_madrid, fernan_caballero, palau_cantares","","",8,0,0,[],""],["rm_t2-n1626",0,"Señor arcarde mayó,\nPréndam' usté esa morena,\nQue me tiene 'r corason\nPrisionero entre caenas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,97,97,"1626","",0,"","","",1,0,0,[],""],["rm_t2-n1627",0,"Mi amante viste á lo majo\nY en la cintura se pone\nUna fajita grosella\nQue roba los corazones.",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,97,97,"1627","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1628",0,"Eres alto y buen mozo;\nLuégo, te pones\nUna faja, que robas\nLos corazones.",0,0,-1,0,"",6,4,"oe",34,0,-1,0,97,97,"1628","",0,"","","",1,0,0,[],""],["rm_t2-n1629",0,"-De los tres qu' ayí bienen,\n¿Cuál es er tuyo?\n- Er que trae 'r sombrero\nMás á lo tuno.\n-¿Cuál es tu amante?\n-Er que trae 'r sombrero\nA lo tunante.",0,0,-1,0,"",4,7,"ae",47,0,-1,0,97,97,"1629","",0,"","","",1,0,0,[],""],["rm_t2-n1630",0,"No hay sombrero en la plaza\nMás cortesano\nQu' er de mi morenito\nY er de su hermano.",0,0,-1,0,"",6,4,"ao",81,0,-1,0,98,98,"1630","",0,"","","",1,0,0,[],""],["rm_t2-n1631",0,"Bale más la bizarría\nDer galan que m' enamora\nQue toita l' Andalusía\nY la bega de Carmona.",0,0,-1,0,"",0,4,"oa",-1,0,-1,0,98,98,"1631","",0,"","","",1,0,0,[],""],["rm_t2-n1632",0,"Anque 'ngarsaran en oro\nLa catreá de Sebiya\nY la jisieran dinero\nBalias tú más, chiquiya.",0,0,-1,0,"",0,4,"ia",93,0,-1,0,98,98,"1632","",0,"","","",1,0,0,[],""],["rm_t2-n1633",0,"Bale más la peineta\nDe mi serrana\nQue la recua de mulos\nDe Cantiyana.",0,0,-1,0,"",6,4,"aa",4,0,-1,0,98,98,"1633","",0,"","","",1,0,0,[],""],["rm_t2-n1634",0,"En la puerta de tu casa\nCatorce muertos bí un dia,\nPorque los mató la pena,\nEn ber que no los querias.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,98,98,"1634","",0,"","","",13,0,0,[],""],["rm_t2-n1635",0,"Paca, quien te puso Paca\nNo te supo poner nombre;\nQue te debió de haber puesto\nLa perdicion de los hombres.",0,0,-1,0,"",0,4,"oe",-1,0,-1,0,98,98,"1635","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n1636",0,"Cuando te pusieron Ana\nBorracho estaría el cura;\nQue te debió de poner\nRamillete de hermosura.",0,0,-1,0,"",0,4,"ua",17,0,-1,0,98,98,"1636","",0,"","","",3,0,0,[],""],["rm_t2-n1637",0,"Eres Ana de las Anas\nY por ser Ana te atreves\nA robar los corazones:\nEl mio preso lo tienes.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,99,99,"1637","",0,"","","",2,0,0,[],""],["rm_t2-n1638",0,"Entre los árboles todos\nSe enseñorea el laurel,\nEntre las mujeres Ana\nY entre flores el clavel.",0,0,-1,0,"",0,4,"e",32,0,-1,0,99,99,"1638","",0,"","","",4,0,0,[],""],["rm_t2-n1639",0,"María sé que te llamas\nY por apellido Luna;\nAlúmbrame con tus rayos,\nPorque está la noche oscura.",0,0,-1,0,"",0,4,"ua",-1,0,-1,0,99,99,"1639","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1640",0,"Hazme, María, una torta,\nAunque sea de centeno;\nPorque, siendo de tu mano,\nSe volverá trigo bueno.",0,0,-1,0,"",0,4,"eo",76,0,-1,0,99,99,"1640","",0,"","","",3,0,0,[],""],["rm_t2-n1641",0,"Todas las Marías tienen\nEn el pecho un relicario\nY en la punta de la lengua\nAzúcar, canela y clavo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,99,99,"1641","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n1643",0,"En er basar hay un baso,\nY en er baso una bebía,\nEn la bebía una rosa,\nY en la rosa una María.",0,0,-1,0,"",0,4,"ia",0,0,-1,0,99,99,"1643","",0,"","","",1,0,0,[],""],["rm_t2-n1644",0,"Es María una esmeralda\nQue mucho dinero vale:\nEl que tiene una María\nNo se quiere hablar con nádie.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,100,100,"1644","",0,"","","",1,0,0,[],""],["rm_t2-n1645",0,"A María no agrabiarla\nEn lo mínimo d' un pelo,\nPorque María se yama\nLa que gobierna los sielos.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,100,100,"1645","",0,"","","",1,0,0,[],""],["rm_t2-n1646",0,"De la raíz de la palma\nNacieron las Isabeles,\nDelgaditas de cintura\nY de corazon alegre.",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,100,100,"1646","",0,"","","",3,0,0,[],""],["rm_t2-n1647",0,"De los artos sielesitos\nCayeron nuebe asusenas:\nTres Antonias, tres Fransiscas\nY tres dibinas Manuelas.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,100,100,"1647","",0,"","","",1,0,0,[],""],["rm_t2-n1648",0,"De lo más arto der sielo\nHan caio nuebe rosas:\nTres Anas y tres Marías,\nTres Isabeles presiosas.",0,0,-1,0,"",0,4,"oa",61,0,-1,0,100,100,"1648","",0,"","","",2,0,0,[],""],["rm_t2-n1649",0,"Una rueda de Juanes\nY un Pepe enmedio\nY un Manolito al lado,\n¡Jesús, qué cielo!",0,0,-1,0,"",6,4,"eo",-1,0,-1,0,100,100,"1649","",0,"","","",1,0,0,[],""],["rm_t2-n1650",0,"Para todos los Juanes\nTengo una siya\nCon candela debajo,\nPórbora 'nsima.\nBuerbo la hoja:\nPor ensima clabeles\nY abajo rosas.",0,0,-1,0,"",4,7,"oa",-1,0,-1,0,100,101,"1650","",0,"","","",1,0,0,[],""],["rm_t2-n1651",0,"Dicen que todos los Juanes\nSe parecen á la muerte;\nTengo yo un Juan en el alma\nQue al sol le dice: ¡Detente!",0,0,-1,0,"",0,4,"ee",-1,0,-1,0,101,101,"1651","",0,"","","",1,0,0,[],""],["rm_t2-n1652",0,"Dicen que las Dolores\nTienen espinas:\nUna tengo en el alma\n' No me lastima.",0,0,-1,0,"",6,4,"ia",-1,0,-1,0,101,101,"1652","",0,"","","",2,0,0,[],""],["rm_t2-n1653",0,"Quisiera, querida diosa,\nMandarte labrar un templo,\nQue la gente te adorara\nSegun tu merecimiento.",0,0,-1,0,"",0,4,"eo",-1,0,-1,0,101,101,"1653","",0,"","","",1,0,0,[],""],["rm_t2-n1654",0,"Si yo tubiera dinero\nComo tengo boluntá,\nPor donde quiera que pasas\nTe tenía e repicá.",0,0,-1,0,"",0,4,"a",9,0,-1,0,101,101,"1654","",0,"","","",1,0,0,[],""],["rm_t2-n1655",0,"Tengo de hacer un castiyo\nDe pesetas colunarias\nY ensima colocaré\nA tí y á tus dos hermanas.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,101,101,"1655","",0,"","","",1,0,0,[],""],["rm_t2-n1656",0,"Haré una torre que yegue\nAr sielo con cuatro esquinas\nY en eya colocaré\nEr nombre de Catalina.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,101,102,"1656","",0,"","","",2,0,0,[],""],["rm_t2-n1657",0,"No sé cómo no florece\nLa escoba con que tú barres,\nSiendo tú tan bien nacida,\nHija de tan buenos padres.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,102,102,"1657","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1658",0,"No sé cómo no floresen\nLas tejas e tu tejao,\nEstando tú ebajo d' eyas,\nPrimaberita de Mayo.",0,0,-1,0,"",0,4,"ao",-1,0,-1,0,102,102,"1658","",0,"","","",1,0,0,[],""],["rm_t2-n1659",0,"Aunque vives en rincon,\nNo vives arrinconada:\nQue en los rincones se crian\nLas mejores ensaladas.",0,0,-1,0,"",0,4,"aa",-1,0,-1,0,102,102,"1659","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n1660",0,"Rubita, no tienes padre,\nPorque Dios te l' ha quitado;\nDios le dé salú á tu madre\nPara ponerte en estado.",0,0,-1,0,"",1,4,"ao",14,0,-1,0,102,102,"1660","",0,"","","",1,0,0,[],""],["rm_t2-n1661",0,"Hermosa como er grano\nDe la granada;\nNo te bean mis ojos\nMar empleada.\nPorque si te ben,\nMi pena será mucha,\nPulido clabé.",0,0,-1,0,"",4,7,"e",-1,0,-1,0,102,102,"1661","",0,"","","",1,0,0,[],""],["rm_t2-n1662",0,"Mozuelas mormuraoras\nQue todo lo mormurais,\nNo mormurar á esta rosa,\nMirar que la deshojais.",0,0,-1,0,"",5,4,"oa",-1,0,-1,0,102,102,"1662","",0,"","","",1,0,0,[],""],["rm_t2-n1663",0,"Gran castigo merecia\nEr que tiene mala lengua,\nQue l' está quitando er créito\nA la fió de la canela.",0,0,-1,0,"",0,4,"ea",-1,0,-1,0,102,103,"1663","",0,"","","",1,0,0,[],""],["rm_t2-n1664",0,"Todas las aves del mundo\nNacieron para volar\nY las manos de María\nPara coser y bordar.",0,0,-1,0,"",0,4,"a",21,0,-1,0,103,103,"1664","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1665",0,"Cantas con tanto arreglo,\nTanta dulzura,\nQue el alma le arrebatas\nAl que te escucha.\nYo estoy sin ella,\nPorque llegué á escucharte\nLa vez primera.",0,0,-1,0,"",4,7,"ea",-1,0,-1,0,103,103,"1665","",0,"","","",1,0,0,[],""],["rm_t2-n1666",0,"De los juncos sale el agua,\nDe los álamos el viento,\nY de tí, pulida dama,\nMemoria y entendimiento.",0,0,-1,0,"",0,4,"eo",94,0,-1,0,103,103,"1666","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t2-n1667",0,"Chiquiya, ¡balientemente\nTe dió Dios sabiduría!\nUna palabra que hablas\nBale por docientas mias.",0,0,-1,0,"",0,4,"ia",-1,0,-1,0,103,103,"1667","",0,"","","",2,0,0,[],""],["rm_t2-n1668",0,"Tienes tal atractivo\nCon tu modestia,\nQue todo el que te escucha\nPrendado queda.\nY así se advierte\nQue cuantos te conocen\nTodos te quieren.",0,0,-1,0,"",4,7,"ee",-1,0,-1,0,103,103,"1668","",0,"","","",2,0,0,[],""],["rm_t2-n1669",0,"Te tengo comparaita\nCon las piedras e la caye.\nQue las pisa toito 'r mundo\nY no se quejan á náide.",0,0,-1,0,"",0,4,"ae",-1,0,-1,0,104,104,"1669","",0,"","","",2,0,0,[],""],["rm_t2-n1670",0,"Aunque linda y modesta,\nPerdiste el pleito,\nQue los hombres no buscan\nMás que el dinero.\nMas no te enojes,\nPorque en virtudes tienes\nTu mejor dote.",0,0,-1,0,"",4,7,"oe",-1,0,-1,0,104,104,"1670","",0,"","","",1,0,0,[],""],["rm_t2-n1671",0,"Tengo un dolor no sé dónde,\nNacido de no sé qué;\nSanaré yo no sé cuando,\nSi me cura no sé quién.",0,0,-1,1,"",0,4,"e",-1,0,-1,0,134,134,"1671","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t2-n1672",0,"Acá dentro del pecho\nTengo un gusano,\nQue me roe, me roe,\nDe cuando en cuando.",0,0,-1,1,"",6,4,"ao",-1,0,-1,0,134,134,"1672","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1673",0,"Nada me aflige y tengo\nMelancolía;\nYo no sé de qué nace\nLa pena mia.\nSólo me alivio\nCada vez que me miras\nY yo te miro.",0,0,-1,1,"",4,7,"io",-1,0,-1,0,134,134,"1673","",0,"","","",2,0,0,[],""],["rm_t2-n1675",0,"Los enemigos del alma\nTodos dicen que son tres\nY yo digo que son cuatro,\nDesde que conozco á usté.",0,0,-1,1,"",0,4,"e",-1,0,-1,0,135,135,"1675","",0,"","","",8,0,0,[],""],["rm_t2-n1676",0,"Desde Madrid he venido,\nPisando espinas y abrojos,\nSólo por llegar á verte,\nClavellina de mis ojos.",0,0,-1,1,"",0,4,"oo",99,0,-1,0,135,135,"1676","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1677",0,"En Málaga me embarqué\nCon el agua á la rodiya,\nSólo por benirte á ber,\nSebiyanita pulida.",0,0,-1,1,"",0,4,"ia",-1,0,-1,0,135,135,"1677","",0,"","","",5,0,0,[],""],["rm_t2-n1678",0,"Sólo por conocerte\nVengo á buscarte,\nPues tu fama ya corre\nPor todas partes.\nPero la fama,\nPorque no te conoce\nTan mal te trata.",0,0,-1,1,"",4,7,"aa",-1,0,-1,0,135,135,"1678","",0,"","","",2,0,0,[],""],["rm_t2-n1680",0,"En la placita del Puente\nHay dos hijas de su madre;\nYo festejo á la pequeña;\nMi compañero á la grande.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,136,136,"1680","",0,"","","",2,0,0,[],""],["rm_t2-n1682",0,"Er triguito 'stá 'n la era\nY el aire se yeba 'r tamo;\nPor la más chica benimos,\nQue la mayó tiene amo.",0,0,-1,1,"",0,4,"ao",100,0,-1,0,136,136,"1682","",0,"","","",1,0,0,[],""],["rm_t2-n1683",0,"De las tres perdigonsitas\nQue duermen en un corchon,\nDe la más chiquirritita\nQuisiera se' 'r perdigon.",0,0,-1,1,"",5,4,"io",-1,0,-1,0,136,136,"1683","",0,"","","",1,0,0,[],""],["rm_t2-n1684",0,"Palomita amartelada\nDentro de tu palomar,\nPalomos de lejas tierras\nTe vienen á visitar.",0,0,-1,1,"",0,4,"a",21,0,-1,0,136,136,"1684","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n1685",0,"Por amores ha venido\nUn forastero al lugar;\nPor amores ha venido\nY amores se ha de llevar.",0,0,-1,1,"",1,4,"a",21,0,-1,0,136,136,"1685","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1687",0,"Como soy forasterito,\nA todo el mundo pregunto\nQuién es aquella morena\nQue está vestida de luto.",0,0,-1,1,"",0,4,"uo",-1,0,-1,0,137,137,"1687","",0,"","","",3,0,0,[],""],["rm_t2-n1689",0,"Donde hay gusto no hay disgusto:\nYo quiero á aquer cabayero\nQu' está bestío de luto,\nQu' á mí me gusta lo negro.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,137,137,"1689","",0,"","","",2,0,0,[],""],["rm_t2-n1690",0,"Dama del pañuelo negro,\nDíme quién se te murió;\nSi es tu padre, bien lo lloras;\nSi es tu amante, aquí estoy yo.",0,0,-1,1,"",0,4,"o",2,0,-1,0,137,137,"1690","",0,"","","",2,0,0,[],""],["rm_t2-n1691",0,"Morenita y enlutada,\n¡Qué bien que te sienta el luto!\nNos casaremos los dos\nY Dios perdone al difunto.",0,0,-1,1,"",0,4,"uo",-1,0,-1,0,137,137,"1691","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1692",0,"Pregunté si eres casada,\nQue tu garbo me embelesa;\nEl preguntar no es errar,\nSi la pregunta no es necia.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,137,137,"1692","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1694",0,"Al alto cielo subí\nA preguntar por tu nombre\nY me dijo un serafin\nQue te llamabas Dolores\n[-Dolores me llamo, sí.]",0,0,-1,1,"",7,5,"i",-1,0,-1,0,138,138,"1694","",0,"","","",6,0,0,[],""],["rm_t2-n1695",0,"María sé que te llamas;\nTu apellido no lo sé;\nSi por la calle te encuentro,\nMaría te llamaré.",0,0,-1,1,"",0,4,"e",77,0,-1,0,138,138,"1695","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n1696",0,"Isabel sé que te llamas,\nCara redonda de luna;\nY muero por tus amores\nDesde chiquito en la cuna.",0,0,-1,1,"",0,4,"ua",56,0,-1,0,138,138,"1696","",0,"","","",1,0,0,[],""],["rm_t2-n1697",0,"Socorro pide en el mar\nEl marinero perdido,\nY yo que estoy en la tierra,\nSocorro, Socorro pido.",0,0,-1,1,"",0,4,"io",101,0,-1,0,138,138,"1697","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1698",0,"De Dolores estoy malo,\nDe Dolores enfermé;\nDolores tiene la culpa\nDe que yo malito esté.",0,0,-1,1,"",0,4,"e",77,0,-1,0,138,138,"1698","",0,"frenk_t1","","",2,0,0,[],""],["rm_t2-n1699",0,"Dígal' usté á esa serrana\nQue m' he muerto y que me bele\nY que m' encomiende 'l arma\nA la Bígen de las Niebes.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,139,139,"1699","",0,"","","",1,0,0,[],""],["rm_t2-n1700",0,"¡Ay, qué ventana tan alta!\n¡Ay, qué balcon tan dorado!\n¡Ay, qué niña tan bonita!\n¿Quién será su enamorado?",0,0,-1,1,"",0,4,"ao",14,0,-1,0,139,139,"1700","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1701",0,"Eres chiquita y bonita\nComo el trigo riojano.\n¡Vive Dios que eres hermosa!\n¡Quién fuera tu enamorado!",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,139,139,"1701","",0,"","","",12,0,0,[],""],["rm_t2-n1703",0,"Serrana, ¿quién te camela?\n¡Dime la berdá, por Dios!\nSi no te camela nádie,\nQuiero camelarte yo.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,139,139,"1703","",0,"","","",3,0,0,[],""],["rm_t2-n1704",0,"Eres rosita en capullo,\nSin acabar de salir;\nSi todavía no amas,\nAmame primero á mí.",0,0,-1,1,"",0,4,"i",-1,0,-1,0,139,139,"1704","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1705",0,"Manzanita colorada,\nQue en el suelo te cogí,\nSi no estás enamorada,\nEnamórate de mí.",0,0,-1,1,"",1,4,"i",23,0,-1,0,140,140,"1705","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1706",0,"Cuando te encuentro en la calle\nTe quisiera preguntar\nSi te causo yo alegria,\nO si te causo pesar.",0,0,-1,1,"",0,4,"a",21,0,-1,0,140,140,"1706","",0,"","","",13,0,0,[],""],["rm_t2-n1707",0,"Si duermo, contigo sueño;\nSi despierto, pienso en tí;\nDime tú, compañerita,\nSi te pasa lo que á mí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,140,140,"1707","",0,"","","",1,0,0,[],""],["rm_t2-n1708",0,"Si me acuesto, pienso en tí;\nSi m' alebanto, en tí pienso;\nTe quisiera preguntá\nSi á tí te pasa lo mesmo.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,140,140,"1708","",0,"","","",3,0,0,[],""],["rm_t2-n1709",0,"Quiero decir y no digo,\nY estoy sin decir diciendo;\nQuiero y no quiero querer,\nY estoy sin querer queriendo.",0,0,-1,1,"",0,4,"eo",52,0,-1,0,140,140,"1709","",0,"","","",2,0,0,[],""],["rm_t2-n1710",0,"Cada vez que me miras\nY yo te miro\nTe digo con los ojos\nLo que no digo.\nComo no hallo\nQue tú me correspondas,\nTe miro y callo.",0,0,-1,1,"",4,7,"ao",102,0,-1,0,140,140,"1710","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1711",0,"Con los ojos yo te miro\nY con la boca te hablo;\nY con los ojos te digo\nLo que no dicen mis labios.",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,141,141,"1711","",0,"","","",2,0,0,[],""],["rm_t2-n1712",0,"El amor que te tengo\nEs muy cobarde:\nHace que sienta mucho\nY poco hable.\nDicen mis penas\nMis ojos y suspiros,\nMas nó mi lengua.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,141,141,"1712","",0,"","","",10,0,0,[],""],["rm_t2-n1713",0,"Si miras á mis ojos\nCuando te miro,\nNo sé cómo no entiendes\nLo que te digo.\nSi me quisieras,\nTan sólo con mirarme\nTú me entendieras.",0,0,-1,1,"",4,7,"ea",103,0,-1,0,141,141,"1713","",0,"","","",1,0,0,[],""],["rm_t2-n1714",0,"Yo quiero bien y no puedo\nDecir á quién quiero bien;\nTan sólo diré que quiero\nSólo por sólo querer.",0,0,-1,1,"",0,4,"e",-1,0,-1,0,141,141,"1714","",0,"lafuente_madrid, preciso_coleccion, palau_cantares","","",4,0,0,[],""],["rm_t2-n1715",0,"Estoy adorando á un sol\nY veneran do á una imágen;\nNo siento más que una cosa:\nQue la quiero y no lo sabe.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,141,141,"1715","",0,"","","",3,0,0,[],""],["rm_t2-n1716",0,"Cualesquiera que me biere\nConoserá mi pasion:\nLo que la boca no jabla\nLo naquera er corason.",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,141,141,"1716","",0,"","","",4,0,0,[],""],["rm_t2-n1718",0,"Anoche tube un ensueño;\nSoñé que contigo hablaba;\nSoñaba er siego que bia\nY era que lo deseaba.",0,0,-1,1,"",0,4,"aa",28,0,-1,0,142,142,"1718","",0,"","","",1,0,0,[],""],["rm_t2-n1719",0,"Aunque sabe mi pecho\nLo que te quiere,\nTambien sabe ocultarlo,\nPor no ofenderte.",0,0,-1,1,"",6,4,"ee",-1,0,-1,0,142,142,"1719","",0,"","","",1,0,0,[],""],["rm_t2-n1720",0,"Me consumo la vida\nCuando te miro,\nPues te digo y no entiendes\nLo que te digo.",0,0,-1,1,"",6,4,"io",-1,0,-1,0,142,142,"1720","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1721",0,"Muchos hay que te dirán:\n-¡Salero, por tí me muero!-\nY yo no te digo nada,\nY soy el que más te quiero.",0,0,-1,1,"",0,4,"eo",38,0,-1,0,142,142,"1721","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1722",0,"Más te quieren mis ojos\nDisimulando\nQue otros dándote voces\nY alborotando.",0,0,-1,1,"",6,4,"ao",33,0,-1,0,142,142,"1722","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1723",0,"Mucho tengo que decirte,\nPero lo digo al silencio;\nMucho te digo callando,\nSi tienes entendimiento.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,142,142,"1723","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1724",0,"Estoy yo cuanto puedo\nDisimulando\nY tú con esos ojos\nMe estás matando.",0,0,-1,1,"",6,4,"ao",33,0,-1,0,143,143,"1724","",0,"","","",1,0,0,[],""],["rm_t2-n1725",0,"Muchos hay que no pueden\nDecir sus penas,\nPorque al querer decirlas\nSe ahogan con ellas.\nAsí, las mias\nNo podrás comprenderlas,\nNi yo decirlas.",0,0,-1,1,"",4,7,"ia",-1,0,-1,0,143,143,"1725","",0,"","","",3,0,0,[],""],["rm_t2-n1726",0,"Sólo puedo decirte\nMedias palabras;\nLo que empieza la lengua\nLo acaba el alma.\nPorque sucede\nQue el amor es muy niño\nY hablar no puede.",0,0,-1,1,"",4,7,"ee",104,0,-1,0,143,143,"1726","",0,"","","",1,0,0,[],""],["rm_t2-n1727",0,"Yo no sé lo que tienes\nEn tus ojuelos,\nQue mientras más los miro,\nMás gana tengo.\nPorque al mirarlos,\nBien sé yo lo que siento,\nPero lo callo.",0,0,-1,1,"",4,7,"ao",-1,0,-1,0,143,143,"1727","",0,"","","",2,0,0,[],""],["rm_t2-n1728",0,"Mi corazon se abrasa,\nNo sale el humo:\n¡Eso sí que es quemarse\nCon disimulo!",0,0,-1,1,"",6,4,"uo",-1,0,-1,0,143,143,"1728","",0,"","","",4,0,0,[],""],["rm_t2-n1729",0,"Mi corazon se abrasa;\nMas como es cuerdo,\nJamás ha dado indicios\nDe tal incendio.\nPero algun dia\nQue reviente es preciso\nLa oculta mina.",0,0,-1,1,"",4,7,"ia",-1,0,-1,0,144,144,"1729","",0,"","","",4,0,0,[],""],["rm_t2-n1730",0,"Tus ojos y los mios\nSe miran y hablan;\nPero los corazones\nNo se declaran.\nMas te prevengo\nQue si tú no te explicas,\nYo no te entiendo.",0,0,-1,1,"",4,7,"eo",-1,0,-1,0,144,144,"1730","",0,"murciano_antiguo, palau_cantares","","",7,0,0,[],""],["rm_t2-n1731",0,"Yo te quiero y no quiero,\nQue son dos cosas:\nYo te quiero y no quiero\nQue lo conozcas.",0,0,-1,1,"",6,4,"oa",-1,0,-1,0,144,144,"1731","",0,"fernan_caballero, suspiros_amor","","",5,0,0,[],""],["rm_t2-n1732",0,"Yo quisiera y no quisiera\nQue son cosas diferentes:\nQuisiera que me quisieras\nY no quisiera quererte.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,144,144,"1732","",0,"","","",6,0,0,[],""],["rm_t2-n1733",0,"Yo quisiera y no quisiera\nQue son dos cosas contrarias;\nQuisiera que me quisieras,\nPero que no me olvidaras.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,144,144,"1733","",0,"","","",6,0,0,[],""],["rm_t2-n1734",0,"Desde aquí te estoy mirando\nCara á cara y frente á frente\nY no te puedo decir\nLo que mi corazon siente.",0,0,-1,1,"",0,4,"ee",15,0,-1,0,144,145,"1734","",0,"carrizo_salta","","",20,0,0,[],""],["rm_t2-n1735",0,"Quisiera ser por un rato\nDe tu zarcillo el arete,\nPara decirte al oído\nLo que mi corazon siente.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,145,145,"1735","",0,"carrizo_salta","","",9,0,0,[],""],["rm_t2-n1736",0,"Considera tú por tí\nMi alma cómo estaría:\nEstando enfrente de tí,\nQuise hablarte y no podía.",0,0,-1,1,"",1,4,"ia",0,0,-1,0,145,145,"1736","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1737",0,"Por la caye ba quien quiere,\nPasa quien le da la gana;\nY yo aunque paso no pueo\nJablar contigo, serrana.",0,0,-1,1,"",0,4,"aa",4,0,-1,0,145,145,"1737","",0,"","","",1,0,0,[],""],["rm_t2-n1738",0,"Me miras y te miro;\nNo puedo hablarte;\nSentimiento en el alma\nTengo bastante.",0,0,-1,1,"",6,4,"ae",-1,0,-1,0,145,145,"1738","",0,"","","",3,0,0,[],""],["rm_t2-n1739",0,"No suspiro por verte,\nQue bien te veo;\nSuspiro por hablarte:\nQuiero y no puedo.",0,0,-1,1,"",6,4,"eo",-1,0,-1,0,145,145,"1739","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1740",0,"Enfrente de mí te tengo;\nNo te puedo decir nada:\nEstamos, como Valencia,\nCercaditos de murallas.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,145,145,"1740","",0,"","","",1,0,0,[],""],["rm_t2-n1742",0,"Desde que te ví te amé,\nDesde que te amé me muero;\nY si me muero por tí,\nDichoso me considero.",0,0,-1,1,"",0,4,"eo",38,0,-1,0,146,146,"1742","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",17,0,0,[],""],["rm_t2-n1743",0,"Desde que te ví te amé;\nPésame que ha sido tarde;\nQue yo quisiera, bien mio,\nDesde que nací adorarte.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,146,146,"1743","",0,"palau_cantares, lafuente_madrid, suspiros_amor","","",17,0,0,[],""],["rm_t2-n1744",0,"Verte, quererte y amarte,\nTodo ha sido de improviso;\nQue no sé qué fué primero:\nSi amarte ó haberte visto.",0,0,-1,1,"",0,4,"io",-1,0,-1,0,146,146,"1744","",0,"","","",3,0,0,[],""],["rm_t2-n1745",0,"Antes de conocerte,\nYa te queria,\nPorque me lo anunciaba\nLa estrella mia.\nQue es tal mi estrella,\nQue me anuncia la dicha\nSin conocerla.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,146,146,"1745","",0,"","","",3,0,0,[],""],["rm_t2-n1746",0,"Desde que te ví, rubita,\nEse rostro tan sereno,\nLas alas del corazon\nA los piés se me cayeron.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,146,146,"1746","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1747",0,"Desde aquella vez primera\nQue en tu presencia me ví,\nEl corazon, vida y alma\nA tu obediencia rendí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,146,147,"1747","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1748",0,"Ar regorbé d' una esquina\nTe bí la primera be\nY desde 'ntónses te beo,\nManque no te quiera be.",0,0,-1,1,"",0,4,"e",-1,0,-1,0,147,147,"1748","",0,"","","",2,0,0,[],""],["rm_t2-n1749",0,"Desde el punto que tus ojos\nEn los mios se fijaron,\nPaso los dias gimiendo\nY las noches suspirando.",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,147,147,"1749","",0,"","","",1,0,0,[],""],["rm_t2-n1750",0,"Compañerilla del alma,\nCuando mis ojos te vieron\nSe me arrancó el corazon,\nDe fatigas que me dieron.",0,0,-1,1,"",0,4,"eo",105,0,-1,0,147,147,"1750","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n1751",0,"Desde que te ví existo,\nDe tal manera,\nQue por no haberte visto\nNo sé qué diera.\nDándome tú el sér,\nPorque te he visto, vivo\nY muero tambien.",0,0,-1,1,"",4,7,"ae",-1,0,-1,0,147,147,"1751","",0,"","","",1,0,0,[],""],["rm_t2-n1752",0,"Ley es el que te adore\nEl que te viere:\nYo te he visto y no quiero\nQuebrantar leyes.\nPues mereciera\nDestierro de tus ojos,\nPor justa pena.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,147,147,"1752","",0,"","","",1,0,0,[],""],["rm_t2-n1753",0,"Desde que te bí, arma mia,\nPrendaito me queé,\nY más cuando me dijieron\nQu' eres firme 'n er queré.",0,0,-1,1,"",0,4,"e",77,0,-1,0,148,148,"1753","",0,"","","",1,0,0,[],""],["rm_t2-n1755",0,"Estudiante quise ser\nY así que vi tu hermosura\nA los infiernos tiré\nTintero, papel y pluma.",0,0,-1,1,"",0,4,"ua",-1,0,-1,0,148,148,"1755","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1756",0,"La primer vez que te ví\nMe echastes una cadena,\nSentadita en esa silla,\nCon esa cara morena.",0,0,-1,1,"",0,4,"ea",59,0,-1,0,148,148,"1756","",0,"","","",7,0,0,[],""],["rm_t2-n1757",0,"Desde que te ví, morena,\nEn la calle de Mesones,\nMe echastes una cadena\nCon veinticinco eslabones.",0,0,-1,1,"",1,4,"oe",34,0,-1,0,148,148,"1757","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n1758",0,"Una mañanita, apénas\nSalió el sol por el Oriente,\nMe echastes una cadena\nCon los rizos.de tu frente.",0,0,-1,1,"",0,4,"ee",15,0,-1,0,148,148,"1758","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1759",0,"A la salida de misa\nMe miraste y te miré;\nUna cadena me echaste,\nQue prisionero quedé.",0,0,-1,1,"",0,4,"e",77,0,-1,0,148,148,"1759","",0,"","","",5,0,0,[],""],["rm_t2-n1761",0,"Ya no te miran mis ojos\nCon aqueya serenía,\nComo te miraban ántes,\nCuando á mi casa benías.",0,0,-1,1,"",0,4,"ia",-1,0,-1,0,149,149,"1761","",0,"","","",1,0,0,[],""],["rm_t2-n1762",0,"Dicen qu' usté no me quiere,\nPorque soy un niño yo;\nDe un niño se espera un hombre\nY de un hombre un niño nó.",0,0,-1,1,"",0,4,"o",2,0,-1,0,149,149,"1762","",0,"","","",1,0,0,[],""],["rm_t2-n1763",0,"Dame de tus entrañas\nTodo el cariño\nY acaba de criarme,\nQue soy muy niño.\nY en siendo hombre,\nYo te daré el cariño\nQue corresponde.",0,0,-1,1,"",4,7,"oe",-1,0,-1,0,149,149,"1763","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1765",0,"Dichoso yo mil veces,\nFeliz mi suerte,\nPues tuve la fortuna\nDe conocerte.\nMe falta ahora\nEl que tú á mi cariño\nLe correspondas.",0,0,-1,1,"",4,7,"oa",-1,0,-1,0,149,150,"1765","",0,"","","",1,0,0,[],""],["rm_t2-n1766",0,"Yo te queria querer;\nYo te queria adorar;\nYo te queria tener\nUna firme boluntá.",0,0,-1,1,"",0,4,"a",-1,0,-1,0,150,150,"1766","",0,"","","",1,0,0,[],""],["rm_t2-n1767",0,"Er pensamiento m' anima\nDe querer á esta serrana;\nSolo yegaré á sentir\nQue me deje con la gana.",0,0,-1,1,"",0,4,"aa",4,0,-1,0,150,150,"1767","",0,"","","",1,0,0,[],""],["rm_t2-n1768",0,"¡Jole con jole con jole!\n¡Jole de tí para mí!\nQuiéreme, chachita mia,\nComo yo te quiero á tí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,150,150,"1768","",0,"","","",3,0,0,[],""],["rm_t2-n1769",0,"Quiéreme, Pepa mia,\nQuiéreme, Pepa;\nQuiéreme, por los golpes\nDe la retreta.",0,0,-1,1,"",6,4,"ea",-1,0,-1,0,150,150,"1769","",0,"","","",1,0,0,[],""],["rm_t2-n1770",0,"Determínate á quererme;\nNo me seas temerosa;\nDe los riesgos que vinieren\nTe sacaré victoriosa.",0,0,-1,1,"",0,4,"oa",63,0,-1,0,150,150,"1770","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1776",0,"Con ese delantal blanco\nVienes publicando guerra;\nY yo, como buen soldado,\nSiento plaza en tu bandera.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,151,151,"1776","",0,"","","",3,0,0,[],""],["rm_t2-n1777",0,"La reina doña Isabel\nPuso sus tiros en Baza\nY yo los he puesto en tí,\nPorque me haces mucha gracia.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,151,151,"1777","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1779",0,"La naranja nació verde\nY el tiempo la maduró;\nMi corazon nació libre\nY el tuyo lo cautivó.",0,0,-1,1,"",0,4,"o",2,0,-1,0,152,152,"1779","",0,"isaacs_colombia, andina_t2","","",5,0,0,[],""],["rm_t2-n1780",0,"Dime cómo te obligan\nLos que te quieren;\nDímelo, por si puedo\nYo parecerles.",0,0,-1,1,"",6,4,"ee",-1,0,-1,0,152,152,"1780","",0,"","","",1,0,0,[],""],["rm_t2-n1781",0,"En méritos no fundo\nMi confianza,\nQue amor no es de justicia,\nSino de gracia.",0,0,-1,1,"",6,4,"aa",-1,0,-1,0,152,152,"1781","",0,"","","",2,0,0,[],""],["rm_t2-n1782",0,"Pocos méritos tengo\nPara tu gracia;\nSupla lo que te quiero\nLo que me falta.\nY á mis finezas\nOtorga de justicia\nCorrespondencia.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,152,152,"1782","",0,"","","",1,0,0,[],""],["rm_t2-n1783",0,"Si para hablar contigo\nNo tengo gracia,\nRecompense el cariño\nLo que me falta.\nNo me maltrates,\nQue mi amor no merece\nQue así le pagues.",0,0,-1,1,"",4,7,"ae",-1,0,-1,0,152,152,"1783","",0,"","","",2,0,0,[],""],["rm_t2-n1784",0,"Además de tu gracia,\nTienes estrella\nPara que los amantes\nTodos te quieran.\nY á mí me falta\nPara que tú me quieras\nEstrella y gracia.",0,0,-1,1,"",4,7,"aa",-1,0,-1,0,152,153,"1784","",0,"","","",1,0,0,[],""],["rm_t2-n1785",0,"Si mi corazon llegare\nA pedirte una limosna\nY no tuvieres que darle,\nDile con amor:—Perdona—\n[No lo eches á la calle].",0,0,-1,1,"",7,5,"ae",-1,0,-1,0,153,153,"1785","",0,"","","",1,0,0,[],""],["rm_t2-n1786",0,"Limosniya 'r probe\nDásela por Dios;\nQu' er pro besito - biene mar jerío\nDer mar del amó.",0,0,-1,1,"",3,4,"o",-1,0,-1,0,153,153,"1786","",0,"","","",1,0,0,[],""],["rm_t2-n1787",0,"Yo pedí una limosna,\nPor ver tu cara,\nY me dijo tu madre\nQue perdonara.\n¡Qué pena me dió\nCuando tu madre dijo:\n-Perdona por Dios!",0,0,-1,1,"",4,7,"o",-1,0,-1,0,153,153,"1787","",0,"","","",1,0,0,[],""],["rm_t2-n1790",0,"María, flor de hermosura,\nPor tí peno y por tí muero;\nTú tienes la medicina:\nDale salud á este enfermo.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,154,154,"1790","",0,"","","",2,0,0,[],""],["rm_t2-n1791",0,"Pasando por tu calle\nEnfermé de amor;\nLlegué á tu puerta y dije:\n-¿Vive aquí el doctor?-\nMe respondieron:\n-Aquí vive quien puede\nDarte el remedio.",0,0,-1,1,"",4,7,"eo",-1,0,-1,0,154,154,"1791","",0,"","","",2,0,0,[],""],["rm_t2-n1792",0,"Son tus hermosos ojos\nDos hospitales,\nDonde curan enfermos\nDe graves males.\nAdmíteme á mí,\nQue estoy muy mal herido,\nDe quererte á tí.",0,0,-1,1,"",4,7,"i",23,0,-1,0,154,154,"1792","",0,"","","",4,0,0,[],""],["rm_t2-n1793",0,"El corazon tengo herido\nY las heridas me duelen;\nNo está muy léjos de aquí\nLa que curármelas puede.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,154,154,"1793","",0,"","","",6,0,0,[],""],["rm_t2-n1794",0,"Mi corazon dice, dice,\nQue se muere, que se muere;\nY yo le digo, le digo,\nQue confiese, que confiese.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,154,154,"1794","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1795",0,"Corresponde á mis ánsias,\nQue es tiranía\nNo aplicar el remedio\nQuien dió la herida.\nY aún es más grave\nHerida que penetra\nSin hacer sangre.",0,0,-1,1,"",4,7,"ae",-1,0,-1,0,154,155,"1795","",0,"","","",2,0,0,[],""],["rm_t2-n1797",0,"Como la mariposa\nBusco el quererte\nY en la luz de tus ojos\nTengo la muerte.\n¡Es cosa grande\nQue en la luz de tus ojos\nQuiera quemarme!",0,0,-1,1,"",4,7,"ae",-1,0,-1,0,155,155,"1797","",0,"","","",6,0,0,[],""],["rm_t2-n1798",0,"Anita y Ana y Anica,\nAnita, son tres renglones;\nAnita, si usté quisiera,\nCambiáramos corazones.",0,0,-1,1,"",3,4,"oe",34,0,-1,0,155,155,"1798","",0,"","","",1,0,0,[],""],["rm_t2-n1799",0,"Serrana, tú eres la lima,\nY tu padre es el limon,\nY tu madre la naranja:\nLa lima la quiero yo.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,155,155,"1799","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1800",0,"Dicen que lo azul es celos,\nY lo encarnado alegría,\nY lo verde es esperanza;\nEn tí espero, vida mia.",0,0,-1,1,"",0,4,"ia",0,0,-1,0,155,156,"1800","",0,"","","",3,0,0,[],""],["rm_t2-n1801",0,"Dama de abanico verde,\n¿Quiere usté ser mi pastora,\nQue el ganado que yo guardo\nDe lo verde se enamora?",0,0,-1,1,"",0,4,"oa",107,0,-1,0,156,156,"1801","",0,"","","",1,0,0,[],""],["rm_t2-n1802",0,"Eres alta y buena moza,\nMas te falta lo mejor:\nUn relicario en tu pecho\nY enmedio mi corazon.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,156,156,"1802","",0,"","","",3,0,0,[],""],["rm_t2-n1803",0,"En la cruz de tu pecho\nUna ermita ví;\nSi no tiene ermitaño\nArmíteme á mí.\nPorque una ermita,\nSi no tiene ermitaño\nNo está bonita.",0,0,-1,1,"",4,7,"ia",50,0,-1,0,156,156,"1803","",0,"","","",1,0,0,[],""],["rm_t2-n1805",0,"Señora, ¡quién fuera pollo\nDe su recoba de usté,\nPara andar todito el dia,\nPio, pio, tras de usté!",0,0,-1,1,"",0,4,"e",-1,0,-1,0,156,156,"1805","",0,"","","",2,0,0,[],""],["rm_t2-n1806",0,"En tu patio una lila\nDicen que tienes;\nNo me das un ramito,\nPorque no quieres.\nQue si quisieras,\nUn ramito de lila\nTú á mí me dieras.",0,0,-1,1,"",4,7,"ea",103,0,-1,0,156,157,"1806","",0,"","","",1,0,0,[],""],["rm_t2-n1807",0,"Si me das un ramillete\nCompuesto con tu cariño,\nYo te daré el corazon,\nLa prenda que más estimo.",0,0,-1,1,"",0,4,"io",-1,0,-1,0,157,157,"1807","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1808",0,"El clavel que tú me distes\nEl dia de la Asuncion\nNo fué clavel, sino clavo\nQue clavó mi corazon.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,157,157,"1808","",0,"","","",1,0,0,[],""],["rm_t2-n1809",0,"Toma, niña, esta naranja;\nTe la doy porque te quiero;\nNo la partas con cuchillo,\nQue va mi corazon dentro.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,157,157,"1809","",0,"","","",4,0,0,[],""],["rm_t2-n1810",0,"Toma, chiquiya, este aniyo\nQue te lo da un marinero;\nOjalay que te se buerba\nUna barquita con remos.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,157,157,"1810","",0,"","","",1,0,0,[],""],["rm_t2-n1811",0,"Una tórtola te traigo\nQue del nido la cogí;\nSu madre llora por ella,\nComo yo lloro por tí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,157,157,"1811","",0,"","","",3,0,0,[],""],["rm_t2-n1812",0,"Palomita amartelada\nDel palomar de Cupido,\nNo sientas levantar vuelo\nY vente á volar conmigo.",0,0,-1,1,"",0,4,"io",-1,0,-1,0,157,157,"1812","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1813",0,"Dame la mano, paloma,\nPara subí ar palomá;\nQue m' han dicho qu' estás sola\nY te vengo á 'compañá.",0,0,-1,1,"",0,4,"a",9,0,-1,0,158,158,"1813","",0,"","","",3,0,0,[],""],["rm_t2-n1814",0,"-Pajarito de la niebe,\nDime, ¿dónde tiene 'r nío?\n-Lo tengo en un pino berde,\nEn una rama escondío.",0,0,-1,1,"",0,4,"io",3,0,-1,0,158,158,"1814","",0,"","","",1,0,0,[],""],["rm_t2-n1815",0,"Por ermedio d' esta caye\nAnda un gabilan perdío,\nDisiendo qu' ha de sacá\nLa paloma de su nío.",0,0,-1,1,"",0,4,"io",3,0,-1,0,158,158,"1815","",0,"","","",1,0,0,[],""],["rm_t2-n1816",0,"Águila que vas volando,\n¿Dónde remontas el vuelo?\nLo remonto yo bien alto,\nMas no lo remonto al cielo.",0,0,-1,1,"",0,4,"eo",10,0,-1,0,158,158,"1816","",0,"","","",10,0,0,[],""],["rm_t2-n1817",0,"Águila real hermosa,\nNo busques nido:\nAquí tienes mi pecho\nFortalecido.\nNo te remontes;\nSuspéndete en el aire\nY oirás mis voces.",0,0,-1,1,"",4,7,"oe",-1,0,-1,0,158,158,"1817","",0,"","","",1,0,0,[],""],["rm_t2-n1818",0,"Soy pájaro zarzaleño\nQue me cuelo en los zarzales;\nEn tu casa no me cuelo,\nPorque no quiere tu madre.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,158,158,"1818","",0,"","","",1,0,0,[],""],["rm_t2-n1819",0,"Yo se lo dije á una niña\nA la puerta de la calle\nY me respondió diciendo:\n-Allá dentro está mi madre.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,159,159,"1819","",0,"","","",1,0,0,[],""],["rm_t2-n1820",0,"Anda bé y dile á tu madre\nQue si te quiere bendé,\nEn la mano 'stá 'r dinero\nY en la puerta 'r mercaé.",0,0,-1,1,"",0,4,"e",77,0,-1,0,159,159,"1820","",0,"","","",2,0,0,[],""],["rm_t2-n1821",0,"Mozo der botín caído\nY er sombrero á lo gachon,\nSi usté compra corazones,\nEr mio lo bendo yo.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,159,159,"1821","",0,"","","",1,0,0,[],""],["rm_t2-n1822",0,"Anda bé y dile á tu mare\nQue yo me quiero najá;\nY si tu mare no quiere,\nAl istante m' etendrá.",0,0,-1,1,"",0,4,"a",9,0,-1,0,159,159,"1822","",0,"","","",4,0,0,[],""],["rm_t2-n1826",0,"Tan sólo porque me miras\nMe parece que me quieres;\nSi así fuera, prenda mia,\n¿A qué quiero más placeres?",0,0,-1,1,"",0,4,"ee",55,0,-1,0,160,160,"1826","",0,"","","",1,0,0,[],""],["rm_t2-n1827",0,"Si usté me quisiera á mí\nLo mismo que yo la quiero,\nNo le tuviera yo envidia\nNi á los ángeles del cielo.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,160,160,"1827","",0,"","","",3,0,0,[],""],["rm_t2-n1828",0,"Si usté me quisiera á mí\nComo yo la quiero á usté,\nNos llamaran á los dos\nLos amantes de Teruel.",0,0,-1,1,"",0,4,"e",-1,0,-1,0,160,160,"1828","",0,"","","",3,0,0,[],""],["rm_t2-n1829",0,"Si supiera, pimpollito,\nQue para mí te criabas,\nTodos los bienes del mundo\nPor tí los abandonara.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,160,160,"1829","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1830",0,"Si supiera que era yo\nLa causa de tu tristeza,\nDejaria padre y madre\nY te amara con firmeza.",0,0,-1,1,"",0,4,"ea",108,0,-1,0,160,160,"1830","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1831",0,"Por que tú me quisieras,\nSerrana mia,\nDiera yo todo el oro\nQue hay en las Indias.",0,0,-1,1,"",6,4,"ia",-1,0,-1,0,160,160,"1831","",0,"","","",1,0,0,[],""],["rm_t2-n1832",0,"Diera yo por que me dieras\nDe tu linda boca el sí,\nLas alfombras de Turquía\nY el oro del Potosí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,160,160,"1832","",0,"","","",1,0,0,[],""],["rm_t2-n1833",0,"Si supiera que eras mia,\nTe regalaba un pañuelo\nCon cuatro borlitas de oro\nY mi corazon enmedio.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,161,161,"1833","",0,"","","",1,0,0,[],""],["rm_t2-n1834",0,"Si supiera que con flores\nTe habia de conseguir,\nTe trajera yo más flores\nQue tienen Mayo y Abril.",0,0,-1,1,"",0,4,"i",-1,0,-1,0,161,161,"1834","",0,"","","",2,0,0,[],""],["rm_t2-n1835",0,"Si con promesas pudiera\nAcarrearte ar queré,\nE roiyas iba á Roma,\nPor la leche que mamé.",0,0,-1,1,"",0,4,"e",77,0,-1,0,161,161,"1835","",0,"","","",1,0,0,[],""],["rm_t2-n1837",0,"Quiéreme y esperimenta;\nLuégo verás si te quiero:\nVerás á un hombre morir,\nComo Cristo en el madero.",0,0,-1,1,"",0,4,"eo",38,0,-1,0,161,161,"1837","",0,"","","",1,0,0,[],""],["rm_t2-n1839",0,"Si por hazañas de monta\nSe pudiera usté ganar,\nTomara yo por asalto\nEl peñon de Gibraltar.",0,0,-1,1,"",0,4,"a",21,0,-1,0,161,161,"1839","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1840",0,"Diera yo por conseguir\nEl que usté á mí me quisiera\nLos ojitos e mi cara,\nAunque me queara siega.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,162,162,"1840","",0,"","","",2,0,0,[],""],["rm_t2-n1841",0,"Bien sabe Dios que te diera\nPor esa morena cara\nLos ojitos de lamia,\nAunque ciego me queara.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,162,162,"1841","",0,"","","",6,0,0,[],""],["rm_t2-n1842",0,"Ar demonio del infierno\nYo mi arma le daria,\nPor hablá contigo á solas\nSiquiera una horita 'r dia.",0,0,-1,1,"",0,4,"ia",0,0,-1,0,162,162,"1842","",0,"","","",1,0,0,[],""],["rm_t2-n1843",0,"Niña, si quieres canela,\nCanela yo te daré;\nMira que á canela sabe\nDe mi pechito er queré.",0,0,-1,1,"",0,4,"e",77,0,-1,0,162,162,"1843","",0,"","","",2,0,0,[],""],["rm_t2-n1845",0,"Aquí no se bende guasa,\nQue se bende más arriba;\nQue lo que se bende aquí\nEs canela de la fina.",0,0,-1,1,"",0,4,"ia",-1,0,-1,0,162,162,"1845","",0,"","","",1,0,0,[],""],["rm_t2-n1846",0,"Eres, niña chiquita,\nFlor de la cera;\n¿Cómo no he de quererte,\nSi soy abeja?\nSi me quisieras,\nEn miel mi cariñito\nSe convirtiera.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,162,163,"1846","",0,"","","",2,0,0,[],""],["rm_t2-n1847",0,"En la sala del crímen\nDe tu belleza\nEstá mi amor á gritos\nPidiendo audiencia.\nNo se la niegues,\nQue la causa que alega\nJusticia tiene.",0,0,-1,1,"",4,7,"ee",-1,0,-1,0,163,163,"1847","",0,"","","",1,0,0,[],""],["rm_t2-n1848",0,"Las campanas de la iglesia\nEstán doblando por mí;\nDime, niña, si me quieres,\nResucitaré por tí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,163,163,"1848","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1849",0,"Quisiera ser onza de oro,\nMi vida, y tener dos caras,\nPara parecerle bien\nA todo el que me mirara.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,163,163,"1849","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1850",0,"Échame una cadenita\nDe tu muñeca á mi mano\nY cualquiera que nos vea\nDirá que somos hermanos.",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,163,163,"1850","",0,"","","",1,0,0,[],""],["rm_t2-n1851",0,"Ni como ni bebo á gusto,\nNi me aprobecha la cena,\nEn pensar si haremos argo\nCon esta moza tan buena.",0,0,-1,1,"",0,4,"ea",59,0,-1,0,163,163,"1851","",0,"","","",1,0,0,[],""],["rm_t2-n1852",0,"Yo tiré un limon á un pozo,\nSe fué al fondo y crió rama;\nPor eso á mi me precisa\nEl querer á esta serrana.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,163,164,"1852","",0,"","","",1,0,0,[],""],["rm_t2-n1853",0,"Alza la voz, pregonero,\nY apregona que en el rio\nNo hay agua para apagar\nUn corazon encendío.",0,0,-1,1,"",0,4,"io",3,0,-1,0,164,164,"1853","",0,"","","",9,0,0,[],""],["rm_t2-n1854",0,"Abre esos brazos de amor,\nResalada prenda mia,\nY en ellos recogerás\nUn arma que ba perdía.",0,0,-1,1,"",0,4,"ia",0,0,-1,0,164,164,"1854","",0,"","","",1,0,0,[],""],["rm_t2-n1855",0,"Ábrele á tu pecho tierno\nUna ventana chiquita,\nQue pueda mi corazon\nHacerle al tuyo visita.",0,0,-1,1,"",0,4,"ia",50,0,-1,0,164,164,"1855","",0,"","","",1,0,0,[],""],["rm_t2-n1857",0,"Contigo me dan matraca,\n¡Ojalay fuera berdá,\nQue nunca los rayos caen\nDonde la tormenta está!",0,0,-1,1,"",0,4,"a",9,0,-1,0,164,164,"1857","",0,"","","",3,0,0,[],""],["rm_t2-n1858",0,"Un canario aflegío\nRonda mi barrio;\n¡Quién fuera la canaria\nD' ese canario!",0,0,-1,1,"",6,4,"ao",-1,0,-1,0,164,164,"1858","",0,"","","",1,0,0,[],""],["rm_t2-n1859",0,"La calle me la pasea,\nMadre mia, un andaluz;\nEl andaluz de mis ojos;\nDe mis ojitos la luz.",0,0,-1,1,"",0,4,"u",109,0,-1,0,165,165,"1859","",0,"","","",1,0,0,[],""],["rm_t2-n1860",0,"Un alto y un pequeño\nRondan mi calle;\nEl alto se parece\nAl sol que sale.\nPero el pequeño\nSe parece á la luna\nDel mes de Enero.",0,0,-1,1,"",4,7,"eo",-1,0,-1,0,165,165,"1860","",0,"","","",1,0,0,[],""],["rm_t2-n1861",0,"Bajito de cuerpo es\nEl que mi calle pasea;\nComo se mantenga firme,\nLogrará lo que desea.",0,0,-1,1,"",0,4,"ea",54,0,-1,0,165,165,"1861","",0,"","","",1,0,0,[],""],["rm_t2-n1862",0,"Son tus hermosos ojos\nComo dos soles\nY eres, niña, la reina\nDe los amores.\nNiña, por piedad,\nDéjame que en la reina\nPueda yo mandar.",0,0,-1,1,"",4,7,"a",-1,0,-1,0,165,165,"1862","",0,"","","",4,0,0,[],""],["rm_t2-n1863",0,"Un pañuelo de llamas\nTengo que darte,\nPor ver si con las llamas\nPuedo llamarte.\n¡Ay, que no puedo\nLlamarte con las llamas\nDe mi pañuelo!",0,0,-1,1,"",4,7,"eo",-1,0,-1,0,165,165,"1863","",0,"","","",1,0,0,[],""],["rm_t2-n1864",0,"A Isabela en el baño\nLa vió el rey Dabí\nY se enamoró d' eya\nComo yo de tí.\nQuiéreme tú á mí,\nTú serás la Isabela\nY yo el rey Dabí.",0,0,-1,1,"",4,7,"i",23,0,-1,0,166,166,"1864","",0,"","","",1,0,0,[],""],["rm_t2-n1865",0,"Sólo con acordarme\nDe que te amo\nEs tanta mi alegría,\nQue de mí salgo.\nConque si viera\nQue me correspondias,\nDe mí, ¿qué fuera?",0,0,-1,1,"",4,7,"ea",44,0,-1,0,166,166,"1865","",0,"","","",1,0,0,[],""],["rm_t2-n1866",0,"El dia que tú me quieras\nLo mismo que yo te quiero,\nDímelo poquito á poco,\nPorque de prisa, me muero.",0,0,-1,1,"",0,4,"eo",38,0,-1,0,166,166,"1866","",0,"","","",4,0,0,[],""],["rm_t2-n1867",0,"Cupido como niño\nSe lamentaba\nY Vénus como diosa\nLe consolaba.\nHazlo conmigo\nY tú serás la diosa\nY yo Cupido.",0,0,-1,1,"",4,7,"io",-1,0,-1,0,166,166,"1867","",0,"","","",3,0,0,[],""],["rm_t2-n1868",0,"Cupidillo, no gastes\nChanzas conmigo,\nQue si no tengo amores,\nLos he tenido.\nConmigo chanzas,\nQue si no tengo amores,\nTengo esperanzas.",0,0,-1,1,"",4,7,"aa",110,0,-1,0,166,167,"1868","",0,"","","",3,0,0,[],""],["rm_t2-n1869",0,"Debajo de un limon verde\nUn pajarito cantó;\nCante quien amores tiene,\nQue pronto cantaré yo.",0,0,-1,1,"",0,4,"o",2,0,-1,0,167,167,"1869","",0,"","","",9,0,0,[],""],["rm_t2-n1870",0,"Ayer me fuí á confesar\nCon un padre capuchino\nY me echó de penitencia\nQue me casara contigo.",0,0,-1,1,"",0,4,"io",-1,0,-1,0,167,167,"1870","",0,"","","",3,0,0,[],""],["rm_t2-n1871",0,"Yo soy uno y tú eres una;\nUno y una, que son dos;\nDos que debieran ser uno;\n¡Ay, si lo quisiera Dios!",0,0,-1,1,"",0,4,"o",87,0,-1,0,167,167,"1871","",0,"","","",1,0,0,[],""],["rm_t2-n1872",0,"Más quisiera que fueras\nFea y afable\nQue nó hermosa y esquiva,\nPara matarme.\nMas si esto logro,\nSiendo afable y hermosa,\nSeré dichoso.",0,0,-1,1,"",4,7,"oo",-1,0,-1,0,167,167,"1872","",0,"","","",1,0,0,[],""],["rm_t2-n1873",0,"Pregunta por mi nombre\nEn este lugar;\nTe dirán que soy pobre;\nNo te dirán más.\nY aunque soy pobre,\nLa vergüenza y la honra\nCautiva al hombre.",0,0,-1,1,"",4,7,"oe",-1,0,-1,0,167,167,"1873","",0,"","","",1,0,0,[],""],["rm_t2-n1874",0,"Tienes cara de ángel bello,\nY ojitos de serafin;\nYo me casara contigo,\nSi tú me dieras el sí.",0,0,-1,1,"",0,4,"i",-1,0,-1,0,168,168,"1874","",0,"","","",1,0,0,[],""],["rm_t2-n1875",0,"Sin tí no puedo vivir,\nHermosa luna brillante;\nDame de tu boca el sí,\nQue deseo ser tu aman te.",0,0,-1,1,"",5,4,"e",-1,0,-1,0,168,168,"1875","",0,"","","",2,0,0,[],""],["rm_t2-n1876",0,"Son tus labios dos cortinas\nDe tafetan carmesí\nY entre cortina y cortina\nEstoy esperando el sí.",0,0,-1,1,"",3,4,"i",23,0,-1,0,168,168,"1876","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1877",0,"Vivo en el cautiverio\nDe una morena\nY con un sí tan sólo\nSalgo de penas.",0,0,-1,1,"",6,4,"ea",-1,0,-1,0,168,168,"1877","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n1878",0,"Con un sí de tus labios\nMi amor se paga;\nMira qué poco pido:\nDos letras, nada.\nSé compasiva,\nQue con un sí tan sólo\nMe das la vida.",0,0,-1,1,"",4,7,"ia",-1,0,-1,0,168,168,"1878","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n1879",0,"Campaniya e plata,\nReló e marfin,\nComo esperaba, - compañera mia,\nE tu boca er sí.",0,0,-1,1,"",3,4,"i",-1,0,-1,0,168,168,"1879","",0,"","","",1,0,0,[],""],["rm_t2-n1880",0,"Enmedio de tu frente\nTienes una i\nY te falta una s\nPara decir sí.\n¡Ay, si tuvieras\nLa s que te falta,\nQue sí dijeras!",0,0,-1,1,"",4,7,"ea",103,0,-1,0,169,169,"1880","",0,"","","",1,0,0,[],""],["rm_t2-n1881",0,"Dame lo que te pido,\nBien de mi vida:\nUna i y una s\nY un punto encima.\nMuerto me tienes,\nAl ver que ántes me diste\nLa o y la n.",0,0,-1,1,"",4,7,"",-1,0,-1,0,169,169,"1881","",0,"","","",1,0,0,[],""],["rm_t2-n1883",0,"Tantas letras tiene el sí,\nComo letras tiene el nó;\nCon el sí me das la vida\nY la muerte con el nó.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,169,169,"1883","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1885",0,"Desengáñame, tirana,\nY dime que sí ó que nó;\nSi he de entrar, he de ser solo;\nSi entra otro, no entro yo.",0,0,-1,1,"",0,4,"o",2,0,-1,0,170,170,"1885","",0,"","","",1,0,0,[],""],["rm_t2-n1886",0,"No te quiero dar el sí,\nHasta ver cómo te portas;\nQue no muy léjos de aquí\nMe han dicho que tienes otra\n[Que la quieres más que á mí].",0,0,-1,1,"",7,5,"i",23,0,-1,0,170,170,"1886","",0,"","","",3,0,0,[],""],["rm_t2-n1887",0,"La luna para salir\nLe pide licencia al cielo\nY yo para hablar contigo\nLicencia pido primero.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,170,170,"1887","",0,"carrizo_salta","","",14,0,0,[],""],["rm_t2-n1888",0,"Escucha, que quiero hablarte\nEn amorosa consurta:\nDe toas las mosas qu' he bisto\nTú eres la que más me gusta.",0,0,-1,1,"",3,4,"ua",-1,0,-1,0,170,170,"1888","",0,"","","",1,0,0,[],""],["rm_t2-n1889",0,"Siéntate al lado de mí\nY te daré una razon,\nPara que nádie se entere\nDe nuestra conversacion.",0,0,-1,1,"",0,4,"ao",31,0,-1,0,170,170,"1889","",0,"","","",1,0,0,[],""],["rm_t2-n1890",0,"Déjame, prenda, por Dios,\nPlaticar, aunque sea pobre;\nQue un grillo vale dos cuartos,\nY con todo, se le oye.",0,0,-1,1,"",0,4,"oe",-1,0,-1,0,170,170,"1890","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1891",0,"Gracias á Dios que he llegado\nA declarar mi pasion\nA una dama tan hermosa\nComo los rayos del sol.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,170,170,"1891","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n1892",0,"Ya me despido, mi vida,\nDe tu hermosura y belleza;\nPara vivir ó morir,\nSólo aguardo la respuesta.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,171,171,"1892","",0,"","","",3,0,0,[],""],["rm_t2-n1893",0,"El decirte á tí que sí\nLo tengo yo de mi mano;\nPero cifro mi gustiyo\nEn ber los hombres penando.",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,171,171,"1893","",0,"","","",1,0,0,[],""],["rm_t2-n1894",0,"Soy más gitana qu' er gayo;\nNáide me lo contradiga;\nEr gachó que me camele\nHa de pasá faitiguiyas.",0,0,-1,1,"",0,4,"ia",-1,0,-1,0,171,171,"1894","",0,"","","",1,0,0,[],""],["rm_t2-n1895",0,"Quiéreme y adórame;\nQue me aborrezcas no quiero;\nY si me has de aborrecer,\nDame la muerte primero.",0,0,-1,1,"",0,4,"eo",38,0,-1,0,171,171,"1895","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1896",0,"Si me quieres, dímelo,\nY si nó, dame veneno;\nNo serás tú la primera\nQue se lo ha dado á su dueño.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,171,171,"1896","",0,"carrizo_salta","","",17,0,0,[],""],["rm_t2-n1897",0,"Toma allá mi corazon;\nSi lo quieres matar, puedes;\nPero como tú estás dentro,\nTambien si lo matas, mueres.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,171,171,"1897","",0,"","","",7,0,0,[],""],["rm_t2-n1898",0,"Si mi corazon te estorba,\nAnda y échalo á la calle\nQue se lo coman los perros,\nSi es que no lo quiere nádie.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,171,171,"1898","",0,"","","",3,0,0,[],""],["rm_t2-n1899",0,"Mi corazon tú lo tienes;\nDámelo si no te sirve;\nSe lo daré á otra paloma\nQue con su calor lo abrigue.",0,0,-1,1,"",0,4,"ie",-1,0,-1,0,172,172,"1899","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n1900",0,"¡Mi corazon á tus piés\nRendido y no lo levantas!\n¡Lástima de corazon,\nQue no duerme ni descansa!",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,172,172,"1900","",0,"","","",5,0,0,[],""],["rm_t2-n1902",0,"Ya voy llegando á la calle\nDonde muero y peno yo;\n¡Las paredes me conocen\nY el bien de mi vida nó!",0,0,-1,1,"",0,4,"o",2,0,-1,0,172,172,"1902","",0,"","","",1,0,0,[],""],["rm_t2-n1903",0,"Mucho sentiré, bien mio,\nQue tu amor me dé mal pago,\nPorque de tu barrio al mio\nPara zapatos no gano.",0,0,-1,1,"",11,4,"ao",2,0,-1,0,172,172,"1903","",0,"","","",1,0,0,[],""],["rm_t2-n1904",0,"Desde que amanece el dia\nHasta que se pone el sol\nEstoy, como un alma en pena,\nDebajo de tu balcon.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,172,172,"1904","",0,"","","",1,0,0,[],""],["rm_t2-n1905",0,"Desempiedra tu calle\nY échale barro,\nY verás las pisadas\nDe mi caballo.\nY échale arena\nY verás las pisadas\nQue doy en ella.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,173,173,"1905","",0,"","","",1,0,0,[],""],["rm_t2-n1906",0,"Si esta noche no sales\nÁ la ventana,\nCuéntame con los muertos\nDesde mañana.",0,0,-1,1,"",6,4,"aa",4,0,-1,0,173,173,"1906","",0,"","","",2,0,0,[],""],["rm_t2-n1907",0,"Si quieres hablarme y verme,\nVén esta noche al postigo\nY mientras mi madre duerme,\nEstaré hablando contigo.",0,0,-1,1,"",1,4,"io",106,0,-1,0,173,173,"1907","",0,"","","",1,0,0,[],""],["rm_t2-n1910",0,"No me mires de reojo,\nQue es mirada de traidor;\nMírame así, cara á cara,\nQue es miradita de amor.",0,0,-1,1,"",0,4,"o",72,0,-1,0,173,173,"1910","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1911",0,"No me mires de lado,\nQue es de traidores;\nMírame cara á cara,\nQue es de señores.",0,0,-1,1,"",6,4,"oe",5,0,-1,0,173,173,"1911","",0,"palau_cantares, barcenas_marinera, huambachano","","",4,0,0,[],""],["rm_t2-n1912",0,"No me mires con ojos\nAtravesados;\nMírame con los ojos\nQue Dios te ha dado'.",0,0,-1,1,"",6,4,"ao",-1,0,-1,0,174,174,"1912","",0,"fernan_caballero, barcenas_marinera","","",3,0,0,[],""],["rm_t2-n1913",0,"No me mires, ingrata,\nCon tanto dengue;\nQue si no tengo penas,\nMe haces que pene.",0,0,-1,1,"",6,4,"ee",-1,0,-1,0,174,174,"1913","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t2-n1914",0,"Tienes unos ojos, niña,\nEnseñados á vivir;\nCariñosos para todos\nY tiranos para mí.",0,0,-1,1,"",0,4,"i",-1,0,-1,0,174,174,"1914","",0,"palau_cantares, lafuente_madrid","","",13,0,0,[],""],["rm_t2-n1915",0,"Por Dios, si no me quieres,\nQue no me mires:\nYa que no me rescates,\nNo me cautives.\nNo me mires más;\nNo me pongas cadenas\nQue no has de quitar.",0,0,-1,1,"",4,7,"a",-1,0,-1,0,174,174,"1915","",0,"fernan_caballero","","",7,0,0,[],""],["rm_t2-n1916",0,"Para hacerme dichoso,\nNo sé que dudas,\nSabiendo que hasta el alma\nQue tengo es tuya.\nO has de ser mia,\nO has de volverme el alma,\nPara que viva.",0,0,-1,1,"",4,7,"ia",-1,0,-1,0,174,174,"1916","",0,"","","",1,0,0,[],""],["rm_t2-n1918",0,"El alma me has robado;\nDame la tuya,\nQue el ladron es preciso\nQue restituya.\nAmor tirano,\nRestitúyeme el alma\nQue me has robado.",0,0,-1,1,"",4,7,"ao",-1,0,-1,0,175,175,"1918","",0,"","","",5,0,0,[],""],["rm_t2-n1919",0,"Me robastes el alma\nCon tal salero,\nQue para hablar con otra,\nAlma no tengo.\nDame la tuya,\nQue el ladron es preciso\nQue restituya.",0,0,-1,1,"",4,7,"ua",111,0,-1,0,175,175,"1919","",0,"","","",1,0,0,[],""],["rm_t2-n1921",0,"Debes á mi cariño\nCorresponderme,\nPorque te he dado el alma\nY esa me debes.\nLa paga aguardo,\nPues el negarla es prueba\nDe un pecho ingrato.",0,0,-1,1,"",4,7,"ao",-1,0,-1,0,175,175,"1921","",0,"","","",1,0,0,[],""],["rm_t2-n1922",0,"Rendido de amor me tienes\nY sé que quieres á otro;\nY por Dios te pido, niña,\nQue me lo despaches pronto.",0,0,-1,1,"",0,4,"oo",-1,0,-1,0,176,176,"1922","",0,"","","",1,0,0,[],""],["rm_t2-n1923",0,"Si luégo has de quererme,\nQuiéreme ahora,\nPorque dice el adagio:\nMás vale un toma....\nNo me des largas\nPues podré yo decirte:\nBuenas son mangas....",0,0,-1,1,"",4,7,"aa",-1,0,-1,0,176,176,"1923","",0,"","","",1,0,0,[],""],["rm_t2-n1924",0,"Si me quieres, dímelo,\nY si nó, no me desprecies;\nQue soy chino y algun dia\nPuede ser que en mí tropieces.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,176,176,"1924","",0,"fernan_caballero","","",17,0,0,[],""],["rm_t2-n1925",0,"¿Apénas me conoces,\nYa me amenazas?\nMira que tengo un huerto\nDe calabazas.\nMira que voy,\nCorto una calabaza\nY tela doy.",0,0,-1,1,"",4,7,"o",112,0,-1,0,176,176,"1925","",0,"","","",1,0,0,[],""],["rm_t2-n1926",0,"Si me quieres, dímelo;\nY si nó, dí que me vaya;\nNo me tengas al sereno,\nQue no soy cántaro de agua.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,176,176,"1926","",0,"palau_cantares, navalmoral_mata","","",17,0,0,[],""],["rm_t2-n1927",0,"Acábame de decir\nQue me quede ó que me vaya,\nPorque me estoy deshaciendo\nComo la sal en el agua.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,176,176,"1927","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n1928",0,"Díme, niña, si me quieres;\nPor Dios, descubre tu pecho;\nQue no quiero en este mundo\nPasar tiempo sin provecho.",0,0,-1,1,"",0,4,"eo",60,0,-1,0,177,177,"1928","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n1929",0,"¡Caramba! si me quieres,\nNo me muelas más;\nResuélvete y acaba\nDe determinar.\nSi no me quieres,\nDímelo luégo al punto,\nQue hay quien espere.",0,0,-1,1,"",4,7,"ee",-1,0,-1,0,177,177,"1929","",0,"","","",1,0,0,[],""],["rm_t2-n1931",0,"Dime, dueño, si vivo\nDentro del alma,\nY si nó, no gastemos\nPólvora en salvas.",0,0,-1,1,"",6,4,"aa",-1,0,-1,0,177,177,"1931","",0,"","","",2,0,0,[],""],["rm_t2-n1933",0,"Acaba de quererme,\nTardeó temprano;\nNo seas como el perro\nDel hortelano.",0,0,-1,1,"",6,4,"ao",81,0,-1,0,177,177,"1933","",0,"","","",2,0,0,[],""],["rm_t2-n1935",0,"Abre, niña, los ojos;\nDeja lo esquivo;\nMira que no se encuentran\nMuchos maridos.",0,0,-1,1,"",6,4,"io",-1,0,-1,0,178,178,"1935","",0,"","","",2,0,0,[],""],["rm_t2-n1936",0,"Te dije si me querias\nY me dijiste:-Veré.-\nBastante tiempo has tenido\nPara tomar parecer.",0,0,-1,1,"",0,4,"e",-1,0,-1,0,178,178,"1936","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1937",0,"Tú me das esperanzas;\nMas no me dices\nEl dia que mis ánsias\nSerán felices.",0,0,-1,1,"",6,4,"ie",113,0,-1,0,178,178,"1937","",0,"carrizo_salta, palau_cantares","","",4,0,0,[],""],["rm_t2-n1938",0,"Yo quiero que al principio\nMe desengañes:\nMás bien quiero desprecios\nQun falsedades.",0,0,-1,1,"",6,4,"ae",-1,0,-1,0,178,178,"1938","",0,"","","",1,0,0,[],""],["rm_t2-n1939",0,"Tú eres el juez de mi causa\nY yo soy el delincuente;\nAcaba de sentenciar\nSi soy de vida ó de muerte.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,178,178,"1939","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1940",0,"Pues tu rigor decreta\nDarme tormento,\nEl delito de amarte\nYo lo confieso.\nDa la sentencia,\nQue confeso y convicto,\nNiña, me encuentras.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,178,178,"1940","",0,"","","",1,0,0,[],""],["rm_t2-n1941",0,"Yo no pretendo, serrana,\nQue me quieras á la fuerza;\nPero sí quiero que mires\nLas penillas que me cuestas.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,179,179,"1941","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1942",0,"Anda béte de mi puerta,\nAnda béte retirando,\nQue mi puerta no se ha hecho\nReja de confesonario.",0,0,-1,1,"",0,4,"ao",-1,0,-1,0,179,179,"1942","",0,"","","",1,0,0,[],""],["rm_t2-n1943",0,"Dentro de mi pecho tengo\nUn tribunal superior,\nQue en echando la sentencia\nYa no admite apelacion.",0,0,-1,1,"",0,4,"o",-1,0,-1,0,179,179,"1943","",0,"","","",32,0,0,[],""],["rm_t2-n1944",0,"¡Al cabo de tanto tiempo\nQue mi corazon te amó,\nHas tenido atrevimiento\nPara decirme que nó!",0,0,-1,1,"",0,4,"o",2,0,-1,0,179,179,"1944","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1945",0,"Corazon, busca un empeño\nPara hablarle á esa mujer;\nQue yo me muero por ella\nY ella no me puede ver.",0,0,-1,1,"",0,4,"e",20,0,-1,0,179,179,"1945","",0,"","","",1,0,0,[],""],["rm_t2-n1946",0,"Como que sale de tí,\nPrégúntale si me quiere;\nY si te dice que nó,\nDile qué motivos tiene.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,179,179,"1946","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1948",0,"A mi triste camarada\nQuiérelo, que bien te quiere;\nDelante de mí ha jurado,\nSerrana, que por tí muere.",0,0,-1,1,"",0,4,"ee",115,0,-1,0,180,180,"1948","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1950",0,"¿De qué te sirve que andes\nComo gato por paderes?\n¿No ha yegado á tu notisia\nQu' esa niña no te quiere?",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,180,180,"1950","",0,"","","",4,0,0,[],""],["rm_t2-n1951",0,"En el medio de la mar\nHay una lechuga de oro;\nAunque me cueste la vida\nHe de coger el cogollo.",0,0,-1,1,"",0,4,"oo",-1,0,-1,0,180,180,"1951","",0,"","","",3,0,0,[],""],["rm_t2-n1952",0,"Aunque te vuelvas culebra,\nY te vayas á la mar,\nY te entierres en la arena,\nContigo me he de casar.",0,0,-1,1,"",0,4,"a",21,0,-1,0,180,180,"1952","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1953",0,"La perla no está segura\nEn lo jondito der má;\nTú qu' estás sobre la playa,\n¿Cómo te podrás librar?",0,0,-1,1,"",0,4,"a",-1,0,-1,0,180,180,"1953","",0,"","","",1,0,0,[],""],["rm_t2-n1954",0,"No te ha valer ermita,\nNi parroquia ni convento:\nMe has de querer á la fuerza,\nO has de vivir con tormento.",0,0,-1,1,"",0,4,"eo",94,0,-1,0,181,181,"1954","",0,"","","",1,0,0,[],""],["rm_t2-n1955",0,"Por fuerza me has de querer;\nPor justicia me has de amar;\nCariño me has de tener,\nO el diablo te ha de llevar.",0,0,-1,1,"",1,4,"a",21,0,-1,0,181,181,"1955","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n1956",0,"Yo corriendo y tú corriendo,\nBeremos cuál es más firme;\nYo como sol á buscarte,\nTú como sombra ájuirme.",0,0,-1,1,"",5,4,"ae",-1,0,-1,0,181,181,"1956","",0,"","","",1,0,0,[],""],["rm_t2-n1958",0,"Si yo supiera de cierto\nDe que usté no me queria,\nMe retirara á un desierto\nComo Santa Rosalía\n[A llorar mi sentimiento].",0,0,-1,1,"",7,5,"eo",-1,0,-1,0,181,181,"1958","",0,"","","",4,0,0,[],""],["rm_t2-n1959",0,"Por Dios, ni en chanzas ni en véras\nMe digas que no me quieres;\nNo me pongas de manera\nQue hasta del cielo reniegue.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,181,181,"1959","",0,"","","",1,0,0,[],""],["rm_t2-n1960",0,"Si yo lo supiera\nQue no me querias,\nYo renegara - e Dios y me fuera\nA la morería.",0,0,-1,1,"",3,4,"ia",-1,0,-1,0,181,181,"1960","",0,"","","",1,0,0,[],""],["rm_t2-n1961",0,"Yo soy serraniyo puro\nY en mí no cabe mardá;\nYo t' estoy queriendo á tí\nSin sabé tu boluntá.",0,0,-1,1,"",0,4,"a",9,0,-1,0,182,182,"1961","",0,"","","",1,0,0,[],""],["rm_t2-n1962",0,"La pena d' un siego es grande,\nQue no be por dónde ba;\nPero más grande es la mia,\nQue no sé tu boluntá.",0,0,-1,1,"",0,4,"a",9,0,-1,0,182,182,"1962","",0,"","","",1,0,0,[],""],["rm_t2-n1964",0,"A una niña estoy queriendo\nY ella me paga muy mal;\nQue paso muchas duquitas,\nNo me quiere consolar.",0,0,-1,1,"",0,4,"a",-1,0,-1,0,182,182,"1964","",0,"","","",1,0,0,[],""],["rm_t2-n1965",0,"Si aquel que más te estima\nTe mereciera,\nEl dichoso entre tantos\nYo solo fuera.\nPero es lo cierto\nQue el que más lo merece\nConsigue ménos.",0,0,-1,1,"",4,7,"eo",-1,0,-1,0,182,182,"1965","",0,"","","",1,0,0,[],""],["rm_t2-n1966",0,"Sin duda hallarás muchos\nQue más te gusten;\nPero quien más te adore,\nEso es embuste.\nBien que tú quieres\nAmar al que te gusta\nMás que al que debes.",0,0,-1,1,"",4,7,"ee",-1,0,-1,0,182,182,"1966","",0,"","","",1,0,0,[],""],["rm_t2-n1967",0,"Yo bien sé que tú quieres\nA quien te engaña,\nY no á mí, que te llevo\nSiempre en el alma.\nMas me consuela\nQue no has de encontrar nunca\nQuien más te quiera.",0,0,-1,1,"",4,7,"ea",-1,0,-1,0,183,183,"1967","",0,"","","",1,0,0,[],""],["rm_t2-n1968",0,"Las estrellitas del cielo\nCada cual tiene su nombre;\nLa mia se llama Rita,\nLa llamo y no me responde.",0,0,-1,1,"",0,4,"oe",-1,0,-1,0,183,183,"1968","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",25,0,0,[],""],["rm_t2-n1969",0,"Hace más de siete meses\nQue te quiero con fatigas\nY tú no me correspondes,\nPorque piensas que es mentira.",0,0,-1,1,"",0,4,"ia",-1,0,-1,0,183,183,"1969","",0,"","","",1,0,0,[],""],["rm_t2-n1970",0,"¡Bárgame Dios de los sielos,\nQué penosiyo es mi má!\nT' estoy queriendo á montones,\nY tú no me quieres nâ.",0,0,-1,1,"",5,4,"",-1,0,-1,0,183,183,"1970","",0,"","","",3,0,0,[],""],["rm_t2-n1971",0,"Estoy pasando más penas\nQue San Juan er de la Isla (?)\nPor una cara morena\nY no pueo conseguirla.",0,0,-1,1,"",0,4,"ia",-1,0,-1,0,183,183,"1971","",0,"","","",4,0,0,[],""],["rm_t2-n1972",0,"Morenita de mi vida,\nYa no puedo con más penas;\nSi tú no me las alivias,\nTengo de morir con ellas.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,183,183,"1972","",0,"","","",1,0,0,[],""],["rm_t2-n1974",0,"¿No te da pena er sabé\nQué poco m' ocupa er sueño,\nQu' están mis ojos yorando\nMientras los tuyos durmiendo?",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,184,184,"1974","",0,"","","",1,0,0,[],""],["rm_t2-n1977",0,"Las piedras duras quebranto,\nA los álamos blandeo,\nA las fieras muebo á yanto,\nY á tí, serrana, no pueo\n[Acarrearte á mis brasos].",0,0,-1,1,"",7,5,"ao",-1,0,-1,0,184,184,"1977","",0,"","","",2,0,0,[],""],["rm_t2-n1978",0,"Aunque tú no me quieras,\nTengo el consuelo\nDe saber que tú sabes\nQue yo te quiero.",0,0,-1,1,"",6,4,"eo",-1,0,-1,0,184,184,"1978","",0,"carrizo_salta, palau_cantares, fernan_caballero","","",7,0,0,[],""],["rm_t2-n1979",0,"Me tienes aborrecía\nPorque sigo tu amistá;\nSólo porque esa es la tema,\nTe tengo de querer más.",0,0,-1,1,"",0,4,"a",-1,0,-1,0,184,184,"1979","",0,"","","",1,0,0,[],""],["rm_t2-n1980",0,"Haré por tí una fineza,\nLa que tú por mí no harás:\nQuererte aunque no me quieras;\n¿Qué más quieres? ¿Quieres más?",0,0,-1,1,"",0,4,"a",51,0,-1,0,185,185,"1980","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n1981",0,"Por vida de las estrellas ss\nQue están en el cielo azul,\nQue te tengo de querer,\nAunque no me quieras tú.",0,0,-1,1,"",0,4,"u",-1,0,-1,0,185,185,"1981","",0,"","","",1,0,0,[],""],["rm_t2-n1982",0,"Con un pié en la sepurtura\nY otro en la mismita bera\nYo te tengo de queré,\nAunque tú á mí no me quieras.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,185,185,"1982","",0,"","","",1,0,0,[],""],["rm_t2-n1983",0,"A la mar fuí por naranjas,\nCosa que la mar no tiene;\nMetí la mano en el agua:\nLa esperanza me mantiene.",0,0,-1,1,"",0,4,"ee",70,0,-1,0,185,185,"1983","",0,"leonesas_diez","","",7,0,0,[],""],["rm_t2-n1984",0,"Aunque me digas que nó,\nA tu casa siempre acudo;\nQue al cabo saca limosna\nEl pobre que es importuno.",0,0,-1,1,"",0,4,"uo",-1,0,-1,0,185,185,"1984","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1986",0,"Puse pleito en quererte\nDel cielo arriba\nY del pleito ha salido\nQue siga, siga.\n¡Siga, sigamos!\n¡Sigamos con el pleito,\nQue lo ganamos!",0,0,-1,1,"",4,7,"ao",116,0,-1,0,186,186,"1986","",0,"","","",1,0,0,[],""],["rm_t2-n1987",0,"De cien dificultades\nQue el amor tiene\nYa llevo yo vencidas\nNoventa y nueve.\nUna me falta,\nY esa espero vencerla\nCon la constancia.",0,0,-1,1,"",4,7,"aa",-1,0,-1,0,186,186,"1987","",0,"","","",1,0,0,[],""],["rm_t2-n1988",0,"Ya se acabaron las chanzas\nY entra la formalidad;\nSi me quieres, yo te quiero;\nVamos á ver la verdad.",0,0,-1,1,"",0,4,"a",16,0,-1,0,186,186,"1988","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n1989",0,"A mí me gusta, me gusta,\nA mí me gusta ná más,\nA mí me gusta, me gusta\nUn hombre que sea formal.",0,0,-1,1,"",0,4,"a",-1,0,-1,0,186,186,"1989","",0,"","","",2,0,0,[],""],["rm_t2-n1990",0,"Mañana á la misma hora\nPásese usté por aquí,\nQue á mí me cuesta vergüenza\nDecir tan pronto que sí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,186,186,"1990","",0,"","","",2,0,0,[],""],["rm_t2-n1991",0,"Amor, si tú fueras firme\nComo la palma en verano,\nYo te entregara las llaves\nDe mi pecho soberano.",0,0,-1,1,"",0,4,"ao",81,0,-1,0,187,187,"1991","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1992",0,"Serás dueña de mi vida,\nSi sabes corresponder;\nSólo sien to tu mudanza,\nPorque al fin eres mujer.",0,0,-1,1,"",0,4,"e",20,0,-1,0,187,187,"1992","",0,"","","",2,0,0,[],""],["rm_t2-n1993",0,"Supongo que tú me quieres;\nSiempre constante serás;\nDios nos libre de una vieja\nQue nos comience á enredar.",0,0,-1,1,"",0,4,"a",-1,0,-1,0,187,187,"1993","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n1994",0,"Mi corazon se dirige\nSolamente á benerarte\nY si tú me quieres firme,\nYo jamás podré orbiarte.",0,0,-1,1,"",0,4,"ae",8,0,-1,0,187,187,"1994","",0,"","","",1,0,0,[],""],["rm_t2-n1995",0,"Yo te querré, dueño mio,\nSi son ciertas tus palabras;\nPero si has de ser ingrato,\nPrepárame la mortaja.",0,0,-1,1,"",0,4,"aa",-1,0,-1,0,187,187,"1995","",0,"","","",1,0,0,[],""],["rm_t2-n1996",0,"Enamorado de mí\nNo dudo que lo estarás;\nMas tambien habrás notado\nQue sigo tu boluntá.",0,0,-1,1,"",0,4,"a",-1,0,-1,0,187,187,"1996","",0,"","","",1,0,0,[],""],["rm_t2-n1997",0,"Siempre me ha gustado á mí\nPlaticar con quien me entiende,\nOlvidar á quien me olvida\nY querer á quien me quiere.",0,0,-1,1,"",0,4,"ee",-1,0,-1,0,187,187,"1997","",0,"","","",1,0,0,[],""],["rm_t2-n1998",0,"Dentro de mi corazon\nTengo yo una pasionera,\nPara tenerle pasion\nA aquel que por mí la tenga.",0,0,-1,1,"",0,4,"ea",-1,0,-1,0,188,188,"1998","",0,"","","",7,0,0,[],""],["rm_t2-n2000",0,"¡Válgame Dios! ¿No conoces\nQue en tí tengo mi amor puesto?\n¡Válgame Dios, y qué falto\nEres de conocimiento!",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,188,188,"2000","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2001",0,"Si yo misma no me entiendo,\n¿Quién me ha de entender á mí,\nQue digo que no te quiero\nY estoy loquita por tí?",0,0,-1,1,"",0,4,"i",23,0,-1,0,188,188,"2001","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n2002",0,"Entra corriendo y no temas,\nEntra y díselo á mi madre,\nQue no te dirá que nó;\nQue mi corazon lo sabe.",0,0,-1,1,"",0,4,"ae",-1,0,-1,0,188,188,"2002","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2003",0,"A tu madre se lo dije;\nA tu padre no me atrevo;\nEn sabiéndolo tu madre,\nTu padre lo sabrá luégo.",0,0,-1,1,"",0,4,"eo",-1,0,-1,0,188,188,"2003","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2004",0,"Se lo dije á tu madre;\nDijo:—Veremos.—\nLa respuesta no es mala;\nBoda tendremos.\nAnde usté, ande,\nQue la misericordia\nDe Dios es grande.",0,0,-1,1,"",4,7,"ae",117,0,-1,0,188,189,"2004","",0,"","","",2,0,0,[],""],["rm_t2-n2005",0,"—¿Hay quien nos escuche?—Nó.\n—¿Quieres que te diga?—Dí.\n—¿Tienes otro amante?—Nó.\n—¿Quieres que lo sea?—Sí.",0,0,-1,1,"",1,4,"i",23,0,-1,0,189,189,"2005","",0,"","","",1,0,0,[],""],["rm_t2-n2006",0,"Hasta la última gota\nDe sangre diera por tí,\nSólo porque te mantengas\nSiempre diciendo que sí.",0,0,-1,1,"",0,4,"i",23,0,-1,0,189,189,"2006","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2007",0,"¡Salero, que me mirastes!\n¡Salero, que te miré!\n¡Salero, que me gustastes!\n¡Salero, que te gusté!",0,0,-1,1,"",1,4,"e",77,0,-1,0,189,189,"2007","",0,"","","",1,0,0,[],""],["rm_t2-n2008",0,"Canta tú y cantaré yo,\nPajarito en rama verde;\nCanta tú y cantaré yo:\nCante quien amores tiene.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,210,210,"2008","",0,"","","",6,0,0,[],""],["rm_t2-n2009",0,"Un pajarito volando\nLleva en el pico un letrero,\nCon letras de oro que dicen:\n«Soy del amor prisionero.»",0,0,-1,2,"",0,4,"eo",38,0,-1,0,210,210,"2009","",0,"","","",1,0,0,[],""],["rm_t2-n2010",0,"Tengo yo unos amores\nNuevos de ahora,\nCortados de la pieza\nDe última moda.",0,0,-1,2,"",6,4,"oa",-1,0,-1,0,210,210,"2010","",0,"","","",1,0,0,[],""],["rm_t2-n2011",0,"Amores, amores tengo;\nNo los quisiera tener;\nQue un hombre se pone tonto\nEn queriendo á una mujer.",0,0,-1,2,"",0,4,"e",20,0,-1,0,210,210,"2011","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t2-n2012",0,"Er queré quita er sentío\nY borra 'l entendimiento;\nBalentías jase un hombre\nCon sujetarse á sí mesmo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,210,210,"2012","",0,"","","",2,0,0,[],""],["rm_t2-n2014",0,"Quisiera una cadena;\nPero reparo\nQue los presos de amores\nNo están atados.",0,0,-1,2,"",6,4,"ao",-1,0,-1,0,211,211,"2014","",0,"","","",1,0,0,[],""],["rm_t2-n2015",0,"He estado en el purgatorio\nY he visto lo que son penas;\nY he visto que por querer\nNingun alma se condena.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,211,211,"2015","",0,"","","",5,0,0,[],""],["rm_t2-n2016",0,"En el pozo más hondo\nDe mi corazon\nSembré una pasionera,\nCogí una pasion.\nQue las pasiones\nPor algun tiempo alegran\nLos corazones.",0,0,-1,2,"",4,7,"oe",34,0,-1,0,211,211,"2016","",0,"","","",1,0,0,[],""],["rm_t2-n2017",0,"Yo sembré una mirada,\nNació un deseo,\nFloreció un desengaño,\nCogí un afecto.\n¡Feliz quien siembra,\nSi al fin de sus afanes\nTiene cosecha!",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,211,212,"2017","",0,"","","",3,0,0,[],""],["rm_t2-n2018",0,"Yo llegué á los umbrales\nDe un amor fino\nY ántes que entrara dentro,\nMe hallé rendido.",0,0,-1,2,"",6,4,"io",-1,0,-1,0,212,212,"2018","",0,"","","",1,0,0,[],""],["rm_t2-n2019",0,"Un incendio amoroso\nMi pecho abrasa;\n¡Ojalá yo pudiera\nEcharle agua!",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,212,212,"2019","",0,"","","",2,0,0,[],""],["rm_t2-n2020",0,"Raises como 'l olibo\nBa criando mi queré;\nMás raises tiene ahora\nQue cuando lo prinsipié.",0,0,-1,2,"",0,4,"e",77,0,-1,0,212,212,"2020","",0,"","","",1,0,0,[],""],["rm_t2-n2021",0,"Apénas nasía\nLa yerbita-güena,\nComo se iban - alimen tandito\nLas raises d' eya.",0,0,-1,2,"",3,4,"ea",-1,0,-1,0,212,212,"2021","",0,"","","",1,0,0,[],""],["rm_t2-n2022",0,"Fuentecilla cristalina,\nArroyuelo caudaloso;\nPara dos que bien se quieren,\nCaminos largos son cortos.",0,0,-1,2,"",0,4,"oo",-1,0,-1,0,212,212,"2022","",0,"","","",3,0,0,[],""],["rm_t2-n2023",0,"—Corason enamorado,\nDime, ¿quién t' enamoró?\n—Una muchacha d' á quinse,\nQu' á diesiseis no yegó.",0,0,-1,2,"",0,4,"o",2,0,-1,0,212,212,"2023","",0,"","","",1,0,0,[],""],["rm_t2-n2024",0,"—¿Dime, rosita de Mayo,\n¿Quién t' ha robado er coló?\n—Un sordado d' á cabayo\nCon palabritas d' amó.",0,0,-1,2,"",1,4,"o",2,0,-1,0,212,212,"2024","",0,"","","",1,0,0,[],""],["rm_t2-n2025",0,"Ya no se usa desí\n«Te matara y te enterrara;»\nQue lo que se usa ahora:\n«¡Dame tu sangre salada!»",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,213,213,"2025","",0,"","","",1,0,0,[],""],["rm_t2-n2026",0,"Ya no se estila decir:\n«Viva el oro, viva el oro;»\nQue sólo se dice ahora:\n«¡Viva la prenda que adoro!»",0,0,-1,2,"",0,4,"oo",85,0,-1,0,213,213,"2026","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n2027",0,"En la escalera la ví\nUna tarde que bajaba;\nYo le dije: -Adios, mi vida, -\nY ella dijo: -Adios, mi alma.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,213,213,"2027","",0,"","","",1,0,0,[],""],["rm_t2-n2028",0,"En el rio la encontré\nAsentadita en la arena;\nElla no me dijo nada;\nYo le dije: -Abur, morena.",0,0,-1,2,"",0,4,"ea",59,0,-1,0,213,213,"2028","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2029",0,"Una mora me enamora\nY no es mora de nacion;\nQue es mora porque ella mora\nDentro de mi corazon.",0,0,-1,2,"",1,4,"ao",31,0,-1,0,213,213,"2029","",0,"","","",8,0,0,[],""],["rm_t2-n2030",0,"Mi padre se habrá creido\nQue estoy predicando en Roma\nY estoy queriendo á una niña\nMás blanca que una paloma.",0,0,-1,2,"",0,4,"oa",86,0,-1,0,213,213,"2030","",0,"","","",1,0,0,[],""],["rm_t2-n2031",0,"Mi madre piensa que estoy\nEstudiando en Salamanca\nY estoy queriendo á una niña\nComo la nieve de blanca.",0,0,-1,2,"",0,4,"aa",75,0,-1,0,213,213,"2031","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2032",0,"Digo que no hay en el mundo\nHombre que mi gustó tenga;\nQue estoy queriendo á una niña\nMás chiquita que una almendra.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,214,214,"2032","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2033",0,"Una zarza me prendió;\nUna zarza chiquitita;\nNo hay cosita que más prenda\nQue una muchacha bonita.",0,0,-1,2,"",0,4,"ia",50,0,-1,0,214,214,"2033","",0,"","","",1,0,0,[],""],["rm_t2-n2034",0,"Las estrellas he contado,\nPor ver la que á mí me sigue;\nA mí me sigue una estrella\nChiquitita, pero firme.",0,0,-1,2,"",0,4,"ie",-1,0,-1,0,214,214,"2034","",0,"","","",5,0,0,[],""],["rm_t2-n2035",0,"Santa Teresita tiene\nLa paloma en el oído,\nY yo quisiera tener\nDe mi amante el apellido.",0,0,-1,2,"",0,4,"io",101,0,-1,0,214,214,"2035","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2037",0,"Tengo yo un amiguito\nTan de mi gusto,\nQue de mi pecho al suyo\nNo hay nada oculto.\nEntra en mi casa\nY se sien ta y le cu en to\nLo que me pasa.",0,0,-1,2,"",4,7,"aa",123,0,-1,0,214,214,"2037","",0,"","","",1,0,0,[],""],["rm_t2-n2038",0,"Míralo por dónde viene,\nTodo lleno de alegría;\nAunque es moreno de cara,\nLe quiero más que á mi vida.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,215,215,"2038","",0,"","","",1,0,0,[],""],["rm_t2-n2039",0,"Por la caye abajito\nBa quien yo quiero;\nNo le beo la cara,\nCon er sombrero.",0,0,-1,2,"",6,4,"eo",38,0,-1,0,215,215,"2039","",0,"","","",1,0,0,[],""],["rm_t2-n2040",0,"¿Es mi amante buen mozo,\nÓ es pasion mia?\nUn desapasionado\nQue me lo diga.\nQue las pasiones\nSuelen ablandar mucho\nLos corazones.",0,0,-1,2,"",4,7,"oe",34,0,-1,0,215,215,"2040","",0,"","","",1,0,0,[],""],["rm_t2-n2041",0,"Tengo mi querer puesto\nEn un muchacho\nDelgado de cintura,\nMoreno y alto.\nY así lo quiero:\nDelgado de cintura,\nAlto y moreno.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,215,215,"2041","",0,"","","",1,0,0,[],""],["rm_t2-n2042",0,"Aunque soy morenita,\nMi amor me quiere\nLo mismo que si fuera\nComo la nieve.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,215,215,"2042","",0,"","","",2,0,0,[],""],["rm_t2-n2043",0,"Todos me dicen que tengo\nOjitos de religiosa\nY yo digo que los tengo\nDe casada cariñosa.",0,0,-1,2,"",1,4,"oa",63,0,-1,0,215,216,"2043","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2044",0,"Una rubia como tú\nY de tu propio salero\nMe tiene robada el alma\nY el corazon prisionero.",0,0,-1,2,"",0,4,"eo",38,0,-1,0,216,216,"2044","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2045",0,"Todas las morenas son\nDulces como el caramelo\nY yo, como soy goloso,\nPor una morena muero.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,216,216,"2045","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2046",0,"Yo estoy queriendo á una vieja....\nDe catorce ó quince años,\nO aunque tenga un año más,\nQue en eso yo no reparo.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,216,216,"2046","",0,"","","",1,0,0,[],""],["rm_t2-n2047",0,"Una morena me mata,\nUna rubia me hace el hoyo\nY una muchacha de á quince\nMe saca del purgatorio.",0,0,-1,2,"",0,4,"oo",-1,0,-1,0,216,216,"2047","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2048",0,"De lo que viste la noche\nViste la prenda que estimo;\nLa noche viste de negro\nY mi prenda de lo mismo.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,216,216,"2048","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2049",0,"De las aves que vuelan\nMe gusta el cuervo,\nPorque el bien de mi vida\nViste de negro.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,216,216,"2049","",0,"","","",2,0,0,[],""],["rm_t2-n2050",0,"Una corona me ponen\nDe plata sobredorada\nCuando me dicen que estoy\nDe mi amante apasionada.",0,0,-1,2,"",0,4,"aa",49,0,-1,0,216,216,"2050","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2051",0,"Mi amor me dice de usté\nY yo lo mismo le digo;\nY en estando los dos solos,\nDe tú por tú nos decimos.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,217,217,"2051","",0,"","","",1,0,0,[],""],["rm_t2-n2052",0,"Cuando voy á la casa\nDe mi María,\nSe me hace cuesta abajo\nLa cuesta arriba.\nY cuando salgo,\nSe me hace cuesta arriba\nLa cuesta abajo.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,217,217,"2052","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t2-n2054",0,"Cuando veo á mi suegra,\n¡Me alegro tanto...!\nCuando el altar me alegra,\n¿Qué será el santo?",0,0,-1,2,"",6,4,"ao",30,0,-1,0,217,217,"2054","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t2-n2055",0,"A San Nicolás me voy,\nDe San Nicolás me vengo,\nDe pedirle al santo mio\nPor una novia que tengo.",0,0,-1,2,"",0,4,"eo",124,0,-1,0,217,217,"2055","",0,"","","",3,0,0,[],""],["rm_t2-n2056",0,"La noche que tronó tanto\nMe fuí en busca de mi novia,\nPor si se acababa el mundo,\nIrme arrimando á la gloria.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,217,217,"2056","",0,"","","",3,0,0,[],""],["rm_t2-n2057",0,"Marinero es mi amante,\nDe agua salada;\nPorque los de agua dulce\nNo valen nada.",0,0,-1,2,"",6,4,"aa",49,0,-1,0,217,218,"2057","",0,"palau_cantares, fernan_caballero","","",6,0,0,[],""],["rm_t2-n2058",0,"Un carpintero me quiere,\nUn sastre me solicita\nY un marinero ha de ser\nDueño de mi personita.",0,0,-1,2,"",0,4,"ia",50,0,-1,0,218,218,"2058","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2059",0,"Un marinerito, madre,\nMe tiene robada el alma;\nSi no me caso con él,\nMuero moza y llevo palma.",0,0,-1,2,"",0,4,"aa",125,0,-1,0,218,218,"2059","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n2060",0,"Labrador es mi amante;\nLabra en papeles;\nQue es oficio pesado\nLabrar con bueyes.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,218,218,"2060","",0,"","","",1,0,0,[],""],["rm_t2-n2061",0,"Mi amante es cartujano,\nPintor de losa,\nQue pinta palanganas\nColor de rosa.\nAsí lo quiero:\nQue pinte palanganas\nColor de sielo.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,218,218,"2061","",0,"","","",1,0,0,[],""],["rm_t2-n2062",0,"Estudiante del alma,\nEstudia, estudia,\nQue en llegando á mayores\nToda soy tuya.",0,0,-1,2,"",6,4,"ua",-1,0,-1,0,218,218,"2062","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2063",0,"Soldadito lo quiero,\nAunque supiera\nQue la noche de novios\nSe marcha fuera.\nQue el del soldado\nEs el amor más dulce\nQue yo he probado.",0,0,-1,2,"",4,7,"ao",14,0,-1,0,218,219,"2063","",0,"","","",1,0,0,[],""],["rm_t2-n2064",0,"Mi amante es alto y delgado,\nGasta corbatin al cuello;\nEs soldado de á caballo:\n¡Esa es la pena que tengo!",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,219,219,"2064","",0,"","","",2,0,0,[],""],["rm_t2-n2065",0,"Carrero como er mio\nNo entra en Torrijos;\nQue ha subido la cuesta,\nNos' ha caido.\n¡Biba mi carro!\nQue ha subido la cuesta,\nNos' ha trepado.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,219,219,"2065","",0,"","","",1,0,0,[],""],["rm_t2-n2066",0,"San Antonio lleva el Niño,\nSanto Domingo la estrella,\nSan José la vara hermosa....\nEntiéndame quien me entienda,",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,219,219,"2066","",0,"","","",4,0,0,[],""],["rm_t2-n2067",0,"San Cristobal lleva el pino\nY San Rafael el pez;\nSan Antonio lleva el Niño\nY la vara San José.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,219,219,"2067","",0,"","","",1,0,0,[],""],["rm_t2-n2069",0,"A San Antonio le rezo\nTres dias en la semana;\nSi algun santo tiene envidia,\nLe rezo á quien me da gana.",0,0,-1,2,"",0,4,"aa",4,0,-1,0,220,220,"2069","",0,"","","",1,0,0,[],""],["rm_t2-n2070",0,"Todas las mozuelas tienen\nSanto de su devocion\nY yo tengo al Patriarca,\nSanto de mi corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,220,220,"2070","",0,"","","",1,0,0,[],""],["rm_t2-n2071",0,"Todos los santos me gustan\nY en particular aquel\nQue está en el altar mayor\nY en la mano tiene un pez.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,220,220,"2071","",0,"","","",1,0,0,[],""],["rm_t2-n2072",0,"A todos los santos quiero\nY en particular á tres:\nSan Antonio, San Francisco\nY el patriarca José.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,220,220,"2072","",0,"","","",3,0,0,[],""],["rm_t2-n2073",0,"A todos los santos quiero\nY en particular á uno:\nAl que floreció la vara\nA vista de todo el mundo.",0,0,-1,2,"",0,4,"uo",-1,0,-1,0,220,220,"2073","",0,"","","",3,0,0,[],""],["rm_t2-n2074",0,"A todos los santos quiero\nY al tuyo más que á ninguno,\nPorque tiene cinco llagas\nA vista de todo el mundo.",0,0,-1,2,"",0,4,"uo",-1,0,-1,0,220,220,"2074","",0,"","","",3,0,0,[],""],["rm_t2-n2075",0,"De los árboles frutales,\nNinguno como el peral;\nY de los santos del cielo,\nNinguno como San Juan.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,220,220,"2075","",0,"","","",1,0,0,[],""],["rm_t2-n2077",0,"Si quereis saber, señores,\nEl nombre de mi querido,\nAcordarse de aquel santo\nQue tiene un ramo florido.",0,0,-1,2,"",0,4,"io",101,0,-1,0,221,221,"2077","",0,"","","",9,0,0,[],""],["rm_t2-n2078",0,"Si quereis saber, señores,\nEl nombre de mi querer,\nAcordarse de aquel santo\nQue tiene al diablo á sus piés.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,221,221,"2078","",0,"","","",9,0,0,[],""],["rm_t2-n2080",0,"La vara de San José\nSiempre la llevo á mi lado,\nPorque se llama José\nMi querido enamorado.",0,0,-1,2,"",1,4,"ao",14,0,-1,0,221,221,"2080","",0,"","","",5,0,0,[],""],["rm_t2-n2081",0,"Mucho quiero á San Vicente,\nPorque es patron de Valencia;\nPero más te quiero á tí,\nPorque te llamas Vicenta.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,221,221,"2081","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2082",0,"Mucho quiero á San Francisco,\nPorque tiene cinco llagas;\nPero más quiero á aquel santo\nQue con el dedo señala.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,221,221,"2082","",0,"","","",5,0,0,[],""],["rm_t2-n2083",0,"Hágam' usté un San Juaquin\nQue sea de plata fina,\nPorque la prenda que adoro\nTambien se llama Juaquina.",0,0,-1,2,"",0,4,"ia",11,0,-1,0,222,222,"2083","",0,"","","",1,0,0,[],""],["rm_t2-n2084",0,"Un San Antonio de plata\nTengo de mandar hacer;\nCon una devocion santa\nAl cuello me lo echaré\n[Porque Antoñito te llamas].",0,0,-1,2,"",7,5,"aa",-1,0,-1,0,222,222,"2084","",0,"","","",2,0,0,[],""],["rm_t2-n2085",0,"La estampa de San Antonio\nSiempre la traigo en el pecho;\nCuando me acuerdo de Antonio\nSaco la estampa y la beso.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,222,222,"2085","",0,"","","",3,0,0,[],""],["rm_t2-n2087",0,"Cada vez que digo ramo\nSe me alegra el corazon,\nPorque Ramona se llama\nLa prenda que adoro yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,222,222,"2087","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2088",0,"Cada vez que miento á Francia\nHasta el alma se me alegra,\nPorque de Francia á Francisco\nVa muy poca diferencia.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,222,222,"2088","",0,"","","",1,0,0,[],""],["rm_t2-n2089",0,"San Antonio er de Jeré\nTiene los ojitos tristes\nY tú, Antoñito del arma,\nEr corason me partistes.",0,0,-1,2,"",0,4,"ie",91,0,-1,0,222,222,"2089","",0,"","","",1,0,0,[],""],["rm_t2-n2090",0,"San Francisco, por humilde,\nTiene su cuerpo llagado,\nY tú me tienes á mí\nEl corazon traspasado.",0,0,-1,2,"",0,4,"ao",14,0,-1,0,223,223,"2090","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t2-n2091",0,"Si viniera San Francisco\nA pedirme el corazon,\nAl santo se lo negara\nY á uno de su nombre nó.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,223,223,"2091","",0,"","","",3,0,0,[],""],["rm_t2-n2092",0,"A San José pido el ramo,\nA San Francisco el cordon,\nA Santa Rita la espina\nY á mi amante el corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,223,223,"2092","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2093",0,"San Antonio está en el cielo;\nEso no lo ignoro yo;\nY tambien está en la tierra\nLa Antonia que adoro yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,223,223,"2093","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t2-n2094",0,"Por un Juan diera un ochavo,\nPor un Francisco un doblon\nY por un Antonio diera\nAlma, vida y corazon.",0,0,-1,2,"",5,4,"ao",31,0,-1,0,223,223,"2094","",0,"","","",1,0,0,[],""],["rm_t2-n2095",0,"En el lado derecho\nDe mi corpiño\nTengo un Juan, un Antonio\nY un Joseíto.\nY al otro lado\nTengo un Francisco muerto,\nCiego y vendado.",0,0,-1,2,"",4,7,"ao",14,0,-1,0,223,223,"2095","",0,"","","",2,0,0,[],""],["rm_t2-n2096",0,"Tengo un Francisco en el alma,\nY en el corazon un Juan,\nY en la garganta un Antonio\nQue no lo puedo tragar.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,224,224,"2096","",0,"","","",1,0,0,[],""],["rm_t2-n2097",0,"Los ojos de un Juan me matan,\nLos de un Francisco me hieren,\nLos de un Diego me aprisionan\nY muero por los de un Pepe.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,224,224,"2097","",0,"","","",1,0,0,[],""],["rm_t2-n2098",0,"Un Juanito es la hebilla\nDe mi zapato,\nUn Pepe los ribetes,\nManuel el lazo.\nDigo y repito\nQue el lazo del zapato\nEs Manolito.",0,0,-1,2,"",4,7,"io",119,0,-1,0,224,224,"2098","",0,"","","",1,0,0,[],""],["rm_t2-n2099",0,"Una rosa tengo en agua\nY otra tengo en el rosal;\nUna se la doy á Antonio\nY otra se la doy á Juan.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,224,224,"2099","",0,"","","",3,0,0,[],""],["rm_t2-n2100",0,"Catalina me prendió,\nAna me echó la cadena,\nMaría me la quitó;\n¡Viva su cara morena!",0,0,-1,2,"",1,4,"ea",59,0,-1,0,224,224,"2100","",0,"","","",1,0,0,[],""],["rm_t2-n2101",0,"Juan se llamaba mi aman te;\nSe me volvieron las tornas;\nAhora se llama José\nEl que tengo en la memoria.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,224,224,"2101","",0,"","","",1,0,0,[],""],["rm_t2-n2102",0,"Mi padre dice que Antonio\nY mi madre que José;\nY este geniecillo mio\nDice que ha de ser Manuel.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,225,225,"2102","",0,"","","",1,0,0,[],""],["rm_t2-n2103",0,"El agua para ser buena,\nHa de salir de la pita;\nY la mujer para el hombre\nSe ha de llamar Carmelita.",0,0,-1,2,"",0,4,"ia",50,0,-1,0,225,225,"2103","",0,"","","",2,0,0,[],""],["rm_t2-n2104",0,"El agua para ser buena,\nHa de salir del peñon;\nY la mujer para el hombre\nSe ha de llamar Asuncion.",0,0,-1,2,"",5,4,"uo",31,0,-1,0,225,225,"2104","",0,"","","",2,0,0,[],""],["rm_t2-n2105",0,"La uva para ser buena,\nHa de ser la moscatel;\nY la mujer para el hombre\nSe ha de llamar Isabel.",0,0,-1,2,"",0,4,"e",32,0,-1,0,225,225,"2105","",0,"","","",1,0,0,[],""],["rm_t2-n2107",0,"A un Antoñito en mi pecho\nLo tengo tan retratado,\nQue por más agua que bebo,\nNo lo puedo ver borrado.",0,0,-1,2,"",0,4,"ao",14,0,-1,0,225,225,"2107","",0,"","","",1,0,0,[],""],["rm_t2-n2108",0,"El retrato de Juana\nTengo en mi cuarto\nY por eso me acuerdo\nDe Juana tanto.",0,0,-1,2,"",6,4,"ao",-1,0,-1,0,226,226,"2108","",0,"","","",1,0,0,[],""],["rm_t2-n2109",0,"Juan se llama mi amante,\nNombre de bobo;\nYo me llamo María:\nLo tapo todo.",0,0,-1,2,"",6,4,"oo",-1,0,-1,0,226,226,"2109","",0,"","","",1,0,0,[],""],["rm_t2-n2110",0,"Toda la calle viene\nLlena de Juanes;\nComo no viene el mio,\nNo viene nádie.",0,0,-1,2,"",6,4,"ae",-1,0,-1,0,226,226,"2110","",0,"","","",1,0,0,[],""],["rm_t2-n2111",0,"Las vecinas y comadres\nSe juntan á murmurar;\nQue se las come la envidia,\nDe ver que me quiere Juan.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,226,226,"2111","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2112",0,"Bendita sea la madre\nQue te echó al mundo\nY el cura que en la pila\nTe puso Curro.\nQue te dió leche\nY el cura que en la pila\nTe puso Pepe.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,226,226,"2112","",0,"","","",5,0,0,[],""],["rm_t2-n2113",0,"Tienes el nombre á mi gusto;\nLas condiciones tambien;\nBendito aquel que te puso\nEn el bautismo Manuel.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,226,226,"2113","",0,"","","",2,0,0,[],""],["rm_t2-n2114",0,"He pasado más penas\nPor los Manueles\nQue el Cristo de Torrijos\nMilagros tiene.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,227,227,"2114","",0,"","","",1,0,0,[],""],["rm_t2-n2115",0,"Todos los Pepes son santos\nY los demás pecadores:\n¡Qué dicha será la mia!\n¡Qué santos son mis amores!",0,0,-1,2,"",0,4,"oe",5,0,-1,0,227,227,"2115","",0,"","","",1,0,0,[],""],["rm_t2-n2116",0,"En un Juan puse los ojos\nY los puse tan de véras,\nQue si Juan me pide el alma,\nYo creo que se la diera.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,227,227,"2116","",0,"","","",1,0,0,[],""],["rm_t2-n2117",0,"Esta mañana temprano\nA la huerta fuí por flores;\nMe hice el entretenido,\nPara hablar con mi Dolores.",0,0,-1,2,"",0,4,"oe",5,0,-1,0,227,227,"2117","",0,"","","",4,0,0,[],""],["rm_t2-n2118",0,"Mi corazon se perdió\nEn un vallado de flores;\nLa dama que se lo halló\nTiene por nombre Dolores.",0,0,-1,2,"",1,4,"oe",5,0,-1,0,227,227,"2118","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2119",0,"Tomaré una calavera\nY un Santo Cristo de estambre\nY me iré á hacer penitencia\nCon Mariquita del Cármen.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,227,227,"2119","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n2120",0,"Tú te llamas Antonia\nY yo Antoñito;\n¡Mira qué matrimonio\nTan igualito!",0,0,-1,2,"",6,4,"io",119,0,-1,0,227,227,"2120","",0,"","","",1,0,0,[],""],["rm_t2-n2121",0,"Por la calle abajo vengo\nRodando como melon,\nSólo por llegará verte,\nAngustias del corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,228,228,"2121","",0,"","","",4,0,0,[],""],["rm_t2-n2122",0,"San Antonio lleve á Antonio\nY Antonio me lleve á mí;\nQue yo muero por Antonio\nY Antonio muere por mí.",0,0,-1,2,"",1,4,"i",-1,0,-1,0,228,228,"2122","",0,"","","",1,0,0,[],""],["rm_t2-n2123",0,"De San Antonio vengo,\nAntonia mia;\nSólo de ver tu santo\nTengo alegría.",0,0,-1,2,"",6,4,"ia",0,0,-1,0,228,228,"2123","",0,"","","",2,0,0,[],""],["rm_t2-n2124",0,"La sirena de la mar\nEmbelesa á quien la oye;\nAsí me embelesa á mí,\nMaría, tu dulce nombre.",0,0,-1,2,"",0,4,"oe",-1,0,-1,0,228,228,"2124","",0,"","","",7,0,0,[],""],["rm_t2-n2125",0,"Me enamoré jugando\nDe una María;\nCuando quise olvidarla,\nYa no podia.",0,0,-1,2,"",6,4,"oa",0,0,-1,0,228,228,"2125","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t2-n2126",0,"Por una Pepita muero,\nPepita y nó de melon;\nQue es Pepita que yo tengo\nDentro de mi corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,228,228,"2126","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n2127",0,"Pepe quiero, Pepe adoro,\nPepe tengo en la memoria;\nCada vez que digo Pepe,\nParece que digo: ¡Gloria!",0,0,-1,2,"",0,4,"oa",126,0,-1,0,228,228,"2127","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2128",0,"La cartilla del amor\nLa pasé con eficacia\nY en el último renglon\nMe quedé diciendo:-¡Gracia!",0,0,-1,2,"",0,4,"aa",121,0,-1,0,229,229,"2128","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2129",0,"La cartilla del amor\nLa pasé letra por letra\nY así que llegué á la P,\nMe quedé diciendo:-¡Pepa,\n[Pepa, por tí moriré]!",0,0,-1,2,"",7,5,"e",-1,0,-1,0,229,229,"2129","",0,"","","",5,0,0,[],""],["rm_t2-n2130",0,"Cinco letras circundan\nA mi corazon\nY en ellas leo el nombre\nDe mi dulce amor.\n¡Dulce letrero!\n¡Qué de penas me quita\nCuando lo leo!",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,229,229,"2130","",0,"","","",1,0,0,[],""],["rm_t2-n2131",0,"El nombre de mi dama\nTres letras tiene:\nEnmedio de dos aes\nTiene una N.",0,0,-1,2,"",6,4,"",-1,0,-1,0,229,229,"2131","",0,"","","",1,0,0,[],""],["rm_t2-n2132",0,"Cuatro nombres con R\nTiene mi dama:\nRosales, Rosalía,\nRosa y Rosaura.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,229,229,"2132","",0,"","","",3,0,0,[],""],["rm_t2-n2133",0,"Pasionera, pasionera,\nDisimula tu pasion,\nComo yo la disimulo\nDentro de mi corazon.",0,0,-1,2,"",0,4,"ao",31,0,-1,0,229,229,"2133","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2134",0,"Por Dios, que disimules\nLo que me quieres;\nQue tú no logras nada\nY á mí me pierdes.\nPorque estas cosas\nEn ser comunes pierden\nEl ser preciosas.",0,0,-1,2,"",4,7,"oa",61,0,-1,0,230,230,"2134","",0,"preciso_coleccion, palau_cantares","","",3,0,0,[],""],["rm_t2-n2135",0,"Disimula, bien mio,\nSi es que me estimas;\nQue nos siguen á entrambos\nCelos y envidia.\nSólo te pido\nQue de este disimulo\nNo nazca olvido.",0,0,-1,2,"",4,7,"io",101,0,-1,0,230,230,"2135","",0,"","","",1,0,0,[],""],["rm_t2-n2136",0,"Campanita e plata,\nMira que no quiero\nEr que se sepa, compañera mia,\nLo que mos queremos.",0,0,-1,2,"",3,4,"eo",-1,0,-1,0,230,230,"2136","",0,"","","",1,0,0,[],""],["rm_t2-n2137",0,"Retírate, que la gente\nNo conozca nuestro amor;\nMientras más léjos el santo,\nMás cérca la devocion.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,230,230,"2137","",0,"","","",1,0,0,[],""],["rm_t2-n2138",0,"Mariquita, María,\nFlor de romero,\nNo le digas á nádie\nQue yo te quiero.\nDe romero flor,\nNo le digas á nádie\nQue te quiero yo.",0,0,-1,2,"",4,7,"o",-1,0,-1,0,230,230,"2138","",0,"","","",12,0,0,[],""],["rm_t2-n2139",0,"No le digas á tu madre\nQue nosotros nos queremos;\nQue se lo diga el demonio,\nCuando se vaya al infierno.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,231,231,"2139","",0,"","","",1,0,0,[],""],["rm_t2-n2140",0,"Mariquita, si me quieres,\nNo se lo digas á nádie;\nMete la mano en tu pecho;\nDile al corazon que calle.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,231,231,"2140","",0,"","","",1,0,0,[],""],["rm_t2-n2141",0,"María, si bien me quieres,\nNo se lo digas al cura;\nQue los secretos de amor\nSon para la sepultura.",0,0,-1,2,"",0,4,"ua",17,0,-1,0,231,231,"2141","",0,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["rm_t2-n2142",0,"Cuando voy á confesar,\nTodos mis pecados digo;\nPero no le digo al padre\nLo que tengo yo contigo.",0,0,-1,2,"",0,4,"io",106,0,-1,0,231,231,"2142","",0,"","","",1,0,0,[],""],["rm_t2-n2144",0,"Delante de las gentes,\nPor Dios te ruego\nQue tengas en mirarme\nMás miramiento.\nPues no quisiera\nQue aquello que ocultamos\nSe descubriera.",0,0,-1,2,"",4,7,"ea",44,0,-1,0,231,231,"2144","",0,"","","",1,0,0,[],""],["rm_t2-n2145",0,"No me mires, que miran\nQue nos miramos;\nMiremos la manera\nDe no mirarnos.\nNo nos miremos\nY cuando no nos miren,\nNos miraremos.",0,0,-1,2,"",4,7,"eo",127,0,-1,0,231,232,"2145","",0,"palau_cantares, suspiros_amor","","",6,0,0,[],""],["rm_t2-n2146",0,"No me mires con ánsia\nDonde hay peligro;\nQue no conozca nádie\nNuestro cariño.\nDonde haya gente;\nQue no conozca nádie\nNuestro deleite.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,232,232,"2146","",0,"","","",2,0,0,[],""],["rm_t2-n2147",0,"No me mires con ánsia\nDonde haya niños,\nQue será descubierto\nNuestro cariño.\nEsos extremos\nGuárdalos para cuando\nSolos estemos.",0,0,-1,2,"",4,7,"eo",127,0,-1,0,232,232,"2147","",0,"","","",2,0,0,[],""],["rm_t2-n2148",0,"Con los ojos del alma\nTe estoy mirando\nY con los de la cara\nDisimulando.\nQue este es el modo\nDe que nuestro cariño\nSe oculte á todos.",0,0,-1,2,"",4,7,"oo",-1,0,-1,0,232,232,"2148","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n2149",0,"Si te preguntan, niña,\nA quién adoras,\nPrimero morir mártir\nQue confesora.\nQue el que confiesa\nTiene siempre segura\nLa penitencia.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,232,233,"2149","",0,"fernan_caballero, suspiros_amor","","",3,0,0,[],""],["rm_t2-n2150",0,"Si en tu casa te regañan,\nDí á voces que no me quieres;\nCon esto quedarás bien\nY háblame cuando pudieres.",0,0,-1,2,"",0,4,"ee",55,0,-1,0,233,233,"2150","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2151",0,"Si tu madre te regaña\nPorque me piensas querer,\nDile que ya no me quieres,\nY con eso quedas bien.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,233,233,"2151","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2152",0,"Si tu madre te pregunta\nQue si me quieres á mí,\nDí con la boca que nó,\nCon el corazon que sí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,233,233,"2152","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2153",0,"En mi casa me dicen\nQue si te quiero;\nYo digo que ni verte....\n¡Cuando no puedo!",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,233,233,"2153","",0,"palau_cantares","","",11,0,0,[],""],["rm_t2-n2154",0,"En mi casa me dicen\nQue si te quiero;\nLa mentira la digo,\nLa verdad niego.\nY si me aprietan,\nQue te requiero digo,\nAunque lo sientan.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,233,233,"2154","",0,"","","",11,0,0,[],""],["rm_t2-n2155",0,"Me dicen que si te quiero\nY yo digo que ni verte;\nEs menester disimulo,\nPor el hablar de las gentes.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,233,234,"2155","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2156",0,"Si mi madre supiera\nQue te queria,\n¡Qué vida tan amarga\nFuera la mia!",0,0,-1,2,"",6,4,"a",0,0,-1,0,234,234,"2156","",0,"","","",1,0,0,[],""],["rm_t2-n2157",0,"Mucho te quiero callando\nY tu callar agradezco;\nQue para un firme querer\nNo hay cosa como el silencio.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,234,234,"2157","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2158",0,"El nombre de mi moreno\nEso no lo diré yo,\nPorque no quiero que sepan\nDónde tengo mi aficion.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,234,234,"2158","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2159",0,"Enamoradita estoy,\nPero no lo sabe nádie:\nTengo el amor forastero\nY no me ronda la calle.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,234,234,"2159","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2160",0,"Aunque para mí no seas,\nSiempre te tendré aficion,\nPorque eres disimulada\nCuando llega la ocasion.",0,0,-1,2,"",0,4,"o",31,0,-1,0,234,234,"2160","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2161",0,"Dicen que no nos queremos,\nPorque no nos ven hablar;\nA tu corazon y al mio\nSe lo pueden preguntar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,234,234,"2161","",0,"lafuente_madrid, murciano_antiguo, barcenas_marinera, palau_cantares","","",11,0,0,[],""],["rm_t2-n2162",0,"Dicen que no nos queremos,\nPorque no nos visitamos;\nLas visitas son de noche\nPara los enamorados.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,235,235,"2162","",0,"palau_cantares, lafuente_madrid","","",11,0,0,[],""],["rm_t2-n2163",0,"A mí me llaman silencio\nY el silencio es lo que vale:\nAnoche estuve en tu puerta\nY no me sintió tu madre.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,235,235,"2163","",0,"","","",3,0,0,[],""],["rm_t2-n2164",0,"Principio principiando;\nPrincipiar quiero,\nPor ver si principiando\nPrincipiar puedo.\nNiña querida,\nDoy principio, y te quiero\nMás que á mi vida.",0,0,-1,2,"",4,7,"ia",37,0,-1,0,235,235,"2164","",0,"","","",2,0,0,[],""],["rm_t2-n2165",0,"Bendita sea la hora\nQue yo te empecé á querer,\nBendito tu padre y madre\nY bendita tú tambien.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,235,235,"2165","",0,"","","",3,0,0,[],""],["rm_t2-n2166",0,"Benditos los nueve meses\nQue estuvistes encerrado\nEn el vientre de tu madre,\nPara ser mi enamorado.",0,0,-1,2,"",0,4,"ao",14,0,-1,0,235,235,"2166","",0,"","","",3,0,0,[],""],["rm_t2-n2167",0,"Benditos los nueve meses\nQue estuvistes, que estuvistes\nEn el vientre de tu madre,\nPara consolar á un triste.",0,0,-1,2,"",0,4,"ie",-1,0,-1,0,235,235,"2167","",0,"","","",3,0,0,[],""],["rm_t2-n2168",0,"La primer marimoñita\nQue eche mi marimoñero\nSe la tengo de poner\nA Antoñito en el sombrero.",0,0,-1,2,"",0,4,"eo",38,0,-1,0,236,236,"2168","",0,"","","",1,0,0,[],""],["rm_t2-n2169",0,"En los jardines del conde\nDe una maceta cogí\nUn clavel para mi amante\nY una rosa para mí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,236,236,"2169","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2170",0,"De un peral peralito\nCogí tres peras:\nUna le dí á mi aman te,\nDos á mi suegra.\nPorque mi amante,\nComo es tan chiquitito,\nTiene bastante.",0,0,-1,2,"",4,7,"ae",47,0,-1,0,236,236,"2170","",0,"","","",1,0,0,[],""],["rm_t2-n2171",0,"En el patio de mi casa\nHe de poner unjardin\nCon mil flores diferentes,\nPara divertirte á tí.",0,0,-1,2,"",5,4,"i",-1,0,-1,0,236,236,"2171","",0,"","","",8,0,0,[],""],["rm_t2-n2172",0,"Galan, si vienes á verme,\nVén el domingo en la tarde;\nSólo porque te diviertas,\nTengo de formar un baile.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,236,236,"2172","",0,"","","",1,0,0,[],""],["rm_t2-n2173",0,"En tu puerta sembré un guindo\nY en tu bentana un perá,\nPâ que cuando t' alebantes\nComas guindas, pera y pan.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,236,236,"2173","",0,"","","",2,0,0,[],""],["rm_t2-n2174",0,"Desde tu puerta á l' ilesia\nTengo de poné un rosá,\nPâ que cuando bas á misa\nTengas rosas que cortá.",0,0,-1,2,"",0,4,"a",9,0,-1,0,237,237,"2174","",0,"","","",3,0,0,[],""],["rm_t2-n2175",0,"Desde tu puerta á l' ilesia\nTengo de poné un armendro,\nPâ que cuando baya' á misa\nNo te dé 'r só en er pelo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,237,237,"2175","",0,"","","",3,0,0,[],""],["rm_t2-n2176",0,"Desde tu puerta á l' ilesia\nTengo de poné una parra,\nPâ que cuando baya' á misa\nNo te dé 'r só en la cara.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,237,237,"2176","",0,"","","",3,0,0,[],""],["rm_t2-n2177",0,"Tengo que empedrar tu calle\nCon realillos de á ocho cuartos,\nPara que vayas á misa\nSin romperte los zapatos.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,237,237,"2177","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2178",0,"Esa calle en que vives,\nSi fuera mia,\nDe perlas y brillantes\nLa empedraria.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,237,237,"2178","",0,"","","",1,0,0,[],""],["rm_t2-n2179",0,"En la esquina de esta calle\nHe de poner un farol,\nPara que encienda el cigarro\nEl bien de mi corazon.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,237,237,"2179","",0,"","","",1,0,0,[],""],["rm_t2-n2180",0,"Si supiera que eras diosa\nY que estabas endiosada,\nTe mandara hacer un templo\nY como á Dios te adorara.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,237,237,"2180","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2183",0,"Amores he tenido\nY amores tengo;\nA ninguno he querido\nY á tí te quiero.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,238,238,"2183","",0,"","","",2,0,0,[],""],["rm_t2-n2184",0,"Amores si quisiera\nTengo á manojos;\nPero en tí, vida mia,\nPuse los ojos.",0,0,-1,2,"",6,4,"oo",99,0,-1,0,238,238,"2184","",0,"murciano_antiguo","","",2,0,0,[],""],["rm_t2-n2185",0,"Mi navío y tu galera\nSe encontraron en el mar\nY así que se divisaron\nSe hicieron salva rëal.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,238,238,"2185","",0,"","","",1,0,0,[],""],["rm_t2-n2186",0,"No tienes tú la culpa,\nNi yo te culpo,\nDe que Dios te haya hecho\nTan de mi gusto.",0,0,-1,2,"",6,4,"uo",-1,0,-1,0,238,238,"2186","",0,"palau_cantares, barcenas_marinera","","",4,0,0,[],""],["rm_t2-n2187",0,"Hermanitos terceros\nSon los claveles:\nUn clavel fué la causa\nDe yo quererte.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,238,238,"2187","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2188",0,"Yo no sabia querer,\nDueño de mi corazon,\nY contigo me enseñé;\nYa te puedo dar leccion.",0,0,-1,2,"",0,4,"o",31,0,-1,0,239,239,"2188","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2189",0,"Cupido me enseñó á amar,\nYo como niño aprendí;\nCupido fué mi maestro,\nYo su discípulo fuí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,239,239,"2189","",0,"","","",1,0,0,[],""],["rm_t2-n2190",0,"En la escuela de amores\nDiscípulo fuí;\nLa leccion de adorarte\nFué la que aprendí.\nSalí tan diestro,\nQue lecciones le daba\nA mi maestro.",0,0,-1,2,"",4,7,"eo",128,0,-1,0,239,239,"2190","",0,"","","",3,0,0,[],""],["rm_t2-n2191",0,"En la escuela de Cupido\nTengo de tomar leccion,\nPor ver si encuentro en el mundo\nQuien te quiera más que yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,239,239,"2191","",0,"","","",1,0,0,[],""],["rm_t2-n2192",0,"Me llevaste de la mano\nA la escuela del amor\nY el corazon me robaste\nEn la primera leccion.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,239,239,"2192","",0,"","","",1,0,0,[],""],["rm_t2-n2193",0,"En la escuela de Vénus\nEntré yo un dia\nY ví á mi amor leyendo\nFilosofía.\nYo tambien quiero\nPonerme en esa escuela,\nPor ver si aprendo.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,239,240,"2193","",0,"","","",1,0,0,[],""],["rm_t2-n2194",0,"—Dame una leccioncita\nDe tus quereres,\nQue se me va olvidando\nCómo se quiere.\n—Eso es mentira;\nQue lo que bien se aprende\nNunca se olvida.",0,0,-1,2,"",4,7,"ia",-1,0,-1,0,240,240,"2194","",0,"","","",1,0,0,[],""],["rm_t2-n2195",0,"Fuiste mi primer amor;\nTú me enseñaste á querer;\nNo me enseñes á olvidar,\nQue no lo quiero aprender.",0,0,-1,2,"",0,4,"e",20,0,-1,0,240,240,"2195","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],""],["rm_t2-n2196",0,"Todo el saber del mundo\nQue yo tuviera,\nQueriendo como quiero,\nNo me valiera.\nQueriendo tanto,\nDíganme los que quieren:\n¿Habrá hombre sabio?",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,240,240,"2196","",0,"","","",1,0,0,[],""],["rm_t2-n2197",0,"Ni la cencia ni er sabé\nM' ha serbiito de nâ;\nQue m' ha puesto tu queré\nSujeto á tu boluntá.",0,0,-1,2,"",5,4,"a",-1,0,-1,0,240,240,"2197","",0,"","","",1,0,0,[],""],["rm_t2-n2198",0,"No sé qué estrella es la tuya,\nQue domina sobre mí;\nA nádie me he sujetado\nY ahora me sujeto á tí.",0,0,-1,2,"",3,4,"i",23,0,-1,0,240,240,"2198","",0,"","","",3,0,0,[],""],["rm_t2-n2199",0,"Yo no sé lo que l' ha dao\nEsta chiquiya á mi cuerpo,\nQue jago por orbiarla\nY más presente la tengo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,241,241,"2199","",0,"","","",1,0,0,[],""],["rm_t2-n2200",0,"Yo no sé lo que me has dado\nPara que tanto te quiera,\nQue me has hecho que me olvide\nDe mi familia y mi tierra.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,241,241,"2200","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2201",0,"¡Mar fin tengas! ¿Qué m' has dao\nPâ que yo tanto te quiera,\nQue m' has jecho aborresé\nAr que queria de béras?",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,241,241,"2201","",0,"","","",1,0,0,[],""],["rm_t2-n2202",0,"Yo no sé lo que m' has dao;\nTú m' has quitao er sentío;\nYo he procuraito orbiarte,\nFlamenquiya, y no he poío.",0,0,-1,2,"",0,4,"io",3,0,-1,0,241,241,"2202","",0,"","","",2,0,0,[],""],["rm_t2-n2203",0,"Yo no sé lo que m' has dao,\nQue no te pueo orbiá;\nParese que m' has tocao\nCon la piedresiya iman.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,241,241,"2203","",0,"","","",2,0,0,[],""],["rm_t2-n2204",0,"Todo cuanto tú querias,\nChiquiya, te se logró;\nDime á qué santo le resas,\nQue tanto arcansas con Dios.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,241,241,"2204","",0,"","","",1,0,0,[],""],["rm_t2-n2205",0,"Cuando pasé por Argel\nLos moros me cautivaron\nY ahora me cautivas tú,\nPara vivir siempre esclavo.",0,0,-1,2,"",3,4,"ao",-1,0,-1,0,241,241,"2205","",0,"","","",1,0,0,[],""],["rm_t2-n2206",0,"De amor en las cadenas\nGimo y suspiro;\nPero sus duros hierros\nBeso y bendigo.\nQue estas cadenas,\nPorque tú me las pones\nMe son ligeras.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,242,242,"2206","",0,"","","",1,0,0,[],""],["rm_t2-n2207",0,"Si supiera que en el mundo\nSe vendian corazones,\nFuera yo y comprara uno,\nPorque el mio está en prisiones.",0,0,-1,2,"",0,4,"oe",34,0,-1,0,242,242,"2207","",0,"","","",3,0,0,[],""],["rm_t2-n2208",0,"Estoy en cautiverio\nComo paloma,\nY tú con tu piquito\nMe das que coma.",0,0,-1,2,"",6,4,"oa",86,0,-1,0,242,242,"2208","",0,"","","",1,0,0,[],""],["rm_t2-n2209",0,"Dame con tu boquita\nDe lo que comes,\nComo las palomitas\nA sus pichones.",0,0,-1,2,"",6,4,"oe",-1,0,-1,0,242,242,"2209","",0,"","","",1,0,0,[],""],["rm_t2-n2210",0,"La voluntad no es mía,\nPues nádie ignora\nQue un cautivo no tiene\nVoluntad propia.",0,0,-1,2,"",6,4,"oa",-1,0,-1,0,242,242,"2210","",0,"","","",1,0,0,[],""],["rm_t2-n2211",0,"Sin voluntad me tienes\nNi entendimiento;\nLlévate la memoria,\nQue es mi tormento.\nPues si me dejas,\n¿De qué sirve acordarme\nDe tus finezas?",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,242,243,"2211","",0,"","","",2,0,0,[],""],["rm_t2-n2212",0,"De todas las potencias\nHay una sola\nQue no me hayas robado,\nY es la memoria.\nMucho la estimo,\nPorque vivo por ella\nSiempre contigo.",0,0,-1,2,"",4,7,"io",-1,0,-1,0,243,243,"2212","",0,"","","",1,0,0,[],""],["rm_t2-n2213",0,"La otra noche en la ventana\nCinco claveles te dí\nY eran los cinco sentidos,\nSerrana, que puse en tí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,243,243,"2213","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2214",0,"Dicen que lo que es bueno\nCuesta un sentido;\n¿Qué serás tú, que cuestas\nTodos los mios?\nY es cosa cierta\nQue tú mucho más vales\nDe lo que cuestas.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,243,243,"2214","",0,"","","",1,0,0,[],""],["rm_t2-n2217",0,"Mil vidas que tuviera\nTe diera juntas;\nToma, pues no las tengo,\nMil veces una.\nQue si lo adviertes,\nEs más que mil á un tiempo\nUna mil veces.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,244,244,"2217","",0,"","","",1,0,0,[],""],["rm_t2-n2218",0,"Yo por tí estoy perdido;\nSi tú me encuentras,\nTe daré por hallazgo\nEl alma entera.\nMas ya la tienes\nY dártela no puedo,\nSi no la vuelves.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,244,244,"2218","",0,"","","",1,0,0,[],""],["rm_t2-n2219",0,"Cuerpo que está sin alma\nMuerto ha quedado\nY yo vivo sin ella,\nPues te la he dado.\nSerá, sin duda,\nQue tú la mia tienes\nY yo la tuya.",0,0,-1,2,"",4,7,"ua",-1,0,-1,0,244,244,"2219","",0,"","","",1,0,0,[],""],["rm_t2-n2220",0,"Para los hombres se hizo,\nCeuta, Melilla y Peñon\nY para tí, vida mia,\nSe hizo mi corazon.",0,0,-1,2,"",5,4,"ao",31,0,-1,0,244,244,"2220","",0,"","","",1,0,0,[],""],["rm_t2-n2221",0,"Me mandastes á decir\nQue era tuya el alma mia\nY yo te mandé á decir\nQue era de Dios, tuya y mia.",0,0,-1,2,"",1,4,"a",-1,0,-1,0,245,245,"2221","",0,"","","",4,0,0,[],""],["rm_t2-n2222",0,"Quitarme de que te quiera\nEs quitarme la salú,\nPorque, á la chita callando,\nMi vida la tienes tú.",0,0,-1,2,"",0,4,"u",73,0,-1,0,245,245,"2222","",0,"","","",3,0,0,[],""],["rm_t2-n2223",0,"Mi vida vive tu vida;\nSi esa me falta, me muero;\nEn faltándome tu vida,\nA media vida me quedo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,245,245,"2223","",0,"","","",1,0,0,[],""],["rm_t2-n2224",0,"Vén acá, luz de mi cara;\nVén acá, prenda querida;\nEres clavel encarnado;\nPor tí perderé la vida.",0,0,-1,2,"",0,4,"ia",37,0,-1,0,245,245,"2224","",0,"","","",3,0,0,[],""],["rm_t2-n2225",0,"Al Señor le estoy pidiendo\nTe conserve la salú,\nPorque en teniendo la tuya,\nLa mia la tienes tú.",0,0,-1,2,"",0,4,"u",73,0,-1,0,245,245,"2225","",0,"","","",1,0,0,[],""],["rm_t2-n2227",0,"Mi corazon y el tuyo\nSe han consultado\nY dicen que no pueden\nSer separados.",0,0,-1,2,"",6,4,"ao",-1,0,-1,0,245,245,"2227","",0,"","","",2,0,0,[],""],["rm_t2-n2228",0,"Debajo de las alas\nDe mi corazon\nTe tengo preparada\nUna habitacion.\nY si no cabes,\nTe daré de mi pecho\nTodas las llaves.",0,0,-1,2,"",4,7,"ae",129,0,-1,0,246,246,"2228","",0,"","","",1,0,0,[],""],["rm_t2-n2229",0,"Toma allá mi corazon,\nCon grillos, cadena y llaves;\nÁbrelo y métete dentro,\nPorque tú solito cabes.",0,0,-1,2,"",0,4,"ae",130,0,-1,0,246,246,"2229","",0,"","","",7,0,0,[],""],["rm_t2-n2230",0,"Dentro de mi pecho tengo\nUn cofre con una llave;\nMuchos pretenden abrirlo\nY sólo mi amante cabe.",0,0,-1,2,"",0,4,"ae",131,0,-1,0,246,246,"2230","",0,"lafuente_madrid","","",32,0,0,[],""],["rm_t2-n2231",0,"Desde que te ví te dí\nLa llave de mi pechito;\nMuchos me la pretendieron\nY á tí te la dí solito.",0,0,-1,2,"",0,4,"io",119,0,-1,0,246,246,"2231","",0,"","","",1,0,0,[],""],["rm_t2-n2232",0,"Dentro de mi corazon\nNo puedo admitir á nádie,\nPorque tiene un candadito\nY mi amor tiene la llave.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,246,246,"2232","",0,"","","",7,0,0,[],""],["rm_t2-n2233",0,"Dicen que el águila es\nReina de todas las aves,\nY tú solamente tienes\nDe mi corazon la llave.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,246,246,"2233","",0,"","","",1,0,0,[],""],["rm_t2-n2234",0,"Ya se cerró mi pecho;\nToma la llave\nY hasta que tú no vuelvas,\nYa no se abre.\n¡Qué friolera\nQue mi pecho se abriese\nPara cualquiera!",0,0,-1,2,"",4,7,"ea",44,0,-1,0,247,247,"2234","",0,"","","",1,0,0,[],""],["rm_t2-n2235",0,"Ábreme el pecho y registra\nHasta el último rincon\nY verás como tú reinas\nDonde ninguno reinó.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,247,247,"2235","",0,"","","",1,0,0,[],""],["rm_t2-n2236",0,"Toma esta rosa encarnada\nY ábrela, que está en capullo,\nY verás mi corazon\nEnlazado con el tuyo.",0,0,-1,2,"",0,4,"uo",78,0,-1,0,247,247,"2236","",0,"","","",1,0,0,[],""],["rm_t2-n2237",0,"Toma esta llave dorada\nY abre este fuerte castillo\nY verás mi corazon\nEntre cadenas y grillos.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,247,247,"2237","",0,"","","",1,0,0,[],""],["rm_t2-n2238",0,"Entre grillos y cadenas\nTengo yo mi corazon;\nEntre cadenas y grillos,\nComo si fuera un ladron.",0,0,-1,2,"",0,4,"ao",31,0,-1,0,247,247,"2238","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2239",0,"Ahí tienes mi corazon\nEntre dos flechas metido\nY para mayor dolor,\nEntre cadenas y grillos.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,247,247,"2239","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t2-n2240",0,"Toma este puñal dorado\nY ábreme con él el pecho\nY verás una escritura\nQue mi corazon te ha hecho.",0,0,-1,2,"",0,4,"eo",60,0,-1,0,248,248,"2240","",0,"","","",6,0,0,[],""],["rm_t2-n2241",0,"Toma este puñal dorado\nY ábreme el pecho con él\nY en el color de la sangre\nVerás si te quiero bien.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,248,248,"2241","",0,"","","",6,0,0,[],""],["rm_t2-n2242",0,"Toma este puñal dorado\nY párteme el corazon\nY en el color de la sangre\nVerás si te tengo amor.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,248,248,"2242","",0,"","","",6,0,0,[],""],["rm_t2-n2243",0,"Toma este puñalito\nY ábreme el pecho\nY verás tu retrato\nSi está bien hecho.",0,0,-1,2,"",6,4,"eo",60,0,-1,0,248,248,"2243","",0,"huambachano","","",3,0,0,[],""],["rm_t2-n2244",0,"Tienes dos corazones;\nYo no lo dudo,\nPorque tienes el mio\nDentro del tuyo.",0,0,-1,2,"",6,4,"uo",-1,0,-1,0,248,248,"2244","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2245",0,"Ábreme, niña, el pecho\nCon dos punzones\nY verás como tengo\nDos corazones.\nCon dos agujas\nY verás como tengo\nDos almas puras.",0,0,-1,2,"",4,7,"ua",-1,0,-1,0,248,248,"2245","",0,"","","",1,0,0,[],""],["rm_t2-n2246",0,"Eché un candado en mi pecho\nDesde que ví tu belleza,\nPorque ninguna éntre en él\nSin que tú le des licencia.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,249,249,"2246","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2248",0,"El alma me has robado\nY yo, en castigo,\nTe he metido en la cárcel\nDel pecho mio.\nTen, pues, paciencia,\nPorque no he de soltarte,\nAunque te mueras.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,249,249,"2248","",0,"","","",5,0,0,[],""],["rm_t2-n2249",0,"Mi corazon volando\nSe entró en el tuyo;\nSe quebraron las alas,\nSalir no pudo.\nY está contento:\n¡Como que el pobrecito\nSe halla en su centro!",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,249,249,"2249","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n2250",0,"Mi corazon volando\nSe entró en tu pecho;\nLe cortaron las alas,\nSe quedó dentro.\nQuiérelo mucho,\nYa que volar no puede\nLéjos del tuyo.",0,0,-1,2,"",4,7,"uo",-1,0,-1,0,249,249,"2250","",0,"","","",4,0,0,[],""],["rm_t2-n2251",0,"Del corazon de Pepe\nTengo la llave,\nPor que no se enamore\nPepe de nádie.\n¡Ay, Pepe, Pepe,\nEn lo mejor del alma\nTe tengo siempre!",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,250,250,"2251","",0,"","","",1,0,0,[],""],["rm_t2-n2252",0,"Toma allá mi corazon,\nÉchalo en esa candela,\nMas no agarres las cenizas,\nQue te has de quemar con ellas.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,250,250,"2252","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["rm_t2-n2253",0,"Dentro de mi pecho tengo\nUna sala de cristal\nY una antesala de oro,\nDonde habita esa deidad.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,250,250,"2253","",0,"lafuente_madrid, palau_cantares","","",32,0,0,[],""],["rm_t2-n2254",0,"Dentro de mi pecho tengo\nDos leones con dos lazos\nY están tirando de mí,\nPara llevarme á tus brazos.",0,0,-1,2,"",0,4,"ao",132,0,-1,0,250,250,"2254","",0,"","","",32,0,0,[],""],["rm_t2-n2255",0,"Dentro de mi pechito\nTengo una cuna\nDonde el bien de mi alma\nDuerme y se arrulla.\nY á los vaivenes,\nSe despierta y me dice:\n-Chacha, ¿me quieres?",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,250,250,"2255","",0,"","","",1,0,0,[],""],["rm_t2-n2256",0,"Tengo yo en mi pechito\nPara quien quiero\nUn corazon más dulce\nQue el caramelo.\nY es al contrario:\nQue para quien no quiero\nLo tengo agrio.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,250,251,"2256","",0,"","","",1,0,0,[],""],["rm_t2-n2257",0,"El corazon te daré,\nTambien te daré la vida;\nY el alma no te la doy,\nPorque esa prenda no es mia.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,251,251,"2257","",0,"","","",6,0,0,[],""],["rm_t2-n2258",0,"Si acaso tiras flechas\nContra mi pecho,\nRepara adónde apuntas,\nQue tú estás dentro.\nY si acertares,\nMi corazon hiriendo,\nHieres tu imágen.",0,0,-1,2,"",4,7,"ae",-1,0,-1,0,251,251,"2258","",0,"","","",1,0,0,[],""],["rm_t2-n2259",0,"Por las cinco ventanas\nDe mis sentidos\nTe has entrado en mi pecho\nSin ser sentido.\nQuiero que sepas\nQue salir ya no puedes\nSin que te sienta.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,251,251,"2259","",0,"","","",2,0,0,[],""],["rm_t2-n2260",0,"En el jardin de Vénus\nCanté una cancion\nY por premio me dieron\nUn fiel corazon.\nAprende tú á dar:\nQue de uno que me dieron\nTe doy la mitad.",0,0,-1,2,"",4,7,"a",-1,0,-1,0,251,251,"2260","",0,"","","",1,0,0,[],""],["rm_t2-n2262",0,"Si la sangre se vendiera,\nFueras tú rica y yo pobre,\nPorque tienes en tus venas\nLa que á mí me corresponde.",0,0,-1,2,"",0,4,"oe",-1,0,-1,0,252,252,"2262","",0,"","","",1,0,0,[],""],["rm_t2-n2263",0,"Si me miraras por dentro,\nMe bieras er corason;\nDe tanto como te quiero,\nNo tiene parpitasion.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,252,252,"2263","",0,"","","",1,0,0,[],""],["rm_t2-n2264",0,"Ardiéndose estaba Troya,\nTorres, murayas y armenas;\nEr fuego d' amor m' abrasa,\nQue quema más que candela.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,252,252,"2264","",0,"","","",1,0,0,[],""],["rm_t2-n2265",0,"Es mi pecho constante\nTroya abrasada,\nQue causó su ruïna\nUna mirada.\nY experimento\nQue de una sola chispa\nNace el incendio.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,252,252,"2265","",0,"","","",1,0,0,[],""],["rm_t2-n2266",0,"Es natural que al fuego\nLo apague el agua;\nEn mi pecho sucede\nPor la contraria.\nPues no han logrado\nLágrimas de mis ojos\nVerle apagado.",0,0,-1,2,"",4,7,"ao",14,0,-1,0,252,252,"2266","",0,"","","",1,0,0,[],""],["rm_t2-n2268",0,"La luna solitaria\nBrilla en el cielo,\nComo de amor la llama\nArde en mi pecho.\nLa diferencia\nEs que la luna pasa\nY el amor queda.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,253,253,"2268","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2269",0,"La luna buscaba al sol\nTres horas ántes del dia,\nComo yo te busco á tí,\nPrincipio y fin de mi vida.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,253,253,"2269","",0,"","","",1,0,0,[],""],["rm_t2-n2271",0,"Desde aquel feliz instante\nQue alma y vida te rendí,\nHice voto de adorarte\nY no adorar más que á tí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,253,253,"2271","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2272",0,"María, paloma mia,\nLas palomas son del rey\nY tú, paloma, eres mia,\nPorque lo manda la ley.",0,0,-1,2,"",1,4,"e",133,0,-1,0,253,253,"2272","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t2-n2273",0,"Hermoso clabé rosado\nCogido con er rosío,\nEsos labios de tu boca,\nNo son tuyos, que son mios.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,253,254,"2273","",0,"","","",1,0,0,[],""],["rm_t2-n2274",0,"En un sarsá me metí,\nTodo me yené d' espinas;\nMu mal herido salí\nPor tu queré, rosa fina.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,254,254,"2274","",0,"","","",1,0,0,[],""],["rm_t2-n2275",0,"Tú eres palma y yo soy dátil,\nTú eres zarza y yo me enredo;\nTú eres la rosa fragante\nDel jardin de mi recreo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,254,254,"2275","",0,"","","",1,0,0,[],""],["rm_t2-n2276",0,"María, tú eres la yedra\nY el álamo blanco yo;\nY si la yedra se enreda,\nPreso el álamo quedó.",0,0,-1,2,"",0,4,"o",2,0,-1,0,254,254,"2276","",0,"","","",1,0,0,[],""],["rm_t2-n2277",0,"Por tí me muero de amor,\nPor tí deliro y suspiro,\nPor tí se abrasa mi pecho,\nPor tí muero y por tí vivo.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,254,254,"2277","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2278",0,"Para rey nació Dabí,\nPara sabio Salomon,\nPara yorar Jeremías\nY para quererte yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,254,254,"2278","",0,"","","",1,0,0,[],""],["rm_t2-n2279",0,"Eres para mí el reposo,\nEres para mí el recreo,\nEres clavel oloroso,\nEres el bien que poseo.",0,0,-1,2,"",1,4,"eo",66,0,-1,0,254,254,"2279","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2281",0,"Cuando me dijeron que era\nTrabajo en balde el quererte\nMe pareció que llegaba\nEl tránsito de mi muerte.",0,0,-1,2,"",0,4,"ee",134,0,-1,0,255,255,"2281","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2282",0,"Eres palomita blanca\nY yo palomito asú;\nJuntaremos los piquitos,\nCantaremos currucú.",0,0,-1,2,"",0,4,"u",73,0,-1,0,255,255,"2282","",0,"","","",2,0,0,[],""],["rm_t2-n2283",0,"Las cortinas de tu cama\nSon de seda y algodon\nY entre cortina y cortina\nDescansa mi corazon.",0,0,-1,2,"",3,4,"ao",31,0,-1,0,255,255,"2283","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2284",0,"Santo Domingo nació\nCon una estrella en la frente\nY yo he nacido, morena,\nCon la estrella de quererte.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,255,255,"2284","",0,"","","",1,0,0,[],""],["rm_t2-n2285",0,"Las estrellas en el cielo\nLe están alumbrando á Dios\nY tú, como eres mi estrella,\nAlumbras mi corazon.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,255,255,"2285","",0,"","","",18,0,0,[],""],["rm_t2-n2286",0,"De la uba sale 'r bino,\nDel' asituna 'l aseite\nY de mi pechito sale\nResura para quererte.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,255,255,"2286","",0,"","","",1,0,0,[],""],["rm_t2-n2287",0,"Como la campana tiene\nFundíos siete metales,\nAsí tengo tu cariño\nEn la masa de la sangre.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,256,256,"2287","",0,"","","",4,0,0,[],""],["rm_t2-n2288",0,"La fundacion del querer\nMe pueden á mí llamar,\nPorque he sido en tus amores\nLa piedra fundamental.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,256,256,"2288","",0,"","","",6,0,0,[],""],["rm_t2-n2289",0,"La piedra fundamental\nFuí á mi casa y la yebé\nY por eso á mí me yaman\nLa fundasion der queré.",0,0,-1,2,"",3,4,"e",77,0,-1,0,256,256,"2289","",0,"","","",1,0,0,[],""],["rm_t2-n2290",0,"A la mar van á parar,\nMaría, todos los rios\nY allí se irán á juntar\nTus amores y los mios.",0,0,-1,2,"",1,4,"o",135,0,-1,0,256,256,"2290","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2291",0,"Soy peñasco, soy risco,\nSoy dura piedra;\nPara todos soy bronce;\nPara tí cera.",0,0,-1,2,"",6,4,"ea",-1,0,-1,0,256,256,"2291","",0,"palau_cantares, frenk_t1, preciso_coleccion","","",4,0,0,[],""],["rm_t2-n2292",0,"Un limon me tirastes\nDesde la torre;\nEn el alma me distes,\nSangre me corre.",0,0,-1,2,"",6,4,"oe",136,0,-1,0,256,256,"2292","",0,"","","",1,0,0,[],""],["rm_t2-n2293",0,"De tu ventana á la mia\nMe tirastes un limon;\nEl limon cayó en el suelo\nY el agrio en mi corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,256,256,"2293","",0,"","","",10,0,0,[],""],["rm_t2-n2295",0,"Eres el arco íris\nDe mis pesares,\nCon el cual se remedian\nTodos mis males.",0,0,-1,2,"",6,4,"ae",-1,0,-1,0,257,257,"2295","",0,"","","",2,0,0,[],""],["rm_t2-n2296",0,"Es tu pecho la plana\nDonde yo escribo\nLas horas y minutos\nQue hablo contigo.",0,0,-1,2,"",6,4,"io",-1,0,-1,0,257,257,"2296","",0,"","","",1,0,0,[],""],["rm_t2-n2297",0,"A Sevilla me llevan\nPor los cabellos;\nSevillano del alma,\nTírame de ellos.",0,0,-1,2,"",6,4,"eo",137,0,-1,0,257,257,"2297","",0,"","","",1,0,0,[],""],["rm_t2-n2298",0,"Dame la mano, niña,\nDame la mano;\nSubiremos la cuesta\nDel avellano.",0,0,-1,2,"",6,4,"ao",81,0,-1,0,257,257,"2298","",0,"leonesas_diez","","",3,0,0,[],""],["rm_t2-n2299",0,"Dame de tu cabeza\nSiquiera un pelo,\nPara atarme una herida\nQue Amor me ha hecho.\nPero es locura,\nPues más ha de inflamarse\nCon la atadura.",0,0,-1,2,"",4,7,"ua",17,0,-1,0,257,257,"2299","",0,"","","",2,0,0,[],""],["rm_t2-n2300",0,"Mi corazon y el tuyo\nEstán enfermos;\nProcura, dueño mio,\nQue los curemos.\nQue es gran locura\nQue estén los dos enfermos,\nHabiendo cura.",0,0,-1,2,"",4,7,"ua",17,0,-1,0,257,258,"2300","",0,"","","",2,0,0,[],""],["rm_t2-n2301",0,"Al pozo voy por agua;\nSoga no llevo;\nDame, Pepe, la cinta\nDe tu sombrero.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,258,258,"2301","",0,"","","",1,0,0,[],""],["rm_t2-n2302",0,"Ar pilá de Barberde\nBoy á dar agua,\nPâ hacé una paraíta\nCon mi serrana.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,258,258,"2302","",0,"","","",1,0,0,[],""],["rm_t2-n2303",0,"Tú, cogiendo asituna;\nYo, bareando;\nE ramito en ramito\nTe boy mirando.",0,0,-1,2,"",6,4,"ao",33,0,-1,0,258,258,"2303","",0,"","","",1,0,0,[],""],["rm_t2-n2304",0,"Estando en la ventana,\nMe dijo un galan:\n-Águila real hermosa,\n¿Cuándo volarás?-\nYo le respondí:\n-Cuando tú, vida mia,\nMe saques de aquí.",0,0,-1,2,"",4,7,"i",23,0,-1,0,258,258,"2304","",0,"","","",1,0,0,[],""],["rm_t2-n2305",0,"Mi amante es un cobarde,\nQue no se atrebe\nA sacarme de noche\nPor las paderes.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,258,258,"2305","",0,"","","",2,0,0,[],""],["rm_t2-n2306",0,"Te quiero porque has dado\nDe puñaladas;\nQue de ningun cobarde\nS' ha escrito nada.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,259,259,"2306","",0,"","","",2,0,0,[],""],["rm_t2-n2307",0,"Mi amor de una quimera\nSe salió huyendo;\nAmor, no seas cobarde;\nMétete enmedio.\nAnda y no temas;\nQue aquí tienes los brazos\nDe tu morena.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,259,259,"2307","",0,"","","",1,0,0,[],""],["rm_t2-n2308",0,"Esta noche es la noche\nDel desafío;\nQuiera Dios que mi amante\nNo salga herido.",0,0,-1,2,"",6,4,"io",-1,0,-1,0,259,259,"2308","",0,"","","",3,0,0,[],""],["rm_t2-n2309",0,"Esta noche es la noche\nDel desafío;\nYa veremos si vence\nTu amor al mio.\nSi lo venciere,\nHarás de mi persona\nLo que quisieres.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,259,259,"2309","",0,"","","",3,0,0,[],""],["rm_t2-n2310",0,"Una niña en su patio\nComiendo estaba\nY por señas le dije\nQue si me daba.\nY me respondió\nQue bajara y comiera\nDe su corazon.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,259,259,"2310","",0,"","","",1,0,0,[],""],["rm_t2-n2311",0,"Cierta dama soñando\nAsí decia:\n—¿Dónde estará el amante\nDel alma mia?\nDespierta, dueño,\nQue te estoy adorando\nHasta en el sueño.",0,0,-1,2,"",4,7,"eo",138,0,-1,0,260,260,"2311","",0,"","","",1,0,0,[],""],["rm_t2-n2313",0,"Mi moreno me ayudó\nA subir los escalones;\nVale más mi morenito\nQue el oro en las ocasiones.",0,0,-1,2,"",0,4,"oe",34,0,-1,0,260,260,"2313","",0,"","","",1,0,0,[],""],["rm_t2-n2314",0,"¡Mira con qué disimulo\nTe bas por la caye arriba,\nSin repará que te dejas\nA una serrana cautiba!",0,0,-1,2,"",0,4,"ia",140,0,-1,0,260,260,"2314","",0,"","","",3,0,0,[],""],["rm_t2-n2315",0,"Como barquiyo 'n er má,\nQue ba pegando baibenes,\nAsí está mi corason\nCuando te yamo y no bienes.",0,0,-1,2,"",0,4,"ee",120,0,-1,0,260,260,"2315","",0,"","","",1,0,0,[],""],["rm_t2-n2316",0,"María del alma mia,\nTu rosario es mi cordon\nY tu pecho el oratorio\nDonde hago yo mi oracion.",0,0,-1,2,"",0,4,"o",31,0,-1,0,260,260,"2316","",0,"","","",6,0,0,[],""],["rm_t2-n2317",0,"Quisiera que mis voces\nFueran campanas\nY que sonara el eco\nDonde tú estabas.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,260,261,"2317","",0,"","","",1,0,0,[],""],["rm_t2-n2318",0,"A esa niña de mis ojos\nNo ponérmela delante;\nQue, como la quiero tanto,\nEl corazon se me parte.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,261,261,"2318","",0,"","","",3,0,0,[],""],["rm_t2-n2319",0,"Con un cedazo espeso\nTe he comparado,\nDonde queda el que pasa\nPulverizado.\nNo digas que nó,\nQue pondré por testigo\nA mi corazon.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,261,261,"2319","",0,"","","",1,0,0,[],""],["rm_t2-n2320",0,"Nunca puede estar triste\nQuien bien te quiere,\nPues verá á todas horas\nTu rostro alegre.\nPorque es constante\nQue el humor de la amada\nPase al amante.",0,0,-1,2,"",4,7,"ae",47,0,-1,0,261,261,"2320","",0,"","","",1,0,0,[],""],["rm_t2-n2321",0,"Tú me tiês á mí\nComo San Lorenso:\nAchicharrao - por un lao y otro\nY siempre contento.",0,0,-1,2,"",3,4,"eo",-1,0,-1,0,261,261,"2321","",0,"","","",1,0,0,[],""],["rm_t2-n2322",0,"Yo no he visto en este mundo\nMujer de tu natural,\nQue por estar bien conmigo,\nCon todo el mundo estás mal.",0,0,-1,2,"",0,4,"a",1,0,-1,0,261,261,"2322","",0,"","","",1,0,0,[],""],["rm_t2-n2323",0,"Er sentío me se pierde\nCuando con eya platico,\nEn bé que tengo una nobia\nCantaora y con buen pico.",0,0,-1,2,"",0,4,"io",141,0,-1,0,262,262,"2323","",0,"","","",1,0,0,[],""],["rm_t2-n2324",0,"A mi madre en una sala\nEl respeto le perdí\nCon acciones y palabras,\nSólo por quererte á tí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,262,262,"2324","",0,"","","",1,0,0,[],""],["rm_t2-n2325",0,"El que yo á tí te quiera\nNo es cosa injusta;\nPues busco, como todos,\nLo que me gusta.\nY en esto fundo\nConozcas que te quiero,\nCuando te busco.",0,0,-1,2,"",4,7,"uo",-1,0,-1,0,262,262,"2325","",0,"","","",1,0,0,[],""],["rm_t2-n2326",0,"No hay cosa más natural\nQue querer lo que más vale;\nQuisiera vivir mil siglos,\nPara otros tantos amarte.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,262,262,"2326","",0,"","","",1,0,0,[],""],["rm_t2-n2327",0,"Tú me amas, yo te amo,\nNuestro amor no ofende á Dios;\nSi tú quieres y yo quiero,\n¿Qué imposible entre los dos?",0,0,-1,2,"",0,4,"o",87,0,-1,0,262,262,"2327","",0,"","","",1,0,0,[],""],["rm_t2-n2328",0,"Más quisiera contigo\nVivir en guerra\nQue estar en paz con otra\nQue me quisiera.",0,0,-1,2,"",6,4,"ea",-1,0,-1,0,262,262,"2328","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2329",0,"Yo le pregunté á Undebé\nDe qué mar me moriria;\nMe dijo que der queré,\nSerrana, que te tenía.",0,0,-1,2,"",1,4,"ia",0,0,-1,0,263,263,"2329","",0,"","","",1,0,0,[],""],["rm_t2-n2330",0,"Si despues que me muriera\nTú m' habias e yorá,\nPor una lágrima tuya\nMe dejaba yo matá.",0,0,-1,2,"",0,4,"a",9,0,-1,0,263,263,"2330","",0,"","","",1,0,0,[],""],["rm_t2-n2332",0,"Si sientes como siento,\nBien de mi vida,\nLos mayores tormentos\nTienes en vida.",0,0,-1,2,"",6,4,"ia",-1,0,-1,0,263,263,"2332","",0,"","","",2,0,0,[],""],["rm_t2-n2333",0,"Hazme, mi bien, desdenes;\nQue todo el tiempo\nQue se tarda la dicha\nVive el deseo.\nY en mi amor noble\nSuponen esperanzas\nMás que favores.",0,0,-1,2,"",4,7,"oe",-1,0,-1,0,263,263,"2333","",0,"preciso_coleccion, palau_cantares","","",3,0,0,[],""],["rm_t2-n2334",0,"No eres tan generosa\nComo me han dicho;\nAntes eres avara\nDe tus cariños.\nEsto me gusta;\nQue así el tesoro guardas\nDe tu hermosura.",0,0,-1,2,"",4,7,"ua",-1,0,-1,0,263,264,"2334","",0,"","","",1,0,0,[],""],["rm_t2-n2335",0,"Cuando de tí mal oigo,\nSuspiro y callo;\nNi digo que eres bueno,\nNi que eres malo.\nQuisiera tener\nUna boca prestada\nPara responder.",0,0,-1,2,"",4,7,"e",20,0,-1,0,264,264,"2335","",0,"","","",1,0,0,[],""],["rm_t2-n2336",0,"Tan imposible lo jayo\nEn tí una mala partía,\nComo er jaser un bautismo\nEn tierra de morería.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,264,264,"2336","",0,"","","",1,0,0,[],""],["rm_t2-n2337",0,"Anoche fí á Capuchinos\nA resarle á Cristo un creo;\nPor desir: «Creo en Dios Padre,»\nDije: «Creo en mi moreno.»",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,264,264,"2337","",0,"","","",1,0,0,[],""],["rm_t2-n2338",0,"Si como yo soy tuyo\nFueras tú mia,\nMuchas dificultades\nSe vencerian.\nPues es constante\nQue cuando dos se quieren....\n¡Dios nos ampare!",0,0,-1,2,"",4,7,"ae",-1,0,-1,0,264,264,"2338","",0,"","","",1,0,0,[],""],["rm_t2-n2339",0,"Tengo un loro y no cesa\nDe decir: «Dueño»\nY es porque todo el dia\nMe lo está oyendo.\n¡Animalito,\nQue lo que ocultar quiero,\nLo dice á gritos!",0,0,-1,2,"",4,7,"io",-1,0,-1,0,264,265,"2339","",0,"","","",1,0,0,[],""],["rm_t2-n2340",0,"Desnuda te quisiera,\nPor más hermosa....\nDesnuda de pasiones,\nNó de otra cosa.\nY de esta suerte,\nFuera yo quien vistiera\nTus desnudeces.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,265,265,"2340","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t2-n2341",0,"Aunque vengas disfrazado,\nTe tengo de conocer,\nPor el tiempo que has estado\nPrisionero en mi querer.",0,0,-1,2,"",1,4,"e",20,0,-1,0,265,265,"2341","",0,"","","",1,0,0,[],""],["rm_t2-n2342",0,"Segundo Marco Antonio\nSoy en quererte,\nQue á vista de Cleopatra\nSe dió la muerte.\nY de este modo,\nTú imitas á Cleopatra,\nYo á Marco Antonio.",0,0,-1,2,"",4,7,"oo",-1,0,-1,0,265,265,"2342","",0,"","","",1,0,0,[],""],["rm_t2-n2343",0,"Fuertes lazos pusiera\nYo á mi garganta,\nSi el amor que te tengo\nCayera en falta.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,265,265,"2343","",0,"","","",1,0,0,[],""],["rm_t2-n2345",0,"Por Dios te pido, hermanita,\nQu' en habiendo gente 'lante,\nNi me mires ni te rias,\nNi me pongas mar semblante.",0,0,-1,2,"",0,4,"ae",47,0,-1,0,266,266,"2345","",0,"","","",1,0,0,[],""],["rm_t2-n2346",0,"¿Qué tenías ayer tarde,\nAmante mio moreno,\nQue tan aprisa yamabas\nA Jesús er Nasareno?",0,0,-1,2,"",0,4,"eo",76,0,-1,0,266,266,"2346","",0,"","","",6,0,0,[],""],["rm_t2-n2347",0,"¿Qué tenías anoche,\nMorena mia,\nQue llamabas al Cristo\nDe la Agonía?",0,0,-1,2,"",6,4,"ia",0,0,-1,0,266,266,"2347","",0,"","","",1,0,0,[],""],["rm_t2-n2348",0,"San Antonio Portugués,\nDevoto de lo perdido,\nMi amante se perdió anoche;\nBuscármelo, santo mio.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,266,266,"2348","",0,"","","",3,0,0,[],""],["rm_t2-n2349",0,"¡Gracias á Dios, madre mia,\nQue ya pareció el perdido!\nNunca se puede perder\nPájaro que tiene nido.",0,0,-1,2,"",0,4,"io",101,0,-1,0,266,266,"2349","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2350",0,"Dame la mano, iremos\nDonde llorastes,\nA recoger las perlas\nQue derramastes.",0,0,-1,2,"",6,4,"ae",142,0,-1,0,266,266,"2350","",0,"","","",1,0,0,[],""],["rm_t2-n2351",0,"Dame la manita, iremos\nAl sitio donde llorastes\nY entre los dos cogeremos\nLas perlas que derramastes.",0,0,-1,2,"",1,4,"ae",142,0,-1,0,267,267,"2351","",0,"","","",3,0,0,[],""],["rm_t2-n2352",0,"Quiéreme poco á poco;\nNo te apresures;\nQue lo que á mí me gusta\nQuiero que dure.",0,0,-1,2,"",6,4,"ue",-1,0,-1,0,267,267,"2352","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2353",0,"Quiéreme poquito á poco,\n¡Salero! no te apresures;\nQue este cariñito nuestro,\n¡Salero! quiero que dure.",0,0,-1,2,"",0,4,"ue",-1,0,-1,0,267,267,"2353","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2354",0,"Al alto cielo subí\nA confesar con un santo\nY me echó de penitencia\nQue no te quisiera tanto.",0,0,-1,2,"",0,4,"ao",30,0,-1,0,267,267,"2354","",0,"suspiros_amor","","",6,0,0,[],""],["rm_t2-n2355",0,"El querer que te tengo\nLo he confesado\nY el confesor me ha dicho\nQue no es pecado.\nQue es natural,\nQuererse unos á otros,\nPor caridad.",0,0,-1,2,"",4,7,"a",-1,0,-1,0,267,267,"2355","",0,"","","",4,0,0,[],""],["rm_t2-n2356",0,"Confesé con un fraile;\n¡Qué bueno era!\nMe echó de penitencia\nQue te quisiera.\nY yo te quise,\nPorque las penitencias\nDeben cumplirse.",0,0,-1,2,"",4,7,"ie",-1,0,-1,0,267,268,"2356","",0,"","","",2,0,0,[],""],["rm_t2-n2357",0,"En lo que me entretengo\nCuando estoy triste\nEs en oler la rosa\nQue tú me distes.\nAunque está seca,\nMe acuerdo de aquel tiempo\nQue estaba fresca.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,268,268,"2357","",0,"","","",2,0,0,[],""],["rm_t2-n2358",0,"Los cabellos atados\nQue tú me distes\nLos desato y los cuento\nCuando estoy triste.\nPero es el caso\nQue despues que los cuento,\nCojo y los ato.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,268,268,"2358","",0,"","","",1,0,0,[],""],["rm_t2-n2359",0,"Cuando estoy engolfado\nEn tus memorias\nMe parecen momentos\nLas que son horas.\nY si me ausento,\nUn siglo me parece\nCada momento.",0,0,-1,2,"",4,7,"eo",94,0,-1,0,268,268,"2359","",0,"","","",1,0,0,[],""],["rm_t2-n2362",0,"Me preguntas si te quiero;\nEscusada es la pregunta,\nSabiendo que por tu causa\nA mí ninguno me gusta.",0,0,-1,2,"",0,4,"ua",-1,0,-1,0,269,269,"2362","",0,"","","",3,0,0,[],""],["rm_t2-n2363",0,"Me preguntas si te quiero\nY las fatigas m' ajogan;\nYo t' estoy queriendo á tí\nComo á mi mesma persona.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,269,269,"2363","",0,"","","",3,0,0,[],""],["rm_t2-n2364",0,"Preguntó mi morena\nSi la queria;\nYo le dije tan sólo:\n-¡Morena mia!",0,0,-1,2,"",6,4,"a",0,0,-1,0,269,269,"2364","",0,"","","",1,0,0,[],""],["rm_t2-n2365",0,"Si quieres saber, niña,\nLo que te quiero,\nMira que es muy difícil\nEl comprenderlo.\nPorque no cabe\nQue el mismo que te quiera\nPueda explicarle.",0,0,-1,2,"",4,7,"ae",-1,0,-1,0,269,269,"2365","",0,"","","",1,0,0,[],""],["rm_t2-n2366",0,"Como sé lo que es bueno\nY lo que es malo,\nPor eso, vida mía,\nTe quiero tanto.\nQue á no saberlo,\nNo te quisiera tanto\nComo te quiero.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,269,269,"2366","",0,"","","",1,0,0,[],""],["rm_t2-n2367",0,"Sarga la luna y alumbre\nEr campo y los olibares;\nEste queré que te tengo\nDe los reaños me sale.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,269,269,"2367","",0,"","","",1,0,0,[],""],["rm_t2-n2368",0,"Si en trigo se combirtiera\nEste queré que te tengo,\nNo hubiera casa en Sebiya\nQue no tubiera granero.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,270,270,"2368","",0,"","","",1,0,0,[],""],["rm_t2-n2370",0,"Yo t' estoy queriendo á tí\nCon más penas y desbelos\nQue granos e trigo cabe'\n'N una cámara sin suelo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,270,270,"2370","",0,"","","",4,0,0,[],""],["rm_t2-n2371",0,"Con letras de plata y oro\nPondré en tu puerta un letrero,\nPara que sepa la gente\nLo mucho que yo te quiero.",0,0,-1,2,"",0,4,"eo",38,0,-1,0,270,270,"2371","",0,"","","",2,0,0,[],""],["rm_t2-n2374",0,"Bien sabe Dios que te quiero\nSin interés ni mardá\nY por tus güenas partías\nTe tengo de querer más.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,270,270,"2374","",0,"","","",3,0,0,[],""],["rm_t2-n2375",0,"Tomá papé, toma tinta,\nToma sangre de mis benas;\nToma la pluma y escribe\nLo que te quiero, morena.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,270,271,"2375","",0,"","","",1,0,0,[],""],["rm_t2-n2376",0,"Si se pudiera escribir\nLo que te quiero, morena,\nNo hubiera papel bastante\nEn el reino de Valencia.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,271,271,"2376","",0,"","","",3,0,0,[],""],["rm_t2-n2377",0,"Si la mar fuera de tinta\nY el cielo fuera papel,\nNo se podria escribir\nLo mucho que es mi querer.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,271,271,"2377","",0,"","","",11,0,0,[],""],["rm_t2-n2379",0,"Sinco lebriyos e sangre\nYené yo por tu queré;\n¡Mira que queré tan fino,\nQue con sangre lo regué!",0,0,-1,2,"",0,4,"e",77,0,-1,0,271,271,"2379","",0,"","","",1,0,0,[],""],["rm_t2-n2380",0,"Por aquer San Rafaé\nQue está en lo arto der puente,\nYo te tengo de queré\nCon fatiguiyas de muerte.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,271,271,"2380","",0,"","","",1,0,0,[],""],["rm_t2-n2381",0,"Bien sabes que te he querido\nY que te he sido leal\nY que siempre te he tenido\nUna firme boluntá.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,271,271,"2381","",0,"","","",2,0,0,[],""],["rm_t2-n2382",0,"Bien sabes que te he querido\nY que te he sido constante\nY que siempre te he tenido\nEn la cara buen semblante.",0,0,-1,2,"",1,4,"ae",47,0,-1,0,271,272,"2382","",0,"","","",2,0,0,[],""],["rm_t2-n2383",0,"Mucho quiero yo á mi suegra,\nQue es madre de mis amores\nY para mí está criando\nUn ramillete de flores.",0,0,-1,2,"",0,4,"oe",5,0,-1,0,272,272,"2383","",0,"","","",1,0,0,[],""],["rm_t2-n2384",0,"Es tanto lo que te quiero,\nQue te quisiera llevar\nMetida en la faltriquera,\nComo pedazo de pan.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,272,272,"2384","",0,"","","",26,0,0,[],""],["rm_t2-n2385",0,"Es tanto lo que te quiero,\nQue te quisiera tener\nMetida en la faltriquera,\nComo pliego de papel.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,272,272,"2385","",0,"","","",26,0,0,[],""],["rm_t2-n2386",0,"¡Quién pudiera llevarte,\nHermosa niña,\nMetida en los bolsillos\nDe mi pellica!\nAllí gozaras\nDe todos los placeres\nQue desearas.",0,0,-1,2,"",4,7,"aa",143,0,-1,0,272,272,"2386","",0,"","","",1,0,0,[],""],["rm_t2-n2387",0,"En una concha de nácar\nTe tengo de retratar,\nPara tenerte á mi lado\nY no salirte á buscar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,272,272,"2387","",0,"","","",1,0,0,[],""],["rm_t2-n2388",0,"En un relicario hermoso\nTe quisiera retratar,\nPara llevarte en mi pecho,\nComo Vírgen del Pilar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,272,273,"2388","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2389",0,"Si sabes los mandamientos,\nEl primero es el amar;\nEs tanto lo que te quiero,\nQue no te puedo olvidar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,273,273,"2389","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t2-n2390",0,"Cuando te veo con pena,\nEn mí no reina alegría;\nQue, como te quiero tanto,\nSiento la tuya y la mia.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,273,273,"2390","",0,"","","",8,0,0,[],""],["rm_t2-n2391",0,"Se me oprime el corazon\nCuando con pena te veo,\nQue la sombra de tu pena\nA mí me da sentimiento.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,273,273,"2391","",0,"","","",4,0,0,[],""],["rm_t2-n2392",0,"Es tanto lo que te quiero\nY lo que te quiero es tanto,\nQue el dia que no te veo\nNo le rezo á ningun santo.",0,0,-1,2,"",0,4,"ao",30,0,-1,0,273,273,"2392","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",26,0,0,[],""],["rm_t2-n2393",0,"Es tanto lo que te quiero,\nSerrana, que te matara\nY con sangre de mis venas\nLuégo te resucitara.",0,0,-1,2,"",0,4,"aa",57,0,-1,0,273,273,"2393","",0,"lafuente_madrid, palau_cantares","","",26,0,0,[],""],["rm_t2-n2394",0,"Tengo yo una prima hermana\nQue la quiero tanto y cuánto\nY la he de llevar á Roma,\nQue la vea el Padre Santo.",0,0,-1,2,"",0,4,"ao",30,0,-1,0,273,273,"2394","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2395",0,"Dise esta gitana\nQue yo no la quiero;\nCuando la miro -la miro á la cara\nDe duquitas muero.",0,0,-1,2,"",3,4,"eo",38,0,-1,0,274,274,"2395","",0,"","","",1,0,0,[],""],["rm_t2-n2396",0,"Dices que no te tengo\nMucho cariño;\nPreguntárselo puedes\nAl Dios Cupido.\nPorque, sin duda,\nDirá me hirió con flecha\nLa más aguda.",0,0,-1,2,"",4,7,"ua",144,0,-1,0,274,274,"2396","",0,"","","",1,0,0,[],""],["rm_t2-n2397",0,"Dueño mio, no hagas caso\nDe lo que dice la gente;\nQue tengo yo mi querer\nEn tí puesto solamente.",0,0,-1,2,"",0,4,"ee",15,0,-1,0,274,274,"2397","",0,"","","",1,0,0,[],""],["rm_t2-n2398",0,"Si á tus oidos yegare\nDe que m' estoy dibirtiendo,\nA tí no te dé cuidao,\nQue siempre t' estoy queriendo.",0,0,-1,2,"",0,4,"eo",52,0,-1,0,274,274,"2398","",0,"","","",1,0,0,[],""],["rm_t2-n2399",0,"No tengas jachares\nNi pases fatigas;\nQu' á náide quiero, - compañero el arma,\nMientras tú me bibas.",0,0,-1,2,"",3,4,"ia",-1,0,-1,0,274,274,"2399","",0,"","","",1,0,0,[],""],["rm_t2-n2400",0,"Trabajiyo m' ha costao\nEr reconosé tu genio;\nQu' á náide miro á la cara,\nPor no sabé si t' ofendo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,274,274,"2400","",0,"","","",1,0,0,[],""],["rm_t2-n2401",0,"Soy un posito de penas\nDesde que te conosí;\nA nádie miro á la cara,\nPor no darte que sentir.",0,0,-1,2,"",0,4,"i",-1,0,-1,0,275,275,"2401","",0,"","","",1,0,0,[],""],["rm_t2-n2402",0,"Quisiera darte á leer\nEscritos del corazon,\nPara que pudieras ver\nLo fino de mi aficion.",0,0,-1,2,"",1,4,"io",31,0,-1,0,275,275,"2402","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2403",0,"Aunque me veas con otras,\nNo tomes celos de mí;\nTodas me parecen feas\nCuando me acuerdo de tí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,275,275,"2403","",0,"","","",2,0,0,[],""],["rm_t2-n2404",0,"Si de los cielos bajara\nUna mujer para mí,\nCreo que no la mirara,\nPor haberte visto á tí.",0,0,-1,2,"",1,4,"i",23,0,-1,0,275,275,"2404","",0,"","","",1,0,0,[],""],["rm_t2-n2405",0,"Aunque á tí te demuestro\nTanto cariño,\nNo creas que con todas\nHago lo mismo.",0,0,-1,2,"",6,4,"io",-1,0,-1,0,275,275,"2405","",0,"","","",1,0,0,[],""],["rm_t2-n2406",0,"La barandiya der puente\nSe menea cuando paso;\nA tí solita te quiero\nY á náide le jago caso.",0,0,-1,2,"",0,4,"ao",145,0,-1,0,275,275,"2406","",0,"","","",1,0,0,[],""],["rm_t2-n2407",0,"A tí solito te quiero,\nA tí solito te adoro\nY á tí solito te entrego\nLas yabes de mi tesoro.",0,0,-1,2,"",0,4,"oo",85,0,-1,0,275,275,"2407","",0,"","","",1,0,0,[],""],["rm_t2-n2408",0,"Dicen que estás queriendo\nA mí y á otra;\nSiendo yo la del alma,\nPoco me importa.\nA otra y á mí;\nSiendo yo la del alma\nNo me importa á mí.",0,0,-1,2,"",4,7,"i",-1,0,-1,0,276,276,"2408","",0,"","","",1,0,0,[],""],["rm_t2-n2409",0,"No quisiera quererte\nCon tanto extremo,\nY aún me parece poco\nLo que te quiero.",0,0,-1,2,"",3,4,"eo",-1,0,-1,0,276,276,"2409","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2410",0,"Aunque más haga, nunca\nQuerer más puedo,\nPorque lo quiero todo\nCuando te quiero.\nNo querré á otra,\nPorque las perfecciones\nEn tí están todas.",0,0,-1,2,"",4,7,"oa",-1,0,-1,0,276,276,"2410","",0,"","","",1,0,0,[],""],["rm_t2-n2411",0,"Te quiero más que me quieres;\nBien te lo dirán mis obras;\nQue moriré en la demanda,\nPor defender tu persona.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,276,276,"2411","",0,"","","",8,0,0,[],""],["rm_t2-n2412",0,"Te quiero más que me quieres;\nMis obras te lo dirán,\nY si nó, déjalo al tiempo,\nQue es padre de la verdad.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,276,276,"2412","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["rm_t2-n2413",0,"Te quiero más que me quieres;\nEn eso no admitas duda;\nQue una mujer arrestada\nNo teme cosa ninguna.",0,0,-1,2,"",0,4,"ua",-1,0,-1,0,276,277,"2413","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["rm_t2-n2414",0,"No me olvides, flor de lís;\nNo me olvides, violeta,\nPorque te quiero yo á tí\nMás que al pan que me alimenta.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,277,277,"2414","",0,"","","",1,0,0,[],""],["rm_t2-n2415",0,"Á Dios der sielo le pío\nQue m' acabes de queré;\nTe quiero yo, sin reselo,\nMás qu' á ninguna mujé.",0,0,-1,2,"",0,4,"e",77,0,-1,0,277,277,"2415","",0,"","","",1,0,0,[],""],["rm_t2-n2416",0,"A mi padre y á mi madre\nLos quiero como es debío;\nPero en yegando á mi amante\nPierdo los sinco sentíos.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,277,277,"2416","",0,"","","",4,0,0,[],""],["rm_t2-n2417",0,"Te quiero más que á mi vida\nY más que á mi corazon;\nY más que al alma no digo,\nPorque se la debo á Dios.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,277,277,"2417","",0,"","","",8,0,0,[],""],["rm_t2-n2420",0,"Te quiero más que al vivir,\nMás que á la tierra y al cielo,\nMás que á mi padre y mi madre\nY más quererte no puedo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,277,277,"2420","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2421",0,"Te quiero más que á la sangre\nQue me corre por las venas\nY en estando tú delante,\nNádie me verá con pena.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,278,278,"2421","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2422",0,"Sacando á Dios verdadero,\nQue es al que se debe amar,\nTan sólo á tí te prefiero\nEntre todos los demás.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,278,278,"2422","",0,"","","",1,0,0,[],""],["rm_t2-n2423",0,"Esta guitarra que toco\nMe sirva de sepultura\nSi á otra quiero más que á tí,\nDespues de la Vírgen Pura.",0,0,-1,2,"",0,4,"ua",17,0,-1,0,278,278,"2423","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n2424",0,"Yo te quiero más que á mi\nY más que á mí te venero;\nConsidera tú por tí\nLo mucho que yo me quiero\n[Pero más te quiero á tí].",0,0,-1,2,"",7,5,"i",-1,0,-1,0,278,278,"2424","",0,"","","",1,0,0,[],""],["rm_t2-n2425",0,"Yo te quiero más que á Dios\nY d' eso náide se espante:\nQue á Dios como á Dios lo quiero\nY á tí como á fino amante.",0,0,-1,2,"",0,4,"ae",47,0,-1,0,278,278,"2425","",0,"","","",2,0,0,[],""],["rm_t2-n2426",0,"Yo te quiero más que á Dios\nY no digan qu' es locura;\nQu' á Dios como á Dios lo quiero\nY á ti como á criatura.",0,0,-1,2,"",0,4,"ua",17,0,-1,0,278,278,"2426","",0,"","","",2,0,0,[],""],["rm_t2-n2428",0,"Der Padre Santo de Roma\nEspero la escomunion,\nPorque sabe que yo he dicho\nQue te quiero más que á Dios.",0,0,-1,2,"",5,4,"o",-1,0,-1,0,279,279,"2428","",0,"","","",1,0,0,[],""],["rm_t2-n2429",0,"Aunque andes por el mundo\nDando mil vueltas,\nImposible es que encuentres\nQuien más te quiera.",0,0,-1,2,"",6,4,"ea",-1,0,-1,0,279,279,"2429","",0,"","","",2,0,0,[],""],["rm_t2-n2430",0,"Aunque tengas más amores\nQue flores tiene un almendro,\nNinguno te ha de querer\nComo yo te estoy queriendo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,279,279,"2430","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n2431",0,"Aunque te subas al cielo\nY te pongas junto á Dios,\nNo te han de querer los santos\nComo á tí te quiero yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,279,279,"2431","",0,"","","",8,0,0,[],""],["rm_t2-n2432",0,"Aunque te subas al cielo\nY te pongas en las nubes,\nTe tengo de conocer,\nPor el querer que te tuve.",0,0,-1,2,"",0,4,"ue",-1,0,-1,0,279,279,"2432","",0,"","","",8,0,0,[],""],["rm_t2-n2433",0,"Ni tu padre ni tu madre\nNi los que vayan naciendo\nTe pueden á tí querer\nComo yo te estoy queriendo.",0,0,-1,2,"",0,4,"eo",52,0,-1,0,279,279,"2433","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n2434",0,"Ni tu padre ni tu madre\nNi aquel Dios que te crió\nTienen de quererte tanto\nComo á tí te quiero yo.",0,0,-1,2,"",0,4,"o",2,0,-1,0,279,279,"2434","",0,"","","",10,0,0,[],""],["rm_t2-n2435",0,"Mi morena con faitigas\nMe dise que no la quiero;\n¡Asín la quisiera tanto\nUndebé del arto sielo!",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,280,280,"2435","",0,"","","",1,0,0,[],""],["rm_t2-n2436",0,"En toito 'r mundo s' encuentra\nQuien te quiera como yo;\n¡H' orbidaito á un güen flamenco\nPor quererte á tí, gachó!",0,0,-1,2,"",0,4,"o",2,0,-1,0,280,280,"2436","",0,"","","",1,0,0,[],""],["rm_t2-n2437",0,"En habiendo quien te quiera\nEn er mundo más que yo,\nMe meteré 'bajo e tierra,\nAonde no me bea ni Dios.",0,0,-1,2,"",3,4,"o",-1,0,-1,0,280,280,"2437","",0,"","","",1,0,0,[],""],["rm_t2-n2439",0,"Toitas las arañas negras\nQu' están metía' 'n sus níos\nMe pique' 'n er corason,\nSi mi queré es fingío.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,280,280,"2439","",0,"","","",1,0,0,[],""],["rm_t2-n2441",0,"La luz der sielo me farte\nY muera sin confesion,\nSi pretendo el engañarte\nO traigo tar in tension.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,280,280,"2441","",0,"","","",1,0,0,[],""],["rm_t2-n2442",0,"Que la lengua se me seque\nSi he jablaíto mar de tí;\nQue los ojos se me sarten\nSi te quiero con mar fin.",0,0,-1,2,"",0,4,"i",-1,0,-1,0,281,281,"2442","",0,"","","",1,0,0,[],""],["rm_t2-n2443",0,"Jasta 'l arma m' ha yegao\nLa raiz de tu queré;\nSi no es berdá lo que digo,\nMala puñalá me den.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,281,281,"2443","",0,"","","",1,0,0,[],""],["rm_t2-n2444",0,"No bayas, ánger dibino,\nA la misa que yo boy;\nNi tú resas, ni yo reso,\nNi con debosion estoy.",0,0,-1,2,"",0,4,"o",112,0,-1,0,281,281,"2444","",0,"","","",1,0,0,[],""],["rm_t2-n2445",0,"Dueño mio, no vayas\nA misa mayor;\nQue ni rezas ni rezo,\nNi pongo atencion.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,281,281,"2445","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2446",0,"Ayer en misa mayor\nHice un pecado mortal:\nPuse los ojos en tí\nY los quité del altar.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,281,281,"2446","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2447",0,"Cuando voy á la iglesia,\n¡Dios me perdone!\nPrimero miro al lado\nDonde te pones.",0,0,-1,2,"",6,4,"oe",-1,0,-1,0,281,281,"2447","",0,"","","",4,0,0,[],""],["rm_t2-n2448",0,"Voy á misa y no la oigo\n(Dile á Dios que me perdone),\nPorque no quito los ojos\nDel sitio donde te pones.",0,0,-1,2,"",0,4,"oe",-1,0,-1,0,281,281,"2448","",0,"","","",1,0,0,[],""],["rm_t2-n2449",0,"Ayer en misa mayor\nMe miraste y te reiste\nY me pareciste un sol\nCuando la cara volviste.",0,0,-1,2,"",5,4,"ie",-1,0,-1,0,282,282,"2449","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2450",0,"Cuando voy á la iglesia\nY no te veo,\nQuisiera que durara\nLa misa un credo.\nSi allí te hallo,\nQuisiera que durara\nLa misa un año.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,282,282,"2450","",0,"","","",4,0,0,[],""],["rm_t2-n2451",0,"Cuando en misa no te beo\nEn er sitio acostumbrado\nLe digo á mi corason:\n-Mi cariñito está malo.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,282,282,"2451","",0,"","","",1,0,0,[],""],["rm_t2-n2452",0,"Jasta los árboles sienten\nQue se le caiga una hoja;\nLo mismo lo sien to yo\nCuando mi niña se enoja",0,0,-1,2,"",0,4,"oa",146,0,-1,0,282,282,"2452","",0,"","","",1,0,0,[],""],["rm_t2-n2453",0,"Yo m' asomé á tu bentana\nÁ bé lo qu' estaba' haciendo,\nY bí qu' estabas yorando;\nLa curpa yo no la tengo.",0,0,-1,2,"",3,4,"eo",-1,0,-1,0,282,282,"2453","",0,"","","",1,0,0,[],""],["rm_t2-n2454",0,"Vendrá mi amante y dirá:\n-¿Qué tienes, que estás llorosa?\nY yo le responderé:\n-Contigo ninguna cosa.",0,0,-1,2,"",0,4,"oa",63,0,-1,0,282,282,"2454","",0,"","","",1,0,0,[],""],["rm_t2-n2455",0,"¿Qué tienes, qu' estás tan triste,\nCon la mano en la mejiya?\nTraigo para consolarte\nLa fló de la marabiya. (?)",0,0,-1,2,"",0,4,"ia",93,0,-1,0,283,283,"2455","",0,"","","",1,0,0,[],""],["rm_t2-n2456",0,"Vén acá; tú eres mi amor\nY tú eres mi cielecito;\nDime, ¿qué te he hecho yo,\nQue estás tan enojadito?",0,0,-1,2,"",0,4,"io",119,0,-1,0,283,283,"2456","",0,"","","",1,0,0,[],""],["rm_t2-n2457",0,"¡Qué triste y qué pensativa\nEstá la prenda que adoro!\n¿Qué cariñito le haré,\nQue se le quite el enojo?",0,0,-1,2,"",0,4,"oo",-1,0,-1,0,283,283,"2457","",0,"","","",3,0,0,[],""],["rm_t2-n2458",0,"A la Bírgen del Rocío\nYo le boy á preguntar\nQue t' han hecho mis ojiyos,\nQue no los quieres mirar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,283,283,"2458","",0,"","","",1,0,0,[],""],["rm_t2-n2459",0,"Mi morena se ha enojado,\nPorque no le dije «adios.»\n¡.A.dios, morena del alma!\n¡Adios, morenita, adios!",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,283,283,"2459","",0,"","","",4,0,0,[],""],["rm_t2-n2460",0,"Más te quiero enojada\nQue placentera;\nQue haces una enojada\nMuy hechicera.",0,0,-1,2,"",6,4,"ea",44,0,-1,0,283,283,"2460","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2461",0,"Más bella con desdenes\nMe has parecido;\nQue á lo hel'moso lo ingrato\nSirve de aliño.\nPero, cuidado,\nQue afean los desdenes\nSi son sobrados.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,283,284,"2461","",0,"","","",1,0,0,[],""],["rm_t2-n2462",0,"No te enfades conmigo\nSi bien me quieres,\nQue los disgustos mudan\nLos pareceres.\nY nádie olvida\nEl puñal que lé causa\nMortal herida.",0,0,-1,2,"",4,7,"ia",37,0,-1,0,284,284,"2462","",0,"","","",1,0,0,[],""],["rm_t2-n2463",0,"Si he de reñir contigo,\nCólera dame,\nPues sin ella, muy fresca\nTengo la sangre.\nY yo no puedo\nReñir á sangre fria\nCon la que quiero.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,284,284,"2463","",0,"","","",1,0,0,[],""],["rm_t2-n2464",0,"No sé cómo tú ni yo\nTenemós tantos disgustos,\nSi ni tú ni yo podemos\nVivir si no estamos juntos.",0,0,-1,2,"",0,4,"uo",-1,0,-1,0,284,284,"2464","",0,"","","",1,0,0,[],""],["rm_t2-n2465",0,"Yo no sé qué demonios\nLos dos tenemos;\nMientras más regaílamos,\nMás nos queremos.",0,0,-1,2,"",6,4,"eo",127,0,-1,0,284,284,"2465","",0,"","","",4,0,0,[],""],["rm_t2-n2466",0,"Cuando te beo benir\nTe muestro dos mir enojos;\nY cuando te beo ir\nDetrás me se ban los ojos.",0,0,-1,2,"",1,4,"oo",99,0,-1,0,284,284,"2466","",0,"","","",3,0,0,[],""],["rm_t2-n2467",0,"Me dices que no me quieres\nY es mentira, que me engañas;\nQue estoy leyendo en tus ojos\nLo que me quiere tu alma.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,285,285,"2467","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n2468",0,"Andas disiendo, chiquiya,\nQue mar tirito me den\nY las fatigas t' ajogan\nEr dia que no me bes.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,285,285,"2468","",0,"","","",1,0,0,[],""],["rm_t2-n2472",0,"Permita er sielo qu' un rayo...\nPero nó, detente lengua;\nQue no quiero que por mí\nDaño á mi amante le benga.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,285,285,"2472","",0,"","","",1,0,0,[],""],["rm_t2-n2473",0,"Tengo mir agrabios tuyos\nY t' he de mandá prendé....\nEn la cárse de mis brasos,\nQu' en otra no puede sé.",0,0,-1,2,"",0,4,"e",77,0,-1,0,285,285,"2473","",0,"","","",1,0,0,[],""],["rm_t2-n2475",0,"Permita Dios de los sielos\nQue te caigas y te mates....\nY que yo sea la piedra\nDonde los sesos te sartes.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,286,286,"2475","",0,"","","",2,0,0,[],""],["rm_t2-n2476",0,"«¡Caramba, que si me enfado\nHe de llegar á olvidarte!»\nEsto digo, pero luégo\nNo puedo más que adorarte.",0,0,-1,2,"",0,4,"ae",8,0,-1,0,286,286,"2476","",0,"","","",1,0,0,[],""],["rm_t2-n2477",0,"Juré no volver á verte....\n¡Mira tú que juramento,\nCuando te llevo en el alma\nY en mi mismo pensamiento!",0,0,-1,2,"",0,4,"eo",94,0,-1,0,286,286,"2477","",0,"","","",1,0,0,[],""],["rm_t2-n2479",0,"Cuando yo estoy delante\nDel dueño mio,\nCuanto más se me ofrece,\nMénos le digo.\nPues mis potencias\nConfusas y turbadas\nTraban mi lengua.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,286,286,"2479","",0,"","","",1,0,0,[],""],["rm_t2-n2480",0,"Aunque al mirarme callas,\nBien te comprendo;\nQue hay un lenguaje mudo\nQue es muy discreto.\nY si se entiende,\nEs con ménos palabras\nMás elocuente.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,287,287,"2480","",0,"","","",1,0,0,[],""],["rm_t2-n2481",0,"Porque callo no creas\nQue yo te olvido;\nQue cuanto ménos hablo,\nYo más te digo.\nY mis obsequios\nSilenciosos te muestran\nMás mi respeto.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,287,287,"2481","",0,"","","",2,0,0,[],""],["rm_t2-n2482",0,"Con los ojos me explicas\nTu amante llama;\nRepara bien los mios,\nVerás la paga.\nY en los extremos,\nSerán los ojos lenguas\nPara entendernos.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,287,287,"2482","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t2-n2483",0,"Me miras y te miro,\nCallas y callo;\nAsí nos estaremos\nDoscientos años.\nY de esta suerte,\nEstándonos mirando,\nVendrá la muerte.",0,0,-1,2,"",4,7,"ee",134,0,-1,0,287,287,"2483","",0,"","","",3,0,0,[],""],["rm_t2-n2484",0,"Tusojos y mis ojos\nMiran atentos\nY callando se dicen\nSus pensamientos.\nCosa es bien rara\nQue sin hablar se entiendan\nNuestras dos almas.",0,0,-1,2,"",4,7,"aa",-1,0,-1,0,287,288,"2484","",0,"","","",1,0,0,[],""],["rm_t2-n2485",0,"Tus ojitos y los mios\nSe miran con aficion\nY parece que se dicen\nLo que siente el corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,288,288,"2485","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2486",0,"Tus ojos y los mios\nSe han enredado,\nComo las zarzamoras\nPor los vallados.",0,0,-1,2,"",6,4,"ao",-1,0,-1,0,288,288,"2486","",0,"palau_cantares, fernan_caballero","","",7,0,0,[],""],["rm_t2-n2487",0,"A la mar, por ser honda,\nSe van los rios\nY detrás de tus ojos\nSe van los mios.",0,0,-1,2,"",6,4,"o",135,0,-1,0,288,288,"2487","",0,"palau_cantares, barcenas_marinera, huambachano","","",5,0,0,[],""],["rm_t2-n2488",0,"Detrás de tí, dueño mio,\nMis ojos llorando van,\nComo soldado á la guerra\nDetrás de su capitan.",0,0,-1,2,"",0,4,"a",147,0,-1,0,288,288,"2488","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2489",0,"Cuando me echan tus ojos\nUna mirada,\nLos rayos que despiden\nHieren el alma.\nPorque tus ojos\nHan de volver sensibles\nHasta los troncos.",0,0,-1,2,"",4,7,"oo",-1,0,-1,0,288,288,"2489","",0,"","","",1,0,0,[],""],["rm_t2-n2490",0,"Si por una mirada\nSe da cuenta á Dios,\n¡Qué cuenta tan estrecha\nDaremos los dos!\nY yo he querido\nEnmendarme, alma mia,\nY no he podido.",0,0,-1,2,"",4,7,"io",101,0,-1,0,289,289,"2490","",0,"","","",1,0,0,[],""],["rm_t2-n2491",0,"De tus divinos ojos\nSaltó una chispa,\nPrendió fuego en los mios,\n¡Jesús, qué dicha!\nY ahora me abraso,\nCon tan sólo una chispa,\nQue no hice caso.",0,0,-1,2,"",4,7,"ao",145,0,-1,0,289,289,"2491","",0,"","","",1,0,0,[],""],["rm_t2-n2492",0,"Descuidos de mis ojos\nEn el mirarte\nCausaron el cuidado\nDel pecho amante.\nDe tal manera,\nQue la culpa es de aquéllos,\nDe éste la pena.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,289,289,"2492","",0,"","","",1,0,0,[],""],["rm_t2-n2493",0,"Si sólo por mirarte\nMuerte me dieran,\nMil vidas deseara,\nPara perderlas.\nPorque no quiero\nLa vida que no es vida,\nSi no te veo.",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,289,289,"2493","",0,"","","",1,0,0,[],""],["rm_t2-n2494",0,"Querer que con sosiego\nTe esté mirando\nEs querer imposibles\nQue yo no alcanzo.\nSi fueras fea,\nNo sabrias quejarte\nDe mi obediencia.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,289,290,"2494","",0,"","","",1,0,0,[],""],["rm_t2-n2495",0,"Ocultar que amor tienes\nEs un delirio;\nQue el mal sale á la cara,\nSi es de peligro.\nY en tí se ad vierten\nSíntomas expresivos\nDe este accidente.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,290,290,"2495","",0,"","","",1,0,0,[],""],["rm_t2-n2496",0,"El verte es mi alimento;\nYa tengo hambre;\nNo permitas, bien mio,\nQue me desmaye.\nSi me desmayo,\nMis penas y fatigas\nVan á tu cargo.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,290,290,"2496","",0,"","","",1,0,0,[],""],["rm_t2-n2497",0,"Si me quitan el verte,\nQue es mi alimento,\nSuban al campanario,\nToquen á muerto.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,290,290,"2497","",0,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["rm_t2-n2498",0,"Yo no sé si me quieres\nO si me olvidas;\nLo que yo sé es que vivo\nCuando me miras.\nY así, te pido\nNo olvides el remedio\nCon que yo vivo.",0,0,-1,2,"",4,7,"io",-1,0,-1,0,290,290,"2498","",0,"","","",2,0,0,[],""],["rm_t2-n2499",0,"Al compás de tus ojos\nLlevo los mios;\nSi los abres, los abro;\nSi miras, miro.\nYo no puedo más\nQue seguir tu dictámen\nHasta en el mirar.",0,0,-1,2,"",4,7,"a",-1,0,-1,0,291,291,"2499","",0,"","","",1,0,0,[],""],["rm_t2-n2500",0,"Mi amor no se complace·\nSólo con verte,\nPorque dice el adagio\nQue quien más tiene....",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,291,291,"2500","",0,"","","",3,0,0,[],""],["rm_t2-n2501",0,"Cuando monto á caballo\nSoy mal ginete,\nPues pierdo los estribos,\nNiña, por verte.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,291,291,"2501","",0,"","","",2,0,0,[],""],["rm_t2-n2502",0,"El que estrellas estudia\nVe su destino\nY yo estudio tus ojos\nPor ver el mio.",0,0,-1,2,"",6,4,"o",-1,0,-1,0,291,291,"2502","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2503",0,"Yo no necesito verte\nPara tenerte aficion,\nPues ántes de conocerte\nLloraba mi corazon\n[Gotas de sangre por verte].",0,0,-1,2,"",7,5,"ee",134,0,-1,0,291,291,"2503","",0,"","","",3,0,0,[],""],["rm_t2-n2504",0,"En tu presencia, niña,\nYo vivo á gusto;\nMas si de tí me aparto,\nCaigo difunto.",0,0,-1,2,"",6,4,"uo",-1,0,-1,0,291,291,"2504","",0,"","","",1,0,0,[],""],["rm_t2-n2505",0,"Mi corazon herido\nSangre derrama;\nTan sólo con mirarte,\nLa herida sana.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,292,292,"2505","",0,"","","",2,0,0,[],""],["rm_t2-n2506",0,"Ya sé que te han impuesto\nQue no me mires;\nObedece el mandato,\nMas no me olvides.\nQue la obediencia,\nDueño mio, no quita\nCorrespondencia.",0,0,-1,2,"",4,7,"ea",46,0,-1,0,292,292,"2506","",0,"","","",1,0,0,[],""],["rm_t2-n2507",0,"Por donde quiera que voy,\nParece que te voy viendo;\nY es la sombra del querer,\nQue me viene persiguiendo.",0,0,-1,2,"",0,4,"eo",52,0,-1,0,292,292,"2507","",0,"carrizo_salta, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2508",0,"Cuando me hallo solita\nLloro mi solicitud;\nTodas las sombras que veo\nMe parece que eres tú.",0,0,-1,2,"",0,4,"u",-1,0,-1,0,292,292,"2508","",0,"","","",1,0,0,[],""],["rm_t2-n2509",0,"Mira tú si yo tendré\nFijo en tí mi pensamiento,\nQue si al espejo me miro,\nEn vez de verme te veo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,292,292,"2509","",0,"","","",1,0,0,[],""],["rm_t2-n2510",0,"Dos contrarios efectos\nMe causa el verte;\nA la vista contento\nY al alma muerte.",0,0,-1,2,"",6,4,"ee",134,0,-1,0,292,292,"2510","",0,"","","",1,0,0,[],""],["rm_t2-n2511",0,"No verte me da pena,\nVerte me mata;\nCon que en verte y no verte\nMi muerte se halla.\nNo sé qué hacerme,\nCuando en los dos extremos\nHallo la muerte.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,293,293,"2511","",0,"","","",1,0,0,[],""],["rm_t2-n2512",0,"Tengo pena si te veo,\nY si no te veo, doble;\nNo tengo más alegría\nQue cuando escucho tu nombre.",0,0,-1,2,"",0,4,"oe",-1,0,-1,0,293,293,"2512","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2513",0,"La pena de no verte\nMe martiriza\nY cuando á verte llego....\n¡Dios nos asista!",0,0,-1,2,"",6,4,"ia",-1,0,-1,0,293,293,"2513","",0,"","","",3,0,0,[],""],["rm_t2-n2514",0,"El verte me da la muerte;\nEl no verte me da vida;\nMás quiero morir y verte\nQue no verte y tener vida.",0,0,-1,2,"",1,4,"ia",-1,0,-1,0,293,293,"2514","",0,"","","",5,0,0,[],""],["rm_t2-n2515",0,"El sol me parece oscuro\nY oscura la luna clara;\nLa música me entristece;\nSólo me alegra tu cara.",0,0,-1,2,"",0,4,"aa",57,0,-1,0,293,293,"2515","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2516",0,"La luna me da de cara (?)\nY el sol dorado me quema;\nLa música me entristece;\nSólo tu vista me alegra.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,293,293,"2516","",0,"","","",1,0,0,[],""],["rm_t2-n2517",0,"Un corazon constante\nQue fino te ama,\n¿Cómo ha de estar alegre\nSin ver tu cara?",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,294,294,"2517","",0,"","","",1,0,0,[],""],["rm_t2-n2518",0,"Ni comiendo ni bebiendo\nNi durmiendo ni soñando\nTiene mi penita alivio,\nSi no es que te estoy mirando.",0,0,-1,2,"",0,4,"ao",33,0,-1,0,294,294,"2518","",0,"","","",3,0,0,[],""],["rm_t2-n2519",0,"¿Para qué me dísteis vista,\nSeñora Santa Lucía,\nSi no veo lo que quiero\nTodas las horas del dia?",0,0,-1,2,"",0,4,"ia",0,0,-1,0,294,294,"2519","",0,"","","",1,0,0,[],""],["rm_t2-n2520",0,"Dame un poco de agua,\nFria ó caliente,\nNó por la sed que tengo,\nSino por verte.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,294,294,"2520","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2521",0,"Cada vez que te veo,\nCara de santa,\nEl corazon al cielo\nSe me levanta.",0,0,-1,2,"",6,4,"aa",148,0,-1,0,294,294,"2521","",0,"","","",6,0,0,[],""],["rm_t2-n2522",0,"Cada vez que te veo,\nPara mí digo:\n—A mi prójimo amo\nComo á mí mismo.",0,0,-1,2,"",6,4,"io",-1,0,-1,0,294,294,"2522","",0,"palau_cantares, fernan_caballero","","",6,0,0,[],""],["rm_t2-n2523",0,"Si yo te viera esta noche,\nMorena del alma mía,\n¡Qué pronto recompensaba\nTodas las horas del dia!",0,0,-1,2,"",0,4,"ia",0,0,-1,0,294,294,"2523","",0,"","","",1,0,0,[],""],["rm_t2-n2524",0,"El gilguero canta en zarza\nY el ruiseñor en almendro;\nYo no sé donde ponerme\nPara siempre estarte viendo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,295,295,"2524","",0,"","","",1,0,0,[],""],["rm_t2-n2525",0,"Si yo pudiera alcanzar\nDe una estrella los reflejos,\nTe los pondria en la frente,\nPara verte desde léjos.",0,0,-1,2,"",0,4,"eo",149,0,-1,0,295,295,"2525","",0,"","","",1,0,0,[],""],["rm_t2-n2526",0,"Amantito, amantito,\nAmante, amante,\nLas pestañas me estorban\nPara mirarte.",0,0,-1,2,"",6,4,"ae",-1,0,-1,0,295,295,"2526","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2527",0,"Hermoso sol de los soles,\n¿Dónde estuvistes ayer,\nQue mis ojos te buscaron\nY no te pudieron ver?",0,0,-1,2,"",0,4,"e",20,0,-1,0,295,295,"2527","",0,"","","",3,0,0,[],""],["rm_t2-n2528",0,"Cuando llegan los domingos,\n¿Dónde estás, que no te veo,\nSiendo la palma gallarda\nDel jardin de mi recreo?",0,0,-1,2,"",0,4,"eo",66,0,-1,0,295,295,"2528","",0,"","","",1,0,0,[],""],["rm_t2-n2529",0,"Yo quisiera estarte viendo\nTreinta dias cada mes,\nSiete dias en semana,\nCada minuto una vez.",0,0,-1,2,"",0,4,"e",150,0,-1,0,295,295,"2529","",0,"","","",2,0,0,[],""],["rm_t2-n2530",0,"Llevo contados los meses,\nLas semanas y los dias,\nLas horas y los minutos\nQue á tu cara no la via.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,295,295,"2530","",0,"","","",1,0,0,[],""],["rm_t2-n2531",0,"Uno, dos, tres, cuatro, cinco,\nSeis, siete, ocho, nueve, diez,\nOnce, doce, trece dias\nHay que no te vengo á ver.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,296,296,"2531","",0,"","","",3,0,0,[],""],["rm_t2-n2532",0,"El dia que no te veo\nPor tarde, noche y mañana\nNi la comida me sabe\nNi el agua bebo con gana.",0,0,-1,2,"",0,4,"aa",4,0,-1,0,296,296,"2532","",0,"","","",5,0,0,[],""],["rm_t2-n2533",0,"Con hablarte como y bebo\nY sólo el verte me engorda\nY el dia que no te veo\nLas fatiguillas me ahogan.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,296,296,"2533","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2534",0,"Tanto me alimenta el verte\nComo el agua al macetero.\nComo la ropa al desnudo\nY la salud al enfermo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,296,296,"2534","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2535",0,"Mas fácil fuera contar\nLas estrellitas del cielo\nQue las penas que yo paso\nEl dia que no te veo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,296,296,"2535","",0,"","","",1,0,0,[],""],["rm_t2-n2536",0,"El dia que no te beo\nPeniya tengo en el arma,\nPorque m' estoy deshaciendo,\nComo la sar en el agua.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,296,296,"2536","",0,"","","",1,0,0,[],""],["rm_t2-n2537",0,"El dia que no veo,\nGalan, tu cara,\nComo la golondrina\nVoy enlutada.",0,0,-1,2,"",6,4,"aa",-1,0,-1,0,296,296,"2537","",0,"","","",4,0,0,[],""],["rm_t2-n2538",0,"El dia que no te veo\nTengo yo mi corazon\nComo un jardin sin recreo,\nComo una flor sin olor.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,297,297,"2538","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2539",0,"Er pelo de mi morena\nEs negro jasta las puntas\nY er dia que no la beo\nSielo y tierra me se juntan.",0,0,-1,2,"",0,4,"ua",-1,0,-1,0,297,297,"2539","",0,"","","",1,0,0,[],""],["rm_t2-n2540",0,"Fatigas me dan de muerte\nEn no biéndote en un dia;\nSi no te biera en un año\nLa pena me mataria.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,297,297,"2540","",0,"","","",3,0,0,[],""],["rm_t2-n2542",0,"El dia que no veo\nA mi rubita\nEl dolor de cabeza\nNo se me quita.",0,0,-1,2,"",6,4,"ia",50,0,-1,0,297,297,"2542","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t2-n2543",0,"Amarillo sale el sol\nEl dia que no te veo;\nNi mis ojos tienen luz,\nNi mi corazon consuelo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,297,297,"2543","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2544",0,"El sol sale para todos,\nQue lo dice el almanaque;\nEl dia que no te veo\nEl sol para mí no sale.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,297,297,"2544","",0,"","","",2,0,0,[],""],["rm_t2-n2545",0,"El dia que no te veo\nPara mí no sale el sol,\nNi tienen mis ojos luces,\nNi vida mi corazon.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,298,298,"2545","",0,"","","",5,0,0,[],""],["rm_t2-n2546",0,"¡Qué triste que va la luna\nCuando no lleva lucero!\nAsí está mi corazon\nEl dia que no te veo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,298,298,"2546","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2547",0,"¡Válgame Dios, padre Adan, (?)\nLo que quiero á esta mujer!\nEl dia que no la veo\nLa retrato en la paré.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,298,298,"2547","",0,"","","",3,0,0,[],""],["rm_t2-n2548",0,"Er dia que yo no beo\nTu cara, morena, un rato,\nMe boy á Santo Domingo\nY ayí miro tu retrato.",0,0,-1,2,"",0,4,"ao",19,0,-1,0,298,298,"2548","",0,"","","",1,0,0,[],""],["rm_t2-n2549",0,"El dia que no veo\nMi amor tres veces,\nLos minutos son horas,\nLas horas meses.",0,0,-1,2,"",6,4,"ee",151,0,-1,0,298,298,"2549","",0,"","","",4,0,0,[],""],["rm_t2-n2550",0,"María del alma mia,\nLa de los ojitos garzos,\nMuerto está mi corazon\nEl dia que no te hablo.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,298,298,"2550","",0,"","","",6,0,0,[],""],["rm_t2-n2551",0,"Como pajarito triste,\nE rama en rama bolando\nTengo yo mi corazon\nEr dia que no te hablo.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,298,298,"2551","",0,"","","",2,0,0,[],""],["rm_t2-n2554",0,"Si con hechizos pudiera\nEsta noche hablar contigo,\nEn breve los dispusiera,\nPor dar á mi pena alivio.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,299,299,"2554","",0,"","","",3,0,0,[],""],["rm_t2-n2555",0,"Los presos cuentan los dias,\nLos presidiarios los años\nY yo cuento, vida mia,\nLas horas que no te hablo.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,299,299,"2555","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2556",0,"Más quisiera verte, niña,\nEmbarcadita en la mar,\nQue nó verte en la ventana\nPara no poderte hablar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,299,299,"2556","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n2557",0,"Tengo yo mi corazon\nMás negro que el terciopelo,\nDe ver que no puedo hablarte\nTodas las horas que quiero.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,299,299,"2557","",0,"palau_cantares, lafuente_madrid","","",14,0,0,[],""],["rm_t2-n2558",0,"¿Cómo quieres que á solas\nComuniquemos,\nSi el hacha de la envidia\nCorta los remos?",0,0,-1,2,"",6,4,"eo",127,0,-1,0,299,299,"2558","",0,"","","",1,0,0,[],""],["rm_t2-n2559",0,"Para verte y no hablarte,\nMás bien quisiera\nNo haberte conocido\nPor vez primera.",0,0,-1,2,"",6,4,"ea",44,0,-1,0,300,300,"2559","",0,"","","",1,0,0,[],""],["rm_t2-n2560",0,"Hermosura del alma,\nVéte á una aldea;\nYa que yo no te hable,\nQue no te vea.",0,0,-1,2,"",6,4,"ea",54,0,-1,0,300,300,"2560","",0,"","","",2,0,0,[],""],["rm_t2-n2561",0,"Fortuna con desgracia\nTuve ayer tarde:\nEncontré á mi morena\n' No pude hablarle.",0,0,-1,2,"",6,4,"ae",-1,0,-1,0,300,300,"2561","",0,"","","",1,0,0,[],""],["rm_t2-n2562",0,"Ya que no te puedo hablar\nNi en tu casa ni en la calle,\nMe contento con mirar\nDe tu puerta los umbrales.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,300,300,"2562","",0,"","","",6,0,0,[],""],["rm_t2-n2563",0,"Ya que no te puedo hablar,\nPonte donde yo te vea;\nLe daré gusto á mis ojos,\nYa que otra cosa no sea.",0,0,-1,2,"",0,4,"ea",54,0,-1,0,300,300,"2563","",0,"lafuente_madrid, palau_cantares","","",6,0,0,[],""],["rm_t2-n2564",0,"Ya que no puedes hablarme,\nHazme con los ojos señas;\nQue en algunas ocasiones\nLos ojos sirven de lengua.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,300,300,"2564","",0,"","","",1,0,0,[],""],["rm_t2-n2565",0,"Dímelo tú con tus ojos,\nAunque lo calle la boca;\nQue el cariño verdadero\nNo es palabras, sino es obras.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,300,300,"2565","",0,"","","",1,0,0,[],""],["rm_t2-n2566",0,"Quisiera que tu casa\nDe cristal fuera:\nYa que hablarte no puedo,\nVerte pudiera.",0,0,-1,2,"",6,4,"ea",44,0,-1,0,301,301,"2566","",0,"","","",1,0,0,[],""],["rm_t2-n2567",0,"Nunca de tí me acuerdo,\nDueño querido,\nPorque aquel que se acuerda\nSupone olvido.\nY yo en mi mente\nTengo la imágen tuya\nSiempre presente.",0,0,-1,2,"",4,7,"ee",15,0,-1,0,301,301,"2567","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2568",0,"¿Quieres tú saber mi vida\nDesde que te conocí?\nEn tí pensando al no verte\nY al verte pensando en tí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,301,301,"2568","",0,"","","",1,0,0,[],""],["rm_t2-n2571",0,"Más veces de tí me acuerdo\nQue hojas tienen los laureles,\nY botes un boticario,\nY un escribano papeles.",0,0,-1,2,"",0,4,"ee",97,0,-1,0,301,301,"2571","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2572",0,"Me acuerdo de ti más beses\nQue minutos tiene 'r dia\nY todos son de quererte\nY no 'rbidarte enlabia.",0,0,-1,2,"",5,4,"aa",-1,0,-1,0,302,302,"2572","",0,"","","",1,0,0,[],""],["rm_t2-n2573",0,"Pienso en ti solamente,\nSola te quiero\nY en mis tristezas sólo\nDe tí me acuerdo.\nDe esta manera\nEn ti tengo empleadas\nLas tres potencias.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,302,302,"2573","",0,"","","",2,0,0,[],""],["rm_t2-n2574",0,"Cuando voy á la besana\nLlebo los güeyes arando,\nCon la mano en la mansera\nY en tí, serrana, pensando.",0,0,-1,2,"",0,4,"ao",33,0,-1,0,302,302,"2574","",0,"","","",3,0,0,[],""],["rm_t2-n2575",0,"Camino de Grazalema\nMe puse á echar un cigarro\nY acordándome de tí\nSe me cayó de la mano.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,302,302,"2575","",0,"","","",3,0,0,[],""],["rm_t2-n2576",0,"Cuando me dieron el tiro\nEn los montes de Llerena,\nCon las ánsias de la muerte\nMe acordé de tí, morena.",0,0,-1,2,"",0,4,"ea",59,0,-1,0,302,302,"2576","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2577",0,"Cuando yo estaba en prisiones\nEn lo que me entretenia\nEra en escribir tu nombre\nEn los ladrillos que habia.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,302,302,"2577","",0,"carrizo_salta","","",10,0,0,[],""],["rm_t2-n2578",0,"En un castillo me ví\nPrisionero entre cadenas\nY acordándome de tí\nSe me quitaban las penas.",0,0,-1,2,"",1,4,"ea",62,0,-1,0,303,303,"2578","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2579",0,"En un castillo me ví\nDonde sol ni luna entraban\nY acordándome de tí\nLas penas se me quitaban.",0,0,-1,2,"",1,4,"aa",39,0,-1,0,303,303,"2579","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2580",0,"En el alma te tengo\nTan á lo vivo,\nQue despierto soñando\nSiempre contigo.\nY en despertando,\nMe digo yo á mí mismo:\n--¡Vamos soñando!",0,0,-1,2,"",4,7,"ao",33,0,-1,0,303,303,"2580","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t2-n2582",0,"Sueño en tí, vida mía,\nPero entre sueños\nSueño lo que quisiera\nNo fuera sueño.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,303,303,"2582","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2583",0,"Esta noche he soñado....\n¡Qué dulce sueño!\nDecírtelo pensaba,\nMas no me atrevo.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,303,303,"2583","",0,"","","",2,0,0,[],""],["rm_t2-n2584",0,"Anoche soñaba yo\nQue con mi amante dormía;\n¡Qué sueño tan resalado\nQue mi corazon tenía!",0,0,-1,2,"",0,4,"ia",0,0,-1,0,303,304,"2584","",0,"","","",9,0,0,[],""],["rm_t2-n2585",0,"Soñé contigo, arma mia,\nSoñé con gusto y descanso;\nSoñé que yo te tenía\nEn mis amorosos brazos.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,304,304,"2585","",0,"","","",1,0,0,[],""],["rm_t2-n2586",0,"Anoche tuve un ensueño;\nSoñé que me parecía\nQue me besaban tus labios\nY entre tus brazos dormia.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,304,304,"2586","",0,"","","",2,0,0,[],""],["rm_t2-n2587",0,"Anoche ensoñé un ensueño;\n¡Ojalay fuera berdá!\nQue t' estaba desatando\nLa sinta der delantá.",0,0,-1,2,"",0,4,"a",9,0,-1,0,304,304,"2587","",0,"","","",1,0,0,[],""],["rm_t2-n2588",0,"Soñaba yo que gozaba\nEn brazos del bien que adoro;\nCuando desperté, me hallé\nQue era un sueño; sufro y lloro.",0,0,-1,2,"",0,4,"oo",85,0,-1,0,304,304,"2588","",0,"","","",1,0,0,[],""],["rm_t2-n2589",0,"Pensando en tí me dormí,\nHermoso cielo estrellado;\nDesperté y me hallé sin tí....\n¡Qué sueño tan desgraciado!",0,0,-1,2,"",1,4,"ao",14,0,-1,0,304,304,"2589","",0,"","","",9,0,0,[],""],["rm_t2-n2590",0,"Pensando en tí me dormí,\nRetrato del mismo cielo;\nDesperté y me hallé sin tí\nY eché á llorar sin consuelo.",0,0,-1,2,"",1,4,"eo",10,0,-1,0,304,304,"2590","",0,"","","",9,0,0,[],""],["rm_t2-n2591",0,"Estoy durmiendo y soñando\nQue estás á la vera mia;\nDespierto y me hallo sin tí;\nVuelvo á la misma fatiga.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,305,305,"2591","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2592",0,"Yo soñaba que en un trono\nReinando, mi bien, estabas,\nSentenciándome á morir,\nTan sólo porque te amaba.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,305,305,"2592","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2593",0,"Anoche soñé un ensueño\nY en el ensueño soñé\nQue m' habias orbidao....\n¡Si bieras cuánto yoré!",0,0,-1,2,"",0,4,"e",77,0,-1,0,305,305,"2593","",0,"","","",7,0,0,[],""],["rm_t2-n2594",0,"Si lo que sueño de noche\nDe dia lo ejecutara,\nA la casa de los locos\nDe seguro me llevaran.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,305,305,"2594","",0,"","","",2,0,0,[],""],["rm_t2-n2596",0,"En mis cortas orasiones\nLe pío á San Rafaé\nQu' en lo mejó de mi sueño\nMe dispierte tu queré.",0,0,-1,2,"",0,4,"e",77,0,-1,0,305,305,"2596","",0,"","","",1,0,0,[],""],["rm_t2-n2598",0,"Er leon con ser leon\nDisen que lo rinde 'r sueño;\nYo que soy criatura humana,\nDe pensar en tí no duermo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,306,306,"2598","",0,"","","",1,0,0,[],""],["rm_t2-n2599",0,"Compañeriya del arma,\nEr sueño no m' alimenta;\nDuermo soñando contigo\nY tu queré me dispierta.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,306,306,"2599","",0,"","","",2,0,0,[],""],["rm_t2-n2600",0,"Tu pare y tu mare disen\nQue no los dejo dormí;\nDentro e la casita tienen\nLa que no me deja á mí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,306,306,"2600","",0,"","","",1,0,0,[],""],["rm_t2-n2601",0,"Las campanas de maitines\nTodas las noches las cuento\nY pensando en tu querer\nPierdo las horas del sueño.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,306,306,"2601","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2603",0,"¿Hasta cuando, vida mia,\nTengo de vivir así?\nLas horitas de la noche\nMe las paso sin dormir.",0,0,-1,2,"",0,4,"i",-1,0,-1,0,306,306,"2603","",0,"","","",11,0,0,[],""],["rm_t2-n2604",0,"¿Hasta cuando, vida mia,\nTengo de vivir penando?\nLas horitas de la noche\nMe las llevo suspirando,",0,0,-1,2,"",0,4,"ao",33,0,-1,0,306,306,"2604","",0,"","","",11,0,0,[],""],["rm_t2-n2605",0,"Jamás pensé, vida mia,\nQuererte como te quiero;\nCuando me meto en la cama\nNo puedo cuajar el sueño.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,307,307,"2605","",0,"","","",4,0,0,[],""],["rm_t2-n2606",0,"E noche no duermo,\nE dia tampoco;\nSólo en pensá - 'n la mia compañera\nMe güerbo yo loco.",0,0,-1,2,"",3,4,"oo",152,0,-1,0,307,307,"2606","",0,"","","",1,0,0,[],""],["rm_t2-n2610",0,"No me mientes la comía\nNi me yames á comé;\nQue yo m' estoy manteniendo\nCon la raíz der queré.",0,0,-1,2,"",0,4,"e",77,0,-1,0,307,307,"2610","",0,"","","",1,0,0,[],""],["rm_t2-n2611",0,"Cuando me siento á la mesa\nDe pensar en tí no como;\nTus palabras me alimentan,\nTus labios me dan socorro.",0,0,-1,2,"",0,4,"oo",-1,0,-1,0,307,307,"2611","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n2612",0,"Me yamaban á comé\nY á la mesa me sentaba;\nY acordándome de tí\nLas ganas me se quitaban.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,307,308,"2612","",0,"","","",1,0,0,[],""],["rm_t2-n2614",0,"Muchas beses yo pensando\nEn er queré que te tengo\nMe yamo á mí y me pregunto\nEn qué bendrá á parar esto.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,308,308,"2614","",0,"","","",1,0,0,[],""],["rm_t2-n2615",0,"Cuando soliya t' encuentres\nPiensa 'rguna bes en mí.\n¡Bien sabe Dios, compañera,\nLo que m' espera sin tí!",0,0,-1,2,"",0,4,"i",23,0,-1,0,308,308,"2615","",0,"","","",1,0,0,[],""],["rm_t2-n2616",0,"Er má, con sé tan soberbio,\nS' asujeta ' la rason;\nYo asujetarme no pueo,\nQue me siega la pasion.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,308,308,"2616","",0,"","","",1,0,0,[],""],["rm_t2-n2617",0,"A la Bígen de los Reyes\nEr cabeyo l' ofresí\nPorque te borbieras loco\n' Tiraras piedras por mí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,308,308,"2617","",0,"","","",1,0,0,[],""],["rm_t2-n2618",0,"Sombra le pedí á una fuente\nY agua le pedí á un olibo;\nQue m' ha puesto tu queré,\nQue no sé lo que me digo.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,308,308,"2618","",0,"","","",3,0,0,[],""],["rm_t2-n2620",0,"Náide diga qu' hay locura,\nPorque si locura hubiera,\nAmarrao á una coluna\nMi cuerpesito estubiera.",0,0,-1,2,"",0,4,"ea",44,0,-1,0,309,309,"2620","",0,"","","",1,0,0,[],""],["rm_t2-n2621",0,"M' han dicho qu' estás malita,\nChiquiya, y que ya t' has muerto;\nYo te resusitaré\nCon er caló de mi pecho.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,309,309,"2621","",0,"","","",2,0,0,[],""],["rm_t2-n2622",0,"Serrana, si te murieras....\n¡Pero más bale que nó!\nLas serranas s' asombraran\nDer luto qu' echara yo.",0,0,-1,2,"",0,4,"o",2,0,-1,0,309,309,"2622","",0,"","","",2,0,0,[],""],["rm_t2-n2625",0,"Si supiera ó entendiera\nQu' era farso tu queré,\nCon los moritos me fuera\n' Renegara de la fé.",0,0,-1,2,"",1,4,"e",77,0,-1,0,309,309,"2625","",0,"","","",11,0,0,[],""],["rm_t2-n2626",0,"Mi cuerpo apuñalaito,\nPuesto por esos caminos,\nEso lo tienes e bé\nSi no me caso contigo.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,309,310,"2626","",0,"","","",1,0,0,[],""],["rm_t2-n2628",0,"A Jesús triste le rezo\nY ¿sabes lo que le pido?\nQue el dia que tú te mueras\nTambien me muera contigo.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,310,310,"2628","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2629",0,"El dia que tú nacistes\nAquel dia nací yo;\nEl dia que tú te mueras\nNos moriremos los dos.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,310,310,"2629","",0,"carrizo_salta","","",7,0,0,[],""],["rm_t2-n2630",0,"Dueño mio, si te vieres\nEn la presencia de Dios,\nLe pedirás que me muera,\nQue sin tí no vivo yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,310,310,"2630","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2631",0,"Al arto sielo subí,\nJise escritura con Dios\nQu' er dia que tú te mueras\nMe tengo de morir yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,310,310,"2631","",0,"","","",2,0,0,[],""],["rm_t2-n2632",0,"Tú encendistes el fuego\nDel pecho mio\nY ahora vas á apagarlo\nCon tus suspiros.\n¡Válgame el cielo,\nY qué poco que entiendes\nDe estos incendios!",0,0,-1,2,"",4,7,"eo",-1,0,-1,0,310,311,"2632","",0,"","","",2,0,0,[],""],["rm_t2-n2633",0,"Quítate de esa ventana,\nPorque voy á suspirar;\nMis suspiros son de fuego\nY te puedes abrasar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,311,311,"2633","",0,"carrizo_salta","","",6,0,0,[],""],["rm_t2-n2634",0,"Dame, Pepe, el pañuelo\n'Lo lavaré;\nCon suspiros del alma\nLo secaré.",0,0,-1,2,"",6,4,"e",77,0,-1,0,311,311,"2634","",0,"","","",1,0,0,[],""],["rm_t2-n2635",0,"De tu puerta á la mia\nVa una cadena\nFormada de suspiros,\nDe amores llena.\nVa un rio claro\nY los envidiosillos\nMe lo enturbiaron.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,311,311,"2635","",0,"","","",1,0,0,[],""],["rm_t2-n2636",0,"De tu corazon al mio\nHay una larga cadena\nToda llena de suspiros,\nDe suspiros toda llena.",0,0,-1,2,"",0,4,"ea",59,0,-1,0,311,311,"2636","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2637",0,"Suspiritos menuditos\nSalen de mi pecho triste\nY se meten en el tuyo\nComo granitos de alpiste.",0,0,-1,2,"",0,4,"ie",153,0,-1,0,311,311,"2637","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2638",0,"Suspiros, salid, salid\nY trasminad las paredes\nY mirad si está dormida\nLa reina de las mujeres.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,312,312,"2638","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2639",0,"Suspiros del corazon\nSalen de mi pecho ardiendo\nY se van á aposentar\nDonde está mi amor durmiendo.",0,0,-1,2,"",0,4,"eo",52,0,-1,0,312,312,"2639","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2640",0,"Si mis suspiros llegan\nA tu almohada,\nComo caritativa\nDales posada.",0,0,-1,2,"",6,4,"aa",49,0,-1,0,312,312,"2640","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2641",0,"Si en tu cara sintieres\nUn aire frio,\nSon suspiros del alma\nQue yo te envio.\nPorque en mi cuarto\nSuspirando y gimiendo\nPaso los ratos.",0,0,-1,2,"",4,7,"ao",-1,0,-1,0,312,312,"2641","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2642",0,"Si á media noche sintieres\nEn tu cara un aire frio,\nNo le eches la culpa al viento,\nQue son los suspiros mios.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,312,312,"2642","",0,"","","",3,0,0,[],""],["rm_t2-n2643",0,"Si llega hasta tí un suspiro,\nNo preguntes de quién es;\nDevuélveselo á su dueño,\nQue yo lo recibiré.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,312,312,"2643","",0,"","","",1,0,0,[],""],["rm_t2-n2644",0,"Vuela, pensamiento mio,\nAl lecho de mis amores\nY la estancia de mi dueño\nPerfúmala con olores.",0,0,-1,2,"",0,4,"oe",5,0,-1,0,313,313,"2644","",0,"","","",3,0,0,[],""],["rm_t2-n2645",0,"Si tuviera figura\nMi pensamiento,\nSiempre te lo encontraras\nEn tu aposento.",0,0,-1,2,"",6,4,"eo",94,0,-1,0,313,313,"2645","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2646",0,"El tiempo que he vivido\nSin conocerte\nMe ha sido noche triste;\nYa es dia alegre.\nY si me olvidas,\nVolverán á ser noches\nTodos mis dias.",0,0,-1,2,"",4,7,"a",-1,0,-1,0,313,313,"2646","",0,"","","",2,0,0,[],""],["rm_t2-n2649",0,"No olvides un momento\nMi fiel cariño,\nQue te quise, mi vida,\nDesde muy niño.\nQuiéreme siempre,\nQue mi dicha se encuentra\nDe tí pendiente.",0,0,-1,2,"",4,7,"ee",-1,0,-1,0,313,313,"2649","",0,"","","",1,0,0,[],""],["rm_t2-n2651",0,"Un hábito de Dolores\nOfrecí por tu salú;\nAhora que te has puesto bueno,\nNo me olvides, por Jesús.",0,0,-1,2,"",0,4,"u",-1,0,-1,0,314,314,"2651","",0,"","","",1,0,0,[],""],["rm_t2-n2653",0,"Por aqueya cruz bendita\nQu' está en aquer campanario,\nNo m' orbíes, hermanita,\nQue con otra no m' apaño.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,314,314,"2653","",0,"","","",1,0,0,[],""],["rm_t2-n2654",0,"Si me quieres ver morir\nSin calentura y sin mal,\nNo tienes más que decir\nQue me quieres olvidar.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,314,314,"2654","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t2-n2655",0,"Si me quieres dar la muerte,\nOrbídame, prenda mia;\nQue no hay cuchiyo más fuerte\nPara quitarme la bia.",0,0,-1,2,"",1,4,"a",0,0,-1,0,314,314,"2655","",0,"","","",1,0,0,[],""],["rm_t2-n2656",0,"De terciopelo negro\nTengo cortinas,\nPara enlutar mi cuarto\nSi tú me olvidas.",0,0,-1,2,"",6,4,"ia",-1,0,-1,0,314,314,"2656","",0,"palau_cantares","","",7,0,0,[],""],["rm_t2-n2657",0,"Mañana boy á cabirdo\nA ber echar er sorteo\nY si le toca á mi amante,\nDiré que por ér me queo.",0,0,-1,2,"",0,4,"eo",66,0,-1,0,315,315,"2657","",0,"","","",1,0,0,[],""],["rm_t2-n2658",0,"Si soldado salieres\nEn esta quinta,\nPara tu charretera\nTengo yo cinta.",0,0,-1,2,"",6,4,"ia",155,0,-1,0,315,315,"2658","",0,"","","",1,0,0,[],""],["rm_t2-n2659",0,"He salido por soldado\nY no tengo escarapela;\nDame una gota de sangre\nDe tu corazon, morena.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,315,315,"2659","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2660",0,"Me quisistes moso y libre,\nTambien me querrás sordao;\nQue tú no despresiarás\nLo qu' er rey no ha despresiao.",0,0,-1,2,"",0,4,"ao",98,0,-1,0,315,315,"2660","",0,"","","",1,0,0,[],""],["rm_t2-n2661",0,"Cuando estoy de sentinela\nY te pones junto á mí,\nMe s' orbia la consinia\nY me s' ispara er fusí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,315,315,"2661","",0,"","","",1,0,0,[],""],["rm_t2-n2662",0,"Acaba de dar, acaba,\nReló de la catedrá,\nQu' está mi amante de guardia\nY lo ban á relebá.",0,0,-1,2,"",0,4,"a",9,0,-1,0,315,315,"2662","",0,"","","",8,0,0,[],""],["rm_t2-n2663",0,"¡Biba Cádiz, biba er Puerto,\nBiba Sanlúca y J eré!\n¡Biba quien pasa en er mundo\nPenas por una mujé!",0,0,-1,2,"",0,4,"e",77,0,-1,0,315,315,"2663","",0,"","","",1,0,0,[],""],["rm_t2-n2664",0,"Para los hombres se hisieron\nLos griyos y las caenas;\n¡Biba tô aquer que las sufre\nPor una cara morena!",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,316,316,"2664","",0,"","","",1,0,0,[],""],["rm_t2-n2666",0,"Tengo una pesadumbre\nQue al alma llega;\n¡Viva quien me la ha dado,\nAunque yo muera!",0,0,-1,2,"",6,4,"ea",-1,0,-1,0,316,316,"2666","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2667",0,"Por tu queré 'stoy pasando\nMir peniyas y tormentos;\n¡Bengan penas! ¡Bengan penas!\n¡Biba er queré y er salero!",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,316,316,"2667","",0,"","","",1,0,0,[],""],["rm_t2-n2668",0,"Las penas que por tí paso\nNo me salen á la cara;\nComo las paso por tí,\nLas paso ele buena gana.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,316,316,"2668","",0,"","","",7,0,0,[],""],["rm_t2-n2669",0,"Las penas que por tí paso\nLas voy echando en un pozo;\nMe hago la cuenta y digo:\n-Las paso por un buen mozo.",0,0,-1,2,"",0,4,"oo",156,0,-1,0,316,316,"2669","",0,"","","",7,0,0,[],""],["rm_t2-n2670",0,"Te quiero y sé que nunca\nSeré tu dueño;\n¡Eso sí que es fineza\nDe amor sin premio!",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,316,316,"2670","",0,"","","",2,0,0,[],""],["rm_t2-n2671",0,"Te quiero sin que me quieras,\nQue es verdadero querer;\nQue querer porque nos quieran\nEs querer por interés.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,317,317,"2671","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2672",0,"Un imposible adoro,\nQue es de discretos;\nLas posibilidades\nLas ama un necio.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,317,317,"2672","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t2-n2673",0,"Un imposible adoro\nTan imposible,\nQue es imposible hallarlo\nMás imposible.\nAsí lo quiero;\nQue el amor imposible\nEs verdadero.",0,0,-1,2,"",4,7,"eo",38,0,-1,0,317,317,"2673","",0,"","","",4,0,0,[],""],["rm_t2-n2674",0,"Un imposible me mata;\nPor un imposible muero;\nImposible es alcanzar\nEl imposible que quiero.",0,0,-1,2,"",0,4,"eo",38,0,-1,0,317,317,"2674","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n2675",0,"A mi corazon le pego\nY á solas riño con él\nY el pícaro me responde:\n-Muero por un querer bien.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,317,317,"2675","",0,"","","",1,0,0,[],""],["rm_t2-n2676",0,"Deseo que me mandes,\nPorque conoicas\nQue mis ofrecimientos\nNo son lisonjas.",0,0,-1,2,"",6,4,"oa",-1,0,-1,0,317,317,"2676","",0,"","","",1,0,0,[],""],["rm_t2-n2677",0,"Quisiera que me mandaras\nEn que poderte servir\nY entónces vieras á un hombre\nPor una mujer morir.",0,0,-1,2,"",0,4,"i",157,0,-1,0,318,318,"2677","",0,"","","",1,0,0,[],""],["rm_t2-n2678",0,"Mándame, niña, que vaya\nA la gran Costantinopla\nY verás como te traigo\nDel Gran Turco la corona.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,318,318,"2678","",0,"","","",3,0,0,[],""],["rm_t2-n2679",0,"Si me mandaras morir,\nAl momento me muriera;\n¿Qué me mandaras tú á mí,\nSalero, que yo no hiciera?",0,0,-1,2,"",0,4,"ea",44,0,-1,0,318,318,"2679","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2680",0,"¿Quieres que baya á la mar\nPor ser la parte más jonda,\nCoja los peses bibitos\nY en la mano te los ponga?",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,318,318,"2680","",0,"","","",1,0,0,[],""],["rm_t2-n2681",0,"¿Sabes á lo que m' atrebo,\nChiquiya, por tu queré?\nA meterme en los infiernos\nY hablar con er Lusifé.",0,0,-1,2,"",0,4,"e",77,0,-1,0,318,318,"2681","",0,"","","",1,0,0,[],""],["rm_t2-n2684",0,"Más humirde que la tierra\nMe parió mi madre á mí;\nDime, niña, quien t' ofende;\n¡Berás á un leon reñí!",0,0,-1,2,"",0,4,"i",23,0,-1,0,319,319,"2684","",0,"","","",1,0,0,[],""],["rm_t2-n2685",0,"Si supiera ó entendiera\nQu' er só que sale t' ofende,\nCon er só me peleara,\nAnque 'r só me diera muerte.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,319,319,"2685","",0,"","","",11,0,0,[],""],["rm_t2-n2686",0,"Si supiera que los santos\nDe la ilesia t' ofendian,\nAnque me recondenara,\nN' oyera misa en la bia.",0,0,-1,2,"",5,4,"a",-1,0,-1,0,319,319,"2686","",0,"","","",1,0,0,[],""],["rm_t2-n2687",0,"Si m' entero qu' argun guapo\nSe mete con mi lusero,\nLe doy más puñalaítas\nQue estreyitas tiene 'r sielo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,319,319,"2687","",0,"","","",1,0,0,[],""],["rm_t2-n2689",0,"Una fragata argelina\nA mi dama cautivó;\nAunque me cueste la vida,\nHe de rescatarla yo.",0,0,-1,2,"",0,4,"o",2,0,-1,0,319,319,"2689","",0,"","","",1,0,0,[],""],["rm_t2-n2690",0,"Los mositos de mi barrio\nDisen que no soy baliente;\nContéstales tú, morena,\nQue m' h' atrebío á quererte.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,320,320,"2690","",0,"","","",1,0,0,[],""],["rm_t2-n2691",0,"Yo te vengo á visitar\nCon la mejor intencion\nY al que quisiere estorbarlo\nLe arrancaré el corazon.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,320,320,"2691","",0,"","","",1,0,0,[],""],["rm_t2-n2692",0,"Ar que m' estorba quererte\nEn tu caye mataré;\nSi bes ar salí una crú\nNo preguntes por quién es.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,320,320,"2692","",0,"","","",1,0,0,[],""],["rm_t2-n2693",0,"Si yo abiyelara er mando\nQue Undebé le dió á la muerte,\nYo quitara d' este mundo\nAr que m' estorba er quererte.",0,0,-1,2,"",0,4,"ee",134,0,-1,0,320,320,"2693","",0,"","","",1,0,0,[],""],["rm_t2-n2694",0,"Si con er mirá t ' ofendo,\nMe lo mandas á desí;\nYo me sartaré los ojos,\nPor no darte que sentí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,320,320,"2694","",0,"","","",2,0,0,[],""],["rm_t2-n2695",0,"Si con er mirá t ' ofendo\nY con el hablá t' agrabio,\nYo me sartaré los ojos\nY me coseré los labios.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,320,320,"2695","",0,"","","",2,0,0,[],""],["rm_t2-n2696",0,"Si mis ojos te dan penas,\nYo los aprisionaré;\nLos meteré entre cadenas,\nDonde penas no te den.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,320,320,"2696","",0,"","","",1,0,0,[],""],["rm_t2-n2697",0,"Si mis ojos te ofenden,\nYo te prometo\nPor que no te molesten,\nAmarte ciego.\nMas te suplico\nQue en tal lance me sirvas\nDe lazarillo.",0,0,-1,2,"",4,7,"io",-1,0,-1,0,321,321,"2697","",0,"","","",1,0,0,[],""],["rm_t2-n2699",0,"Si la sangre de mis venas\nLa hubieres de menester,\nBien puedes contar con ella,\nQue yo me la sacaré.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,321,321,"2699","",0,"","","",3,0,0,[],""],["rm_t2-n2701",0,"Ar peligro de la muerte\nPor mi queré t' has espuesto;\nYo sacaré de mi sangre\nCardo para tu alimento.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,321,321,"2701","",0,"","","",1,0,0,[],""],["rm_t2-n2702",0,"Si no tenías dinero,\n¿Por qué no me lo pedias\nY á la bos der pregonero\nMis carnes se benderian?",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,321,321,"2702","",0,"","","",1,0,0,[],""],["rm_t2-n2703",0,"Si con bender yo mis carnes\nTubiera alibio tu pena,\nA la bos der pregonero\nPor las cayes se bendieran.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,321,321,"2703","",0,"","","",1,0,0,[],""],["rm_t2-n2704",0,"Los ojitos e mi cara\nPor tí los boy á bendé;\nCuando los ojitos bendo,\nPor tí, ¿qué no benderé?",0,0,-1,2,"",0,4,"e",77,0,-1,0,322,322,"2704","",0,"","","",1,0,0,[],""],["rm_t2-n2705",0,"Si mis ojitos te bieran\nEn desgrasia á tí argun dia,\nLa ropita de mi cuerpo\nCon gusto la benderia.",0,0,-1,2,"",5,4,"ea",-1,0,-1,0,322,322,"2705","",0,"","","",1,0,0,[],""],["rm_t2-n2706",0,"Mi ropita bendo;\n¿Quién la quie mercá?\nComo la bendo - por poquito inero,\nPa tu libertá.",0,0,-1,2,"",3,4,"a",9,0,-1,0,322,322,"2706","",0,"","","",1,0,0,[],""],["rm_t2-n2707",0,"Jasta 'l agua der bautismo\nLa empeñé por tu queré;\nSi no es berdá lo que digo,\nMala puñala me den.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,322,322,"2707","",0,"","","",1,0,0,[],""],["rm_t2-n2711",0,"A la niña de mis ojos\nLe digo que no se ofenda;\nQue si lo hace por dinero,\nSu esclavo soy: que me venda.",0,0,-1,2,"",0,4,"ea",159,0,-1,0,322,323,"2711","",0,"","","",1,0,0,[],""],["rm_t2-n2712",0,"Quisiera ser tu lacayo\nY que me echaras un hierro,\nHermoso clavel dorado,\nPor lo mucho que te quiero.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,323,323,"2712","",0,"","","",2,0,0,[],""],["rm_t2-n2714",0,"Si el rey de España me diera\nEl mando de su corona,\nNo lo apreciara yo tanto\nComo aprecio tu persona.",0,0,-1,2,"",0,4,"oa",7,0,-1,0,323,323,"2714","",0,"","","",2,0,0,[],""],["rm_t2-n2715",0,"Emperadores y reyes\nPor tí despreciara yo,\nPorque tú solo, solito\nReinas en mi corazon.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,323,323,"2715","",0,"","","",1,0,0,[],""],["rm_t2-n2716",0,"Aunque á mí me pretendieran\nPríncipes y generales,\nA tu pobreza me rindo,\nQue yo no quiero caudales.",0,0,-1,2,"",0,4,"ae",26,0,-1,0,323,323,"2716","",0,"","","",1,0,0,[],""],["rm_t2-n2717",0,"Yo no quiero más caudales\nQue dormir contigo un sueño\nY tener por cabesera\nLas trensitas e tu pelo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,323,323,"2717","",0,"","","",1,0,0,[],""],["rm_t2-n2719",0,"No quiero coches ni mulas,\nNi haciendas ni mayorazgos;\nLo que quiero es mi moreno\nTenerlo siempre á mi lado.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,324,324,"2719","",0,"","","",1,0,0,[],""],["rm_t2-n2721",0,"Soy más rico siendo pobre\nQue 'r rey labrando monea:\nTengo er caudá de mi gusto\nY ¿á qué quiero más riquesa?",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,324,324,"2721","",0,"","","",3,0,0,[],""],["rm_t2-n2722",0,"Yo soy más rico que Leria\nY que Martin er pañero;\nTengo er caudá de mi gusto\nY me rio der dinero.",0,0,-1,2,"",0,4,"eo",38,0,-1,0,324,324,"2722","",0,"","","",2,0,0,[],""],["rm_t2-n2723",0,"Náide s' espante 'n er mundo\nDe lo que yo estoy jasiendo;\nEr pagarme de mi gusto,\nEse eser caudá que tengo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,324,324,"2723","",0,"","","",1,0,0,[],""],["rm_t2-n2725",0,"En mi alma manda Dios\nY en mi persona mis padres;\nEn mi gusto mando yo\nY sobre mi gusto nádie.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,325,325,"2725","",0,"","","",4,0,0,[],""],["rm_t2-n2726",0,"Mi padre y mi madre son\nDueños de lo que yo gano;\nPero de mi personita\nYo solito soy el amo.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,325,325,"2726","",0,"","","",7,0,0,[],""],["rm_t2-n2727",0,"Sobre mi gusto, canela;\nSobre mi gusto, azafran;\nSobre mi gusto ha de ser;\nSobre mi gusto será.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,325,325,"2727","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2729",0,"Jasta que no t' emborrachas\nNo bienes en busca mia;\nOjalay t' emborracharas\nToitas las horas der dia.",0,0,-1,2,"",0,4,"a",0,0,-1,0,325,325,"2729","",0,"","","",1,0,0,[],""],["rm_t2-n2731",0,"Te miro d' arriba 'bajo\nY luégo me miro yo;\nAleria me da 'r berte\nY peniya er berme yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,326,326,"2731","",0,"","","",1,0,0,[],""],["rm_t2-n2733",0,"Dicen que ya no me quieres;\nCon dejarte, se acabó;\nNo quiero que pases penas,\nDueño de mi corazon.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,326,326,"2733","",0,"","","",9,0,0,[],""],["rm_t2-n2734",0,"Yo sé que por mi querer\nTus padres te dan pesares;\nQuédate con Dios, perlita;\nNo quiero que tú lo pagues.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,326,326,"2734","",0,"","","",1,0,0,[],""],["rm_t2-n2735",0,"Si porque te quiero quieres\nQue yo la muerte reciba,\nCúmplase tu voluntad:\nMuera yo por que otro viva.",0,0,-1,2,"",0,4,"ia",53,0,-1,0,326,326,"2735","",0,"","","",11,0,0,[],""],["rm_t2-n2736",0,"No me mates con cuchiyo\nQue tenga 'l asero fuerte;\nMátame con un suspiro\nY te perdono la muerte.",0,0,-1,2,"",0,4,"ee",134,0,-1,0,327,327,"2736","",0,"","","",2,0,0,[],""],["rm_t2-n2737",0,"No me mates con cuchiyo,\nQu' el asero es enconoso;\nMátame con un suspiro\nDe tu corason hermoso.",0,0,-1,2,"",0,4,"oo",160,0,-1,0,327,327,"2737","",0,"","","",2,0,0,[],""],["rm_t2-n2738",0,"Dicen que me has de matar\nCon un puñal valenciano;\nYo te perdono la muerte,\nSi me matas mano á mano.",0,0,-1,2,"",0,4,"ao",81,0,-1,0,327,327,"2738","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2740",0,"Mi corazon por tí muere,\nMi alma se sujeta á tí,\nSerrana, y mi cuerpo dice:\nHaz lo que quieras de mí.",0,0,-1,2,"",0,4,"i",23,0,-1,0,327,327,"2740","",0,"","","",1,0,0,[],""],["rm_t2-n2741",0,"En todo lo que quieras\nYo me resigno\nY en la ara de tu gusto\nMe sacrifico.\nSiendo la ofrenda\nMi cariño constante\nY mi obediencia.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,327,327,"2741","",0,"","","",1,0,0,[],""],["rm_t2-n2742",0,"Es mi gusto tu gusto\nDe tal manera,\nQue lo que gustas gusto;\nSi nó, á la prueba.",0,0,-1,2,"",6,4,"ea",-1,0,-1,0,327,328,"2742","",0,"","","",1,0,0,[],""],["rm_t2-n2743",0,"Me pediste la mano,\nTe la dí al punto;\n¡Mira si tendré ganas\nDe darte gusto!",0,0,-1,2,"",6,4,"uo",-1,0,-1,0,328,328,"2743","",0,"","","",1,0,0,[],""],["rm_t2-n2744",0,"Ronca estoy, cantar no puedo....\nPorqu' está mi amor delante,\nQue me está jasiendo señas\nQue estoy ronca y que no cante.",0,0,-1,2,"",0,4,"ae",47,0,-1,0,328,328,"2744","",0,"","","",1,0,0,[],""],["rm_t2-n2745",0,"Me dijistes por señas\nQue no cantara\nY yo, por darte gusto,\nMe fingí mala.\nQue estoy dispuesta\nA no darte disgustos,\nAunque lo sienta.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,328,328,"2745","",0,"","","",1,0,0,[],""],["rm_t2-n2746",0,"Si la justicia me ordena\nQue yo merezca prision,\nQue me lleve enhorabuena\nA la cárcel de tu amor.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,328,328,"2746","",0,"","","",1,0,0,[],""],["rm_t2-n2747",0,"Si tu casa fuera cárcel\nY tu cuarto calabozo\nY tus brazos la cadena,\nYo prisionero gustoso.",0,0,-1,2,"",0,4,"oo",160,0,-1,0,328,328,"2747","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2748",0,"Toda mi vida estuviera\nPreso en la cárcel de amor,\nSiendo tú la carcelera\nY yo el alguacil mayor.",0,0,-1,2,"",1,4,"o",72,0,-1,0,328,328,"2748","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2749",0,"Si tu casa fuera cárcel\nY tú, niña, carcelera,\nSan Pedro lleve mi alma\nSi de la cárcel saliera.",0,0,-1,2,"",0,4,"ea",44,0,-1,0,329,329,"2749","",0,"","","",5,0,0,[],""],["rm_t2-n2750",0,"En el hoyo de tu barba\nQuisiera verme dormido,\nPara ver de cuando en cuando\nSi dabas algun suspiro.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,329,329,"2750","",0,"lafuente_madrid","","",7,0,0,[],""],["rm_t2-n2751",0,"¡Quién tuviera un cordon de oro\nTan largo como esta calle,\nPara sacar á una niña\nDel dominio de su padre!",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,329,329,"2751","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2752",0,"Quisiera ser poderoso\nY mantenerte en el aire,\nY ya que yo no te gozo,\nQue no te gozara nádie\n[Regalado dueño hermoso].",0,0,-1,2,"",7,5,"oo",160,0,-1,0,329,329,"2752","",0,"","","",3,0,0,[],""],["rm_t2-n2753",0,"Si yo fuera basilisco,\nCon la vista te matara\nY te sacara del mundo,\nPa que nádie te gozara.",0,0,-1,2,"",0,4,"aa",57,0,-1,0,329,329,"2753","",0,"","","",4,0,0,[],""],["rm_t2-n2754",0,"En el campito llueve;\nMi amor se moja;\n¡Quién fuera chaparrito\nCubierto de hojas!",0,0,-1,2,"",6,4,"oa",-1,0,-1,0,329,329,"2754","",0,"","","",1,0,0,[],""],["rm_t2-n2755",0,"Si supiera que estaba\nMi amor segando,\nLe llevara un pañuelo\nPara en sudando.",0,0,-1,2,"",6,4,"ao",33,0,-1,0,329,329,"2755","",0,"","","",1,0,0,[],""],["rm_t2-n2756",0,"Mi amante está segando;\n¡Vírgen divina!\n¡Quién pudiera ponerle\nAl sol cortinas!",0,0,-1,2,"",6,4,"ia",-1,0,-1,0,330,330,"2756","",0,"","","",2,0,0,[],""],["rm_t2-n2757",0,"Si me volviera paloma,\n¡Qué gustosa que quedara!\nDentro de tu corazon\nAllí mi nido formara.",0,0,-1,2,"",0,4,"aa",57,0,-1,0,330,330,"2757","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2758",0,"Lágrima de tus ojos\nQuisiera yo ser\nY correr por tu cara\nY al pecho caer.\nEn él entrara\nY en tu corazoncito\nMe aposentara.",0,0,-1,2,"",4,7,"aa",57,0,-1,0,330,330,"2758","",0,"","","",1,0,0,[],""],["rm_t2-n2759",0,"Envidia le tengo al oro\nQue tienes en tus zarcillos,\nPorque siempre está besando\nEsos divinos carrillos.",0,0,-1,2,"",0,4,"io",161,0,-1,0,330,330,"2759","",0,"","","",3,0,0,[],""],["rm_t2-n2760",0,"¡Quién fuera peine en tu pelo,\nY alfiler de tu pechera,\nY ruedo de tus enaguas,\nY lazo de tus chinelas!",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,330,330,"2760","",0,"","","",1,0,0,[],""],["rm_t2-n2761",0,"¡Quién fuera fino coral,\nPerla de tu gargantilla,\nDe tu cintura clavete,\nDe tu zapato la hebilla!",0,0,-1,2,"",0,4,"ia",162,0,-1,0,330,330,"2761","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2762",0,"¡Quién tuviera la dicha\nQue tiene la luz,\nQue se apaga y se queda\nDonde duermes tú!",0,0,-1,2,"",0,4,"u",-1,0,-1,0,330,331,"2762","",0,"huambachano","","",7,0,0,[],""],["rm_t2-n2763",0,"¡Quién tuviera la dicha\nQue tiene el candil,\nQue de noche se queda\nTan cérca de tí!",0,0,-1,2,"",0,4,"i",-1,0,-1,0,331,331,"2763","",0,"","","",7,0,0,[],""],["rm_t2-n2764",0,"Quisiera ser clavo de oro\nDonde cuelgas el candil,\nPara ver tu fino pecho\nCuando te vas á dormir.",0,0,-1,2,"",0,4,"i",-1,0,-1,0,331,331,"2764","",0,"","","",1,0,0,[],""],["rm_t2-n2765",0,"¡Quién fuera rayo de sol\nY por tu ventana entrara\nY te ayudara á ponerte\nMedias, zapatos y enaguas!",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,331,331,"2765","",0,"","","",1,0,0,[],""],["rm_t2-n2766",0,"Quisiera ser ingeniero,\nPara ver de qué manera\nPodia entrar en tu cuarto,\nSentarme á tu cabecera.",0,0,-1,2,"",0,4,"ea",44,0,-1,0,331,331,"2766","",0,"","","",3,0,0,[],""],["rm_t2-n2767",0,"Quisiera que de noche\nFueran papeles\nLas paredes del cuarto\nDonde tú duermes.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,331,331,"2767","",0,"","","",1,0,0,[],""],["rm_t2-n2768",0,"Quisiera borberme yedra\nY trasminar tus paderes,\nSentarme á tu cabesera\nY ber er dormir que tienes.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,331,331,"2768","",0,"","","",1,0,0,[],""],["rm_t2-n2769",0,"Subiré como hiedra\nPor las paredes,\nHasta llegar al sitio\nDonde tú duermes.\nPero en llegando,\nSe aliviarán mis penas\nContigo hablando.",0,0,-1,2,"",4,7,"ao",33,0,-1,0,332,332,"2769","",0,"","","",1,0,0,[],""],["rm_t2-n2770",0,"Quisiera ser por un rato\nCinta de tu delantal,\nPara estrechar en mis brazos\nEse talle tan galan.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,332,332,"2770","",0,"","","",9,0,0,[],""],["rm_t2-n2771",0,"Arcarrasa de tu casa,\nChiquiya, quisiera ser,\nPara besarte los labios\nCuando fueras á beber.",0,0,-1,2,"",0,4,"e",20,0,-1,0,332,332,"2771","",0,"","","",1,0,0,[],""],["rm_t2-n2773",0,"Quisiera morirme pronto\nY ángel del cielo volverme\nY ser ángel de la guarda\nY estar á tu lado siempre.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,332,332,"2773","",0,"","","",2,0,0,[],""],["rm_t2-n2774",0,"Si tu cara fuera iglesia\nY tu cuarto fuera altar\nY tu cama sepultura,\nVivo me fuera á enterrar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,332,332,"2774","",0,"","","",1,0,0,[],""],["rm_t2-n2775",0,"Quisiera ser el sepulcro\nDonde á tí te han de enterrar,\nPara tenerte en mis brazos\nPor toda la eternidad.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,333,333,"2775","",0,"","","",1,0,0,[],""],["rm_t2-n2776",0,"¿Cuándo querrá Dios der sielo\nQue yo t' encuentre en la caye\nY te diga:-Mira, oye,\n¿Dónde pusistes la yabe?",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,333,333,"2776","",0,"","","",4,0,0,[],""],["rm_t2-n2777",0,"¡Cuándo querrá Dios der sielo\nQue yo t' encuentre 'n la plasa\nY te diga:-Mira, oye,\nDame la yabe de casa!",0,0,-1,2,"",0,4,"aa",123,0,-1,0,333,333,"2777","",0,"","","",4,0,0,[],""],["rm_t2-n2778",0,"¡Cuándo querrá Dios del cielo\nY la Vírgen del Pilar\nQue tu ropita y la mia\nVayan juntas á lavar!",0,0,-1,2,"",0,4,"a",-1,0,-1,0,333,333,"2778","",0,"","","",11,0,0,[],""],["rm_t2-n2779",0,"¡Cuándo querrá la Vírgen\nDe las Angustias\nQue tu ropa y la mia\nSe doblen juntas!\nDe los Dolores\nQue tu ropa y la mia\nJuntas se doblen!",0,0,-1,2,"",4,7,"oe",-1,0,-1,0,333,333,"2779","",0,"","","",6,0,0,[],""],["rm_t2-n2780",0,"¡Cuándo quedrá la Bínge\nDer Mayó Doló\nQue los cabeyos - e mi compañera\nLos peinara yo!",0,0,-1,2,"",3,4,"o",2,0,-1,0,333,333,"2780","",0,"","","",1,0,0,[],""],["rm_t2-n2781",0,"¡Cuándo yegará er dia\nQue diga er cura:\n-¿Quiere usté á esta señora\nPor mujer suya?",0,0,-1,2,"",6,4,"ua",-1,0,-1,0,334,334,"2781","",0,"","","",1,0,0,[],""],["rm_t2-n2782",0,"¡Cuándo querrá Dios der sielo\nQue mos digan á los dos:\n-¿Resib' usté?-Sí resibo.\n-¿Otorga usté?-Sí señó!",0,0,-1,2,"",0,4,"o",-1,0,-1,0,334,334,"2782","",0,"","","",4,0,0,[],""],["rm_t2-n2783",0,"¡Cuándo querrá Dios der sielo\nY la Bírgen d' ayá 'rriba\nQue te coja de la mano\nY diga:-Esta prenda es mia!",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,334,334,"2783","",0,"","","",4,0,0,[],""],["rm_t2-n2784",0,"¡Cuándo llegará aquel dia\nY aquella feliz mañana\nQue nos lleven á los dos\nEl chocolate á la cama!",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,334,334,"2784","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2785",0,"¡Qué consuelo y qué dulzura\nSerá tenerte á mi lado!\n¡Cuándo llegará aquel dia\nPara mí tan deseado!",0,0,-1,2,"",0,4,"ao",14,0,-1,0,334,334,"2785","",0,"","","",3,0,0,[],""],["rm_t2-n2786",0,"Toda la noche velo\nConsiderando\nCuándo serás tú mia,\nYo tuyo cuándo.",0,0,-1,2,"",6,4,"ao",33,0,-1,0,334,334,"2786","",0,"","","",2,0,0,[],""],["rm_t2-n2787",0,"Deseando estoy que yegue\nEr dia de nuestra union,\nPara estrecharte 'n mis brasos,\nPrenda de mi corason.",0,0,-1,2,"",5,4,"ao",-1,0,-1,0,334,334,"2787","",0,"","","",3,0,0,[],""],["rm_t2-n2788",0,"¡Mi arma sí qu' estará\nGososa d' haber nasío,\nPara morir en tus brasos,\nCuando Dios fuere serbío!",0,0,-1,2,"",0,4,"io",3,0,-1,0,335,335,"2788","",0,"","","",1,0,0,[],""],["rm_t2-n2790",0,"Tengo yo mi corazon\nHechito cuatro pedazos;\nPero me queda el consuelo\nQue he de morir en tus brazos.",0,0,-1,2,"",0,4,"ao",132,0,-1,0,335,335,"2790","",0,"palau_cantares, lafuente_madrid","","",14,0,0,[],""],["rm_t2-n2791",0,"¿Sabes por qué no me caso,\nConsiderándote á tí?\nPorque en viéndome en tus brazos,\nPienso que me he de morir.",0,0,-1,2,"",0,4,"i",-1,0,-1,0,335,335,"2791","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2792",0,"Ten pasiensia, sufre y caya,\nLe digo á mi corason;\nQue en sus amorosos brasos\nArgun dia 'staré yo.",0,0,-1,2,"",5,4,"o",-1,0,-1,0,335,335,"2792","",0,"","","",1,0,0,[],""],["rm_t2-n2793",0,"Ten pasiensia, dueño mio,\nQue ya bendrá la ocasion\nQu' en tus amorosos brasos\nDescanse mi corason.",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,335,335,"2793","",0,"","","",1,0,0,[],""],["rm_t2-n2794",0,"Penas, angustias, quebrantos,\nDesazones rigorosas;\nTodo lo paso con gusto,\nCon tal que seas mi esposa.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,335,335,"2794","",0,"","","",1,0,0,[],""],["rm_t2-n2795",0,"Tú penar y yo penar,\nTodo es penar, vida mia;\nAlgun dia los pesares\nSe han de volver alegría.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,336,336,"2795","",0,"","","",3,0,0,[],""],["rm_t2-n2796",0,"No estés triste ni llorosa;\nAlégrate, vida mia;\nQue algun dia querrá Dios\nQue tengamos alegría.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,336,336,"2796","",0,"","","",1,0,0,[],""],["rm_t2-n2797",0,"Argun dia querrá Dios\nQue la Pascua caiga en biérnes\nY la luna en tu tejao\nY yo en la cama en que duermes.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,336,336,"2797","",0,"","","",2,0,0,[],""],["rm_t2-n2799",0,"Mirando estoy desde aquí\nLa que tiene de ser mía;\nLa que tiene de juntar\nSu carita con la mia.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,336,336,"2799","",0,"","","",4,0,0,[],""],["rm_t2-n2800",0,"Encimita de la frente\nTe lo tengo de escribir:\nPondré una A y una M\nY entre las dos una I.",0,0,-1,2,"",0,4,"i",-1,0,-1,0,336,336,"2800","",0,"","","",1,0,0,[],""],["rm_t2-n2801",0,"El dia que nos casemos,\nBello fin de mi alegría,\nTengo de armar un festejo\nQue ha de durar cuatro dias.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,336,336,"2801","",0,"","","",1,0,0,[],""],["rm_t2-n2802",0,"El dia que yo me case\nContigo, dueño querido,\nDe alegría y de placer\nPienso perder el sentido.",0,0,-1,2,"",0,4,"io",101,0,-1,0,337,337,"2802","",0,"","","",3,0,0,[],""],["rm_t2-n2803",0,"Como triste mariposa\nCamino de noche y dia,\nHasta que quieran los cielos\nQue te publiquen por mia.",0,0,-1,2,"",0,4,"a",0,0,-1,0,337,337,"2803","",0,"","","",3,0,0,[],""],["rm_t2-n2804",0,"Vivo con la esperanza\nDe ser tu dueño\nY por eso me visto\nDe verde y negro.\nVerde, esperanza;\nY lo negro es el luto\nDe la tardanza.",0,0,-1,2,"",4,7,"aa",163,0,-1,0,337,337,"2804","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t2-n2805",0,"Compañerita del arma,\n¡Qué penita pasa aquér\nQue tiene el agua en los labios\nY no la puede beber!",0,0,-1,2,"",0,4,"e",20,0,-1,0,337,337,"2805","",0,"","","",2,0,0,[],""],["rm_t2-n2806",0,"Tengo enfrente la fuente\nDe mi deseo;\nTengo sed, veo el agua\nY no la bebo.\n¡Mira qué pena:\nTener sed, ver el agua\nY no beberla!",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,337,337,"2806","",0,"","","",1,0,0,[],""],["rm_t2-n2807",0,"La fuente del deseo\nLa tengo enfrente;\nTengo sed y no puedo\nSatisfacerme.\nLa tengo cérca;\nTengo sed y no puedo\nSatisfacerla.",0,0,-1,2,"",4,7,"ea",-1,0,-1,0,337,338,"2807","",0,"","","",1,0,0,[],""],["rm_t2-n2808",0,"¡Ay, que me muero de sé,\nTeniendo un poso en mi casa\nY no la puedo beber\nPorque la soga no arcansa!",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,338,338,"2808","",0,"","","",1,0,0,[],""],["rm_t2-n2809",0,"Soy pájaro qu' en el agua\nTengo el alimento mio\nY no la pueo bebé,\nSiendo del agua nasío.",0,0,-1,2,"",0,4,"io",3,0,-1,0,338,338,"2809","",0,"","","",1,0,0,[],""],["rm_t2-n2811",0,"Con mirar aquel sauce\nQue está en el rio\nComprenderás la pena\nDel pecho mio.\nPues aquel sauce\nEstá cérca y no goza\nDe sus cristales.",0,0,-1,2,"",4,7,"ae",-1,0,-1,0,338,338,"2811","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2812",0,"Las ubitas de tu parra\nEstán disiendo:-Comerme.-\nY los pampaniyos disen:\n-¡Que biene 'r guarda! ¡Que biene!",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,338,338,"2812","",0,"","","",1,0,0,[],""],["rm_t2-n2813",0,"Me ha dado el apetito\nPor comer uvas;\nSalió el guarda y me dijo:\n-No están maduras.-\n¡Las estoy viendo,\nQue de puro maduras\nSe están cayendo!",0,0,-1,2,"",4,7,"eo",52,0,-1,0,339,339,"2813","",0,"","","",1,0,0,[],""],["rm_t2-n2815",0,"En tu puerta planté un guindo\nY en tu ventana un cerezo;\nEn cada guinda un abrazo\nY en cada cereza un beso.",0,0,-1,2,"",0,4,"eo",48,0,-1,0,339,339,"2815","",0,"","","",2,0,0,[],""],["rm_t2-n2816",0,"Er sarsiyo e tus orejas\nSiempre se ba meneando;\nYo quisiera darte un beso\nDonde 'r sarsiyo ba dando.",0,0,-1,2,"",0,4,"ao",33,0,-1,0,339,339,"2816","",0,"","","",1,0,0,[],""],["rm_t2-n2817",0,"Yo quisiera y no quisiera,\nQue son dos cosas contrarias;\nQuisiera pedirte un beso\nY que no me lo negaras.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,339,339,"2817","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n2818",0,"Mariquita, dame un beso,\nQue me voy á confesar;\nY si el cura me regaña,\nYo te lo volveré á dar.",0,0,-1,2,"",0,4,"a",21,0,-1,0,339,340,"2818","",0,"lafuente_madrid, palau_cantares","","",7,0,0,[],""],["rm_t2-n2819",0,"¿Porque un beso me has dado\nRiñe tu madre?\nToma, niña, tu beso;\nDile que calle.",0,0,-1,2,"",6,4,"ae",-1,0,-1,0,340,340,"2819","",0,"","","",1,0,0,[],""],["rm_t2-n2820",0,"En lo que canta un poyo\nM' atrebo á darte\nMás besos que pepitas\nTiene un tomate.",0,0,-1,2,"",6,4,"ae",-1,0,-1,0,340,340,"2820","",0,"","","",1,0,0,[],""],["rm_t2-n2821",0,"Mis ojos lloran por verte,\nMi corazon por hablarte,\nMi boca por darte un beso,\nMis brazos por abrazarte.",0,0,-1,2,"",0,4,"ae",8,0,-1,0,340,340,"2821","",0,"frenk_t1, huambachano","","",4,0,0,[],""],["rm_t2-n2822",0,"No quisiera más ventura\nNi más gloria merecer\nQue de tu boca á la mia\nNo cupiera un alfiler.",0,0,-1,2,"",0,4,"e",20,0,-1,0,340,340,"2822","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t2-n2824",0,"Dame un besito y adios,\nSalero, y béte á la cama;\nQue no quiero que por mí\nPases frio en la bentana.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,340,340,"2824","",0,"","","",3,0,0,[],""],["rm_t2-n2825",0,"Algun azucarero\nTe hizo los labios,\nQue has dejado los mios\nAzucarados.\nNo me regañes\nSi yo tus labios busco\nPara endulzarme.",0,0,-1,2,"",4,7,"ae",-1,0,-1,0,341,341,"2825","",0,"","","",1,0,0,[],""],["rm_t2-n2826",0,"Si los besos de noche\nLunares fueran,\nTuvieras en tu cara\nDos mil docenas.\nFueran lunares,\nTuvieras en tu cara\nDos mil millares.",0,0,-1,2,"",4,7,"ae",164,0,-1,0,341,341,"2826","",0,"","","",1,0,0,[],""],["rm_t2-n2827",0,"Hágame usté unos zapatos\nCon el tacon que levante,\nQue soy chiquita y no alcanzo\nA los brazos de mi amante.",0,0,-1,2,"",0,4,"ae",47,0,-1,0,341,341,"2827","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n2828",0,"Tu caye traigo por cama,\nPor cabesera un ladriyo;\nCon las esquinas m' abraso,\nPensando qu' estoy contigo.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,341,341,"2828","",0,"","","",1,0,0,[],""],["rm_t2-n2829",0,"Lo que no hayas de darme\nNo me lo enseñes;\nQue Amor es como el niño:\nQue en viendo, quiere.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,341,341,"2829","",0,"","","",2,0,0,[],""],["rm_t2-n2830",0,"En un sofá dormida\nTe ví ayer tarde;\nMe perdí una fineza,\nPor ser cobarde.\nPero has de saber\nQue si otra vez te encuentro,\nNo la he de perder.",0,0,-1,2,"",4,7,"e",20,0,-1,0,341,342,"2830","",0,"","","",1,0,0,[],""],["rm_t2-n2831",0,"Por gozar á la esposa\nDe Colatino,\nLa diadema de Roma\nPerdió Tarquino.\nY yo arriesgara\nLa diadema del mundo\nSi te alcanzara.",0,0,-1,2,"",4,7,"aa",57,0,-1,0,342,342,"2831","",0,"","","",1,0,0,[],""],["rm_t2-n2832",0,"Adios, que me voy del mundo,\nPorque la tierra me llama,\nY en el testamento dejo\nQue me entierren en tu cama.",0,0,-1,2,"",0,4,"aa",90,0,-1,0,342,342,"2832","",0,"","","",3,0,0,[],""],["rm_t2-n2833",0,"La luna se ba poniendo\nPor detrás de tu corrá;\nDe sueño me boy cayendo;\nJarme 'n tu cama un lugá.",0,0,-1,2,"",1,4,"a",9,0,-1,0,342,342,"2833","",0,"","","",1,0,0,[],""],["rm_t2-n2834",0,"Átame con un cabello\nA los bancos de tu cama,\nQue aunque el cabello se rompa,\nSeguro está que me vaya.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,342,342,"2834","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2835",0,"¡Si yo me viera contigo\nCon la llavecita echada\nY el herrero se muriera\nY la llave se quebrara...!",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,342,342,"2835","",0,"","","",3,0,0,[],""],["rm_t2-n2836",0,"Una mardision t' h' echao;\nPermita Dios que t' arcanse:\nQue tu corason y er mio\nEn una cama descansen.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,343,343,"2836","",0,"","","",1,0,0,[],""],["rm_t2-n2837",0,"Échame una mardision,\nUna mardision gitana;\nQue los ángeles me yeben\nEn prosesion á tu cama.",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,343,343,"2837","",0,"","","",1,0,0,[],""],["rm_t2-n2838",0,"Si tu mare no me quiere,\nQue m' eche una mardision:\nQue se le pierda su hija\nY que me la encuentre yo.",0,0,-1,2,"",5,4,"o",-1,0,-1,0,343,343,"2838","",0,"","","",1,0,0,[],""],["rm_t2-n2839",0,"Si mi madre fuera mora\nY yo morito de Argel,\nRenegaba de Mahoma,\nSólo por venirte á ver.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,343,343,"2839","",0,"","","",3,0,0,[],""],["rm_t2-n2840",0,"A los moros que te vayas\nA renegar de la fé,\nTengo de irme contigo\nA renegar yo tambien.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,343,343,"2840","",0,"","","",3,0,0,[],""],["rm_t2-n2841",0,"Aunque te bayas, chiquiya,\nA los montes Pirineos,\nT' he de seguí con el arma,\nSi con er cuerpo no pueo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,343,343,"2841","",0,"","","",1,0,0,[],""],["rm_t2-n2842",0,"Al infierno que te vayas,\nTengo de irme contigo,\nPorque yendo en tu compaña,\nLlevo la gloria conmigo.",0,0,-1,2,"",0,4,"io",106,0,-1,0,343,343,"2842","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2843",0,"A la mar que te vayas,\nQuerido Pepe,\nA la mar que te vayas,\nMe voy por verte.\nMoreno mio,\nA la mar que te vayas\nMe voy contigo.",0,0,-1,2,"",4,7,"io",-1,0,-1,0,344,344,"2843","",0,"","","",3,0,0,[],""],["rm_t2-n2844",0,"Como tú me llevaras\nAdonde fueras,\nComo tú me llevaras,\nMas que no vuelvas.",0,0,-1,2,"",6,4,"ea",-1,0,-1,0,344,344,"2844","",0,"","","",3,0,0,[],""],["rm_t2-n2845",0,"Disen que m' has de yebar\nA bibir á una montaña;\nYébame donde tú quieras,\nQu' er queré toíto lo ayana.",0,0,-1,2,"",3,4,"aa",-1,0,-1,0,344,344,"2845","",0,"","","",2,0,0,[],""],["rm_t2-n2846",0,"Disen que m' has de yebar\nA bibir á un bentorriyo;\nYébame donde tú quieras,\nQue tu gustiyo eser mio.",0,0,-1,2,"",0,4,"io",-1,0,-1,0,344,344,"2846","",0,"","","",2,0,0,[],""],["rm_t2-n2847",0,"¡Mal haya quien no te quiere!\n¡Mal haya quien no te ama!\n¡Mal haya quien no se fuere\nContigo de buena gana!",0,0,-1,2,"",0,4,"aa",-1,0,-1,0,344,344,"2847","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2848",0,"Maria, ¡dulce nombre!\nSiempre te traigo\nDe dia en la memoria,\nDe noche al lado.\nVénte conmigo,\nQue no perderás nada,\nNi yo contigo.",0,0,-1,2,"",4,7,"io",106,0,-1,0,344,345,"2848","",0,"","","",1,0,0,[],""],["rm_t2-n2849",0,"Bénte cormigo, serrana;\nBénte cormigo, salero;\nComerás der pan que como;\nMorirás der mar que muero.",0,0,-1,2,"",0,4,"eo",38,0,-1,0,345,345,"2849","",0,"","","",1,0,0,[],""],["rm_t2-n2852",0,"Si te cansa la sierra,\nSerrana hermosa,\nDeja la serranía,\nBénte á mi chosa.",0,0,-1,2,"",6,4,"oa",63,0,-1,0,345,345,"2852","",0,"","","",1,0,0,[],""],["rm_t2-n2856",0,"Bén te cormigo ar molino\nY serás mi molinera;\nEcharás trigo en la torba,\nMientras yo pico la piedra.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,345,346,"2856","",0,"","","",1,0,0,[],""],["rm_t2-n2857",0,"Vénte comigo á Roma,\nSerás romana\nY aprenderás la lengua\nNapolitana.",0,0,-1,2,"",6,4,"aa",4,0,-1,0,346,346,"2857","",0,"","","",1,0,0,[],""],["rm_t2-n2863",0,"Compañerito del arma,\nPor Dios, no me yores más;\nQue yo me diré contigo\nAonde me quieras yebá.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,346,346,"2863","",0,"","","",2,0,0,[],""],["rm_t2-n2865",0,"Si pasas el rio Ebro,\nPásalo por el ponton,\nQue en la arboleda te aguardo,\nPrenda de mi corazon.",0,0,-1,2,"",5,4,"ao",-1,0,-1,0,347,347,"2865","",0,"","","",1,0,0,[],""],["rm_t2-n2867",0,"Como tortoliya\nT' andube buscando,\nCompañerita, - d' olibo en olibo,\nDe ramito en ramo.",0,0,-1,2,"",3,4,"ao",-1,0,-1,0,347,347,"2867","",0,"","","",1,0,0,[],""],["rm_t2-n2868",0,"Como borreguiyo manso\nSales ar campo á buscarme\nY yo t' estoy aguardando,\nSangresiya de mi sangre.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,347,347,"2868","",0,"","","",1,0,0,[],""],["rm_t2-n2869",0,"Cada vez que paso y miro\nLos umbrales de tu puerta,\nMe arrodillo y los venero,\nComo si fuera la iglesia.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,347,347,"2869","",0,"lafuente_madrid","","",25,0,0,[],""],["rm_t2-n2870",0,"Cada vez que paso y miro\nLos sitios acostumbrados,\nMe arrodillo y los venero,\nComo si fueran sagrados.",0,0,-1,2,"",0,4,"ao",18,0,-1,0,347,347,"2870","",0,"","","",25,0,0,[],""],["rm_t2-n2871",0,"Cada vez que paso y miro\nEl sitio donde te hablé,\nMe dan ganas de sentarme\nY estarme un ratito en él.",0,0,-1,2,"",0,4,"e",-1,0,-1,0,348,348,"2871","",0,"","","",25,0,0,[],""],["rm_t2-n2872",0,"Cuando t' encuentro en la caye\nAgacho la vista 'r suelo,\nBeso la tierra que pisas\nY con eso me consuelo.",0,0,-1,2,"",0,4,"eo",10,0,-1,0,348,348,"2872","",0,"","","",5,0,0,[],""],["rm_t2-n2873",0,"Cuando t' encuentro en la caye\nY no me dises adios,\nNi las ánimas benditas\nPasan más ducas que yo.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,348,348,"2873","",0,"","","",5,0,0,[],""],["rm_t2-n2874",0,"Cuando t' encuentro en la caye\nEr sentío me se quita\nY m' agarro á las paeres,\nJasta perderte de bista.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,348,348,"2874","",0,"","","",5,0,0,[],""],["rm_t2-n2875",0,"Cuando t' encuentro en la caye\n' Se rosa ropa con ropa,\nEr sentío me se quita\n' La sangre me s' arborota.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,348,348,"2875","",0,"","","",5,0,0,[],""],["rm_t2-n2877",0,"Cuando te encuentro en la calle\nLa sangre se me rebota\nY se me quiere salir\nEl corazon por la boca.",0,0,-1,2,"",0,4,"oa",-1,0,-1,0,348,348,"2877","",0,"palau_cantares, lafuente_madrid","","",13,0,0,[],""],["rm_t2-n2878",0,"Si te veo, me aturrullo;\nY si en la calle te encuentro,\nHace un movimiento el alma\nPara salirse del cuerpo.",0,0,-1,2,"",0,4,"eo",-1,0,-1,0,349,349,"2878","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2879",0,"Esta calle está medida\nCon cien varas de liston,\nEn cada esquina una rosa\nY enmedio mi corazon.",0,0,-1,2,"",0,4,"o",31,0,-1,0,349,349,"2879","",0,"","","",2,0,0,[],""],["rm_t2-n2881",0,"Cuando paso por tu puerta\nY te veo en la ventana,\nSe me alegra el corazon\nPara toda la semana.",0,0,-1,2,"",0,4,"aa",4,0,-1,0,349,349,"2881","",0,"","","",17,0,0,[],""],["rm_t2-n2883",0,"Cuando te beo bení\nJasta 'l arma se m' alegra;\nNo te sargo á resibí,\nPor mó de las malas lenguas.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,349,349,"2883","",0,"","","",2,0,0,[],""],["rm_t2-n2884",0,"Cuando voy por la calle\nDe mi paloma,\nHago una paradita,\nPor ver si asoma.",0,0,-1,2,"",6,4,"oa",86,0,-1,0,349,349,"2884","",0,"","","",1,0,0,[],""],["rm_t2-n2885",0,"Cada vez que paso y miro\nY en la ventana no estás,\nVoy acortando los pasos,\nPor ver si te asomarás.",0,0,-1,2,"",0,4,"a",51,0,-1,0,350,350,"2885","",0,"","","",25,0,0,[],""],["rm_t2-n2887",0,"Cuando paso por tu puerta\nY no la encuentro barría\nLe digo á mi corason:\n-Mala 'stá la prenda mia.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,350,350,"2887","",0,"","","",17,0,0,[],""],["rm_t2-n2888",0,"No sé qué para mí tienes,\nQue cada bes que te beo\nMe queo como San Juan,\nSeñalando con er deo.",0,0,-1,2,"",0,4,"eo",66,0,-1,0,350,350,"2888","",0,"","","",3,0,0,[],""],["rm_t2-n2889",0,"Desde mi casa á la tuya,\nMorena, no hay más que un paso;\nDesde la tuya á la mia,\n¡Ay, qué camino tan largo!",0,0,-1,2,"",0,4,"ao",-1,0,-1,0,350,350,"2889","",0,"","","",3,0,0,[],""],["rm_t2-n2890",0,"Quisiera berte 'n la caye\nPara darte mi sentir;\nPero tienes una madre\nQue no te deja salir\n[Ni á la puerta de la caye].",0,0,-1,2,"",7,5,"ae",-1,0,-1,0,350,350,"2890","",0,"","","",1,0,0,[],""],["rm_t2-n2892",0,"Por la mañana temprano\nIré á hacerte una visita;\nSiempre estás acompañada\nY yo te quiero solita.",0,0,-1,2,"",0,4,"ia",50,0,-1,0,351,351,"2892","",0,"","","",2,0,0,[],""],["rm_t2-n2893",0,"Deseando estoy que yegue\nLa noche para yo hablarte;\nQue tiene mi corason\nMuchas cosas que contarte.",0,0,-1,2,"",0,4,"ae",8,0,-1,0,351,351,"2893","",0,"","","",3,0,0,[],""],["rm_t2-n2894",0,"Ya se ba poniendo er só;\nSarga la luna briyante;\n¡Qué ganas que tengo yo\nDe platicá con mi amante!",0,0,-1,2,"",1,4,"ae",47,0,-1,0,351,351,"2894","",0,"","","",1,0,0,[],""],["rm_t2-n2895",0,"Aquel lucero que sale\nPor detrás de las cabrillas\nEs el que á mí me acompaña\nCuando voy á verte, niña.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,351,351,"2895","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2896",0,"Las estreyitas der sielo\nMe sirbén de compañía\nCuando paseo tu caye,\nMás de noche que de dia.",0,0,-1,2,"",0,4,"ia",0,0,-1,0,351,351,"2896","",0,"","","",3,0,0,[],""],["rm_t2-n2897",0,"Marinero, boga, boga\nY que vuele mi barquilla,\nQue al otro lado del rio\nMe espera el bien de mi vida.",0,0,-1,2,"",0,4,"ia",-1,0,-1,0,352,352,"2897","",0,"","","",3,0,0,[],""],["rm_t2-n2898",0,"Contando voy los minutos\nQue faltan hasta las nueve,\nPor ser la hora de cita\nQue mi amante viene á verme.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,352,352,"2898","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2899",0,"Pasando por tu puerta,\nLas nueve daban;\nTu madre te reñia;\nTú suspirabas.\nY en los suspiros\nDecias:-Juan del alma,\nYo no te olvido.",0,0,-1,2,"",4,7,"io",-1,0,-1,0,352,352,"2899","",0,"","","",1,0,0,[],""],["rm_t2-n2900",0,"Amor mio, vén temprano,\nNo me vengas á deshora,\nQue la vecina de enfrente\nEs algo murmuradora.",0,0,-1,2,"",0,4,"oa",107,0,-1,0,352,352,"2900","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2901",0,"María, tu enamorado\nRonda la calle á deshora\nY de ver que tú no sales,\nGotitas de sangre llora.",0,0,-1,2,"",0,4,"oa",107,0,-1,0,352,352,"2901","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2902",0,"Baja, niña, al cuarto bajo\nY hablaremos por la reja\nDos palabritas de amor,\nSin que se entere la vieja.",0,0,-1,2,"",0,4,"ea",165,0,-1,0,352,352,"2902","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t2-n2903",0,"Si quieres venirte, vénte;\nSi quieres estarte, estáte;\nNos quedaremos á solas,\nQue tengo que platicarte.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,353,353,"2903","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2904",0,"Cerrado está el convento\nQue adoro y miro;\nDentro está la paloma\nPor quien suspiro.\n¡Convento santo!\nDentro está la paloma\nPor quien yo can to.",0,0,-1,2,"",4,7,"o",-1,0,-1,0,353,353,"2904","",0,"","","",1,0,0,[],""],["rm_t2-n2905",0,"En la calle del árbol\nPegué tres voces:\n- Josefita del alma,\n¿No me conoces?—\nTres voces pegué:\n-Josefita del alma,\n¿No me quieres ver?",0,0,-1,2,"",4,7,"e",-1,0,-1,0,353,353,"2905","",0,"","","",1,0,0,[],""],["rm_t2-n2906",0,"Cuando pases por mi puerta\nDesgarra bien, que oiga yo;\nQue estoy metida en mi sala,\nNo sé si pasas ó nó.",0,0,-1,2,"",0,4,"o",2,0,-1,0,353,353,"2906","",0,"","","",1,0,0,[],""],["rm_t2-n2907",0,"Con mi puro y mi guitarra\nMe tendrás todas las noches\nEnfrente de tu ventana,\nÁntes que suenen las doce.",0,0,-1,2,"",0,4,"oe",-1,0,-1,0,353,353,"2907","",0,"","","",3,0,0,[],""],["rm_t2-n2909",0,"De ventana en ventana\nMe voy durmiendo;\nEn llegando á la tuya\nSe me va el sueño.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,354,354,"2909","",0,"","","",2,0,0,[],""],["rm_t2-n2910",0,"Échale pan al perro\nSi vas á verme,\nPorque tiene mi madre\nSueño de liebre.",0,0,-1,2,"",6,4,"ee",-1,0,-1,0,354,354,"2910","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2911",0,"Ya está puesta la escala;\n¿Quieres que suba\nA gozar de los rayos\nDe tu hermosura?",0,0,-1,2,"",6,4,"ua",-1,0,-1,0,354,354,"2911","",0,"","","",1,0,0,[],""],["rm_t2-n2912",0,"Me asomé á la ventana\nY ví un sombrero;\nConocí que era el tuyo\nY abrí sin miedo.",0,0,-1,2,"",6,4,"eo",-1,0,-1,0,354,354,"2912","",0,"","","",1,0,0,[],""],["rm_t2-n2913",0,"Yo no sé lo que tiene,\nMadre, la luna,\nQue se para en mi puerta\nMás que en ninguna.",0,0,-1,2,"",6,4,"ua",56,0,-1,0,354,354,"2913","",0,"","","",2,0,0,[],""],["rm_t2-n2914",0,"Bien pudiera la luna\nSer campechana\nY alumbrar con sus rayos\nEsta ventana.\nPara estar viendo\nUna cara morena\nQue estoy queriendo.",0,0,-1,2,"",4,7,"eo",52,0,-1,0,354,354,"2914","",0,"","","",2,0,0,[],""],["rm_t2-n2915",0,"Agua menudita llueve,\nPronto cairán las canales;\nÁbreme la puerta, cielo,\nQue soy aquel que tú sabes.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,355,355,"2915","",0,"","","",6,0,0,[],""],["rm_t2-n2916",0,"Anoche medió la una\nPlaticando con mi amor;\nEsta noche, si Dios quiere,\nLa una y tambien las dos.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,355,355,"2916","",0,"","","",1,0,0,[],""],["rm_t2-n2917",0,"Me dijistes que aguardara\nY hasta las once aguardé;\nY viendo que no venías,\nFuí á la cama y me acosté.",0,0,-1,2,"",3,4,"e",77,0,-1,0,355,355,"2917","",0,"","","",1,0,0,[],""],["rm_t2-n2918",0,"Un sirbío, dos sirbíos;\nA los tres te conosí;\nPerdóname, dueño mio,\nQue no he podío salí\n[Que mi padre m' ha sentío].",0,0,-1,2,"",7,5,"io",3,0,-1,0,355,355,"2918","",0,"","","",1,0,0,[],""],["rm_t2-n2920",0,"-Estrella, sol y luna,\nSal á la calle.\n-Lucero, no me deja\nSalir mi madre.\nSi me dejara,\nA la calle saliera,\nContigo hablara.",0,0,-1,2,"",4,7,"aa",57,0,-1,0,355,355,"2920","",0,"","","",2,0,0,[],""],["rm_t2-n2921",0,"Si por mí sales, luna,\nLuna, no salgas,\nQue esta noche no tengo\nQue pelar paba.\nNo salgas, luna,\nQue esta noche no tengo\nPaba ninguna.",0,0,-1,2,"",4,7,"ua",56,0,-1,0,356,356,"2921","",0,"","","",1,0,0,[],""],["rm_t2-n2922",0,"Por estar en tu ventana\nQuiso prenderme el alcalde;\nNo che y dia me estaré,\nQue yo no le temo á nádie.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,356,356,"2922","",0,"","","",1,0,0,[],""],["rm_t2-n2923",0,"Antiernoche bine á berte,\nLusero de la mañana;\nMe quisieron dar la muerte\nDebajo de tu bentana.",0,0,-1,2,"",1,4,"aa",4,0,-1,0,356,356,"2923","",0,"","","",1,0,0,[],""],["rm_t2-n2924",0,"Debajo de tu ventana\nMe quisieron dar la muerte,\nLucero de la mañana,\nSólo por venir á verte.",0,0,-1,2,"",1,4,"ee",134,0,-1,0,356,356,"2924","",0,"palau_cantares, lafuente_madrid","","",29,0,0,[],""],["rm_t2-n2925",0,"Entre usté, que estoy solita\nY mi madre está en la calle;\nLe pondré á usté una sillita,\nQue nádie se come á nádie.",0,0,-1,2,"",0,4,"ae",-1,0,-1,0,356,356,"2925","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2926",0,"Entra tú, que estoy solita\nY mi madre ya vendrá;\nY si no viniere pronto,\nTú á mí no me comerás.",0,0,-1,2,"",0,4,"a",-1,0,-1,0,356,356,"2926","",0,"","","",3,0,0,[],""],["rm_t2-n2928",0,"Siéntate á la bera mia\nSiquiera por un minuto\nY le darás á mi cuerpo\nEse ratiyo de gusto.",0,0,-1,2,"",0,4,"uo",-1,0,-1,0,357,357,"2928","",0,"","","",2,0,0,[],""],["rm_t2-n2929",0,"Vén acá, cuñada mia,\nVén acá y siéntate aquí;\nYa que no veo á tu hermana,\nSiquiera te veré á tí.",0,0,-1,2,"",3,4,"i",23,0,-1,0,357,357,"2929","",0,"","","",1,0,0,[],""],["rm_t2-n2930",0,"Se fué mi madre á misa,\nVino mi novio;\n¡Así fueran las misas\nDe San Gregorio!",0,0,-1,2,"",6,4,"oo",-1,0,-1,0,357,357,"2930","",0,"","","",1,0,0,[],""],["rm_t2-n2933",0,"No me digas que me vaya;\nPor Dios, no me digas véte,\nPorque se me representan\nLas fatigas de la muerte.",0,0,-1,2,"",0,4,"ee",-1,0,-1,0,357,357,"2933","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2934",0,"Ya me boy, morena mia,\nYa me boy, porqu' amanese;\nEr lusero s' ha perdio\nY la luna no parese.",0,0,-1,2,"",0,4,"ee",65,0,-1,0,358,358,"2934","",0,"","","",1,0,0,[],""],["rm_t2-n2936",0,"Adios, serafin sin fin,\nAdios, serafin hermoso;\nQue me boy con la esperansa\nDe borber á ber tu rostro.",0,0,-1,2,"",0,4,"oo",-1,0,-1,0,358,358,"2936","",0,"","","",1,0,0,[],""],["rm_t2-n2937",0,"Siempre que te vas me dices:\n-Adios, hasta la primera.\nComo no me dices cuándo,\nSiempre me dejas con pena.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,358,358,"2937","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2938",0,"Nunca me digas adios,\nQue es una palabra triste;\nCorazones que se aman\nNunca deben despedirse.",0,0,-1,2,"",0,4,"ie",-1,0,-1,0,358,358,"2938","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n2939",0,"Amor, no digas adios\nCuando por la calle vas,\nQue parece que me dices:\n-Adios, hasta nunca más.",0,0,-1,2,"",0,4,"a",51,0,-1,0,358,358,"2939","",0,"","","",3,0,0,[],""],["rm_t2-n2940",0,"No quiero que te vayas,\nNi que te quedes,\nNi que me dejes sola,\nNi que me lleves.\nQuiero tan sólo....\nPero no quiero nada;\nLo quiero todo.",0,0,-1,2,"",4,7,"oo",-1,0,-1,0,358,359,"2940","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n2941",0,"Cormaíyo tengo yo er gusto\nCuando te tengo á mi bera;\nLas fatigas e Dios paso\nCuando te bas y me dejas.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,359,359,"2941","",0,"","","",1,0,0,[],""],["rm_t2-n2942",0,"Cuando sierras la bentana,\nAr gorpe de la madera\nSe me queda er corason\nComo er paná de la sera.",0,0,-1,2,"",0,4,"ea",44,0,-1,0,359,359,"2942","",0,"","","",1,0,0,[],""],["rm_t2-n2943",0,"Quédate con Dios, bentana,\nY dile á la que te sierra\nQue si s' acuerda de mí\nComo yo m' acuerdo d' eya.",0,0,-1,2,"",0,4,"ea",-1,0,-1,0,359,359,"2943","",0,"","","",1,0,0,[],""],["rm_t2-n2944",0,"Esta mañana temprano,\nÁntes que saliera el sol,\nLe dije al bien de mi vida\nQue se quedara con Dios.",0,0,-1,2,"",0,4,"o",-1,0,-1,0,359,359,"2944","",0,"","","",4,0,0,[],""],["rm_t2-n2945",0,"Por San Juan hizo un año\nQue te queria;\nMás firme estoy ahora\nQue el primer día.",0,0,-1,3,"",6,4,"ia",0,0,-1,0,432,432,"2945","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n2946",0,"Seré para tí más firme\nQue la Isla de Leon,\nQue el año del terremoto\nTembló, pero no cayó.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,432,432,"2946","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2947",0,"Más firme soy en quererte\nQue las horas del reló:\nEl reló muda las horas,\nPero mi firmeza nó.",0,0,-1,3,"",0,4,"o",2,0,-1,0,432,432,"2947","",0,"","","",3,0,0,[],""],["rm_t2-n2948",0,"Yo soy como aquel barquito\nQue lo están encarenando;\nMientras más golpes le dan,\nMás firme lo ban dejando.",0,0,-1,3,"",0,4,"ao",33,0,-1,0,432,432,"2948","",0,"","","",2,0,0,[],""],["rm_t2-n2949",0,"Soy castillo en lo alto,\nPiedra en lo fuerte;\nSoy constante, en amarte,\nFirme en quererte.\nSi tú me amas,\nSoy constante, aunque el mundo\nSobre mí cáiga.",0,0,-1,3,"",4,7,"aa",-1,0,-1,0,432,433,"2949","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2950",0,"Las estrellas y luceros\nQue salen por el Oriente\nNo tienen tanta firmeza\nComo yo para quererte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,433,433,"2950","",0,"lafuente_madrid","","",10,0,0,[],""],["rm_t2-n2951",0,"Me tirastes de la cuerda\nPor ber si me blandeaba\nY m' encontrastes más firme\nQu' er muro de la Girarda.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,433,433,"2951","",0,"","","",1,0,0,[],""],["rm_t2-n2952",0,"Aunque me ves encogida\nY que tengo pocos años,\nEn tocando á la firmeza,\nNi la cruz de San Fernando.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,433,433,"2952","",0,"fernan_caballero, palau_cantares","","",4,0,0,[],""],["rm_t2-n2953",0,"Aunque me ves niña, tengo\nLas palabritas muy firmes;\nSi tus palabras son falsas,\nLas mias nunca se rinden.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,433,433,"2953","",0,"","","",3,0,0,[],""],["rm_t2-n2954",0,"El airesiyo solano\nQue biene por la Gomera\nPasó por aquí y me dijo\nQue firme me mantubiera.",0,0,-1,3,"",3,4,"ea",44,0,-1,0,433,433,"2954","",0,"","","",1,0,0,[],""],["rm_t2-n2955",0,"Yo me cojo á las raises\nQu' están debajito e tierra\nY á las ramas no me cojo,\nPorque 'r biento se las yeba.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,433,434,"2955","",0,"","","",1,0,0,[],""],["rm_t2-n2956",0,"Los árboles de Aranjuez\nUnidos de dos en dos\nNo tienen tanta firmeza\nComo tenemos los dos.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,434,434,"2956","",0,"","","",6,0,0,[],""],["rm_t2-n2957",0,"Los árboles de Aranjuez\nUnidos de siete en siete\nNo tienen tanta firmeza\nComo yo para quererte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,434,434,"2957","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n2958",0,"Los árboles del Retiro\nUnidos de diez en diez\nNo tienen tanta firmeza\nComo tiene mi querer.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,434,434,"2958","",0,"","","",1,0,0,[],""],["rm_t2-n2959",0,"Los árboles de Aranjuez\nJuntos con los del Retiro\nNo tienen tanta firmeza\nComo tengo yo contigo.",0,0,-1,3,"",0,4,"io",-1,0,-1,0,434,434,"2959","",0,"","","",6,0,0,[],""],["rm_t2-n2960",0,"Estreyas del arto sielo,\nBajar y firmar por mí,\nQue cumpliré la palabra\nQue ar qu' está ausente le dí.",0,0,-1,3,"",0,4,"i",23,0,-1,0,434,434,"2960","",0,"","","",1,0,0,[],""],["rm_t2-n2961",0,"Firma tú y firmaré yo\nY se juntarán dos firmas;\nVeremos cuál de los dos\nCon más firmeza camina.",0,0,-1,3,"",0,4,"ia",-1,0,-1,0,434,434,"2961","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n2962",0,"Firmo, confirmo y afirmo,\nFirmo y confirmo mi fé;\nFirmo que yo seré firme;\nFirmo que firme seré.",0,0,-1,3,"",0,4,"e",77,0,-1,0,435,435,"2962","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2963",0,"Firmo, confirmo y afirmo,\nFirmo mi firme esperanza;\nFirmo que yo seré firme;\nFirmo que no habrá mudanza.",0,0,-1,3,"",0,4,"aa",163,0,-1,0,435,435,"2963","",0,"","","",3,0,0,[],""],["rm_t2-n2964",0,"Firme estoy, firme estaré,\nFirme estoy hasta la muerte\nY en muriendo yo, dirán:\n-Murió, pero firme siempre.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,435,435,"2964","",0,"","","",1,0,0,[],""],["rm_t2-n2965",0,"Fragua, yunque y martiyo\nRompe los metales;\nEr juramento-que yo á tí t' he jecho\nNo lo rompe náide.",0,0,-1,3,"",3,4,"ae",-1,0,-1,0,435,435,"2965","",0,"","","",1,0,0,[],""],["rm_t2-n2966",0,"Silencio y perseverancia\nMantendrán nuesto querer;\nDeja que de amor me muera;\nNo mudes de parecer.",0,0,-1,3,"",0,4,"e",20,0,-1,0,435,435,"2966","",0,"","","",1,0,0,[],""],["rm_t2-n2967",0,"Yo soy rio y no me enturbio,\nAunque caiga una tormenta;\nQue me mantengo más claro\nQue los caños de una huerta.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,435,435,"2967","",0,"","","",1,0,0,[],""],["rm_t2-n2968",0,"Se cayó la Babilonia,\nPorque le fartó er simiento;\nEste queré no lo erriba\nNi tampoco er firmamento.",0,0,-1,3,"",0,4,"eo",94,0,-1,0,435,435,"2968","",0,"","","",2,0,0,[],""],["rm_t2-n2969",0,"Se cayó la Babilonia,\nPorque no la hisieron bien;\nEste queré no lo erriba\nSino Dios con su podé.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,436,436,"2969","",0,"","","",2,0,0,[],""],["rm_t2-n2970",0,"El castillo de Figueras\nCon veinticinco cañones\nNo ha podido derribar\nNuestros primeros amores.",0,0,-1,3,"",0,4,"oe",-1,0,-1,0,436,436,"2970","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2971",0,"Bien podrán los imposibles\nQuitarme el gozar tu cielo;\nPero no podrán quitarme\nMi amor, porque es verdadero.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,436,436,"2971","",0,"","","",1,0,0,[],""],["rm_t2-n2972",0,"Yo soy como aquer güen biejo\nQue moritos cautibaron:\nPor martirios que le dieron,\nNunca dejó su rosario.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,436,436,"2972","",0,"","","",1,0,0,[],""],["rm_t2-n2973",0,"Dame tu sangre, serrana,\nQue yo te daré la mia,\nY haremos una contrata\nQue dure toda la vida.",0,0,-1,3,"",0,4,"ia",-1,0,-1,0,436,436,"2973","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2974",0,"Por tu querer quebranté\nLas leyes de la obediencia\nY atrás no me he de volver,\nPorque me llamo firmeza.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,436,436,"2974","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2975",0,"Er querer es cuesta arriba\nY el olbidar cuesta abajo;\nQuiero subir cuesta arriba,\nAunque me cueste trabajo.",0,0,-1,3,"",1,4,"ao",168,0,-1,0,436,436,"2975","",0,"","","",1,0,0,[],""],["rm_t2-n2976",0,"Juramento tengo hecho\nCon er Señó de la Sangre\nDe no orbidá tu queré\nJasta que Dios me lo mande.",0,0,-1,3,"",0,4,"ae",77,0,-1,0,437,437,"2976","",0,"","","",2,0,0,[],""],["rm_t2-n2977",0,"Cuanto más jondiyo un poso,\nMás fresquita sale el agua;\nCuanto más apartaítos,\nMás firme 'stá mi palabra.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,437,437,"2977","",0,"","","",1,0,0,[],""],["rm_t2-n2978",0,"El alma que tengo es tuya\nEn esta conformidá:\nQue si presente te quiero,\nAusente te quiero más.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,437,437,"2978","",0,"","","",4,0,0,[],""],["rm_t2-n2979",0,"Al umbral de tu puerta\nL' he preguntado:\n-Mientras yo h' estado ausente,\n¿Quién ha reinado?-\nM' ha respondido\nQu' en ausencia y presencia\nYo solo he sido.",0,0,-1,3,"",4,7,"io",101,0,-1,0,437,437,"2979","",0,"","","",1,0,0,[],""],["rm_t2-n2980",0,"Mi corazon en quererte\nEs un monte en espesura:\nMientras más ramas le cortan,\nTiene la raíz más dura.",0,0,-1,3,"",0,4,"ua",17,0,-1,0,437,437,"2980","",0,"","","",3,0,0,[],""],["rm_t2-n2981",0,"Si el amor que te tengo\nFuere pecado,\nNo podré de esta culpa\nSer perdonado.\nPues nunca ha sido\nPerdonado el pecado\nNo arrepentido.",0,0,-1,3,"",4,7,"io",101,0,-1,0,437,438,"2981","",0,"","","",3,0,0,[],""],["rm_t2-n2982",0,"En la cárcel de amores\nEstoy metida,\nPor adorar á un hombre\nMás que á mi vida.\nY lo he de querer,\nAunque toda mi vida\nPrisionera esté.",0,0,-1,3,"",4,7,"e",-1,0,-1,0,438,438,"2982","",0,"","","",1,0,0,[],""],["rm_t2-n2983",0,"Si por tu querer me espongo\nA riesgo de que me maten,\nVaya el mundo noramala,\nQue yo no quiero olvidarte.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,438,438,"2983","",0,"","","",1,0,0,[],""],["rm_t2-n2984",0,"A mi corason l' han dao\nJier y binagre á bebé\nY con gusto lo ha tomao,\nPor no dejá tu queré.",0,0,-1,3,"",1,4,"e",77,0,-1,0,438,438,"2984","",0,"","","",1,0,0,[],""],["rm_t2-n2985",0,"Para imprimir tu afecto\nFuí yo de bronce;\nPero estando ya impreso,\nNo hay quien le borre.\nPorque yo tardo;\nPero si á querer llego,\nNunca me aparto.",0,0,-1,3,"",4,7,"ao",-1,0,-1,0,438,438,"2985","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t2-n2986",0,"No podrás morir nunca\nMientras yo viva;\nSi tu vida te falta,\nTienes mi vida.\nNo la maltrates,\nQue moriré en el punto\nQue de tí falte.",0,0,-1,3,"",4,7,"ae",-1,0,-1,0,438,439,"2986","",0,"","","",1,0,0,[],""],["rm_t2-n2987",0,"Tengo de quererte á tí\nAunque otra me solicite;\nQue un hombre puesto á querer\nEs un barco echado á pique.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,439,439,"2987","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2988",0,"Yo te quiero y te requiero\nY no habrá quien me lo quite;\nQue una mujer arrestada\nEs un barco echado á pique.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,439,439,"2988","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n2989",0,"Si el amor en el mundo\nLlega á perderse,\nSe ha de hallar en mi pecho,\nQue aquí está siempre.\nPero está sólo\nEmpleado en la prenda\nQue firme adoro.",0,0,-1,3,"",4,7,"oo",-1,0,-1,0,439,439,"2989","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n2990",0,"Me dijistes bajando\nPor la escalera:\n-Como por tí no quede,\nPor mí, no queda.-\nYo te respondí:\n-Como por tí no quede,\nNo queda por mí.",0,0,-1,3,"",4,7,"i",23,0,-1,0,439,439,"2990","",0,"","","",1,0,0,[],""],["rm_t2-n2991",0,"Dicen se muda el hombre\nLuégo en logrando,\nY yo, cuanto más logro,\nMás idolatro.\nSólo me pesa\nEl instante que pasa\nSin ver mi prenda.",0,0,-1,3,"",4,7,"ea",-1,0,-1,0,439,440,"2991","",0,"","","",2,0,0,[],""],["rm_t2-n2992",0,"Por darle gusto á mis padres\nY á mi corazon pesar,\nDije que no te queria,\nY no te puedo olvidar.",0,0,-1,3,"",0,4,"a",21,0,-1,0,440,440,"2992","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2993",0,"Tú reinas en mi pecho;\nNo te receles;\nQue no ha de reinar nádie\nDonde tú reines.",0,0,-1,3,"",6,4,"ee",-1,0,-1,0,440,440,"2993","",0,"","","",1,0,0,[],""],["rm_t2-n2994",0,"Desecha todo temor;\nVive alegre y placentero;\nQue el que fué primer amor\nSiempre ha sido verdadero.",0,0,-1,3,"",1,4,"eo",38,0,-1,0,440,440,"2994","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n2995",0,"Amor mio, no pierdas\nLas esperanzas,\nQue en el pozo más hondo\nLa soga alcanza.",0,0,-1,3,"",6,4,"aa",-1,0,-1,0,440,440,"2995","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t2-n2996",0,"Ojos de color de cielo,\nAzules como los mios,\nNo perdais las esperanzas,\nQue yo no las he perdido.",0,0,-1,3,"",0,4,"io",-1,0,-1,0,440,440,"2996","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n2998",0,"Dulce iman de mi querer,\nRegalo de mi esperanza,\nNo tienes de qué temer,\nQue en mí no cabe mudanza.",0,0,-1,3,"",1,4,"aa",163,0,-1,0,440,441,"2998","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n2999",0,"Amor mio, no llores\nNi te desveles;\nQue la que ha de ser tuya\nCierta la tienes.",0,0,-1,3,"",6,4,"ee",-1,0,-1,0,441,441,"2999","",0,"","","",1,0,0,[],""],["rm_t2-n3000",0,"No me llores, vida mia,\nNo me llores, no me llores;\nQue me tienes tan seguro\nComo la estrella del Norte.",0,0,-1,3,"",0,4,"oe",-1,0,-1,0,441,441,"3000","",0,"","","",1,0,0,[],""],["rm_t2-n3001",0,"No quiero querer ninguno;\nEl cielo no me castigue;\nUno que traigo entre manos\nOlvidarlo es imposible.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,441,441,"3001","",0,"","","",1,0,0,[],""],["rm_t2-n3002",0,"He pensado olvidarte\nQuinientas veces\nY en viéndote no hay forma\nDe que me acuerde.\nQue un pecho fino\nSólo olvida la causa\nDe los olvidos.",0,0,-1,3,"",4,7,"io",-1,0,-1,0,441,441,"3002","",0,"","","",2,0,0,[],""],["rm_t2-n3003",0,"Al principiar á amarte\nHice promesa\nDe olvidar tus amores\nCuando fallezca.",0,0,-1,3,"",6,4,"ea",-1,0,-1,0,441,441,"3003","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3004",0,"No pienses, dueño querido,\nQue yo te podré olvidar;\nLo que en mi pecho se encierra\nMis obras te lo dirán.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,441,441,"3004","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3005",0,"Niña, lo que bien se quiere\nNo puede olvidarse, nó;\nPor más añitos que pasen\nNunca he de olvidarte yo.",0,0,-1,3,"",0,4,"o",2,0,-1,0,442,442,"3005","",0,"","","",1,0,0,[],""],["rm_t2-n3006",0,"Yo no te puedo olvidar,\nPorque es mi querer muy grande;\nYo te tengo á tí metida\nEn la masa de la sangre.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,442,442,"3006","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3007",0,"A las plantas de la Vírgen\nQuiero llegar á hacer voto\nDe no olvidarte en la vida,\nNi dejarte á tí por otro.",0,0,-1,3,"",0,4,"oo",-1,0,-1,0,442,442,"3007","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3008",0,"En consulta han entrado\nLas tres potencias;\nQue te deje y te olvide\nDos me aconsejan.\nMas la voluntad\nA sus espaldas dice\nQue ella te ha de amar.",0,0,-1,3,"",4,7,"a",-1,0,-1,0,442,442,"3008","",0,"","","",1,0,0,[],""],["rm_t2-n3009",0,"Los ancianos se juntan\nPara discutir\nSi es posible que pueda\nOlvidarte á tí.\nY todos dicen\nQue mi amor fué el primero\nY echó raíces.",0,0,-1,3,"",4,7,"ie",-1,0,-1,0,442,442,"3009","",0,"","","",1,0,0,[],""],["rm_t2-n3012",0,"Todo cuanto me pidas\nDaré al instante,\nA no ser la palabra\nQue he de olvidarte.\nPues nunca ofrezco\nLo que por imposible\nCumplir no puedo.",0,0,-1,3,"",4,7,"eo",-1,0,-1,0,443,443,"3012","",0,"","","",1,0,0,[],""],["rm_t2-n3014",0,"¡Buen empeño has tomado\nDe que te olvide!\n¿Acaso está en mi mano\nLo que me pides?\n¡Vaya, que es bueno\nEl querer que yo haga\nLo que no puedo!",0,0,-1,3,"",4,7,"eo",-1,0,-1,0,443,443,"3014","",0,"","","",1,0,0,[],""],["rm_t2-n3015",0,"Échame otra penitensia\nQue yo la pueda cumplir;\nPero que yegue á orbidarte\nY a no depende de mí.",0,0,-1,3,"",0,4,"i",-1,0,-1,0,443,443,"3015","",0,"","","",1,0,0,[],""],["rm_t2-n3016",0,"Corason de filigrana,\nEmbutido en fino asero,\n¿Cómo quieres que te orbide,\nSi has sido mi amor primero?",0,0,-1,3,"",0,4,"eo",38,0,-1,0,444,444,"3016","",0,"","","",1,0,0,[],""],["rm_t2-n3017",0,"¿Cómo quieres que te orbide,\nSi has sido mi amor primero,\nY ese amor echa raíces\nComo la planta en er suelo?",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,444,444,"3017","",0,"","","",1,0,0,[],""],["rm_t2-n3018",0,"¿Cómo quieres que te olvide,\nSi has sido mi compañera,\nY el amor echa raíces\nComo la planta en la tierra?",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,444,444,"3018","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n3019",0,"¿Cómo quieres que la olvide,\nSi le he dado tantos besos\nComo lleva un relicario\nCuando va de pueblo en pueblo?",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,444,444,"3019","",0,"","","",3,0,0,[],""],["rm_t2-n3020",0,"¿Cómo quiês que no le jable,\nSi ha tenío nuebe meses\nDentro der cuerpo mi sangre,\nY d' eya tengo un hijito\nQue cuando me be 'n la caye,\nPapá dise 'l angelito?",0,0,-1,3,"",9,6,"io",119,0,-1,0,444,444,"3020","",0,"","","",1,0,0,[],""],["rm_t2-n3021",0,"Cuatro velas encendidas\nY un hábito franciscano\nNecesitaba mi cuerpo\nPara olvidar á quien amo.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,444,444,"3021","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3022",0,"Los cuatro elementos juntos,\nAgua, tierra, viento y fuego,\nNo podrán hacer que olvide\nLo mucho que yo te quiero.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,444,445,"3022","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3023",0,"Aunque el mundo se oponga,\nNo te he de olvidar;\nQue te he de ser constante\nHasta el espirar.\nY si me muero,\nMis últimas palabras\nSerán te quiero.",0,0,-1,3,"",4,7,"eo",38,0,-1,0,445,445,"3023","",0,"","","",1,0,0,[],""],["rm_t2-n3024",0,"Aunque hallara el remedio\nPara olvidarte,\nTe aseguro, bien mio,\nNo he de tomarle.\nPorque no quiero\nMorirme de repente\nCon el remedio.",0,0,-1,3,"",4,7,"eo",-1,0,-1,0,445,445,"3024","",0,"","","",1,0,0,[],""],["rm_t2-n3026",0,"Anque 'n mil años no güerbas,\nYo seré como la bimbre,\nQue la bambolea 'l aire,\nPero se mantiene firme.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,445,445,"3026","",0,"","","",1,0,0,[],""],["rm_t2-n3027",0,"Aunque yo á tí no te bea\nNi en uno, ni en dos, ni en tres,\nTe tengo d' estar queriendo,\nPor la leche que mamé.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,445,445,"3027","",0,"","","",1,0,0,[],""],["rm_t2-n3028",0,"Aunque me pase sin berte\nUn añiyo, ó dos, ó tres,\nNo te tengo de orbidar,\nNi doy mi braso á torser.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,446,446,"3028","",0,"","","",1,0,0,[],""],["rm_t2-n3029",0,"Anque de los sielos caigan\nEstreyitas á miyares,\nA tí solo he de quererte,\nPor no darle gusto á náide.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,446,446,"3029","",0,"","","",1,0,0,[],""],["rm_t2-n3030",0,"Las estreyitas der sielo\nS' han de caer á miyares,\nFlamenca, porque t' orbíe,\nY eso no lo berá náide.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,446,446,"3030","",0,"","","",3,0,0,[],""],["rm_t2-n3031",0,"Si las estreyas der sielo\nTodas se borbieran lansas,\nCon la punta para er suelo,\nEn mi queré no hay mudansa.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,446,446,"3031","",0,"","","",1,0,0,[],""],["rm_t2-n3032",0,"Aunque las piedras dén gritos,\nY el sol deje de correr,\nY el agua del mar se acabe,\nNo dejaré tu querer.",0,0,-1,3,"",0,4,"e",20,0,-1,0,446,446,"3032","",0,"","","",4,0,0,[],""],["rm_t2-n3033",0,"Yo te tengo de querer,\nAunque le pese á mi estrella;\nAunque contra mí se junten\nAíre, fuego, mar y tierra.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,446,446,"3033","",0,"","","",6,0,0,[],""],["rm_t2-n3034",0,"Si las piedras de tu calle\nSe volvieran migueletes,\nTodos los atropellara,\nSólo por venir á verte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,446,446,"3034","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t2-n3035",0,"Anque pongan en tu puerta\nUn ejército francés,\nAmparado con tu sombra,\nA nádie le he de temer.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,447,447,"3035","",0,"","","",1,0,0,[],""],["rm_t2-n3036",0,"Aunque pongan en tu puerta\nCañones de á venticuatro\nY á tu padre de artillero,\nDe tu querer no me aparto.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,447,447,"3036","",0,"","","",3,0,0,[],""],["rm_t2-n3037",0,"Aunque pongan en tu puerta\nLa artillería real\nY á tu padre de artillero,\nContigo me he de casar.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,447,447,"3037","",0,"","","",3,0,0,[],""],["rm_t2-n3038",0,"Aunque pongan en tu puerta\nLa artillería volante\nY á tu padre de artillero,\nHe de pasar adelante.",0,0,-1,3,"",0,4,"ae",47,0,-1,0,447,447,"3038","",0,"","","",3,0,0,[],""],["rm_t2-n3039",0,"Anque pongan en tu caye\nCañones de artiyería,\nEr que se puso á queré,\nSe puso á perdé la bia.",0,0,-1,3,"",0,4,"ia",0,0,-1,0,447,447,"3039","",0,"","","",1,0,0,[],""],["rm_t2-n3040",0,"Aunque te bea difunta\nCon cuatro belas ardiendo,\nHasta la sepurturita\nTe tengo d' estar queriendo.",0,0,-1,3,"",0,4,"eo",52,0,-1,0,447,447,"3040","",0,"","","",1,0,0,[],""],["rm_t2-n3041",0,"Aunque pase más penitas\nQue Cádiz tiene arfileres,\nNo t' he d' orbidar, bien mio,\nPor ber er fin qu' esto tiene.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,447,447,"3041","",0,"","","",2,0,0,[],""],["rm_t2-n3042",0,"Aunque pase más fatigas\nQue arenas tiene la playa,\nNo he de dejar tu querer,\nHasta ver en lo que pára.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,448,448,"3042","",0,"","","",5,0,0,[],""],["rm_t2-n3043",0,"Aunque pase más trabajos\nQue arenas tienen los rios\nY pinos tienen los montes,\nNo te he de olvidar, bien mio.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,448,448,"3043","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3044",0,"Aunque pase más fatigas\nQue clabos tiene una puerta,\nYo te tengo de querer,\nQu' er mundo da muchas buertas.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,448,448,"3044","",0,"","","",5,0,0,[],""],["rm_t2-n3045",0,"Aunque me dieran más palos\nQue le dan al martinete,\nNo te tengo de olvidar,\nPorque es mi gusto el quererte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,448,448,"3045","",0,"","","",3,0,0,[],""],["rm_t2-n3046",0,"Aunque me dén más balasos,\nQu' adarmes pesa un nabío,\nNo s' han de romper los lasos\nQue unen tu amor con er mio.",0,0,-1,3,"",1,4,"o",3,0,-1,0,448,448,"3046","",0,"","","",1,0,0,[],""],["rm_t2-n3047",0,"Amar bien es padecer\nY padecer es morir;\nAunque la vida me cueste,\nYo te he de querer á tí.",0,0,-1,3,"",0,4,"i",-1,0,-1,0,448,448,"3047","",0,"","","",1,0,0,[],""],["rm_t2-n3050",0,"Aunque tu querer me mate,\nNo he de dejar de quererte;\nQue te quiero con el alma\nY el alma nunca se muere.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,449,449,"3050","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3051",0,"Te he de seguir queriendo,\nAunque me cueste\nMorir en un madero\nPúblicamente.\nQue no es afrenta\nMorir en un madero\nPor tu belleza.",0,0,-1,3,"",4,7,"ea",-1,0,-1,0,449,449,"3051","",0,"","","",2,0,0,[],""],["rm_t2-n3052",0,"Aunque me vea en dos palos,\nY un capuchino á los piés,\nY un dogal á la garganta,\nYo siempre te he de querer.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,449,449,"3052","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3053",0,"Se me puso en la cabeza\nQue te habia de querer,\nAunque hubiera más contrarios\nQue moritos tiene Argel.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,449,449,"3053","",0,"","","",3,0,0,[],""],["rm_t2-n3054",0,"Aunque contra mí se opongan,\nAunque sufra mil castigos,\nAunque mi padre no quiera,\nYo me he de casar contigo.",0,0,-1,3,"",0,4,"io",-1,0,-1,0,449,449,"3054","",0,"","","",1,0,0,[],""],["rm_t2-n3055",0,"Dentro e mi pechito\nTengo yo su imánge;\nManque me yeben - á la fin der mundo,\nNo hay quien me l' arranque.",0,0,-1,3,"",3,4,"ae",-1,0,-1,0,449,449,"3055","",0,"","","",1,0,0,[],""],["rm_t2-n3056",0,"Aunque me digan que eres\nMujer de mala conducta\nY de malos procederes,\nTe quiero porque me gustas.",0,0,-1,3,"",0,4,"ua",-1,0,-1,0,450,450,"3056","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3057",0,"Aunque bengan y me digan\nQue desiendes de gitanos,\nEso es benir y ponerme\nUna peseta en la mano.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,450,450,"3057","",0,"","","",1,0,0,[],""],["rm_t2-n3058",0,"Aunque me digan de tí\nLo que dicen del demonio,\nYo te tengo de querer,\nCarita de San Antonio.",0,0,-1,3,"",0,4,"oo",169,0,-1,0,450,450,"3058","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3059",0,"Aunque me vayan celando\nPor balcones y ventanas,\nLograremos nuestro intento;\nNo pases pena por nada.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,450,450,"3059","",0,"","","",1,0,0,[],""],["rm_t2-n3060",0,"Aunque tu madre te meta\nEn una sepa de biña,\nM' has de cumplí la palabra\nQue me distes cuando niña.",0,0,-1,3,"",0,4,"ia",170,0,-1,0,450,450,"3060","",0,"","","",2,0,0,[],""],["rm_t2-n3061",0,"Aunque tu padre te meta\nEn un castiyo de bronse,\nHemos de pelar la paba\nEntre las dies y las onse.",0,0,-1,3,"",0,4,"oe",171,0,-1,0,450,450,"3061","",0,"","","",4,0,0,[],""],["rm_t2-n3062",0,"Aunque tu padre te meta\nDebajo de los ladrillos,\nYo te tengo de sacar\nY me he de casar contigo.",0,0,-1,3,"",0,4,"io",-1,0,-1,0,450,450,"3062","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3063",0,"Aunque tus padres no quieran\nY los mios digan nó,\nSi tu quieres y yo quiero,\nEso será y otro nó.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,451,451,"3063","",0,"","","",1,0,0,[],""],["rm_t2-n3064",0,"Annque todos se opusieran,\nContigo me he de casar;\nQue más estimo mi gusto\nQue cuanto me puedan dar.",0,0,-1,3,"",0,4,"a",21,0,-1,0,451,451,"3064","",0,"","","",1,0,0,[],""],["rm_t2-n3065",0,"Las gentes nos critican\nQue nos hablamos;\nLa fortuna que tienen,\nQue ahora empezamos.\n¿Qué podrán decir?\nQue yo quiero á un mocito\nY el mocito á mí.",0,0,-1,3,"",4,7,"i",-1,0,-1,0,451,451,"3065","",0,"","","",1,0,0,[],""],["rm_t2-n3066",0,"Deseo de ser tuya\nDe horita en hora,\nPor librarme de lenguas\nMurmuradoras.\nHable quien hable,\nCon vinagrillo fuerte\nRiego la calle.",0,0,-1,3,"",4,7,"ae",-1,0,-1,0,451,451,"3066","",0,"","","",1,0,0,[],""],["rm_t2-n3067",0,"Este querer tuyo y mio\nParece que está de Dios;\nMiéntras más nos lo critican\nMás nos queremos los dos.",0,0,-1,3,"",0,4,"o",87,0,-1,0,451,451,"3067","",0,"palau_cantares","","",4,0,0,[],""],["rm_t2-n3068",0,"Me dicen que Pedro es feo;\nQue no le debo querer;\nNo le miro yo á la cara,\nSino á su buen proceder.",0,0,-1,3,"",0,4,"e",20,0,-1,0,451,451,"3068","",0,"","","",1,0,0,[],""],["rm_t2-n3069",0,"Dicen que mi amante es feo;\nPara mí es el sol dorado;\nEn estando yo gustosa,\nTodo el mundo está pagado.",0,0,-1,3,"",0,4,"ao",14,0,-1,0,452,452,"3069","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3070",0,"Todo el mundo me murmura\nPorque te tengo á mi lado;\nEn estando tu y yo á gusto,\nTodo el mundo está pagado.",0,0,-1,3,"",0,4,"ao",14,0,-1,0,452,452,"3070","",0,"","","",1,0,0,[],""],["rm_t2-n3071",0,"Todos me dicen que adoro\nUn clavel del mal color;\nDiga el mundo lo que quiera,\nÁ mí me parece un sol.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,452,452,"3071","",0,"","","",4,0,0,[],""],["rm_t2-n3072",0,"Dicen que mi amante es feo\nY picado de viruelas;\nA mí me parece un sol\nCoronadito de estrellas.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,452,452,"3072","",0,"","","",4,0,0,[],""],["rm_t2-n3073",0,"Todo el mundo me da vaya,\nPorque quiero á un hombre chico;\nYo digo que por el aire\nSe compran los abanicos.",0,0,-1,3,"",0,4,"io",-1,0,-1,0,452,452,"3073","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3075",0,"Me dicen que te olvide;\n¡Mira que necios!\nMientras más me lo dicen,\nMás te requiero.",0,0,-1,3,"",6,4,"eo",-1,0,-1,0,452,452,"3075","",0,"","","",1,0,0,[],""],["rm_t2-n3076",0,"Me han dicho que te olvide;\nEso no haré yo,\nQue no pueden los santos\nOlvidará Dios.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,453,453,"3076","",0,"","","",1,0,0,[],""],["rm_t2-n3077",0,"Tú platica conmigo\nCuanto quisieres;\nQue si alguno se ahorca,\nYo haré cordeles.",0,0,-1,3,"",6,4,"ee",-1,0,-1,0,453,453,"3077","",0,"","","",1,0,0,[],""],["rm_t2-n3078",0,"Varios envidiosillos\nHan intentado\nPonerme á mal contigo,\nNo lo han logrado.\nNi lo han de lograr,\nPorque te voy queriendo\nCada dia más.",0,0,-1,3,"",4,7,"a",-1,0,-1,0,453,453,"3078","",0,"","","",1,0,0,[],""],["rm_t2-n3080",0,"¿Qué cuidaíto me da á mí\nQuejablen lo qu' han jablao?\nUn pañuelo tengo negro,\nLo he de teñí en colorao.",0,0,-1,3,"",0,4,"ao",98,0,-1,0,453,453,"3080","",0,"","","",1,0,0,[],""],["rm_t2-n3081",0,"Deja que la gente diga,\nDeja que la gente hable;\nEn queriéndonos los dos,\nMas que no nos quiera nádie.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,453,453,"3081","",0,"","","",3,0,0,[],""],["rm_t2-n3082",0,"Deja que la gente jable,\nQue para mí es alegría;\nSi tú me quieres, serrana,\nTe pagaré con la bía.",0,0,-1,3,"",0,4,"ia",0,0,-1,0,453,454,"3082","",0,"","","",1,0,0,[],""],["rm_t2-n3083",0,"Déjalos que digan, digan,\nY de mi formen historia;\nQu' er que se muere queriendo\nSe ba derecho á la gloria.",0,0,-1,3,"",0,4,"oa",126,0,-1,0,454,454,"3083","",0,"","","",1,0,0,[],""],["rm_t2-n3085",0,"Cuando se quiere de véras,\nNo se mira el qué dirán;\nQuien tiene fé en un camino\nNo vuelve la cara atrás.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,454,454,"3085","",0,"rm_t4","","",3,0,0,[],""],["rm_t2-n3086",0,"El quererme á mí quitar\nEste amor del pensamiento\nEs escribir en el agua\nY predicar en desierto.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,454,454,"3086","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t2-n3087",0,"El decirme que te olvide\nEs predicar en desierto,\nMachacar en hierro frio\nY darle voces á un muerto.",0,0,-1,3,"",0,4,"eo",88,0,-1,0,454,454,"3087","",0,"","","",3,0,0,[],""],["rm_t2-n3088",0,"Si te dieren consejos\nPá que me olbides,\nDile á los consejeros\nQue se retiren.",0,0,-1,3,"",6,4,"ie",-1,0,-1,0,454,454,"3088","",0,"","","",1,0,0,[],""],["rm_t2-n3089",0,"No te yebes de consejos,\nAunque te los dé tu tia,\nQue yo no me yebaré,\nAunque me los dé la mía.",0,0,-1,3,"",0,4,"ia",0,0,-1,0,454,455,"3089","",0,"","","",1,0,0,[],""],["rm_t2-n3090",0,"Aquel que me aconsejare\nQue yo deje tu amistá,\nSepa que tiene en el mundo\nUn enemigo mortal.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,455,455,"3090","",0,"","","",2,0,0,[],""],["rm_t2-n3091",0,"Consejos que á mí me daban\nY yo los aborrecia,\nPor un oido me entraban\nY por otro me salian.",0,0,-1,3,"",5,4,"aa",-1,0,-1,0,455,455,"3091","",0,"","","",1,0,0,[],""],["rm_t2-n3092",0,"Todo el mundo me lo dice\nQue qué saco yo de tí;\nY yo le respondo al mundo:\n-Nádie me gobierna á mí.",0,0,-1,3,"",0,4,"i",23,0,-1,0,455,455,"3092","",0,"lafuente_madrid","","",14,0,0,[],""],["rm_t2-n3093",0,"Todos predican en mí,\nComo si yo fuera hereje;\nTodas las predicaciones\nVan al fin de que te deje.",0,0,-1,3,"",0,4,"ee",173,0,-1,0,455,455,"3093","",0,"","","",1,0,0,[],""],["rm_t2-n3094",0,"Me dicen que no te quiera;\nNo me pueden convencer;\nQue en el corazon que tengo\nNo me cabe tu querer.",0,0,-1,3,"",0,4,"e",20,0,-1,0,455,455,"3094","",0,"","","",2,0,0,[],""],["rm_t2-n3095",0,"Me aconsejan que te olvide;\n¡Mira qué barbaridad!\nComo no saben querer,\nNo saben aconsejar.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,455,455,"3095","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t2-n3096",0,"Me aconsejan que te olvide;\n¡Qué consejos dan las gentes!\nJuramento tengo hecho\nDe olvidarte con la muerte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,456,456,"3096","",0,"","","",7,0,0,[],""],["rm_t2-n3097",0,"Me dicen que te despida;\nNo soy de tal parecer;\nMe daré muerte primero\nQue tal cosa llegue á hacer.",0,0,-1,3,"",0,4,"e",20,0,-1,0,456,456,"3097","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3098",0,"Toíto er mundo á mí me dise\nQue t' orbíe y no te quiera\nY yo le digo á tô er mundo:\n-Cuando me coma la tierra.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,456,456,"3098","",0,"","","",1,0,0,[],""],["rm_t2-n3099",0,"Todos me dicen á mí\nQue te olvide, que te olvide;\nY el olvidarte será\nTenerte el amor más firme.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,456,456,"3099","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3100",0,"Todo el mundo me aconseja\nQue yo deje tu amistad\nY yo les digo:-Señores,\n¿Es envidia, ó caridad?",0,0,-1,3,"",0,4,"a",16,0,-1,0,456,456,"3100","",0,"","","",3,0,0,[],""],["rm_t2-n3101",0,"Jasta los caracolitos\nDe la oriyita der má\nM' aconsejan que t' orbíe;\nYo no te pueo 'rbiá.",0,0,-1,3,"",0,4,"a",9,0,-1,0,456,456,"3101","",0,"","","",2,0,0,[],""],["rm_t2-n3102",0,"Jasta los caracolitos\nQu' están en la arena arena\nM' aconsejan que t' orbíe;\nEso será cuando muera.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,456,456,"3102","",0,"","","",2,0,0,[],""],["rm_t2-n3103",0,"En mi casa me dicen\nQue no te quiera;\nMientras más me lo dicen,\nMás me lo acuerdan.\nY ahora te digo:\n-Como me aprieten mucho,\nMe voy contigo.",0,0,-1,3,"",4,7,"io",106,0,-1,0,457,457,"3103","",0,"","","",11,0,0,[],""],["rm_t2-n3104",0,"Arrepentida m' eché\nA los piés d' un confesó;\nMe dijo que t' orbidara;\nComo un insurto me dió.",0,0,-1,3,"",0,4,"o",2,0,-1,0,457,457,"3104","",0,"","","",1,0,0,[],""],["rm_t2-n3105",0,"Los confesores me mandan\nQue te orbide, Manoliyo;\n¡Los confesores no saben\nLo que cuesta un buen cariño!",0,0,-1,3,"",0,4,"io",-1,0,-1,0,457,457,"3105","",0,"","","",3,0,0,[],""],["rm_t2-n3106",0,"Los confesores me han dicho\nQue te olvide y no lo haré;\n¡Los confesores no saben\nLo que cuesta un buen querer!",0,0,-1,3,"",0,4,"e",-1,0,-1,0,457,457,"3106","",0,"","","",1,0,0,[],""],["rm_t2-n3107",0,"Hasta el confesor me ha dicho\nQue te olvide y digo yo\nQue primero olvidaria\nLa madre que me parió.",0,0,-1,3,"",0,4,"o",2,0,-1,0,457,457,"3107","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3109",0,"El confesor me dice\nQue no te quiera,\nPorque el pobre padece\nDe la mollera.\n¡Ay, pobrecito!\n¡Cual si los mandamientos\nFueran delito!",0,0,-1,3,"",4,7,"io",119,0,-1,0,458,458,"3109","",0,"","","",1,0,0,[],""],["rm_t2-n3110",0,"- Hombre, orbida á esa mujé.\n-Padre mio, yo no puedo;\nEcharme otra penitensia,\nQue cumplir ésa no quiero.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,458,458,"3110","",0,"","","",1,0,0,[],""],["rm_t2-n3111",0,"Ni los padres misioneros,\nNi los misioneros padres,\nMe pueden á mí quitar\nQue te quiera y que te hable.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,458,458,"3111","",0,"","","",2,0,0,[],""],["rm_t2-n3112",0,"El Padre Santo de Roma\nMe dijo que no te amara;\nYo le dije:-Padre mio,\n¡Aunque me recondenara!",0,0,-1,3,"",0,4,"aa",57,0,-1,0,458,458,"3112","",0,"","","",3,0,0,[],""],["rm_t2-n3113",0,"El Padre Santo me ha dicho\nQue te olvide, que te olvide;\nYo le dije:-Padre mio,\n¡No es posible! ¡No es posible!",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,458,458,"3113","",0,"","","",2,0,0,[],""],["rm_t2-n3114",0,"El Padre Santo me ha dicho\nQue te deje, que te deje;\nYo le dije:-Padre mio,\n¡Con la muerte! ¡Con la muerte!",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,458,458,"3114","",0,"","","",2,0,0,[],""],["rm_t2-n3115",0,"Jasta los santos der sielo\nMe mandan que no te quiera;\nYo recapasito y digo:\n—¡Cuando me coma la tierra!",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,459,459,"3115","",0,"","","",1,0,0,[],""],["rm_t2-n3116",0,"Todos los santos del cielo,\nÁngeles y serafines,\nMe aconsejan que te deje\nY yo, cada vez más firme.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,459,459,"3116","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3117",0,"Al arto sielo subí\nAjablá con Undebé\nY m' echó de penitensia\nQue orbiara tu queré.",0,0,-1,3,"",0,4,"e",77,0,-1,0,459,459,"3117","",0,"","","",2,0,0,[],""],["rm_t2-n3118",0,"S' han serraiyo los templos;\nNo me quieren confesá;\nNo m' echan l' arsolusion,\nSi n' orbío tu amistá.",0,0,-1,3,"",0,4,"a",9,0,-1,0,459,459,"3118","",0,"","","",1,0,0,[],""],["rm_t2-n3119",0,"Ni tu padre ni tu madre\nNi el que dispone en los cielos\nMe apartan de tu querer\nMientras tú me estés queriendo.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,459,459,"3119","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n3120",0,"Ni mi padre ni mi madre\nNi San Antonio bendito\nMe pueden á mí quitar\nQue yo te quiera un poquito.",0,0,-1,3,"",0,4,"io",119,0,-1,0,459,459,"3120","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3121",0,"Todo el mundo en contra mia,\nSerrana, porque te quiero;\nTodo el mundo en contra mia,\nY yo contra el mundo entero.",0,0,-1,3,"",1,4,"eo",38,0,-1,0,459,459,"3121","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n3122",0,"De los siete planetas\nQue hay en el cielo\nTres van en contra mia,\nPorque te quiero.\nY he de quererte,\nAunque vayan en contra\nTodos los siete.",0,0,-1,3,"",4,7,"ee",-1,0,-1,0,460,460,"3122","",0,"","","",1,0,0,[],""],["rm_t2-n3123",0,"Si tu madre no quisiere\nY la mia fuere necia,\nPara eso hay un vicario\nY una católica Iglesia.",0,0,-1,3,"",0,4,"ea",139,0,-1,0,460,460,"3123","",0,"","","",2,0,0,[],""],["rm_t2-n3124",0,"Si tu madre no quiere\nNi tus hermanos,\nPor encima de todos\nDame la mano.",0,0,-1,3,"",6,4,"ao",-1,0,-1,0,460,460,"3124","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t2-n3125",0,"Bien puedes, majito mio,\nSacarme manifestada,\nPorque mis padres no quieren\nVerme contigo casada.",0,0,-1,3,"",0,4,"aa",49,0,-1,0,460,460,"3125","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3126",0,"En casa de mis padres\nVivo rabiando;\nSácame, vida mia,\nPor el vicario.",0,0,-1,3,"",6,4,"ao",-1,0,-1,0,460,460,"3126","",0,"","","",1,0,0,[],""],["rm_t2-n3127",0,"¿De qué le sirbe á tu madre\nEchar yabe 'n er corrá,\nSi t' has de bení cormigo\nPor la puerta prensipá?",0,0,-1,3,"",0,4,"a",9,0,-1,0,460,460,"3127","",0,"","","",2,0,0,[],""],["rm_t2-n3128",0,"¿De qué le sirbe á tu madre\nMachacar en jierro frio,\nSi tiene qu' entrá en su casa\nLo que tiene aborresío?",0,0,-1,3,"",0,4,"io",3,0,-1,0,461,461,"3128","",0,"","","",2,0,0,[],""],["rm_t2-n3129",0,"Apesar de los pesares,\nTu padre ha de ser mi suegro,\nTus hermanas mis cuñadas\nY yo tu querido dueño.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,461,461,"3129","",0,"","","",2,0,0,[],""],["rm_t2-n3130",0,"Por un Pepe que adoro\nMe ponen guardia;\nAunque guardia me pongan,\n¡Pepe del alma!\n¡Ay, Pepe, Pepe,\nEn lo mejor del alma\nTe tengo siempre!",0,0,-1,3,"",4,7,"ee",-1,0,-1,0,461,461,"3130","",0,"","","",1,0,0,[],""],["rm_t2-n3131",0,"Me quieren quitar á mí\nEl que yo tu cara vea;\nPor cima de quien lo estorbe\nHe de hacer una vereda.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,461,461,"3131","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n3132",0,"Murayas quieren ponerme\nPara que yo no tebea;\nPor er monte más espeso\nAbren mis ojos berea.",0,0,-1,3,"",0,4,"ea",54,0,-1,0,461,461,"3132","",0,"","","",1,0,0,[],""],["rm_t2-n3133",0,"Quitarme de que te hable\nBien me lo pueden quitar;\nQuitarme de que te quiera\nNi han podido ni podrán.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,461,461,"3133","",0,"","","",2,0,0,[],""],["rm_t2-n3134",0,"Ar peñon de la Gomera\nMe quiere yebar tu madre\nPorque te quiero de béras;\n¡Baya unos motibos grandes!",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,461,462,"3134","",0,"","","",1,0,0,[],""],["rm_t2-n3135",0,"Porque te quiero, niña,\nMe quieren llevar\nA un castillo que han hecho\nEn medio del mar.\nY yo he jurado\nQuererte, aunque me lleven\nMás retirado.",0,0,-1,3,"",4,7,"ao",14,0,-1,0,462,462,"3135","",0,"","","",1,0,0,[],""],["rm_t2-n3136",0,"Apartarnos pretenden;\n¡Pretension necia!\nQue está el lazo en el alma\nY ésa es eterna.\nY áun divididos,\nTú vives en mí siempre\nY yo en tí vivo.",0,0,-1,3,"",4,7,"io",-1,0,-1,0,462,462,"3136","",0,"","","",1,0,0,[],""],["rm_t2-n3137",0,"Me sacan de la córte\nPor que te olvide\nY mientras más me alejan,\nEstoy más firme.",0,0,-1,3,"",6,4,"ie",-1,0,-1,0,462,462,"3137","",0,"","","",1,0,0,[],""],["rm_t2-n3138",0,"A los presidios de Orán\nMe llevan por que te olvide;\nAunque me lleven á Ceuta,\nOlvidarte es imposible.",0,0,-1,3,"",0,4,"ie",-1,0,-1,0,462,462,"3138","",0,"","","",3,0,0,[],""],["rm_t2-n3139",0,"Prisionero me llevan\nPor que te olvide,\nY yo sigo afirmando\nQue es imposible.\nPor que te quiero,\nY yo sigo afirmando\nQue por tí muero.",0,0,-1,3,"",4,7,"eo",38,0,-1,0,462,463,"3139","",0,"","","",2,0,0,[],""],["rm_t2-n3140",0,"Por más que nos separe\nLa tiranía,\nYo he de ser siempre tuyo;\nTú siempre mia.",0,0,-1,3,"",6,4,"a",0,0,-1,0,463,463,"3140","",0,"","","",2,0,0,[],""],["rm_t2-n3141",0,"—A cajas destempladas\nMe echan del reino\nPorque deje de amarte,\nQuerido dueño.\n-¡Ay, vida mia!\nSi te echan de tu casa,\nVénte á la mia.",0,0,-1,3,"",4,7,"a",-1,0,-1,0,463,463,"3141","",0,"","","",1,0,0,[],""],["rm_t2-n3142",0,"Mis padres quieren que quiera\nA uno que tenga doblones;\nYo no quiero la moneda,\nQue en tí he puesto mis amores.",0,0,-1,3,"",0,4,"oe",-1,0,-1,0,463,463,"3142","",0,"","","",1,0,0,[],""],["rm_t2-n3144",0,"Estoy queriendo á un chabá\nY á mi padre no le gusta;\nY yo digo qu' er queré\nTiene lisensia asoluta.",0,0,-1,3,"",0,4,"ua",-1,0,-1,0,463,463,"3144","",0,"","","",2,0,0,[],""],["rm_t2-n3145",0,"Estoy tan arrestadita\nA pagarte tus desvelos,\nQue á rigores de mi padre,\nDueño mio, no le temo.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,464,464,"3145","",0,"","","",1,0,0,[],""],["rm_t2-n3146",0,"Mi padre me tiene dicho\nQue me tiene de sacar\nLos ojos con que te miro,\nY yo, que te he de mirar.",0,0,-1,3,"",0,4,"a",21,0,-1,0,464,464,"3146","",0,"","","",4,0,0,[],""],["rm_t2-n3147",0,"Tengo un padre que me riñe,\nY una madre queme mata,\nY un amante que me dice:\n-Sigue tu rumbo, muchacha.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,464,464,"3147","",0,"","","",1,0,0,[],""],["rm_t2-n3148",0,"Mi padre me pega palos\nPor que olvide tu amistad,\nY al són de los palos digo\nQue te quiero mucho más.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,464,464,"3148","",0,"","","",12,0,0,[],""],["rm_t2-n3149",0,"Mi padre me pega palos\nPorque quiero á un granaero,\nY ar són de los palos digo:\n-¡Biban las gorras de pelo!",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,464,464,"3149","",0,"","","",12,0,0,[],""],["rm_t2-n3150",0,"Mi padre me pega palos\nPorque quiero á un militar,\nY ar són de los palos digo:\n-¡Biba la gorra encarna!",0,0,-1,3,"",5,4,"aa",-1,0,-1,0,464,464,"3150","",0,"","","",12,0,0,[],""],["rm_t2-n3151",0,"Mi padre me pega palos;\nMi madre me mortifica;\nY al són de los palos digo:\n-Sarna con gusto, no pica.",0,0,-1,3,"",0,4,"ia",174,0,-1,0,464,464,"3151","",0,"","","",12,0,0,[],""],["rm_t2-n3152",0,"Mi padre porque te quiero\nMe castiga con rigor;\nMucho puede la obediencia,\nPero más puede el amor.",0,0,-1,3,"",0,4,"o",72,0,-1,0,465,465,"3152","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3154",0,"Sentensiao estoy á muerte\nSi me ven hablar contigo;\nY a pueden los mataores\nAprebenir los cuchiyos.",0,0,-1,3,"",0,4,"io",-1,0,-1,0,465,465,"3154","",0,"","","",1,0,0,[],""],["rm_t2-n3155",0,"Subí á la Sala der crímen\nY le pregunté ar fiscá\nSi este queré que te tengo\nTiene causa criminá.",0,0,-1,3,"",0,4,"a",9,0,-1,0,465,465,"3155","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t2-n3156",0,"Subí á la Sala der crímen\nY le dije ar presïente:\n-Si er queré bien es delito,\nQue me sentensien á muerte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,465,465,"3156","",0,"","","",4,0,0,[],""],["rm_t2-n3157",0,"Si el querer bien es delito,\nPonerme en manos de un juez\nY que el juez sentencie y diga\nSi es delito el querer bien.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,465,465,"3157","",0,"","","",3,0,0,[],""],["rm_t2-n3158",0,"Si er queré bien es delito,\nY amarme á unjues que me prenda\nY que me yebe á la cárse,\nQu' en mi queré no hay ermienda.",0,0,-1,3,"",0,4,"ea",159,0,-1,0,465,465,"3158","",0,"","","",1,0,0,[],""],["rm_t2-n3159",0,"Si es delito el querer bien,\nNo aprietes tanto la soga;\nSi el querer bien es delito,\n¡Dios mio, misericordia!",0,0,-1,3,"",0,4,"oa",-1,0,-1,0,466,466,"3159","",0,"","","",1,0,0,[],""],["rm_t2-n3162",0,"Porque te quiero m' echaron\nA la garganta un cordé\nY de los piés me tiraron\nY ahora te quiero más bien.",0,0,-1,3,"",3,4,"e",-1,0,-1,0,466,466,"3162","",0,"","","",1,0,0,[],""],["rm_t2-n3163",0,"Agua me nieguen las fuentes,\nEl cielo me desampare,\nLluevan las plagas de Egipto\nSobre mí, si te olvidare.",0,0,-1,3,"",0,4,"ae",175,0,-1,0,466,466,"3163","",0,"","","",3,0,0,[],""],["rm_t2-n3164",0,"Mientras más ausente estoy,\nMás firme estoy en amar;\nLa luz del cielo me falte\nSi yo te llego á olvidar.",0,0,-1,3,"",0,4,"a",21,0,-1,0,466,467,"3164","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3166",0,"Permita Dios si me olvidas,\nTe trague la mar serena;\nY si yo te olvido á tí,\nPase por la misma pena.",0,0,-1,3,"",0,4,"ea",59,0,-1,0,467,467,"3166","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n3167",0,"Lo mismo es decirme á mí\nQue te olvide y no te quiera,\nQue decirle al sol que pare\nEnmedio de su carrera.",0,0,-1,3,"",0,4,"ea",44,0,-1,0,467,467,"3167","",0,"","","",2,0,0,[],""],["rm_t2-n3168",0,"Tan imposible lo hallo\nEl olvidar tu querer\nComo tomar un caballo\nY pasar la mar con él.",0,0,-1,3,"",0,4,"e",-1,0,-1,0,467,467,"3168","",0,"lafuente_madrid","","",13,0,0,[],""],["rm_t2-n3169",0,"Tan imposible lo hallo\nQue te deje de adorar\nComo meterme en un coche\nY pasar en él la mar.",0,0,-1,3,"",0,4,"a",21,0,-1,0,467,467,"3169","",0,"","","",13,0,0,[],""],["rm_t2-n3170",0,"Tan imposible lo hallo\nEl olvidar tu cariño\nComo llegar á quitarle\nA San Antonio su Niño.",0,0,-1,3,"",0,4,"io",176,0,-1,0,467,467,"3170","",0,"palau_cantares, lafuente_madrid","","",13,0,0,[],""],["rm_t2-n3171",0,"Tan imposible lo hayo\nBorrarte de mi memoria\nComo conseguir que suba\nUn hombre bibo á la gloria.",0,0,-1,3,"",0,4,"oa",126,0,-1,0,467,468,"3171","",0,"","","",1,0,0,[],""],["rm_t2-n3172",0,"Tan imposible lo hallo\nDe tu querer apartarme\nComo escribir en el agua,\nDe una piedra sacar sangre.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,468,468,"3172","",0,"","","",13,0,0,[],""],["rm_t2-n3173",0,"Para que yo te orbidara\nEra menester que hubiera\nDiligensias por los mares\nY barquiyos por la tierra.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,468,468,"3173","",0,"","","",1,0,0,[],""],["rm_t2-n3174",0,"Para que yo te olvidara\nEra menester que hubiera\nOtra luna y otro sol\nY otro Dios que dispusiera.",0,0,-1,3,"",0,4,"ea",44,0,-1,0,468,468,"3174","",0,"","","",1,0,0,[],""],["rm_t2-n3175",0,"Para olvidar tu querer\nHe de ver yo dos señales:\nQue se caigan las estrellas\nY que se sequen los mares.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,468,468,"3175","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n3176",0,"El orbidarte será\nCuando tú beas que biene\nUn año sin tener Pascua\nY una semana sin biérnes.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,468,468,"3176","",0,"","","",1,0,0,[],""],["rm_t2-n3177",0,"Dejaré de quererte\nCuando las ranas\nAl monte se retiren,\nDejen el agua.\n¿Cómo puede ser\nQue al monte se retiren\nPara perecer?",0,0,-1,3,"",4,7,"e",20,0,-1,0,468,468,"3177","",0,"","","",1,0,0,[],""],["rm_t2-n3178",0,"Primero que yo me aparte,\nMorena, de tu queré,\nHe de pasá por los filos\nDel asero más crué.",0,0,-1,3,"",0,4,"e",77,0,-1,0,469,469,"3178","",0,"","","",3,0,0,[],""],["rm_t2-n3179",0,"De los güesos de mi cuerpo\nTengo de haser un rosario;\nAntes s' han d' apoliyar\nQue darte yo á tí mar pago.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,469,469,"3179","",0,"","","",2,0,0,[],""],["rm_t2-n3180",0,"Quiéreme tú á mí, hermanita,\nQue primero fartará\nPonsio Pilatos der creo\nQue yo 'rbie tu amistá.",0,0,-1,3,"",0,4,"a",9,0,-1,0,469,469,"3180","",0,"","","",1,0,0,[],""],["rm_t2-n3181",0,"Primero faltará el vino\nPara la misa mayor,\nQue faltará la palabra\nQue de mi pecho salió.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,469,469,"3181","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t2-n3182",0,"Antes que yo te orbide,\nSi tú me quieres,\nEcharán los olibos\nUbas jaenes.\nSi tú me estimas,\nEcharán los olibos\nNaranjas chinas.",0,0,-1,3,"",4,7,"ia",-1,0,-1,0,469,469,"3182","",0,"","","",1,0,0,[],""],["rm_t2-n3183",0,"Primero que yo me aparte\nDer queré de los Manueles\nHan d' echar los olibitos\nRasimos de ubas lairenes.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,469,469,"3183","",0,"","","",3,0,0,[],""],["rm_t2-n3184",0,"Primero que yo te orbide,\nMariquita der Rosario,\nHan d' echar los olibitos\nUbas y limones agrios.",0,0,-1,3,"",0,4,"ao",-1,0,-1,0,469,470,"3184","",0,"","","",1,0,0,[],""],["rm_t2-n3185",0,"Una palabra te he dado\nY primero he de morir\nY faltarle al sol sus rayos\nQue dejarla de cumplir.",0,0,-1,3,"",0,4,"i",157,0,-1,0,470,470,"3185","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3186",0,"Primero que yo te olvide\n¡Mira qué comparacion!\nHa de calentar la luna\nY ha de refrescar el sol.",0,0,-1,3,"",0,4,"o",-1,0,-1,0,470,470,"3186","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3187",0,"No tengas pena, morena,\nQue primero ha de fartar\nEr sor en Sierra Morena\nQue yo orbíe tu amistá.",0,0,-1,3,"",0,4,"a",-1,0,-1,0,470,470,"3187","",0,"","","",2,0,0,[],""],["rm_t2-n3188",0,"Escúchame, compañera,\nQue te lo quiero jurar:\nPrimero que yo te olvide\nLa tierra me ha de tragar.",0,0,-1,3,"",0,4,"a",21,0,-1,0,470,470,"3188","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3189",0,"Prisionero soy de amor\nY lo seré mientras viva,\nQue el prisionero de amor\nPrimero muere que olvida.",0,0,-1,3,"",0,4,"ia",-1,0,-1,0,470,470,"3189","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n3190",0,"Desde que te vi te amé\nY te amaré mientras viva,\nPorque el que te amó una vez\nNo puede olvidarte, niña.",0,0,-1,3,"",0,4,"ia",-1,0,-1,0,470,470,"3190","",0,"","","",17,0,0,[],""],["rm_t2-n3193",0,"No porque t' haigas casao\nJuigas e la bera mia;\nYo te tengo e queré\nToíto er resto e mi bía.",0,0,-1,3,"",0,4,"ia",0,0,-1,0,471,471,"3193","",0,"","","",1,0,0,[],""],["rm_t2-n3194",0,"No porque te hayas casado\nTe olvides de mi querer;\nQue puede ser que enviudes\nY vuelvas á mi poder.",0,0,-1,3,"",0,4,"e",20,0,-1,0,471,471,"3194","",0,"","","",1,0,0,[],""],["rm_t2-n3195",0,"Mientras mi cuerpo durare\nY la tierra no me coma\nYo te tengo de querer,\nHermosísima paloma.",0,0,-1,3,"",0,4,"oa",86,0,-1,0,471,471,"3195","",0,"","","",1,0,0,[],""],["rm_t2-n3196",0,"Hasta la muerte he de amarte,\nQue soy firme en el querer;\nDificulto el olvidarte,\nPorque no sé aborrecer.",0,0,-1,3,"",1,4,"e",20,0,-1,0,471,471,"3196","",0,"","","",1,0,0,[],""],["rm_t2-n3197",0,"Aunque tú no me quieras,\nYo he de quererte,\nMientras no me lo quite\nDios con la muerte.",0,0,-1,3,"",6,4,"ee",134,0,-1,0,472,472,"3197","",0,"","","",7,0,0,[],""],["rm_t2-n3198",0,"Yo te tengo de querer\nHasta que la muerte fiera\nPonga á mi cuerpo en prisiones,\nDebajito de la tierra.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,472,472,"3198","",0,"","","",6,0,0,[],""],["rm_t2-n3199",0,"Dos cosas en el mundo\nMe harán perderte:\nSi vivo, un desengaño;\nSi nó, la muerte.",0,0,-1,3,"",6,4,"ee",134,0,-1,0,472,472,"3199","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n3201",0,"Yo te quiero y te requiero\nY te tengo de queré,\nJasta sortar er peyejo\nComo San Bartolomé.",0,0,-1,3,"",0,4,"e",77,0,-1,0,472,472,"3201","",0,"","","",6,0,0,[],""],["rm_t2-n3202",0,"María, siempre María;\nMaría siempre diré;\nY á la hora de mi muerte\nA María llamaré.",0,0,-1,3,"",0,4,"e",77,0,-1,0,472,472,"3202","",0,"","","",1,0,0,[],""],["rm_t2-n3204",0,"He de mandar que me entierren\nSentado cuando me muera,\nPara que puedas decir:\n-Se murió, pero me espera.",0,0,-1,3,"",0,4,"ea",44,0,-1,0,473,473,"3204","",0,"suspiros_amor","","",3,0,0,[],""],["rm_t2-n3205",0,"Quiero que en mi sepulcro\nSe pongan cirios\nPrendidos en el fuego\nDe mis suspiros.\nY si se apagan,\nQue acudan á mi pecho\nY hallarán llama.",0,0,-1,3,"",4,7,"aa",-1,0,-1,0,473,473,"3205","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3206",0,"Con la sangre de mis venas\nTe firmaré una escritura\nDe no dejar tu querer\nNi en la misma sepultura.",0,0,-1,3,"",0,4,"ua",17,0,-1,0,473,473,"3206","",0,"","","",3,0,0,[],""],["rm_t2-n3207",0,"Yo siempre te he de adorar,\nCuésteme lo que me cueste;\nDe tu querer no me aparto,\nAunque viniera la muerte.",0,0,-1,3,"",0,4,"ee",-1,0,-1,0,473,473,"3207","",0,"","","",1,0,0,[],""],["rm_t2-n3209",0,"Jasta la seporturiya\nTe tengo d' estar queriendo,\nPorque tú has jecho conmigo\nPartías e cabayero.",0,0,-1,3,"",0,4,"eo",-1,0,-1,0,473,473,"3209","",0,"","","",1,0,0,[],""],["rm_t2-n3210",0,"Á la sepultura iremos,\nTú detrás y yo delante;\nYo no me aparto de tí\nHasta que Dios me lo mande.",0,0,-1,3,"",0,4,"ae",-1,0,-1,0,474,474,"3210","",0,"","","",4,0,0,[],""],["rm_t2-n3211",0,"Á la sepultura iremos\nCual dos amantes esposos;\nYo te querré en este mundo\nY te adoraré en el otro.",0,0,-1,3,"",0,4,"oo",-1,0,-1,0,474,474,"3211","",0,"","","",4,0,0,[],""],["rm_t2-n3212",0,"Me dices si te quiero;\nDoy por respuesta\nOlvidarte, bien mio,\nDespués de muerta.",0,0,-1,3,"",6,4,"ea",-1,0,-1,0,474,474,"3212","",0,"","","",1,0,0,[],""],["rm_t2-n3213",0,"Firme estoy en tu ausencia,\nFirme presente,\nFirme después de muerto\nY firme siempre.\nY aunque me olvides,\nEn todas ocasiones\nEstoy yo firme.",0,0,-1,3,"",4,7,"ie",-1,0,-1,0,474,474,"3213","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3214",0,"Más allá de la muerte\nMi amor te quiere,\nQue mi amor es del alma\nY ésa no muere.\nQue si muriera,\nCon tal de no olvidarte\nNo te quisiera.",0,0,-1,3,"",4,7,"ea",44,0,-1,0,474,474,"3214","",0,"","","",1,0,0,[],""],["rm_t2-n3215",0,"Dentro de mi seportura\nTengo de dar un quejío,\nPá que tengas en memoria\nEr tiempo que t' he querío.",0,0,-1,3,"",0,4,"io",3,0,-1,0,474,474,"3215","",0,"","","",1,0,0,[],""],["rm_t2-n3216",0,"Con un pié en la seportura\nY otro en la mesmita bera,\nYo te tengo de queré,\nAunque tú á mí no me quieras.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,475,475,"3216","",0,"","","",1,0,0,[],""],["rm_t2-n3217",0,"Aunque me veas cadáver\nEn la puerta de una ermita,\nNo me toques con el pié,\nQue los muertos resucitan.",0,0,-1,3,"",0,4,"ia",-1,0,-1,0,475,475,"3217","",0,"","","",3,0,0,[],""],["rm_t2-n3218",0,"Aunque difunto me hallare\nEn el compás de la iglesia,\nSi álguien dijere tu nombre,\nLevantaré la cabeza.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,475,475,"3218","",0,"","","",1,0,0,[],""],["rm_t2-n3219",0,"Si al pié de mi sepultura\nMe vinieras á llorar,\nLas cenizas de mi cuerpo\nSe habían de menear.",0,0,-1,3,"",0,4,"a",21,0,-1,0,475,475,"3219","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3220",0,"Tendido sobre una estera,\nVestido con la mortaja,\nSi te viera entrar á tí,\nDe fé que resucitaba.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,475,475,"3220","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3221",0,"Tres años despues de muerto\nY con la tierra en la cara,\nSi me dieras una voz,\nCreo que resucitaba.",0,0,-1,3,"",0,4,"aa",-1,0,-1,0,475,475,"3221","",0,"","","",2,0,0,[],""],["rm_t2-n3222",0,"Dentro de la sepultura,\nYa para echarme la tierra,\nSi me dieras una voz,\nCreo que al mundo volviera.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,475,475,"3222","",0,"","","",2,0,0,[],""],["rm_t2-n3223",0,"Dies años después de muerto\nY de gusanos comío,\nLetreros tendrán mis güesos,\nDisiendo que t' he querío.",0,0,-1,3,"",0,4,"io",3,0,-1,0,476,476,"3223","",0,"","","",2,0,0,[],""],["rm_t2-n3224",0,"Abierta la sepurtura,\nYa para echarme la tierra,\nY no ha podío la muerte\nQuitarme de que te quiera.",0,0,-1,3,"",0,4,"ea",-1,0,-1,0,476,476,"3224","",0,"","","",1,0,0,[],""],["rm_t2-n3225",0,"Ar pié de la seportura,\nYa para echarme ó no echarme,\nBino la muerte y no pudo\nDe tu querer apartarme.",0,0,-1,3,"",0,4,"ae",35,0,-1,0,476,476,"3225","",0,"","","",1,0,0,[],""],["rm_t2-n3226",0,"Dies años después de muerto,\nLa tierra me preguntó\nQue si te habia orbidao\nY yo le dije que nó.",0,0,-1,3,"",0,4,"o",2,0,-1,0,476,476,"3226","",0,"","","",2,0,0,[],""],["rm_t2-n3227",0,"Rondeñas bienen cantando;\nSobre la cama me siento,\nPorque en oyendo rondeñas\nSe me alegra el pensamiento.",0,0,-1,4,"",0,4,"eo",94,0,-1,0,488,488,"3227","",0,"","","",1,0,0,[],""],["rm_t2-n3228",0,"Esta noche mi guitarra\nRonda por los barrios bajos;\nEr que se meta con eya\nYeba palos pá un sombrajo.",0,0,-1,4,"",0,4,"ao",-1,0,-1,0,488,488,"3228","",0,"","","",1,0,0,[],""],["rm_t2-n3229",0,"Por tu caye boy entrando,\nCabeyos d' emperaora;\nSi tienes er nobio guapo,\nDile que sarga aquí ahora.",0,0,-1,4,"",0,4,"oa",107,0,-1,0,488,488,"3229","",0,"","","",2,0,0,[],""],["rm_t2-n3230",0,"Por tu caye boy entrando;\nM' han dicho que no hay salía;\nYo la tengo d' encontrá,\nAnque me cueste la bía.",0,0,-1,4,"",0,4,"ia",0,0,-1,0,488,488,"3230","",0,"","","",2,0,0,[],""],["rm_t2-n3231",0,"Por tu calle voy entrando,\nHermosa flor de romero;\nAquí tienes un criado\nSin que te cueste el dinero.",0,0,-1,4,"",0,4,"eo",38,0,-1,0,488,488,"3231","",0,"","","",4,0,0,[],""],["rm_t2-n3232",0,"Por la calle abajo viene\nUna guitarra de plata\nY la prima va diciendo:\n-Una morena me mata.",0,0,-1,4,"",0,4,"aa",74,0,-1,0,489,489,"3232","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n3233",0,"En aquel balcon hay luz;\n¡Si se estarán acostando!\nAllí está mi corazon\nY aquí mi alma penando.",0,0,-1,4,"",0,4,"ao",-1,0,-1,0,489,489,"3233","",0,"","","",1,0,0,[],""],["rm_t2-n3234",0,"En esta calle, galanes,\nTodo el mundo cante bien,\nQue á la entrada está una rosa\nY á la salida un clavel.",0,0,-1,4,"",0,4,"e",-1,0,-1,0,489,489,"3234","",0,"","","",1,0,0,[],""],["rm_t2-n3237",0,"La luna para salir\nLe pide al cielo licencia,\nY para cantar yo aquí\nLa pido con reverencia.",0,0,-1,4,"",0,4,"ea",46,0,-1,0,490,490,"3237","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",14,0,0,[],""],["rm_t2-n3238",0,"La luna para salir\nLe pide licencia al cielo,\nY para cantar yo aquí\nLicencia pido primero.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,490,490,"3238","",0,"carrizo_salta","","",14,0,0,[],""],["rm_t2-n3240",0,"A tu puerta estamos cuatro;\nTodos cuatro te queremos;\nSál á la puerta y escoge\nY los demás nos iremos.",0,0,-1,4,"",0,4,"eo",127,0,-1,0,491,491,"3240","",0,"palau_cantares","","",8,0,0,[],""],["rm_t2-n3241",0,"A tu puerta estamos cuatro,\nY cinco con el que toca,\nY seis con el que quisiera\nBesar tus manos y boca.",0,0,-1,4,"",0,4,"oa",178,0,-1,0,491,491,"3241","",0,"","","",8,0,0,[],""],["rm_t2-n3242",0,"Por ser la primera bes\nQu' á tu puerta, niña, canto,\nEn er nombre sea de Dios\nY del Espíritu Santo.",0,0,-1,4,"",0,4,"ao",30,0,-1,0,491,491,"3242","",0,"","","",1,0,0,[],""],["rm_t2-n3243",0,"En el nombre sea de Dios\nY del Espíritu Santo;\nEsta es la primera copla\nQue á tu puerta, niña, canto.",0,0,-1,4,"",0,4,"ao",30,0,-1,0,491,491,"3243","",0,"lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["rm_t2-n3244",0,"Dios te dé muy buenas noches,\nHermosísimo lusero:\nEn teniéndolas tú buenas,\nYo felises las espero.",0,0,-1,4,"",0,4,"eo",38,0,-1,0,491,491,"3244","",0,"","","",4,0,0,[],""],["rm_t2-n3245",0,"Dios te dé muy buenas noches,\nHermosísima deidá;\nM' alegro que sigas buena;\nPor acá no hay nobedá.",0,0,-1,4,"",0,4,"a",9,0,-1,0,491,491,"3245","",0,"","","",4,0,0,[],""],["rm_t2-n3246",0,"Dios te dé muy buenas noches,\nHermosa concha der mar,\nDonde nasen los espejos\nEn que me bengo á mirar.",0,0,-1,4,"",0,4,"a",21,0,-1,0,492,492,"3246","",0,"","","",4,0,0,[],""],["rm_t2-n3247",0,"Esta casa güele á pino\nY las puertas son de bronse;\nA los amos d' esta casa\nDios les dé muy buenas noches.",0,0,-1,4,"",0,4,"oe",-1,0,-1,0,492,492,"3247","",0,"","","",1,0,0,[],""],["rm_t2-n3248",0,"La primera, por el amo;\nLa segunda, por la dueña;\nTersera, por la criada,\nQue es la qu' á mí me da pena.",0,0,-1,4,"",0,4,"ea",-1,0,-1,0,492,492,"3248","",0,"","","",3,0,0,[],""],["rm_t2-n3251",0,"Grasias á Dios qu' he yegado,\nA tu puerta, beya aurora;\nQue me parese qu' h' echado\nEn cada paso una hora.",0,0,-1,4,"",1,4,"oa",107,0,-1,0,493,493,"3251","",0,"","","",7,0,0,[],""],["rm_t2-n3252",0,"Grasias á Dios qu' he yegado\nA la lus d' este faró,\nPara sacarme una espina\nQue traigo en er corason.",0,0,-1,4,"",5,4,"ao",-1,0,-1,0,493,493,"3252","",0,"","","",7,0,0,[],""],["rm_t2-n3253",0,"Grasias á Dios qu' he yegado\nA est' hermoso palomá,\nDond' habita una paloma\nCon las alas plateâs.",0,0,-1,4,"",5,4,"ae",-1,0,-1,0,493,493,"3253","",0,"","","",7,0,0,[],""],["rm_t2-n3254",0,"Grasias á Dios qu' he yegado\nAr palasio donde habita\nEsta paloma surita,\nReflejo de mi cuidado.",0,0,-1,4,"",11,4,"ao",14,0,-1,0,493,493,"3254","",0,"","","",7,0,0,[],""],["rm_t2-n3255",0,"Grasias á Dios qu' he yegado\nDonde no pensé yegar,\nA darte las buenas noches;\nMorena, ¿qué tar te ba?",0,0,-1,4,"",0,4,"a",-1,0,-1,0,493,493,"3255","",0,"","","",7,0,0,[],""],["rm_t2-n3256",0,"Grasias á Dios qu' he yegado\nA la puerta der deseo;\nNádie me quite la lus,\nQu' he de cantar er primero.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,493,493,"3256","",0,"","","",7,0,0,[],""],["rm_t2-n3257",0,"Grasias á Dios qu' he yegado;\nGrasias á Dios que yegné;\nGrasias á Dios qu' he cantado;\nGrasias á Dios que canté.",0,0,-1,4,"",1,4,"e",77,0,-1,0,493,494,"3257","",0,"","","",7,0,0,[],""],["rm_t2-n3258",0,"Si hay una, canto por una,\nY si hay dos, canto por dos;\nTú cantas por la más chica;\nYo canto por la mayor.",0,0,-1,4,"",0,4,"o",-1,0,-1,0,494,494,"3258","",0,"","","",1,0,0,[],""],["rm_t2-n3259",0,"A mí me tocó la suerte\nComo mejor director\nDe venir á despertar\nDel barrio la mejor flor.",0,0,-1,4,"",0,4,"o",72,0,-1,0,494,494,"3259","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t2-n3260",0,"Si supiera que cantando\nDaba gusto á mi morena,\nToda la noche cantara\nY á la mañana durmiera.",0,0,-1,4,"",0,4,"ea",-1,0,-1,0,494,494,"3260","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n3261",0,"Si supiera que cantando\nTe había de divertir,\nToda la noche cantara,\nAunque perdiera el dormir.",0,0,-1,4,"",0,4,"i",157,0,-1,0,494,494,"3261","",0,"carrizo_salta, palau_cantares, fernan_caballero","","",10,0,0,[],""],["rm_t2-n3262",0,"Si supiera, vida mia,\nQue me estabas escuchando,\nToda la noche estaría\nComo un ruiseñor cantando.",0,0,-1,4,"",1,4,"ao",33,0,-1,0,494,494,"3262","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3263",0,"Ya sé que estás en la cama;\nYa sé que no duermes, nó;\nYa sé que estás escuchando\nLas coplas que canto yo.",0,0,-1,4,"",0,4,"o",2,0,-1,0,494,494,"3263","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3264",0,"Ya sé qu' estás en camisa,\nEn la bentana escuchando,\nY en un paper escribiendo\nLas coplas que boy cantando.",0,0,-1,4,"",0,4,"ao",33,0,-1,0,494,495,"3264","",0,"","","",1,0,0,[],""],["rm_t2-n3265",0,"Tú t' estás en tu camita\nArropadita y caliente,\nY yo por las esquinitas,\nTitirití con los dientes.",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,495,495,"3265","",0,"","","",1,0,0,[],""],["rm_t2-n3266",0,"Despierta, madama hermosa,\nDe ese sueño tan profundo,\nQue no es razon que tú duermas\nY yo pene por el mundo.",0,0,-1,4,"",0,4,"uo",179,0,-1,0,495,495,"3266","",0,"","","",1,0,0,[],""],["rm_t2-n3267",0,"Despierta der durse sueño\nQu' er dibino Dios t' ha dado,\nQue para dártelo á tí,\nA otro se lo habrá quitado.",0,0,-1,4,"",0,4,"ao",14,0,-1,0,495,495,"3267","",0,"","","",1,0,0,[],""],["rm_t2-n3268",0,"Despiértate, noble dama;\nDespiértate, hermosa niña;\nLa dama que tiene amores\nNo debe de estar dormida.",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,495,495,"3268","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3269",0,"Despierta, calandria hermosa,\nQue en tu puerta hay un gilguero,\nEn tu garganta una rosa\nY en tu pecho un prisionero.",0,0,-1,4,"",1,4,"eo",38,0,-1,0,495,495,"3269","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3270",0,"Despierta si estás dormida,\nBuérbete del otro lado,\nDale un beso á l' armohada\nY dí qu' á mí me lo has dado.",0,0,-1,4,"",0,4,"ao",14,0,-1,0,495,495,"3270","",0,"","","",5,0,0,[],""],["rm_t2-n3271",0,"Ya tú m' habrás conosido\nEn er l' eco de la bos\nY dirás desde la cama:\n-Ese que canta es mi amor.",0,0,-1,4,"",0,4,"o",-1,0,-1,0,495,496,"3271","",0,"","","",1,0,0,[],""],["rm_t2-n3272",0,"Debajo de tu bentana\nTiene la perdís su nido,\nY yo, como perdigon,\nA su reclamo he benido.",0,0,-1,4,"",0,4,"io",-1,0,-1,0,496,496,"3272","",0,"","","",1,0,0,[],""],["rm_t2-n3273",0,"La guitarra es de marfil,\nDe oro las cuerdas y el puente,\nY el tañedor que la tañe,\nSalada, tu pretendiente.",0,0,-1,4,"",0,4,"ee",15,0,-1,0,496,496,"3273","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3274",0,"Dame de tu pelo rubio\nCuerdas para mi bigüela,\nQue mes' ha roto la prima,\nCuarta, segunda y tersera.",0,0,-1,4,"",0,4,"ea",-1,0,-1,0,496,496,"3274","",0,"","","",4,0,0,[],""],["rm_t2-n3275",0,"Aquí me manda cantar\nUn enamorado tuyo;\nSi no lo quieres creer,\nUn pié tengo sobre el suyo.",0,0,-1,4,"",0,4,"uo",78,0,-1,0,496,496,"3275","",0,"","","",1,0,0,[],""],["rm_t2-n3276",0,"A la puerta de mi novia\nMi compañero cantó;\nA la puerta de la suya\nEs razon que cante yo.",0,0,-1,4,"",0,4,"o",2,0,-1,0,496,496,"3276","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3277",0,"No s' armire usté, señora,\nQu' un sordao eser que canta;\nCon er pan de mulision\nTengo mala la garganta.",0,0,-1,4,"",0,4,"aa",148,0,-1,0,496,496,"3277","",0,"","","",1,0,0,[],""],["rm_t2-n3278",0,"Señora, tu enamorado\nEstá aquí, pero no canta,\nPorque 'r porbo der camino\nL' h' apretado la garganta.",0,0,-1,4,"",0,4,"aa",148,0,-1,0,496,497,"3278","",0,"","","",2,0,0,[],""],["rm_t2-n3279",0,"Ahora sí que canto claro,\nQue he tomado caramelo,\nQue me lo dió una gitana\nCon muchísimo salero.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,497,497,"3279","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3280",0,"Aquí me tienes penando,\nDueño de mi corazon,\nPues vengo de contrabando\nY no puedo alzar la voz.",0,0,-1,4,"",0,4,"o",-1,0,-1,0,497,497,"3280","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3281",0,"Señora, tu enamorado\nEs mi amigo y lo ha de ser;\nCelebraría en el alma\nQue te casaras con él.",0,0,-1,4,"",0,4,"e",-1,0,-1,0,497,497,"3281","",0,"","","",2,0,0,[],""],["rm_t2-n3282",0,"Aunque no canta, aquí viene,\nSalada, tu enamorado;\nAunque no canta, aquí viene;\nAquí lo tengo á mi lado.",0,0,-1,4,"",1,4,"ao",14,0,-1,0,497,497,"3282","",0,"","","",3,0,0,[],""],["rm_t2-n3283",0,"Quien la música ha traido\nNo está aquí ni viene aquí;\nPero está tan retirado\nComo la ropa de mí.",0,0,-1,4,"",3,4,"i",23,0,-1,0,497,497,"3283","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3284",0,"Si quieres saber, señora,\nQuién la música ha traído,\nFrancisco tiene por nombre;\nAdivina el apellido.",0,0,-1,4,"",0,4,"io",101,0,-1,0,497,497,"3284","",0,"","","",3,0,0,[],""],["rm_t2-n3285",0,"Si quieres saber, hermosa,\nQuién te ha venido á cantar,\nEs un mozo aragonés\nQue te tiene voluntad.",0,0,-1,4,"",0,4,"a",-1,0,-1,0,497,498,"3285","",0,"","","",3,0,0,[],""],["rm_t2-n3286",0,"Una copliya en tu abono\nM' han mandado que te eche;\nEres más rubia qu' el oro\nY más blanca que la leche.",0,0,-1,4,"",0,4,"ee",180,0,-1,0,498,498,"3286","",0,"","","",1,0,0,[],""],["rm_t2-n3294",0,"Si por miedo de tus amos\nNo te asomas al balcon,\nMucho puede la obediencia,\nPero más puede el amor.",0,0,-1,4,"",0,4,"o",-1,0,-1,0,504,504,"3294","",0,"","","",1,0,0,[],""],["rm_t2-n3295",0,"Asómate á esa ventana,\nOjos y cara de cielo,\nY con la luz de tus ojos\nLa vihuela templaremos.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,504,504,"3295","",0,"","","",50,0,0,[],""],["rm_t2-n3296",0,"Asómate á esa ventana,\nBeya dama, y te beré\nY con la lus de tus ojos\nEr sigarro ensenderé.",0,0,-1,4,"",0,4,"e",77,0,-1,0,504,504,"3296","",0,"","","",50,0,0,[],""],["rm_t2-n3297",0,"Asómate á esa ventana\nY dame un poco de lumbre\nPara encender el cigarro,\nPor no perder la costumbre.",0,0,-1,4,"",0,4,"ue",181,0,-1,0,504,504,"3297","",0,"","","",50,0,0,[],""],["rm_t2-n3298",0,"Asómate á esa ventana,\nCara de piñon de oro;\nQuiero encender el cigarro\nEn el fuego de tus ojos.",0,0,-1,4,"",0,4,"oo",-1,0,-1,0,504,504,"3298","",0,"","","",50,0,0,[],""],["rm_t2-n3299",0,"Asómate á esa ventana,\nHermosura de la tierra,\nY verás en el instante\nAl sol parar su carrera.",0,0,-1,4,"",0,4,"ea",-1,0,-1,0,504,504,"3299","",0,"palau_cantares, lafuente_madrid","","",50,0,0,[],""],["rm_t2-n3300",0,"Asómate á esa ventana,\nHermosísima diadema;\nQue aunque está la noche oscura,\nTú de claridad la llenas.",0,0,-1,4,"",0,4,"ea",-1,0,-1,0,504,504,"3300","",0,"lafuente_madrid","","",50,0,0,[],""],["rm_t2-n3301",0,"Asómate á ese balcon,\nAsómate, luz divina;\nVerás con tu resplandor\nTu amante, que está en la esquina.",0,0,-1,4,"",0,4,"ia",11,0,-1,0,505,505,"3301","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t2-n3302",0,"Asómate á ese balcon,\nY si nó, á la ventanilla,\nY si no tienes ventana,\nA la puerta, vida mia.",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,505,505,"3302","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t2-n3303",0,"Asómate á esa bentana,\nSi te quieres asomá,\nY mira no te lastimes\nEse pecho de cristá.",0,0,-1,4,"",0,4,"a",9,0,-1,0,505,505,"3303","",0,"","","",4,0,0,[],""],["rm_t2-n3304",0,"Asómate á esa ventana,\nNiña, si quieres oir\nLas coplas de un firme amante,\nQue las canta un serafin.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,505,505,"3304","",0,"palau_cantares, lafuente_madrid","","",50,0,0,[],""],["rm_t2-n3305",0,"Asómate á esa ventana,\nCara de luna redonda,\nLucero de la mañana,\nEspejo de quien te ronda.",0,0,-1,4,"",1,4,"oa",182,0,-1,0,505,505,"3305","",0,"","","",50,0,0,[],""],["rm_t2-n3306",0,"Asómate á esa ventana,\nCara de luna brillante;\nQue aunque yo no te pretendo,\nConmigo viene tu amante.",0,0,-1,4,"",0,4,"ae",47,0,-1,0,505,505,"3306","",0,"palau_cantares, lafuente_madrid","","",50,0,0,[],""],["rm_t2-n3307",0,"Asómate á esa ventana,\nSi te quieres asomar;\nVerás la calle barrida\nPor la capa de un galan.",0,0,-1,4,"",0,4,"a",-1,0,-1,0,505,505,"3307","",0,"","","",50,0,0,[],""],["rm_t2-n3308",0,"Asómate á esa ventana,\nA la que da sobre el rio,\nManojo de clavellinas\nCogidas con el rocío.",0,0,-1,4,"",0,4,"io",3,0,-1,0,506,506,"3308","",0,"","","",50,0,0,[],""],["rm_t2-n3309",0,"Asómate á esa ventana,\nCara de jazmin florido,\nQue te ha venido á cantar\nEl que ha de ser tu marido.",0,0,-1,4,"",0,4,"io",101,0,-1,0,506,506,"3309","",0,"","","",50,0,0,[],""],["rm_t2-n3310",0,"Vámonos, compañeritos,\nQue las cabrillas van altas\nY viene la luz del dia\nA descubrir nuestras faltas.",0,0,-1,4,"",0,4,"aa",183,0,-1,0,506,506,"3310","",0,"","","",11,0,0,[],""],["rm_t2-n3311",0,"La luna se va á poner;\nYa hacen sombra los tejados;\n¿Cómo me despediré\nDe estos claveles dorados?",0,0,-1,4,"",0,4,"ao",18,0,-1,0,506,506,"3311","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3312",0,"Con esta copla, señores,\nDe mi niña me despido;\nQue mi madre ya dirá:\n-¿Dónde andará ese perdido?",0,0,-1,4,"",0,4,"io",101,0,-1,0,506,506,"3312","",0,"","","",5,0,0,[],""],["rm_t2-n3313",0,"Canto ésta y uo más canto,\nPorque me voy á dormir;\nQue mañana, si Dios quiere,\nNádie velará por mí.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,506,506,"3313","",0,"","","",1,0,0,[],""],["rm_t2-n3314",0,"De tu puerta, bella aurora,\nSe despide un valenciano,\nCon un clavel en la boca\nY una rosa en cada mano.",0,0,-1,4,"",0,4,"ao",81,0,-1,0,506,506,"3314","",0,"","","",1,0,0,[],""],["rm_t2-n3315",0,"Adios, que ya me despido\nDe tu cerrojo y aldaba\nY de tí no me despido,\nPorque se me arranca el alma.",0,0,-1,4,"",0,4,"aa",-1,0,-1,0,507,507,"3315","",0,"","","",2,0,0,[],""],["rm_t2-n3316",0,"Mañana por la mañana\nLevántate tempranito\nY verás en tu ventana\nDe yerbabuena un ramito.",0,0,-1,4,"",1,4,"io",119,0,-1,0,507,507,"3316","",0,"","","",14,0,0,[],""],["rm_t2-n3317",0,"Mañana por la mañana,\nÁntes de que salga el sol,\nEn el quicio de tu puerta\nDejaré mi corazon.",0,0,-1,4,"",0,4,"o",-1,0,-1,0,507,507,"3317","",0,"lafuente_madrid","","",14,0,0,[],""],["rm_t2-n3318",0,"En los clabos de tu puerta\nSe queda mi corason;\nLebántate tempranito,\nNo me lo marchite el sol.",0,0,-1,4,"",5,4,"o",-1,0,-1,0,507,507,"3318","",0,"","","",1,0,0,[],""],["rm_t2-n3320",0,"La despedida te echo;\nNo te la quisiera echar;\nCon lágrimas de mis ojos\nQueda regado el umbral.",0,0,-1,4,"",0,4,"a",-1,0,-1,0,507,507,"3320","",0,"palau_cantares","","",5,0,0,[],""],["rm_t2-n3321",0,"Ahí te va la despedida,\nCon corona, ramo y palma;\n¡Esta sí que es despedida\nDe dos amantes del alma!",0,0,-1,4,"",1,4,"aa",125,0,-1,0,507,507,"3321","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n3322",0,"La despedía te echo,\nLa que Cristo echó en er coro;\nAdios, rosa; adios clabé;\nAdios, pimpoyo de oro.",0,0,-1,4,"",0,4,"oo",85,0,-1,0,508,508,"3322","",0,"","","",4,0,0,[],""],["rm_t2-n3323",0,"La despedía te echo,\nLa que Cristo echó en er monte;\nQuédate con Dios, morena,\nHasta mañana á la noche.",0,0,-1,4,"",0,4,"oe",-1,0,-1,0,508,508,"3323","",0,"","","",4,0,0,[],""],["rm_t2-n3324",0,"La despedía te echo,\nLa que Cristo echó en la gloria;\nAr que borbiere á cantá\nQue se le muera la nobia.",0,0,-1,4,"",0,4,"oa",-1,0,-1,0,508,508,"3324","",0,"","","",4,0,0,[],""],["rm_t2-n3325",0,"Echemos la despedía\nAl uso de mi lugá:\nMás bale poquito y güeno\nQue nó mucho y enfadá.",0,0,-1,4,"",0,4,"a",9,0,-1,0,508,508,"3325","",0,"","","",4,0,0,[],""],["rm_t2-n3327",0,"Echemos la despedía\nAl uso de Barcelona:\nLa madre que te parió\nSe merese una corona.",0,0,-1,4,"",0,4,"oa",7,0,-1,0,508,508,"3327","",0,"","","",4,0,0,[],""],["rm_t2-n3328",0,"Echemos la despedía,\nLa qu' echan los jarrieros:\nCon la bara en la sintura,\n«¡Jarre, borrico platero!»",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,508,508,"3328","",0,"","","",4,0,0,[],""],["rm_t2-n3336",0,"Si tuviera una naranja,\nContigo la partiria:\nPero como no la tengo,\nTe canto la despedida.",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,510,510,"3336","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3337",0,"La despedía han echao;\nCabayeros, ¿qué habeis hecho?\nParese que m' habeis dao\nUna puñalâ en er pecho.",0,0,-1,4,"",1,4,"eo",60,0,-1,0,510,510,"3337","",0,"","","",1,0,0,[],""],["rm_t2-n3338",0,"La despedida te echo\nCon el pañuelo en la mano;\nMira si te quiero bien,\nQue me despido llorando.",0,0,-1,4,"",0,4,"ao",-1,0,-1,0,510,510,"3338","",0,"","","",5,0,0,[],""],["rm_t2-n3339",0,"La despedida te echo;\nNo te la quisiera echar;\nPero se van mis amigos\nY me tengo que marchar.",0,0,-1,4,"",0,4,"a",21,0,-1,0,510,510,"3339","",0,"","","",5,0,0,[],""],["rm_t2-n3340",0,"Echemos la despedía\nCon un ramito de nueses;\nEsto no ha balido nada\nPâ lo qu' usté se merese.",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,510,510,"3340","",0,"","","",4,0,0,[],""],["rm_t2-n3341",0,"Echemos la despedida,\nEchémosla muy corteses,\nQue es hija de buenos padres\nY ella bien se lo merece.",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,510,510,"3341","",0,"palau_cantares, lafuente_madrid","","",18,0,0,[],""],["rm_t2-n3342",0,"La despedida te doy;\nLa despedida voy dando;\nEsta sí que es despedida,\nQue me despido cantando.",0,0,-1,4,"",0,4,"ao",33,0,-1,0,510,510,"3342","",0,"palau_cantares, lafuente_madrid","","",9,0,0,[],""],["rm_t2-n3343",0,"Me despido de tu puerta\nCon la mano en la paré;\nMira no te quês dormía,\nQue yo pronto borberé.",0,0,-1,4,"",0,4,"e",77,0,-1,0,511,511,"3343","",0,"","","",3,0,0,[],""],["rm_t2-n3344",0,"La despedida te echo,\nSeñora, porque nos bamos;\nMis compañeros y yo\nTodos te besan la mano.",0,0,-1,4,"",0,4,"ao",-1,0,-1,0,511,511,"3344","",0,"","","",5,0,0,[],""],["rm_t2-n3345",0,"Te echaré la despedida\nDe rositas y claveles\nY un ramito de albahaca,\nPara que de mí te acuerdes.",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,511,511,"3345","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t2-n3346",0,"A la gente d' esta casa\nDios le dé salú y bida;\nTrigo para todo el año;\n¡Esta sí que es despedida!",0,0,-1,4,"",0,4,"ia",37,0,-1,0,511,511,"3346","",0,"","","",1,0,0,[],""],["rm_t2-n3347",0,"La música que t' he dao\nNo ha podio ser más larga,\nPorque bienen tôs borrachos\nY han rompío la guitarra.",0,0,-1,4,"",0,4,"aa",-1,0,-1,0,511,511,"3347","",0,"","","",1,0,0,[],""],["rm_t2-n3348",0,"Del cielo bajará un ángel\nCon una cruz en la mano,\nA acompañar á esta niña,\nPorque nosotros nos vamos.",0,0,-1,4,"",0,4,"ao",-1,0,-1,0,511,511,"3348","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3349",0,"Grande atrevimiento ha sido\nEl ponerme aquí á cantar,\nHabiendo tantos maestros,\nSiendo yo un pobre oficial.",0,0,-1,4,"",0,4,"a",-1,0,-1,0,511,511,"3349","",0,"","","",1,0,0,[],""],["rm_t2-n3350",0,"Señores, ustês perdonen\nPor lo poco y mar cantao,\nQue soy nuebo en el ofisio\nY no estoy desaminao.",0,0,-1,4,"",0,4,"ao",98,0,-1,0,512,512,"3350","",0,"","","",3,0,0,[],""],["rm_t2-n3351",0,"Aunque me voy, no me voy;\nAunque me voy, no me ausento;\nAunque me voy de palabra,\nNo me voy de pensamiento.",0,0,-1,4,"",0,4,"eo",94,0,-1,0,512,512,"3351","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3352",0,"Eres conchita del mar\nY estrellita del Oriente;\nAdios, que me voy sin tí;\nAdios, que me voy sin verte.",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,512,512,"3352","",0,"","","",4,0,0,[],""],["rm_t2-n3353",0,"Adios te digo, y adios\nTe digo con sentimiento;\nAunque te habla mi boca,\nMi corazon está muerto.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,512,512,"3353","",0,"","","",1,0,0,[],""],["rm_t2-n3354",0,"Adios, corazon amado;\nAdios, palma de hermosura;\nAdios, clavel; adios, rosa;\nAdios, hermosa pintura.",0,0,-1,4,"",0,4,"ua",17,0,-1,0,512,512,"3354","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3355",0,"Adios, dueño de mi vida;\nAdios, hechizo del alma;\nAdios, norte de mi amor;\nAdios, mar de mi esperanza.",0,0,-1,4,"",0,4,"aa",-1,0,-1,0,512,512,"3355","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3356",0,"Adios, adios, que me voy\nY no me quisiera ir;\nDame los brazos del alma,\nQue me vengo á despedir.",0,0,-1,4,"",0,4,"i",157,0,-1,0,512,512,"3356","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n3357",0,"Adios, vida de mi vida,\nAdios, corazon amado,\nAdios, que me voy sin verte,\nPorque la ausencia ha llegado.",0,0,-1,4,"",0,4,"ao",14,0,-1,0,513,513,"3357","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t2-n3358",0,"Adios, portal Oreal,\nAdios, la vera del rio,\nAdios, morena del alma;\nAunque me voy, no te olvido.",0,0,-1,4,"",0,4,"io",-1,0,-1,0,513,513,"3358","",0,"","","",1,0,0,[],""],["rm_t2-n3359",0,"Adios, dueño querido,\nPrenda adorada;\nAunque de tí me ausento,\nVas en el alma.",0,0,-1,4,"",6,4,"aa",-1,0,-1,0,513,513,"3359","",0,"","","",2,0,0,[],""],["rm_t2-n3360",0,"Adios, Málaga la beya,\nCastiyo de San Lorenso;\nAdios, María del arma,\nQue por tí me yeban preso.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,513,513,"3360","",0,"","","",4,0,0,[],""],["rm_t2-n3361",0,"Adios, cayes de Triana,\nBentanas y postiguiyos;\nAdios, morena del arma,\nQue por tí boy á presiyo.",0,0,-1,4,"",0,4,"io",-1,0,-1,0,513,513,"3361","",0,"","","",1,0,0,[],""],["rm_t2-n3362",0,"Adios, quédate con Dios;\nAdios, el cielo te guarde;\nUna estrella que te guie\nY un ángel que te acompañe.",0,0,-1,4,"",0,4,"ae",-1,0,-1,0,513,513,"3362","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3363",0,"Quédate con Dios, salada;\nTú te quedas, yo me voy;\nEl aire que entra en tu cuarto\nSon los suspiros que doy.",0,0,-1,4,"",0,4,"o",112,0,-1,0,513,514,"3363","",0,"","","",6,0,0,[],""],["rm_t2-n3364",0,"Adios, adorada prenda,\nQue me vengo á despedir\nY las piedras se quebrantan\nAl ausentarme de tí.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,514,514,"3364","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3365",0,"Adios, mi adorado bien;\nNo me olvides, por tu vida;\nQue yo no te olvidaré\nSi la muerte no me priva.",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,514,514,"3365","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3366",0,"Adios, mi estrella y mi gloria;\nNo pongas en mi lugar\nOtro galan en memoria,\nNi me llegues á olvidar.",0,0,-1,4,"",1,4,"a",21,0,-1,0,514,514,"3366","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3367",0,"Mañana por la mañana\nSe embarca el bien de mi vida;\n¡Mal haya la embarcacion\nY el demonio que la guia!",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,514,514,"3367","",0,"","","",14,0,0,[],""],["rm_t2-n3368",0,"Precipicio cauteloso,\nMañana voy de partida;\nSi la ausencia causa muerte,\n¡Qué corta será mi vida!",0,0,-1,4,"",0,4,"ia",37,0,-1,0,514,514,"3368","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3369",0,"El sábado es esperanza,\nEl domingo es alegría,\nMas el lúnes es tristeza,\nPues se va la prenda mia.",0,0,-1,4,"",0,4,"ia",0,0,-1,0,514,514,"3369","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3370",0,"Dicen que te vas el lúnes;\nNo te vayas hasta el mártes,\nQue tiene mi corazon\nMuchos consejos que darte.",0,0,-1,4,"",0,4,"ae",-1,0,-1,0,514,514,"3370","",0,"","","",3,0,0,[],""],["rm_t2-n3377",0,"Se despiden dos amantes\nAr pié d' una berde oliba;\nComo la oliba es amarga,\nAmarga es la despedida.",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,516,516,"3377","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t2-n3378",0,"Si de tu ausencia no muero,\nY con ella he de morir,\nDigan que soy en el mundo\nLa mujer más infeliz.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,516,516,"3378","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3379",0,"Tengo yo mi corazon\nDomo el de San Agustin,\nLlorando gotas de sangre,\nCuando me aparto de tí.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,516,516,"3379","",0,"","","",14,0,0,[],""],["rm_t2-n3380",0,"¡Ay, mal haya mi fortuna\nY tambien mi mala suerte,\nQue el galan que yo idolatro\nQuieren que de mí se ausente!",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,516,516,"3380","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3381",0,"Sin tí no puedo pasar;\nSin tí no puedo vivir;\nLa vida me ha de costar\nEstar ausente de tí.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,516,516,"3381","",0,"","","",1,0,0,[],""],["rm_t2-n3382",0,"Si oyes que tocan á muerto,\nNo preguntes quién murió;\nPorque ausente de tu vista,\n¿Quién puede ser sino yo?",0,0,-1,4,"",0,4,"o",2,0,-1,0,516,516,"3382","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3383",0,"Amor mio, si te vas,\nEn tu ausencia yo me muero;\nCuando vuelvas me hallarás\nMuerto y sin tener consuelo.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,516,516,"3383","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3384",0,"Quisiera tener un arte\nY con el arte partirme;\nCon una mitá quearme\nY con otra mitá dirme.",0,0,-1,4,"",0,4,"ie",184,0,-1,0,517,517,"3384","",0,"","","",1,0,0,[],""],["rm_t2-n3385",0,"¡Ojalá no te hablara!\n¡Nunca te viera,\nNi gozara tu dulce\nCorrespondencia!\nQue es ménos ánsia\nCarecer de la dicha\nQue abandonarla.",0,0,-1,4,"",4,7,"aa",-1,0,-1,0,517,517,"3385","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3386",0,"Aunque de tí me aparto,\nNunca me ausento,\nPues llevo tu retrato\nDentro del pecho.\nY éste me alienta,\nAliviando los males\nDe larga ausencia.",0,0,-1,4,"",4,7,"ea",-1,0,-1,0,517,517,"3386","",0,"palau_cantares","","",2,0,0,[],""],["rm_t2-n3387",0,"Aunque de tí me ausento,\nTén entendido\nQue te llevo en el pecho\nSiempre conmigo.\nQue allá en su centro,\nPor más que te retires,\nSiempre te encuentro.",0,0,-1,4,"",4,7,"eo",185,0,-1,0,517,517,"3387","",0,"","","",1,0,0,[],""],["rm_t2-n3388",0,"No estaré jamás sin tí,\nQue sólo podrá el rigor\nApartarte de mi vista,\nMas nó de mi corazon.",0,0,-1,4,"",0,4,"o",-1,0,-1,0,517,517,"3388","",0,"","","",6,0,0,[],""],["rm_t2-n3389",0,"Anda véte, corre véte,\nY véte con el seguro\nQue el lado que tú ocupares\nNo lo ocupará ninguno.",0,0,-1,4,"",0,4,"uo",-1,0,-1,0,518,518,"3389","",0,"","","",1,0,0,[],""],["rm_t2-n3390",0,"Si me quieres aguardar\nQue benga de los nabíos,\nSerás tú la más dichosa\nQue de mujer ha nasío.",0,0,-1,4,"",0,4,"io",-1,0,-1,0,518,518,"3390","",0,"","","",1,0,0,[],""],["rm_t2-n3391",0,"Por enmedio de esos mares\nMe voy á buscar la vida;\nAcuérdate, si no vuelvo,\nDe quien tanto te queria.",0,0,-1,4,"",0,4,"ia",-1,0,-1,0,518,518,"3391","",0,"","","",1,0,0,[],""],["rm_t2-n3393",0,"Sordado soy, ¿qué remedio?\nAsí lo quiso la suerte,\nY no me pesa er fusí,\nPero sí dejar de berte.",0,0,-1,4,"",0,4,"ee",134,0,-1,0,518,518,"3393","",0,"","","",1,0,0,[],""],["rm_t2-n3394",0,"Yo no siento ser soldado\nNi cargar con el fusil;\nLo que yo siento es mi novia,\nQue se queda por aquí.",0,0,-1,4,"",0,4,"i",-1,0,-1,0,518,518,"3394","",0,"","","",1,0,0,[],""],["rm_t2-n3395",0,"Er dia qu' á mí me digan\n«Los quintos nuebos se ban»,\nMis ojos serán dos fuentes:\nComo arroyos correrán.",0,0,-1,4,"",0,4,"a",147,0,-1,0,518,519,"3395","",0,"","","",1,0,0,[],""],["rm_t2-n3397",0,"Los quintos se van mañana;\nSe llevan los escogidos\nY las muchachas se quedan\nCon los que el rey no ha querido.",0,0,-1,4,"",0,4,"io",-1,0,-1,0,519,519,"3397","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3398",0,"Mañana se van los quintos;\nYa se va mi corazon;\nLa Vírgen de los Dolores\nLes eche su bendicion.",0,0,-1,4,"",0,4,"o",31,0,-1,0,519,519,"3398","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n3399",0,"Mañana se van los quintos\nY con ellos va mi Pepe;\nYa no tengo quien me traiga\nHorquillas para el rodete.",0,0,-1,4,"",0,4,"ee",-1,0,-1,0,519,519,"3399","",0,"palau_cantares, lafuente_madrid","","",10,0,0,[],""],["rm_t2-n3400",0,"Ya se van los quintos, madre,\nY yo no me quiero ir,\nPorque dejo en esta calle\nUn pimpollo á medio abrir.",0,0,-1,4,"",0,4,"i",157,0,-1,0,519,519,"3400","",0,"","","",8,0,0,[],""],["rm_t2-n3401",0,"Ya se van los quintos, madre,\nPor la puerta de Alcalá;\nYa se van los quintos, madre;\n¡Sabe Dios si volverán!",0,0,-1,4,"",0,4,"a",-1,0,-1,0,519,519,"3401","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["rm_t2-n3402",0,"Adios, puente de Tudela;\nYa se van los cazadores;\nPor debajo pasa el agua;\nPor encima mis amores.",0,0,-1,4,"",0,4,"oe",5,0,-1,0,519,519,"3402","",0,"palau_cantares","","",3,0,0,[],""],["rm_t2-n3403",0,"Adios, padre, y adios, madre,\nY adios, nobia, si la tengo;\nQue boy á pagarle ar rey\nCuatro añiyos que le debo.",0,0,-1,4,"",0,4,"eo",-1,0,-1,0,520,520,"3403","",0,"","","",3,0,0,[],""],["rm_t2-n3404",0,"Adios, porque no sé dónde\nMe destinará mi suerte,\nSi á la Fransia ó á la Italia;\nYa no buerbo más á berte.",0,0,-1,4,"",0,4,"ee",134,0,-1,0,520,520,"3404","",0,"","","",1,0,0,[],""],["rm_t2-n3405",0,"Suspiros que de mí salgan\nY otros que de tí saldrán,\nSi en el camino se encuentran,\n¡Qué de cosas se dirán!",0,0,-1,4,"",0,4,"a",147,0,-1,0,520,520,"3405","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t2-n3406",0,"¡Cuántas veces, vida mia,\nTe asomarás al balcon\nY te quitarás llorando,\nDe ver que no paso yo!",0,0,-1,4,"",0,4,"o",-1,0,-1,0,520,520,"3406","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t2-n3407",0,"Lusero de la mañana,\nPréstame tu claridá\nPara seguirle los pasos\nA mi amante que se ba.",0,0,-1,4,"",0,4,"a",9,0,-1,0,520,520,"3407","",0,"","","",1,0,0,[],""],["rm_t2-n3408",0,"Aguarda, moreno, aguarda;\nAguarda y me iré contigo\nY entre los dos pasaremos\nLa soledá der camino.",0,0,-1,4,"",0,4,"io",-1,0,-1,0,520,520,"3408","",0,"","","",1,0,0,[],""],["rm_t3-n3410",1,"Mi amante ba de camino;\nLa Bírgen baya con él\nY lo traiga en su compaña\nHasta que lo buerba á bé.",1,0,-1,5,"",0,4,"e",-1,0,-1,0,12,12,"3410","",0,"","","",1,0,0,[],""],["rm_t3-n3411",1,"Jasta er mueye fuimos juntos\nY platicando los dos\nY ¡ayí fueron los lamentos,\nCuando eya me dijo adios!",1,0,-1,5,"",0,4,"o",87,0,-1,0,12,12,"3411","",0,"","","",1,0,0,[],""],["rm_t3-n3412",1,"Hasta el muelle fuí con ella;\nEn el muelle la dejé;\n¡Allí fueron los lamentos,\nCuando de ella me aparté!",1,0,-1,5,"",0,4,"e",77,0,-1,0,12,12,"3412","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t3-n3413",1,"L' agarré' la mano\nY la yebé ar mueye;\n¡Que las olitas - der má l' acompañen!\n¡Mi Dios la consuele!",1,0,-1,5,"",3,4,"ee",-1,0,-1,0,12,12,"3413","",0,"","","",1,0,0,[],""],["rm_t3-n3418",1,"Yo me subí á un arto pino\nPor ber si la dibisaba;\nLo que dibisé fué 'r porbo\nDer coche que la yebaba.",1,0,-1,5,"",0,4,"aa",28,0,-1,0,13,13,"3418","",0,"","","",1,0,0,[],""],["rm_t3-n3419",1,"Se fué mi dueño querido\nY solito me ha dejado,\nComo pajarito triste\nDe rama en rama volando.",1,0,-1,5,"",0,4,"ao",-1,0,-1,0,13,13,"3419","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3420",1,"Ya mi dueño se ausentó;\nMe ha dejado sin compaña;\nSe ha llevado mis sentidos\nY las potencias del alma.",1,0,-1,5,"",0,4,"aa",-1,0,-1,0,13,13,"3420","",0,"","","",1,0,0,[],""],["rm_t3-n3421",1,"Faitigas me dieron,\nGanas e yorá,\nCuando te bide - metío 'n er tren,\nLa máquina andá.",1,0,-1,5,"",3,4,"a",9,0,-1,0,13,14,"3421","",0,"","","",2,0,0,[],""],["rm_t3-n3422",1,"Cuando mi gitano\nS' apartó de mí,\nDe las faitigas - que me dieron, mare,\nAr suelo caí.",1,0,-1,5,"",3,4,"i",23,0,-1,0,14,14,"3422","",0,"","","",2,0,0,[],""],["rm_t3-n3423",1,"¡Mal haya mi sueño,\nQue tanto he dormío!\nComo s' ha dío - la mia compañera\nY no la he sentío.",1,0,-1,5,"",3,4,"io",3,0,-1,0,14,14,"3423","",0,"","","",1,0,0,[],""],["rm_t3-n3425",1,"A la Crus de la Ensina\nNo bayas, primo,\nPorque ya la paloma\nNo está 'n er nío.\nPrimo, no bayas,\nPorque ya la paloma\nNo está 'onde 'staba.",1,0,-1,5,"",4,7,"aa",-1,0,-1,0,14,14,"3425","",0,"","","",1,0,0,[],""],["rm_t3-n3426",1,"Yo le pregunté á la luna\nPor tí, mi dueño adorado,\nY me respondió diciendo:\n-Ese hombre se ha ausentado.",1,0,-1,5,"",0,4,"ao",14,0,-1,0,14,14,"3426","",0,"","","",1,0,0,[],""],["rm_t3-n3427",1,"Llévame en la trasera\nDel carro, Pedro,\nPara así estar más cérca\nDel bien que dejo.",1,0,-1,5,"",6,4,"eo",-1,0,-1,0,14,14,"3427","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n3428",1,"Si supiera la estrella\nQue te guiara,\nLa metiera en mi pecho,\n'La venerara.",1,0,-1,5,"",6,4,"aa",57,0,-1,0,15,15,"3428","",0,"","","",2,0,0,[],""],["rm_t3-n3429",1,"Si con er pensamiento\nSe caminara,\nMás de cuatro ratitos\nTe acompañara.",1,0,-1,5,"",6,4,"aa",57,0,-1,0,15,15,"3429","",0,"","","",1,0,0,[],""],["rm_t3-n3431",1,"Suiguiriyas son guindas\nGuindas son flores;\nCamino de Sebiya\nBan mis amores.",1,0,-1,5,"",6,4,"oe",5,0,-1,0,15,15,"3431","",0,"","","",1,0,0,[],""],["rm_t3-n3432",1,"Sólo llevo en mi ausencia\nPor compañero\nEl recuerdo terrible\nDel bien que pierdo.\n¡Qué feliz fuera,\nSi pasadas memorias\nBorrar pudiera!",1,0,-1,5,"",4,7,"ea",44,0,-1,0,15,15,"3432","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3433",1,"Por esas mares adentro\nVa la nave de mi amor\nY mi corazon va en ella\nSirviéndole de timon.",1,0,-1,5,"",0,4,"o",-1,0,-1,0,15,15,"3433","",0,"","","",1,0,0,[],""],["rm_t3-n3434",1,"Todas las mañanas voy\nA la orillita del mar\nY le pregunto á las olas\nSi han visto á mi amor pasar.",1,0,-1,5,"",0,4,"a",21,0,-1,0,15,16,"3434","",0,"","","",12,0,0,[],""],["rm_t3-n3435",1,"Todas las mañanas voy\nA la orillita del rio,\nA preguntarle á las olas.\nSi han visto al cariño mio.",1,0,-1,5,"",0,4,"o",3,0,-1,0,16,16,"3435","",0,"","","",12,0,0,[],""],["rm_t3-n3436",1,"Oliyas der má,\nNo tener sosiego,\nQue s' han yebao-á mi compañerita\nAonde no la beo.",1,0,-1,5,"",3,4,"eo",-1,0,-1,0,16,16,"3436","",0,"","","",1,0,0,[],""],["rm_t3-n3437",1,"Marinero es mi amante,\nMucho lo siento;\nQue andan por esos mares\nMis pensamientos.",1,0,-1,5,"",6,4,"eo",-1,0,-1,0,16,16,"3437","",0,"palau_cantares, fernan_caballero","","",6,0,0,[],""],["rm_t3-n3438",1,"¡Mal haya quien hizo el barco,\nY el que lo arrojó á la mar,\nY el que cortó la madera,\nY el que la mandó cortar!",1,0,-1,5,"",0,4,"a",21,0,-1,0,16,16,"3438","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3439",1,"Marinero, sube al palo\nY dile á mi compañera\nQue si se acuerda de mí\nComo yo me acuerdo de ella.",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,16,16,"3439","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t3-n3440",1,"Ojos que te vieron ir\nPor esos mares afuera,\n¡Cuándo te verán volver\nPara alivio de mis penas!",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,16,16,"3440","",0,"","","",12,0,0,[],""],["rm_t3-n3441",1,"Ojos que te vieron ir\nPor esos mares adentro,\n¡Cuándo te verán venir\nPara mi divertimiento!",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,16,17,"3441","",0,"","","",12,0,0,[],""],["rm_t3-n3443",1,"Ojos que te vieron ir\nPor aquellos olivares,\n¡Cuándo te verán volver\nPara alivio de mis males!",1,0,-1,5,"",0,4,"ae",-1,0,-1,0,17,17,"3443","",0,"palau_cantares, lafuente_madrid","","",12,0,0,[],""],["rm_t3-n3444",1,"Ojos que te vieron ir\nPor aquel camino llano,\n¡Cuándo te verán volver\nCon la licencia en la mano!",1,0,-1,5,"",0,4,"ao",81,0,-1,0,17,17,"3444","",0,"","","",12,0,0,[],""],["rm_t3-n3445",1,"Er camino de Sebiya,\n¡Qué triste 'stá para mí!\nPor ayí se fué mi amante;\n¡Cuándo lo beré benir!",1,0,-1,5,"",0,4,"i",-1,0,-1,0,17,17,"3445","",0,"","","",1,0,0,[],""],["rm_t3-n3446",1,"Deben cegar estos ojos,\nQue ya no te pueden ver;\n¡Ojos que te vieron ir,\nCuándo te verán volver!",1,0,-1,5,"",0,4,"e",20,0,-1,0,17,17,"3446","",0,"","","",1,0,0,[],""],["rm_t3-n3447",1,"Cuando salí de Marbeya\nJasta 'r cabayo yoraba;\nQue me dejé una donseya\nQue ar sor sus rayos quitaba.",1,0,-1,5,"",1,4,"aa",28,0,-1,0,17,17,"3447","",0,"","","",1,0,0,[],""],["rm_t3-n3448",1,"Cuando salí de Sebiya\nBorbí la cara yorando:\n-Adios, tierresita mia,\n¡Qué léjos te bas queando!",1,0,-1,5,"",0,4,"ao",33,0,-1,0,18,18,"3448","",0,"","","",1,0,0,[],""],["rm_t3-n3449",1,"Cuando nos despedimos\nEn el poyete,\nTus ojos fueron rios,\nLos mios fuentes.\nNo me dió pena,\nHasta que me dijistes:\n--Adios, morena.",1,0,-1,5,"",4,7,"ea",59,0,-1,0,18,18,"3449","",0,"","","",1,0,0,[],""],["rm_t3-n3450",1,"El dia que me aparté\nDe tu presencia divina,\nMás lágrimas derramé\nQue lleva el Guadalmedina.",1,0,-1,5,"",1,4,"ia",11,0,-1,0,18,18,"3450","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3451",1,"Nunca supe lo mucho\nQue te quería\nHasta que dió la hora\nDe tu partida.\nPorque se ignora\nEl valor de los bienes\nMiéntras se gozan.",1,0,-1,5,"",4,7,"oa",-1,0,-1,0,18,18,"3451","",0,"","","",3,0,0,[],""],["rm_t3-n3452",1,"Cuando t' apartaron\nE la bera mia,\nYo no comia-bocaíto á gusto,\nPorque no te bía.",1,0,-1,5,"",3,4,"ia",0,0,-1,0,18,18,"3452","",0,"","","",1,0,0,[],""],["rm_t3-n3454",1,"El dia que te ausentaste\nLe eché un candado á mi pecho\nY á mi corazon le dije:\n-Tú quedarás satisfecho.",1,0,-1,5,"",0,4,"eo",60,0,-1,0,19,19,"3454","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n3455",1,"Desde que te ausentastes,\nSol de los soles,\nNi los pájaros cantan\nNi el rio corre.\n¡Ay amor mio!\nNi los pájaros cantan\nNi corre el rio.",1,0,-1,5,"",4,7,"o",3,0,-1,0,19,19,"3455","",0,"","","",1,0,0,[],""],["rm_t3-n3456",1,"Las penas que pasa un perro\nCuando le cortan el rabo,\nEsas mismas pasé yo\nCuando de tí me apartaron.",1,0,-1,5,"",0,4,"ao",-1,0,-1,0,19,19,"3456","",0,"","","",2,0,0,[],""],["rm_t3-n3457",1,"Acaba de dar, acaba,\nRel ó de la catedral,\nQue quiero contar las horas\nQue ausente mi amor está.",1,0,-1,5,"",0,4,"a",-1,0,-1,0,19,19,"3457","",0,"","","",8,0,0,[],""],["rm_t3-n3458",1,"Acaba de dar, acaba,\nBeyo reló de marfí,\nQue quiero contar er tiempo\nQue bibo ausente de ti.",1,0,-1,5,"",0,4,"i",23,0,-1,0,19,19,"3458","",0,"","","",8,0,0,[],""],["rm_t3-n3459",1,"Mi amante se fué y me dijo\nQue cantara y no yorara,\nQu' echara penas al aire,\nPero que no l' olbidara.",1,0,-1,5,"",0,4,"aa",57,0,-1,0,19,20,"3459","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t3-n3461",1,"No estaré jamás sin tí;\nQue sólo podrá el rigor\nSepararte de mi vista,\nMas no de mi corazon.",1,0,-1,5,"",0,4,"o",-1,0,-1,0,20,20,"3461","",0,"","","",6,0,0,[],""],["rm_t3-n3462",1,"¿Qué importa que no te vea,\nSi yo tengo un grande alivio?\nTengo yo mi corazon\nTodas las horas contigo.",1,0,-1,5,"",0,4,"io",-1,0,-1,0,20,20,"3462","",0,"","","",3,0,0,[],""],["rm_t3-n3464",1,"Dicen algunos autores\nQue la ausencia causa olvido;\nYo soy una que no puedo\nOlvidar lo que he querido.",1,0,-1,5,"",0,4,"io",101,0,-1,0,20,20,"3464","",0,"","","",4,0,0,[],""],["rm_t3-n3465",1,"Dicen que el amor ausente\nCon facilidad se olvida;\nAusente lo tengo yo\nY no lo olvido en la vida.",1,0,-1,5,"",0,4,"ia",37,0,-1,0,20,21,"3465","",0,"","","",1,0,0,[],""],["rm_t3-n3466",1,"El amor que te tengo\nEs como sombra;\nCuanto más apartado,\nMás cuerpo toma.\nY eres á un tiempo\nSombra de mis amores,\nPues huyes de ellos.",1,0,-1,5,"",4,7,"eo",-1,0,-1,0,21,21,"3466","",0,"carrizo_salta","","",10,0,0,[],""],["rm_t3-n3467",1,"El querer que te tengo\nSombra parece;\nMientras más apartado,\nMucho más crece.",1,0,-1,5,"",6,4,"ee",64,0,-1,0,21,21,"3467","",0,"","","",4,0,0,[],""],["rm_t3-n3468",1,"Por tí no me pregunta\nMi pensamiento,\nPara que no le diga\nQue estás muy léjos.\nMas le consuela\nMi corazon, que siempre\nTe tiene cérca.",1,0,-1,5,"",4,7,"ea",-1,0,-1,0,21,21,"3468","",0,"","","",1,0,0,[],""],["rm_t3-n3469",1,"Para el mal de la ausencia\nDicen que sirve\nDe alivio el ser mudable;\nMas yo soy firme.",1,0,-1,5,"",6,4,"ie",-1,0,-1,0,21,21,"3469","",0,"","","",1,0,0,[],""],["rm_t3-n3470",1,"A los santos les pido\nQue en esta ausencia\nA tí te dén constancia\nY á mí paciencia.",1,0,-1,5,"",6,4,"ea",46,0,-1,0,21,21,"3470","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n3471",1,"Más bien quiero aguardarte\nQuinientos años,\nQue nó beber las hieles\nDe un desengaño.",1,0,-1,5,"",6,4,"ao",-1,0,-1,0,22,22,"3471","",0,"","","",1,0,0,[],""],["rm_t3-n3472",1,"Desde que me fí ar serbisio\nY que mi tierra dejé\nNo pienso más qu' en mi mare\nY en la mujé que yo sé.",1,0,-1,5,"",0,4,"e",77,0,-1,0,22,22,"3472","",0,"","","",1,0,0,[],""],["rm_t3-n3473",1,"Lucero del mes de Abril,\nEstrella del mes de Mayo,\nDí, ¿cómo te vá sin mí,\nPues yo sin tí no me hallo?",1,0,-1,5,"",0,4,"ao",102,0,-1,0,22,22,"3473","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3474",1,"Muriendo los dos vivimos,\nPorque penamos los dos;\nEstaré sin verte, sí;\nPero sin quererte nó.",1,0,-1,5,"",0,4,"o",-1,0,-1,0,22,22,"3474","",0,"","","",1,0,0,[],""],["rm_t3-n3475",1,"Toítas las mañanas\nM' alebanto y digo:\n-Er luserito - qu' á mí m' alumbraba\nYa no está cormigo.",1,0,-1,5,"",3,4,"io",106,0,-1,0,22,22,"3475","",0,"","","",1,0,0,[],""],["rm_t3-n3477",1,"Por el camino real\nVa una doncellita triste\nEn busca de sus amores;\nNo hay mata que no registre.",1,0,-1,5,"",0,4,"ie",-1,0,-1,0,22,22,"3477","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3478",1,"Dichoso es aquel que tiene\nAmores en el lugar;\nQue yo que los tengo fuera\nLos tengo que ir á buscar.",1,0,-1,5,"",0,4,"a",21,0,-1,0,23,23,"3478","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3479",1,"Ya ba pâ tres lúnes,\nContaítos los yebo,\nQue no diquelo - ' la mía compañera;\nDe duquitas muero.",1,0,-1,5,"",3,4,"eo",-1,0,-1,0,23,23,"3479","",0,"","","",1,0,0,[],""],["rm_t3-n3480",1,"Con lo que me consuelo\nCuando estoy triste\nEs con ver el camino\nPor donde fuiste.",1,0,-1,5,"",6,4,"ie",153,0,-1,0,23,23,"3480","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3481",1,"Mis ojos estaban hechos\nA verte todos los dias\nY ahora se me van pasando\nMeses, semanas y dias.",1,0,-1,5,"",3,4,"a",-1,0,-1,0,23,23,"3481","",0,"","","",1,0,0,[],""],["rm_t3-n3482",1,"Más siento la ausencia tuya\nQue la muerte de mi padre;\n¿Sabes por qué no echo luto?\nPorque la gente no hable.",1,0,-1,5,"",0,4,"ae",-1,0,-1,0,23,23,"3482","",0,"","","",2,0,0,[],""],["rm_t3-n3483",1,"Las estreyitas der sielo\nSe bisten d' asur seleste\nY yo me bisto de negro\nPorque mi amor está ausente.",1,0,-1,5,"",0,4,"ee",-1,0,-1,0,23,23,"3483","",0,"","","",3,0,0,[],""],["rm_t3-n3484",1,"Dosientas sincuenta leguas\nYebo de nabegasion;\nDosientas sincuenta penas\nYebo yo en er corason.",1,0,-1,5,"",0,4,"ao",-1,0,-1,0,23,23,"3484","",0,"","","",1,0,0,[],""],["rm_t3-n3485",1,"Una pena te envio,\nDueño adorado,\nQue es la prenda que tengo\nMás á la mano.\nTantas me quedan,\nQue en número compiten\nCon las estrellas.",1,0,-1,5,"",4,7,"ea",-1,0,-1,0,24,24,"3485","",0,"","","",2,0,0,[],""],["rm_t3-n3486",1,"¿Cómo quieres que tenga\nGusto en el cante,\nSi la prenda que adoro\nNo está delante?",1,0,-1,5,"",6,4,"ae",47,0,-1,0,24,24,"3486","",0,"palau_cantares, fernan_caballero","","",14,0,0,[],""],["rm_t3-n3487",1,"¿Cómo quieres que tenga\nGusto sin verte,\nSi eres la que más quiero\nY estás ausente?",1,0,-1,5,"",6,4,"ee",-1,0,-1,0,24,24,"3487","",0,"palau_cantares, preciso_coleccion","","",14,0,0,[],""],["rm_t3-n3488",1,"En un calabozo oscuro\nEstoy pasando la bía\nSin ber á mi compañera:\n¡Estas sí que son fatigas!",1,0,-1,5,"",0,4,"ia",-1,0,-1,0,24,24,"3488","",0,"","","",1,0,0,[],""],["rm_t3-n3489",1,"Aunque 'stoy en er presiyo\nPor tus malitos quereles,\nMás ganita e berte tengo\nQue salí d' estas paderes.",1,0,-1,5,"",0,4,"ee",-1,0,-1,0,24,24,"3489","",0,"","","",1,0,0,[],""],["rm_t3-n3490",1,"Es el más grande castigo\nEl castigo de no verte;\nDesde aquí te estoy queriendo;\n¡Mal haya mi mala suerte!",1,0,-1,5,"",0,4,"ee",134,0,-1,0,24,24,"3490","",0,"","","",1,0,0,[],""],["rm_t3-n3491",1,"Ya tomaran mis ojos\nA buen partido,\nPor no dejar de verte,\nNo haberte visto.\nCiego dos veces\nQuedé, porque te he visto\nY no he de verte.",1,0,-1,5,"",4,7,"ee",-1,0,-1,0,24,25,"3491","",0,"","","",1,0,0,[],""],["rm_t3-n3493",1,"Ausente estoy de tu vista;\nMis ojos ya no te ven;\nMi corazon se marchita\nDe pensar en tu querer.",1,0,-1,5,"",0,4,"e",-1,0,-1,0,25,25,"3493","",0,"palau_cantares","","",7,0,0,[],""],["rm_t3-n3494",1,"Ausente de tu vista\nLloro y suspiro;\nSolamente descanso\nCuando te miro.\nPorque tú eres\nEl único remedio\nDe mis paeseres.",1,0,-1,5,"",4,7,"ee",55,0,-1,0,25,25,"3494","",0,"","","",5,0,0,[],""],["rm_t3-n3495",1,"Ni veo ni respiro,\nNi oigo ni siento,\nComo que está sin alma\nTodo mi cuerpo.\nY esto depende\nDe ser la ausencia ensayo\nPara la muerte.",1,0,-1,5,"",4,7,"ee",-1,0,-1,0,25,25,"3495","",0,"","","",2,0,0,[],""],["rm_t3-n3496",1,"Ausente del bien que adoro,\n¿Qué dicha podré tener?\nEn mí no reina alegría\nHasta que lo vuelva á ver.",1,0,-1,5,"",0,4,"e",20,0,-1,0,25,26,"3496","",0,"palau_cantares","","",10,0,0,[],""],["rm_t3-n3497",1,"Ausente estoy de tus ojos\nY de tu cara morena;\nAusente del bien que adoro,\n¿Para qué quiero más penas?",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,26,26,"3497","",0,"","","",1,0,0,[],""],["rm_t3-n3498",1,"Con la pena de no verte\nEstoy viviendo en la tierra;\nCuando no me muero yo,\nNádie se muere de pena.",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,26,26,"3498","",0,"","","",5,0,0,[],""],["rm_t3-n3499",1,"Con la pena de no verte\nNo sé cómo tengo vida;\nPero Dios con su poder\nMe tiene fortalecida.",1,0,-1,5,"",0,4,"ia",37,0,-1,0,26,26,"3499","",0,"palau_cantares","","",5,0,0,[],""],["rm_t3-n3500",1,"Pensativa en mi cuarto,\nMil veces digo:\n-Ausente de quien amo,\n¿Cómo es que vivo?",1,0,-1,5,"",6,4,"io",-1,0,-1,0,26,26,"3500","",0,"","","",2,0,0,[],""],["rm_t3-n3501",1,"Ausente del bien que adoro,\nSin esperanza de verte,\nNo puede haber para mí\nMás consuelo que la muerte.",1,0,-1,5,"",0,4,"ee",134,0,-1,0,26,26,"3501","",0,"","","",10,0,0,[],""],["rm_t3-n3502",1,"Ausente del bien que adoro\nMe tiene la ingrata suerte;\nComo infeliz desgraciado,\nAl cielo pido la muerte.",1,0,-1,5,"",0,4,"ee",134,0,-1,0,26,26,"3502","",0,"","","",10,0,0,[],""],["rm_t3-n3503",1,"Ausente de tu vista\nMucho más vivo,\nPorque cada momento\nSe me hace un siglo.\nPero, mi dueño,\nMás que vivir ausente\nMorirme quiero.",1,0,-1,5,"",4,7,"eo",-1,0,-1,0,26,27,"3503","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],""],["rm_t3-n3504",1,"No supe qué era ausencia\nHasta no verte\nY ahora digo que quiero\nMejor la muerte.\nPues en muriendo\nSe acabarán mis penas\nY sufrimientos.",1,0,-1,5,"",4,7,"eo",-1,0,-1,0,27,27,"3504","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3506",1,"Si me quieres ver morir,\nNo pongas al mal remedio:\nQue yo no te vuelva á ver\nY me iré hácia el cementerio.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,27,27,"3506","",0,"","","",7,0,0,[],""],["rm_t3-n3507",1,"¡Bárgam' U ndebé, serrana,\nLo que me cuesta tu ausensia!\nTres años d' enfermedá\nY dos de combalesensia.",1,0,-1,5,"",0,4,"ea",187,0,-1,0,27,27,"3507","",0,"","","",1,0,0,[],""],["rm_t3-n3508",1,"Sacan á un pez del agua\nY al punto es muerto,\nAsí que lo separan\nDe su elemento.\nYo soy lo mismo,\nAsí que me separan\nDe mi cariño.",1,0,-1,5,"",4,7,"io",-1,0,-1,0,27,27,"3508","",0,"","","",1,0,0,[],""],["rm_t3-n3509",1,"Cuatro son las heridas\nQue me atormentan:\nTu hermosura, tu gracia,\nMi amor y ausencia.\nMira si puedo\nVivir con tanta herida\nPor mucho tiempo.",1,0,-1,5,"",4,7,"eo",-1,0,-1,0,28,28,"3509","",0,"","","",2,0,0,[],""],["rm_t3-n3510",1,"Para placeres, tu amor;\nPara dichas, tu presencia;\nPara tormento, tus celos;\nY para muerte, tu ausencia.",1,0,-1,5,"",0,4,"ea",46,0,-1,0,28,28,"3510","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3511",1,"¿Qué he de hacer sin tu vista,\nTriste y ausente,\nSi estaré todo el dia\nSiente que siente,\nY hasta que muera\nEstará el pecho mio\nPena que pena?",1,0,-1,5,"",4,7,"ea",-1,0,-1,0,28,28,"3511","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3512",1,"A la Dolorosa\nL' ayuno los biérnes,\nPâ que me ponga, - compañera mia,\nAonde yo te biere.",1,0,-1,5,"",3,4,"ee",-1,0,-1,0,28,28,"3512","",0,"","","",2,0,0,[],""],["rm_t3-n3513",1,"Todas las horas del dia\nLe estoy pidiendo á Jesús\nQue por su pasion y muerte\nMe lleve donde estás tú.",1,0,-1,5,"",0,4,"u",-1,0,-1,0,28,28,"3513","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3514",1,"Anoche fui á suplicarle\nAr Cristo de la Humirdá\nQue siquiera po' una horita\nMe yebe donde tú estás.",1,0,-1,5,"",0,4,"a",-1,0,-1,0,28,29,"3514","",0,"","","",1,0,0,[],""],["rm_t3-n3515",1,"Si San Rafael me diera\nSus alas para volar\nDonde tengo el pensamiento\nFuera de un vuelo á parar.",1,0,-1,5,"",0,4,"a",21,0,-1,0,29,29,"3515","",0,"","","",5,0,0,[],""],["rm_t3-n3517",1,"¡Quién fuera y llegara ahora\nDonde tengo el pensamiento!\nEl sitio no lo diré,\nPorque no lo sé de cierto.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,29,29,"3517","",0,"","","",3,0,0,[],""],["rm_t3-n3518",1,"¡Quién fuera y llegara ahora\nDonde está mi pensamiento,\nPara llegar y decirle:\n-Muchacha, ¿qué estás haciendo?",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,29,29,"3518","",0,"","","",3,0,0,[],""],["rm_t3-n3519",1,"¡Quién fuera y llegara ahora\nDonde mi moreno está\nY al oido le dijera:\n-Moreno, ¿qué tal te va?",1,0,-1,5,"",0,4,"a",9,0,-1,0,29,29,"3519","",0,"","","",3,0,0,[],""],["rm_t3-n3520",1,"¡Quién estubiera tan arta\nComo la estreya der Norte,\nPara saber lo que hase\nMi morenito esta noche!",1,0,-1,5,"",0,4,"oe",-1,0,-1,0,29,29,"3520","",0,"","","",1,0,0,[],""],["rm_t3-n3521",1,"Si yo hallara una hechicera\nQue me quisiera llevar\nDonde está el bien de mi vida,\nYo le pagara el jornal.",1,0,-1,5,"",0,4,"a",-1,0,-1,0,29,30,"3521","",0,"","","",1,0,0,[],""],["rm_t3-n3522",1,"Cuando suspiro ausente,\nCon tu memoria\nEncuentran dulce calma\nMis penas todas.",1,0,-1,5,"",6,4,"oa",-1,0,-1,0,30,30,"3522","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3523",1,"Beo que no puede ser;\nPero me queda er consuelo\nQue yegarán mis suspiros\nDando muestra e que te quiero.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,30,30,"3523","",0,"","","",1,0,0,[],""],["rm_t3-n3524",1,"Mis amores son del campo\nY no vienen al lugar;\nMis suspiros son correos:\nUnos vienen y otros van.",1,0,-1,5,"",0,4,"a",-1,0,-1,0,30,30,"3524","",0,"murciano_antiguo","","",6,0,0,[],""],["rm_t3-n3525",1,"Camino de la sierra\nVan mis suspiros,\nDerribando carrascas,\nRobles y pinos.",1,0,-1,5,"",6,4,"io",-1,0,-1,0,30,30,"3525","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3526",1,"A Cádiz van mis suspiros,\nAl cuartel de Santa Elena;\nSi yo viera á mi amantito,\nSe me quitaban las penas.",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,30,30,"3526","",0,"","","",1,0,0,[],""],["rm_t3-n3527",1,"Como Sevilla tiene\nFuertes murallas,\nNo pueden mis suspiros\nAtravesallas.",1,0,-1,5,"",6,4,"aa",188,0,-1,0,30,30,"3527","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n3528",1,"Hasta los suspiros mios\nSon más dichosos que yo;\nEllos se van y yo quedo;\nEllos se van y yo nó.",1,0,-1,5,"",0,4,"o",2,0,-1,0,30,31,"3528","",0,"","","",1,0,0,[],""],["rm_t3-n3529",1,"Del hueso de una aceituna\nTengo que hacer una nave,\nPara que vayan y vengan\nMis suspiros por el aire.",1,0,-1,5,"",0,4,"ae",-1,0,-1,0,31,31,"3529","",0,"lafuente_madrid, palau_cantares","","",6,0,0,[],""],["rm_t3-n3530",1,"Del hueso de una aceituna\nTengo de hacer un navío,\nPara que vayan y vengan\nTus suspiros y los mios.",1,0,-1,5,"",0,4,"io",-1,0,-1,0,31,31,"3530","",0,"","","",6,0,0,[],""],["rm_t3-n3531",1,"Suspiros exhalados\nDel pecho mio,\n¡Quién fuera con vosotros\nDonde os envío!",1,0,-1,5,"",6,4,"io",3,0,-1,0,31,31,"3531","",0,"","","",1,0,0,[],""],["rm_t3-n3532",1,"Retrocede á mi pecho,\nSuspiro mio;\nQue en el alma te dejas\nA quien te envío.",1,0,-1,5,"",6,4,"io",3,0,-1,0,31,31,"3532","",0,"","","",1,0,0,[],""],["rm_t3-n3533",1,"Pensamiento que vuelas,\nCorre vé y dile\nA mi amor, que está ausente,\nQue no me olvide.\nPues si me olvida,\nMe llevaré llorando\nToda mi vida.",1,0,-1,5,"",4,7,"ia",37,0,-1,0,31,31,"3533","",0,"","","",4,0,0,[],""],["rm_t3-n3534",1,"Pensamiento que vuelas\nMás que las aves,\nLlévale este suspiro\nA quien tú sabes.\nSé mensajero\nY dime si suspira\nTambien su pecho.",1,0,-1,5,"",4,7,"eo",-1,0,-1,0,31,32,"3534","",0,"","","",4,0,0,[],""],["rm_t3-n3535",1,"Pájaro que alzas el vuelo,\nCon el pico naranjado,\nLlévale noticias mias\nA mi triste enamorado.",1,0,-1,5,"",0,4,"ao",14,0,-1,0,32,32,"3535","",0,"","","",1,0,0,[],""],["rm_t3-n3536",1,"Pajarillo, amoroso\nQue estás llamando\nCon tus dulces gorjeos\nA mi cuidado,\nPor Dios te pido\nQue me digas si sabes\nDel dueño mio.",1,0,-1,5,"",4,7,"o",-1,0,-1,0,32,32,"3536","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3537",1,"Si por esos andurriales\nT' encuentras á mi morena,\nDile qu' estoy trabajando\nPara sacarla de penas.",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,32,32,"3537","",0,"","","",3,0,0,[],""],["rm_t3-n3538",1,"Dígal' usté á esa mujer\nQue no yore por mi ausensia;\nQue no fartará en er mundo\nQuien la consuele en sus penas.",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,32,32,"3538","",0,"","","",1,0,0,[],""],["rm_t3-n3539",1,"Bien conozco que me canso\nSintiendo penas en balde:\nQue lágrimas en la ausencia\nCuestan mucho y nada valen.",1,0,-1,5,"",0,4,"ae",-1,0,-1,0,32,32,"3539","",0,"","","",1,0,0,[],""],["rm_t3-n3540",1,"Ausente de mi vista\nY á tu libertad,\nTemo que se divierta\nTu fragilidad.\nPues si presente\nVivo desconfiado,\n¿Qué será ausente?",1,0,-1,5,"",4,7,"ee",15,0,-1,0,33,33,"3540","",0,"","","",1,0,0,[],""],["rm_t3-n3541",1,"¿Cómo ha de ser la memoria\nEl correo en las ausencias,\nSi no lleva los recados\nNi vuelve con las respuestas?",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,33,33,"3541","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3542",1,"Quien ausente lo tenga,\nMuerto lo llore;\nQue la ausencia y la muerte\nParejas corren.\nYo que tal digo,\nPorque ausente lo tengo\nMuerto lo miro.",1,0,-1,5,"",4,7,"io",-1,0,-1,0,33,33,"3542","",0,"","","",1,0,0,[],""],["rm_t3-n3543",1,"Por más firmeza que haya\nEn nobles pechos,\nEs la ausencia madrastra\nDe los afectos.\nY así los mios\nLos veo en este trance\nCasi perdidos.",1,0,-1,5,"",4,7,"io",-1,0,-1,0,33,33,"3543","",0,"","","",2,0,0,[],""],["rm_t3-n3544",1,"¡Válgame Dios, madama,\nQué ausente vives!\nSi hay papel en tu tierra,\n¿Por qué no escribes?",1,0,-1,5,"",6,4,"ie",189,0,-1,0,33,33,"3544","",0,"","","",1,0,0,[],""],["rm_t3-n3545",1,"Porque mi letra no ves,\nPiensas que de tí me olvido;\nY en el fondo de mi pecho\nA cada instante te escribo.",1,0,-1,5,"",0,4,"io",-1,0,-1,0,34,34,"3545","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3546",1,"Ya no me alegran á mi\nLas fiestas ni los paseos;\nLo que me alegra son cartas\nQue vienen por el correo.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,34,34,"3546","",0,"","","",3,0,0,[],""],["rm_t3-n3547",1,"Er dia que yo m' entere\nQu' er correo 'stá 'n bahía,\nTodas las penas que tengo\nS' han de borber alegrías.",1,0,-1,5,"",0,4,"ia",-1,0,-1,0,34,34,"3547","",0,"","","",1,0,0,[],""],["rm_t3-n3549",1,"Anoche fuí al correo,\nPor ver si habia\nCarta de aquel amante\nQue yo queria.\nNo tuve carta;\nSe vistieron de luto\nMis esperanzas.",1,0,-1,5,"",4,7,"aa",-1,0,-1,0,34,34,"3549","",0,"","","",3,0,0,[],""],["rm_t3-n3551",1,"¡Ay, quién tuviera la pluma\nDe Santo Tomá de Aquino,\nPara escribirle una carta\nA mi amante con cariño!",1,0,-1,5,"",0,4,"io",-1,0,-1,0,34,34,"3551","",0,"","","",2,0,0,[],""],["rm_t3-n3552",1,"Si hubiera papel de oro\nComprara pluma de plata\nY con sangre de mis venas\nTe escribiria una carta.",1,0,-1,5,"",0,4,"aa",-1,0,-1,0,35,35,"3552","",0,"","","",1,0,0,[],""],["rm_t3-n3553",1,"Ya no hay papel en la tienda,\nYa no hay tinta en los tinteros,\nNi plumas tienen las aves\nPara escribirle á mi dueño.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,35,35,"3553","",0,"","","",1,0,0,[],""],["rm_t3-n3554",1,"Tres beses cogí la pluma;\nTres beses cogí er tintero;\nTres beses me se cayó\nEr corason en er suelo.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,35,35,"3554","",0,"","","",1,0,0,[],""],["rm_t3-n3555",1,"En paper blanco t' escribo,\nPorque blanca fué mi suerte;\nEn renglones dibidíos,\nPorque de tí bibo ausente.",1,0,-1,5,"",0,4,"ee",-1,0,-1,0,35,35,"3555","",0,"","","",1,0,0,[],""],["rm_t3-n3556",1,"Este corason tendío,\nSeyado en er paper blanco,\nPara que beas por é\nDe la suerte que yo trato.",1,0,-1,5,"",0,4,"ao",-1,0,-1,0,35,35,"3556","",0,"","","",2,0,0,[],""],["rm_t3-n3557",1,"Este corason tendío,\nCon parma, setro y corona,\nQuiere decir, dueño mio,\nQue mi corason t' adora.",1,0,-1,5,"",0,4,"oa",-1,0,-1,0,35,35,"3557","",0,"","","",2,0,0,[],""],["rm_t3-n3558",1,"Ya no puedo escribir más,\nPorque me fartan las fuersas,\nTan sólo en considerar\nEn tu dilatada ausensia.",1,0,-1,5,"",0,4,"ea",-1,0,-1,0,35,35,"3558","",0,"","","",1,0,0,[],""],["rm_t3-n3560",1,"Te la escribí con la pluma,\nTe la noté con el arma;\nNo preguntes de quién es:\nYa sabes cómo se yama.",1,0,-1,5,"",0,4,"aa",-1,0,-1,0,36,36,"3560","",0,"","","",3,0,0,[],""],["rm_t3-n3561",1,"Llorando te la escribí,\nLlorando te la mandé;\nLas lágrimas de mis ojos\nNo me la dejaron ver.",1,0,-1,5,"",0,4,"e",-1,0,-1,0,36,36,"3561","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3562",1,"En la carta que escribí\nArgunos borrones fueron;\nNo m' eches la curpa á mí:\nSon lágrimas que cayeron.",1,0,-1,5,"",1,4,"eo",105,0,-1,0,36,36,"3562","",0,"","","",1,0,0,[],""],["rm_t3-n3563",1,"Por papel van suspiros;\nPor letras, ánsias;\nPor sobrescrito, penas;\nPor firma, el alma.\nY son los celos\nLos que llevan la carta,\nPor más ligeros.",1,0,-1,5,"",4,7,"eo",-1,0,-1,0,36,36,"3563","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3564",1,"Vuela, papel venturoso,\nQue á manos de un ángel vas;\nNo digas que yo te envío,\nSino que tú sólo vas.",1,0,-1,5,"",0,4,"a",-1,0,-1,0,36,36,"3564","",0,"","","",3,0,0,[],""],["rm_t3-n3565",1,"Papelito venturoso,\n¡Quién fuera dentro de tí,\nPara darle mil abrazos\nAl ángel que te ha de abrir!",1,0,-1,5,"",0,4,"i",-1,0,-1,0,36,37,"3565","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n3567",1,"Dios te dé buenos dias,\nPulida imágen,\nY á las demás personas\nDe tu linage.\nAnda y no llores,\nQue te traigo noticias\nDe tus amores.",1,0,-1,5,"",4,7,"oe",5,0,-1,0,37,37,"3567","",0,"","","",1,0,0,[],""],["rm_t3-n3568",1,"He recibido tu carta\nCon mucho gusto y placer;\nSi no me pongo en camino,\nNo dudes que moriré.",1,0,-1,5,"",0,4,"e",-1,0,-1,0,37,37,"3568","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n3569",1,"Cuando á mis manos llegó\nTu carta, dueño querido,\nTodo el pesar que tenía\nSe convirtió en regocijo.",1,0,-1,5,"",0,4,"io",-1,0,-1,0,37,37,"3569","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n3570",1,"Mi amante con la luna\nMe envía cartas\nY yo con el lucero\nPenas á mantas.",1,0,-1,5,"",6,4,"aa",-1,0,-1,0,37,37,"3570","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n3571",1,"Cartas van, cartas vienen\nPor el correo;\nNada me satisface\nSi no te veo.",1,0,-1,5,"",6,4,"eo",66,0,-1,0,38,38,"3571","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3572",1,"No me mandes papeles,\nQue no sé leer;\nMándame tu persona,\nQue la quiero ver.",1,0,-1,5,"",0,4,"e",20,0,-1,0,38,38,"3572","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],""],["rm_t3-n3573",1,"Me mandastes una carta\nCon una cintita azul;\nNo quiero carta ni cinta,\nQue quiero que vengas tú.",1,0,-1,5,"",0,4,"u",-1,0,-1,0,38,38,"3573","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3575",1,"¡Si yo biera, si yo biera,\nSi yo biera, y agua nó...!\n¡Si yo biera, si yo biera\nAr bien de mi corason...",1,0,-1,5,"",5,4,"ao",-1,0,-1,0,38,38,"3575","",0,"","","",1,0,0,[],""],["rm_t3-n3576",1,"Todo lo que yo amo\nLo tengo léjos;\nNada me satisface\nSi no te veo.\nLo tengo ausente;\nNada me satisface\nDe lo presente.",1,0,-1,5,"",4,7,"ee",15,0,-1,0,38,38,"3576","",0,"","","",1,0,0,[],""],["rm_t3-n3577",1,"Vïudo me considero\nPorque de tí vivo ausente;\nQue la ausencia del amor\nLa comparo con la muerte.",1,0,-1,5,"",0,4,"ee",-1,0,-1,0,38,39,"3577","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3579",1,"En una cama de ausencia\nCayó mala mi esperanza;\nLágrimas, tener paciencia,\nQue el tiempo todo lo alcanza.",1,0,-1,5,"",1,4,"aa",163,0,-1,0,39,39,"3579","",0,"","","",3,0,0,[],""],["rm_t3-n3580",1,"En tierra tan dilatada\nTengo perdido el consuelo:\nMas vivo con la esperanza\nDe verte, y si nó, me muero.",1,0,-1,5,"",0,4,"eo",-1,0,-1,0,39,39,"3580","",0,"","","",1,0,0,[],""],["rm_t3-n3581",1,"La esperanza de verte\nMe tiene viva;\nQue si nó, ya tuviera\nLa tierra encima.",1,0,-1,5,"",6,4,"ia",-1,0,-1,0,39,39,"3581","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n3582",1,"A la vera de un sauce,\nJunto á una fuente,\nSuspiraba un amante\nPor verse ausente.\nY así decía:\n-¿Cuándo volveré á verte,\nBien de mi vida?",1,0,-1,5,"",4,7,"ia",-1,0,-1,0,39,39,"3582","",0,"","","",1,0,0,[],""],["rm_t3-n3583",1,"Estrellita relumbrante,\n¿Cuándo será tu venida,\nQue yo te estoy aguardando\nPara la Pascua florida?",1,0,-1,5,"",0,4,"ia",37,0,-1,0,40,40,"3583","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3584",1,"No siente el pecho mio\nMás alegría\nQue el dia que se acuerda\nDe tu venida.",1,0,-1,5,"",6,4,"ia",-1,0,-1,0,40,40,"3584","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3585",1,"Si supiera la bereda\nPor donde habias de venir,\nFuera yo y la enladriyara\nCon ladriyos de marfil.",1,0,-1,5,"",0,4,"i",-1,0,-1,0,40,40,"3585","",0,"","","",1,0,0,[],""],["rm_t3-n3586",1,"Ya los ojitos me duelen\nDe mirar hácia el camino,\nPor ver si veo venir\nAl espejo en que me miro.",1,0,-1,5,"",0,4,"io",-1,0,-1,0,40,40,"3586","",0,"","","",2,0,0,[],""],["rm_t3-n3587",1,"Deseando estoy, madre,\nQue llegue el viérnes,\nVíspera de otro dia\nQue mi amor viene.",1,0,-1,5,"",6,4,"ee",-1,0,-1,0,40,40,"3587","",0,"","","",2,0,0,[],""],["rm_t3-n3588",1,"Por no sentir mi dama\nTanto mi ausencia,\nBusca quien la consuele\nDe su tristeza.\nY aunque me escribe,\nLa que por mí se muere\nCon otros vive.",1,0,-1,6,"",4,7,"ie",190,0,-1,0,52,52,"3588","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3589",1,"Dias há que lo verde\nMe da inquietudes,\nPorque mis esperanzas\nSe han vuelto azules.",1,0,-1,6,"",6,4,"ue",-1,0,-1,0,52,52,"3589","",0,"rm_t2, palau_cantares, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n3590",1,"Yo tenía una maceta\nDe claveles encarnados;\nDe la noche á la mañana\nSe han vuelto marisalados.",1,0,-1,6,"",0,4,"ao",18,0,-1,0,52,52,"3590","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n3591",1,"Tengo un clavel encarnado\nA la sombra y bajo llave,\nPara que el sol no lo vea\nY con mirarlo lo aje.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,52,52,"3591","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t3-n3592",1,"Porque te quiero te celo,\nQue si nó, no te celara;\nQue si yo no te quisiera,\nAunque el diablo te llevara.",1,0,-1,6,"",0,4,"aa",57,0,-1,0,53,53,"3592","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3593",1,"Al amanecer el dia\nMe despido de tu calle,\nQue la prenda que yo adoro\nNo quiero que otro la guarde.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,53,53,"3593","",0,"","","",3,0,0,[],""],["rm_t3-n3594",1,"Tengo un jardin de rosas;\nPara guardarlo\nNo bastan sus espinas\nNi mi cuidado.\nY receloso,\nPorque no las deshojen,\nYo me desojo.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,53,53,"3594","",0,"","","",1,0,0,[],""],["rm_t3-n3595",1,"Me llaman el celoso;\n¡Mira qué pena!\nSoy labrador y quiero\nGuardar mi hacienda.",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,53,53,"3595","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n3596",1,"Me preguntó un amigo\nLo que eran celos;\nNo sabe el bien que tiene\nCon no saberlo.\nDe buena gana\nTrocara yo mi ciencia\nPor su ignorancia.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,53,53,"3596","",0,"fernan_caballero, palau_cantares","","",3,0,0,[],""],["rm_t3-n3597",1,"Con cuatro letras vivo,\nCon cinco peno,\nDesfallezco con nueve,\nCon doce muero.\nLa cuenta es clara:\nAmor, celos, paciencia,\nDesconfianza.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,53,54,"3597","",0,"","","",3,0,0,[],""],["rm_t3-n3598",1,"En el pozo de celos\nBajé yo á beber;\nTraganteando celos,\nCon sed me quedé.\nQue en este pozo\nTodo el que llega y bebe\nQueda celoso.",1,0,-1,6,"",4,7,"oo",160,0,-1,0,54,54,"3598","",0,"","","",1,0,0,[],""],["rm_t3-n3599",1,"Yo me embarqué en la nave\nDe Amor tirano;\nDesembarqué en el puerto\nDel desengaño.\nY estuve amante\nEn el golfo de celos\nPara anegarme.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,54,54,"3599","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3600",1,"Rios de celos vierte\nEl pecho mio;\nIngratitudes lloro,\nPor más que rio.\nY en el tormento\nEstoy manifestando\nMayor contento.",1,0,-1,6,"",4,7,"eo",94,0,-1,0,54,54,"3600","",0,"","","",1,0,0,[],""],["rm_t3-n3601",1,"Mi pasion he ocultado\nDentro del pecho;\nYa no puedo al presente\nCallar con celos.\n¡Dolor agudo,\nQue sobra para hacerle\nHablar á un mudo!",1,0,-1,6,"",4,7,"uo",191,0,-1,0,54,55,"3601","",0,"","","",1,0,0,[],""],["rm_t3-n3602",1,"Pajarito que lloras\nCon tus gorjeos,\nPorque en tu pecho sientes\nEl mal de celos,\nNo te sonrojes,\nQue por los celos lloran\nTambien los hombres.",1,0,-1,6,"",4,7,"oe",-1,0,-1,0,55,55,"3602","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3603",1,"Yo vivo de lo que como\nY bebo lo que me dan;\nPero masco algunas cosas\nQue no las puedo tragar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,55,55,"3603","",0,"palau_cantares, lafuente_madrid, leonesas_diez","","",5,0,0,[],""],["rm_t3-n3604",1,"En una macetita\nSembré un desvelo;\nFloreció un desengaño\nY cogí celos.\n¡Quién lo creyera\nQue tan buena semilla\nTal fruto diera!",1,0,-1,6,"",4,7,"ea",44,0,-1,0,55,55,"3604","",0,"","","",1,0,0,[],""],["rm_t3-n3605",1,"Tengo un vestido en el arca,\nQue tiene cuatro colores:\nLa ilusion y la esperanza,\nLos celos y los amores.",1,0,-1,6,"",0,4,"oe",5,0,-1,0,55,55,"3605","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3606",1,"Más quiero un desengaño\nQue me confunda\nQue nó vivir penando\nPor una duda.\nPues mis recelos\nHacen de leves dudas\nMuy graves celos.",1,0,-1,6,"",4,7,"eo",192,0,-1,0,55,56,"3606","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3607",1,"Al pié de un verde sauce,\nJunto á una fuente,\nLloraba un afligido\nAmargamente.\nY eran los celos\nLos que á aquel pobre hombre\nLo tenian lelo.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,56,56,"3607","",0,"","","",1,0,0,[],""],["rm_t3-n3609",1,"Como estás esta noche\nTan celosita,\nPareces una rosa\nCon espinitas.",1,0,-1,6,"",6,4,"ia",-1,0,-1,0,56,56,"3609","",0,"fernan_caballero, palau_cantares","","",3,0,0,[],""],["rm_t3-n3610",1,"No quiero pedir celos\nA mi morena,\nPorque sintiera mucho\nQue me los diera.",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,56,56,"3610","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3611",1,"Yo no sé lo que haga\nCon unos celos,\nQue ya estoy para darlos,\nPor no tenerlos.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,56,56,"3611","",0,"","","",2,0,0,[],""],["rm_t3-n3612",1,"¿Para qué pides celos\nA tus cuidados,\nSi has de rabiar con ellos\nSi llego á darlos?",1,0,-1,6,"",6,4,"ao",-1,0,-1,0,56,57,"3612","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3613",1,"Dame, mi bien, pesares;\nDame desvelos;\nDame lo que tú quieras;\nNo me dés celos.",1,0,-1,6,"",6,4,"eo",192,0,-1,0,57,57,"3613","",0,"","","",2,0,0,[],""],["rm_t3-n3614",1,"En insufrible fuego\nDe celos ardo;\nPor eso determino\nMorir matando.\nPorque me alivia\nVer á la que me mata\nTambien herida.",1,0,-1,6,"",4,7,"ia",-1,0,-1,0,57,57,"3614","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3615",1,"En el cáliz amargo\nDe mis disgustos\nSe está labrando el centro\nDe mi sepulcro.\nY mis rivales\nPresenciarán con gusto\nMis funerales.",1,0,-1,6,"",4,7,"ae",26,0,-1,0,57,57,"3615","",0,"","","",1,0,0,[],""],["rm_t3-n3616",1,"Yo m' estoy muriendito,\nYo estoy cadáber;\nEstos pícaros selos\nMuerto me traen.\nPorque los selos\nMatan ar que no sabe\nBibir con eyos.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,57,57,"3616","",0,"","","",1,0,0,[],""],["rm_t3-n3617",1,"Yo puse un epitafio\nEn mi sepulcro\nY un renglon que decia:\n«Quien amar supo.»\nY puse luégo:\n«Aquí murió un amante\nDe puros celos.»",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,57,58,"3617","",0,"","","",1,0,0,[],""],["rm_t3-n3618",1,"Convaleciente estoy\nDe cierto celo\nY me ha dado la vida\nEl no ser cierto.\nQue si lo fuera,\nNi yo respiraria\nNi ella viviera.",1,0,-1,6,"",4,7,"ea",44,0,-1,0,58,58,"3618","",0,"","","",1,0,0,[],""],["rm_t3-n3619",1,"Si yo supiera las piedras\nQue mi amor pisa en la caye,\nLas borbiera der rebés,\nQue no las pisara nádie.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,58,58,"3619","",0,"","","",3,0,0,[],""],["rm_t3-n3620",1,"Mi marido es mi marido,\nQue no es marido de nádie;\nLa que quisiere marido\nVaya á la guerra y lo gane.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,58,58,"3620","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n3621",1,"Los ojos de mi morena,\nSanta Lusía, guardarlos;\nY si no son para mí,\nBenir, cuerbos, y sacarlos.",1,0,-1,6,"",0,4,"ao",193,0,-1,0,58,58,"3621","",0,"","","",23,0,0,[],""],["rm_t3-n3622",1,"Mi amante es tan veleidoso,\nQue no lo veo venir:\n¡Si se estará divirtiendo\nCon flores de otro jardin!",1,0,-1,6,"",0,4,"i",-1,0,-1,0,58,58,"3622","",0,"","","",1,0,0,[],""],["rm_t3-n3624",1,"Si á mí me estuviera bien\nEl andar de noche sola,\nYo sabria si mi amante\nGalantea á otra persona.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,59,59,"3624","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3625",1,"Esperando estoy las doce\nPara salir disfrazada,\nPor ver si hallaré á mi amante\nHablando con otra dama.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,59,59,"3625","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3626",1,"Si supiera qu' argun guapo\nPretendia tu salero,\nLe daba más puñalâs\nQu' estreyitas tiene 'r sielo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,59,59,"3626","",0,"","","",1,0,0,[],""],["rm_t3-n3627",1,"Si supiera, dama hermosa,\nQue otro galan te adoraba,\nCon un penetrante acero\nEl corazon le pasara.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,59,59,"3627","",0,"","","",1,0,0,[],""],["rm_t3-n3628",1,"La gachí que yo camelo,\nSi otro me la camelara,\nSacara mi nabajita\nY er pescueso le cortara.",1,0,-1,6,"",0,4,"aa",57,0,-1,0,59,59,"3628","",0,"","","",3,0,0,[],""],["rm_t3-n3629",1,"Si supiera ó entendiera\nQue otro mozo te procura,\nDebajo de tu ventana\nLe abriera la sepultura.",1,0,-1,6,"",0,4,"ua",17,0,-1,0,59,59,"3629","",0,"lafuente_madrid","","",11,0,0,[],""],["rm_t3-n3630",1,"Si supiera ó entendiera\nQue á otro quieres más que á mí,\nDe puñaladas le diera\nY al rey me fuera á servir.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,60,60,"3630","",0,"palau_cantares","","",11,0,0,[],""],["rm_t3-n3632",1,"En sabiendo tú que yo\nAndo por Andalusía,\nEr gachó que te camela\nNo durará más qu' un día.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,60,60,"3632","",0,"","","",1,0,0,[],""],["rm_t3-n3633",1,"Mucho se para en tu puerta\nEl sereno de esta calle;\nYo le diré que se vaya\nCon la música á otra parte.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,60,60,"3633","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3634",1,"Er sereno de mi caye\nMe quiere quitar la nobia;\nEsta noche nos beremos\nCon er chuso y la pistola.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,60,60,"3634","",0,"","","",1,0,0,[],""],["rm_t3-n3635",1,"Por pillar uno en tu puerta\nAndo que bebo los vientos;\nComo lo llegue á pillar,\nTienes en tu puerta un muerto.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,60,60,"3635","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3636",1,"Cuando sepa, compañera,\nQue otro ocupa mi lugar,\nLa campanita del alba\nA rebato ha de tocar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,60,60,"3636","",0,"","","",1,0,0,[],""],["rm_t3-n3637",1,"El dia que yo te vea\nHablando con quien tú sabes,\nTe cayó la lotería\nDe los números cabales.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,61,61,"3637","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3639",1,"A servir al rey me voy\nCon intencion de volver;\nComo te encuentre casada,\nDe tu sangre he de beber.",1,0,-1,6,"",0,4,"e",20,0,-1,0,61,61,"3639","",0,"","","",5,0,0,[],""],["rm_t3-n3641",1,"Desempedraré tu calle\nY la cubriré de arena,\nPara mirar las pisadas\nDe los que rondan tu reja.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,61,61,"3641","",0,"rm_t2, lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t3-n3642",1,"Quisiera abrir en tu pecho\nUna pequeña ventana,\nPara ver tu corazon\nCon quién comunica y trata.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,61,61,"3642","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3643",1,"Si tuviera cristales\nTu pecho hermoso,\nNo viviera este mio\nTan receloso.",1,0,-1,6,"",6,4,"oo",160,0,-1,0,61,62,"3643","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3645",1,"Si supiera que en otra\nTu amor ponias,\nLe echara un velo negro\nAl alma mia.",1,0,-1,6,"",6,4,"a",-1,0,-1,0,62,62,"3645","",0,"","","",1,0,0,[],""],["rm_t3-n3646",1,"Desventura con celos\nTemen mis dudas;\nMas espero que al cabo\nMe dés ventura.\nAunque, constante,\nMe basta la ventura\nDe ser tu amante.",1,0,-1,6,"",4,7,"ae",47,0,-1,0,62,62,"3646","",0,"","","",1,0,0,[],""],["rm_t3-n3647",1,"Me dicen que á otro quieres,\nPero lo dudo;\nQue mujer tan amante\nFingir no pudo.\nPero te advierto\nQue deseo con ansia\nSaber si es cierto.",1,0,-1,6,"",4,7,"eo",88,0,-1,0,62,62,"3647","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3649",1,"Me han dicho que tienes otra\nQue es más bonita que yo;\nMás bonita sí será;\nPero más amante nó.",1,0,-1,6,"",0,4,"o",2,0,-1,0,63,63,"3649","",0,"andina_t1","","",4,0,0,[],""],["rm_t3-n3650",1,"Me han dicho que tienes otra;\nNo lo niegues ni te escuses;\nQue lo ménos que se encienden\nEn un altar son dos luces.",1,0,-1,6,"",0,4,"ue",194,0,-1,0,63,63,"3650","",0,"","","",4,0,0,[],""],["rm_t3-n3651",1,"Tengo barias personitas\nQue m' escriben, que me notan\nLas horas y los minutos\nQu' estás hablando con otra.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,63,63,"3651","",0,"","","",1,0,0,[],""],["rm_t3-n3652",1,"Si piensas que nada sé\nTe advierto que nada ignoro;\nQue no das paso en la calle\nQue no me lo cuenten todo.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,63,63,"3652","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3653",1,"Si piensas que nada sé\nY crees que todo lo ignoro,\nA quien tú se lo dijistes\nVino y me lo dijo todo.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,63,64,"3653","",0,"","","",4,0,0,[],""],["rm_t3-n3654",1,"En una canariera\nTengo un canario\nQue me trae noticias\nDe tus agravios.",1,0,-1,6,"",6,4,"ao",-1,0,-1,0,64,64,"3654","",0,"","","",1,0,0,[],""],["rm_t3-n3655",1,"Por ocurto que lo jagas\nLo tengo yo de sabé,\nQue tengo por consejero\nDel arto sielo á Undebé.",1,0,-1,6,"",0,4,"e",77,0,-1,0,64,64,"3655","",0,"","","",1,0,0,[],""],["rm_t3-n3656",1,"No te descuides soñando,\nPorque te celan durmiendo:\nLo que á tí te está pasando\nSin querer lo estoy sabiendo.",1,0,-1,6,"",1,4,"eo",52,0,-1,0,64,64,"3656","",0,"","","",1,0,0,[],""],["rm_t3-n3657",1,"-A la luna he mirado\nY he visto en ella\nQue te has enamorado\nDe otra doncella.\n-¿Quién te lo ha dicho?\n-No me lo ha dicho nádie,\nQue yo lo he visto.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,64,64,"3657","",0,"","","",1,0,0,[],""],["rm_t3-n3658",1,"Los ojitos de tu cara\nNo los buerbo yo á mirar,\nPorque sé que tienes otra\nPuestesita en mi lugar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,64,64,"3658","",0,"","","",1,0,0,[],""],["rm_t3-n3659",1,"Ya sé los pasos que traes,\nAunque me lo niegas siempre;\nAnda te en ese camino:\nCántaro que va á la fuente....",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,64,64,"3659","",0,"","","",1,0,0,[],""],["rm_t3-n3660",1,"Conosiendo tú mi genio,\nSabiendo que estoy selosa,\nY por darme que sentir\nTe pones á hablar con otra.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,65,65,"3660","",0,"","","",1,0,0,[],""],["rm_t3-n3661",1,"Como fiera leona\nQue anda en el soto\nMe pongo cuando veo\nQue hablas con otro.",1,0,-1,6,"",6,4,"oo",-1,0,-1,0,65,65,"3661","",0,"","","",1,0,0,[],""],["rm_t3-n3662",1,"Con otro has llegado á hablar;\nTú nunca podrás decir\nQue yo te he dado mal pago,\nComo tú me has dado á mí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,65,65,"3662","",0,"","","",1,0,0,[],""],["rm_t3-n3663",1,"Sé que finezas haces\nA otro sujeto;\nBien puedes, pues he sido\nYo tu maestro.\nNo te equivoques\nY por costumbre en ellas\nA mí me nombres.",1,0,-1,6,"",4,7,"oe",-1,0,-1,0,65,65,"3663","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3664",1,"La otra noche yobiendo\nPensé orbidarte,\nPorque estaba yo biendo\nSegundo amante.\nY yo no quiero\nQue haya segundo amante,\nY más yo biendo.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,65,65,"3664","",0,"","","",1,0,0,[],""],["rm_t3-n3665",1,"Vengo más encendida\nQue la granada,\nPorque he visto á mi amante\nPelar la pava.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,65,65,"3665","",0,"","","",1,0,0,[],""],["rm_t3-n3666",1,"Mis ojos fueron testigos\nDe berte con otro hablar;\nSi no es berdá lo que digo,\nNo bea la claridá.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,66,66,"3666","",0,"","","",4,0,0,[],""],["rm_t3-n3667",1,"El corazon tengo herido\nY la sangre la provoco,\nDesde que te ví ayer tarde\nPelar la pava con otro.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,66,66,"3667","",0,"palau_cantares","","",6,0,0,[],""],["rm_t3-n3668",1,"Todas mis esperanzas\nSe me han frustrado,\nPues te he visto esta tarde\nCon otro al lado.\nYo te observaba;\nPero tú no atendias\nA mis miradas.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,66,66,"3668","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n3669",1,"Si quieres que yo te quiera,\nHas de olvidar á quien amas;\nQue sopitas añadidas\nLas como de mala gana.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,66,66,"3669","",0,"lafuente_madrid, palau_cantares","","",23,0,0,[],""],["rm_t3-n3670",1,"Si quieres que yo te quiera\nSahúmate con romero,\nQue te se quite el olor\nDe los amores primeros.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,66,66,"3670","",0,"","","",23,0,0,[],""],["rm_t3-n3671",1,"Aunque de azul me visto,\nNo soy celosa;\nPero por Dios te pido\nNo hables con otra.",1,0,-1,6,"",6,4,"oa",-1,0,-1,0,66,66,"3671","",0,"","","",2,0,0,[],""],["rm_t3-n3672",1,"Aunque á tí te parezca,\nNo soy celosa,\nNi le quito á mi amante\nQue hable con otra;\nPero te advierto\nQue mucha confianza\nNo la consiento.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,66,67,"3672","",0,"","","",1,0,0,[],""],["rm_t3-n3673",1,"Está celoso mi amor;\nNo quiero que hables con nádie,\nSino con tu confesor,\nCon tu padre y con tu madre\n[Con tus hermanos y yo].",1,0,-1,6,"",7,5,"o",-1,0,-1,0,67,67,"3673","",0,"","","",1,0,0,[],""],["rm_t3-n3675",1,"Cuando bayas á la iglesia,\nPonte un belito 'n la cara,\nQue los santos, con ser santos,\nDe los artares se bajan.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,67,67,"3675","",0,"","","",1,0,0,[],""],["rm_t3-n3676",1,"Compañerita del arma,\nNo pases por la Bitoria,\nNo sarga un santo y te quite\nMi queré de la memoria.",1,0,-1,6,"",0,4,"oa",126,0,-1,0,67,67,"3676","",0,"","","",2,0,0,[],""],["rm_t3-n3677",1,"Cuando miras á otra,\nMe desbarato,\nPorque con las miradas\nSe hacen los tratos.\nY yo quisiera\nQue todas las miradas\nPara mí fueran.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,67,67,"3677","",0,"","","",1,0,0,[],""],["rm_t3-n3678",1,"Si el establecer leyes\nEn mí estuviera,\nQue nádie te mirara\nUna ley fuera.\nPorque me temo\nQue todo el que te mire\nTe adore luégo.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,68,68,"3678","",0,"","","",1,0,0,[],""],["rm_t3-n3679",1,"Contar las estrellitas\nQue hay en el cielo\nEs mas fácil que calmen\nPor hoy mis celos.\nPorquelos tengo\nDel aire que respiras\nY hasta del cielo.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,68,68,"3679","",0,"","","",1,0,0,[],""],["rm_t3-n3680",1,"Tengo celos del aire\nQue da en tu cara;\n¡Si el aire fuera hombre\nYo lo matara!",1,0,-1,6,"",6,4,"aa",57,0,-1,0,68,68,"3680","",0,"","","",3,0,0,[],""],["rm_t3-n3682",1,"Hasta al agua que bebes\nLe tengo envidia;\n¡Mira si tendré celos\nDe quien te mira!",1,0,-1,6,"",6,4,"ia",-1,0,-1,0,68,68,"3682","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3683",1,"«¡Yo te adoro!» una noche\nDije dormido\nY desperté celoso\nDe haberme oido.\nPorque pensaba\nQue alguno te decia\nQue te adoraba.",1,0,-1,6,"",4,7,"aa",28,0,-1,0,68,69,"3683","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3684",1,"Quítate de esa ventana;\nNo me seas ventanera;\nQue la cuba de buen vino\nNo necesita bandera.",1,0,-1,6,"",0,4,"ea",44,0,-1,0,69,69,"3684","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t3-n3685",1,"Más quisiera verte, niña,\nEmbarcadita en el mar\nQue nó pasar por tu puerta\nY verte con otro hablar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,69,69,"3685","",0,"palau_cantares","","",6,0,0,[],""],["rm_t3-n3686",1,"Una peseta le mando\nA las ánimas benditas\nPor que no ronde tu puerta\nAquel que te solicita.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,69,69,"3686","",0,"","","",2,0,0,[],""],["rm_t3-n3687",1,"Serrana, si tú me quieres\nY me tienes boluntá,\nAr gachó que te camela\nDile que no güerba más.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,69,69,"3687","",0,"","","",3,0,0,[],""],["rm_t3-n3688",1,"El que te quiere soy yo\nY el que te lleva en el pecho;\nPero no quiero que quieras\nA ese que yo me sospecho.",1,0,-1,6,"",0,4,"eo",60,0,-1,0,69,69,"3688","",0,"","","",1,0,0,[],""],["rm_t3-n3689",1,"Yo te quiero y no quiero,\nQue son dos cosas;\nYo te quiero y no quiero\nQue hables con otra.",1,0,-1,6,"",6,4,"oa",-1,0,-1,0,69,69,"3689","",0,"palau_cantares","","",5,0,0,[],""],["rm_t3-n3690",1,"Te quiero; pero quiero\nQue tú no quieras\nAl que te quiere y quiere\nQue no me quieras.",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,70,70,"3690","",0,"","","",2,0,0,[],""],["rm_t3-n3691",1,"Por Dios te pido, bien mio,\nQue cuando con otra estés\nNo le hagas los cariños\nQue á mí me sueles hacer.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,70,70,"3691","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n3693",1,"¡Más balía qu' entre cuatro\nTe yebaran á la ilesia\nQue nó que otro te gosara\nDelante de mi presensia!",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,70,70,"3693","",0,"","","",1,0,0,[],""],["rm_t3-n3694",1,"Considera por tí mesmo\nSi tú con otro me bieras\nY tú me quisieras mucho,\nQué fatigas no te dieran.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,70,70,"3694","",0,"","","",1,0,0,[],""],["rm_t3-n3695",1,"Considera por tí propio\nY ponte tú á carculá\nSi tú con otro me bieras,\nQue t' habias de pensá.",1,0,-1,6,"",0,4,"a",9,0,-1,0,70,70,"3695","",0,"","","",1,0,0,[],""],["rm_t3-n3696",1,"Considera por tí propia\nSi tú me bieras á mí\nEstar hablando con otra,\nQué grasia te hisiera á tí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,70,70,"3696","",0,"","","",3,0,0,[],""],["rm_t3-n3697",1,"A ese que á tu casa biene\nArguna caló l' has dao;\nArmítelo si combiene,\nQu' á mí no me da cuidao.",1,0,-1,6,"",1,4,"ao",98,0,-1,0,71,71,"3697","",0,"","","",1,0,0,[],""],["rm_t3-n3698",1,"¿Para qué vienes á berme,\nSi tienes quien te lo estorbe?\nDale gusto á esa persona\nY tén partías de hombre.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,71,71,"3698","",0,"","","",1,0,0,[],""],["rm_t3-n3699",1,"Dueño mio, bienes tarde\nPara mantener parola;\nDonde l' has tenío á prima\nPuedes tenerla á deshora.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,71,71,"3699","",0,"","","",1,0,0,[],""],["rm_t3-n3700",1,"Quiérela y no la dejes,\nQue es muy bonita,\nY aunque sea mi contraria,\nPasion no quita.\nY esto es muy cierto,\nPorque pasion no quita\nConocimiento.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,71,71,"3700","",0,"","","",1,0,0,[],""],["rm_t3-n3701",1,"Anda béte con la otra,\nSupuesto que l' has querío,\nQue yo sembraré 'n mi güerto\nLa semiya del orbío\n[Y la fló del escarmiento.]",1,0,-1,6,"",7,5,"eo",-1,0,-1,0,71,71,"3701","",0,"","","",1,0,0,[],""],["rm_t3-n3702",1,"Tú quieres á dos juntas\nY eso me agravia;\nQuiéreme á mí solita,\nO á mi contraria.\nPorque más vale\nQue haya una satisfecha\nQue dos con hambre.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,71,72,"3702","",0,"","","",2,0,0,[],""],["rm_t3-n3703",1,"¿Qué tenías ayer tarde,\nQue en la ventana llorabas?\n¿Te habia dicho que nó\nEl galan que te adoraba?",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,72,72,"3703","",0,"","","",6,0,0,[],""],["rm_t3-n3704",1,"En tu casa con idea\nEntra y sale cierto amigo\nY luégo vienes diciendo\nQue nada tiene contigo.",1,0,-1,6,"",0,4,"io",106,0,-1,0,72,72,"3704","",0,"","","",1,0,0,[],""],["rm_t3-n3705",1,"No siento que en tu casa\nÉntre ó no éntre;\n¡Que se siente á tu lado\nSí que se siente!",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,72,72,"3705","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n3706",1,"Dices que no la quieres\nNi vas á verla;\nPero la veredita\nNo cria yerba.",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,72,72,"3706","",0,"frenk_t2","","",4,0,0,[],""],["rm_t3-n3707",1,"Con el arma y con la bía\nM' estás disiendo que sí;\nPero con er pensamiento\nA otro quieres más que á mí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,72,72,"3707","",0,"","","",1,0,0,[],""],["rm_t3-n3708",1,"En er sementerio entré\nDando boses como un loco\nY hasta la muerte me dijo\nQue tú querias á otro.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,72,72,"3708","",0,"","","",4,0,0,[],""],["rm_t3-n3709",1,"Que un buen mozo te guste\nNádie lo extraña;\nQue á mí una buena moza\nTambien me agrada.\nPero me espanto\nDe verte enamorada\nDe un currutaco.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,72,73,"3709","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3710",1,"Con el mismo abanico\nQue te echas aire\nEstás haciendo señas\nA quien tú sabes.\nY aquí se halla\nLo que á tí te refresca\nY á mí me abrasa.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,73,73,"3710","",0,"","","",1,0,0,[],""],["rm_t3-n3711",1,"Si á otro cuando me quieres\nLa mano das,\nCuando ya no me quieras,\n¿Qué le darás?\nMas no lo digas;\nQue estaba yo creyendo\nQue eras más fina.",1,0,-1,6,"",4,7,"ia",-1,0,-1,0,73,73,"3711","",0,"","","",2,0,0,[],""],["rm_t3-n3712",1,"Bien pareces á todos;\nMas, sin dobleces,\nQue á todos bien parezcas\nMal me parece.\nY á tí, bien mio,\nParecer bien á todos\nTe ha parecido.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,73,73,"3712","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3713",1,"Siempre que de tu vista\nMe aparto, lloro,\nTemiendo que mis dichas\nLas logre otro.\nQue en mis pesares\nLas dichas son ligeras,\nLargos los males.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,73,74,"3713","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n3714",1,"La gloria de mirarte\nSerá un infierno,\nSi se van tus miradas\nHácia otro dueño.\nQue es muy amargo\nVer en poder ajeno\nBienes logrados.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,74,74,"3714","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3715",1,"Te entraste por los ojos\nCon tal estrago,\nQue por haberte visto,\nCiego he quedado.\nY si algo veo,\nSon las dichas en sombras,\nClaros los celos.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,74,74,"3715","",0,"","","",3,0,0,[],""],["rm_t3-n3716",1,"Dueño mio, no jures,\nQue te condenas;\nSi tienes otra dama,\n¿Por qué lo niegas?",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,74,74,"3716","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3717",1,"Como pájaro humilde\nVengo á tu mano;\nMe desprecias por otro\nQue va volando.",1,0,-1,6,"",6,4,"ao",-1,0,-1,0,74,74,"3717","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3718",1,"Al balcon de mis ansias\nSalgo, luz mia,\nPero siempre te miro\nPor celosía.\nY no es impropio,\nPues el que tiene celos\nEs todo ojos.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,74,75,"3718","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3719",1,"Pues que de mí se ausentan\nTus bellos ojos,\nDéjame por tí, niña,\nQue nó por otro.\nPorque más quiero\nVerme de tí olvidado\nQue sufrir celos.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,75,75,"3719","",0,"","","",1,0,0,[],""],["rm_t3-n3720",1,"De que todos te quieran\nYo no me asusto,\nPues gusto de que todos\nTengan mi gusto.\nPero te aviso\nQue no les correspondas,\nQue no es preciso.",1,0,-1,6,"",4,7,"io",92,0,-1,0,75,75,"3720","",0,"","","",2,0,0,[],""],["rm_t3-n3721",1,"Más quisiera, bien mio,\nVerte difunta,\nQue nó que otro mancebo\nTe llame suya.\nQue de ese modo,\nYa que mia no fueras,\nNo fueras de otro.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,75,75,"3721","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3722",1,"De tus finezas hice\nLos escalones\nPara subir al trono\nDe mis amores.\nPoco han durado,\nQue en batalla los celos\nMe han destronado.",1,0,-1,6,"",4,7,"ao",14,0,-1,0,75,76,"3722","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3723",1,"Tengo amor, tengo ausencia\nY tengo celos;\nTengo desconfianza,\nPues no te tengo.\nSi te tuviera,\nCelos ni otros disgustos\nMe compitieran.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,76,76,"3723","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3724",1,"Deletrea los cielos,\nQuítales la i\nY verás las fatigas\nQue tengo por tí.\nPorque los cielos,\nSi la i se les quita,\nQuedan en celos.",1,0,-1,6,"",4,7,"eo",192,0,-1,0,76,76,"3724","",0,"","","",1,0,0,[],""],["rm_t3-n3725",1,"Son doblados los celos\nQue de tí tengo,\nPues celos no son sólo,\nSino recelos.\nPero fundados\nEn tus facilidades\nY en mis agravios.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,76,76,"3725","",0,"","","",1,0,0,[],""],["rm_t3-n3726",1,"El verme en paz contigo\nYa lo deseo,\nPorque es muy dura guerra\nLa de los celos.\nY así, el dejarte\nSerá el único medio\nDe hacer las paces.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,76,76,"3726","",0,"","","",2,0,0,[],""],["rm_t3-n3727",1,"Dicen que te casas pronto\nY yo pretendo saber\nEl cómo, con quién y cuándo,\nEl cuándo, cómo y con quién.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,77,77,"3727","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n3728",1,"El corazon tengo triste\nY el alma tengo penosa,\nEn ver que yo te he querido\nY que otro galante goza.",1,0,-1,6,"",0,4,"oa",195,0,-1,0,77,77,"3728","",0,"","","",3,0,0,[],""],["rm_t3-n3731",1,"Tú no me pagas la casa;\nTú no me das de comé;\nMe bienes pidiendo selos;\n¿A fundamento de qué?",1,0,-1,6,"",0,4,"e",77,0,-1,0,77,77,"3731","",0,"","","",2,0,0,[],""],["rm_t3-n3733",1,"Con el verde naranjo\nComparo á tu amor;\nNo sazona su fruto\nY ya echa otra flor.",1,0,-1,6,"",0,4,"o",72,0,-1,0,77,77,"3733","",0,"","","",1,0,0,[],""],["rm_t3-n3734",1,"¿Qué importa que yo queme\nEn tus altares\nMás incienso que llanto\nDan mis pesares,\nSi allá en tu templo\nEl último que llega\nQuema el incienso?",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,78,78,"3734","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3735",1,"Yo pensé, dueño mio,\nQue en tu oratorio\nNo se daba más culto\nQue á un santo solo.\nPero ya veo\nQue tienes más santitos\nQue el añalejo.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,78,78,"3735","",0,"","","",2,0,0,[],""],["rm_t3-n3736",1,"Con todos en la calle\nTe paras á hablar\nY luégo á mí me dices\nQue es casualidad.\nEsa es mi pena:\nQue de casualidades\nSiempre estás llena.",1,0,-1,6,"",4,7,"ea",59,0,-1,0,78,78,"3736","",0,"","","",1,0,0,[],""],["rm_t3-n3737",1,"Mi amor es una viña\nDonde yo miro\nPendientes de una cepa\nMuchos racimos.\nSepa mi amante\nQue yo no quiero cepa\nTan abundante.",1,0,-1,6,"",4,7,"ae",47,0,-1,0,78,78,"3737","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3738",1,"El sarmiento en la lumbre\nY el que enamora\nPor un lado se encienden\nPor otro lloran.\nTú eres lo propio:\nCuando lloras por verme\nTe vas por otro.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,78,79,"3738","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3739",1,"Es verdad (lo confieso,\nPues lo preguntas),\nQue tus falsas caricias\nYa me disgustan.\nPorque conozco\nQue estos mismos halagos\nHaces á otros.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,79,79,"3739","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3741",1,"En tu corazoncito\nMe diste un cuarto\nY no pude barrerlo,\nPor tanto trasto.\nYo no lo quiero,\nA ménos que no quites\nTrastos de enmedio.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,79,79,"3741","",0,"","","",2,0,0,[],""],["rm_t3-n3742",1,"Todo el mundo me lo dice;\nDigo que tienen razon:\nQue hombre que trata con muchas\nA ninguna tiene amor.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,79,79,"3742","",0,"preciso_coleccion","","",14,0,0,[],""],["rm_t3-n3744",1,"Eres galan que á todas\nLas apeteces;\nConténtate con una,\nQue no son nueces.",1,0,-1,6,"",6,4,"ee",196,0,-1,0,80,80,"3744","",0,"","","",1,0,0,[],""],["rm_t3-n3745",1,"Yo pensé que de tu pecho\nSolo tenía la llave;\nMas he llegado á entender\nQue todo el que quiere abre.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,80,80,"3745","",0,"","","",3,0,0,[],""],["rm_t3-n3746",1,"Yo pensé que era á mí solo,\nSerrana, á quien tú querias,\nY te diviertes con otro\nTodas las horas del dia.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,80,80,"3746","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3747",1,"Yo creí que era yo solo\nEl que tu jardin regaba\nY ya veo que son muchos\nLos que van y sacan agua.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,80,80,"3747","",0,"","","",2,0,0,[],""],["rm_t3-n3748",1,"En el jardin de mi reina\nEra jardinero yo\nY al tiempo de cojer rosas,\nOtro jardinero entró.",1,0,-1,6,"",0,4,"o",2,0,-1,0,80,80,"3748","",0,"","","",3,0,0,[],""],["rm_t3-n3749",1,"Si piensas que son ganancias\nEl tener á muchos ley,\nEs tan sólo una ignorancia\nQue las mujeres teneis.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,80,80,"3749","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3750",1,"Si por beber de una fuente\nHas dejado secar otra,\nOlvidar para querer\nEs una ignorancia loca.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,81,81,"3750","",0,"suspiros_amor","","",5,0,0,[],""],["rm_t3-n3751",1,"Si por querer á un paisano\nOlvidas á un militar,\nHazte cuenta que has cambiado\nOro fino por metal.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,81,81,"3751","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t3-n3752",1,"Yo te quise á tí solita;\nTú quisistes á un monton;\nTú querias repicar\nY andar en la procesion.",1,0,-1,6,"",0,4,"o",31,0,-1,0,81,81,"3752","",0,"","","",1,0,0,[],""],["rm_t3-n3753",1,"Eres Marta la piadosa,\nTan llena de caridad,\nQue ningun pobre en tu puerta\nDesconsoladito va.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,81,81,"3753","",0,"","","",1,0,0,[],""],["rm_t3-n3754",1,"Cuando por tu puerta paso\nEl corazon se me enluta,\nDe ver que no hay más que un árbol\nY hay muchos para la fruta.",1,0,-1,6,"",0,4,"ua",197,0,-1,0,81,81,"3754","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n3755",1,"Muchos son los privados\nQue en tí se miran;\nSólo á mí, desdichado,\n¿Por qué me privas?",1,0,-1,6,"",6,4,"ia",-1,0,-1,0,81,81,"3755","",0,"","","",2,0,0,[],""],["rm_t3-n3756",1,"Diviértete con todos,\nHaz lo que quieras\nY luégo vén y ponme\nLas aguaderas.\nY aun después falta\nQue á la pila me lleves\nA beber agua.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,81,82,"3756","",0,"","","",1,0,0,[],""],["rm_t3-n3757",1,"Si acaso tú me quieres,\nYo te lo estimo;\nMas no debo fiarme\nDe tu cariño.\nPorque he notado\nQue anda, como pelota,\nDe mano en mano.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,82,82,"3757","",0,"","","",1,0,0,[],""],["rm_t3-n3758",1,"¿Para qué, me andas diciendo\nQue me quieres, que me adoras,\nSi en volviendo las espaldas\nDe cualquiera te enamoras?",1,0,-1,6,"",0,4,"oa",198,0,-1,0,82,82,"3758","",0,"","","",4,0,0,[],""],["rm_t3-n3759",1,"¿Cómo quieres que vaya\nDe noche á verte,\nSi tienes la ventana\nLlena de gente?",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,82,82,"3759","",0,"","","",2,0,0,[],""],["rm_t3-n3760",1,"Te diviertes con quien quieres,\nLuégo vienes con achaques\nA recobrar lo perdido;\n¡Eso, ni con chocolate!",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,82,82,"3760","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t3-n3761",1,"Te diviertes con quien quieres,\nLuégo vienes, me lo niegas\nY quieres con tu saber\nHacer á la gente ciega.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,82,82,"3761","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n3762",1,"A un sujeto conozco\nQue está sujeto\nEn estando delante\nDe otro sujeto.\nPero en no estando,\nAbsuelve al penitente\nque va llegando.",1,0,-1,6,"",4,7,"ao",33,0,-1,0,82,83,"3762","",0,"","","",1,0,0,[],""],["rm_t3-n3763",1,"En mi presencia finges\nNo hay otra cosa\nY en volviendo la espalda\nVuelves la hoja.\nQue eres un tomo\nMás grande que el Tostado\nY con más folios.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,83,83,"3763","",0,"","","",1,0,0,[],""],["rm_t3-n3764",1,"Anda béte noramala;\nYa m' he cansado d' amarte,\nQu' eres faror de retreta,\nQu' alumbras á todas partes.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,83,83,"3764","",0,"","","",1,0,0,[],""],["rm_t3-n3765",1,"El hablar á dos hombres\nRequiere maña\nY el quedarse sin ellos\nNo es cosa extraña.\nEsto lo digo\nPor si acaso pensabas\nJugar conmigo.",1,0,-1,6,"",4,7,"io",106,0,-1,0,83,83,"3765","",0,"","","",1,0,0,[],""],["rm_t3-n3766",1,"Ingrata, mala mujer,\nDe Dios te venga el castigo;\nSi te has de casar con otro,\n¿Para qué tratas conmigo?",1,0,-1,6,"",0,4,"io",106,0,-1,0,83,83,"3766","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3767",1,"Te quiero como si fueras\nHijito de mis entrañas;\nPero si quieres á otra,\n¿Por qué no me desengañas.",1,0,-1,6,"",0,4,"aa",42,0,-1,0,83,84,"3767","",0,"","","",3,0,0,[],""],["rm_t3-n3768",1,"Si me quieres á mí solo\nSeré una muraya firme,\nPero si quieres á otro,\nSeré un rayo en despedirme.",1,0,-1,6,"",0,4,"ie",184,0,-1,0,84,84,"3768","",0,"","","",4,0,0,[],""],["rm_t3-n3769",1,"Si me quieres á mí solo\nDame un vaso de amor lleno;\nPero si quieres á otro,\nDame un vaso de veneno.",1,0,-1,6,"",0,4,"eo",76,0,-1,0,84,84,"3769","",0,"","","",4,0,0,[],""],["rm_t3-n3770",1,"Que te quiero, no lo ignores;\nQue te adoro, sol divino;\nLo que llegaré á sentir\nQue yo sirva de interino.",1,0,-1,6,"",0,4,"io",199,0,-1,0,84,84,"3770","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3771",1,"Algun dia, algun dia\nFuí yo tu aman te\nY ahora me voy quedando\nDe sobrestante.",1,0,-1,6,"",3,4,"ae",-1,0,-1,0,84,84,"3771","",0,"","","",2,0,0,[],""],["rm_t3-n3772",1,"Plato de segunda mesa\nNunca en mi vida lo he sido;\nSi ahora quieres que lo sea\nEstás muy mal entendido.",1,0,-1,6,"",0,4,"io",101,0,-1,0,84,84,"3772","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3773",1,"Por esta calle que es larga\nMe tengo de pasear,\nPor darle gusto á una dama\nY á un majito en qué pensar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,84,84,"3773","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3774",1,"Tú desprecias mis trapitos\nY te vas con los galones;\nUn remiendo mal pegado\nSe lleva las atenciones.",1,0,-1,6,"",0,4,"oe",34,0,-1,0,84,85,"3774","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3775",1,"¿Para qué me diste el sí,\nTraidora, teniendo dueño,\nSi sabes que no se logra\nCon gusto lo que es ajeno?",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,85,85,"3775","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],""],["rm_t3-n3776",1,"Causa de mi perdicion,\nQuiero apartarme de tí;\nLa mujer que quiere á dos\nNo puede tener buen fin.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,85,85,"3776","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3777",1,"Tú tienes amor con otra\nY quieres amor conmigo;\nTú quieres partir amor;\nYo no quiero amor partido.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,85,85,"3777","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n3778",1,"Corazones partidos\nYo no los quiero,\nQue cuando doy el mio,\nLo doy entero.",1,0,-1,6,"",6,4,"eo",38,0,-1,0,85,85,"3778","",0,"palau_cantares, isaacs_colombia, leonesas_diez","","",7,0,0,[],""],["rm_t3-n3779",1,"Yo te quise no pensando\nQue me habias de olvidar;\nTú juegas con dos barajas\nY yo con una no más.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,85,85,"3779","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t3-n3780",1,"¿De qué te sirve penar\nY dar voces como un loco\nSi yo me muero por tí\nY tú te mueres por otro.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,85,85,"3780","",0,"","","",2,0,0,[],""],["rm_t3-n3781",1,"Tú tienes amor con otro\nY conmigo las chancitas,\nSi te quieres divertir,\nCompra un trompo y una guita.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,85,86,"3781","",0,"","","",1,0,0,[],""],["rm_t3-n3783",1,"Si pasares por la iglesia,\nDile al sacristan que apague\nLa bela qu' está ensendía,\nQu' á mí no me la da nádie.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,86,86,"3783","",0,"","","",2,0,0,[],""],["rm_t3-n3784",1,"Si usté me quiso de gorpe,\nYo lo quise de queíto;\nSi usté tiene su pichona,\nYo tengo mi pichonsito.",1,0,-1,6,"",0,4,"io",119,0,-1,0,86,86,"3784","",0,"","","",1,0,0,[],""],["rm_t3-n3785",1,"Haré un hoyito en la arena\nY vivo me enterraré,\nPor no ver en mano ajena\nPrenda que tanto estimé.",1,0,-1,6,"",1,4,"e",77,0,-1,0,86,86,"3785","",0,"","","",5,0,0,[],""],["rm_t3-n3786",1,"Un rayo caiga der sielo\nY me parta por mitá,\nPrimero que yo te bea\nEn manos de otro galan.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,86,86,"3786","",0,"","","",1,0,0,[],""],["rm_t3-n3787",1,"¿Cómo quieres, mozo jóven,\nQue ponga mi amor en tí,\nSi eres como la veleta,\nHoy aquí, mañana allí?",1,0,-1,6,"",0,4,"i",23,0,-1,0,86,86,"3787","",0,"","","",1,0,0,[],""],["rm_t3-n3788",1,"¡Mal haya la veleta\nQue el aire mueve!\n¡Mal haya quien se fia\nDe las mujeres!",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,86,87,"3788","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3789",1,"¡Mal haya la cocina!\n¡Mal haya el humo!\n¡Mal haya quien se fia\nDe hombre ninguno!",1,0,-1,6,"",6,4,"uo",-1,0,-1,0,87,87,"3789","",0,"","","",2,0,0,[],""],["rm_t3-n3790",1,"¡Mal haya de la beleta\nQu' está en lo arto e la torre:\nBiene un aire, biene otro,\nY á toítos les corresponde!",1,0,-1,6,"",3,4,"oe",-1,0,-1,0,87,87,"3790","",0,"","","",1,0,0,[],""],["rm_t3-n3791",1,"Puse mi amor en un punto\nComo beleta en la torre;\nPor eso lo dificurto\nQue buerban nuestros amores.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,87,87,"3791","",0,"","","",1,0,0,[],""],["rm_t3-n3793",1,"Me dijistes veleta;\nYo no lo he sido;\nLa causa de olvidarte\nTú la has tenido.\nPues de otra suerte,\nTe hubiera yo querido\nHasta la muerte.",1,0,-1,6,"",4,7,"ee",134,0,-1,0,87,87,"3793","",0,"","","",2,0,0,[],""],["rm_t3-n3794",1,"Me dijistes veleta,\nPor lo mudable;\nSi yo soy la veleta,\nTú eres el aire.\nQue la veleta,\nSi el aire no la mueve,\nSiempre está quieta.",1,0,-1,6,"",4,7,"ea",200,0,-1,0,87,88,"3794","",0,"","","",2,0,0,[],""],["rm_t3-n3796",1,"Eres como el gallo inglés,\nQue á todos les haces cara;\nHazte, niña, mesonera,\nY á todos darás posada.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,88,88,"3796","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3797",1,"Eres una y eres dos,\nEres tres y eres cuarenta;\nEres la iglesia mayor,\nDonde todo el mundo entra.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,88,88,"3797","",0,"","","",5,0,0,[],""],["rm_t3-n3799",1,"Yo pensé qu' eras castiyo\nCon arguna fortalesa;\nYa beo qu' eres mujé\nY en tí no cabe firmesa.",1,0,-1,6,"",0,4,"ea",201,0,-1,0,88,88,"3799","",0,"","","",1,0,0,[],""],["rm_t3-n3800",1,"He de formar un castillo\nEncima de un alfiler\nY ha de tener más firmeza\nQue ha tenido tu querer.",1,0,-1,6,"",0,4,"e",20,0,-1,0,88,88,"3800","",0,"","","",1,0,0,[],""],["rm_t3-n3801",1,"Er juramento mi niña\nLo escribió sobre l' arena;\nLo que en la arena s' escribe\nBiene 'l aire y se lo yeba.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,89,89,"3801","",0,"","","",1,0,0,[],""],["rm_t3-n3802",1,"Escribistes en l' arena\nY firmastes en la mar;\nEl aire fué tu correo:\n¡Baya una seguridá!",1,0,-1,6,"",0,4,"a",-1,0,-1,0,89,89,"3802","",0,"","","",1,0,0,[],""],["rm_t3-n3803",1,"Er queré d' esta serrana\nEn una rama quedó;\nBino un remolino grande,\nRama y querer se yebó.",1,0,-1,6,"",0,4,"o",2,0,-1,0,89,89,"3803","",0,"","","",1,0,0,[],""],["rm_t3-n3805",1,"La palabra que me distes\nA la orilla de la fuente,\nComo fué junto del agua,\nSe la llevó la corriente.",1,0,-1,6,"",0,4,"ee",15,0,-1,0,89,89,"3805","",0,"","","",3,0,0,[],""],["rm_t3-n3806",1,"A tu queré lo comparo\nCon la nobedá der tiempo:\nYa se nubla, ya se arrasa,\nYa dilubia, ya hase bueno.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,89,89,"3806","",0,"","","",3,0,0,[],""],["rm_t3-n3807",1,"Como er sielo en berano\nSon tus quereles;\nQue se forma tormenta,\nLuégo no yuebe.\nTus quereles son;\nQue se forma tormenta,\nLuégo sale 'r só.",1,0,-1,6,"",4,7,"o",-1,0,-1,0,89,90,"3807","",0,"","","",1,0,0,[],""],["rm_t3-n3808",1,"Tienes nubes como el cielo,\nMareas como la mar,\nMudanzas como los vientos,\nY luégo te ha de pesar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,90,90,"3808","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t3-n3809",1,"Como las olas der má,\nLo mesmito es tu queré;\nQue unos dias son muy grandes\nY otros dias no se ben.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,90,90,"3809","",0,"","","",1,0,0,[],""],["rm_t3-n3810",1,"Ar barquiyo que 'n ermar\nEstá pegando baibenes,\nTengo yo comparaíta\nLa boluntar que me tienes.",1,0,-1,6,"",0,4,"ee",120,0,-1,0,90,90,"3810","",0,"","","",1,0,0,[],""],["rm_t3-n3811",1,"A tu queré lo comparo\nCon l' alameda de Seuta,\nQue siempre s' está regando\nY ar mejor tiempo se seca.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,90,90,"3811","",0,"","","",3,0,0,[],""],["rm_t3-n3812",1,"A tu queré lo comparo\nCon er correo de Beles,\nQu' en cayendo cuatro gotas\nSe le mojan los papeles.",1,0,-1,6,"",0,4,"ee",97,0,-1,0,90,90,"3812","",0,"","","",3,0,0,[],""],["rm_t3-n3813",1,"A tu querer lo comparo\nCon la torre de Babel,\nQue subió más de cien millas\nY al fin se vino á caer.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,90,90,"3813","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n3814",1,"Tu queré 's como la bela:\nYa s' apaga, ya s' ensiende;\nQue aunque los dén muy corríos,\nNunca tienen las cabales.",1,0,-1,6,"",5,4,"ae",-1,0,-1,0,90,92,"3814","",0,"","","",1,0,0,[],""],["rm_t3-n3822",1,"En el mar hay una piedra\nQue rueda y no tiene asiento;\nAsí son las palabritas\nQue hablan algunos sujetos.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,92,92,"3822","",0,"","","",1,0,0,[],""],["rm_t3-n3823",1,"Bén acá, mala gitana;\nT' has güerto como er dinero,\nQue anda e duana en duana\nJasta que l' echan er seyo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,92,92,"3823","",0,"","","",2,0,0,[],""],["rm_t3-n3824",1,"Como la lejía turbia\nEs, mosuela, tu amistá,\nQue nunca puede salir\nA puerto de claridá.",1,0,-1,6,"",0,4,"a",9,0,-1,0,92,92,"3824","",0,"","","",2,0,0,[],""],["rm_t3-n3825",1,"Como los toriyos brabos\nTienes, gitana, el arranque;\nSólo t' acuerdas e mí\nCuando me tienes elan te.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,92,92,"3825","",0,"","","",1,0,0,[],""],["rm_t3-n3827",1,"Tienes el amor puesto\nCon alfileres,\nY tan pronto me dejas\nComo me quieres.",1,0,-1,6,"",6,4,"ee",55,0,-1,0,92,93,"3827","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3828",1,"El amor de esta serrana\nYo no lo puedo entender;\nQue un dia me quiere mucho\nY otro no me puede ver.",1,0,-1,6,"",0,4,"e",20,0,-1,0,93,93,"3828","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t3-n3829",1,"Er querer d' esta serrana\nNingun gachó lo chanela;\nEs como er berde limon,\nQu' er que lo entiende lo yeba. (?)",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,93,93,"3829","",0,"","","",1,0,0,[],""],["rm_t3-n3831",1,"De la noche á la mañana\nMudastes de pareser;\nPero quiso Dios der sielo\nQue yo me lo imaginé.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,93,93,"3831","",0,"","","",2,0,0,[],""],["rm_t3-n3832",1,"Un amor tenía yo\nQue me decia llorando\nQue nunca me olvidaría....\n¡Y ya me estaba olvidando!",1,0,-1,6,"",0,4,"ao",33,0,-1,0,93,93,"3832","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3834",1,"¡Bien me decian á mí\nQue tu querer era vano\nY desapareceria\nComo nube de verano!",1,0,-1,6,"",0,4,"ao",81,0,-1,0,93,94,"3834","",0,"","","",1,0,0,[],""],["rm_t3-n3835",1,"¡Bien me lo decia á mí\nMi comadre la ventera\nQue tu querer no duraba\nNi una semanita entera!",1,0,-1,6,"",0,4,"ea",44,0,-1,0,94,94,"3835","",0,"","","",1,0,0,[],""],["rm_t3-n3836",1,"¿Para qué me dijistes\n«Toma mi alma,»\nSi bebes en la fuente\nDe la inconstancia?",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,94,94,"3836","",0,"","","",2,0,0,[],""],["rm_t3-n3837",1,"Tienes de sol el rostro,\nCosa es segura;\nPero tienes la cara\nComo la luna.\nY es cosa clara\nQue, siendo el sol muy fijo,\nLa luna es varia.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,94,94,"3837","",0,"","","",2,0,0,[],""],["rm_t3-n3838",1,"Condiciones de luna\nTiene mi amante;\nPara poco creciente,\nMucho menguante.",1,0,-1,6,"",6,4,"ae",47,0,-1,0,94,94,"3838","",0,"","","",1,0,0,[],""],["rm_t3-n3839",1,"A la luna parece,\nNiña, tu afecto,\nQue tiene mil mudanzas\nY mil aspectos.\nSé luna llena\nY deja los menguantes,\nPorque te afean.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,94,94,"3839","",0,"","","",2,0,0,[],""],["rm_t3-n3840",1,"Tu cariño supongo\nQue es á la moda,\nPues quieres como y cuando\nMás te acomoda.\nY me parece\nQue aquel á quien más amas\nMénos merece.",1,0,-1,6,"",4,7,"ee",64,0,-1,0,95,95,"3840","",0,"","","",1,0,0,[],""],["rm_t3-n3841",1,"Lo que ayer te enfadaba\nHoy ya te gusta;\nNo es seguro el cariño\nQue así se muda.\nPues de esa suerte\nSe olvidará mañana\nLo que hoy se quiere.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,95,95,"3841","",0,"","","",1,0,0,[],""],["rm_t3-n3842",1,"Permite que te diga,\nSi no te ofendo,\nQue cuanto más te trato\nMénos te entiendo.\nPues prontamente\nRetrocedes de amante\nA indiferente.",1,0,-1,6,"",4,7,"ee",15,0,-1,0,95,95,"3842","",0,"","","",1,0,0,[],""],["rm_t3-n3843",1,"Puse al cielo una querella\nY respondieron los aires\nQue mi querer no lo ponga\nDonde firmeza no halle.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,95,95,"3843","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3844",1,"Me llamastes aparte\nPara decirme\nQue la mujer es varia\nY el hombre firme.\nY es al contrario:\nQue la mujer es firme\nY el hombre vario.",1,0,-1,6,"",4,7,"ao",25,0,-1,0,95,96,"3844","",0,"","","",1,0,0,[],""],["rm_t3-n3845",1,"Las sombras que me dices\nQue te desvelan\nSerán de tus mudanzas\nLas consecuencias.\nPorque es muy propio\nEn todos los culpados\nFingir enojos.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,96,96,"3845","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3846",1,"En busca de firmezas\nMi amor andaba\nY encontró un desengaño\nQue no buscaba.",1,0,-1,6,"",6,4,"aa",28,0,-1,0,96,96,"3846","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3847",1,"Como sé que te mudas\nA todos aires,\nNo suspiro, mi vida,\nPor no mudarte.\nQue aunque es muy leve,\nEl aire de un suspiro\nMudarte puede.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,96,96,"3847","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n3848",1,"Eres hermosa en extremo,\nPero tienes una falta:\nQue en el campo hay varias flores\nY tú tambien eres varia.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,96,96,"3848","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t3-n3849",1,"Del mundo imágen viva\nTe considero,\nPorque imitas lo vario\nDe sus sucesos.\nSé, pues, constante,\nY ni áun quede en tí sombra\nDe tal imágen.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,96,97,"3849","",0,"","","",1,0,0,[],""],["rm_t3-n3850",1,"Dicen que hay damas firmes;\nNo sé cuál sea:\nLa que á mí me ha tocado\nSe bambolea.",1,0,-1,6,"",6,4,"ea",54,0,-1,0,97,97,"3850","",0,"","","",3,0,0,[],""],["rm_t3-n3851",1,"Eres mujer y fueras\nMateria rara\nSi firmeza en tu pecho\nMi fé encontrara.",1,0,-1,6,"",6,4,"aa",57,0,-1,0,97,97,"3851","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3852",1,"Si usté me quiere escribir,\nYo le diré donde vivo:\nEn la calle de Firmeza,\nDonde usté nunca ha vivido.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,97,97,"3852","",0,"","","",1,0,0,[],""],["rm_t3-n3853",1,"No tengas que comparar\nTu voluntad con lamia;\nQue es sin fin mi voluntad\nY la tuya duró un dia.",1,0,-1,6,"",5,4,"a",-1,0,-1,0,97,97,"3853","",0,"","","",2,0,0,[],""],["rm_t3-n3854",1,"Ayer no me quisistes;\nHoy me pretendes:\nMira tus vanidades\nQué precio tienen.\nPero no importa\nQue sirvas de escarmiento\nPara las otras.",1,0,-1,6,"",4,7,"oa",-1,0,-1,0,97,97,"3854","",0,"","","",1,0,0,[],""],["rm_t3-n3855",1,"Si observas cuidadosa\nLo que en tí pasa,\nHallarás el retrato\nDe la inconstancia.\nPues ahora anhelas\nLo que dentro de poco\nYa te molesta.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,97,98,"3855","",0,"","","",1,0,0,[],""],["rm_t3-n3856",1,"Toma la espada y véte,\nMoreno mio,\nA buscar la firmeza\nQue tú has perdido.\nY si la hallas,\nMétetela en el pecho,\nNo te se vaya.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,98,98,"3856","",0,"","","",1,0,0,[],""],["rm_t3-n3857",1,"En tocando que toquen\nA la aleluya,\nVeremos si es constante\nLa pasion tuya.\nPero recelo\nQue todas son lisonjas\nLas que voy viendo.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,98,98,"3857","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t3-n3858",1,"Es tu baile tan lindo,\nQue me embelesa;\nSi esto hacen las mudanzas,\n¿Qué harán firmezas?\nMas no te admire:\nQue sólo en las mudanzas\nEres tú firme.",1,0,-1,6,"",4,7,"ie",-1,0,-1,0,98,98,"3858","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3859",1,"Nunca me gustas ménos\nQue cuando bailas,\nPorque nunca he gustado\nDe las mudanzas.\nMas tú, inconstante,\nPorque tiene mudanzas\nGustas del baile.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,98,99,"3859","",0,"","","",1,0,0,[],""],["rm_t3-n3860",1,"¿Para qué me preguntas\nQué pito toco,\nSi el pito que tocaba\nLo toca otro?\nEl pito toqué;\nPor no tocar el chico,\nEl pito dejé.",1,0,-1,6,"",4,7,"e",77,0,-1,0,99,99,"3860","",0,"","","",3,0,0,[],""],["rm_t3-n3861",1,"Mi amor está entenguerengue,\nComo el navío en la mar;\nY como está entenguerengue,\nYa se viene, ya se va.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,99,99,"3861","",0,"","","",1,0,0,[],""],["rm_t3-n3862",1,"Ayer me dijiste que hoy,\nY hoy me dices que mañana,\nY mañana me dirás:\n-Ya se me quitó la gana.",1,0,-1,6,"",0,4,"aa",4,0,-1,0,99,99,"3862","",0,"carrizo_salta","","",11,0,0,[],""],["rm_t3-n3863",1,"Que sí, que nó, que sería,\nQue hoy, que mañana, que ayer,\nQue ahora, que luégo, que cuándo....\n¿Quién diablos te ha de en tender?",1,0,-1,6,"",0,4,"e",20,0,-1,0,99,99,"3863","",0,"","","",5,0,0,[],""],["rm_t3-n3864",1,"Si te adoro, me olvidas;\nSi hablo, te enojas;\nSi callo, te entristeces;\nSi me voy, lloras.\n¡Oh, amor supremo,\nTodo tú eres distancias,\nTodo tú extremos!",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,99,99,"3864","",0,"","","",2,0,0,[],""],["rm_t3-n3865",1,"Si te busco, te ausentas;\nSi te hallo, riñes;\nSi te riño, te alegras;\nSi bailo, gimes.\n¡Terribles ansias!\n¿Quién podrá hallar firmezas\nDonde hay mudanzas?",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,100,100,"3865","",0,"","","",2,0,0,[],""],["rm_t3-n3866",1,"Si rio, me desprecias;\nSi lloro, cantas;\nSi canto, no me atiendes;\nSi te hablo, callas.\n¡Dolor funesto!\n¡Cada vez el cariño\nMuda de afectos!",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,100,100,"3866","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3867",1,"Si soy fino, tú ingrata;\nSi amante, esquiva;\nSi rendido, soberbia;\nSi humilde, altiva.\nSi fiel, tú falsa;\nSi soy tierno, tú dura;\nSi firme, varia.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,100,100,"3867","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3868",1,"Sabrás como yo tengo\nPor tus mudanzas\nEnfermas de peligro\nMis esperanzas.\nPorque ya tengo\nDe penas por quererte\nEl pecho lleno.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,100,100,"3868","",0,"","","",1,0,0,[],""],["rm_t3-n3869",1,"Lloro entre los halagos\nDe una esperanza\nY, como es hembra, tengo\nDesconfianza.\nPues en las hembras\nSe encuentran más mudanzas\nQue en las estrellas.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,100,101,"3869","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3870",1,"Todas mis esperanzas\nOlas parecen,\nQue montes aparentan\nY espumas mueren.\nY tu inconstancia\nEs tambien por las olas\nRepresentada.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,101,101,"3870","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n3871",1,"Aborreciste á otro\nPara quererme;\nTambien te será fácil\nAborrecerme.\nQue siempre en esto\nDe aquel refran me valgo:\nQuien hace un cesto....",1,0,-1,6,"",4,7,"eo",83,0,-1,0,101,101,"3871","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3872",1,"Yo bien sé que tú tendrás\nQuien te quiera; más te advierto\nQue quien te quiera tendrás;\nMas nó como yo te quiero.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,101,101,"3872","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3873",1,"Si todo el mundo corrieras,\nFácil te será encontrar\nOtro amante á quien más quieras;\nMas nó que te quiera más.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,101,101,"3873","",0,"","","",3,0,0,[],""],["rm_t3-n3874",1,"Si hallas poco mi querer,\nBusca quien te quiera más:\nQue yo siempre te he querido\nComo á aquélla del altar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,101,102,"3874","",0,"","","",1,0,0,[],""],["rm_t3-n3875",1,"Gitaniya como yo\nNo la tienes d' encontrar,\nAunque gitana se buerba\nToíta la cristiandá.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,102,102,"3875","",0,"","","",1,0,0,[],""],["rm_t3-n3876",1,"A ninguno en este mundo\nHe querío como á tí\nY tú no lo has conosío:\nEse es mi mayor sentí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,102,102,"3876","",0,"","","",1,0,0,[],""],["rm_t3-n3877",1,"Con mucho gusto te miro;\nCon poco gusto me ves;\nMira, pues, si hay diferencia\nDe tu amor á mi querer.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,102,102,"3877","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3878",1,"Mi corazon se derrite\nDe pena y de sentimiento,\nDe ver que tú no me quieres\nLo mismo que yo te quiero.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,102,102,"3878","",0,"","","",3,0,0,[],""],["rm_t3-n3879",1,"Mi corazon es leal\nPara la persona tuya;\nEl tuyo para mí nó,\nQue siempre va con segunda.",1,0,-1,6,"",0,4,"ua",-1,0,-1,0,102,102,"3879","",0,"","","",3,0,0,[],""],["rm_t3-n3880",1,"Si mi amor no te gusta,\nNo busques otro;\nMira que cuesta mucho\nDomar un potro.\nPero te advierto\nQue en estando domado,\nNo tiene precio.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,102,103,"3880","",0,"","","",1,0,0,[],""],["rm_t3-n3881",1,"Junto á aquel ciprés tan alto\nHay una flor chiquitita;\nJunto á mi amor que es tan grande\nEl tuyo apénas le imita.",1,0,-1,6,"",0,4,"ia",50,0,-1,0,103,103,"3881","",0,"","","",1,0,0,[],""],["rm_t3-n3882",1,"Vives desconfiado\nDe mi cariño;\n¡Ojalá fuera el tuyo\nComo es el mio!",1,0,-1,6,"",6,4,"o",-1,0,-1,0,103,103,"3882","",0,"","","",1,0,0,[],""],["rm_t3-n3883",1,"Parece tu cariño\nFlor del almendro;\nNace pronto y fallece\nAl primer viento.\nNo es así el mio,\nPues no le acaba el aire\nDe tus desvíos.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,103,103,"3883","",0,"","","",2,0,0,[],""],["rm_t3-n3884",1,"Una palabra me distes\nQue nunca la cumplirás;\nYo sí cumpliré la mia\nDe no olvidarte jamás.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,103,103,"3884","",0,"","","",1,0,0,[],""],["rm_t3-n3886",1,"Ayer tarde me alargaste\nPor la ventana un limon;\nLo partí y estaba seco:\n¿Está así tu corazon?",1,0,-1,6,"",0,4,"o",-1,0,-1,0,103,103,"3886","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3887",1,"'Stoy echao en orasion,\nPor ber si Dios me rebela\nSi este queré que me tienes\nEs de chansa ó es de béras.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,104,104,"3887","",0,"","","",1,0,0,[],""],["rm_t3-n3888",1,"El arma le diera á Dios\nY er corason á Undebé,\nSólo por saber de sierto\nSi es fingío tu queré.",1,0,-1,6,"",0,4,"e",77,0,-1,0,104,104,"3888","",0,"","","",1,0,0,[],""],["rm_t3-n3889",1,"Si supiera que estabas\nComo nacistes,\nFuera un ángel del cielo\nPara servirte.",1,0,-1,6,"",6,4,"ie",-1,0,-1,0,104,104,"3889","",0,"","","",1,0,0,[],""],["rm_t3-n3890",1,"Te he comparado, niña,\nCon un pimiento,\nQue nádie ve las pipas\nQue tiene dentro.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,104,104,"3890","",0,"","","",2,0,0,[],""],["rm_t3-n3891",1,"Hay en el campo una piedra\nY con ella te comparo,\nNó en lo hermosa, que eres fea,\nSino en lo dura de cascos.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,104,104,"3891","",0,"","","",1,0,0,[],""],["rm_t3-n3892",1,"Cual roble somos ambos\nQue más resiste;\nPero tú por lo dura;\nYo por lo firme.\nY tu dureza\nNo se ablanda ni cede\nA mi firmeza.",1,0,-1,6,"",4,7,"ea",108,0,-1,0,104,104,"3892","",0,"","","",1,0,0,[],""],["rm_t3-n3893",1,"Ya no te acuerdas de mí,\nCorazon de piedra dura,\nSabiendo que yo por tí\nPaso ratos de amargura.",1,0,-1,6,"",1,4,"ua",17,0,-1,0,104,105,"3893","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3894",1,"Una cicion componen\nTu amor y el mio;\nYo con la calentura,\nTú con el frío.",1,0,-1,6,"",6,4,"io",3,0,-1,0,105,105,"3894","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3896",1,"El avefría en el campo\nClaramente dice nieve,\nY eso lo dice por tí,\nSabiendo que á nádie quieres.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,105,105,"3896","",0,"","","",2,0,0,[],""],["rm_t3-n3897",1,"Tres prodigios muy raros\nAdmiran todos:\nTu hermosura es el uno,\nMi amor el otro.\nY es el tercero\nQue tu nieve no pueda\nCalmar mi fuego.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,105,105,"3897","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3898",1,"Al sol no se derrite\nLa blanca nieve:\nYa no derrite el fuego\nCosa tan leve.\nPues no ha deshecho\nTanto fuego en mis ojos\nNieve en tu pecho.",1,0,-1,6,"",4,7,"eo",60,0,-1,0,105,105,"3898","",0,"","","",1,0,0,[],""],["rm_t3-n3899",1,"Tú y yo nos parecemos\nMucho á la nieve:\nTú, en lo blanca y lo fria;\nYo, en deshacerme.",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,106,106,"3899","",0,"palau_cantares, frenk_t2, suspiros_amor","","",4,0,0,[],""],["rm_t3-n3900",1,"El jardin de mis gustos\nSe ha marchitado\nCon la fuerza del hielo\nQue tú has sembrado.",1,0,-1,6,"",6,4,"ao",14,0,-1,0,106,106,"3900","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3901",1,"Dentro de mi pecho tengo\nUna mesa de cristal\nDonde juegan á los naipes\nMi amor y tu falsedad.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,106,106,"3901","",0,"palau_cantares, lafuente_madrid","","",32,0,0,[],""],["rm_t3-n3902",1,"Si quieres que te lo diga,\nTe lo diré en dos razones:\nEres hombre de dos caras\nY de malas condiciones.",1,0,-1,6,"",0,4,"oe",34,0,-1,0,106,106,"3902","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",9,0,0,[],""],["rm_t3-n3903",1,"Falsas son tus palabras,\nFalsas tus obras,\nFalsos tus pensamientos,\nTú falsa toda.\nEsto lo digo\nPorque tengo experiencia\nPara decirlo.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,106,106,"3903","",0,"","","",1,0,0,[],""],["rm_t3-n3904",1,"Tienes cara de buen mozo,\nCuerpo de corregidor;\nPero tienes una falta:\nQue eres falso en el amor.",1,0,-1,6,"",0,4,"o",72,0,-1,0,106,106,"3904","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3905",1,"Mientras más caricias me haces,\nMás en confusion me pones,\nPorque tus caricias son\nVísperas de tus traiciones.",1,0,-1,6,"",0,4,"oe",34,0,-1,0,106,107,"3905","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3906",1,"Aquellas palabritas\nQue me dijiste,\nSi no fueran falaces,\nFueran felices.\nY de este modo,\nNo las creo yo tanto,\nQue no soy tonto.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,107,107,"3906","",0,"","","",2,0,0,[],""],["rm_t3-n3907",1,"Si piensas engañarme\nCon risa falsa,\nYo daré á tu cariño\nLa misma paga.\nY si esto sale,\nEl vale que me diste\nDe nada vale.",1,0,-1,6,"",4,7,"ae",202,0,-1,0,107,107,"3907","",0,"","","",1,0,0,[],""],["rm_t3-n3908",1,"No me digas, aleve,\nQue me idolatras;\nQue vienen mal las obras\nCon las palabras.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,107,107,"3908","",0,"","","",1,0,0,[],""],["rm_t3-n3909",1,"Si quieres que te quiera,\nDame fianza,\nPues de tí no me fio,\nQue eres muy falsa.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,107,107,"3909","",0,"palau_cantares, fernan_caballero","","",17,0,0,[],""],["rm_t3-n3910",1,"Si quieres que te quiera,\nDame primero\nFianzas con que pueda\nPedirte luégo.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,107,107,"3910","",0,"palau_cantares","","",17,0,0,[],""],["rm_t3-n3911",1,"Imposible es que haya.\nPecho ninguno\nTan lleno de traiciones\nComo está el tuyo.",1,0,-1,6,"",6,4,"uo",-1,0,-1,0,108,108,"3911","",0,"","","",1,0,0,[],""],["rm_t3-n3912",1,"Con sus voces ocultas\nMe dice el alma\nQue crea en lo sincero\nDe tus palabras.\nMas sólo creo\nQue deben ser engaños\nDe mi deseo.",1,0,-1,6,"",4,7,"eo",66,0,-1,0,108,108,"3912","",0,"","","",1,0,0,[],""],["rm_t3-n3913",1,"Siempre estás inventando\nDos mil embustes;\nMas fingir que me quieres\nNo se te ocurre.\n¡Buena desgracia,\nNo encontrar quien me quiera,\nSiquiera en chanza!",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,108,108,"3913","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3914",1,"Tengo en el pecho escritas\nTus falsedades;\nTengo de publicarlas,\nAunque te enfades.\nPues no creyera\nQue me hubieras vendido\nDe tal manera.",1,0,-1,6,"",4,7,"ea",44,0,-1,0,108,108,"3914","",0,"","","",3,0,0,[],""],["rm_t3-n3915",1,"Si compras un sombrero,\nCómpralo fino\nY ponle galon falso,\nComo tú has sido.",1,0,-1,6,"",6,4,"io",-1,0,-1,0,108,108,"3915","",0,"","","",1,0,0,[],""],["rm_t3-n3916",1,"Si yo lo hubiera sabido\nLo falso que era tu pecho,\nNo me hubiera yo metido\nEn callejon tan estrecho.",1,0,-1,6,"",1,4,"eo",60,0,-1,0,109,109,"3916","",0,"","","",3,0,0,[],""],["rm_t3-n3917",1,"Si yo lo hubiera sabido\nQue era tu pecho traidor,\nNo me hubiera yo embarcado\nEn tan mala embarcacion.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,109,109,"3917","",0,"","","",3,0,0,[],""],["rm_t3-n3918",1,"Me dijistes «¡agua va!»\nAl tiempo que me la echastes;\nNo me dejastes mirar\nLa falsedad con que obrastes.",1,0,-1,6,"",0,4,"ae",142,0,-1,0,109,109,"3918","",0,"","","",3,0,0,[],""],["rm_t3-n3919",1,"Con tus falsas caricias\nMe has preparado\nUn cáliz de veneno\nPurificado.\nY áun con saberlo,\nPor venir de tus manos\nVoy á beberlo.",1,0,-1,6,"",4,7,"eo",203,0,-1,0,109,109,"3919","",0,"","","",1,0,0,[],""],["rm_t3-n3920",1,"Ya me tienes difunta;\nMándame enterrar\nEn el panteon triste\nDe tu falsedad.\nÉchame tierra;\nNo me dejes, tirano,\nTan descubierta.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,109,109,"3920","",0,"","","",1,0,0,[],""],["rm_t3-n3921",1,"Te quise, en la creencia\nDe que tu pecho\nDe tórtola tenía\nLos sentimientos.\nPero ya miro\nQue era tu amor el llanto\nDel cocodrilo.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,109,110,"3921","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3922",1,"Ya conozco tus tramas\nY tus designios,\nPues bien sabes, ingrata,\nQue por el hilo....\nY no lo extrañes,\nPues eres un ovillo\nDe falsedades.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,110,110,"3922","",0,"","","",2,0,0,[],""],["rm_t3-n3923",1,"Los presos cuentan los dias,\nLos estudiantes los años,\nY yo contaré de tí\nLa falsedad y el engaño.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,110,110,"3923","",0,"","","",5,0,0,[],""],["rm_t3-n3925",1,"Al principio de quererte,\nQuien te conoció me dijo\nQue de tí no me fiara,\nQue eres falsa en el cariño.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,110,110,"3925","",0,"","","",3,0,0,[],""],["rm_t3-n3926",1,"Cuando mi amor lo rendí,\nFiando en que me adorabas,\nAl momento conocí\nLa traicion que tú fraguabas.",1,0,-1,6,"",1,4,"aa",204,0,-1,0,110,110,"3926","",0,"","","",1,0,0,[],""],["rm_t3-n3927",1,"Estándote yo queriendo\nCon la voluntad que sabes,\nCon una llave maestra\nDescubrí tus falsedades.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,111,111,"3927","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3928",1,"Con el corazon dañado\nTe pones á hablar conmigo,\nY yo con mi sencillez\nLo que me pasa te digo.",1,0,-1,6,"",0,4,"io",106,0,-1,0,111,111,"3928","",0,"","","",1,0,0,[],""],["rm_t3-n3929",1,"Porque te ví desde léjos,\nPor éso te quiero tanto;\nHaces bien en alejarte:\nDe cérca pierde lo falso.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,111,111,"3929","",0,"","","",3,0,0,[],""],["rm_t3-n3931",1,"Entre todos sus vasallos\nNo ha conocido el Amor\nMujer más falsa que tú\nNi hombre más firme que yo.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,111,111,"3931","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t3-n3932",1,"Tú pensabas engañarme\nCon palabras melositas;\nPero me parió mi madre\nMás pícara que bonita.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,111,111,"3932","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3933",1,"Tú pensastes engañarme\nComo me bistes muchacha;\nTú eres rata de bayao\nY yo culebra de sarsa.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,111,111,"3933","",0,"","","",1,0,0,[],""],["rm_t3-n3934",1,"Pensastes engañarme,\nPero ¡mamola!\nNo me ha dado mi madre\nLeche tan boba.",1,0,-1,6,"",6,4,"oa",-1,0,-1,0,112,112,"3934","",0,"","","",1,0,0,[],""],["rm_t3-n3935",1,"Pensabas engañarme;\nTú te engañabas;\nQue si tú tienes conchas,\nYo tengo escamas.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,112,112,"3935","",0,"","","",1,0,0,[],""],["rm_t3-n3936",1,"Tres veces me quisiste,\nTres me negaste;\nOtro San Pedro fuiste,\nMas no lloraste.\nLlegará ocasion\nQue quizás cante el gallo\nDe nuestra pasion.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,112,112,"3936","",0,"","","",2,0,0,[],""],["rm_t3-n3938",1,"Las apariencias de Júdas,\nSerrana, me estás haciendo:\nPor delante buena cara,\nPor detrás me estás vendiendo.",1,0,-1,6,"",0,4,"eo",52,0,-1,0,112,112,"3938","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n3939",1,"Ar prinsipio de quererte\nSiempre tenía mis duas;\nPero ya m' he combensío\nQu' eres más farso que Júas.",1,0,-1,6,"",5,4,"ua",-1,0,-1,0,112,112,"3939","",0,"","","",2,0,0,[],""],["rm_t3-n3940",1,"De los hábitos de J údas\nTe he de hacer un delantal,\nPara que lleves delante\nTu insignia de falsedad.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,112,113,"3940","",0,"","","",1,0,0,[],""],["rm_t3-n3941",1,"Vén acá, falsa y refalsa;\nFalsa, te vuelvo á decir;\nEl dia que me vendiste,\n¿Cuánto te dieron por mí?",1,0,-1,6,"",0,4,"i",-1,0,-1,0,113,113,"3941","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n3942",1,"Si mi amante fuera amante\nQue me supiera estimar,\nTengo yo para mi amante\nUn corazon muy lëal.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,113,113,"3942","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3943",1,"Cual nave combatida\nSe halla mi pecho,\nNaufragando en las olas\nDe tus desprecios.\nCon la esperanza\nQue he de llegar al puerto\nDe la bonanza.",1,0,-1,6,"",4,7,"aa",163,0,-1,0,113,113,"3943","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n3944",1,"Aunque fina me amabas,\nHoy tengo duda,\nPorque el tiempo y la ausensia\nTodo lo mudan.\nMas, sin embargo,\nEspero en la palabra\nQue ántes me has dado.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,113,113,"3944","",0,"","","",1,0,0,[],""],["rm_t3-n3945",1,"Esclavo de unos ojos\nFuí largo tiempo;\nPretendia favores;\nCogí desprecios.\nY en mi desgracia,\nNi áun me queda el alivio\nDe la esperanza.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,113,114,"3945","",0,"","","",2,0,0,[],""],["rm_t3-n3946",1,"¿De qué sirve el cariño\nQue yo te tengo,\nSi tú me pagas siempre\nCon mil desprecios?",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,114,114,"3946","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3947",1,"Al balcon del desprecio\nSola me asomo,\nA ver lo bien que pago,\nLo mal que cobro.\nSi bien cobrara,\nAl balcon del desprecio\nNo me asomara.",1,0,-1,6,"",4,7,"aa",57,0,-1,0,114,114,"3947","",0,"","","",1,0,0,[],""],["rm_t3-n3948",1,"Yo te quiero y tú á mí nó;\nYo te amo y me aborreces;\nYo te trato con cariño\nY tú á mí con altiveces.",1,0,-1,6,"",0,4,"ee",196,0,-1,0,114,114,"3948","",0,"","","",1,0,0,[],""],["rm_t3-n3949",1,"Los ojitos de mi cara\nLos tengo de castigar,\nPorque miran con cariño\nA quien mal pago les da.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,114,114,"3949","",0,"","","",13,0,0,[],""],["rm_t3-n3950",1,"Si supieras mi dolor,\nMi sentimiento y mi pena,\nTe mostraras cariñoso,\nAunque más ingrato fueras.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,114,114,"3950","",0,"","","",2,0,0,[],""],["rm_t3-n3951",1,"Si la carne de mi cuerpo\nLa jisieran cuarterones,\nNo lo sintiera yo tanto\nComo siento tus razones.",1,0,-1,6,"",0,4,"oe",34,0,-1,0,114,114,"3951","",0,"","","",1,0,0,[],""],["rm_t3-n3953",1,"En el fuego en que me abraso\nTe quisiera ver arder,\nPara que vieras, ingrata,\nLo que cuesta un buen querer.",1,0,-1,6,"",0,4,"e",20,0,-1,0,115,115,"3953","",0,"","","",4,0,0,[],""],["rm_t3-n3954",1,"Dices que me quieres mucho;\nEs mentira, no lo creo;\nPara tanto cariñito,\nPocos desatinos veo.",1,0,-1,6,"",0,4,"eo",66,0,-1,0,115,115,"3954","",0,"","","",13,0,0,[],""],["rm_t3-n3955",1,"Dices que me quieres mucho\nY es mentira, que me engañas:\nEn un corazon tan chico\nNo pueden caber dos almas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,115,115,"3955","",0,"carrizo_salta, murciano_antiguo","","",13,0,0,[],""],["rm_t3-n3956",1,"Yo no sé lo que tú tienes,\nNi si te han dado consejos;\nQue no encuentro tu querer\nComo estaba de primero.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,115,115,"3956","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3957",1,"Por tí no tengo sosiego;\nPor tí no duermo ni como;\nY, aunque ves que estoy muriendo,\nTe desentiendes de todo.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,115,115,"3957","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3959",1,"Si supieras lo que haces\nCon darme á mí que sentir,\nNo te metieras en éso,\nQue me pones á morir.",1,0,-1,6,"",0,4,"i",157,0,-1,0,116,116,"3959","",0,"","","",1,0,0,[],""],["rm_t3-n3961",1,"Bien sabe el divino cielo\nQue te quiero más que al alma;\nPero tus ingratitudes\nSon las que á mí me relajan.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,116,116,"3961","",0,"","","",1,0,0,[],""],["rm_t3-n3962",1,"Te quiero más que al alma,\nNo lo conoces;\n¿Quieres que te publique\nMi amor á voces?",1,0,-1,6,"",6,4,"oe",205,0,-1,0,116,116,"3962","",0,"","","",1,0,0,[],""],["rm_t3-n3963",1,"Si mis ojos lloraron,\nRazon tuvieron,\nPorque se enamoraron\nDe un forastero.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,116,116,"3963","",0,"","","",2,0,0,[],""],["rm_t3-n3964",1,"No me mires, que me matas\nCon esos ojos tan tristes,\nPorque se me representa\nEl mal pago que me distes.",1,0,-1,6,"",0,4,"ie",91,0,-1,0,116,116,"3964","",0,"","","",3,0,0,[],""],["rm_t3-n3965",1,"Anda y dale esos jachares\nAr que te diere motibo,\nQue hasta er corason me duele\nDejaserlo bien contigo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,116,116,"3965","",0,"","","",1,0,0,[],""],["rm_t3-n3966",1,"Mi corazon está herido\nY no hace más que llorar;\nMientras más gusto te doy,\nMás sentimientos me das.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,117,117,"3966","",0,"","","",1,0,0,[],""],["rm_t3-n3967",1,"Parece un esqueleto\nMi semejanza;\nMe preguntó un ingrato\nCuál es la causa.\nYo le respondí:\n-Malas correspondencias\nMe tienen así.",1,0,-1,6,"",4,7,"i",23,0,-1,0,117,117,"3967","",0,"","","",1,0,0,[],""],["rm_t3-n3968",1,"Cada dia me parece\nQue no puedo sufrir más\nY cada dia me traes\nUn aumento de pesar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,117,117,"3968","",0,"","","",2,0,0,[],""],["rm_t3-n3969",1,"¡A qué precio tan costoso\nDispones de mi amistá!\nPor cada horita de gusto\nMe das ciento de pesar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,117,117,"3969","",0,"","","",4,0,0,[],""],["rm_t3-n3970",1,"Como sabes, ángel bello,\nQue yo me muero por tí,\nTienes el gusto cifrado\nEn darme á mí que sentir.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,117,117,"3970","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3971",1,"Como ves que yo me esmero\nEn adorarte y quererte,\nPor eso, bello lucero,\nMe pagas tan malamente.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,117,117,"3971","",0,"","","",3,0,0,[],""],["rm_t3-n3972",1,"Como sabes que te quiero,\nTe ries de mi cariño\nY me tomas y me dejas,\nComo á juguete de niño.",1,0,-1,6,"",0,4,"io",176,0,-1,0,117,118,"3972","",0,"","","",3,0,0,[],""],["rm_t3-n3973",1,"Por lo mismo que sabes\nCuánto te adoro,\nParece que te empeñas\nEn darme enojos.\nMas no lo extraño,\nPues todas las mujeres\nDan este pago.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,118,118,"3973","",0,"","","",1,0,0,[],""],["rm_t3-n3974",1,"Debajo de un laurel verde\nMe puse á considerar\nLo mucho que te he querido\nY el mal pago que me das.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,118,118,"3974","",0,"","","",1,0,0,[],""],["rm_t3-n3975",1,"Ojitos de terciopelo,\nLabios de clavel morado,\nNo me des más que sentir,\nQue ya bastante me has dado.",1,0,-1,6,"",0,4,"ao",14,0,-1,0,118,118,"3975","",0,"carrizo_salta, huambachano","","",4,0,0,[],""],["rm_t3-n3976",1,"Tienes el gusto cifrado\nEn darme á mí que sentir,\nY yo lo tengo cifrado\nEn no querer más que á tí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,118,118,"3976","",0,"","","",1,0,0,[],""],["rm_t3-n3977",1,"Hermanito, no más penas,\nQue me tienes consumía;\nMira que no doy á nádie\nSiquiera los buenos dias.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,118,118,"3977","",0,"","","",1,0,0,[],""],["rm_t3-n3978",1,"Morenita, no más penas,\nMira que no soy de bronse\nY una piedra se quebranta\nA fuersa de tantos gorpes.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,118,118,"3978","",0,"","","",1,0,0,[],""],["rm_t3-n3979",1,"¿Cómo quieres que te quiera,\nSi siempre m' estás pegando,\nComo si mi cuerpo fuera\nDe piedresiya de mármo?",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,119,119,"3979","",0,"","","",16,0,0,[],""],["rm_t3-n3980",1,"¿Cómo quieres que te quiera,\nSi me estás amenazando\nQue el dia que sea tuya\nLa muerte me está aguardando?",1,0,-1,6,"",0,4,"ao",33,0,-1,0,119,119,"3980","",0,"","","",16,0,0,[],""],["rm_t3-n3981",1,"¿Cómo quieres que le diga\nA tu madre «madre mia»\nY á tus hermanas «cuñadas,»\nSi tú no quieres ser mia?",1,0,-1,6,"",0,4,"a",-1,0,-1,0,119,119,"3981","",0,"","","",3,0,0,[],""],["rm_t3-n3982",1,"¿Cómo quieres que navegue\nUn barco que está en la playa?\n¿Cómo quieres que yo quiera\nUn cuerpo que está sin alma?",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,119,119,"3982","",0,"lafuente_madrid, palau_cantares","","",6,0,0,[],""],["rm_t3-n3983",1,"¿Cómo quieres que navegue,\nSi no veo tu velera?\n¿Quieres que á la mar me arroje\nY desesperado muera?",1,0,-1,6,"",0,4,"ea",44,0,-1,0,119,119,"3983","",0,"","","",6,0,0,[],""],["rm_t3-n3984",1,"¿Cómo quieres que en los aires\nAnden pájaros sin alas?\n¿Cómo quieres que yo viva,\nSi me quitas la esperanza?",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,119,119,"3984","",0,"","","",1,0,0,[],""],["rm_t3-n3985",1,"¿Cómo quieres que te quiera,\nSi tengo el alma dormida?\n¿Cómo quieres que te mire,\nCuando tú ya no me miras?",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,119,119,"3985","",0,"","","",16,0,0,[],""],["rm_t3-n3986",1,"¿Cómo quieres que diga\nMe estás amando,\nSi á cada instante miro\nMi desengaño?\nLo que tú quieres\nEs que yo te entretenga\nY entretenerme.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,120,120,"3986","",0,"","","",1,0,0,[],""],["rm_t3-n3987",1,"¿Cómo quieres que tenga\nFinos colores,\nSi me los van quitando\nTus sinrazones?\nColores finos,\nSi me los van quitando\nTus desatinos?",1,0,-1,6,"",4,7,"io",206,0,-1,0,120,120,"3987","",0,"","","",14,0,0,[],""],["rm_t3-n3988",1,"Te quiero y me aborreces\nCon tal porfía,\nQue ni puedo ser de otra,\nNi tú ser mia.",1,0,-1,6,"",6,4,"a",0,0,-1,0,120,120,"3988","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3989",1,"¿Para qué, ingrata, quieres\nSaber mis males?\nCon saber que te quiero\nTodos los sabes.",1,0,-1,6,"",6,4,"ae",-1,0,-1,0,120,120,"3989","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n3990",1,"Si en adelante no quieres\nHacer más caso de mí,\nLa vida que me has robado\nMe debes restituir.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,120,120,"3990","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3991",1,"Compañerito del arma,\nPor la salú de tu mare,\nLo que pasó entre los dos\nNo se lo cuentes á náide.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,120,120,"3991","",0,"","","",2,0,0,[],""],["rm_t3-n3992",1,"Toítos mis sinco sentíos\nEn tí los bine á poné;\nMe cayó tierra en los ojos,\nPor mí mesmo me segué.",1,0,-1,6,"",0,4,"e",77,0,-1,0,121,121,"3992","",0,"","","",1,0,0,[],""],["rm_t3-n3993",1,"Los ojitos de mi cara\nLos he perdío por tí\nY asín que m' has bisto siego\nT' estás burlando de mí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,121,121,"3993","",0,"","","",13,0,0,[],""],["rm_t3-n3994",1,"Grande facurtá te dí\nEn haberte daíto er mando\nY ahora me beo, compañera,\nCastigaíyo e tu mano.",1,0,-1,6,"",3,4,"ao",-1,0,-1,0,121,121,"3994","",0,"","","",1,0,0,[],""],["rm_t3-n3995",1,"Yo t' estoy queriendo á tí\nSin sabé lo que mejago;\nLo que yegaré á sentí\nQue luégo me dés mar pago.",1,0,-1,6,"",1,4,"ao",207,0,-1,0,121,121,"3995","",0,"","","",4,0,0,[],""],["rm_t3-n3996",1,"Si me pagas con desdenes,\nSeré como el ruiseñor,\nQue me pondré entre las hojas\nA llorar mi perdicion.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,121,121,"3996","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3997",1,"¡Mal haya este pecho tierno\nQue tanto te ha idolatrado!\n¡Mientras más enternecido,\nHa sido más despreciado!",1,0,-1,6,"",0,4,"ao",14,0,-1,0,121,121,"3997","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n3999",1,"De tus ingratitudes\nTengo yo hecho,\nComo la Magdalena,\nLlaga en el pecho.",1,0,-1,6,"",6,4,"eo",60,0,-1,0,122,122,"3999","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n4000",1,"Te vinistes á mi casa,\nDiciendo que me querias\nY solito me dejastes\nComo la una del dia.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,122,122,"4000","",0,"","","",1,0,0,[],""],["rm_t3-n4001",1,"Tan remontado te miro,\nTan tibio y tan deslëal,\nQue aunque el reclamo te llama,\nNo lo quieres escuchar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,122,122,"4001","",0,"","","",1,0,0,[],""],["rm_t3-n4002",1,"Dentro de la sepurtura\nTe quisiera dar la mano;\nPero reconosco en tí\nQue te busco y no te hayo.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,122,122,"4002","",0,"","","",1,0,0,[],""],["rm_t3-n4003",1,"Como la memoria es frágil,\nNo me acuerdo si te quise;\nPero me acuerdo, serrana,\nDel mal pago que me distes.",1,0,-1,6,"",0,4,"ie",-1,0,-1,0,122,122,"4003","",0,"","","",3,0,0,[],""],["rm_t3-n4004",1,"No dupliques los males\nA mis fatigas;\nQue está de más la muerte\nDonde no hay vida.",1,0,-1,6,"",6,4,"ia",-1,0,-1,0,122,122,"4004","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4005",1,"¿Qué te han hecho mis ojos,\nQue no los miras\nCon aquel cariñito\nQue tú solias?",1,0,-1,6,"",6,4,"oa",-1,0,-1,0,122,122,"4005","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4006",1,"Si han de ser tus rigores\nTan duros siempre,\n¡Bien haya quien no sabe\nLo que es quererte!",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,123,123,"4006","",0,"","","",1,0,0,[],""],["rm_t3-n4007",1,"Morena, tú me matas\nCon tus rigores;\nQuieres que paguen justos\nPor pecadores.",1,0,-1,6,"",6,4,"oe",5,0,-1,0,123,123,"4007","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n4008",1,"Si David con la honda\nMató al gigante,\nTú me matas, bien mio,\nCon tu semblante.",1,0,-1,6,"",6,4,"ae",47,0,-1,0,123,123,"4008","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t3-n4009",1,"Está mi amor tan gachon,\nQue lo tengo comparao\nCon los niños de la escuela,\nQue siempre 'stán enojaos.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,123,123,"4009","",0,"","","",3,0,0,[],""],["rm_t3-n4011",1,"¡Ay de mí, que enojada\nTe considero,\nCuando pensé que nunca\nSe airaba el cielo!\nMas ya se sabe\nQue fantásticas nubes\nSu luz distraen.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,123,123,"4011","",0,"","","",2,0,0,[],""],["rm_t3-n4012",1,"La desgracia me sigue,\nSegun voy viendo,\nPues cuando yo te busco,\nTú vas huyendo.",1,0,-1,6,"",6,4,"eo",52,0,-1,0,124,124,"4012","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4013",1,"Parece que jugamos\nAl escondite:\nTe busco y no te encuentro,\nCorazon triste.",1,0,-1,6,"",6,4,"ie",-1,0,-1,0,124,124,"4013","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4015",1,"Si no me querias,\n¿Por qué me yamabas?\n¡P' achicharrarme - mi corasonsiyo\nEn bibitas yamas!",1,0,-1,6,"",3,4,"aa",-1,0,-1,0,124,124,"4015","",0,"","","",2,0,0,[],""],["rm_t3-n4016",1,"Si tú no me querias,\n¿Quién te obligaba,\nQue tan falso cariño\nMe demostrabas?\nPues yo no ando\nComo pobre mendigo\nTu amor buscando.",1,0,-1,6,"",4,7,"ao",33,0,-1,0,124,124,"4016","",0,"","","",1,0,0,[],""],["rm_t3-n4017",1,"Por Dios te pido, mi bien,\nQue no me propongas medio:\nO mátame de una vez,\nO haz por mudar ese genio.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,124,124,"4017","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4018",1,"Si tienes queja de mí,\nMátame si te parece;\nPero no vuelvas la cara\nCuando en la calle te encuentre.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,124,125,"4018","",0,"","","",1,0,0,[],""],["rm_t3-n4019",1,"Si en el trascurso del tiempo\nEn la calle me encontrares,\nPor Dios te pido, hermanita,\nQue te pares y me hables.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,125,125,"4019","",0,"","","",1,0,0,[],""],["rm_t3-n4023",1,"¡Lo que he pasado por tí!\n¡Tu querer cómo me ha puesto,\nQúe con un aguamanil\nMe están dando el alimento!",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,125,125,"4023","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4024",1,"Este queré que te tengo\nTan sin rienda y sin medía,\nTú me lo bas conosiendo;\nQuitarme quieres la bía.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,125,125,"4024","",0,"","","",1,0,0,[],""],["rm_t3-n4025",1,"¡Ay, por Dios, que eso es matarme;\nEso es quitarme la vida;\nEso es echarme á la calle\nComo cosilla perdida!",1,0,-1,6,"",0,4,"ia",37,0,-1,0,125,125,"4025","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4026",1,"Quisiera que me dijeras\nPor qué me echas á la calle,\nDespués de haberte querido\nComo no te quiere nádie.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,126,126,"4026","",0,"","","",3,0,0,[],""],["rm_t3-n4027",1,"No m' eches, que yo me iré;\nDeja que sarga la luna;\nSoy niño y me perderé\nPor esa montaña oscura.",1,0,-1,6,"",0,4,"ua",-1,0,-1,0,126,126,"4027","",0,"","","",1,0,0,[],""],["rm_t3-n4028",1,"La herida penetrante\nDe que fallezco\nEs del puñal agudo\nDe tu desprecio.\nSin tus finezas,\nMoriré á los impulsos\nDe tantas penas.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,126,126,"4028","",0,"","","",1,0,0,[],""],["rm_t3-n4029",1,"Tú no sientes ni consientes\nY no te has de morir nunca;\nYo sí que me he de morir\nY tú has de tener la culpa.",1,0,-1,6,"",0,4,"ua",-1,0,-1,0,126,126,"4029","",0,"","","",1,0,0,[],""],["rm_t3-n4030",1,"Dueño mio, si quieres\nSacrificarme,\nDesenvaina el acero,\nVén á matarme.\nPero detente\nY tén misericordia\nDe esta inocente.",1,0,-1,6,"",4,7,"ee",15,0,-1,0,126,126,"4030","",0,"","","",1,0,0,[],""],["rm_t3-n4031",1,"De los cuatro elementos\nTres me acompañan:\nArdo, suspiro, lloro....\nTierra me falta.\n¡Ay, dueño ingrato!\nLa tierra que me falta\nVas preparando!",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,126,127,"4031","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4032",1,"¡Ay de mí, que te amo!\n¡Ay, que te quiero!\n¡Ay, que tú me aborreces!\n¡Ay, que me muero!\nReniego en vano\nDe quien soy, de quien eres\nY de mi estado.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,127,127,"4032","",0,"","","",3,0,0,[],""],["rm_t3-n4033",1,"Dentro de mi pecho tengo\nUn entierro bien formado;\nMi corazon es el muerto;\nTu querer me lo ha matado.",1,0,-1,6,"",0,4,"ao",14,0,-1,0,127,127,"4033","",0,"lafuente_madrid, fernan_caballero","","",32,0,0,[],""],["rm_t3-n4034",1,"Asómate á las rejas\nDe mi corazon\nY lo verás difunto\nCon fiero dolor.\nDespués de muerto,\nTus desdenes le causan\nDuro tormento.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,127,127,"4034","",0,"","","",1,0,0,[],""],["rm_t3-n4035",1,"Párate, caminante,\nMira esa losa\nDonde tu fiel amante\nMuerto reposa.\nTú le has matado\nCon el puñal agudo\nDel desengaño.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,127,127,"4035","",0,"","","",1,0,0,[],""],["rm_t3-n4037",1,"El corazon tengo herido\nDe una puñalada tuya,\nDe ver que me has olvidado,\nSin tener causa ninguna.",1,0,-1,6,"",0,4,"ua",-1,0,-1,0,128,128,"4037","",0,"palau_cantares","","",6,0,0,[],""],["rm_t3-n4038",1,"El corazon lo tengo\nMartirizado,\nDe ver que sin motivo\nMe has olvidado.",1,0,-1,6,"",6,4,"ao",14,0,-1,0,128,128,"4038","",0,"","","",1,0,0,[],""],["rm_t3-n4039",1,"Dime, ¿por qué motivo\nDe mí te apartas?\nDímelo, dueño mio,\nPorque me matas.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,128,128,"4039","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4041",1,"¿Tienes baló, compañero,\nD' orbidarme á sangre fria,\nCuando se le toma ley\nA un perriyo que se cría?",1,0,-1,6,"",0,4,"ia",0,0,-1,0,128,128,"4041","",0,"","","",1,0,0,[],""],["rm_t3-n4042",1,"Quisiera que me dijeras\nLos motibos que te he dado;\n¡Castigarme d' otra suerte,\nNó con haberme orbidado!",1,0,-1,6,"",0,4,"ao",14,0,-1,0,128,128,"4042","",0,"","","",3,0,0,[],""],["rm_t3-n4044",1,"Te fuistes y me dejastes\nCuando yo más te queria;\n¡No hubieran hecho otro tanto\nLos moros de Berbería!",1,0,-1,6,"",0,4,"ia",0,0,-1,0,129,129,"4044","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4045",1,"¡Ni la sentensia de Cristo\nTubiera tanto rigor!\n¡Como si fuera delito\nQuererte de corason!",1,0,-1,6,"",5,4,"ao",-1,0,-1,0,129,129,"4045","",0,"","","",1,0,0,[],""],["rm_t3-n4046",1,"¿Constante no te adoré\nY fino no te serví?\n¿No hice cuanto fué tu gusto?\nPues ¿por qué me olvidas? dí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,129,129,"4046","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t3-n4047",1,"Corazoncito lëal,\nBien te lo decia yo\nQue te habian de olvidar,\nY tú decias que nó.",1,0,-1,6,"",0,4,"o",2,0,-1,0,129,129,"4047","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4048",1,"Bien te lo decia yo\nQue me habias de olvidar;\nTú me decias que nó;\n¡Mira si salió verdad!",1,0,-1,6,"",0,4,"a",-1,0,-1,0,129,129,"4048","",0,"","","",1,0,0,[],""],["rm_t3-n4050",1,"Si preguntas por quién muero,\nTú eres quien me va matando,\nPues soy tu amor verdadero\nY tú me vas olvidando.",1,0,-1,6,"",1,4,"ao",33,0,-1,0,130,130,"4050","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4051",1,"Por consejos que m' han dao\nNo m' han podío bensé,\nY tú con uno tan sólo\nT' apartas de mi queré.",1,0,-1,6,"",0,4,"e",77,0,-1,0,130,130,"4051","",0,"","","",1,0,0,[],""],["rm_t3-n4053",1,"Si olvidarte fuera fácil,\nBien te olvidaria yo;\nMi corazon gozaria\nLa libertad que perdió.",1,0,-1,6,"",0,4,"o",2,0,-1,0,130,130,"4053","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4054",1,"Dame siquiera un libro\nDe tu bufete,\nPara estudiar los medios\nDe aborrecerte.",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,130,130,"4054","",0,"","","",1,0,0,[],""],["rm_t3-n4055",1,"El alma ya me duele\nDe suplicarte\nQue me des un remedio\nPara olvidarte.",1,0,-1,6,"",6,4,"ae",8,0,-1,0,130,130,"4055","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4056",1,"¿Qué importa que me digas\nPara consuelo\nQue es el medio olvidarte,\nSi olvido el medio,\nY en el instante\nDe tí para tu olvido\nHe de acordarme?",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,131,131,"4056","",0,"","","",1,0,0,[],""],["rm_t3-n4057",1,"Compañeriyo del arma,\nEsta gitaniya perra\nMe trae mortificaíyo,\nQueriendo que no la quiera.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,131,131,"4057","",0,"","","",1,0,0,[],""],["rm_t3-n4058",1,"Anda y señálame un sitio\nDonde yo pueda llorar\nLas penas y las fatigas\nQue tú me haces pasar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,131,131,"4058","",0,"","","",3,0,0,[],""],["rm_t3-n4059",1,"Anda y señálame un sitio\nDonde yo me pueda ir;\nAllí lloraré mis penas,\nAcordándome de tí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,131,131,"4059","",0,"","","",3,0,0,[],""],["rm_t3-n4060",1,"¿Con qué ojitos me mirastes,\nQue tan bien te paresí\nY tan pronto me orbidastes?\n¿Quién t' h' hablao mar de mí?",1,0,-1,6,"",1,4,"i",23,0,-1,0,131,131,"4060","",0,"","","",1,0,0,[],""],["rm_t3-n4061",1,"¡Bárgame la Crus de Marta\nY er Cristo der Gran Podé!\n¡Tanto como me querias,\nY ahora no me puedes bé!",1,0,-1,6,"",3,4,"e",77,0,-1,0,131,131,"4061","",0,"","","",1,0,0,[],""],["rm_t3-n4062",1,"¡Tanto como me querias,\nTanto como me adorabas,\nTanto como yo valia,\nY ahora no valgo nada!",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,131,132,"4062","",0,"","","",1,0,0,[],""],["rm_t3-n4063",1,"Acuérdate, dueño mio,\nDe aquellas conversaciones\nQue teníamos los dos,\nTan unidos y conformes.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,132,132,"4063","",0,"","","",1,0,0,[],""],["rm_t3-n4064",1,"Si por consejos te apartas,\nCariño, de mi cariño,\nRecuerda cuando llorabas\nPor mi querer como un niño.",1,0,-1,6,"",0,4,"io",176,0,-1,0,132,132,"4064","",0,"","","",1,0,0,[],""],["rm_t3-n4066",1,"Acuérdate, mi vida,\nCuando algun tiempo\nMe decias llorando:\n-Por tí me muero.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,132,132,"4066","",0,"","","",2,0,0,[],""],["rm_t3-n4068",1,"Acuérdate, tirano,\nCuando decias\nQue sólo con la muerte\nMe olvidarias.\nYa llegó el tiempo\nDe que tú me olvidaras\nY no te has muerto.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,132,132,"4068","",0,"","","",1,0,0,[],""],["rm_t3-n4069",1,"¿T' acuerdas cuando pusistes\nTu cara sobre la mia\nY yorando me dijistes\nQue nunca m' orbidarias?",1,0,-1,6,"",5,4,"aa",-1,0,-1,0,133,133,"4069","",0,"","","",1,0,0,[],""],["rm_t3-n4070",1,"¿T' acuerdas cuando dijistes\nQue nunca m' orbidarias...?\nCuando m' acuerdo, me rio\nDel afan con que mentias.",1,0,-1,6,"",5,4,"ea",-1,0,-1,0,133,133,"4070","",0,"","","",2,0,0,[],""],["rm_t3-n4072",1,"¿Eres tú la que desias\nQu' en tí no cabe mudansa,\nY te orbidaste de mí\nCuando borbí las espardas?",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,133,133,"4072","",0,"","","",1,0,0,[],""],["rm_t3-n4076",1,"¿T' acuerdas cuando dijistes\nQue me querias más que á Dios?\n¡Qué lástima de palabra,\nQue 'r biento se la yebó!",1,0,-1,6,"",0,4,"o",-1,0,-1,0,134,134,"4076","",0,"","","",2,0,0,[],""],["rm_t3-n4078",1,"-Primero que te olvide,\nBlanca paloma,\nSe ha de volver cristiana\nLa reina mora.\n-Me has olvidado;\nPero la reina mora\nMora ha quedado.",1,0,-1,6,"",4,7,"ao",14,0,-1,0,134,134,"4078","",0,"","","",2,0,0,[],""],["rm_t3-n4079",1,"En la pila der bautismo\nEmpesó nuestro queré;\n¡Quién s' habia e figurá\nLo qu' ha pasao después!",1,0,-1,6,"",0,4,"e",-1,0,-1,0,134,134,"4079","",0,"","","",2,0,0,[],""],["rm_t3-n4081",1,"¡Quién me lo diría á mí\nQue s' había de acabá\nEste queré tuyo y mio,\nTeniendo raíses ya!",1,0,-1,6,"",0,4,"a",9,0,-1,0,135,135,"4081","",0,"","","",1,0,0,[],""],["rm_t3-n4083",1,"Cuando dulces suspiros\nTú me mandabas\nY promesas me hacias\nDe que me amabas,\nDí, ¡quién diria\nQue tantos juramentos\nOlvidarias!",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,135,135,"4083","",0,"","","",1,0,0,[],""],["rm_t3-n4084",1,"¿Para qué me acariciabas\nY me dabas tantas glorias,\nSi me habías de borrar,\nIngrato, de tu memoria?",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,135,135,"4084","",0,"","","",3,0,0,[],""],["rm_t3-n4085",1,"¿Para qué me acariciabas,\nSi me habias de aborrecer?\n¿Para qué le diste entrada\nEn tu pecho á mi querer?",1,0,-1,6,"",0,4,"e",20,0,-1,0,135,135,"4085","",0,"","","",3,0,0,[],""],["rm_t3-n4094",1,"Aunque ahora me desprecias,\nAlgun dia fuí yo bueno;\nCalla tú y callaré yo,\nY así los dos ganaremos.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,137,137,"4094","",0,"","","",3,0,0,[],""],["rm_t3-n4095",1,"En otro tiempo era yo\nEl jardin de tus ideas;\nY ahora que quieres á otra,\nTe voy pareciendo fea.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,137,137,"4095","",0,"","","",1,0,0,[],""],["rm_t3-n4096",1,"Otras veces era yo\nLa alegría de tu cara\nY ahora no me puedes ver,\nPorque he caido en desgracia.",1,0,-1,6,"",3,4,"aa",-1,0,-1,0,137,137,"4096","",0,"","","",3,0,0,[],""],["rm_t3-n4097",1,"Ya yo he caío en desgrasia;\n¿Qué le tenemos d' hasé?\nSantitos que yo pintara,\nDiablos t' han de paresé.",1,0,-1,6,"",0,4,"e",77,0,-1,0,137,137,"4097","",0,"","","",1,0,0,[],""],["rm_t3-n4098",1,"A queya firmesa tanta,\nY aquer ponderar amor,\nY aquer no bibir sin berme,\n¡Qué pronto te s' acabó!",1,0,-1,6,"",0,4,"o",-1,0,-1,0,137,137,"4098","",0,"","","",1,0,0,[],""],["rm_t3-n4099",1,"Mujeres he visto yo,\nPero como tú ninguna;\nQue dejas lo que bien quieres\nPor los bienes de fortuna.",1,0,-1,6,"",0,4,"ua",56,0,-1,0,137,137,"4099","",0,"","","",1,0,0,[],""],["rm_t3-n4100",1,"El amor y el interés\nSalieron al campo un dia\nY más pudo el interés\nQue el amor que me tenias.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,137,137,"4100","",0,"","","",9,0,0,[],""],["rm_t3-n4101",1,"Er mengue por abarisia\nSe condenó y fué al infierno;\nY á tí por abarisiosa\nTe ba ' suseder lo mesmo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,138,138,"4101","",0,"","","",1,0,0,[],""],["rm_t3-n4102",1,"Si por pobre me desprecias,\nDigo que tienes razon:\nHombre pobre y leña verde\nArden cuando hay ocasion.",1,0,-1,6,"",0,4,"ao",31,0,-1,0,138,138,"4102","",0,"machado_venezuela","","",8,0,0,[],""],["rm_t3-n4103",1,"Ya yo te voy á dejar,\nPorque no tengo que darte;\n¡Mira tú, compañerita,\nSi mis fatigas son grandes!",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,138,138,"4103","",0,"","","",1,0,0,[],""],["rm_t3-n4104",1,"Por tu queré, chachipé,\nMe beo d' esta manera,\nArriao y sin parné\nY sin tener quien me quiera.",1,0,-1,6,"",1,4,"ea",44,0,-1,0,138,138,"4104","",0,"","","",1,0,0,[],""],["rm_t3-n4105",1,"Busca una buena moza,\nRica y afable,\nQue yo soy pobrecita\nY despreciable.\nSoy como el oro;\nMientras más me desprecies,\nMás valor tomo.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,138,138,"4105","",0,"","","",1,0,0,[],""],["rm_t3-n4106",1,"Dicen que tú no me quieres,\nPorque no tengo que dar;\nCásate con el reló,\nQue á todas las horas da.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,138,138,"4106","",0,"","","",11,0,0,[],""],["rm_t3-n4107",1,"Porque me bes feo y pobre\nJasta 'l habla m' has negao;\n¡Anda con Dios, compañera,\nQu' er mundo no s' h' acabao!",1,0,-1,6,"",0,4,"ao",98,0,-1,0,139,139,"4107","",0,"","","",1,0,0,[],""],["rm_t3-n4109",1,"Por la interés der dinero\nTe fistes con un gachó;\n¡Y aluégo bienes disiendo\nQue la pasion te segó!",1,0,-1,6,"",0,4,"o",2,0,-1,0,139,139,"4109","",0,"","","",1,0,0,[],""],["rm_t3-n4110",1,"Por interés der dinero\nTe fuistes de la cabesa;\nDijistes qu' eras gitana,\nTe gorbistes montañesa.",1,0,-1,6,"",0,4,"ea",201,0,-1,0,139,139,"4110","",0,"","","",2,0,0,[],""],["rm_t3-n4111",1,"Por interés der dinero\nTe fuistes y me dejastes;\n¡Echate en la fardiquera\nLa ganansia que sacastes!",1,0,-1,6,"",0,4,"ae",142,0,-1,0,139,139,"4111","",0,"","","",2,0,0,[],""],["rm_t3-n4112",1,"Cada cual siente su pena;\nYo siento la mia doble:\nNo me quieren en tu casa,\nPorque dicen que soy pobre.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,139,139,"4112","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4113",1,"Ya se lo he dicho á tu madre\nDe que en boca no me tome;\nLa diferencia que hay\nEs ser tú rico y yo pobre.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,139,139,"4113","",0,"","","",1,0,0,[],""],["rm_t3-n4114",1,"Anda vé y dile á tu madre\nSi no me quiere por pobre,\nQue el mundo da muchas vueltas....\n¡Ayer se cayó una torre!",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,140,140,"4114","",0,"","","",5,0,0,[],""],["rm_t3-n4115",1,"Tu gente no está gustosa\nDe que me quieras á mí;\nNo es ninguna penitencia,\nQue se tenga que cumplir.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,140,140,"4115","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4116",1,"¡Contigo y siempre contigo!\n¡Contigo jasta er morí!\nPero con tu madre nó,\nQue ha jablaíyo mar de mí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,140,140,"4116","",0,"","","",1,0,0,[],""],["rm_t3-n4117",1,"Anda diciendo tu madre\nDe mi honra no sé qué;\n¿Para qué enturbiar el agua,\nSi la tiene que beber?",1,0,-1,6,"",0,4,"e",-1,0,-1,0,140,140,"4117","",0,"","","",23,0,0,[],""],["rm_t3-n4118",1,"Ya mi suegra no me quiere;\nNo lo puedo remediar:\nLos deditos de la mano\nNo se pueden igualar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,140,140,"4118","",0,"","","",1,0,0,[],""],["rm_t3-n4120",1,"Ando rabiando por berte\nY me lo estorba tu madre;\n¿Qué l' importa 'r qu' está jarto.\nQue otro se muera de jambre?",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,140,140,"4120","",0,"","","",1,0,0,[],""],["rm_t3-n4121",1,"Si ya tu madre no quiere\nQue yo contigo platique,\nEso es quitarme la vida\nAntes que Dios me la quite.",1,0,-1,6,"",0,4,"ie",-1,0,-1,0,141,141,"4121","",0,"","","",1,0,0,[],""],["rm_t3-n4122",1,"Toma este puñal dorado\nY dame con él la muerte;\nAsí quedará gustosa\nLa tirana de tu gente.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,141,141,"4122","",0,"","","",6,0,0,[],""],["rm_t3-n4123",1,"Yo no sé por qué motivo\nMi suegra no me querrá,\nSiendo yo tan bien nacida\nComo su hijo será.",1,0,-1,6,"",0,4,"a",9,0,-1,0,141,141,"4123","",0,"","","",5,0,0,[],""],["rm_t3-n4124",1,"Anda disiendo tu madre\nQue me tiene de perdé;\n¡No s' ha de salí con eya,\nPor la leche que mamé!",1,0,-1,6,"",0,4,"e",77,0,-1,0,141,141,"4124","",0,"","","",3,0,0,[],""],["rm_t3-n4125",1,"Anda disiendo tu madre\nQue s' alegra de mis penas;\n¡Ya está metiendo la pata\nY otabía no es mi suegra!",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,141,141,"4125","",0,"","","",3,0,0,[],""],["rm_t3-n4126",1,"Ya te he dicho que á mi madre\nLa tienes que venerar\nComo á la Vírgen del Cármen\nQue está puesta en el altar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,141,141,"4126","",0,"","","",1,0,0,[],""],["rm_t3-n4127",1,"Anda diciendo tu madre\nQue conmigo estás perdiendo;\nY estás ganando conmigo\nUn veinticinco por ciento.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,141,141,"4127","",0,"lafuente_madrid","","",23,0,0,[],""],["rm_t3-n4128",1,"Anda vé y dile á tu madre\nQue no hable mal de mí;\nQue pérdidas y ganancias\nTodas caerán sobre tí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,142,142,"4128","",0,"","","",5,0,0,[],""],["rm_t3-n4131",1,"Doblen las campanas gordas,\nLas de los siete metales; (?)\nQue tú jables mar de mí\nSerraniya, en tí no cabe.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,142,142,"4131","",0,"","","",1,0,0,[],""],["rm_t3-n4132",1,"¿Por qué jablas mar de mí\nY contra er sielo t' enojas?\nQuien malas partías siembra\nJusto es que fatigas coja.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,142,142,"4132","",0,"","","",1,0,0,[],""],["rm_t3-n4135",1,"Tengo un bestío de indiana,\nY otro que m' están cortando,\nY otro que m' están jasiendo\nLas indinas de tus manos.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,142,143,"4135","",0,"","","",1,0,0,[],""],["rm_t3-n4136",1,"Te pones por las esquinas\nA publicar mi querer,\nComo si fuera delito\nEl querer á una mujer.",1,0,-1,6,"",0,4,"e",20,0,-1,0,143,143,"4136","",0,"","","",5,0,0,[],""],["rm_t3-n4139",1,"Te pones por las esquinas\nA desir que m' has dejao;\n¡Bárgame Dios, compañera,\nQué marpaguito m' has dao!",1,0,-1,6,"",0,4,"ao",98,0,-1,0,143,143,"4139","",0,"","","",5,0,0,[],""],["rm_t3-n4140",1,"Yo te estoy queriendo á tí\nCon el más grande silencio\nY tú me vas pregonando\nComo aquel que vende lienzo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,143,143,"4140","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4141",1,"Dicen que la mar es ancha\nY en ella cabe un navío;\n¡Y en el pecho de mi amante\nNo cabe un secreto mio!",1,0,-1,6,"",0,4,"io",3,0,-1,0,143,143,"4141","",0,"","","",1,0,0,[],""],["rm_t3-n4142",1,"Si porque te he querido\nTe alabas necio,\nOtras torres más altas\nCombate el viento.\nNecio te alabas,\nOtras torres más firmes\nCombate el agua.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,143,144,"4142","",0,"","","",1,0,0,[],""],["rm_t3-n4143",1,"Mira por tus alabansias\nEr castigo qu' has tenío;\nEr que másjabla más pierde,\nComo á tí t' ha susedío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,144,144,"4143","",0,"","","",1,0,0,[],""],["rm_t3-n4144",1,"Eres como la perdiz,\nQue por el pico se pierde;\nQue te has dejado decir,\nSalada, que no me quieres.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,144,144,"4144","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4145",1,"Mientras másjables, más pierdes,\nQu' eres como las gayinas,\nQue se ponen á escarbá\nY s' echan la tierra ensima.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,144,144,"4145","",0,"","","",1,0,0,[],""],["rm_t3-n4146",1,"Por esa farta que tienes\nYa tú has caío en desgrasia;\nQue ar que tiene mala lengua\nNo lo quieren ni en su casa.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,144,144,"4146","",0,"","","",1,0,0,[],""],["rm_t3-n4147",1,"Si estás como San Lorenzo,\nPor eso no fundo queja;\nPersona que está quemada,\nDios nos libre de su lengua.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,144,144,"4147","",0,"","","",1,0,0,[],""],["rm_t3-n4148",1,"Ántes era yo buena;\nAhora soy mala;\nHe caido en tu lengua;\nSoy desgraciada.\nTraidor, mal hombre,\nYa que no me has querido,\nNo me deshonres.",1,0,-1,6,"",4,7,"oe",-1,0,-1,0,144,145,"4148","",0,"","","",1,0,0,[],""],["rm_t3-n4149",1,"Por más que me deshonre\nTu lengua infame,\nSoy la espuma del oro\nPara adorarte.\nTengo á mi favor\nQue el oro, aunque se arrastre,\nNo pierde el valor.",1,0,-1,6,"",4,7,"o",72,0,-1,0,145,145,"4149","",0,"","","",2,0,0,[],""],["rm_t3-n4150",1,"Si acaso de mí te dieren\nUna mala informacion,\nTómala como quisieres,\nQue lo mismito haré yo.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,145,145,"4150","",0,"","","",1,0,0,[],""],["rm_t3-n4151",1,"Sentí ruido y me paré\nY me he quedado escuchando\nLas malas informaciones\nQue de mí te estaban dando.",1,0,-1,6,"",0,4,"ao",33,0,-1,0,145,145,"4151","",0,"","","",1,0,0,[],""],["rm_t3-n4152",1,"Si tú sintieras por mí\nUn poquitito de amor,\nNo le tomaras oidos\nA ningun murmurador.",1,0,-1,6,"",0,4,"o",72,0,-1,0,145,145,"4152","",0,"","","",1,0,0,[],""],["rm_t3-n4153",1,"Aunque me digas fea,\nYo no me enojo;\nQue una fea se lleva\nSiempre un buen mozo.",1,0,-1,6,"",6,4,"oo",-1,0,-1,0,145,145,"4153","",0,"","","",2,0,0,[],""],["rm_t3-n4154",1,"Aunque me digas fea,\nYo no me pico,\nPorque todas las feas\nLlevan bonitos.\n¡Ole, salero!\nAquel que no se casa\nQueda soltero.",1,0,-1,6,"",4,7,"eo",38,0,-1,0,146,146,"4154","",0,"","","",2,0,0,[],""],["rm_t3-n4155",1,"Me dijiste que era fea\nY al espejo me miré;\nAlgun salerillo tengo;\nA algun tonto engañaré.",1,0,-1,6,"",0,4,"e",77,0,-1,0,146,146,"4155","",0,"","","",5,0,0,[],""],["rm_t3-n4156",1,"Me dijiste que era fea,\nMe pusiste una corona;\nMás vale fea y con gracia\nQue nó bonita y bobona.",1,0,-1,6,"",0,4,"oa",7,0,-1,0,146,146,"4156","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t3-n4157",1,"Déjame pasar, que voy\nPor agua á la mar serena,\nPara lavarme la cara,\nQue dicen que soy morena.",1,0,-1,6,"",0,4,"ea",59,0,-1,0,146,146,"4157","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4158",1,"No me diga usté morena,\nPorque le diré ladron;\nY el ser ladron es delito\nY el ser morenita nó.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,146,146,"4158","",0,"","","",1,0,0,[],""],["rm_t3-n4159",1,"Dicen que tú no me quieres,\nPorque me ves chiquitito;\nPues, mira, la gen te compra\nPor el aire el abanico.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,146,146,"4159","",0,"","","",11,0,0,[],""],["rm_t3-n4161",1,"Esta noche á la luna\nMe puedes decir\nLos motivos y agravios\nQue tienes de mí.\nDecirme puedes\nLos motivos y agravios\nQue de mí tienes.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,147,147,"4161","",0,"","","",1,0,0,[],""],["rm_t3-n4162",1,"Paseando voy tu calle\nEntre las doce y la una,\nY no me bajas áabrir,\nCorazon de piedra dura.",1,0,-1,6,"",0,4,"ua",-1,0,-1,0,147,147,"4162","",0,"","","",1,0,0,[],""],["rm_t3-n4163",1,"Si no sale usté esta noche\nA la reja á hablar conmigo,\nDesde el dia de mañana\nNo cuente usté ya conmigo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,147,147,"4163","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4164",1,"¿Cómo quieres que te quiera,\nSi no me vienes á ver,\nY tengo yo quien me haga\nVisitas al dia tres?",1,0,-1,6,"",0,4,"e",-1,0,-1,0,147,147,"4164","",0,"lafuente_madrid","","",16,0,0,[],""],["rm_t3-n4165",1,"Anoche estuve en tu puerta;\nTres golpes dí en el candado;\nPara tener amor, niña,\nTienes el sueño pesado.",1,0,-1,6,"",0,4,"ao",14,0,-1,0,147,148,"4165","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4166",1,"Eres la madre del sueño,\nHermosísima María;\nSiempre que te vengo á ver\nHe de encontrarte dormida.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,148,148,"4166","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4167",1,"Una espabilaera\nTengo que darte,\nPara que te espabiles\nEn barias partes.",1,0,-1,6,"",6,4,"ae",-1,0,-1,0,148,148,"4167","",0,"","","",1,0,0,[],""],["rm_t3-n4168",1,"La guitarra sin prima\nSuena quejosa,\nComo estoy yo contigo\nPor cierta cosa.",1,0,-1,6,"",6,4,"oa",63,0,-1,0,148,148,"4168","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n4169",1,"Toda la noche al sereno\nCantando porque te asomes,\nY no he podido lograr\nQue respondas á mis sones.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,148,148,"4169","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n4170",1,"Toda la noche me tienes\nAr sereno y ar rosío,\nY luégo al amaneser\nMe pagas con un sirbío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,148,148,"4170","",0,"","","",7,0,0,[],""],["rm_t3-n4171",1,"Toda la noche me tienes\nEn conversaciones varias\nY luégo al amanecer\nCon un suspiro me engañas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,148,148,"4171","",0,"lafuente_madrid, palau_cantares","","",7,0,0,[],""],["rm_t3-n4172",1,"Toíta la noche\nMe tienes en bela\nComo si fuera - 'r cuerpesito mio\nDe mármo ó de piedra.",1,0,-1,6,"",3,4,"ea",-1,0,-1,0,148,149,"4172","",0,"","","",1,0,0,[],""],["rm_t3-n4173",1,"La ceniza del cigarro\nPuede servir de testigo\nQue anoche estuve en tu puerta\nY no pude hablar contigo.",1,0,-1,6,"",0,4,"io",106,0,-1,0,149,149,"4173","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4174",1,"Resaladita del alma,\nAnoche en tu puerta estuve;\nEstabas á la ventana\nY no me dijiste: «sube.»",1,0,-1,6,"",0,4,"ue",208,0,-1,0,149,149,"4174","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n4175",1,"Me dijistes: «luégo bajo,»\nY te fuistes á dormir;\nTe esperé toda la noche\nY no quisistes venir.",1,0,-1,6,"",0,4,"i",157,0,-1,0,149,149,"4175","",0,"","","",1,0,0,[],""],["rm_t3-n4176",1,"Estoy como San Alejo,\nDebajo de la escalera,\nEsperando la ocasion,\nY la ocasion nunca llega.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,149,149,"4176","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4178",1,"Bien mio, vienes tarde;\nTe vas temprano;\nYo no quiero visitas\nDe cirujano.",1,0,-1,6,"",6,4,"ao",81,0,-1,0,149,149,"4178","",0,"","","",1,0,0,[],""],["rm_t3-n4179",1,"Amor mio, vienes tarde\nY luégo te vas temprano;\n¿De qué me sirven á mí\nVisitas de cirujano?",1,0,-1,6,"",0,4,"ao",81,0,-1,0,149,150,"4179","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n4180",1,"Siempre al tercero dia\nVienes á verme;\nDime si son tercianas\nLo que padeces.\nPues manifiestos\nLos males, ya se curan\nCon más acierto.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,150,150,"4180","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4181",1,"Porque anoche no vine\nTe has ofendido;\nYa no siento yo tanto\nNo haber venido.\nPues satisfecho\nDe que tú lo sentiste,\nMénos lo siento.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,150,150,"4181","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4182",1,"Una vez que vengo á verte\nAl cabo de la semana,\nTe encuentro triste y llorosa\nY me pones mala cara.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,150,150,"4182","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4183",1,"Siempre que vengo á verte\nTe hallo llorando;\nExplícame la causa\nDe llorar tanto.\nPues hago juicio\nDe que llorando imitas\nAl cocodrilo.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,150,150,"4183","",0,"","","",1,0,0,[],""],["rm_t3-n4184",1,"Ahora has dado en quejarte\nDe la cabeza;\nSin duda tus discursos\nTe la calientan.\nQue á las mujeres\nEl meterse en discursos\nNo les conviene.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,150,151,"4184","",0,"","","",1,0,0,[],""],["rm_t3-n4185",1,"Sólo por que te alivies\nPienso ausentarme,\nPues sin duda mi vista\nCausa tus males.\nY esto lo infiero\nDe que á quejarte empiezas\nAsí que llego.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,151,151,"4185","",0,"","","",1,0,0,[],""],["rm_t3-n4186",1,"Si estás en la puerta, cierras;\nSi en la ventana, te escondes;\nDime que te he hecho yo,\nQue tan mal me correspondes.",1,0,-1,6,"",0,4,"oe",209,0,-1,0,151,151,"4186","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n4187",1,"Siempre me echabas achaques\nPara no salirme á hablar;\nLo que es tiempo te sobraba;\nTe faltaba voluntad.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,151,151,"4187","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4189",1,"Cuando te llamo, no vienes;\nCuando vienes, no hay lugar,\nAsí se nos pasa el tiempo\nY así se nos pasará.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,151,151,"4189","",0,"","","",3,0,0,[],""],["rm_t3-n4190",1,"Serrana, si fueras buena\nY tu vieras buena sangre,\nCogieras la mantellina\nY saldrias á buscarme.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,151,152,"4190","",0,"","","",1,0,0,[],""],["rm_t3-n4193",1,"Ya me voy enfadando\nDe tus quereres;\nQue hay pocas ocasiones\nY esas las pierdes.",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,152,152,"4193","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4194",1,"Tú buscaras las horas,\nSi me quisieras,\nEn que yo te explicara\nTodas mis quejas.\nBien sé que puedes;\nPor eso tus excusas\nServir no pueden.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,152,152,"4194","",0,"","","",1,0,0,[],""],["rm_t3-n4195",1,"No digas que no puedes\nHacer favores,\nQue la que quiere y ama\nBusca ocasiones.\nNo pongas duda\nEn que el que quiere y ama\nLa ocasion busca.",1,0,-1,6,"",4,7,"ua",-1,0,-1,0,152,152,"4195","",0,"","","",1,0,0,[],""],["rm_t3-n4196",1,"El amor todo lo puede,\nDice un refran, y es así;\nTú me dices que no puedes,\nLuégo no hay amor en tí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,152,153,"4196","",0,"lafuente_madrid, preciso_coleccion, palau_cantares","","",4,0,0,[],""],["rm_t3-n4197",1,"Llamas amor al tuyo,\nPorque no sabes\nQue el amor nunca tiene\nDificultades.\nY tú pretendes\nTener un amor lleno\nDe inconvenientes.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,153,153,"4197","",0,"","","",1,0,0,[],""],["rm_t3-n4198",1,"Si tú á mí me quisieras\nComo me dices,\nSe juntaran las ramas\nCon las raíces.\nComo lo notas,\nSe juntaran las ramas\nUnas con otras.",1,0,-1,6,"",4,7,"oa",-1,0,-1,0,153,153,"4198","",0,"","","",1,0,0,[],""],["rm_t3-n4199",1,"Se parece á los olmos\nEl amor tuyo,\nQue todo es hojarasca,\nPero sin fruto.\nY yo no quiero\nArbol que no da fruto\nPara mi huerto.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,153,153,"4199","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4200",1,"Tu amor es como el cedro,\nÁrbol sin fruto,\nQue con olor al dueño\nPaga el tributo.\nY de esta suerte,\nPagas tú á quien te ama\nTiranamente.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,153,153,"4200","",0,"","","",1,0,0,[],""],["rm_t3-n4201",1,"No te afanes, compañera,\nPor sacar fruto de mí;\nQue el árbol que no se riega\nSe le seca la raíz.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,154,154,"4201","",0,"","","",2,0,0,[],""],["rm_t3-n4202",1,"Se va secando el árbol\nDe mis delicias,\nPorque le falta el riego\nDe tus caricias.\nSe va secando\nCon el continuo riego\nDel desengaño.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,154,154,"4202","",0,"","","",1,0,0,[],""],["rm_t3-n4203",1,"¿Cómo quieres que un triste\nLlame á tu puerta,\nSi eres de la hermosura\nRica avarienta?",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,154,154,"4203","",0,"","","",1,0,0,[],""],["rm_t3-n4204",1,"Me han dicho que me quieres,\nDueño del alma;\nDímelo con las obras,\nNó con palabras.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,154,154,"4204","",0,"","","",1,0,0,[],""],["rm_t3-n4205",1,"A mí no me gustan plantas;\nMozo bueno, escuche usté;\nLo que me gusta son obras\nY esas no las tiene usté.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,154,154,"4205","",0,"","","",4,0,0,[],""],["rm_t3-n4206",1,"Deja de dar consejos,\nPorque me enfada\nQue tus obras desdigan\nDe tus palabras.\nSé consecuente;\nMira que estás hablando\nCon quien te entiende.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,154,154,"4206","",0,"","","",1,0,0,[],""],["rm_t3-n4207",1,"Si pagar no pudieras,\nTe perdonara;\nMas poder y no hacerlo\nEs ser tirana.\nQue es temeridad\nQuien para pagar tiene\nNo querer pagar.",1,0,-1,6,"",4,7,"a",-1,0,-1,0,155,155,"4207","",0,"","","",1,0,0,[],""],["rm_t3-n4208",1,"Dile, niña, á tus labios\nQue no me hablen,\nPorque si les contesto\nQuieren pegarme.\nY es fuerte cosa\nQue ha de callar un hombre\nSi le provocan.",1,0,-1,6,"",4,7,"oa",-1,0,-1,0,155,155,"4208","",0,"","","",1,0,0,[],""],["rm_t3-n4209",1,"Dime ya si me quieres\nO si me engañas,\nPorque no me alimento\nCon esperanzas.\nMaduran tarde\nY entretanto, yo puedo\nMorirme de hambre.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,155,155,"4209","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4210",1,"Si con hambre castigas\nA quien te ama,\nAdvierte que el desmayo\nQuita la gana.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,155,155,"4210","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n4219",1,"Las penas que yo te daba\nPara mí fueran alivio;\nTe muestras como el acero\nY eres más blando que el vidrio.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,157,157,"4219","",0,"","","",1,0,0,[],""],["rm_t3-n4220",1,"Por ser tú tan mirado\nQuieren casarme.\n¡Fuego de Dios en hombre\nQue es tan cobarde!",1,0,-1,6,"",6,4,"ae",-1,0,-1,0,157,157,"4220","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4221",1,"¡Mal haya el gitanillo\nQue culpa tiene\nDe no ser yo la reina\nDe las mujeres!",1,0,-1,6,"",6,4,"ee",-1,0,-1,0,157,157,"4221","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4222",1,"¿Para qué me has querido\nPara tan poco?\nPerdona que te diga\nQue eres muy tonto.",1,0,-1,6,"",6,4,"oo",-1,0,-1,0,157,157,"4222","",0,"","","",1,0,0,[],""],["rm_t3-n4223",1,"Si temor te parece\nLo que es respeto,\nDame á entender que gustas\nDe atrevimiento.\nPues en tal lance,\nNi bien soy atrevido,\nNi bien cobarde.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,157,157,"4223","",0,"","","",1,0,0,[],""],["rm_t3-n4224",1,"No me trates de burlas,\nSino de véras,\nPues aquéllas me enojan\nY éstas me alegran.\nQue las mujeres,\nSi tratan de casarse,\nLas véras quieren.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,157,158,"4224","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4225",1,"Cuidado con que quiebres\nTu querer fino;\nQue no se diga al cabo:\n-¡Mujer ha sido!",1,0,-1,6,"",6,4,"io",-1,0,-1,0,158,158,"4225","",0,"","","",1,0,0,[],""],["rm_t3-n4226",1,"Que no pagas mi afecto\nDe tí se infiere;\nSólo que lo agradezcas\nMi pecho quiere.\nSi lo pagaras,\nYo fuera poderoso;\nTú mendigaras.",1,0,-1,6,"",4,7,"aa",143,0,-1,0,158,158,"4226","",0,"","","",1,0,0,[],""],["rm_t3-n4227",1,"La cinta que me diste\nPor esperanza,\nTan corta fué, mi dueño,\nQue no me alcanza.",1,0,-1,6,"",6,4,"aa",163,0,-1,0,158,158,"4227","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4228",1,"Cual te quise te quiero;\nPero ya vivo\nSin esperar ser nunca\nCorrespondido.\nSi no te agradé,\n¿Cómo ha de ser ahora\nLo que ántes no fué?",1,0,-1,6,"",4,7,"e",77,0,-1,0,158,158,"4228","",0,"","","",1,0,0,[],""],["rm_t3-n4229",1,"En la escuela de amores\nSoy principiante;\nDame lecciones, niña,\nPara no amarte.\nPues te aseguro\nQue, como salga de ésta,\nSeré buen tuno.",1,0,-1,6,"",4,7,"uo",-1,0,-1,0,158,159,"4229","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4230",1,"Si me quieres, dímelo,\nY si nó, desengañarme;\nQue como se muda el tiempo\nSe mudan las voluntades.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,159,159,"4230","",0,"","","",17,0,0,[],""],["rm_t3-n4231",1,"Si me quieres de balde,\nToda soy tuya;\nPero por el dinero,\nCosa ninguna.",1,0,-1,6,"",6,4,"ua",-1,0,-1,0,159,159,"4231","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4232",1,"De tus ojos á los mios\nFormó el amor un sendero;\nA los tuyos va el amor;\nA los mios, el desprecio.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,159,159,"4232","",0,"","","",1,0,0,[],""],["rm_t3-n4233",1,"Con dos letras te quiero;\nCon dos te hablo;\nCon dos te dificulto;\nCon dos te agravio.\nJunta las ocho,\nVerás un argumento\nDificultoso.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,159,159,"4233","",0,"","","",2,0,0,[],""],["rm_t3-n4234",1,"Nuestro trato y cariño\nNádie lo entiende;\nTú eres galan fantasma,\nYo, dama duende.\nY estos amores\nSerán dentro de poco\nSecreto á voces.",1,0,-1,6,"",4,7,"oe",-1,0,-1,0,159,160,"4234","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4235",1,"¿Quieres qué m' esté cayâ\nY á mi lengua l' eche un nuo?\nSon tus cosiyas capases\nDe jaserle hablará un muo.",1,0,-1,6,"",0,4,"o",2,0,-1,0,160,160,"4235","",0,"","","",1,0,0,[],""],["rm_t3-n4236",1,"Mi querer y tu querer\nSon dos quereres en uno\nY siempre estamos riñendo,\nPor si es mio ó por si es tuyo.",1,0,-1,6,"",0,4,"uo",-1,0,-1,0,160,160,"4236","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4237",1,"Amor, mira que por tí\nPaso muchos disgustiyos;\nMira que estoy arrestado\nA tomar un tabardiyo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,160,160,"4237","",0,"","","",1,0,0,[],""],["rm_t3-n4240",1,"Judit en hermosura\nMe has parecido;\nYo no soy Holofernes;\nTenlo entendido.\nMira no hagas\nLo que con Holofernes\nHizo su amada.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,160,160,"4240","",0,"","","",1,0,0,[],""],["rm_t3-n4241",1,"Si con ingratitudes\nHieres mi pecho,\nTú á tí misma te ofendes,\nPorque estás dentro.\nPero no extraño\nQue por buscar mi muerte,\nBusques tu daño.",1,0,-1,6,"",4,7,"ao",40,0,-1,0,161,161,"4241","",0,"","","",1,0,0,[],""],["rm_t3-n4243",1,"Ya está el carro cargado\nDe tus desprecios;\nMira no falte el eje\nDel sufrimiento.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,161,161,"4243","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4244",1,"Una mesa de trucos\nSon tus amores;\nTodas son idas altas\nTus pretensiones.\nY tus finezas\nPara mí siempre fueron\nBolas cubiertas.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,161,161,"4244","",0,"","","",1,0,0,[],""],["rm_t3-n4245",1,"Es doctrina fingida\nDe aquí adelante\nQue una cosa produce\nSu semejante.\nPues mi cariño\nEn tu pecho produce\nSólo desvío.",1,0,-1,6,"",4,7,"io",-1,0,-1,0,161,162,"4245","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4246",1,"Jasta er corason me duele\nDe rogarte por la pas,\nY luégo me pides tregua,\nDespués de la guerra armâ.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,162,162,"4246","",0,"","","",1,0,0,[],""],["rm_t3-n4247",1,"Como estoy ciego por tí,\nMe estás poniendo con maña\nTus encantos por delante,\nPara que tropiece y caiga.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,162,162,"4247","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n4248",1,"Con furia imaginaria\nTú me quisiste\nY con la misma furia\nMe aborreciste.\nY así, te advierto\nQue, si vienes con furia,\nNo te consiento.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,162,162,"4248","",0,"","","",1,0,0,[],""],["rm_t3-n4249",1,"Tu querer es como el toro\nCuando se encuentra en la plaza;\nQue, como se ve heridito,\nQuiere tomar la venganza.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,162,162,"4249","",0,"","","",3,0,0,[],""],["rm_t3-n4250",1,"Eres como el olivo\nDe poca rama;\nQue en lugar de ampararme,\nMe desamparas.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,162,162,"4250","",0,"","","",1,0,0,[],""],["rm_t3-n4251",1,"Eres Ana y eres vana;\nEres cardo, eres jazmin;\nEres buena y eres mala;\nEres diablo y serafin.",1,0,-1,6,"",0,4,"ai",211,0,-1,0,162,162,"4251","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4252",1,"Deja las expresiones;\nMuda el concepto;\nNo des satisfacciones\nAntes de tiempo.\nMira y repara:\nSatisfaccion sin tiempo\nSospecha causa.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,163,163,"4252","",0,"","","",2,0,0,[],""],["rm_t3-n4253",1,"Estrella de fuego fuiste\nQue en mi corazon entraste;\nDejaste el fuego prendido\nY luégo te retiraste.",1,0,-1,6,"",0,4,"ae",212,0,-1,0,163,163,"4253","",0,"","","",1,0,0,[],""],["rm_t3-n4254",1,"El fuego de mi pecho\nTú lo encendiste;\nYo me quedé en las llamas\nY tú te fuiste.\n¡Mal haya el fuego\nDonde tú no te abrasas\nY yo me quemo!",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,163,163,"4254","",0,"","","",1,0,0,[],""],["rm_t3-n4255",1,"Espejo de cristar fino,\nQue de fino te quebrastes:\nEn la mejor ocasion\nTe fuistes y me dejastes.",1,0,-1,6,"",0,4,"ae",142,0,-1,0,163,163,"4255","",0,"","","",1,0,0,[],""],["rm_t3-n4256",1,"Si has pensado pagarme\nLo que me debes,\nAjusta bien la cuenta,\nQue errarla puedes.\nQue hay muchos datos\nQue hasta de tu memoria\nYa se borraron.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,163,163,"4256","",0,"","","",1,0,0,[],""],["rm_t3-n4257",1,"Te has hecho, vida mia,\nTan miserable,\nQue niegas que te quiero,\nPor no pagarme.\nPero esta deuda\nTe perdono gustoso,\nComo me quieras.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,164,164,"4257","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n4258",1,"En cuenta de mis ansias\nY mis extremos,\nPondrás muchas partidas\nQue estás debiendo.\nEn ellas entra\nAquel atraso grande\nQue erró mi cuenta.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,164,164,"4258","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t3-n4259",1,"Me citas y me debes,\nChusca del alma;\n¿Cuántas veces, morena,\nQuieres la paga?\nCuentas iguales\nY verás, prenda mía,\nQué bien que sales.",1,0,-1,6,"",4,7,"ae",26,0,-1,0,164,164,"4259","",0,"","","",2,0,0,[],""],["rm_t3-n4260",1,"Finezas y caricias\nTe doy á censo;\nLos réditos que cobro\nSon tus desprecios.\nEs injusticia;\nÓ paga las pensiones,\nÓ el censo quita.",1,0,-1,6,"",4,7,"ia",-1,0,-1,0,164,164,"4260","",0,"","","",1,0,0,[],""],["rm_t3-n4261",1,"Deja los disimulos;\nPues ya me enfada\nEl ver que lo que quieres\nSiempre disfrazas.\nHáblame claro\nY veremos si tienes\nGato encerrado.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,164,165,"4261","",0,"","","",1,0,0,[],""],["rm_t3-n4262",1,"Si el hablar te costara\nTanto trabajo\nComo el ser generosa,\nNo hablaras tanto.\nPero tú tratas\nDe ser muy dadivosa\nSólo en palabras.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,165,165,"4262","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4263",1,"Te has vuelto en poco tiempo\nTan embustera,\nQue aunque la verdad busques,\nYa no la encuentras.\nQue es delicada\nY á quien no la respeta,\nVuelve la cara.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,165,165,"4263","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4264",1,"De tu cintura salen\nCuatro mosquetas;\nDe tu boca no sale\nPalabra cierta.",1,0,-1,6,"",6,4,"ea",-1,0,-1,0,165,165,"4264","",0,"","","",1,0,0,[],""],["rm_t3-n4265",1,"Eres una alabanciosa,\nQue cuando vas á comprar,\nTodo te cuesta más caro\nY dices que te lo dan.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,165,165,"4265","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4266",1,"Si quieres que yo te diga\nLa pura de la verdad,\nMucho tienes de bonita;\nPero más de vanidad.",1,0,-1,6,"",0,4,"a",16,0,-1,0,165,166,"4266","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n4267",1,"Confieso que eres linda;\nMas, por lo mismo,\nPorque el pero no falte,\nNo tienes juicio.\nY así, te advierto\nQue si eres más juiciosa,\nNo tendrás pero.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,166,166,"4267","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4268",1,"Eres buena moza y tienes\nUna falta y te la digo:\nQue en la cámara más alta\nGuardas paja y nunca trigo.",1,0,-1,6,"",0,4,"io",106,0,-1,0,166,166,"4268","",0,"","","",2,0,0,[],""],["rm_t3-n4269",1,"Er tambor es tu retrato;\nQue mete mucho ruío\nY si se mira por dentro,\nS' encuentra qu' está basío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,166,166,"4269","",0,"","","",1,0,0,[],""],["rm_t3-n4270",1,"¿De qué te sirve que traigas\nEl sombrero á lo gachon\nY el cuchillo á la cintura,\nSi no tienes corazon?",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,166,166,"4270","",0,"","","",1,0,0,[],""],["rm_t3-n4271",1,"No me bengas con pinturas,\nQue yo pinturas no quiero;\nQue unnobio que yo tenía\nLo dejé por pinturero.",1,0,-1,6,"",0,4,"eo",38,0,-1,0,166,166,"4271","",0,"","","",1,0,0,[],""],["rm_t3-n4272",1,"Yo pensé que tú eras hombre\nY tenías entendimiento\nY veo que eres muchacho\nY como muchacho has hecho.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,166,166,"4272","",0,"","","",1,0,0,[],""],["rm_t3-n4273",1,"Tienes entendimiento;\nTienes memoria;\nPero la otra potencia\nSe fué á la gloria.",1,0,-1,6,"",6,4,"oa",126,0,-1,0,167,167,"4273","",0,"","","",1,0,0,[],""],["rm_t3-n4274",1,"Tienes una carita\nDe San Antonio\nY una condicioncita\nComo un demonio.",1,0,-1,6,"",6,4,"oo",169,0,-1,0,167,167,"4274","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n4275",1,"Anda bé y dile ar maestro\nQu' á tí t' enseñó á querer\nQue te debuerba er dinero,\nPorque no t' enseñó bien.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,167,167,"4275","",0,"","","",1,0,0,[],""],["rm_t3-n4276",1,"Muchachito criatura,\nQuisistes tener amores;\nTe quisistes comparar\nCon la razon de los hombres.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,167,167,"4276","",0,"","","",1,0,0,[],""],["rm_t3-n4277",1,"Mientras yo viva en el mundo\nTendré de tí sentimiento:\nTe estás burlando de mí,\nPorque te falta el talento.",1,0,-1,6,"",0,4,"eo",94,0,-1,0,167,167,"4277","",0,"","","",1,0,0,[],""],["rm_t3-n4282",1,"Esta gitana está loca,\nLoca, que la ban á atar;\nQue lo que sueña de noche\nQuiere que sea berdá.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,168,168,"4282","",0,"","","",3,0,0,[],""],["rm_t3-n4283",1,"Tú me dices que estoy loco;\nYo te confieso que sí;\nQue si loco no estuviera,\n¿Cómo te quisiera á tí?",1,0,-1,6,"",0,4,"i",23,0,-1,0,168,168,"4283","",0,"","","",1,0,0,[],""],["rm_t3-n4287",1,"Que te engaño imaginas;\nDisculpo tu error;\nPues bien en tí se prueba\nQue piensa el ladron....\nY si te engaño,\nDe quien con lobos anda....\nSigo el adagio.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,168,169,"4287","",0,"","","",1,0,0,[],""],["rm_t3-n4288",1,"Eres como el canario,\nQue va y se baña\nY luégo se sacude\nCon arte y maña.",1,0,-1,6,"",0,4,"aa",213,0,-1,0,169,169,"4288","",0,"","","",1,0,0,[],""],["rm_t3-n4289",1,"Pareces una paloma\nCuando por la calle vas;\nCon el meneo que llevas,\n¡A cuántos engañarás!",1,0,-1,6,"",0,4,"a",51,0,-1,0,169,169,"4289","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4290",1,"Si con tus bastos modos\nMe haces jugadas,\nTú me juegas con copas;\nYo, con espadas.\nPorque mis oros\nNo le doy al que juega\nCon bastos modos.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,169,169,"4290","",0,"","","",1,0,0,[],""],["rm_t3-n4291",1,"No me seas retrechera;\nQue te habré de comparar\nCon el reló de Pamplona,\nQue apunta, pero no da.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,169,169,"4291","",0,"","","",4,0,0,[],""],["rm_t3-n4292",1,"Como cangilon de noria\nSon tus partidas, serrana;\nQue unos suben agua buena\nY otros suben agua mala.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,169,169,"4292","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4293",1,"Del jardin salen las rosas;\nDe la marina, los peces;\nDe mi corazon, traiciones\nPara tí que las mereces.",1,0,-1,6,"",0,4,"ee",196,0,-1,0,169,170,"4293","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4294",1,"Yo no te solicité;\nRecuerda que me buscastes;\nTe marchastes por tu gusto\nY volvistes sin llamarte.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,170,170,"4294","",0,"","","",3,0,0,[],""],["rm_t3-n4295",1,"De lo que m' está pasando\nYo mesmo tengo la curpa,\nPor queré á quien no me quiere\nY buscá ' quien no me busca.",1,0,-1,6,"",0,4,"ua",-1,0,-1,0,170,170,"4295","",0,"","","",1,0,0,[],""],["rm_t3-n4296",1,"Corazon mio chiquito,\nNo seas tan lisonjero;\nSi t' han daíto mar pago,\nTú lo has daíto primero.",1,0,-1,6,"",0,4,"eo",38,0,-1,0,170,170,"4296","",0,"","","",1,0,0,[],""],["rm_t3-n4298",1,"Aunque me bes niña y sola,\nGüérfana de padre y madre,\nNo me tires ar codiyo,\nQue Dios no esampara á náide.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,170,170,"4298","",0,"","","",1,0,0,[],""],["rm_t3-n4299",1,"Aunque me bes chiquitita\nY tú tan arto te bes,\nNo pienses que soy escoba,\nQue conmigo has de barrer.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,170,170,"4299","",0,"","","",1,0,0,[],""],["rm_t3-n4300",1,"Mira que no soy de aqueyas\nQue ban por los olibares,\nTu persona no se enmienda,\nSi no se viene conmigo.",1,0,-1,6,"",5,4,"io",-1,0,-1,0,170,172,"4300","",0,"","","",1,0,0,[],""],["rm_t3-n4308",1,"No sé cómo tienes gusto\nPara lavarte la cara\nY peinarte los cabellos,\nSabiendo lo que me pasa.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,172,172,"4308","",0,"","","",1,0,0,[],""],["rm_t3-n4309",1,"Con libertar me querias\nY ahora preso m' aborreses;\n¡Desgrasiao aquer que bibe\nA boluntar de los jueses!",1,0,-1,6,"",3,4,"ee",151,0,-1,0,172,172,"4309","",0,"","","",1,0,0,[],""],["rm_t3-n4310",1,"En la cama y en la cárcel\nLos amigos se han de ver;\nEn diversion no me busques,\nQue no quiero tu querer.",1,0,-1,6,"",0,4,"e",20,0,-1,0,172,172,"4310","",0,"","","",1,0,0,[],""],["rm_t3-n4311",1,"Si piensas que porque cayo\nLo jago de bobería,\nAquer que caya y otorga\nObra con más picardía.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,172,172,"4311","",0,"","","",1,0,0,[],""],["rm_t3-n4312",1,"Véte á la iglesia y confiesa\nY toma la comunion;\nLleva la cruz con paciencia,\nQue tambien la llevo yo.",1,0,-1,6,"",5,4,"o",-1,0,-1,0,172,172,"4312","",0,"","","",1,0,0,[],""],["rm_t3-n4314",1,"No me bengas con belenes,\nQue yo belenes no quiero;\nQue me pones la cabesa\nComo mano de mortero.",1,0,-1,6,"",0,4,"eo",38,0,-1,0,172,173,"4314","",0,"","","",2,0,0,[],""],["rm_t3-n4316",1,"¿Para qué me dijiste\n«Blanca azucena,»\nSi la azucena es blanca,\nYo soy morena?",1,0,-1,6,"",6,4,"ea",59,0,-1,0,173,173,"4316","",0,"","","",10,0,0,[],""],["rm_t3-n4317",1,"¿Para qué me dijiste\n«Rosa temprana,»\nSi soy la más tardía\nQue hay en la rama?",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,173,173,"4317","",0,"palau_cantares","","",10,0,0,[],""],["rm_t3-n4318",1,"Compañerita del alma,\n¿Por dónde la llevas tú?\nYo camino por la arena\nY tú por el cielo azul.",1,0,-1,6,"",0,4,"u",-1,0,-1,0,173,173,"4318","",0,"lafuente_madrid, palau_cantares","","",20,0,0,[],""],["rm_t3-n4319",1,"Si piensas sujetarme\nCon genio adusto,\nYo no doy gusto á nádie,\nSino á mi gusto.\nY si no es bueno,\nTambien sé yo á mi gusto\nPonerle freno.",1,0,-1,6,"",4,7,"eo",76,0,-1,0,173,173,"4319","",0,"","","",1,0,0,[],""],["rm_t3-n4320",1,"De bromiya te lo dije\nQue no entraras en mi casa;\nTan á pecho lo tomastes,\nQue ni por la puerta pasas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,173,173,"4320","",0,"","","",1,0,0,[],""],["rm_t3-n4321",1,"¿Cómo quieres que yo baya\nA los Madriles contigo,\nSi soy casada y no puedo\nOrbidar á mi marido?",1,0,-1,6,"",0,4,"io",-1,0,-1,0,174,174,"4321","",0,"","","",1,0,0,[],""],["rm_t3-n4322",1,"Mujer, ¿qué quieres de mí,\nTú casaíta y yo sortero?\nEs como er refran que dise:\nQuien da pan á perro ajeno....",1,0,-1,6,"",3,4,"eo",-1,0,-1,0,174,174,"4322","",0,"","","",1,0,0,[],""],["rm_t3-n4323",1,"Bén acá, mala gitana,\n¿Qu' es lo que quieres de mí,\nSi ando pidiendo limosna\nPâ que no te farte á tí?",1,0,-1,6,"",0,4,"i",23,0,-1,0,174,174,"4323","",0,"","","",2,0,0,[],""],["rm_t3-n4326",1,"Tengo yo mi corason\nDentro der cuerpo quemao,\nPorque me dise la gente\nQu' á los perros t' has echao",1,0,-1,6,"",0,4,"ao",98,0,-1,0,174,174,"4326","",0,"","","",4,0,0,[],""],["rm_t3-n4328",1,"Al infierno que me baya,\nTenemos que dir los dos,\nPorque tú tienes la curpa\nDe que me condene yo.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,174,175,"4328","",0,"","","",1,0,0,[],""],["rm_t3-n4329",1,"Como tú tienes la curpa\nDe que me condene yo,\nTendrás que benir conmigo\nA prestar declarasion.",1,0,-1,6,"",5,4,"ao",-1,0,-1,0,175,175,"4329","",0,"","","",1,0,0,[],""],["rm_t3-n4330",1,"En er sielo pagarás\nMalos ratos que m' has dao,\nPorque Dios tiene un librito\nY á tôs los yeba apuntaos.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,175,175,"4330","",0,"","","",1,0,0,[],""],["rm_t3-n4331",1,"A Sierra Morena\nMe tengo que dí,\nA jaser bía - con los ermitaños,\nPor curpa de tí.",1,0,-1,6,"",3,4,"i",23,0,-1,0,175,175,"4331","",0,"","","",1,0,0,[],""],["rm_t3-n4332",1,"Tengo de pasarme ar moro\nY tengo de renegá;\nTengo de ser más pirata\nQue Barselon por la má.",1,0,-1,6,"",0,4,"a",9,0,-1,0,175,175,"4332","",0,"","","",1,0,0,[],""],["rm_t3-n4334",1,"De los sentros e la tierra\nTengo e sacar un hombre\nY enseñarle mis costumbres,\nPor ber si me sale noble.",1,0,-1,6,"",0,4,"oe",-1,0,-1,0,175,175,"4334","",0,"","","",1,0,0,[],""],["rm_t3-n4337",1,"A mí no me queman chispas\nDe las más ardientes fraguas;\nLas que me queman á mí\nSon tus partías serranas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,176,176,"4337","",0,"","","",3,0,0,[],""],["rm_t3-n4338",1,"Cuando me siento á la mesa\nY me acuerdo e tus partías,\nTiro er pan y la cuchara\nY aborresco la comía.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,176,176,"4338","",0,"","","",5,0,0,[],""],["rm_t3-n4339",1,"Yo soy serranito puro\nPor tôs los cuatro costaos;\nSi tengo malas partías,\nDe tí me s' habrán pegao.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,176,176,"4339","",0,"","","",1,0,0,[],""],["rm_t3-n4340",1,"La boca te güele á clabo,\nComo si fueras tendera;\n¿De qué te sirbe ser blanca,\nSi tus partías son negras?",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,176,176,"4340","",0,"","","",1,0,0,[],""],["rm_t3-n4341",1,"He apuntaíyo en un libro\nTus arsiones y partías,\nPâ tenerlas en memoria\nToíto er resto e mi bía.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,176,176,"4341","",0,"","","",1,0,0,[],""],["rm_t3-n4342",1,"He querío á esta muchacha\nCon el arma y con la bía\nY s' ha benío acaba\nPor una mala partía.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,176,176,"4342","",0,"","","",1,0,0,[],""],["rm_t3-n4343",1,"M' has jecho malas partías\nY bengativo no soy;\nQu' en queriendo á una persona,\nJasta 'r corason le doy.",1,0,-1,6,"",0,4,"o",112,0,-1,0,177,177,"4343","",0,"","","",1,0,0,[],""],["rm_t3-n4344",1,"Una serrana me ha dicho\nDe tu misma serranía\nQue ningun hombre pequeño\nPuede haser buenas partías.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,177,177,"4344","",0,"","","",3,0,0,[],""],["rm_t3-n4345",1,"¿De qué te sirve que jagas\nConmigo malas partías,\nSi no te cabe 'n er cuerpo\nLa sangre que tienes mia?",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,177,177,"4345","",0,"","","",1,0,0,[],""],["rm_t3-n4347",1,"Si de tus malas partías,\nFlamenca, no m' acordara,\nNi mi corason sintiera,\nNi mis ojitos yoraran..",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,177,177,"4347","",0,"","","",1,0,0,[],""],["rm_t3-n4348",1,"En la sierra eres nasía\nY en la sierra eres criada;\nPor eso, chiquiya mia,\nSon tus partías serranas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,177,177,"4348","",0,"","","",1,0,0,[],""],["rm_t3-n4350",1,"Mi mare me anda disiendo\nQue tú eres, que tú eres,\nUna tierresiya mala\nQue no sirve pâ paeres.",1,0,-1,6,"",0,4,"ee",55,0,-1,0,177,178,"4350","",0,"","","",1,0,0,[],""],["rm_t3-n4352",1,"No me armiro que seas mala,\nPorque te biene d' herensia;\nPorque te dan tentasiones,\nComo ar judío en la ilesia.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,178,178,"4352","",0,"","","",1,0,0,[],""],["rm_t3-n4355",1,"Desciendes de mala rama;\nNo lo puedes remediar;\nLas mujeres y melones\nPor casta se han de buscar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,178,178,"4355","",0,"","","",4,0,0,[],""],["rm_t3-n4356",1,"Tu mare no ha sío güena;\nTú tampoco lo serás;\nDe mar trigo, mala harina;\nDe mala harina, mar pan.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,178,178,"4356","",0,"","","",1,0,0,[],""],["rm_t3-n4357",1,"Dices que eres bien nacida\nY de buenos sentimientos;\nY eres hija de un verdugo,\nPues vives dando tormento.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,178,178,"4357","",0,"","","",1,0,0,[],""],["rm_t3-n4358",1,"Dime con quien andas,\nTe diré quien eres;\nComo tú andas - con malas personas,\nMalito tú eres.",1,0,-1,6,"",3,4,"ee",-1,0,-1,0,179,179,"4358","",0,"","","",1,0,0,[],""],["rm_t3-n4359",1,"Creo que no tienes alma,\nNi naciste en este reino,\nSino que en la morería\nTuviste tu nacimiento.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,179,179,"4359","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4360",1,"Corazon de fiera\nTiene esta mujé:\nComo me be - malito en la cama\n'No me biene á bé.",1,0,-1,6,"",3,4,"e",77,0,-1,0,179,179,"4360","",0,"","","",1,0,0,[],""],["rm_t3-n4361",1,"¡Corason de piedra dura,\nSentrañas de una pantera,\nArma de bronse colao,\nCon inclinasion de fiera!",1,0,-1,6,"",0,4,"ea",44,0,-1,0,179,179,"4361","",0,"","","",1,0,0,[],""],["rm_t3-n4362",1,"Corazon de leona\nTienes á veces;\nAunque me ves que lloro,\nNo te enterneces.",1,0,-1,6,"",6,4,"ee",196,0,-1,0,179,179,"4362","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4363",1,"Sentimientos de leona\nSon los que á tí te acompañan;\nArguna leona fiera\nTe hiso á tí las sentrañas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,179,179,"4363","",0,"","","",1,0,0,[],""],["rm_t3-n4365",1,"Los palomos tienen selo\nY toa clase d' animales;\nTú qu' eres criatura humana,\nNo le tienes ley á nádie.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,180,180,"4365","",0,"","","",1,0,0,[],""],["rm_t3-n4366",1,"¿De qué te sirve tener\nEsa cara tan hermosa,\nSi tiene tu corazon\nEspinas como la rosa?",1,0,-1,6,"",0,4,"oa",63,0,-1,0,180,180,"4366","",0,"lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["rm_t3-n4367",1,"Eres como la adelfa,\nMala gitana;\nQue echas hermosas flores\nY luégo amargan.",1,0,-1,6,"",6,4,"aa",-1,0,-1,0,180,180,"4367","",0,"","","",1,0,0,[],""],["rm_t3-n4368",1,"Con la flor de la adelfa\nTe he comparado,\nQue es hermosa y no come\nDe ella el ganado.",1,0,-1,6,"",6,4,"ao",14,0,-1,0,180,180,"4368","",0,"","","",1,0,0,[],""],["rm_t3-n4370",1,"Si me vieras mal herido\nY en mi sangre revolcado,\nPara tí fuera alegría\nEl verme morir penando.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,180,180,"4370","",0,"","","",1,0,0,[],""],["rm_t3-n4373",1,"Anda y pregúntale á un sabio\nCuál de los dos perdió más:\nTú perdiste la vergüenza;\nYo perdí la libertad.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,181,181,"4373","",0,"","","",5,0,0,[],""],["rm_t3-n4374",1,"Si tú tuvieras talento\nY supieras distinguir,\nTe murieras de vergüenza\nCuando te acuerdas de mí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,181,181,"4374","",0,"","","",1,0,0,[],""],["rm_t3-n4376",1,"Si tú tubieras bergüensa\nY tus sentíos cabales,\nNi pasaras por mi puerta\nNi pisaras mis umbrales.",1,0,-1,6,"",0,4,"ae",26,0,-1,0,181,181,"4376","",0,"","","",3,0,0,[],""],["rm_t3-n4377",1,"Si tú tubieras bergüensa\nY tubieras garlochí,\nTe se cayera la fila\nCuando pasas por aquí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,181,181,"4377","",0,"","","",3,0,0,[],""],["rm_t3-n4379",1,"Triste estoy y avergonzado\nSólo porque te he querido,\nPorque me dice la gente\nQue vergüenza no he tenido.",1,0,-1,6,"",0,4,"io",101,0,-1,0,181,182,"4379","",0,"","","",1,0,0,[],""],["rm_t3-n4382",1,"Olvidé padre y madre\nPor ir contigo,\n¡Y ahora me dejas sola\nPor el camino!",1,0,-1,6,"",3,4,"io",-1,0,-1,0,182,182,"4382","",0,"","","",2,0,0,[],""],["rm_t3-n4384",1,"Por ti abandoné mis hijos;\nMi mare loca murió;\nAhora m' has dejao tú....\n¡No tienes perdon de Dios!",1,0,-1,6,"",0,4,"o",-1,0,-1,0,182,182,"4384","",0,"","","",1,0,0,[],""],["rm_t3-n4385",1,"Por tí perdí yo mis bienes;\nPor tí perdí mis mejoras;\n¡Y ya que perdío me tienes,\nTe ba' y me dejas ahora\n[Malos sentimientos tienes]!",1,0,-1,6,"",7,5,"ee",-1,0,-1,0,182,182,"4385","",0,"","","",1,0,0,[],""],["rm_t3-n4386",1,"Por tí me olvidé de Dios;\nPor tí la gloria perdí;\nY ahora me voy á quedar\nSin Dios, sin gloria y sin tí.",1,0,-1,6,"",3,4,"i",23,0,-1,0,182,182,"4386","",0,"machado_venezuela","","",4,0,0,[],""],["rm_t3-n4387",1,"Déjame buscar á Dios,\nMujer que ya me gosastes;\nNo tienes nâ que pedirme,\nNi yo tengo nâ que darte.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,183,183,"4387","",0,"","","",2,0,0,[],""],["rm_t3-n4388",1,"Déjame buscar á Dios,\nQue yo nunca lo he perdío;\nQue no quiero que otro logre\nCaudales que han sido míos.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,183,183,"4388","",0,"","","",2,0,0,[],""],["rm_t3-n4389",1,"Er querer que puse en tí\nTan firme y tan berdadero,\nSi lo hubiera puesto en Dios,\nHubiera ganado er sielo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,183,183,"4389","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t3-n4390",1,"Er querer que puse en tí\nCon tantísima firmesa,\nSi lo hubiera puesto en Dios,\nTubiera su recompensa.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,183,183,"4390","",0,"","","",4,0,0,[],""],["rm_t3-n4391",1,"Er querer que puse en tí,\nSi lo hubiera puesto en Dios,\nArgo m' hubiera balido\nMás de lo que me balió.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,183,183,"4391","",0,"","","",4,0,0,[],""],["rm_t3-n4393",1,"Mis penas y desventuras\nMuchas y grandes han sido;\nPero la mayor de todas\nEs haberte conocido.",1,0,-1,6,"",0,4,"io",101,0,-1,0,183,183,"4393","",0,"","","",1,0,0,[],""],["rm_t3-n4394",1,"Donde quiera que me ponga\nDiré que no t' he querío;\n¡Harto trabajiyo tengo\nCon haberte conosío!",1,0,-1,6,"",0,4,"io",3,0,-1,0,184,184,"4394","",0,"","","",1,0,0,[],""],["rm_t3-n4395",1,"Más quisiera ser de Argel,\nDe una morita nacido\nY renegar de mi fé\nQue nó haberte conocido.",1,0,-1,6,"",0,4,"io",101,0,-1,0,184,184,"4395","",0,"","","",1,0,0,[],""],["rm_t3-n4396",1,"Más quisiera haber nacido\nArbol silvestre en el campo\nQue nó haberte conocido,\nPara no sufrir yo tanto.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,184,184,"4396","",0,"","","",3,0,0,[],""],["rm_t3-n4397",1,"Más quisiera haberme muerto\nQue nó haberte conosío,\nY no reinara la pena\nQu' está reinando conmigo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,184,184,"4397","",0,"","","",3,0,0,[],""],["rm_t3-n4400",1,"Ponte, compañera, y piensa\nUn ratiyo en mi queré\nY horas tendrás en er dia\nDe no poerte balé.",1,0,-1,6,"",0,4,"e",77,0,-1,0,185,185,"4400","",0,"","","",1,0,0,[],""],["rm_t3-n4402",1,"Tén presente mis partías\nY recuerda en tu memoria;\nQu' ar recordá yo en la mia,\nMis ojitos sangre yoran.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,185,185,"4402","",0,"","","",1,0,0,[],""],["rm_t3-n4403",1,"Acuérdate, esaboría,\nImánge de mis pecaos;\nAcuérdate de las penas\nQue por tu cuerpo he pasao.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,185,185,"4403","",0,"","","",1,0,0,[],""],["rm_t3-n4405",1,"Bén acá, mala flamenca,\n¿No t' ha queao en er cuerpo\nUna gotiya e sangre\nQue te jaga mobimiento?",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,186,186,"4405","",0,"","","",1,0,0,[],""],["rm_t3-n4406",1,"Sólo quiero me digas\nSi te ha quedado\nAlgun triste recuerdo\nDe lo pasado.\nPero me temo\nQue ya de tu memoria\nNo serás dueño.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,186,186,"4406","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n4407",1,"Siempre te estoy tratando\nCon indulgencia,\nPorque tu edad disculpa\nTus ligerezas.\nMas tanto crecen,\nQue es preciso un remedio\nPara que mengüen.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,186,186,"4407","",0,"","","",1,0,0,[],""],["rm_t3-n4409",1,"Á Undebé l' estoy pidiendo\nQue me diñe resistensia;\nQue para bregar contigo\nY a me farta la pasensia.",1,0,-1,6,"",0,4,"ea",187,0,-1,0,186,186,"4409","",0,"","","",3,0,0,[],""],["rm_t3-n4410",1,"Te quise porque te ví\nY te ví porque Dios quiso;\nY al ver qué poco me quieres,\nMe pesa de haberte visto.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,186,186,"4410","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t3-n4411",1,"Yo no sé lo que he de hacerme\nAtento de tu querer;\nSi lo deje de la mano,\nO si me pierda por él.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,187,187,"4411","",0,"","","",1,0,0,[],""],["rm_t3-n4412",1,"Si piensas que porque callo\nTus sinrazones no entiendo,\nAdvierte que aquel que calla\nHablará en llegando el tiempo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,187,187,"4412","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n4413",1,"Tengo yo un cofrecito\nPara ir echando\nPenas y pesadumbres\nQue me vas dando.\nPero algun dia\nSi rompo el cofrecito,\nSerá lamia.",1,0,-1,6,"",4,7,"aa",-1,0,-1,0,187,187,"4413","",0,"","","",5,0,0,[],""],["rm_t3-n4415",1,"No me mires; que tengo\nSangre en los labios\nY el corazon herido\nPor tus agravios.\nLlanto en los ojos\nY el corazon herido\nPor tus enojos.",1,0,-1,6,"",4,7,"oo",99,0,-1,0,187,187,"4415","",0,"","","",1,0,0,[],""],["rm_t3-n4416",1,"Como sabes que te quiero,\nTú te haces de rogar;\nDe la cuerda tiras tanto,\nQue al fin se vendrá á quebrar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,188,188,"4416","",0,"","","",3,0,0,[],""],["rm_t3-n4417",1,"Como sabes que te quiero,\nDe mí te quieres bengar;\nComo t' he sabío querer,\nTambien te sabré orbidar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,188,188,"4417","",0,"","","",3,0,0,[],""],["rm_t3-n4418",1,"Quisistes que te quisiera\nY te quise sin querer;\nNo quieras que te aborrezca,\nQue te voy á aborrecer.",1,0,-1,6,"",0,4,"e",20,0,-1,0,188,188,"4418","",0,"","","",1,0,0,[],""],["rm_t3-n4419",1,"Mientras más te voy queriendo,\nAborreciéndome vas;\nEl mundo da muchas vueltas;\nComo pagas cobrarás.",1,0,-1,6,"",0,4,"a",51,0,-1,0,188,188,"4419","",0,"","","",1,0,0,[],""],["rm_t3-n4420",1,"De enojada y quejosa\nTú punto haces;\nYo he de hacer, si me apuras,\nPunto y aparte.\nSufrir no puedo\nEl paréntesis largo\nDe tus desprecios.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,188,188,"4420","",0,"","","",2,0,0,[],""],["rm_t3-n4421",1,"Tú vives en la calle\nDe la Garduña;\nYo en la de Poñonrostro,\nQue hay menos bulla.\nSon dos extremos;\nConque si no te mudas,\nNo nos hablemos.",1,0,-1,6,"",4,7,"eo",127,0,-1,0,188,188,"4421","",0,"","","",2,0,0,[],""],["rm_t3-n4422",1,"Por tí vivo en la calle\nDe la Amargura,\nY tú en la de Preciados\nVives segura.\nY aunque estoy loco,\nPienso á la del Acuerdo\nMudarme pronto.",1,0,-1,6,"",4,7,"oo",-1,0,-1,0,189,189,"4422","",0,"","","",2,0,0,[],""],["rm_t3-n4423",1,"O finges, ó no finges,\nTirano dueño;\nSi finges, acabóse;\nSi nó, acabemos.",1,0,-1,6,"",6,4,"eo",-1,0,-1,0,189,189,"4423","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n4424",1,"Después de sufrir tanto,\nContra mi genio,\nLe echastes agua al vaso\nQue estaba lleno.\nY así, no extrañes\nQue pierda el sufrimiento,\nPues más no cabe.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,189,189,"4424","",0,"","","",1,0,0,[],""],["rm_t3-n4425",1,"Si del qué dirán quieres,\nNiña, librarte,\nEs preciso que hagamos\nPunto y aparte.\nPorque en el mundo\nNunca en murmuraciones\nSe hace punto.",1,0,-1,6,"",4,7,"uo",-1,0,-1,0,189,189,"4425","",0,"","","",1,0,0,[],""],["rm_t3-n4426",1,"Será rason, compañera,\nQue nuestro querer s' acabe;\nPongamos tierra por medio,\nPâ que la gente no hable.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,189,189,"4426","",0,"","","",1,0,0,[],""],["rm_t3-n4427",1,"En mi vida solicito\nAl que de mí se retira;\nQue he tomado por venganza\nOlvidar á quien me olvida.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,190,190,"4427","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4428",1,"Si me quieres, te quiero;\nSi me amas, te amo;\nSi me olvidas, te olvido;\nA todo hago.",1,0,-1,6,"",6,4,"ao",-1,0,-1,0,190,190,"4428","",0,"fernan_caballero","","",6,0,0,[],""],["rm_t3-n4429",1,"Si me quieres, sé querer;\nSi me olvidas, sé olvidar;\nSi me desprecias, desprecio,\nPorque éste es mi natural.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,190,190,"4429","",0,"","","",4,0,0,[],""],["rm_t3-n4430",1,"Favores y desprecios\nNo los archivo;\nQue los doy al instante\nQue los recibo.\nDe esta manera\nLe pago á cada uno\nEn su moneda.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,190,190,"4430","",0,"","","",2,0,0,[],""],["rm_t3-n4431",1,"A la que por mí suspira\nCon un suspiro le pago;\nYo quiero á quien bien me quiere;\nYo no acaricio ni halago.",1,0,-1,6,"",0,4,"ao",207,0,-1,0,190,190,"4431","",0,"","","",1,0,0,[],""],["rm_t3-n4432",1,"Soy más leal que el caballo;\nMás humilde que la tierra;\nMás carnicero que el lobo,\nSi me tratas con cautela.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,190,190,"4432","",0,"","","",2,0,0,[],""],["rm_t3-n4433",1,"Soy constante y soy mudable,\nPero con tal distincion:\nConstante con quien me ama\nY mudable con quien nó.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,190,191,"4433","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4436",1,"Yo te iré sobrellevando\nHasta que no pueda más;\nQue muchas gotas de cera\nHacen un cirio pascual.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,191,191,"4436","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4437",1,"Como fraile novicio\nSoy en el amar:\nQue aguanto, sufro y callo,\nHasta profesar.\nY en profesando,\nNi aguanto más, ni sufro,\nNi ménos callo.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,191,191,"4437","",0,"","","",1,0,0,[],""],["rm_t3-n4438",1,"Desde aquí te estoy mirando\nQue me la vas á pegar\nY yo te estoy sentenciando\nQue me tengo de vengar.",1,0,-1,6,"",1,4,"a",21,0,-1,0,191,191,"4438","",0,"","","",20,0,0,[],""],["rm_t3-n4439",1,"Como llegues á faltarme\nEn el trato que hemos hecho,\nHe de regar las paredes\nCon la sangre de tu cuerpo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,191,191,"4439","",0,"","","",1,0,0,[],""],["rm_t3-n4440",1,"Debajo de tu ventana\nTengo un puñal escondido,\nPara clavarlo en tu pecho\nSi no te casas conmigo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,192,192,"4440","",0,"lafuente_madrid, palau_cantares","","",29,0,0,[],""],["rm_t3-n4442",1,"Si te haces marinero\nCon intencion de dejarme,\nPermita el cielo divino\nQue el agua del mar te falte.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,192,192,"4442","",0,"","","",3,0,0,[],""],["rm_t3-n4443",1,"Permita Dios que si bienes\nCon intension d' engañarme,\nEn la mitá der camino\nSe abra la tierra y te trague.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,192,192,"4443","",0,"","","",1,0,0,[],""],["rm_t3-n4445",1,"Dibiértete con quien quieras,\nQue tienes lisensia mía;\nY si te piyo en un yerro,\nTienes pena de la bía.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,192,192,"4445","",0,"","","",1,0,0,[],""],["rm_t3-n4446",1,"La mujer qu' ha sío mía\nY ahora no me reconose,\nEsa mujer meresía\nQue la publiquen á boses.",1,0,-1,6,"",3,4,"oe",-1,0,-1,0,192,192,"4446","",0,"","","",1,0,0,[],""],["rm_t3-n4447",1,"Si lo que sueño de noche\nDe dia lo imaginara,\nMás de cuatro personitas\nDe sentimiento lloraran.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,193,193,"4447","",0,"","","",2,0,0,[],""],["rm_t3-n4448",1,"Tú dejaste mi amistad,\nPor querer seguir tu rumbo;\n¡Anda, que pronto verás\nEl pago que te da el mundo!",1,0,-1,6,"",0,4,"uo",-1,0,-1,0,193,193,"4448","",0,"carrizo_salta, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4450",1,"¿Piensas que no ha de benir\nDe Jesucristo er castigo,\nPor lo bien que t' he mirao\nY lo mar que m' has querío?",1,0,-1,6,"",0,4,"io",-1,0,-1,0,193,193,"4450","",0,"","","",1,0,0,[],""],["rm_t3-n4451",1,"Ahora que soy el ayunque\nMe presisa el aguantar;\nSi argun dia soy martiyo,\nBien te puedes preparar.",1,0,-1,6,"",0,4,"a",21,0,-1,0,193,193,"4451","",0,"","","",2,0,0,[],""],["rm_t3-n4452",1,"Ahora que soy el ayunque\nDe mí no tienes clemensia;\nPero en siendo yo er martiyo,\nTendrás que tené pasensia.",1,0,-1,6,"",0,4,"ea",187,0,-1,0,193,193,"4452","",0,"","","",2,0,0,[],""],["rm_t3-n4453",1,"Si porque te ves querida\nMe niegas la voluntad,\nYo he visto una casa nueva\nDerribarla un temporal.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,193,193,"4453","",0,"","","",7,0,0,[],""],["rm_t3-n4454",1,"Si porque te ves querida\nHaces de mí lo que haces,\nMira que Dios no es tan viejo:\nQue todos los años nace.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,194,194,"4454","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t3-n4455",1,"Si porque bes que te quiero\nJasta 'l habla m' has negao,\n¡Anda con Dios, compañera,\nQu' er mundo no s' h' acabao!",1,0,-1,6,"",0,4,"ao",98,0,-1,0,194,194,"4455","",0,"","","",1,0,0,[],""],["rm_t3-n4456",1,"Si de haberme tú querido\nTienes ya remordimiento,\n¡Arrepiéntete y verás\nUn hombre pasar tormentos!",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,194,194,"4456","",0,"","","",1,0,0,[],""],["rm_t3-n4457",1,"Por aquella cruz bendita\nQue está en aquella paré,\nQue te has de quedar en blanco\nComo pliego de papel.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,194,194,"4457","",0,"","","",9,0,0,[],""],["rm_t3-n4458",1,"Ni durmiendo tendrás tú\nTranquilo tu pensamiento;\nQue el que tiene malas cosas\nTiene que vivir despierto.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,194,194,"4458","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t3-n4459",1,"Bien sabe Dios que 'n er mundo\nD' estorbo t' estoy sirbiendo;\nArgun día yorarás,\nCuando no tenga remedio.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,194,194,"4459","",0,"","","",1,0,0,[],""],["rm_t3-n4460",1,"Algun dia llorarás,\nCuando no tenga remedio;\nMe verás y te veré,\nPero no nos hablaremos.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,194,194,"4460","",0,"","","",3,0,0,[],""],["rm_t3-n4461",1,"En el querer no hay venganza;\nTú te has vengado de mí;\nCastigo, tarde ó temprano,\nDel cielo te ha de venir.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,195,195,"4461","",0,"","","",3,0,0,[],""],["rm_t3-n4462",1,"Déjala que cante y ria\nY de mis penas se goce;\nQue puede ser que algun dia\nGotitas de sangre llore.",1,0,-1,6,"",1,4,"oe",-1,0,-1,0,195,195,"4462","",0,"","","",5,0,0,[],""],["rm_t3-n4463",1,"Déjala que vaya y venga\nAl pilarito por agua;\nQue puede ser que algun día\nEn el pilarito caiga.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,195,195,"4463","",0,"","","",3,0,0,[],""],["rm_t3-n4464",1,"Por lo que pasó Jesús\nCamino de las Olivas,\nEn volviendo yo la cara,\nVerás lo que son fatigas.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,195,195,"4464","",0,"","","",1,0,0,[],""],["rm_t3-n4465",1,"Chiquiya, m' has de yorar\nSangre pura, gota á gota;\nEso ha de pasarte á tí,\nChiquiya, por ser tan loca.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,195,195,"4465","",0,"","","",1,0,0,[],""],["rm_t3-n4466",1,"Tú te perdistes sin tiempo;\nPoca reserba has tenío;\nTus ojos serán canales\nPâ yorar lo qu' has perdío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,195,195,"4466","",0,"","","",1,0,0,[],""],["rm_t3-n4467",1,"Tú te ries de mi llanto\nY puede ser que algun día\nYo te vea á tí llorar\nMás que lloró Jeremías.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,195,195,"4467","",0,"frenk_t2","","",2,0,0,[],""],["rm_t3-n4468",1,"Algun dia tú caerás\nEn aquel yerro que hicistes;\nCuando quieras, no podrás\nRecobrar lo que perdistes.",1,0,-1,6,"",1,4,"ie",91,0,-1,0,196,196,"4468","",0,"","","",5,0,0,[],""],["rm_t3-n4469",1,"Échale tú á mi caballo\nHojitas de limon verde;\nQue puede ser que algun dia,\nSerrana, de mí te acuerdes.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,196,196,"4469","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4472",1,"En un hespitá metía\nMis ojitos t' han de bé,\nDe gusanitos comía,\nPorqu' has pagao mi queré\nCon mu malitas partías.",1,0,-1,6,"",7,5,"ia",-1,0,-1,0,196,196,"4472","",0,"","","",1,0,0,[],""],["rm_t3-n4473",1,"Por farsa y por retrechera\nMis ojitos t' han de bé\nE puerta en puerta pîendo\nLimosna por Undebé.",1,0,-1,6,"",0,4,"e",77,0,-1,0,196,196,"4473","",0,"","","",1,0,0,[],""],["rm_t3-n4474",1,"Como gayinita muerta\nQue ruea en los mulaares\nTe tienes que bé, serrana,\nSin que te camele náide.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,196,196,"4474","",0,"","","",1,0,0,[],""],["rm_t3-n4475",1,"Tú te ves elevada\nY yo abatido;\nSeñal que estuve en alto,\nCuando he caido.\nY yo espero ver\nComo después alguno\nTe ha de hacer caer.",1,0,-1,6,"",4,7,"e",20,0,-1,0,197,197,"4475","",0,"","","",3,0,0,[],""],["rm_t3-n4482",1,"Como culebra que sale\nDer nío para morir, (?)\nHas de benir á buscarme\nCuando t' acuerdes de mí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,198,198,"4482","",0,"","","",1,0,0,[],""],["rm_t3-n4483",1,"Bestía de negro luto\nT' he de ber por esas cayes\nY t' has de hincar de rodiyas\nPâ que me pare y te hable.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,198,198,"4483","",0,"","","",1,0,0,[],""],["rm_t3-n4484",1,"Arrastrando por los suelos\nHas de benir á buscarme\nY m' has de pedí por Dios,\nCompañera, que te jable.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,198,198,"4484","",0,"","","",1,0,0,[],""],["rm_t3-n4486",1,"No digas donde te pongas\nQue agua tienes de bautismo;\nQue t' han d' escupí á la cara\nPor lo qu' has jecho conmigo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,198,199,"4486","",0,"","","",1,0,0,[],""],["rm_t3-n4487",1,"Si la Inquisision supiera\nLo que tú has jecho conmigo,\nBinieran y te prendieran\nY te quemarian bibo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,199,199,"4487","",0,"","","",2,0,0,[],""],["rm_t3-n4488",1,"Si la Inquisision supiera\nLo mucho que t' he querío\nY er mar pago que m' has dao,\nTe quemaban por judío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,199,199,"4488","",0,"","","",2,0,0,[],""],["rm_t3-n4489",1,"Jasta ar sabio Salomon\nLe conté yo tus partías\nY me respondió yorando:\n-No paga ni con la bía.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,199,199,"4489","",0,"","","",1,0,0,[],""],["rm_t3-n4490",1,"Si al principio de quererte\nMe hubieras desengañado,\nNo hubiera llegado esto\nAl paraje que ha llegado.",1,0,-1,6,"",0,4,"ao",14,0,-1,0,199,199,"4490","",0,"","","",2,0,0,[],""],["rm_t3-n4491",1,"Si al principio de quererte\nMe hubieras dicho que nó,\nNo hubiera llegado esto\nAl paraje que llegó.",1,0,-1,6,"",0,4,"o",2,0,-1,0,199,199,"4491","",0,"","","",2,0,0,[],""],["rm_t3-n4492",1,"Después de haberme engañado,\n¿A qué vienes á buscarme?\nMás valia que te fueras\nDonde no te viera nádie.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,199,199,"4492","",0,"","","",1,0,0,[],""],["rm_t3-n4493",1,"Basta para desengaños;\nNo quiero más ceguedad;\nQue el yerro de haber querido\nSe paga con olvidar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,199,200,"4493","",0,"","","",1,0,0,[],""],["rm_t3-n4494",1,"Vamos á ajustar la cuenta\nDel tiempo que te he querido;\nDame la carta de pago\nY yo te daré el recibo.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,200,200,"4494","",0,"","","",3,0,0,[],""],["rm_t3-n4495",1,"Si el querer bien se pagara,\n¡Cuánto me fueras debiendo!\nPero como no se paga,\nNi me debes ni te debo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,200,200,"4495","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4496",1,"No quiero que me des gloria,\nPorque no la he merecido;\nLo que quiero es que me pagues\nEl tiempo que te he querido.",1,0,-1,6,"",0,4,"io",101,0,-1,0,200,200,"4496","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4497",1,"Algun dia querrá Dios\nQue yo te encuentre en la calle,\nY ajustaremos las cuentas,\nY el que debiere, que pague.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,200,200,"4497","",0,"","","",5,0,0,[],""],["rm_t3-n4498",1,"Con venderte no me pagas\nLo mucho que te he querido,\nAunque tu cuerpo valiera\nValor de treinta navíos.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,200,200,"4498","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4499",1,"Tengo de escribir mi vida\nY he de mandarla imprimir,\nPara que sepa la gente\nQue la falta ha estado en tí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,200,200,"4499","",0,"","","",2,0,0,[],""],["rm_t3-n4500",1,"Tengo de escribir mi vida\nY he de mandarla á la imprenta\nPara que sepa la gente\nLo que tu querer me cuesta.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,200,201,"4500","",0,"","","",2,0,0,[],""],["rm_t3-n4501",1,"Si piensas que son ganansias\nLas que contigo he tenío,\nHe perdío la salú\nY er tiempo que t' he querío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,201,201,"4501","",0,"","","",1,0,0,[],""],["rm_t3-n4502",1,"Quien hubiere encontrado\nUna esperanza,\nPor Dios que me la vuelva;\nQue me hace falta.\nMas.... bien mirado,\nQue se quede con ella\nQuien la haya hallado.",1,0,-1,6,"",4,7,"ao",14,0,-1,0,201,201,"4502","",0,"","","",1,0,0,[],""],["rm_t3-n4503",1,"He de hacer un castillo\nCon cuatro torres:\nEsperanza, firmeza,\nCelos y amores.\nY por remate,\nHe de poner la estatua\nDe un firme amante.",1,0,-1,6,"",4,7,"ae",-1,0,-1,0,201,201,"4503","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n4504",1,"Tú me estás dando lugar\nDe que eche la capa al toro,\nY que tire de la manta,\nY que se descubra todo.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,201,201,"4504","",0,"","","",3,0,0,[],""],["rm_t3-n4505",1,"He pensao compañera,\nDe no jablarte 'n la bía,\nPâ que no diga tu mare\nQue por mi te be perdía.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,201,201,"4505","",0,"","","",1,0,0,[],""],["rm_t3-n4506",1,"Dises que no me puês be;\nEr remedio 'stá 'n tu mano:\nDonde quiera que me bieres\nJarme la cruz como ar diablo.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,202,202,"4506","",0,"","","",3,0,0,[],""],["rm_t3-n4508",1,"Para perder er sentío\nYa tengo lo muy bastante;\nQu' he reconosío en tí\nQue quiere Dios castigarme.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,202,202,"4508","",0,"","","",1,0,0,[],""],["rm_t3-n4509",1,"A la Vírgen del Rosario\nLe pido de corazon\nQue de tu vista me aparte;\nQue has de ser mi perdicion.",1,0,-1,6,"",0,4,"o",31,0,-1,0,202,202,"4509","",0,"","","",3,0,0,[],""],["rm_t3-n4510",1,"Ya no te quiero, nó, nó;\nYa no te quiero, ni verte;\nQue has de ser mi perdicion\nY la causa de mi muerte.",1,0,-1,6,"",0,4,"ee",134,0,-1,0,202,202,"4510","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4511",1,"Ya no quiero querer más;\nQuiero seguir mi opinion;\nQue un querer con mucho estremo\nEs causa de perdicion.",1,0,-1,6,"",0,4,"io",31,0,-1,0,202,202,"4511","",0,"","","",3,0,0,[],""],["rm_t3-n4512",1,"Anda véte de mi vera,\nQue te lo pido por Dios;\nSi no te vas de mi vera,\nHas de ser mi perdicion.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,202,202,"4512","",0,"","","",1,0,0,[],""],["rm_t3-n4513",1,"Este querer que te tengo\nEs una locura grande;\nYo de tí no saco nada;\nLo que saco es condenarme.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,203,203,"4513","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4514",1,"Soñé que me condenaba\nSi seguia en tu amistá;\nYo me apartaré de tí,\nNo sarga el sueño berdá.",1,0,-1,6,"",0,4,"a",9,0,-1,0,203,203,"4514","",0,"","","",1,0,0,[],""],["rm_t3-n4515",1,"De rodiyas boy á Roma\nA confesar mis pecaos;\nQue 'r tiempo que t' he querío\nHe bibío condenao.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,203,203,"4515","",0,"","","",2,0,0,[],""],["rm_t3-n4517",1,"Cuando yo te quise á tí\nNo estaba yo en mi sentío;\nPorque si lo hubiera estao,\nOtra cosa hubiera sío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,203,203,"4517","",0,"","","",3,0,0,[],""],["rm_t3-n4518",1,"Jise la cama en un rio,\nLa cabesera en un poso;\nEs berdá que t' he querío;\nPero ya no te conosco.",1,0,-1,6,"",0,4,"oo",-1,0,-1,0,203,203,"4518","",0,"","","",1,0,0,[],""],["rm_t3-n4519",1,"Cuando hables de mi persona,\nNo diga que me ha querido;\nDí que fué un capricho sólo\nQue los dos hemos tenido.",1,0,-1,6,"",0,4,"io",101,0,-1,0,203,203,"4519","",0,"","","",3,0,0,[],""],["rm_t3-n4521",1,"Es piedra que se echa á un rio\nEl querer que puse en tí:\nQue llega al fondo, se clava\nY ya no vuelve á salir.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,204,204,"4521","",0,"","","",1,0,0,[],""],["rm_t3-n4522",1,"A dios y olvida mi nombre;\nNo te acuerdes más de mí;\nBórrame de tu memoria\nY hazte cuenta que morí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,204,204,"4522","",0,"","","",1,0,0,[],""],["rm_t3-n4523",1,"Tu falsa correspondencia\nPuso fin á mi alegría;\nEs verdad que no te quiero;\nNo me hables más en tu vida.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,204,204,"4523","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4524",1,"Anda véte, que no quiero\nPasar por tí más fatigas;\nTe portas como quien eres;\n¿Qué más quieres que te diga?",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,204,204,"4524","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n4525",1,"Te pido que no me mires;\nTe pido que no me hables;\nQue si te escucho y te miro,\nVas á volver á engañarme.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,204,204,"4525","",0,"","","",1,0,0,[],""],["rm_t3-n4527",1,"Yo no puedo negarte\nQue te he querido;\nFué una pasion honesta\nY amor novicio.\nNo he profesado;\nQue es religion estrecha\nLa del casado.",1,0,-1,6,"",4,7,"ao",14,0,-1,0,204,205,"4527","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4528",1,"Se ha marchitado el árbol\nDe mi esperanza;\nUn traidor le ha cortado\nSus verdes ramas.\nPero él no advierte\nQue mudando terreno,\nMejor florece.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,205,205,"4528","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4529",1,"A mi corazon le he dicho\nQue no suspire ni llore;\nQue si le has dado mal pago,\nNo faltará quien le adore.",1,0,-1,6,"",0,4,"oe",77,0,-1,0,205,205,"4529","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t3-n4530",1,"He pasado en este mundo\nMuchas fatigas por tí;\nPero ya ha llegado el dia\nDe que las pases por mí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,205,205,"4530","",0,"","","",2,0,0,[],""],["rm_t3-n4531",1,"Gracias á Dios que ya tiene\nAlivio mi corazon;\nRazon será que tú pases\nPor lo que he pasado yo.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,205,205,"4531","",0,"","","",1,0,0,[],""],["rm_t3-n4532",1,"Será el contento grande\nDe tu infiel pecho\nCuando sepas, infame,\nQue ya me ausento.\nYa quedas suelta;\nPrevén otro amor nuevo\nQue me suceda.",1,0,-1,6,"",4,7,"ea",-1,0,-1,0,205,206,"4532","",0,"","","",1,0,0,[],""],["rm_t3-n4534",1,"Y a he roto las cadenitas\nQue me ligaban á tí;\nPues donde el engaño empieza\nDebe el amor tener fin.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,206,206,"4534","",0,"","","",1,0,0,[],""],["rm_t3-n4535",1,"Suéltame la cadenita\nCon que me tienes atado;\nQue bastante tiempo he sido\nDe tu rigor castigado.",1,0,-1,6,"",0,4,"ao",14,0,-1,0,206,206,"4535","",0,"","","",1,0,0,[],""],["rm_t3-n4536",1,"Cuando te veo con pena,\nTe digo:-Bien empleado;\nQue no has querido tomar\nLos consejos que te he dado.",1,0,-1,6,"",0,4,"ao",14,0,-1,0,206,206,"4536","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["rm_t3-n4538",1,"Si escucharas mis consejos\nNo lloraras como lloras;\nNo los quisistes tomar;\n¿A quién te quejas ahora?",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,206,206,"4538","",0,"","","",1,0,0,[],""],["rm_t3-n4539",1,"Bien sabes que te lo dije\nQue te miraras en ello;\nY te has venido á mirar\nCuando no tiene remedio.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,206,206,"4539","",0,"","","",1,0,0,[],""],["rm_t3-n4540",1,"¿De qué te sirbe que yores\nNi te caliente' 'r sentío,\nSi ya no tiene remedio\nLo qu' á tí t' ha susedío?",1,0,-1,6,"",0,4,"io",3,0,-1,0,207,207,"4540","",0,"","","",1,0,0,[],""],["rm_t3-n4542",1,"En los libros del olvido\nMe manda Dios que te ponga,\nPorque tu querer ha sido\nComo cangilon de noria.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,207,207,"4542","",0,"","","",3,0,0,[],""],["rm_t3-n4543",1,"Por cumplir con Dios y el mundo\nTe hablaré cuando te encuentro;\nPero para entre los dos,\nComo si te hubieras muerto.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,207,207,"4543","",0,"","","",1,0,0,[],""],["rm_t3-n4545",1,"No preguntes por qué voy\nToda vestida de negro:\nAndo vestida de luto,\nPorque para mí te has muerto.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,207,207,"4545","",0,"","","",1,0,0,[],""],["rm_t3-n4546",1,"Bien sabe Dios que me alegro\nQue andes buscando tu vida\nCon la misma libertad\nCon que yo busco la mia.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,207,207,"4546","",0,"","","",2,0,0,[],""],["rm_t3-n4547",1,"Como cosa propia\nTe queria yo;\nPero quererte - como te queria,\nYa eso s' acabó.",1,0,-1,6,"",3,4,"o",2,0,-1,0,207,208,"4547","",0,"","","",1,0,0,[],""],["rm_t3-n4548",1,"Yo estuve queriendo á un hombre,\nTanto, que ya me faltaba\nLa luz del entendimiento\nCada vez que lo miraba.",1,0,-1,6,"",0,4,"aa",28,0,-1,0,208,208,"4548","",0,"","","",1,0,0,[],""],["rm_t3-n4549",1,"Yo estube queriendo á un hombre\nUn punto ménos que á Dios;\nJiso una mala partía,\nPero ya no jiso dos.",1,0,-1,6,"",0,4,"o",87,0,-1,0,208,208,"4549","",0,"","","",1,0,0,[],""],["rm_t3-n4550",1,"Yo soy aquer que murió\nY he buerto á resusitar,\nY en er sementerio supe\nQuien me quiso bien ó má.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,208,208,"4550","",0,"","","",1,0,0,[],""],["rm_t3-n4551",1,"Cuando quise no quisistes\nY ahora que quieres no quiero;\nGoza, pues, el amor triste,\nCual yo lo gocé primero.",1,0,-1,6,"",3,4,"eo",38,0,-1,0,208,208,"4551","",0,"","","",1,0,0,[],""],["rm_t3-n4555",1,"Anda con Dios, amor mio;\nQue yo sembraré en mi güerto\nLa semiya del orbío\nY la flor del escarmiento.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,210,210,"4555","",0,"","","",2,0,0,[],""],["rm_t3-n4562",1,"Mira qué poquito á poco\nBas pagando lo que debes:\nPor tus malitas partías\nNadie 'n er mundo te quiere.",1,0,-1,6,"",0,4,"ee",-1,0,-1,0,212,212,"4562","",0,"","","",2,0,0,[],""],["rm_t3-n4563",1,"Bén acá, mala mujé;\nMira cómo t' has queao,\nQue no te quieren los mosos,\nNi tampoco los casaos.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,212,212,"4563","",0,"","","",2,0,0,[],""],["rm_t3-n4564",1,"Tú te fuistes de mi bera\nPensando tené alegría,\nY ahora te bes, compañera,\nDe tô 'r mundo aborresía.",1,0,-1,6,"",3,4,"ia",0,0,-1,0,212,212,"4564","",0,"","","",1,0,0,[],""],["rm_t3-n4565",1,"El pago que te da el mundo\nTe está muy bien empleado;\nQue siempre la ingratitud\nHa merecido ese pago.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,212,212,"4565","",0,"","","",2,0,0,[],""],["rm_t3-n4566",1,"La camisa de mi cuerpo\nPídela y te la daré;\nPero no por eso esperes\nQue yo vuelva á tu querer.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,212,212,"4566","",0,"","","",3,0,0,[],""],["rm_t3-n4567",1,"Mujer que tanto la quise\nY tan mal pago me dió,\nNo la miraré á la cara\nMientras mi Dios fuere Dios,",1,0,-1,6,"",0,4,"o",-1,0,-1,0,212,212,"4567","",0,"","","",1,0,0,[],""],["rm_t3-n4571",1,"Piedresitas e la caye\nSe güerban granos e sá\nY me caigan en los ojos\nSi yo te güerbo á mirá.",1,0,-1,6,"",0,4,"a",9,0,-1,0,213,213,"4571","",0,"","","",1,0,0,[],""],["rm_t3-n4572",1,"Si con una lus me buscas,\nNo me tienes d' encontrá;\nCuando de tu yerro caigas\nAr mengue tiês que yamá.",1,0,-1,6,"",0,4,"a",9,0,-1,0,213,213,"4572","",0,"","","",1,0,0,[],""],["rm_t3-n4573",1,"Fundía como campana\nSa menesté qu' estubieras\nPâ que yo sin reselá\nA tus quereles borbiera.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,213,213,"4573","",0,"","","",1,0,0,[],""],["rm_t3-n4577",1,"Tú te fuistes por tu gusto;\nNáide t' ha echao á la caye;\nAhora tú p' hablá cormigo\nN esesitas memoriales.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,214,214,"4577","",0,"","","",1,0,0,[],""],["rm_t3-n4578",1,"Pâ que borbiera á quererte\nMe tenías que traé,\nEscritos e puño y letra,\nLos informes d' Undibé.",1,0,-1,6,"",0,4,"e",77,0,-1,0,214,214,"4578","",0,"","","",1,0,0,[],""],["rm_t3-n4579",1,"Pâ que yo te quiera\nEs lo nesesario\nQue los informes - d' Undebé der sielo\nPasen por mi mano.",1,0,-1,6,"",3,4,"ao",-1,0,-1,0,214,214,"4579","",0,"","","",1,0,0,[],""],["rm_t3-n4580",1,"Aunque te pongas en cruz,\nNo te tengo de creer;\nPorque ya sé lo que valen\nJuramentos de mujer.",1,0,-1,6,"",0,4,"e",20,0,-1,0,214,214,"4580","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4581",1,"Aunque en una cruz te pongas\nVestido de Nazareno\nY pegues las tres caidas,\nEn tus palabras no creo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,214,214,"4581","",0,"","","",7,0,0,[],""],["rm_t3-n4582",1,"Aunque en una cruz te pongas,\nPara mí acabastes ya,\nPorque quisistes á un tiempo\nCon dos barajasjugar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,214,215,"4582","",0,"","","",7,0,0,[],""],["rm_t3-n4584",1,"Toma el camino de Roma,\nCon el Padre Santo habla\nY dile que te perdone,\nQue has querido á dos hermanas.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,215,215,"4584","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4585",1,"Si quieres ponerte güena\nD' ese mar que Dios t' ha dao,\nAnda béte á Capuchinos\nY confiesa tus pecaos.",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,215,215,"4585","",0,"","","",1,0,0,[],""],["rm_t3-n4586",1,"Anda béte á un simenterio,\nY yébate un Santo Cristo,\nY encomiéndale tu arma;\nQu' es muy grande tu delito.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,215,215,"4586","",0,"","","",1,0,0,[],""],["rm_t3-n4590",1,"Anda, que ya no mereces\nQue mi lengua te salude;\nPor el tiempo que te quise\nLe pido á Dios que te ayude.",1,0,-1,6,"",0,4,"ue",215,0,-1,0,216,216,"4590","",0,"","","",1,0,0,[],""],["rm_t3-n4591",1,"Dios perdone á quien es causa\nDe mis trabajos perdidos\nY advierta que con la vara\nQue mida ha de ser medido.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,216,216,"4591","",0,"","","",1,0,0,[],""],["rm_t3-n4593",1,"M' han bendío tus secretos\nPersonas de tu amistá;\nLuego dirás que soy malo;\n¡Y no me quiero bengar!",1,0,-1,6,"",0,4,"a",-1,0,-1,0,216,216,"4593","",0,"","","",1,0,0,[],""],["rm_t3-n4594",1,"Es más grande mi querer\nQue la voluntad de Dios,\nPorque Dios no te perdona\nLo que te perdono yo.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,216,216,"4594","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4595",1,"Tú, misionero de Dios,\nSi por el mundo la encuentras,\nDile que yo la perdono;\nPero que no quiero verla.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,216,216,"4595","",0,"","","",1,0,0,[],""],["rm_t3-n4596",1,"Dos aves en un árbol\nJuntas vivieron\nY por varias disputas\nSe indispusieron.\nY se ausentaron,\nY quedó el árbol seco\nY arruïnado.",1,0,-1,6,"",4,7,"ao",-1,0,-1,0,216,217,"4596","",0,"","","",1,0,0,[],""],["rm_t3-n4597",1,"Quise bien y aborrecí,\nQue no es delito en quien ama;\nQue cuando yo aborrecí,\nMás que aborrecido estaba.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,270,270,"4597","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t3-n4598",1,"No quiero que me quieras,\nNi yo quererte;\nSino que me aborrezcas\nY aborrecerte.",1,0,-1,6,"",6,4,"ee",134,0,-1,0,270,270,"4598","",0,"","","",4,0,0,[],""],["rm_t3-n4599",1,"Biendo que no me querias,\nCompré un aborresimiento;\nY jise tan güen mercao,\nQue t' aborresí ar momento.",1,0,-1,6,"",0,4,"eo",94,0,-1,0,270,270,"4599","",0,"","","",1,0,0,[],""],["rm_t3-n4600",1,"Quítate de mi presencia,\nQue no te quiero mirar;\nQue te tengo aborrecido\nComo al pecado mortal.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,270,270,"4600","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n4601",1,"Tanto como te queria,\nTanto yegué ' aborreserte,\nQue si en la iglesia te bia,\nMe salia por no berte\n[Y hasta la misa perdia].",1,0,-1,6,"",7,5,"ea",0,0,-1,0,270,271,"4601","",0,"","","",2,0,0,[],""],["rm_t3-n4603",1,"Sombra de jiguera negra\nTe caiga en er corason;\n¡Donde quiera que te pones\nSacas mi combersasion!",1,0,-1,6,"",0,4,"ao",-1,0,-1,0,271,271,"4603","",0,"","","",2,0,0,[],""],["rm_t3-n4604",1,"De tu mardita lengua\nQuiero un guisao;\nQue tu mardita lengua\nM' ha deshonrao.",1,0,-1,6,"",6,4,"ao",98,0,-1,0,271,271,"4604","",0,"","","",1,0,0,[],""],["rm_t3-n4605",1,"Un puchero de lenguas\nTraigo en sarmuera;\nLa primera es la tuya\n' La de mi suegra.\nTraigo en aseite;\nLa primera es la tuya\n' La de tu gente.",1,0,-1,6,"",4,7,"ee",-1,0,-1,0,271,271,"4605","",0,"","","",1,0,0,[],""],["rm_t3-n4606",1,"Se pone tu madre y dice\nQue se alegra de mi mal;\nSi la lengua se le balda,\nYo tambien me he de alegrar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,271,271,"4606","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4608",1,"Por una mala lengua\nQue hay en mi barrio,\nNi mi amante me habla,\nNi yo le hablo.\nPermita el cielo\nQue á esa maldita lengua\nLe caiga fuego.",1,0,-1,6,"",4,7,"eo",-1,0,-1,0,272,272,"4608","",0,"","","",1,0,0,[],""],["rm_t3-n4609",1,"La mardita lengua\nQue de mí mormura\nYo la cogiera - por ermedio ermedio,\nLa dejara mua.",1,0,-1,6,"",3,4,"a",-1,0,-1,0,272,272,"4609","",0,"","","",1,0,0,[],""],["rm_t3-n4610",1,"Er que de mí mar hable\nTenga en la lengua\nUn carbunco, una yaga\nY una postema.\nY al estribiyo,\nBentisinco alaclanes\nEn er gayiyo.",1,0,-1,6,"",4,7,"io",221,0,-1,0,272,272,"4610","",0,"","","",1,0,0,[],""],["rm_t3-n4611",1,"Er sapato tengo roto;\n¿Con qué lo remendaré?\nCon picos de malas lenguas,\nQuejablan lo que no es.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,272,272,"4611","",0,"","","",2,0,0,[],""],["rm_t3-n4612",1,"¿Quién te ha dicho mal de mí,\nViviendo de mí tan léjos?\n¡Maldito el que lleva y trae\nY el que da malos consejos!",1,0,-1,6,"",0,4,"eo",149,0,-1,0,272,272,"4612","",0,"","","",1,0,0,[],""],["rm_t3-n4613",1,"Mal haya quien lleva y trae\nY quien da malos consejos;\nQuien pone mal corazon\nA aquel que lo tiene bueno.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,272,273,"4613","",0,"","","",1,0,0,[],""],["rm_t3-n4615",1,"Aquer que tiene la curpa\nDe que tú á mí no me quieras\nHan de permitir los sielos\nQue se lo trague la tierra.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,273,273,"4615","",0,"","","",1,0,0,[],""],["rm_t3-n4616",1,"Der sielo caiga una piedra\nQue pese dos mir quintales\nY le rompa la cabesa\nA quien quiebra boluntares.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,273,273,"4616","",0,"","","",1,0,0,[],""],["rm_t3-n4617",1,"De la muraya más arta\nSe caiga quien mar me quiera;\nSi es hombre, que se rebiente;\nSi es mujer, rabiando muera.",1,0,-1,6,"",0,4,"ea",44,0,-1,0,273,273,"4617","",0,"","","",1,0,0,[],""],["rm_t3-n4618",1,"Aquel que tiene la culpa\nDe que yo fatigas pase\nSe vea en Argel cautivo,\nSin tener quien lo rescate.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,273,273,"4618","",0,"","","",4,0,0,[],""],["rm_t3-n4620",1,"A Undebé l' estoy pidiendo\nTe dé lo que te combenga;\nQue lo qu' has jecho conmigo\nNo lo jase ni una negra.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,273,274,"4620","",0,"","","",3,0,0,[],""],["rm_t3-n4621",1,"Quisiera que Dios me oyera,\nY que las piedras hablaran,\nY que el castigo viniera\nComo yo lo deseara.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,274,274,"4621","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4622",1,"Pues los cariños te ofenden,\nLe pido á Dios de los cielos\nQue de aquel á quien estimas\nTengas que sufrir desprecios.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,274,274,"4622","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n4623",1,"Quiera Dios que donde pongas\nTodos tus sinco sentíos\nLe paguen á tu querer\nComo tú pagas er mio.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,274,274,"4623","",0,"","","",1,0,0,[],""],["rm_t3-n4624",1,"A mi Dios le estoy pidiendo\nQue como me matas mueras:\nQue te bean mis ojitos\nQuerer y que no te quieran.",1,0,-1,6,"",0,4,"ea",-1,0,-1,0,274,274,"4624","",0,"","","",1,0,0,[],""],["rm_t3-n4625",1,"Premita Dios que te beas\nAborresía y queriendo\nY que las ducas te roan\nLas entrañas e tu cuerpo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,274,274,"4625","",0,"","","",3,0,0,[],""],["rm_t3-n4626",1,"Entre la hostia y er cális\nA mi Dios se lo pedí:\n¡Que t' ajoguen las fatigas\nComo m' ajogan á mí!",1,0,-1,6,"",0,4,"i",23,0,-1,0,274,274,"4626","",0,"","","",1,0,0,[],""],["rm_t3-n4627",1,"Premitan los sielos\nPremítalo Dios,\nQue co' r cuchiyo-que matarme quieres\nTe matara yo.",1,0,-1,6,"",3,4,"o",-1,0,-1,0,274,275,"4627","",0,"","","",1,0,0,[],""],["rm_t3-n4628",1,"Premita Dios que te beas\nEsmamparaíta y sola\nY que bengas á peirme\nPo' Undibé que te socorra.",1,0,-1,6,"",0,4,"oa",-1,0,-1,0,275,275,"4628","",0,"","","",3,0,0,[],""],["rm_t3-n4629",1,"Permita Dios que te beas\nEn la ruea der bapó,\nY er bapó se baya á pique,\nY tú me pias perdon.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,275,275,"4629","",0,"","","",5,0,0,[],""],["rm_t3-n4630",1,"Permita Dios que te beas\nMetía en San Juan de Dios;\nMedesina que tomares\nTe la baya dando yo.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,275,275,"4630","",0,"","","",5,0,0,[],""],["rm_t3-n4631",1,"Permita Dios que te beas\nEn un hespitá rabiando\nY no tengas más consuelo\nQu' er que yo te baya dando.",1,0,-1,6,"",0,4,"ao",33,0,-1,0,275,275,"4631","",0,"","","",5,0,0,[],""],["rm_t3-n4632",1,"Permita Dios que te beas\nEn un calaboso oscuro\nY que pase por mi mano\nTodo el alimento tuyo.",1,0,-1,6,"",0,4,"uo",-1,0,-1,0,275,275,"4632","",0,"","","",5,0,0,[],""],["rm_t3-n4633",1,"La maldicion que te echo\nDesde hoy en adelante\nEs que el dinero te sobre,\nPero que el gusto te falte.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,275,275,"4633","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4634",1,"¡Anda con Dios, bien te logres!\nNo te deseo mar ninguno...\n¡Hora de salú no tengas\nMientras bibas en er mundo!",1,0,-1,6,"",0,4,"uo",-1,0,-1,0,276,276,"4634","",0,"","","",4,0,0,[],""],["rm_t3-n4637",1,"Mardita sea la hora\nQue yo t' empesé á queré;\nMardito tu padre y madre\nY mardita tú tambien.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,276,276,"4637","",0,"","","",1,0,0,[],""],["rm_t3-n4639",1,"Las mantecas e tu cuerpo\nTe se bean erretías,\nEn bé que jases conmigo\nEsas chunguiyas partías.",1,0,-1,6,"",0,4,"ia",214,0,-1,0,276,276,"4639","",0,"","","",1,0,0,[],""],["rm_t3-n4641",1,"¡No saliera d' aquer monte\nUna sierpe y te tragara!\n¡Tan bien como t' he querío,\nY tan mar como me pagas!",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,276,277,"4641","",0,"","","",1,0,0,[],""],["rm_t3-n4642",1,"Tierra, ¿por qué no te abres\nY te sales de tu sentro,\nTe tragas á esta serrana\nCon tan malos sentimientos?",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,277,277,"4642","",0,"","","",2,0,0,[],""],["rm_t3-n4643",1,"Tantas hojas como tiene\nL' alameda del Genil,\nTantos demonios te yeben\nCuando t' acuerdes de mí.",1,0,-1,6,"",0,4,"i",-1,0,-1,0,277,277,"4643","",0,"","","",3,0,0,[],""],["rm_t3-n4645",1,"Permita Dios que te mueras,\nY que t' entierren de barde;\nY te tapen la carita,\nPâ que no te bea nádie.",1,0,-1,6,"",0,4,"ae",-1,0,-1,0,277,277,"4645","",0,"","","",1,0,0,[],""],["rm_t3-n4647",1,"Anda béte de mi bera;\nMar fin tengas, condenao;\nM' ofresistes tu cariño\nY después m' has engañao.",1,0,-1,6,"",0,4,"ao",98,0,-1,0,277,277,"4647","",0,"","","",2,0,0,[],""],["rm_t3-n4650",1,"' Aquer que tubo la curpa,\nMare, de mi perdision,\nA cachitos se le caigan\nLas alas der corason.",1,0,-1,6,"",5,4,"ao",-1,0,-1,0,278,278,"4650","",0,"","","",1,0,0,[],""],["rm_t3-n4651",1,"T' has yebaíto e mi cuerpo\nLa prenda de más baló;\n¡A peasos te se caigan\nLas alas der corason!",1,0,-1,6,"",5,4,"ao",-1,0,-1,0,278,278,"4651","",0,"","","",1,0,0,[],""],["rm_t3-n4654",1,"Mala puñalâ te peguen\nQue te parta er corason;\nQue lo qu' has jecho cormigo\nNo te lo perdona Dios.",1,0,-1,6,"",5,4,"o",-1,0,-1,0,278,278,"4654","",0,"","","",3,0,0,[],""],["rm_t3-n4655",1,"Mala puñalâ te den\nQu' er corason te lo partan;\nQue lo qu' has jecho conmigo\nCon nâ der mundo se paga.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,278,278,"4655","",0,"","","",1,0,0,[],""],["rm_t3-n4658",1,"Te fistes y me dejastes\nEnmedio de mis fatigas;\nMala puñalâ te den\nQu' er Santolio no resibas.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,279,279,"4658","",0,"","","",4,0,0,[],""],["rm_t3-n4660",1,"Ar reborbé d' una esquina\nT' encontré y no me mirastes;\n¡Mala puñalâ te den,\nY qué pronto me dejastes!",1,0,-1,6,"",0,4,"ae",142,0,-1,0,279,279,"4660","",0,"","","",2,0,0,[],""],["rm_t3-n4661",1,"Mala puñalâ le den\nA la mujé mardesía\nQue con sus malas arsiones\nM' está quitando la bía.",1,0,-1,6,"",0,4,"ia",0,0,-1,0,279,279,"4661","",0,"","","",1,0,0,[],""],["rm_t3-n4662",1,"A puñalaítas muera\nEr que m' enseñó á queré;\nQu' estaba yo en mi sentío\nY ahora m' encuentro sin é.",1,0,-1,6,"",3,4,"e",77,0,-1,0,279,279,"4662","",0,"","","",1,0,0,[],""],["rm_t3-n4663",1,"Jablo solo por la caye\nEstando yo en mi sentío;\nMar tiro le den de muerte\nAr; que la curpa ha tenío.",1,0,-1,6,"",0,4,"io",3,0,-1,0,279,279,"4663","",0,"","","",1,0,0,[],""],["rm_t3-n4668",1,"Mi corazon, como niño,\nTe demostró su querer\nY tú me lo despreciastes;\n¡Anda, mal tiro te den!",1,0,-1,6,"",0,4,"e",-1,0,-1,0,280,280,"4668","",0,"","","",1,0,0,[],""],["rm_t3-n4670",1,"Me han dicho que estás mala;\nDios te levante....\nDe la cama á la caja,\nPara enterrarte.",1,0,-1,6,"",6,4,"ae",-1,0,-1,0,280,280,"4670","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n4671",1,"Yo estoy perdia y m' alegro\nDe berte perdío á ti;\nY otro perdío s' alegra\nDe berme perdía á mí.",1,0,-1,6,"",0,4,"i",23,0,-1,0,280,280,"4671","",0,"","","",1,0,0,[],""],["rm_t3-n4672",1,"Aunque me ves que canto,\nCantando rabio:\nSoy mujer y no puedo\nVengar mi agravio.",1,0,-1,6,"",6,4,"ao",223,0,-1,0,281,281,"4672","",0,"","","",6,0,0,[],""],["rm_t3-n4673",1,"No me bengas con jachares,\nDisiéndome que te bas;\nMardita sea tu mare,\nAcábate de guiyá.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,281,281,"4673","",0,"","","",1,0,0,[],""],["rm_t3-n4675",1,"Si la lengua te se seca\nCon aire de perlesía,\nNo l' eches la curpa á náide;\nQue son mardisiones mias.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,281,281,"4675","",0,"","","",1,0,0,[],""],["rm_t3-n4677",1,"Quisiera ser basilisco\nPor horas y por momentos,\nMatar á quien yo quisiera\nY descansara mi cuerpo.",1,0,-1,6,"",0,4,"eo",-1,0,-1,0,281,281,"4677","",0,"palau_cantares, frenk_t4","","",3,0,0,[],""],["rm_t3-n4678",1,"Mira si tengo rason\nPara peírte la bía,\nQu' estoy en un cuarto estrecho\nCurándome las jerías.",1,0,-1,6,"",0,4,"ia",-1,0,-1,0,281,281,"4678","",0,"","","",1,0,0,[],""],["rm_t3-n4679",1,"Ni las murayas de Séuta\nNi er peñon de Gibartá\nT' han de balé, compañera,\nComo sarga en libertá.",1,0,-1,6,"",0,4,"a",9,0,-1,0,282,282,"4679","",0,"","","",1,0,0,[],""],["rm_t3-n4680",1,"Sólo dos caminos tienes\nSi es que te quieres librar:\nÓ que te bayas de Cáis,\nÓ que te tires ar mar.",1,0,-1,6,"",0,4,"a",-1,0,-1,0,282,282,"4680","",0,"","","",1,0,0,[],""],["rm_t3-n4681",1,"Las piedras son, y se chocan\nEn la corriente del rio;\nPídele á Dios no encontrarte\nAlgun dia en mi camino.",1,0,-1,6,"",0,4,"io",-1,0,-1,0,282,282,"4681","",0,"frenk_t2","","",2,0,0,[],""],["rm_t3-n4682",1,"Si piensas que duermo, velo;\nY si te llego á coger,\nHemos de tener más guerra\nQue Francia con el Inglés.",1,0,-1,6,"",0,4,"e",-1,0,-1,0,282,282,"4682","",0,"","","",3,0,0,[],""],["rm_t3-n4684",1,"Tengo d' haser un castiyo\nDe car biba y argamasa\nY ayí tengo de meter\nTiempo, lugar y bengansa.",1,0,-1,6,"",0,4,"aa",-1,0,-1,0,282,282,"4684","",0,"","","",1,0,0,[],""],["rm_t3-n4685",1,"Yo le pedí tiempo ar tiempo\nY er tiempo me respondió\nQue con er tiempo tendria,\nTiempo, lugar y ocasion.",1,0,-1,6,"",0,4,"o",-1,0,-1,0,282,282,"4685","",0,"","","",1,0,0,[],""],["rm_t3-n4687",1,"Si en bía no me bengo,\nMe bengaré 'n muerte:\nComo andaré - toas las seporturas,\nJasta que t' encuentre.",1,0,-1,6,"",3,4,"ee",-1,0,-1,0,283,283,"4687","",0,"","","",1,0,0,[],""],["rm_t3-n4688",1,"Ar prinsipio de quererte\nEstaba siego y no bía;\nYa me se quitó la benda\nQu' en los ojiyos tenía.",1,0,-1,7,"",0,4,"ia",0,0,-1,0,292,292,"4688","",0,"","","",2,0,0,[],""],["rm_t3-n4689",1,"Que te quise cierto fué;\nQue te olvidé no es mentira;\nQue en los árboles la flor\nNo dura toda la vida.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,292,292,"4689","",0,"","","",3,0,0,[],""],["rm_t3-n4690",1,"Que te quise no lo niego;\nQue no te quiero es verdad;\nMira tus malas partidas\nA lo que han dado lugar.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,292,292,"4690","",0,"","","",2,0,0,[],""],["rm_t3-n4691",1,"Es verdad que te he querido;\nUna tontura es negarlo;\nMas para mí ya estás muerto;\nAunque vivieras cien años.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,292,292,"4691","",0,"","","",4,0,0,[],""],["rm_t3-n4692",1,"Es verdad que te he querido;\n¿Para qué lo he de negar?\nHoy si te canonizaran\nNo me acercaba á tu altar.",1,0,-1,7,"",0,4,"a",21,0,-1,0,292,293,"4692","",0,"","","",4,0,0,[],""],["rm_t3-n4693",1,"Verdad es que te quise;\nPero dijiste\nQue tú hablabas conmigo,\nPor divertirte.\nAhora te digo:\nPara las ocasiones\nSon los amigos.",1,0,-1,7,"",4,7,"io",-1,0,-1,0,293,293,"4693","",0,"","","",1,0,0,[],""],["rm_t3-n4694",1,"Me quisistes y te quise;\nMe olvidaste y te olvidé;\nLos dos tuvimos la culpa,\nTú primero y yo después.",1,0,-1,7,"",0,4,"e",-1,0,-1,0,293,293,"4694","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4695",1,"Me quisistes y te quise\nY agradecí tu fineza;\nMe olvidaste y te olvidé;\nTú contento y yo contenta.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,293,293,"4695","",0,"","","",4,0,0,[],""],["rm_t3-n4696",1,"Ya sabes que te he querido\nDos inviernos y un verano\nY ahora te vuelvo á decir\nQue al són que me tocan bailo.",1,0,-1,7,"",3,4,"ao",-1,0,-1,0,293,293,"4696","",0,"","","",2,0,0,[],""],["rm_t3-n4697",1,"Te quise y me quisiste\nPor vanagloria;\nEl volver yo á quererte\nPica en historia.\nVolver no quiero\nA emplear, que en tu renta\nPierdo el dinero.",1,0,-1,7,"",4,7,"eo",38,0,-1,0,293,293,"4697","",0,"","","",1,0,0,[],""],["rm_t3-n4698",1,"Desde chiquita te quise\nY te demostré mi afan,\nY ahora bienes á quererme,\nCuando no te quieo pâ nâ.",1,0,-1,7,"",3,4,"",-1,0,-1,0,294,294,"4698","",0,"","","",1,0,0,[],""],["rm_t3-n4699",1,"Yo no te quió á tí pâ nâ;\nTe bienes jasiendo grande,\nY eres la piedra más chica\nQue yo trompieso en la caye.",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,294,294,"4699","",0,"","","",2,0,0,[],""],["rm_t3-n4700",1,"Es verdad que puse en tí\nAmor firme y me olvidaste;\nQue yo te olvidé por otro;\n¡Claro está! tú me enseñaste.",1,0,-1,7,"",0,4,"ae",212,0,-1,0,294,294,"4700","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t3-n4701",1,"Una nobia tube yo\nQu' habia pensao dejarme;\nYo le partí er pan con tiempo,\nÁntes que le diera jambre.",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,294,294,"4701","",0,"","","",1,0,0,[],""],["rm_t3-n4702",1,"En la cara te conozco\nQue me quieres olvidar;\nEn el padrenuestro dice:\n«Hágase tu voluntad.»",1,0,-1,7,"",0,4,"a",-1,0,-1,0,294,294,"4702","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t3-n4703",1,"Me han dicho que no me quieres;\nBien sabe Dios que me alegro:\nSoy de un natural tan dócil,\nQue lo que tú quieres quiero.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,294,294,"4703","",0,"","","",3,0,0,[],""],["rm_t3-n4704",1,"Porque tú á mí me dejes\nNo tengo queja;\nPorque en dejar no has sido\nTú la primera.\nMas, por si acaso,\nPor no perder de postre,\nGano de mano.",1,0,-1,7,"",4,7,"ao",-1,0,-1,0,294,295,"4704","",0,"","","",1,0,0,[],""],["rm_t3-n4707",1,"No digas que me has dejao,\nPorque te diré que mientes;\nEl que te dejó fuí yo,\nQue no quise más quererte.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,295,295,"4707","",0,"","","",1,0,0,[],""],["rm_t3-n4708",1,"Te pones por las esquinas\nA desir que m' has dejao;\nBien sabe Dios y tô 'r mundo\nQue lo dises de quemao.",1,0,-1,7,"",0,4,"ao",98,0,-1,0,295,295,"4708","",0,"","","",5,0,0,[],""],["rm_t3-n4711",1,"Mi amante es un cobarde,\nQue no se atreve\nA decirme en mi cara\nQue no me quiere.\nYo sí me atrevo\nA decirle en la suya\nQue no lo quiero.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,296,296,"4711","",0,"","","",2,0,0,[],""],["rm_t3-n4712",1,"¿De qué te sirve que andes\nCalle arriba, calle abajo,\nSi sabes que no te quiero,\nGrandísimo porfiado?",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,296,296,"4712","",0,"","","",4,0,0,[],""],["rm_t3-n4713",1,"Deja de escandalizar\nLa calle con tus paseos;\nQue los suspiros que das\nNi los oigo ni los creo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,296,296,"4713","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4714",1,"Amor mio, te olvide;\nA lo hecho no hay remedio;\nArrepentido no estoy:\nBusca quien te dé consuelo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,296,296,"4714","",0,"","","",1,0,0,[],""],["rm_t3-n4715",1,"Si quieres que te lo diga,\nCantando te lo diré:\nEl amor que te tenía\nPor donde vino se fué.",1,0,-1,7,"",0,4,"e",77,0,-1,0,296,296,"4715","",0,"","","",9,0,0,[],""],["rm_t3-n4716",1,"Er queré que te tenía\nEra poco y me se fué;\nY como bino San Juan,\nA otra parte lo mudé.",1,0,-1,7,"",0,4,"e",77,0,-1,0,296,297,"4716","",0,"","","",1,0,0,[],""],["rm_t3-n4717",1,"El querer que te tenía\nLo metí en un agujero;\nY así que llegó el verano,\nLas chinches se lo comieron.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,297,297,"4717","",0,"","","",4,0,0,[],""],["rm_t3-n4718",1,"El amor que te tuve\nFué de bayeta;\nSe le ha caido el pelo;\nYa no calienta.",1,0,-1,7,"",6,4,"ea",-1,0,-1,0,297,297,"4718","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4719",1,"El amor que te tengo\nY el que me tienes,\nPuestos en la balanza,\nNi van ni vienen.",1,0,-1,7,"",6,4,"ee",-1,0,-1,0,297,297,"4719","",0,"palau_cantares","","",10,0,0,[],""],["rm_t3-n4720",1,"Hice un castillo de plumas\nY el aire se lo llevó;\nEl amor que te tenía\nEra poco y se acabó.",1,0,-1,7,"",0,4,"o",2,0,-1,0,297,297,"4720","",0,"","","",1,0,0,[],""],["rm_t3-n4721",1,"Yo te quise por er tiempo\nDe las castañas cosías;\nS' acabaron las castañas,\nY combersasion perdía.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,297,297,"4721","",0,"","","",1,0,0,[],""],["rm_t3-n4722",1,"No digas que yo te quise,\nNi digas que m' has querío;\nDí que fué un capricho sólo\nQue los dos hemos tenío.",1,0,-1,7,"",0,4,"io",3,0,-1,0,297,297,"4722","",0,"","","",1,0,0,[],""],["rm_t3-n4723",1,"Si dije que te quería,\nCabayero, en otro tiempo,\nEran mis ojos muy niños,\nFartos de conosimiento.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,298,298,"4723","",0,"","","",3,0,0,[],""],["rm_t3-n4724",1,"Me causó tu mudanza\nGran pesadumbre:\nAntes ardió mi pecho;\nYa no da lumbre.\nPues me abrasaba\nY se han vuelto cenizas\nAquellas ascuas.",1,0,-1,7,"",4,7,"aa",-1,0,-1,0,298,298,"4724","",0,"","","",1,0,0,[],""],["rm_t3-n4725",1,"Algun día te quise,\nPorque no supe\nDel pié que cojeabas\nNi tus embustes.\nMas ya te entiendo;\nNo serás tú la maula\nQue me dé celos.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,298,298,"4725","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4726",1,"Algun dia lloraba\nTus esquiveces;\nHoy de que otros las lloren\nEstoy alegre.\nQue en este mundo\nSuelen llorar los otros\nSi rien unos.",1,0,-1,7,"",4,7,"uo",-1,0,-1,0,298,298,"4726","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4727",1,"Algun dia sentia\nTus esquiveces\nY hoy me son tus finezas\nIndiferentes.\nDe esta mudanza\nPregúntate á tí misma\nCuál es la causa.",1,0,-1,7,"",4,7,"aa",-1,0,-1,0,298,299,"4727","",0,"","","",3,0,0,[],""],["rm_t3-n4728",1,"Cuando yo más te quería\nEra mi deseo el verte,\nY ahora me da lo mismo\nEl verte como el no verte.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,299,299,"4728","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t3-n4729",1,"Algun dia, santito,\nFuí tu devota,\nY ahora por Dios te pido\nQue busques otra.",1,0,-1,7,"",3,4,"oa",-1,0,-1,0,299,299,"4729","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t3-n4730",1,"Algun dia yo por tí\nLagrimitas derramé;\nMira lo que el tiempo hace,\nQue ya no te puedo ver.",1,0,-1,7,"",0,4,"e",-1,0,-1,0,299,299,"4730","",0,"","","",1,0,0,[],""],["rm_t3-n4731",1,"Otras beses, compañera,\nPasaba ducas por tí;\nPero y' ha yegaíto er tiempo\nQue tú las pases por mí.",1,0,-1,7,"",3,4,"i",23,0,-1,0,299,299,"4731","",0,"","","",1,0,0,[],""],["rm_t3-n4732",1,"Por mirarte algun dia\nSuspiros daba,\nY ahora por no mirarte\nVuelvo la cara.",1,0,-1,7,"",3,4,"aa",-1,0,-1,0,299,299,"4732","",0,"","","",2,0,0,[],""],["rm_t3-n4733",1,"Ya se acabó aquel tiempo\n¡Todo se acaba!\nQue sólo con mirarte\nMe alimentaba.",1,0,-1,7,"",6,4,"aa",28,0,-1,0,299,299,"4733","",0,"palau_cantares, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n4734",1,"Argun dia eran tus ojos\nAlegrías para mí,\nY ahora son las arcayatas\nDonde cuergo yo er candí.",1,0,-1,7,"",3,4,"i",23,0,-1,0,299,300,"4734","",0,"","","",1,0,0,[],""],["rm_t3-n4735",1,"No sé qué estreya reinaba\nEn er tiempo que te quise,\nQue yo estaba alililao\nY no supe lo quejise.",1,0,-1,7,"",0,4,"ie",224,0,-1,0,300,300,"4735","",0,"","","",1,0,0,[],""],["rm_t3-n4736",1,"Er quererte fué un antojo\nY el hablarte fantesía;\nY el orbidarte fué un gusto,\nPorque yo no te queria.",1,0,-1,7,"",0,4,"ia",0,0,-1,0,300,300,"4736","",0,"","","",1,0,0,[],""],["rm_t3-n4739",1,"¿Qué cuidado me da á mí\nQue pases y no me hables,\nSi sabes que yo no como\nCon buenos dias de nádie?",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,300,300,"4739","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4740",1,"¿Qué cuidado le da al rey\nDe que se muera un soldado?\n¿Qué cuidado me da á mí\nDe que me hayas olvidado?",1,0,-1,7,"",0,4,"ao",14,0,-1,0,300,300,"4740","",0,"","","",3,0,0,[],""],["rm_t3-n4741",1,"Tú te tienes por que sabes\nY er sabé no t' ha balío:\nYo he jecho burla de tí\nY tú no l' has conosío.",1,0,-1,7,"",0,4,"io",3,0,-1,0,300,300,"4741","",0,"","","",1,0,0,[],""],["rm_t3-n4743",1,"Ya he lograíyo mi gusto,\nQu' era lo que yo quería;\n¿Qué cuidiao me da á mí\nQue jagas chungas partías?",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,301,301,"4743","",0,"","","",1,0,0,[],""],["rm_t3-n4744",1,"De noche me sargo ar patio\nY me jarto de reí,\nEn ber que me quieres tanto\nY yo no te quiero á tí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,301,301,"4744","",0,"","","",3,0,0,[],""],["rm_t3-n4745",1,"El dia que tú te fuiste\nFué tan grande mi dolor....\nQue me comí dos gallinas\nY tres libras de jamon.",1,0,-1,7,"",5,4,"ao",-1,0,-1,0,301,301,"4745","",0,"","","",1,0,0,[],""],["rm_t3-n4747",1,"Las fatigas d' un senacho\nQuo lo güerben der rebés,\nEsas mismas paso yo\nCuando m' acuerdo d' usté.",1,0,-1,7,"",0,4,"e",-1,0,-1,0,301,301,"4747","",0,"","","",1,0,0,[],""],["rm_t3-n4748",1,"Cuando me dieron la nueba\nDe que tú no me querias,\nA la mar no me tiré....\nPorque 'staba el agua fria.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,301,301,"4748","",0,"","","",3,0,0,[],""],["rm_t3-n4749",1,"Cuando me dieron la nueba\nDe que tú no me querias,\nLa cara me se queó...\nDonde mismo la tenía.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,301,302,"4749","",0,"","","",3,0,0,[],""],["rm_t3-n4750",1,"Cuando me dieron la nueba\nDe que tú no me querias,\nJasta 'r gato de mi casa\nMe miraba y se reia.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,302,302,"4750","",0,"","","",3,0,0,[],""],["rm_t3-n4751",1,"Yo t' estoy queriendo á tí,\nPorque otra cosa no encuentro;\nQue si otra cosa encontrara,\nFueras tú mi pasatiempo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,302,302,"4751","",0,"","","",4,0,0,[],""],["rm_t3-n4752",1,"¡Nada! lo dicho está dicho:\nDe mí no tengas reselo;\nQue me tienes tan seguro....\nComo el agua en un jarnero.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,302,302,"4752","",0,"","","",1,0,0,[],""],["rm_t3-n4753",1,"Gitaniya, gitaniya,\nDe mí no tengas cudiao;\nQue me tienes tan seguro....\nComo el agua en un tejao.",1,0,-1,7,"",0,4,"ao",98,0,-1,0,302,302,"4753","",0,"","","",1,0,0,[],""],["rm_t3-n4754",1,"Amor mio, come y bebe;\nDe mí no tengas sospecha;\nQue me tienes tan segura....\nComo el agua en una cesta.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,302,302,"4754","",0,"","","",3,0,0,[],""],["rm_t3-n4755",1,"Supuesto que no quieres\nNada conmigo,\nCuando te pareciere\nToma el camino.",1,0,-1,7,"",6,4,"io",-1,0,-1,0,302,302,"4755","",0,"fernan_caballero, palau_cantares","","",3,0,0,[],""],["rm_t3-n4757",1,"Para despedir á un hombre\nNo es menester mala cara;\nSino con buenas razones,\n«Váyase usté noramala.» 2",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,303,303,"4757","",0,"","","",3,0,0,[],""],["rm_t3-n4758",1,"Para despedir á un hombre\nNo es menester josiquito;\nSino con buenas rasones,\n«Yo no quiero á usté, mosito.»",1,0,-1,7,"",0,4,"io",119,0,-1,0,303,303,"4758","",0,"","","",3,0,0,[],""],["rm_t3-n4759",1,"Es tanto lo que te quiero,\nTanto el amor que me abrasa,\nQue te quisiera tener\nA cien leguas de distancia.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,303,303,"4759","",0,"carrizo_salta","","",26,0,0,[],""],["rm_t3-n4762",1,"Anda véte, anda véte,\nBarbero loco;\nQue mi madre no quiere\nNi yo tampoco.",1,0,-1,7,"",6,4,"oo",152,0,-1,0,303,303,"4762","",0,"fernan_caballero","","",6,0,0,[],""],["rm_t3-n4763",1,"Anda béte, que no quiero\nContigo más amistá;\nQue ties palabras e santo\nY partías e charran.",1,0,-1,7,"",5,4,"aa",-1,0,-1,0,303,303,"4763","",0,"","","",4,0,0,[],""],["rm_t3-n4764",1,"Anda béte, que no quiero\nContigo combersasion;\nLa que he tenido me pesa\nDentro de mi corason.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,303,304,"4764","",0,"","","",4,0,0,[],""],["rm_t3-n4765",1,"Yo no quiero más pan tuyo,\nQue me amarga la cortesa,\nNi combersasion contigo:\nLa qu' he tenío me pesa.",1,0,-1,7,"",0,4,"ea",201,0,-1,0,304,304,"4765","",0,"","","",1,0,0,[],""],["rm_t3-n4766",1,"Anda béte, corre béte,\nQue ya me se fué 'l amó;\nQuien s' ha comío la yema\nQue se coma er cascaron.",1,0,-1,7,"",5,4,"ao",-1,0,-1,0,304,304,"4766","",0,"","","",1,0,0,[],""],["rm_t3-n4767",1,"Anda, que ya no te quiero,\nQue ya se me fué el amor;\nYa te barrí con la escoba\nDentro de mi corazon.",1,0,-1,7,"",0,4,"o",-1,0,-1,0,304,304,"4767","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t3-n4768",1,"Anda, que ya no te quiero,\nQue ya se me fué el amor:\nAnda, picarillo tonto,\nLlama al demonio mayor.",1,0,-1,7,"",0,4,"o",72,0,-1,0,304,304,"4768","",0,"","","",6,0,0,[],""],["rm_t3-n4769",1,"Anda véte, ó no te vayas,\nQue ya se me fué el querer;\nAnda, picarillo tonto,\nA engañar á otra mujer.",1,0,-1,7,"",0,4,"e",20,0,-1,0,304,304,"4769","",0,"","","",1,0,0,[],""],["rm_t3-n4770",1,"Anda, que ya no te quiero;\nAnda, que ya no te amo;\nDonde has pasado el invierno\nPasa tambien el verano.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,304,304,"4770","",0,"","","",6,0,0,[],""],["rm_t3-n4777",1,"Anda, que no te quiero;\nQue eres del arte;\nQue si no bebes vino,\nJuegas al naipe.",1,0,-1,7,"",6,4,"ae",-1,0,-1,0,305,305,"4777","",0,"","","",4,0,0,[],""],["rm_t3-n4778",1,"Anda, que no te quiero;\nQue estás besada....\nQue te besó tu madre\nCuando mamabas.",1,0,-1,7,"",6,4,"aa",-1,0,-1,0,305,305,"4778","",0,"rm_t4","","",4,0,0,[],""],["rm_t3-n4780",1,"He sabido ya quién eres;\nConque cesen mis pesares;\nDe mi devocion no esperes\nMás incienso en tus altares.",1,0,-1,7,"",1,4,"ae",164,0,-1,0,306,306,"4780","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n4782",1,"¡Anda con mil demonios!\nQue no hay paciencia\nQue pueda sufrir tantas\nImpertinencias.\n¡Cuerno contigo!\n¿Has pensado tú acaso\nJugar conmigo?",1,0,-1,7,"",4,7,"io",106,0,-1,0,306,306,"4782","",0,"","","",1,0,0,[],""],["rm_t3-n4783",1,"Llámame como quieras;\nLlámame ingrato;\nPero déjame libre\nDe tus enfados.\nPues lo que quiero\nEs no volver á verte,\nNi áun desde léjos.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,306,306,"4783","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4784",1,"Acaba de partir nueces\nY echa las piedras al rio;\nQue lo que ha sido y no es,\nComo si no hubiera sido.",1,0,-1,7,"",0,4,"io",-1,0,-1,0,306,306,"4784","",0,"","","",3,0,0,[],""],["rm_t3-n4785",1,"Ya no me queman á mi\nLas llamas de tu candela;\nQue lo que ha sido y no es,\nComo si en la vida fuera.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,306,306,"4785","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4786",1,"Satisfacciones me pides,\nY no te las quiero dar;\nQue darte satisfacciones\nEs volver á tu amistad.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,307,307,"4786","",0,"","","",4,0,0,[],""],["rm_t3-n4787",1,"Todas las mañanas voy\nA misa á San Agustin,\nA darle gracias al santo\nQue me ha librado de tí.",1,0,-1,7,"",0,4,"i",-1,0,-1,0,307,307,"4787","",0,"palau_cantares, lafuente_madrid","","",12,0,0,[],""],["rm_t3-n4789",1,"Ya te se acabó la mina\nQue tanto te producía;\nYa te se acabó el orgullo\nQue tú conmigo tenías.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,307,307,"4789","",0,"","","",1,0,0,[],""],["rm_t3-n4790",1,"Yo tengo sal, aunque poca;\nPero has de saber y escucha:\nQue la gasto con quien quiero;\nCon personas que me gustan.",1,0,-1,7,"",0,4,"ua",-1,0,-1,0,307,307,"4790","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4792",1,"No quiero comer contigo\nGallinas ni pavos reales;\nQuiero pan de municion\nCon personas naturales.",1,0,-1,7,"",0,4,"ae",26,0,-1,0,307,308,"4792","",0,"","","",3,0,0,[],""],["rm_t3-n4793",1,"Te pones por las esquinas\nÁ publicar que te quiero,\n¡Y hasta el santo de tu nombre\nAborrecido lo tengo!",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,308,308,"4793","",0,"","","",5,0,0,[],""],["rm_t3-n4794",1,"Aunque el rey te coronara,\nYa sabes que no te quiero:\nLo que nos pasa á los dos\nLo vas pregonando luégo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,308,308,"4794","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4795",1,"De San Juan quiero la parma\nY de San Diego la crus;\nY der santo de tu nombre\nNi tampoco la salú.",1,0,-1,7,"",0,4,"u",-1,0,-1,0,308,308,"4795","",0,"","","",1,0,0,[],""],["rm_t3-n4799",1,"El clavel que me diste\nLo tiré al pozo;\nYo no quiero claveles\nDe ningun mozo.\nLo que me pesa\nEs que lo tuve un rato\nEn la cabeza.",1,0,-1,7,"",4,7,"ea",108,0,-1,0,308,309,"4799","",0,"","","",3,0,0,[],""],["rm_t3-n4800",1,"Del clavel que me distes\nAnacarado,\nToma allá las cenizas,\nQue lo he quemado.",1,0,-1,7,"",6,4,"ao",14,0,-1,0,309,309,"4800","",0,"","","",2,0,0,[],""],["rm_t3-n4801",1,"No tengo nada tuyo;\nQue si tuviera,\nA la lumbre lo echara,\nPara que ardiera.",1,0,-1,7,"",6,4,"ea",44,0,-1,0,309,309,"4801","",0,"","","",2,0,0,[],""],["rm_t3-n4802",1,"Aunque tu padre me dé\nUn arca yena de ropa,\nNo m' he casar contigo,\nPorque te jiede la boca.",1,0,-1,7,"",0,4,"oa",-1,0,-1,0,309,309,"4802","",0,"","","",2,0,0,[],""],["rm_t3-n4803",1,"Aunque tu padre me diera\nLa mula y el carreton,\nNo me he casar contigo,\nPor tu mala condicion.",1,0,-1,7,"",0,4,"o",-1,0,-1,0,309,309,"4803","",0,"","","",7,0,0,[],""],["rm_t3-n4805",1,"Aunque tu padre me dé\nLa carreta y el buey cojo,\nNo te tengo de querer,\nPorque eres tuerta de un ojo\n[Y con el otro no ves].",1,0,-1,7,"",7,5,"e",-1,0,-1,0,309,309,"4805","",0,"","","",2,0,0,[],""],["rm_t3-n4806",1,"Si mi madre me manda\nQue yo te dé el sí,\nPuesto que ella te quiere,\nCásese por mí.\nQue yo no quiero\nBuscar para mí mueble\nPor gusto ajeno.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,310,310,"4806","",0,"","","",1,0,0,[],""],["rm_t3-n4807",1,"Mi madre me aconseja\nQue yo te ame;.\nY yo que no me gustas\nDigo á mi madre.\nQue es fuerte empeño\nEl querer que yo quiera\nLo que no quiero.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,310,310,"4807","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4808",1,"La flor de la calabaza\nEs una maldita flor,\nQue se la dan á los hombres\nEn la mejor ocasion.",1,0,-1,7,"",0,4,"o",-1,0,-1,0,310,310,"4808","",0,"","","",3,0,0,[],""],["rm_t3-n4809",1,"Toda la calle á lo largo\nLa he sembrado de melones;\nMe han salido calabazas,\nPara darlas á los hombres.",1,0,-1,7,"",0,4,"oe",-1,0,-1,0,310,310,"4809","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4810",1,"Las calabazas de Mayo\nDicen que son las tempranas,\nY yo se las dí á mi amante\nEn Abril una mañana.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,310,310,"4810","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4811",1,"Mi padre y mi madre son\nLos dueños de mi persona;\nSi te he dado calabazas,\nAmante mio, perdona.",1,0,-1,7,"",0,4,"oa",7,0,-1,0,310,310,"4811","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t3-n4812",1,"A todos les da claveles\nLa morena de la plaza;\nA todos les da claveles,\nY á mí me da calabazas.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,311,311,"4812","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4814",1,"Me han dicho que estás sembrando\nCalabazas para mí;\nYa las tengo yo con flores:\nAdelanto te cogí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,311,311,"4814","",0,"","","",2,0,0,[],""],["rm_t3-n4815",1,"Dicen que te has alabado\nQue me diste calabazas;\nYo tambien me alabaré\nQue me las comí en tu casa.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,311,311,"4815","",0,"","","",2,0,0,[],""],["rm_t3-n4816",1,"Si me distes calabazas,\nMe las comí con pan tierno;\nMejor quiero calabazas\nQue una mujer sin gobierno.",1,0,-1,7,"",1,4,"eo",225,0,-1,0,311,311,"4816","",0,"","","",3,0,0,[],""],["rm_t3-n4817",1,"Si me distes calabazas,\nMe las comí con tocino:\nMejor quiero calabazas\nQue nó casarme contigo.",1,0,-1,7,"",0,4,"io",-1,0,-1,0,311,311,"4817","",0,"","","",3,0,0,[],""],["rm_t3-n4818",1,"Si me distes calabazas,\nMe las comí con vinagre;\nPero los besos y abrazos,\nQue te los quite tu madre.",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,311,311,"4818","",0,"","","",3,0,0,[],""],["rm_t3-n4819",1,"Tienes el amor trompero,\nComo se suele decir;\n«Cuantas veo, cuantas quiero;»\nNo me engañarás á mí.",1,0,-1,7,"",0,4,"i",-1,0,-1,0,312,312,"4819","",0,"","","",2,0,0,[],""],["rm_t3-n4820",1,"No quiero prenda con dueño,\nQue me la quiten mañana;\nQuiero prenda que me dure\nEl tiempo que me dé gana.",1,0,-1,7,"",0,4,"aa",4,0,-1,0,312,312,"4820","",0,"","","",3,0,0,[],""],["rm_t3-n4821",1,"Hay galan que pretende\nTener dos damas\nY luégo al fin se queda\nTocando tablas.\nY tú el primero\nTe quedastes tocando\nTabla y tablero.",1,0,-1,7,"",4,7,"eo",38,0,-1,0,312,312,"4821","",0,"","","",1,0,0,[],""],["rm_t3-n4822",1,"Yo te quise no pensando\nQue tenías otro dueño;\nTú juegas con dos barajas\nY aunque me envidas, no quiero.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,312,312,"4822","",0,"","","",5,0,0,[],""],["rm_t3-n4823",1,"Nada de cuanto digas\nQuiero creerte;\nQue una vez engañado\nLo seré siempre.\nLlama á otra puerta,\nPorque la de mi casa\nCerrada queda.",1,0,-1,7,"",4,7,"ea",-1,0,-1,0,312,312,"4823","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4824",1,"Poco me importan á mí\nTu amor ó tu malquerencia,\nPorque el que está sin pecado\nNo teme la penitencia.",1,0,-1,7,"",0,4,"ea",46,0,-1,0,312,312,"4824","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4826",1,"Si vienes, bien te recibo;\nY si no, no me haces falta;\nHas de saber, dueño mio,\nQue yo no contemplo gaitas.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,313,313,"4826","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4827",1,"Si no me correspondes,\nNo correspondo;\nMala cara me pones,\nMala te pongo.\nCon tal despego,\nQue si tú me la pegas,\nYo te la pego.",1,0,-1,7,"",4,7,"eo",29,0,-1,0,313,313,"4827","",0,"","","",2,0,0,[],""],["rm_t3-n4828",1,"¡Qué bien te habrás divertido\nEn el tiempo de mi ausencia!\nYo tambien hice lo mismo,\nPor descargar tu conciencia.",1,0,-1,7,"",0,4,"ea",46,0,-1,0,313,313,"4828","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n4829",1,"Si por que yo te quiero\nTú te imaginas\nQue has de jugar conmigo,\n¡Naranjas chinas!\nNo hay que dudarlo,\nPorque tú muy bien sabes\nQue soy naranjo.",1,0,-1,7,"",4,7,"ao",-1,0,-1,0,313,313,"4829","",0,"","","",1,0,0,[],""],["rm_t3-n4830",1,"De mirarte me abstengo,\nPorque no digas\nQue por que estás sin velo,\nTodos te miran.\nSi no me abstengo,\nSerá para mirarte\nCon más desprecio.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,313,314,"4830","",0,"","","",1,0,0,[],""],["rm_t3-n4831",1,"El que corta una rama\nY la raíz deja,\nEs señal que pretende\nVolver por ella.\nYo no soy así:\nCuando corto la rama,\nCorto la raíz.",1,0,-1,7,"",4,7,"i",-1,0,-1,0,314,314,"4831","",0,"","","",1,0,0,[],""],["rm_t3-n4832",1,"Dicen que no me quieres;\nYa me has querido:\nVáyase lo ganado\nPor lo perdido.",1,0,-1,7,"",6,4,"io",101,0,-1,0,314,314,"4832","",0,"huambachano, palau_cantares","","",18,0,0,[],""],["rm_t3-n4833",1,"Dicen que no me quieres;\nNo me quieras, nó:\nDonde no hay escritura\nNo hay obligacion.",1,0,-1,7,"",6,4,"ao",-1,0,-1,0,314,314,"4833","",0,"fernan_caballero","","",18,0,0,[],""],["rm_t3-n4835",1,"Dicen que tú no me quieres,\nAunque doblones me sobran;\nLos doblones son doblones\nAquí y en Constantinopla.",1,0,-1,7,"",3,4,"oa",-1,0,-1,0,314,314,"4835","",0,"lafuente_madrid","","",11,0,0,[],""],["rm_t3-n4836",1,"Imposible parece\nQue no me quieras,\nCuando me huele á oro\nLa faltriquera.",1,0,-1,7,"",6,4,"ea",-1,0,-1,0,314,315,"4836","",0,"","","",1,0,0,[],""],["rm_t3-n4837",1,"Las pérdidas que yo tenga,\nComo sean por tu causa,\nBien sabe Dios y tó 'r mundo\nQue para mí son ganansias.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,315,315,"4837","",0,"","","",1,0,0,[],""],["rm_t3-n4839",1,"Piensas tú ser muy diestra;\nMas muchas veces\nSacas caña y anzuelo,\nPero sin peces.\nY ciertamente\nNo faltará sujeto\nQue á tí te pesque.",1,0,-1,7,"",4,7,"ee",-1,0,-1,0,315,315,"4839","",0,"","","",1,0,0,[],""],["rm_t3-n4840",1,"Échale trigo á la era\nY á mí no me solicites;\nQue en otra puedes poner\nEl amor que en mí pusistes.",1,0,-1,7,"",0,4,"ie",-1,0,-1,0,315,315,"4840","",0,"","","",4,0,0,[],""],["rm_t3-n4841",1,"Nunca mi pensamiento\nEn tí lo puse,\nPorque te hallé sujeto\nDe pocas luces.\nY yo no quiero\nEn cabeza ligera\nMi pensamiento.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,315,315,"4841","",0,"","","",1,0,0,[],""],["rm_t3-n4842",1,"Sentío bienen bendiendo;\nTu madre que te lo compre;\nQue te jase tanta farta\nComo á una puerta los gonses.",1,0,-1,7,"",0,4,"oe",-1,0,-1,0,316,316,"4842","",0,"","","",1,0,0,[],""],["rm_t3-n4843",1,"Estrella, tú te estrellas\nEn perseguirme;\nNo has de ser tú la estrella\nQue ha de seguirme.\nQue en tal querella,\nTemo que me persiga\nLa mala estrella.",1,0,-1,7,"",4,7,"ea",6,0,-1,0,316,316,"4843","",0,"","","",1,0,0,[],""],["rm_t3-n4844",1,"Tú dices que yo tengo\nCondicion fiera;\nCreo que te pagara\nSi te debiera.\nTe satisfago:\nComo nada te debo,\nNada te pago.",1,0,-1,7,"",4,7,"ao",207,0,-1,0,316,316,"4844","",0,"","","",1,0,0,[],""],["rm_t3-n4845",1,"Tú quieres muchas gachas;\nYo no sé hacerlas;\nAnda y busca una mona\nQue te entretenga.\nY si te afufas,\nTe advierto que en Valencia\nVenden cotufas.",1,0,-1,7,"",4,7,"ua",226,0,-1,0,316,316,"4845","",0,"","","",1,0,0,[],""],["rm_t3-n4846",1,"Para que veas quien soy,\nMemoria no hago de tí,\nNi me acuerdo de tu nombre,\nNi sé si te conocí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,316,317,"4846","",0,"","","",1,0,0,[],""],["rm_t3-n4847",1,"Grandes fatigas pasé\nCuando te estuve olvidando;\nAsí que lo conseguí\nDe contento no me hallo.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,317,317,"4847","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4848",1,"Si pasares por mi casa\nY allí no estuviere yo,\nConténtate con la jaula,\nQue ya el pájaro voló.",1,0,-1,7,"",0,4,"o",2,0,-1,0,317,317,"4848","",0,"","","",1,0,0,[],""],["rm_t3-n4849",1,"Coge la rama de un roble\nY tírala á mi tejado;\nCuando la rama críe flores,\nTe daré entónces la mano.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,317,317,"4849","",0,"","","",3,0,0,[],""],["rm_t3-n4850",1,"Si la ocasion se presenta\nDe verte en alguna parte,\nTe he de volver las espaldas;\nMe he de marchar sin hablarte.",1,0,-1,7,"",0,4,"ae",8,0,-1,0,317,317,"4850","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4851",1,"Er mengue m' está tentando\nPâ que te baya á buscá;\nUndebé puê más qu' er mengue\nY ese gusto no tendrás.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,317,317,"4851","",0,"","","",1,0,0,[],""],["rm_t3-n4852",1,"Por cositas que me jagas\nNo me s' arborota er pecho:\nLas cosas s' han de tomar\nConforme son los sujetos.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,317,317,"4852","",0,"","","",1,0,0,[],""],["rm_t3-n4853",1,"Si yo tuviera un novio\nQue me celara,\nPor éstas que son cruces\nQue lo dejaba.\nTú me has celado;\nPor éstas que son cruces\nQue te he dejado.",1,0,-1,7,"",4,7,"ao",14,0,-1,0,317,318,"4853","",0,"","","",1,0,0,[],""],["rm_t3-n4855",1,"Recuerdo que fuí tu novia;\nTe casaste y nó conmigo.\nTú cuando me encuentras, lloras;\nYo si te encuentro, me rio.",1,0,-1,7,"",0,4,"io",-1,0,-1,0,318,318,"4855","",0,"","","",2,0,0,[],""],["rm_t3-n4856",1,"Tu genio impertinente\nSe me resiste;\nYo no sé quién aguante\nSiempre á una chinche.\nPorque mi genio\nPrefiere á lluvias mansas\nUn aguacero.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,318,318,"4856","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4857",1,"Oyendo falsedades\nVine á quererte;\nPero has dado, amiguita,\nCon quien te entiende.\n¡Ay, que no es nada!\n¡Con lo que se nos viene\nLa buena maula!",1,0,-1,7,"",4,7,"aa",-1,0,-1,0,318,318,"4857","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4858",1,"Todas las noches vienes\nA verme un rato:\nAl que no quiere coles,\nLlenarle el plato.",1,0,-1,7,"",6,4,"ao",19,0,-1,0,318,319,"4858","",0,"","","",1,0,0,[],""],["rm_t3-n4859",1,"El candil se está apagando;\nLa alcuza no tiene aceite...\nNo te digo que te vayas,\nNi te digo que te quedes.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,319,319,"4859","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n4860",1,"Pensabas tú que tenías\nEl pájaro de la cola,\nY luégo que se te ha ido\nTe has quedado como boba.",1,0,-1,7,"",0,4,"oa",-1,0,-1,0,319,319,"4860","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4861",1,"En la fuente del amor\nSembré yo una esparraguera;\nY tan to creciendo fué\nQue por poco me la seca.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,319,319,"4861","",0,"","","",1,0,0,[],""],["rm_t3-n4862",1,"¿De qué te sirve llorar\nY dar voces como un loco,\nSi sabes que soy mujer\nY te he de olvidar por otro?",1,0,-1,7,"",0,4,"oo",-1,0,-1,0,319,319,"4862","",0,"","","",6,0,0,[],""],["rm_t3-n4863",1,"Una rosa tengo en agua\nY la tengo pará Juan;\nOtra tengo para Pepe;\nPara Antonio, rejalgar.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,319,319,"4863","",0,"","","",3,0,0,[],""],["rm_t3-n4864",1,"San Antonio me perdone\nPor lo que voy á decir:\nQue ninguno de su nombre\nNunca me ha gustado á mí.",1,0,-1,7,"",0,4,"i",-1,0,-1,0,319,319,"4864","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4865",1,"Camaraíta del arma,\nUsté no sabe queré:\nLas mujeres se manejan\nCon la puntiya der pié.",1,0,-1,7,"",0,4,"e",77,0,-1,0,319,320,"4865","",0,"","","",1,0,0,[],""],["rm_t3-n4866",1,"Dices que me quieres mucho\nY que te mueres por mí:\nMuérete, que yo lo vea,\nY entónces diré que sí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,320,320,"4866","",0,"","","",13,0,0,[],""],["rm_t3-n4867",1,"Un oficial muy fino\nMe dijo un dia\nQue si yo no le amaba,\nSe moriria.\nPero es lo cierto\nQue yo no lo he querido,\nY él no se ha muerto.",1,0,-1,7,"",4,7,"eo",88,0,-1,0,320,320,"4867","",0,"","","",2,0,0,[],""],["rm_t3-n4869",1,"Esta serrana está loca;\nQuiere que la quiera yo;\nQue la quiera su marío,\nQue tiene la obligasion.",1,0,-1,7,"",5,4,"ao",-1,0,-1,0,320,320,"4869","",0,"","","",3,0,0,[],""],["rm_t3-n4870",1,"Esta serrana está loca,\nY está día der sentío;\nQue quiere que yo le pague\nEr tiempo que m' ha querío.",1,0,-1,7,"",0,4,"io",3,0,-1,0,320,320,"4870","",0,"","","",3,0,0,[],""],["rm_t3-n4871",1,"Esta serrana está loca,\nLoca, que la ban á atar;\nQue lo qu' ensueña de noche\nQuiere que sarga berdá.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,320,320,"4871","",0,"","","",3,0,0,[],""],["rm_t3-n4872",1,"Esta noche he soñado\nQue te queria;\nEn mi vida he soñado\nMayor mentira.",1,0,-1,7,"",6,4,"ia",-1,0,-1,0,321,321,"4872","",0,"","","",2,0,0,[],""],["rm_t3-n4874",1,"A Sevilla me he de ir\nA querer á un sevillano;\nQue los mozos de esta tierra,\nMucha paja y poco grano.",1,0,-1,7,"",0,4,"ao",81,0,-1,0,321,321,"4874","",0,"","","",2,0,0,[],""],["rm_t3-n4875",1,"A la Sierra me he de ir\nA querer á una morena;\nQue las chicas de este pueblo\nNinguna me da ya pena.",1,0,-1,7,"",0,4,"ea",59,0,-1,0,321,321,"4875","",0,"","","",4,0,0,[],""],["rm_t3-n4877",1,"Yo me enamoré de noche\nY la luna me engañó;\nOtra vez que me enamore,\nSerá de dia y con sol.",1,0,-1,7,"",0,4,"o",-1,0,-1,0,321,321,"4877","",0,"palau_cantares, frenk_t2, fernan_caballero","","",9,0,0,[],""],["rm_t3-n4878",1,"Yo m' enamoré de noche,\nPensando qu' era bonita,\nY bide al amanesé\nQu' era tuerta la mardita.",1,0,-1,7,"",0,4,"ia",50,0,-1,0,321,321,"4878","",0,"","","",1,0,0,[],""],["rm_t3-n4879",1,"Hago yo tanto caso\nDe tus razones,\nComo el rey en palacio\nDe porfiadores.",1,0,-1,7,"",6,4,"oe",-1,0,-1,0,322,322,"4879","",0,"","","",1,0,0,[],""],["rm_t3-n4880",1,"Pierde 'r perro y pierde 'r pan\nQuien da pan á perro ajeno;\nYo no t' he dao á tí pan,\nPor no perdé mas qu' er perro.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,322,322,"4880","",0,"","","",1,0,0,[],""],["rm_t3-n4882",1,"Las vecinas me dicen\nQue soy tu novia;\n¡Mira no se te asiente!\n¡Ponte cebollas!",1,0,-1,7,"",6,4,"oa",-1,0,-1,0,322,322,"4882","",0,"","","",1,0,0,[],""],["rm_t3-n4883",1,"Que tenga la boca grande,\nQue tenga la boca chica,\nSi no has de ser mi marido,\n¿A qué me tomas medida?",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,322,322,"4883","",0,"","","",3,0,0,[],""],["rm_t3-n4884",1,"Me llamaste «la blanca,»\nPor hacer burla;\nMorenita soy, majo;\nPero nó tuya.",1,0,-1,7,"",6,4,"ua",-1,0,-1,0,322,322,"4884","",0,"","","",1,0,0,[],""],["rm_t3-n4885",1,"Anda y que te mate un toro\nY que t' entierre Undebé:\nEres más fea qu' er mengue\nY tambien quieres querer.",1,0,-1,7,"",0,4,"e",-1,0,-1,0,322,323,"4885","",0,"","","",1,0,0,[],""],["rm_t3-n4886",1,"Te tienes por bonita\nY eres más fea\nQue los Hércules biejos\nDe l' Alamea.\n¡Ay, que te quiero....\nPara en no habiendo leña\nPegarte fuego!",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,323,323,"4886","",0,"","","",1,0,0,[],""],["rm_t3-n4887",1,"El que tiene una novia.\nFea, como yo,\nEn lo que está pensando\nBien lo sabe Dios.",1,0,-1,7,"",0,4,"o",-1,0,-1,0,323,323,"4887","",0,"","","",1,0,0,[],""],["rm_t3-n4888",1,"Me dices que soy fea;\nYo no lo ignoro;\nComo en los almanaques,\nDios sobre todo.",1,0,-1,7,"",6,4,"oo",-1,0,-1,0,323,323,"4888","",0,"","","",2,0,0,[],""],["rm_t3-n4890",1,"¡J ole con jole con jo le!\nTú l' has tomao conmigo;\nTómala ayá con tu mare,\nQue te puede dar castigo.",1,0,-1,7,"",0,4,"io",106,0,-1,0,323,323,"4890","",0,"","","",1,0,0,[],""],["rm_t3-n4891",1,"¿De qué te sirve tener\nBaston de quiquiricaña,\nSi te dicen las mozuelas:\n«Buen mozo, pero no apaña?»",1,0,-1,7,"",0,4,"aa",213,0,-1,0,323,323,"4891","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t3-n4894",1,"Corre y dile á esa mujé\nQue á mí no me traiga en boca;\nQue una bes que le dí un beso\nPor poco se buerbe loca.",1,0,-1,7,"",0,4,"oa",178,0,-1,0,324,324,"4894","",0,"","","",1,0,0,[],""],["rm_t3-n4895",1,"Si piensas que yo te quiero\nPor que te miro y me rio,\nSoy un poquiyo burlona\nY tú no lo has conosío.",1,0,-1,7,"",0,4,"io",3,0,-1,0,324,324,"4895","",0,"","","",7,0,0,[],""],["rm_t3-n4896",1,"No pienses que yo te quiero\nPor que te miro á la cara;\nQue muchos van á la feria\nA ver y no compran nada.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,324,324,"4896","",0,"","","",1,0,0,[],""],["rm_t3-n4897",1,"Porque te miro á la cara,\nNo por eso te he de amar;\nQue muchos van á la feria\nPor ver y nó por comprar.",1,0,-1,7,"",0,4,"a",21,0,-1,0,324,324,"4897","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t3-n4899",1,"Pensabas que te queria,\nY era para entretenerme;\nMiéntras otro me salia,\nMe servias de juguete.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,324,325,"4899","",0,"","","",4,0,0,[],""],["rm_t3-n4900",1,"Si piensas que yo te quiero\nCon algunos desatinos,\nTengo yo mi querer puesto\nEn otro paño más fino.",1,0,-1,7,"",0,4,"io",-1,0,-1,0,325,325,"4900","",0,"","","",7,0,0,[],""],["rm_t3-n4902",1,"Si piensas que por verte\nMe desatino,\nAgárrate á las lanas\nDe un perro chino.",1,0,-1,7,"",6,4,"io",199,0,-1,0,325,325,"4902","",0,"","","",2,0,0,[],""],["rm_t3-n4903",1,"Si piensas que por verte\nSalgo á la calle,\nTengo calor y quiero\nQue me dé el aire.",1,0,-1,7,"",6,4,"ae",-1,0,-1,0,325,325,"4903","",0,"","","",2,0,0,[],""],["rm_t3-n4904",1,"Si piensas que te quiero,\nTe has engañado;\nPorque tengo yo un gusto\nMuy delicado.",1,0,-1,7,"",6,4,"ao",14,0,-1,0,325,325,"4904","",0,"","","",3,0,0,[],""],["rm_t3-n4905",1,"Si piensas que en tí pienso,\nMal has pensado;\nTengo mi pensamiento\nPor otro lado.",1,0,-1,7,"",6,4,"ao",14,0,-1,0,325,325,"4905","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n4906",1,"Si piensas que en tí pienso,\nHas pensado mal;\nNi pienso, ni he pensado,\nNi pienso en pensar.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,325,326,"4906","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t3-n4907",1,"Tú pensarias que yo\nTe habia de querer siempre;\nEn mi vida lo he pensado,\nNi tú tampoco lo pienses.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,326,326,"4907","",0,"","","",1,0,0,[],""],["rm_t3-n4908",1,"Si piensas que con halagos\nMe has de ablandar como cera,\nSoy yo de tal calidad,\nQue el mismo fuego me hiela.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,326,326,"4908","",0,"","","",3,0,0,[],""],["rm_t3-n4909",1,"Si piensas que han de volver\nLas nueces al cantarillo,\nA tí se te fué el amor\nY á mí se me fué el cariño.",1,0,-1,7,"",0,4,"io",-1,0,-1,0,326,326,"4909","",0,"","","",3,0,0,[],""],["rm_t3-n4910",1,"Si piensas que por tí son\nLos colores que me salen,\nEn mi vida me enamoro\nDe hombres que tan poco valen.",1,0,-1,7,"",0,4,"ae",227,0,-1,0,326,326,"4910","",0,"","","",4,0,0,[],""],["rm_t3-n4911",1,"Piensas que me vuelven loca\nTus patillas y cuchillo;\nY yo no quiero galanes\nQue escupan por el colmillo.",1,0,-1,7,"",0,4,"io",228,0,-1,0,326,326,"4911","",0,"","","",3,0,0,[],""],["rm_t3-n4912",1,"Si piensas que he de echar luto,\nGalan, por tu ausencia leve,\nQuisiera en esta ocasion\nTener galas que ponerme.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,326,326,"4912","",0,"","","",1,0,0,[],""],["rm_t3-n4913",1,"Tú pensarás que me has hecho\nAgravio con enojarte;\nY me has hecho un beneficio,\nQue no sé con qué pagarte.",1,0,-1,7,"",0,4,"ae",8,0,-1,0,326,327,"4913","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4914",1,"Mis amores me dejaron;\nLos motivos no los sé;\nPiensan que me han hecho un daño;\nLo que me han hecho es un bien.",1,0,-1,7,"",0,4,"e",-1,0,-1,0,327,327,"4914","",0,"","","",1,0,0,[],""],["rm_t3-n4915",1,"Pensaba el tonto, pensaba\nQue yo por él me moria;\nÉl pensaba, y yo pensaba\nCómo se la pegaria.",1,0,-1,7,"",1,4,"aa",-1,0,-1,0,327,327,"4915","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4916",1,"Pensaba la muy tontona,\nPensaba que yoraria;\nNo sabe qu' en la taberna\nBenden cañas d' alegría.",1,0,-1,7,"",5,4,"ia",-1,0,-1,0,327,327,"4916","",0,"","","",2,0,0,[],""],["rm_t3-n4917",1,"Se pensaba el mozo vano\nQue yo por él me moria;\nNo me he muerto yo por otros\nQue más cuenta me tenian.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,327,327,"4917","",0,"","","",3,0,0,[],""],["rm_t3-n4918",1,"Si porque tú no me quieres\nMe tengo de morir yo....\n¡Cabalito! ¡Si Dios quiere!\n¡Por supuesto! ¡Sí, señor!",1,0,-1,7,"",0,4,"o",-1,0,-1,0,327,327,"4918","",0,"","","",1,0,0,[],""],["rm_t3-n4919",1,"El dia que me dejastes\nCreyeron que me moria,\nPorque me vieron llorar...\nY lloraba de alegría.",1,0,-1,7,"",0,4,"ia",0,0,-1,0,327,327,"4919","",0,"","","",1,0,0,[],""],["rm_t3-n4920",1,"Si quieres darme pesares\nCon querer á otra deidad,\nQuiérela tú sin recelo,\nQue á mí nada se me da.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,327,328,"4920","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4921",1,"Mi moreno me olvidó;\nNo me da pena maldita;\nQue la mancha de la mora\nCon otra verde se quita.",1,0,-1,7,"",0,4,"ia",50,0,-1,0,328,328,"4921","",0,"","","",3,0,0,[],""],["rm_t3-n4922",1,"Dicen que usté no me quiere;\nA mí no me da cuidado;\nMañana me pongo luto\nDe tafetan encarnado.",1,0,-1,7,"",0,4,"ao",14,0,-1,0,328,328,"4922","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4923",1,"Si piensas que por tu enojo\nTengo de echarme á llorar,\nMañana me pongo luto\nDe encarnado tafetan.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,328,328,"4923","",0,"","","",1,0,0,[],""],["rm_t3-n4924",1,"Dices que no me quieres,\nPorque soy sordo;\nYo tampoco te quiero,\nPor lo que oigo.\nPorque soy ciego;\nTú tampoco me gustas,\nPor lo que veo.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,328,328,"4924","",0,"","","",15,0,0,[],""],["rm_t3-n4925",1,"Me dijiste «la blanca\nDel azabache;»\nYo me estuve en mi casa;\nTú me buscaste.",1,0,-1,7,"",6,4,"ae",-1,0,-1,0,328,328,"4925","",0,"","","",1,0,0,[],""],["rm_t3-n4926",1,"¿Fuistes tú la que dijistes\nAyer en el lavadero\nQue te casabas conmigo?\nEso será si yo quiero.",1,0,-1,7,"",0,4,"eo",38,0,-1,0,328,328,"4926","",0,"","","",1,0,0,[],""],["rm_t3-n4927",1,"Te pusistes y dijistes\nEn la Crus de la Berdá\nQue te casabas conmigo,\nSin saber mi boluntá.",1,0,-1,7,"",0,4,"a",9,0,-1,0,329,329,"4927","",0,"","","",2,0,0,[],""],["rm_t3-n4928",1,"Mi moreno me olvidó,\nPensando que lo sintiera,\nY en su lugar puse otro:\nNo hay mal que por bien no venga.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,329,329,"4928","",0,"","","",3,0,0,[],""],["rm_t3-n4929",1,"Dicen, niña, que usté tiene\nAmores á quien querer;\nLos partidos son iguales:\nSi usté tiene, yo tambien.",1,0,-1,7,"",0,4,"e",-1,0,-1,0,329,329,"4929","",0,"","","",1,0,0,[],""],["rm_t3-n4930",1,"Si tú novia nueva tienes\nY están los gustos cabales,\nNovio nuevo tengo yo\nY estamos los dos iguales.",1,0,-1,7,"",0,4,"ae",26,0,-1,0,329,329,"4930","",0,"","","",1,0,0,[],""],["rm_t3-n4931",1,"Dicen que no me quieres;\nPues déjalo estar;\nQue si tú no me quieres,\nOtra me querrá.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,329,329,"4931","",0,"","","",18,0,0,[],""],["rm_t3-n4932",1,"Algun dia te queria\nY ahora ya no te quiero,\nPorque he encontrado paloma\nQue remonte más el vuelo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,329,329,"4932","",0,"","","",3,0,0,[],""],["rm_t3-n4933",1,"Aunque me ves que me caigo,\nCon un pié me voy teniendo;\nSi tú tienes quien te quiera,\nMira que tambien yo tengo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,329,329,"4933","",0,"","","",2,0,0,[],""],["rm_t3-n4934",1,"Si esta mujer no me quiere,\n¿Qué hago con afligirme?\nA mí no me ha de faltar\nOtra con quien divertirme.",1,0,-1,7,"",0,4,"ie",184,0,-1,0,330,330,"4934","",0,"","","",3,0,0,[],""],["rm_t3-n4935",1,"Dicen que no me quieres\nTú ni tu madre;\nSi una puerta se cierra,\nCiento se abren.",1,0,-1,7,"",6,4,"ae",-1,0,-1,0,330,330,"4935","",0,"fernan_caballero","","",18,0,0,[],""],["rm_t3-n4936",1,"Dicen que usté no me quiere;\nSe me dan tres caracoles;\nMás arriba ó más abajo\nMe están queriendo á montones.",1,0,-1,7,"",0,4,"oe",-1,0,-1,0,330,330,"4936","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t3-n4940",1,"Mejores mosos que tú,\nPajariyos e más cuenta,\nM' están mirando á la cara,\nPa tenerme á mí contenta.",1,0,-1,7,"",0,4,"ea",229,0,-1,0,330,331,"4940","",0,"","","",1,0,0,[],""],["rm_t3-n4941",1,"Del templo de Cupido\nFuí yo devota\nY el santo que adoraba\nSe fué con otra.\nNo me da pena;\nQue ya tengo otro santo\nQue más me quiera.",1,0,-1,7,"",4,7,"ea",-1,0,-1,0,331,331,"4941","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4942",1,"A tu querer lo comparo\nCon los platos del bazar;\nQue cuando se rompe uno,\nSe pone otro en su lugar.",1,0,-1,7,"",0,4,"a",21,0,-1,0,331,331,"4942","",0,"","","",4,0,0,[],""],["rm_t3-n4943",1,"A rey muerto, rey puesto,\nDice mi madre;\nNo pases, hija mia,\nPenas por nadie.",1,0,-1,7,"",6,4,"ae",-1,0,-1,0,331,331,"4943","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t3-n4944",1,"Te quise y me quisistes;\nMas de allí á poco,\nDesnudastes á un santo\nPor vestir otro.\nPero te digo\nQue el que tú desnudastes\nYa está vestido.",1,0,-1,7,"",4,7,"io",-1,0,-1,0,331,331,"4944","",0,"","","",1,0,0,[],""],["rm_t3-n4945",1,"Como mi amor desprecias,\nYo marcho en posta\nA dar estas noticias\nA doña Otra.\nQue es el remedio\nCon que pronto se olvidan\nEstos desprecios.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,331,332,"4945","",0,"","","",2,0,0,[],""],["rm_t3-n4947",1,"Si piensas darme pesares\nCon decir que tienes otra,\nYo tengo para ganarte\nCaballo, malilla y sota.",1,0,-1,7,"",0,4,"oa",-1,0,-1,0,332,332,"4947","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4948",1,"Una caña de pescar\nTengo para mi consuelo;\nSi un amante se me va,\nOtro queda en el anzuelo.",1,0,-1,7,"",0,4,"eo",10,0,-1,0,332,332,"4948","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4949",1,"Échale trigo á la era\nY conmigo no platiques;\nQue tengo yo quien me quiera\nDesde el dia que te fuistes.",1,0,-1,7,"",0,4,"ie",-1,0,-1,0,332,332,"4949","",0,"","","",4,0,0,[],""],["rm_t3-n4950",1,"Toma la veredita\nQue tú quisieres;\nNi á mí me faltan hombres\nNi á tí mujeres.\nY si me faltan,\nNo seré la primera\nQue no se casa.",1,0,-1,7,"",4,7,"aa",-1,0,-1,0,332,332,"4950","",0,"","","",1,0,0,[],""],["rm_t3-n4951",1,"Si piensas que en tu ausencia\nMe pongo triste,\nPara suplir tu falta\nTengo yo quince.",1,0,-1,7,"",6,4,"ie",-1,0,-1,0,332,332,"4951","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n4952",1,"Me quisistes, me olvidastes,\nMe volvistes á querer;\nZapatos que yo desecho\nNo me los vuelvo á poner.",1,0,-1,7,"",0,4,"e",20,0,-1,0,333,333,"4952","",0,"","","",2,0,0,[],""],["rm_t3-n4953",1,"Zapatos que yo desecho\nY los tiro al muladar,\nSi otro llega y se los pone,\n¿Qué cuidado se me da?",1,0,-1,7,"",0,4,"a",-1,0,-1,0,333,333,"4953","",0,"","","",1,0,0,[],""],["rm_t3-n4954",1,"De la lechuga romana\nEl cogollo me comí;\nQue otros se coman las hojas,\n¿Qué cuidado me da á mí?",1,0,-1,7,"",0,4,"i",23,0,-1,0,333,333,"4954","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4955",1,"Anda y dile á quien te quiere\nQue por mí esté descuidao;\nPero que tenga la pena\nDe comer de mi sobrao.",1,0,-1,7,"",0,4,"ao",98,0,-1,0,333,333,"4955","",0,"","","",2,0,0,[],""],["rm_t3-n4956",1,"En esta calle vive,\nVive y vivia,\nLa novia de mi novio,\nContraria mia.\nY yo me rio\nDe ver que ella ha tomado\nDesechos mios.",1,0,-1,7,"",4,7,"o",-1,0,-1,0,333,333,"4956","",0,"","","",3,0,0,[],""],["rm_t3-n4957",1,"Si tratas de olvidarme,\nPon en tu balcon\nUn letrero que diga:\n«Ya esto se acabó.»\nYo pondré enfrente\nUn letrero que diga:\n«Hasta la muerte.»",1,0,-1,7,"",4,7,"ee",-1,0,-1,0,333,333,"4957","",0,"","","",1,0,0,[],""],["rm_t3-n4959",1,"Aunque me ves chiquitita,\nHuérfana de padre y madre,\nNo se crió la lechuga\nPara tan flojo vinagre.",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,334,334,"4959","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t3-n4960",1,"Aunque me ves chiquitita\nY mi madre no está aquí,\nLas lechugas de mi huerto\nNo se crian para tí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,334,334,"4960","",0,"","","",4,0,0,[],""],["rm_t3-n4963",1,"Ya está el pájaro bobo\nPuesto en la esquina,\nEsperando que salga\nLa golondrina.",1,0,-1,7,"",6,4,"ia",11,0,-1,0,334,335,"4963","",0,"","","",1,0,0,[],""],["rm_t3-n4969",1,"Aunque seas buena moza,\nNo te lo presumas tanto;\nQue tambien las buenas mozas\nSe suelen quedar en blanco.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,336,336,"4969","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n4970",1,"No te pongas tan alta,\nQue no eres reina;\nYo me atrevo á alcanzarte\nSin escalera.",1,0,-1,7,"",6,4,"ea",-1,0,-1,0,336,336,"4970","",0,"fernan_caballero, palau_cantares","","",4,0,0,[],""],["rm_t3-n4971",1,"Aunque usté diga, niña,\nQue es de alta esfera,\nTambien para las torres\nHay escalera.\nY no hay mozuelo\nQue no suba en las fiestas\nY toque á vuelo.",1,0,-1,7,"",4,7,"eo",10,0,-1,0,336,336,"4971","",0,"","","",1,0,0,[],""],["rm_t3-n4977",1,"Gastas mucha fantesía\nY estás guindao del aire;\nEsos jumos que terelas\nSa menesté que s' acaben.",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,337,337,"4977","",0,"","","",4,0,0,[],""],["rm_t3-n4978",1,"La fantesía t' ajoga,\nTe siega la baniá\nY tu presona no tiene\nNaitita e particulá.",1,0,-1,7,"",0,4,"a",9,0,-1,0,337,337,"4978","",0,"","","",1,0,0,[],""],["rm_t3-n4979",1,"Gasta usté más fantesía\nQu' er coche del Intendente\nY no bal' usté dos cuartos\nNi ninguno de su gente.",1,0,-1,7,"",0,4,"ee",15,0,-1,0,337,337,"4979","",0,"","","",2,0,0,[],""],["rm_t3-n4980",1,"Ascuch' usté, mosa güena,\nNo gast' usté fantesía;\nQu' er carro de la basura\nTamien gasta campaniyas.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,337,338,"4980","",0,"","","",1,0,0,[],""],["rm_t3-n4981",1,"¡Salero, biba 'r salero!\n¡Biba la sá y la sandunga!\nQue bal' usté más pesetas\nQue clabos tiene una arcusa.",1,0,-1,7,"",0,4,"ua",-1,0,-1,0,338,338,"4981","",0,"","","",2,0,0,[],""],["rm_t3-n4982",1,"Si tuvieras dinerales\nComo tienes fantasía,\nEl rio de Manzanares\nPor tu puerta pasaria.",1,0,-1,7,"",0,4,"ia",0,0,-1,0,338,338,"4982","",0,"","","",1,0,0,[],""],["rm_t3-n4983",1,"Es tanta la vanidad\nQue tu cuerpo representa,\nQue es menester para hablarte\nDoscientos duros de renta.",1,0,-1,7,"",0,4,"ea",229,0,-1,0,338,338,"4983","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4985",1,"Desde que usté se pasea\nPor las calles del lugar,\nEstá perdida la venta\nDe las cañas de pescar.",1,0,-1,7,"",0,4,"a",21,0,-1,0,338,338,"4985","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4990",1,"Tonta tú, tonta tu mare,\nTonta tu agüela y tu tia;\n¿Cómo quieres que te quiera,\nSi eres de la tontería?",1,0,-1,7,"",0,4,"ia",0,0,-1,0,339,339,"4990","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t3-n4991",1,"El quererte yo á tí, sí;\nY el tomar cuanto me dieres;\nPero casarme contigo,\nCréelo cuando lo vieres.",1,0,-1,7,"",0,4,"ee",55,0,-1,0,339,339,"4991","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4992",1,"El quererte yo á tí, sí;\nY el hablarte cuando pueda;\nPero casarme contigo,\nNo ha de caerte esa breva.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,339,339,"4992","",0,"","","",3,0,0,[],""],["rm_t3-n4993",1,"Es cierto que te he querido;\nQue te he querido y te quiero;\nPero casarme contigo,\nNo lo permitan los cielos.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,339,339,"4993","",0,"lafuente_madrid, palau_cantares","","",7,0,0,[],""],["rm_t3-n4994",1,"Es cierto que te he querido\nY que te he sido constante;\nPero casarme contigo,\nEso, ¡ni por chocolate!",1,0,-1,7,"",0,4,"ae",-1,0,-1,0,339,340,"4994","",0,"","","",7,0,0,[],""],["rm_t3-n4995",1,"Es cierto que te he querido\nY que te he sido lëal;\nPero casarme contigo,\nEso nunca lo verás.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,340,340,"4995","",0,"","","",7,0,0,[],""],["rm_t3-n4996",1,"Por donde quiera que voy\nMe dicen que yo soy tuya;\n¿Qué cadena me has echado,\nQue me tienes tan segura?",1,0,-1,7,"",0,4,"ua",-1,0,-1,0,340,340,"4996","",0,"","","",4,0,0,[],""],["rm_t3-n4997",1,"Que tienes muchos majos\nDicen que dices;\nMira cuando reclames,\nNo halles perdices.",1,0,-1,7,"",6,4,"ie",113,0,-1,0,340,340,"4997","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n4998",1,"Me han dicho que tiene usté\nCatorce novios contados;\nConmigo no cuente usté,\nQue tengo el hato aviado.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,340,340,"4998","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n4999",1,"Niña de los veinte novios\nY conmigo veintiuno;\nSi todos son como yo,\nTe quedarás sin ninguno.",1,0,-1,7,"",0,4,"uo",230,0,-1,0,340,340,"4999","",0,"fernan_caballero","","",11,0,0,[],""],["rm_t3-n5000",1,"Niña de los veinte novios,\nQue con ninguno te casas;\nSi te guardas para un rey,\nCuatro tiene la baraja.",1,0,-1,7,"",0,4,"aa",-1,0,-1,0,340,340,"5000","",0,"palau_cantares, lafuente_madrid","","",11,0,0,[],""],["rm_t3-n5001",1,"Si tu madre quiere un rey,\nLa baraja tiene cuatro:\nRey de oros, rey de copas,\nRey de espadas, rey de bastos.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,340,341,"5001","",0,"","","",3,0,0,[],""],["rm_t3-n5003",1,"Se puso tu madre y dijo\nQue la reina para tí;\nAnde vé y dile á tu madre\nQue la reina está en Madrí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,341,341,"5003","",0,"","","",8,0,0,[],""],["rm_t3-n5004",1,"Anda diciendo tu madre\nQue te mereces la reina;\nAnda vé y díle á ese trapo\nQue vaya á Madrí por ella.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,341,341,"5004","",0,"","","",23,0,0,[],""],["rm_t3-n5005",1,"Anda diciendo tu madre\nQue la reina te mereces;\nY yo, como no soy reina,\nTe aconsejo que me dejes.",1,0,-1,7,"",0,4,"ee",-1,0,-1,0,341,341,"5005","",0,"lafuente_madrid","","",23,0,0,[],""],["rm_t3-n5006",1,"Se puso tu madre y dijo\nQue á la reina merecías;\nY yo por engrandecerte,\nDije que no te queria.",1,0,-1,7,"",0,4,"ia",-1,0,-1,0,341,341,"5006","",0,"lafuente_madrid","","",8,0,0,[],""],["rm_t3-n5007",1,"Anda disiendo tu mare\nQu' eya no me quiê pâ nuera;\nAnda bé y dile á tu mare\nQue yo no la quió pâ suegra.",1,0,-1,7,"",0,4,"ea",-1,0,-1,0,341,341,"5007","",0,"","","",3,0,0,[],""],["rm_t3-n5008",1,"Me dijistes mi cuñada,\nPensando que ya lo era;\nNo me siento yo en tablao\nDe tan endeble maera.",1,0,-1,7,"",0,4,"ea",44,0,-1,0,341,342,"5008","",0,"","","",1,0,0,[],""],["rm_t3-n5009",1,"Anda disiendo tu madre\nQue yo contigo no igualo;\nEso será en er dinero,\nPorque en la sangre, te gano.",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,342,342,"5009","",0,"","","",3,0,0,[],""],["rm_t3-n5010",1,"Se puso tu madre y dijo\nQu' eras tú mejor que yo;\n¿En qué libro lo ha leío,\nÓ en qué sueño lo ensoñó?",1,0,-1,7,"",0,4,"o",2,0,-1,0,342,342,"5010","",0,"","","",8,0,0,[],""],["rm_t3-n5011",1,"Anda disiendo tu mare\nQu' eres tú mejor que yo;\nY ni eya que t' ha parío,\nNi er pare que t' engendró",1,0,-1,7,"",0,4,"o",2,0,-1,0,342,342,"5011","",0,"","","",3,0,1,[],""],["rm_t3-n5012",1,"Anda disiendo tu mare\nQue yo á tí t' h' entretenío,\n¡Y te tengo apuntaíya\nEn er libro del orbío!",1,0,-1,7,"",0,4,"io",3,0,-1,0,342,342,"5012","",0,"","","",3,0,0,[],""],["rm_t3-n5013",1,"Tu madre dice que tú\nTe estás burlando de mí;\nA deshonra tengo yo\nHacerme caso de tí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,342,342,"5013","",0,"","","",1,0,0,[],""],["rm_t3-n5014",1,"Cuando paso por tu puerta\nCompro pan y voy comiendo,\nPâ que no diga tu madre\nQue con berte me mantengo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,342,342,"5014","",0,"","","",17,0,0,[],""],["rm_t3-n5015",1,"Cuando paso por tu puerta\nLlevo la capa arrastrando,\nPor que no diga tu madre\nQue te voy enamorando.",1,0,-1,7,"",0,4,"ao",33,0,-1,0,343,343,"5015","",0,"","","",17,0,0,[],""],["rm_t3-n5016",1,"Si tu madre se realza\nPorque tú tienes dinero,\nSi se realza tu madre,\nLa mia ya llega al cielo.",1,0,-1,7,"",0,4,"eo",-1,0,-1,0,343,343,"5016","",0,"","","",1,0,0,[],""],["rm_t3-n5017",1,"Anda bé y dile á tu mare\nQue no jable mar de mí;\nQu' en su bía estubo honrâ\nJasta que la conosí.",1,0,-1,7,"",0,4,"i",23,0,-1,0,343,343,"5017","",0,"","","",4,0,0,[],""],["rm_t3-n5018",1,"Anda bé y dile á tu mare\nQue te pele y que te monde,\nQue te buerba á dá la teta\nY que t' enseñe á ser hombre.",1,0,-1,7,"",0,4,"oe",-1,0,-1,0,343,343,"5018","",0,"","","",4,0,0,[],""],["rm_t3-n5019",1,"Anda bé y dile á tu madre\nQue te meta en un nichito\nY t' ensienda cuatro belas,\nQue yo no te nesesito.",1,0,-1,7,"",0,4,"io",119,0,-1,0,343,343,"5019","",0,"","","",2,0,0,[],""],["rm_t3-n5020",1,"Mariquita, María,\nDile á tu madre\nQue te meta en un cofre,\nTe eche la llave.",1,0,-1,7,"",6,4,"ae",-1,0,-1,0,343,343,"5020","",0,"","","",12,0,0,[],""],["rm_t3-n5021",1,"Anda y dile á tu madre\nQue te empapele;\nQue la que te queria\nYa no te quiere.",1,0,-1,7,"",6,4,"ee",-1,0,-1,0,343,343,"5021","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5022",1,"En siertas combersasiones\nT' has puesto y m' has despresiao;\nTe quisiera preguntar\nQuién conmigo t' ha brindao.",1,0,-1,7,"",0,4,"ao",98,0,-1,0,344,344,"5022","",0,"","","",1,0,0,[],""],["rm_t3-n5023",1,"Parece que me miras;\n¿Quieres comprarme?\nNo tienes tú dinero\nPara pagarme.",1,0,-1,7,"",6,4,"ae",35,0,-1,0,344,344,"5023","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5024",1,"Dices que no me quieres,\nPorque no igualas;\nMi sangre por la tuya\nTú la tomaras.",1,0,-1,7,"",6,4,"aa",-1,0,-1,0,344,344,"5024","",0,"","","",15,0,0,[],""],["rm_t3-n5025",1,"Dicen que tienes un pero;\nUn pero que no es de Ronda;\nCorre y busca una manzana\nQue se iguale á tu persona.",1,0,-1,7,"",0,4,"oa",-1,0,-1,0,344,344,"5025","",0,"","","",1,0,0,[],""],["rm_t3-n5026",1,"Siendo tan güena mosa,\nNo t' has casao;\nArgun pero 'n el arca\nTendrás guardao.\nPero que es pero,\nPero que no es de Ronda,\nYo no lo quiero.",1,0,-1,7,"",4,7,"eo",38,0,-1,0,344,344,"5026","",0,"","","",1,0,0,[],""],["rm_t3-n5027",1,"Anda véte enhoramala,\nY en tu cara te lo digo;\nEres tú muy poca cosa\nPara casarte conmigo.",1,0,-1,7,"",0,4,"io",106,0,-1,0,344,344,"5027","",0,"","","",2,0,0,[],""],["rm_t3-n5029",1,"No te pongas tan alta\nNi tan subida,\nQue otras mucho más altas\nSe ven caidas.\nNo me rebajes;\nQue puedo ser la honra\nDe tu linaje.",1,0,-1,7,"",4,7,"ae",-1,0,-1,0,345,345,"5029","",0,"","","",4,0,0,[],""],["rm_t3-n5030",1,"Náide se iguala conmigo\nNi en sangre ni en caliá;\nTú tienes de dos metales\nY yo de uno nâ más.",1,0,-1,7,"",0,4,"a",-1,0,-1,0,345,345,"5030","",0,"","","",1,0,0,[],""],["rm_t3-n5032",1,"¿Qué más quisiera ese purpo?\n¿Qué más quisiera ese caño,\nQu' er bajío de mi boca\nSe rosara con sus labios?",1,0,-1,7,"",0,4,"ao",-1,0,-1,0,345,345,"5032","",0,"","","",1,0,0,[],""],["rm_t3-n5034",1,"M' han dicho qu' andas jasiendo\nPesquisas de mi linaje;\nSi tú tienes, yo no tengo\nRamiya que se m' esgaje.",1,0,-1,7,"",0,4,"ae",231,0,-1,0,345,345,"5034","",0,"","","",3,0,0,[],""],["rm_t3-n5035",1,"M' han dicho qu' andas jasiendo\nPesquisas de quién soy yo;\nComo si tú desendieras\nD' argun prínsipe ó señó.",1,0,-1,7,"",0,4,"o",2,0,-1,0,346,346,"5035","",0,"","","",3,0,0,[],""],["rm_t3-n5036",1,"Si estás engrandecida\nCon tu linaje,\nMételo en un puchero,\nPon un potaje.\n¡Ole, salero!\n¡Mal haya tu linaje,\nQue no lo quiero!",1,0,-1,7,"",4,7,"eo",38,0,-1,0,346,346,"5036","",0,"","","",1,0,0,[],""],["rm_t3-n5037",1,"Dicen que por el pelo\nTienes amores;\nEcha el pelo en la olla,\nVerás qué comes.",1,0,-1,7,"",6,4,"oe",-1,0,-1,0,346,346,"5037","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5038",1,"Amores y dolores\nQuitan el sueño;\nYo me duermo tranquilo,\nQue no los tengo.",1,0,-1,7,"",6,4,"eo",-1,0,-1,0,346,346,"5038","",0,"","","",2,0,0,[],""],["rm_t3-n5039",1,"Hoy que ya sin cadenas\nLibre respiro,\nLa libertad disfruto\nDe mi albedrío.\nY estoy contento\nDe verme tan distante\nDel cautiverio.",1,0,-1,7,"",4,7,"eo",-1,0,-1,0,346,346,"5039","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n5040",1,"De las dichas que hallaba\nMi cautiverio,\nAhora que estoy libre\nYa no me acuerdo.\nQue aquellas dichas,\nPor ser hijas de un ciego,\nNo tienen vista.",1,0,-1,7,"",4,7,"ia",-1,0,-1,0,346,347,"5040","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5041",1,"Tuve amor, tuve penas\nY tuve celos,\nY salí de estos males\nAborreciendo.\nAhora me paso\nUna vida tranquila,\nSin sobresaltos.",1,0,-1,7,"",4,7,"ao",-1,0,-1,0,347,347,"5041","",0,"","","",1,0,0,[],""],["rm_t3-n5042",1,"Una vez tuve amores;\nYa no los tengo,\nY puedo asegurarte\nQue estoy contento.\nNo más amores,\nPues quiero vivir libre\nDe sujeciones.",1,0,-1,7,"",4,7,"oe",-1,0,-1,0,347,347,"5042","",0,"","","",1,0,0,[],""],["rm_t3-n5043",1,"Empecé por capricho,\nSeguí por tema,\nContinué por desvelo\nY acabé en pena.\nY de esta suerte,\nLe temo á los caprichos\nMás que á la muerte.",1,0,-1,8,"",4,7,"ee",134,0,-1,0,366,366,"5043","",0,"","","",1,0,0,[],""],["rm_t3-n5044",1,"El amor me persigue\nCon tal porfía,\nQue á millones las penas\nMe las envia.",1,0,-1,8,"",6,4,"ea",-1,0,-1,0,366,366,"5044","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5045",1,"Tengo un dolor en el pecho,\nY los médicos me dicen\nQue no es dolor, que es amor,\nQue va criando raíces.",1,0,-1,8,"",0,4,"ie",-1,0,-1,0,366,366,"5045","",0,"","","",2,0,0,[],""],["rm_t3-n5046",1,"¡Bárgame Dios, qué dolores,\nQué fatigas y qué penas\nPasan los hombres á beses\nPor una cara morena!",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,366,366,"5046","",0,"","","",1,0,0,[],""],["rm_t3-n5047",1,"Yo pensé que el querer bien\nEra cosa de juguete,\nY ya veo que se pasan\nLas fatigas de la muerte.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,367,367,"5047","",0,"","","",4,0,0,[],""],["rm_t3-n5048",1,"Yo pensé que el querer bien\nEra fácil de olvidar,\nY es callejon tan estrecho,\nQue el que entra no sale más.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,367,367,"5048","",0,"","","",4,0,0,[],""],["rm_t3-n5049",1,"Yo me enamoré, pensando\nQue el amor era ligero;\nNo ví carga más pesada\nNi que más me quite el sueño.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,367,367,"5049","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5050",1,"Yo me metí en el querer\nMuchachito criatura;\nCuando vine á abrir los ojos,\nMe encontré en la sepultura.",1,0,-1,8,"",0,4,"ua",17,0,-1,0,367,367,"5050","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5051",1,"Nádie se meta á querer,\nQue cuesta mucha fatiga;\nMira yo cómo me veo\nPor un querer que me obliga.",1,0,-1,8,"",0,4,"ia",232,0,-1,0,367,367,"5051","",0,"","","",1,0,0,[],""],["rm_t3-n5052",1,"Los ojitos de mi cara\nTienen los cristales muertos;\nSe han metío en er querer,\nSin saber lo que se han hecho.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,367,367,"5052","",0,"","","",13,0,0,[],""],["rm_t3-n5053",1,"Todos cuantos van á verme\nMe dicen: -¡Ay, qué dolor!\n¡Muchachito criatura,\nPreso en la cárcel de amor!",1,0,-1,8,"",0,4,"o",72,0,-1,0,367,367,"5053","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n5054",1,"Todas las mañanas voy\nA preguntarle al romero\nSi el mal de amor tiene cura,\nPorque yo de amor me muero.",1,0,-1,8,"",0,4,"eo",38,0,-1,0,368,368,"5054","",0,"","","",12,0,0,[],""],["rm_t3-n5056",1,"Anda bé á Santa María\nY encomiéndate á Undebé;\nQu' er que no pasa fatigas\nNo sabe lo qu' es queré.",1,0,-1,8,"",0,4,"e",77,0,-1,0,368,368,"5056","",0,"","","",1,0,0,[],""],["rm_t3-n5057",1,"Santa Teresa en la cueva\nDe cilicios se vistió,\nY yo tengo que vestirme\nDe los cilicios de amor.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,368,368,"5057","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5058",1,"Una palomita blanca,\nBlanquita como la niebe,\nM' ha picaíto en er pecho;\nMamita, mucho me duele.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,368,368,"5058","",0,"","","",2,0,0,[],""],["rm_t3-n5059",1,"Tengo yo una cadena\nQue me traspasa\nDe una pared á otra,\nSin tener causa.\nQue en esta cárcel\nUno paga el delito\nY otro lo hace.",1,0,-1,8,"",4,7,"ae",-1,0,-1,0,368,368,"5059","",0,"","","",1,0,0,[],""],["rm_t3-n5060",1,"Tengo una puñaladita\nQue me la dió una mozuela;\nEn mi vida he visto yo\nPuñalada que más duela.",1,0,-1,8,"",0,4,"ea",167,0,-1,0,369,369,"5060","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t3-n5061",1,"Tengo una puñaladita\nQue me la dió una mujer;\nEn mi vida he visto yo\nPuñalada más cruel.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,369,369,"5061","",0,"","","",6,0,0,[],""],["rm_t3-n5062",1,"¡Bírgen der Cármen, balerme!\n¡Er Santolio, que me muero!\nTengo una puñalaíta\nQue me la dió un querer güeno.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,369,369,"5062","",0,"","","",2,0,0,[],""],["rm_t3-n5063",1,"Yo me enamoré del aire,\nDel aire de una mujer;\nComo la mujer es aire,\nEn el aire me quedé.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,369,369,"5063","",0,"palau_cantares, isaacs_colombia, lafuente_madrid, murciano_antiguo, fernan_caballero","","",9,0,0,[],""],["rm_t3-n5065",1,"¡Mal haya el amor, mal haya\nY quien m' enseñó á queré;\nQu' estaba yo en mi sentío\nY ahora m' encuentro sin é!",1,0,-1,8,"",3,4,"e",77,0,-1,0,369,369,"5065","",0,"","","",7,0,0,[],""],["rm_t3-n5066",1,"¡Mal haya el amor, mal haya,\nY quien del amor se fia:\nQue puse yo mi querer\nEn quien no lo merecía!",1,0,-1,8,"",0,4,"ia",0,0,-1,0,369,370,"5066","",0,"","","",7,0,0,[],""],["rm_t3-n5067",1,"¡Pobre de mí, que me quejo\nDe un amor que me engañó,\nComo el que mira la piedra\nDespués que ya tropezó!",1,0,-1,8,"",0,4,"o",2,0,-1,0,370,370,"5067","",0,"","","",1,0,0,[],""],["rm_t3-n5068",1,"A mi corazon le doy\nGolpes para que se enmiende\nY que se deje de amores,\nQue éso es para quien lo entiende.",1,0,-1,8,"",0,4,"ee",233,0,-1,0,370,370,"5068","",0,"","","",1,0,0,[],""],["rm_t3-n5069",1,"Yo me senté á la sombra\nDe una morera\nY allí consideraba\nLo que amor era.\nViendo mi pesar,\nUna mora me dijo:\n-Déjate de amar.",1,0,-1,8,"",4,7,"a",21,0,-1,0,370,370,"5069","",0,"","","",1,0,0,[],""],["rm_t3-n5070",1,"La música fué siempre\nGrande remedio\nPara alegrar los sanos\nY los enfermos.\nVamos cantando,\nPara aliviar enfermos\nY alegrar sanos.",1,0,-1,8,"",4,7,"ao",-1,0,-1,0,370,370,"5070","",0,"","","",2,0,0,[],""],["rm_t3-n5071",1,"Canta, mi vida, canta:\nCanta y nó llores;\nQue cantando se alegran\nLos corazones.",1,0,-1,8,"",6,4,"oe",-1,0,-1,0,370,370,"5071","",0,"","","",4,0,0,[],""],["rm_t3-n5072",1,"-Canta, mi vida, canta;\nQue con el eco\nDiviertes la memoria\nY el pensamiento.—\nEsto decia\nUn amante del alma\nQue yo tenía.",1,0,-1,8,"",4,7,"ia",0,0,-1,0,371,371,"5072","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n5073",1,"¿Cómo quieres que yo cante,\nSi tengo el corazon triste;\nSi la prenda que yo adoro\nEn este mundo no existe?",1,0,-1,8,"",0,4,"ie",153,0,-1,0,371,371,"5073","",0,"","","",2,0,0,[],""],["rm_t3-n5074",1,"¿Quién canta teniendo penas\nComo las que tengo yo?\nPâ eso es menester que tenga\nSerdas en er corason.",1,0,-1,8,"",5,4,"ao",-1,0,-1,0,371,371,"5074","",0,"","","",1,0,0,[],""],["rm_t3-n5075",1,"Tengo de morir cantando,\nYa que llorando nací;\nQue las dichas de este mundo\nSe acabaron para mí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,371,371,"5075","",0,"","","",2,0,0,[],""],["rm_t3-n5076",1,"Quien canta, su mal espanta;\nY aquel que llora, lo aumenta;\nYo canto por divertir\nPenillas que me atormentan.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,371,371,"5076","",0,"","","",3,0,0,[],""],["rm_t3-n5077",1,"Aunque me ves que canto,\nCanta la boca;\nQue mi corazon siente\nPena, y nó poca.",1,0,-1,8,"",6,4,"oa",178,0,-1,0,371,371,"5077","",0,"","","",6,0,0,[],""],["rm_t3-n5078",1,"Aunque me ves que canto,\nTengo yo el alma\nComo la tortolilla,\nQue llora y canta,\nCuando el consorte,\nHerido de los celos\nSe escapa al monte.",1,0,-1,8,"",4,7,"oe",-1,0,-1,0,371,372,"5078","",0,"","","",6,0,0,[],""],["rm_t3-n5079",1,"El que me oyere cantar\nPensará que estoy alegre;\nYo soy como el pajarito\nQue canta cuando se muere.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,372,372,"5079","",0,"","","",2,0,0,[],""],["rm_t3-n5080",1,"Si porque me bes que canto\nPiensas que tengo alegría,\nYo soy como er caracó, (?)\nQue se gosa en su agonía.",1,0,-1,8,"",1,4,"ia",0,0,-1,0,372,372,"5080","",0,"","","",1,0,0,[],""],["rm_t3-n5081",1,"Calla, canario, y no cantes\nY respeta mi dolor;\nQue no es razon que tú cantes\nTeniendo penitas yo.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,372,372,"5081","",0,"","","",1,0,0,[],""],["rm_t3-n5082",1,"Deja de cantar, gilguero,\nQue me estás atormentando;\nQue es mucha pena en un triste\nOir cantar y estar llorando.",1,0,-1,8,"",0,4,"ao",33,0,-1,0,372,372,"5082","",0,"","","",1,0,0,[],""],["rm_t3-n5083",1,"Aquer pajarito, mare,\nQue canta en la berde oliba,\nDígal' usté que se caye,\nQue su cantar me lastima.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,372,372,"5083","",0,"","","",1,0,0,[],""],["rm_t3-n5084",1,"¿Qué importa que la calandria,\nEl ruiseñor y el gilguero\nCanten para divertirme,\nSi en mí no cabe consuelo?",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,372,372,"5084","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5085",1,"Un gilguerito llora\nY así le digo:\n-¿Tú tambien tienes penas?\nLlora conmigo.\nFiel compañero,\nTú al fin tendrás alivio,\nSi hallas tu dueño.",1,0,-1,8,"",4,7,"eo",-1,0,-1,0,373,373,"5085","",0,"","","",1,0,0,[],""],["rm_t3-n5087",1,"Pajaritos que bolais\nPor esos mundos e Dios,\nDesirme dónde hay un hombre\nMas desgrasiao que yo.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,373,373,"5087","",0,"","","",1,0,0,[],""],["rm_t3-n5088",1,"Árboles, lirios y plantas,\nQue por mí clamen ar sielo,\nPâ qu' esta mujer me quiera,\nQue si nó, de pena muero.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,373,373,"5088","",0,"","","",1,0,0,[],""],["rm_t3-n5089",1,"Soñé que me querías\nLa otra mañana,\nY soñé al mismo tiempo\nQue lo soñaba.\nQue para un triste,\nAun las dichas soñadas\nSon imposibles.",1,0,-1,8,"",4,7,"ie",-1,0,-1,0,373,373,"5089","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n5090",1,"Sufriendo está mi pecho\nPenas crueles,\nPor no saber de cierto\nSi tú me quieres.",1,0,-1,8,"",6,4,"ee",-1,0,-1,0,373,373,"5090","",0,"","","",1,0,0,[],""],["rm_t3-n5091",1,"En la Soledad te ví\nY en la Soledad me vistes;\nQue siempre es la soledad\nEl consuelo de los tristes.",1,0,-1,8,"",0,4,"ie",91,0,-1,0,374,374,"5091","",0,"","","",1,0,0,[],""],["rm_t3-n5094",1,"La alegría para mí\nMe parece contrabando;\nDesde que te conocí\nVivo en el mundo penando.",1,0,-1,8,"",1,4,"ao",33,0,-1,0,374,374,"5094","",0,"","","",1,0,0,[],""],["rm_t3-n5095",1,"Desde que te conosí\nEn mí no reina alegría;\nQue lo que reina es la pena\nQue me tiene consumía.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,374,374,"5095","",0,"","","",2,0,0,[],""],["rm_t3-n5096",1,"Alegría cuando vienes,\nTristeza cuando te vas:\nSiempre está mi corazon\nEn un contínuo penar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,374,374,"5096","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5097",1,"La pena y la que no es pena,\nTodo es pena para mí;\nAyer penaba por verte\nY hoy peno porque te ví.",1,0,-1,8,"",0,4,"i",23,0,-1,0,374,375,"5097","",0,"andina_t1, fernan_caballero","","",9,0,0,[],""],["rm_t3-n5098",1,"Ni contigo ni sin tí\nTienen mis males remedio;\nContigo, porque me matas;\nY sin tí, porque me muero.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,375,375,"5098","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n5099",1,"¿Dónde estás, prenda querida,\nCielo de mis pensamientos?\n¿En dónde estás, que no escuchas\nMis suspiros y lamentos?",1,0,-1,8,"",0,4,"eo",234,0,-1,0,375,375,"5099","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5100",1,"Cuando te oigo mentar\nM' entra er suó de la muerte;\n¡Bárgame Dios, compañera,\nLo que me cuesta er quererte!",1,0,-1,8,"",0,4,"ee",134,0,-1,0,375,375,"5100","",0,"","","",1,0,0,[],""],["rm_t3-n5103",1,"Fatigas pasa un enfermo\nCuando está para morir;\nEsas mismas paso yo\nCuando me acuerdo de tí.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,375,375,"5103","",0,"","","",1,0,0,[],""],["rm_t3-n5104",1,"Cuando te encuentro en la calle,\nAlzo la vista y te miro,\nLas lágrimas de mis ojos\nSe me caen hilo á hilo.",1,0,-1,8,"",0,4,"io",-1,0,-1,0,375,375,"5104","",0,"","","",13,0,0,[],""],["rm_t3-n5105",1,"Cuando te veo bení\nSolito la caye arriba,\nEr corason por la boca\nSe me sale de fatigas.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,376,376,"5105","",0,"","","",1,0,0,[],""],["rm_t3-n5107",1,"Cuando t' encuentro en la caye,\nLa sangre me se rebota\nY me se quiere salí\nEr corason por la boca.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,376,376,"5107","",0,"","","",5,0,0,[],""],["rm_t3-n5108",1,"Cuando te veo venir,\nHaya gente ó no haya gente,\nSin poderlo remediar,\nMe dan fatigas de muerte.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,376,376,"5108","",0,"","","",5,0,0,[],""],["rm_t3-n5109",1,"Cuando te beo benir,\nJasta 'r pelo se m' eriza\nY en las esquinas me paro\nJasta perderte de bista.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,376,376,"5109","",0,"","","",3,0,0,[],""],["rm_t3-n5110",1,"Cuando paso por tu puerta\nY me miras con desprecio,\nMe dejas la sangre helada\nY el corazon sin consuelo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,376,376,"5110","",0,"palau_cantares, lafuente_madrid","","",17,0,0,[],""],["rm_t3-n5111",1,"Cada vez que paso y miro\nDonde te he solido hablar,\nEl corazon se me parte\nDe la pena que me da.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,376,376,"5111","",0,"","","",25,0,0,[],""],["rm_t3-n5112",1,"Cada vez que miro el sitio\nDonde te he solido hablar,\nComienza mi corazon\nGotas de sangre á llorar.",1,0,-1,8,"",0,4,"a",21,0,-1,0,377,377,"5112","",0,"","","",1,0,0,[],""],["rm_t3-n5113",1,"Cuando me siento á la mesa\nY en tí me pongo á pensá,\nTiro er pan y la comía,\nDe fatigas que me dan.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,377,377,"5113","",0,"","","",5,0,0,[],""],["rm_t3-n5114",1,"Tres dias há que no como\nMás que lágrimas y pan;\nEstos son los alimentos\nQue tus amores me dan.",1,0,-1,8,"",0,4,"a",147,0,-1,0,377,377,"5114","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5115",1,"¡Ay, pobre de mí, que soy\nMuchachito criatura,\nY estoy pasando por tí\nMuchos ratos de amargura!",1,0,-1,8,"",0,4,"ua",17,0,-1,0,377,377,"5115","",0,"","","",1,0,0,[],""],["rm_t3-n5116",1,"Si la mar fuera de tinta\nY el cielo de papel blanco,\nEscribirse no podrian\nLas penas que por tí paso.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,377,377,"5116","",0,"","","",11,0,0,[],""],["rm_t3-n5117",1,"Tengo pasadas más penas\nDesde que te conocí\nQue pasó la Magdalena\nCuando se fué á convertir.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,377,377,"5117","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5118",1,"Tengo pasadas más penas\nDesde que te conocí\nQue letras tienen los libros\nQue escribió San Agustin.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,377,377,"5118","",0,"","","",4,0,0,[],""],["rm_t3-n5119",1,"Tengo pasadas por tí\nMás penas y fatigas\nQue pasan los marineros\nEn el Callao de Lima.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,378,378,"5119","",0,"","","",4,0,0,[],""],["rm_t3-n5120",1,"Ni los Templarios de Roma,\nNi el que inventó los tormentos,\nPasaron tantas fatigas\nComo paso por tu cuerpo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,378,378,"5120","",0,"","","",1,0,0,[],""],["rm_t3-n5121",1,"Estoy pasando más penas\nPor un pequeñito cuerpo\nQue granos de trigo tienen\nSanlúcar, Jerez y el Puerto.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,378,378,"5121","",0,"","","",4,0,0,[],""],["rm_t3-n5122",1,"Estoy pasando por tí\nLas ducas der caracó,\nQue yeba su casa ' cuestas,\nCon más fatigas que Dios.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,378,378,"5122","",0,"","","",3,0,0,[],""],["rm_t3-n5123",1,"Estoy pasando por tí\nMás penas y más pesares\nQue pasan los montañeses\nCuando se ban sin pagarles.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,378,378,"5123","",0,"","","",3,0,0,[],""],["rm_t3-n5124",1,"Por tu queré estoy pasando\nMás fatigas y más penas\nQue pasó aquer montañés\nQue selequemó la tienda.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,378,378,"5124","",0,"","","",1,0,0,[],""],["rm_t3-n5125",1,"Estoy pasando más penas\nPor tu cara morenita\nQue pasó aquel ermitaño\nQue se le quemó la ermita.",1,0,-1,8,"",0,4,"ia",50,0,-1,0,378,378,"5125","",0,"palau_cantares","","",4,0,0,[],""],["rm_t3-n5126",1,"Las penas que por tí paso\nNo se pueden numerar;\nDame veneno en un vaso\nY acábame de matar.",1,0,-1,8,"",1,4,"a",21,0,-1,0,379,379,"5126","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t3-n5127",1,"Si me quieres ver morir,\nDame un vaso de veneno,\nY luégo podrás decir:\n—Yo misma maté á mi dueño\n(Con veneno que le dí).",1,0,-1,8,"",7,5,"i",-1,0,-1,0,379,379,"5127","",0,"","","",7,0,0,[],""],["rm_t3-n5128",1,"No me mates, no me mates;\nDéjame que biba, biba;\nDéjame que pase, pase,\nEn este mundo fatigas.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,379,379,"5128","",0,"","","",3,0,0,[],""],["rm_t3-n5129",1,"Por aquella cruz bendita\nQue en Capuchinos está,\nQue no me des más penitas,\nQue no las puedo llevar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,379,379,"5129","",0,"lafuente_madrid, palau_cantares","","",9,0,0,[],""],["rm_t3-n5130",1,"Por la Carmelita hermosa,\nNo me des más que sentir;\nQue tu querer será causa\nDe dar á mi cuerpo fin.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,379,379,"5130","",0,"","","",2,0,0,[],""],["rm_t3-n5131",1,"Lusesita e groria,\nNo me des más penas;\nQue yo seré - un esclabo tuyo\nJasta que me muera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,379,379,"5131","",0,"","","",1,0,0,[],""],["rm_t3-n5132",1,"Dentro de mi corazon\nTengo yo una llaga viva,\nQue me ha hecho tu querer,\nDe pasar puras fatigas.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,379,380,"5132","",0,"palau_cantares","","",7,0,0,[],""],["rm_t3-n5133",1,"Mi corazon lo tengo,\nQue si lo vieras,\nLástima te causara;\nDolor te diera.\nDe puro sentir,\nNegro como la tinta\nFina de escribir.",1,0,-1,8,"",4,7,"i",157,0,-1,0,380,380,"5133","",0,"","","",1,0,0,[],""],["rm_t3-n5135",1,"Como una morsilla negra\nTengo yo mi corason;\nSerranilla, si lo vieras,\nTe habia de dar dolor.",1,0,-1,8,"",5,4,"o",-1,0,-1,0,380,380,"5135","",0,"","","",1,0,0,[],""],["rm_t3-n5137",1,"Válgame Dios de los cielos,\nVírgen del Mayor Dolor,\nComo una bayeta negra\nTengo yo mi corazon.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,380,380,"5137","",0,"palau_cantares, lafuente_madrid","","",33,0,0,[],""],["rm_t3-n5139",1,"Cualesquiera que me biere\nDirá que no tengo penas;\n¡Y tengo mi corason\nComo una bayeta negra!",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,380,381,"5139","",0,"","","",4,0,0,[],""],["rm_t3-n5141",1,"Todo el dia estoy tranquilo\nY en llegando la oracion\nUna piedra de molino\nParece mi corazon.",1,0,-1,8,"",0,4,"ao",31,0,-1,0,381,381,"5141","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n5143",1,"La alegría en mí no reina;\nTengo muerto el corazon.\n¡Madre mía del Amparo,\nValerme en esta ocasion!",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,381,381,"5143","",0,"","","",3,0,0,[],""],["rm_t3-n5144",1,"Si no fuera por la gente,\nYo me vistiera de luto:\nTengo yo mi corazon\nDentro del pecho difunto.",1,0,-1,8,"",0,4,"uo",-1,0,-1,0,381,381,"5144","",0,"","","",1,0,0,[],""],["rm_t3-n5147",1,"Mi corazon lo prendieron,\nY á la cárcel lo llevaron,\nY sin delito ninguno\nA muerte lo sentenciaron.",1,0,-1,8,"",0,4,"ao",41,0,-1,0,382,382,"5147","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n5148",1,"Un corazon de madera\nTengo de mandar hacer,\nQue no sienta ni padezca,\nNi sepa lo que es querer.",1,0,-1,8,"",0,4,"e",20,0,-1,0,382,382,"5148","",0,"","","",4,0,0,[],""],["rm_t3-n5150",1,"Triste el corazon se queja\nY yo le pregunto triste:\n—Corazon, ¿por qué te has muerto?—\nY él responde:—Porque quise.",1,0,-1,8,"",0,4,"ie",-1,0,-1,0,382,382,"5150","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n5151",1,"A mi corazon le digo\nQue se calle y no se queje\nY me contesta diciendo\nQue es mucho el dolor que siente.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,382,382,"5151","",0,"","","",4,0,0,[],""],["rm_t3-n5152",1,"A mi corazon le digo\nQue calle, que le conviene;\nCuando el corazon no calla,\nAlgun sentimiento tiene.",1,0,-1,8,"",0,4,"ee",70,0,-1,0,382,382,"5152","",0,"","","",4,0,0,[],""],["rm_t3-n5153",1,"Mi corazon lloraba;\nYo le decia:\n—Corazon, guarda penas\nPara otro dia.",1,0,-1,8,"",6,4,"a",0,0,-1,0,382,383,"5153","",0,"","","",1,0,0,[],""],["rm_t3-n5154",1,"Corazon mio, no llores,\nNo llores ni tengas penas:\nQue si tú pasas trabajos,\nOtros arrastran cadenas.",1,0,-1,8,"",0,4,"ea",62,0,-1,0,383,383,"5154","",0,"preciso_coleccion","","",3,0,0,[],""],["rm_t3-n5155",1,"Corason mio, no yores\nNi te muestres afligío;\nQue lo que ha sío y no es,\nComo si no hubiera sío.",1,0,-1,8,"",0,4,"io",3,0,-1,0,383,383,"5155","",0,"","","",1,0,0,[],""],["rm_t3-n5156",1,"Corazon, no suspires;\nAlma, no sientas;\nMemoria, no te acuerdas\nDe quien te acuerdas.\nMemoria y alma\nY corazon, no ameis\nA quien no os ama.",1,0,-1,8,"",4,7,"aa",-1,0,-1,0,383,383,"5156","",0,"","","",4,0,0,[],""],["rm_t3-n5157",1,"Ya te he dicho, corazon,\nPrimera y segunda vez\nQue no llames á esa puerta,\nQue no te han de responder.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,383,383,"5157","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t3-n5158",1,"No te aflijas, corazon,\nY cese ya tu quebranto;\nQue vendrá tiempo mejor\nY se acabará tu llanto.",1,0,-1,8,"",0,4,"ao",30,0,-1,0,383,383,"5158","",0,"","","",4,0,0,[],""],["rm_t3-n5159",1,"Se acabará mi querer,\nSe acabará mi llorar,\nSe acabará mi tormento\nY todo se acabará.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,383,383,"5159","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5160",1,"Mi corazon dió un suspiro\nY el alma le preguntó:\n-Corazon, ¿por qué suspiras?\n-Alma, porque tengo amor.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,384,384,"5160","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t3-n5161",1,"El corazon dió un suspiro\nY el alma le dijo:—Cesa;\nNo suspires, corazon,\nQue de tí nádie se acuerda.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,384,384,"5161","",0,"","","",3,0,0,[],""],["rm_t3-n5162",1,"¡Ay, pobrecito de mí,\nQue doy suspiros al aire,\nY el aire se me los lleva,\nY no los recoge nádie!",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,384,384,"5162","",0,"","","",4,0,0,[],""],["rm_t3-n5163",1,"Dando tristes suspiros\nDe sentimiento,\nAnegada en millanto,\nVivo muriendo.",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,384,384,"5163","",0,"","","",2,0,0,[],""],["rm_t3-n5165",1,"¡Válgame Dios de los cielos,\nQué penosito es mi mal!\nSuspirando tengo alivio;\nYa no puedo suspirar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,384,384,"5165","",0,"","","",33,0,0,[],""],["rm_t3-n5166",1,"-¡Válgame Dios del cielo,\n(Dijo una niña),\nLo que descansa un alma\nCuando suspira!",1,0,-1,8,"",6,4,"ia",-1,0,-1,0,384,384,"5166","",0,"palau_cantares, murciano_antiguo","","",8,0,0,[],""],["rm_t3-n5167",1,"Suspirando descansa\nCierto afligido,\nY el descanso le dura\nLo que el suspiro.",1,0,-1,8,"",6,4,"io",-1,0,-1,0,385,385,"5167","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5168",1,"Como mis penas nacen\nDe un vivo fuego,\nRepitiendo suspiros,\nMás las enciendo.\nY en esta fragua\nEl agua de mis ojos\nFomenta llamas.",1,0,-1,8,"",4,7,"aa",-1,0,-1,0,385,385,"5168","",0,"","","",1,0,0,[],""],["rm_t3-n5169",1,"Corazon desdichado,\nTú no estás bueno;\nQue suspiras, te agitas\nY tienes miedo.\nSé más constante,\nQue el mal que estás sufriendo\nNo es incurable.",1,0,-1,8,"",4,7,"ae",-1,0,-1,0,385,385,"5169","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5170",1,"Un suspiro me ofende\nY otro me alivia;\nPero no es favorable\nLa alternativa,\nPues los que ofenden\nSon más que los que alivian\nMi triste suerte.",1,0,-1,8,"",4,7,"ee",-1,0,-1,0,385,385,"5170","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5171",1,"¿Quién perdió lo que yo hallé?\nUn pañuelo casi nuevo,\nEn cada pico un suspiro\nY enmedio un ¡ay, que me muero!",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,385,385,"5171","",0,"","","",1,0,0,[],""],["rm_t3-n5172",1,"Suspiros, ¿por qué quereis\nSalir del corazon triste,\nSi sabeis que donde vais\nNunca jamás os reciben?",1,0,-1,8,"",0,4,"ie",-1,0,-1,0,386,386,"5172","",0,"","","",3,0,0,[],""],["rm_t3-n5173",1,"¡Bárgame Undebé der sielo,\nQué 'sgrasiaíto soy yo!\nSuspirando m' anochese,\nYorando me sale 'r só.",1,0,-1,8,"",0,4,"o",2,0,-1,0,386,386,"5173","",0,"","","",1,0,0,[],""],["rm_t3-n5174",1,"Más agua yoran mis ojos\nQue derrama una tormenta;\nLos suspiros no lo digo,\nPorque he perdía la cuenta.",1,0,-1,8,"",0,4,"ea",229,0,-1,0,386,386,"5174","",0,"","","",2,0,0,[],""],["rm_t3-n5175",1,"Cansado estoy de llorar,\nTriste de pegar suspiros,\nSuspenso de imaginar\nQue no puedo hablar contigo.",1,0,-1,8,"",0,4,"io",-1,0,-1,0,386,386,"5175","",0,"","","",1,0,0,[],""],["rm_t3-n5176",1,"A mi triste corason\nLas fatiguiyas lo ajogan,\nY no tiene más descanso\nQue 'r rato que por tí yora.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,386,386,"5176","",0,"","","",1,0,0,[],""],["rm_t3-n5178",1,"A los piés de mi madre\nNací llorando,\nAnunciando las penas\nQue estoy pasando.\nLlorando nací,\nAnunciando las penas\nQue paso por tí.",1,0,-1,8,"",4,7,"i",23,0,-1,0,386,387,"5178","",0,"","","",1,0,0,[],""],["rm_t3-n5180",1,"La otra tarde me dijeron\nQue tú ya no me querias,\nY no hago más que llorar,\nMoreno del alma mia.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,387,387,"5180","",0,"","","",1,0,0,[],""],["rm_t3-n5181",1,"De noche me sargo ar patio\nY me jarto de yorar,\nEn ber que te quiero tanto\nY tú no me quieres nâ.",1,0,-1,8,"",5,4,"",-1,0,-1,0,387,387,"5181","",0,"","","",3,0,0,[],""],["rm_t3-n5182",1,"Las sábanas de mi cama\nTodas las noches las lavo\nCon lágrimas de mis ojos,\nQue por tu querer derramo.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,387,387,"5182","",0,"","","",3,0,0,[],""],["rm_t3-n5183",1,"Cuando me siento en la cama\nY repaso mi memoria,\nLos ojos del corazon\nLágrimas de sangre lloran.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,387,387,"5183","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5184",1,"A orillas del mar me siento\nA recorrer mis memorias,\nY al acordarme de tí\nSangre mis ojitos lloran.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,387,387,"5184","",0,"","","",6,0,0,[],""],["rm_t3-n5185",1,"A orillas del mar me siento\nY á voces llamo á quien amo;\nY como no me responde,\nMuchas lágrimas derramo.",1,0,-1,8,"",0,4,"ao",100,0,-1,0,387,388,"5185","",0,"","","",6,0,0,[],""],["rm_t3-n5186",1,"Los ojitos de mi cara\nLos tengo jechos canales,\nEn ber que por tí he perdío\nA mi pare y á mi mare.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,388,388,"5186","",0,"","","",13,0,0,[],""],["rm_t3-n5188",1,"Los ojiyos e mi cara\nS' han secaíto e yorá,\nPorque 'l hombre qu' eyos quieren\nL' ha pagaíyo mu má.",1,0,-1,8,"",0,4,"a",9,0,-1,0,388,388,"5188","",0,"","","",1,0,0,[],""],["rm_t3-n5189",1,"Por consejos que le dieron,\nEya á mí m' aborresió;\nMis ojiyos sangre yoran\nPo esgrasiaítos que son.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,388,388,"5189","",0,"","","",1,0,0,[],""],["rm_t3-n5190",1,"¿De qué te sirve llorar,\nSi no tienes quien te oiga,\nSi el que te pudiera oir\nEstá viviendo en sus glorias?",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,388,388,"5190","",0,"","","",6,0,0,[],""],["rm_t3-n5192",1,"Cuando me veas llorar,\nNo me quites el pañuelo;\nQue mis penitas son grandes\nY llorando me consuelo.",1,0,-1,8,"",0,4,"eo",10,0,-1,0,388,389,"5192","",0,"","","",1,0,0,[],""],["rm_t3-n5193",1,"Ojos mios, lloremos,\nQue es el arbitrio\nQue les queda á los tristes\nPara su alivio.\nLloremos tanto,\nQue se aneguen mis ansias\nEn vuestro llanto.",1,0,-1,8,"",4,7,"ao",30,0,-1,0,389,389,"5193","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n5194",1,"Ojitos mios, yorar;\nLágrimas, tener pasiensia;\nQu' er que nase desgrasiao\nDesde pequeñito empiesa.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,389,389,"5194","",0,"","","",1,0,0,[],""],["rm_t3-n5195",1,"Mira qué desgrasiaíto,\nQue hasta por yorar, yoré\nEn er bientre de mi mare\nPoco ántes de naser.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,389,389,"5195","",0,"","","",1,0,0,[],""],["rm_t3-n5196",1,"Yorar, yorar, ojos mios;\nYorar si teneis por qué;\nQue no es bergüensa en un hombre\nYorar por una mujer.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,389,389,"5196","",0,"","","",1,0,0,[],""],["rm_t3-n5197",1,"Déjame yorar, amor,\nQue me tienes afligío;\nLa leña berde 'n er fuego\nSale 'l humo contenío.",1,0,-1,8,"",0,4,"io",3,0,-1,0,389,389,"5197","",0,"","","",1,0,0,[],""],["rm_t3-n5198",1,"Si quieres cambiar, cambiemos\nCorazones á llorar;\nDame el tuyo y toma el mio;\nVeremos cuál llora más.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,389,389,"5198","",0,"","","",3,0,0,[],""],["rm_t3-n5200",1,"Siempre que miro hácia el cielo\nLas lágrimas se me saltan;\nNo sé de qué ni por qué,\nPero lloro con el alma.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,390,390,"5200","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5201",1,"¿Qué me importa que la gente\nVea á mis ojos llorar,\nSi en el mundo todos lloran,\nUnos ménos y otros más?",1,0,-1,8,"",0,4,"a",-1,0,-1,0,390,390,"5201","",0,"","","",1,0,0,[],""],["rm_t3-n5203",1,"Tengo el corazon más duro\nQue las piedras de la calle;\nY son tan grandes mis penas,\nQue lloro gotas de sangre.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,390,390,"5203","",0,"","","",3,0,0,[],""],["rm_t3-n5205",1,"Yo sembré en una maceta\nLa semilla del encanto;\nCon lágrimas la regué...\n¡Mal haya quien llora tanto!",1,0,-1,8,"",0,4,"ao",30,0,-1,0,390,390,"5205","",0,"","","",2,0,0,[],""],["rm_t3-n5206",1,"Ni la tortolilla triste,\nNi el canario más sonoro,\nNi la fuente cristalina\nLlorarán como yo lloro.",1,0,-1,8,"",0,4,"oo",85,0,-1,0,391,391,"5206","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5207",1,"Los pajaritos y yo\nNos levantamos á un tiempo;\nEllos, á cantar el alba;\nYo, á llorar mi sentimiento.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,391,391,"5207","",0,"carrizo_salta","","",5,0,0,[],""],["rm_t3-n5208",1,"Salí yorando una pena\nDer templo de Salomon;\nLo que no tiene remedio,\nOrbidarlo es lo mejor.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,391,391,"5208","",0,"","","",1,0,0,[],""],["rm_t3-n5209",1,"Aquer que tenga fatigas\nBenga y s' arrime á mi bera;\nQu' ar berme yorando sangre,\nAlibio tendrán sus penas.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,391,391,"5209","",0,"","","",1,0,0,[],""],["rm_t3-n5210",1,"En er rincon más ocurto\nQue tiene la casa mia,\nAyí me pongo á yorar\nLa mala fortuna mia.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,391,391,"5210","",0,"","","",1,0,0,[],""],["rm_t3-n5211",1,"A la Bígen se le hisieron\nCanalitas e yorar;\nY yo digo que á mi cara\nGüesos no l' han de quedar.",1,0,-1,8,"",0,4,"a",21,0,-1,0,391,391,"5211","",0,"","","",1,0,0,[],""],["rm_t3-n5212",1,"Sufro, siento, padezco,\nSuspiro y lloro;\nTengo amor y con ésto\nLo digo todo.\nPorque el que adora\nSufre, siente, padece,\nSuspira y llora.",1,0,-1,8,"",4,7,"oa",107,0,-1,0,391,392,"5212","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5213",1,"Mi corason es muy niño;\nNo jase más que yorá;\nMientras más le digo «caya,»\nMás sentimiento le da.",1,0,-1,8,"",0,4,"a",9,0,-1,0,392,392,"5213","",0,"","","",1,0,0,[],""],["rm_t3-n5214",1,"Camisita de mi cuerpo,\nYa no te labas con agua;\nQue te labas con er yanto\nQue mis ojitos erraman.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,392,392,"5214","",0,"","","",1,0,0,[],""],["rm_t3-n5215",1,"Los jarales e mi nena\nNo se laban con pañí,\nQue se laban con la sangre\nDe su propio garlochí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,392,392,"5215","",0,"","","",1,0,0,[],""],["rm_t3-n5216",1,"Ar pié d' un pinito\nMe puse á yorá;\nY fueron tantas - las mias lagrimiyas,\nQue regué 'r piná.",1,0,-1,8,"",3,4,"a",9,0,-1,0,392,392,"5216","",0,"","","",1,0,0,[],""],["rm_t3-n5217",1,"Si las lágrimas que yoro\nSe me borbieran ladriyos,\nEnmedio der mar salado\nHisiera un fuerte castiyo.",1,0,-1,8,"",0,4,"io",-1,0,-1,0,392,392,"5217","",0,"","","",1,0,0,[],""],["rm_t3-n5218",1,"Si lágrimas fueran piedras\nLas que por tí he derramao,\nUn fuerte castiyo hisiera\nEnmedio der mar salao.",1,0,-1,8,"",0,4,"ao",98,0,-1,0,392,392,"5218","",0,"","","",3,0,0,[],""],["rm_t3-n5219",1,"Voy á la fuente y bebo,\nNo la aminoro;\nQue aumento su corriente\nCon lo que lloro.",1,0,-1,8,"",6,4,"oo",85,0,-1,0,393,393,"5219","",0,"","","",3,0,0,[],""],["rm_t3-n5220",1,"Yo voy á la fuente y bebo\nY el agua no la aminoro;\nQue se aumentan las corrientes\nCon las lágrimas que lloro.",1,0,-1,8,"",0,4,"oo",85,0,-1,0,393,393,"5220","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n5221",1,"Oriyita er río\nSus ducas yoraba;\nComo eran fuentes - sus ojitos negros,\nCresieron las aguas.",1,0,-1,8,"",3,4,"aa",-1,0,-1,0,393,393,"5221","",0,"","","",1,0,0,[],""],["rm_t3-n5222",1,"Lágrimas pedí á una fuente\nPara llorar mi tormento,\nPorque es tan grande mi pena,\nQue ya ni lágrimas tengo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,393,393,"5222","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5223",1,"A la mar fueron mis ojos\nPor agua para yorar,\nY no tubieron bastante,\nY se borbieron p' atrás.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,393,393,"5223","",0,"","","",3,0,0,[],""],["rm_t3-n5224",1,"A la mar fueron mis ojos\nPor agua para llorar,\nY se volvieron sin ella,\nPorque estaba seco el mar.",1,0,-1,8,"",0,4,"a",21,0,-1,0,393,393,"5224","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t3-n5225",1,"Disen que 'l agua dibierte\nY quita pena' y fatigas;\nYo m' arrimaré á una fuente,\nPor ber si el agua me anima.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,393,393,"5225","",0,"","","",1,0,0,[],""],["rm_t3-n5226",1,"Salí ar campo á dibertirme;\nFlores, dejarme, dejarme;\nAr que tiene una penita\nNo se la consuela nádie.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,394,394,"5226","",0,"","","",1,0,0,[],""],["rm_t3-n5227",1,"¿Qué importa que mis amigos\nMe saquen á divertir,\nSi en volviendo yo á mi casa,\nVuelvo de nuevo á sentir?",1,0,-1,8,"",0,4,"i",157,0,-1,0,394,394,"5227","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5228",1,"Si las penas mataran\nYa no existiera;\nY así vivo diciendo:\n-Me matan penas.",1,0,-1,8,"",6,4,"ea",-1,0,-1,0,394,394,"5228","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5229",1,"Dicen que las penas matan;\nYo digo que nó y que nó:\nQue si las penas mataran,\nYa estaria muerto yo.",1,0,-1,8,"",0,4,"o",2,0,-1,0,394,394,"5229","",0,"","","",6,0,0,[],""],["rm_t3-n5230",1,"Dicen que penas matan;\nYo digo que nó:\nQue si penas mataran,\nMe muriera yo.",1,0,-1,8,"",0,4,"o",2,0,-1,0,394,394,"5230","",0,"","","",1,0,0,[],""],["rm_t3-n5231",1,"Dicen que las penas matan;\nYo digo que no es así;\nQue si las penas mataran,\nMe hubieran matado á mí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,394,394,"5231","",0,"","","",6,0,0,[],""],["rm_t3-n5232",1,"Dicen que las penas matan,\nY yo digo que no es cierto;\nQue si mataran las penas,\nYa debia yo estar muerto.",1,0,-1,8,"",0,4,"eo",88,0,-1,0,394,394,"5232","",0,"","","",6,0,0,[],""],["rm_t3-n5233",1,"Dicen que las penas matan\nY yo digo que es mentira;\nQue si las penas mataran,\nYa no tuviera yo vida.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,395,395,"5233","",0,"","","",6,0,0,[],""],["rm_t3-n5234",1,"De pena y de sentimiento\nDicen que no muere nádie;\nYo me tengo de morir,\nPorque la mia es muy grande.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,395,395,"5234","",0,"","","",4,0,0,[],""],["rm_t3-n5235",1,"Yo no m' he muerto de pena,\nPorque no he sabío sentí;\nÁ mi corto entendimiento\nL' agraesco yo er bibí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,395,395,"5235","",0,"","","",1,0,0,[],""],["rm_t3-n5236",1,"Dentro de mi pecho tengo\nUna escalera de plata;\nLa suben los desengaños\nY los amores la bajan.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,395,395,"5236","",0,"","","",32,0,0,[],""],["rm_t3-n5237",1,"Dentro de mi pecho tengo\nDos escaleras de vidrio;\nPor una sube la pena,\nPor otra baja el alivio.",1,0,-1,8,"",0,4,"io",-1,0,-1,0,395,395,"5237","",0,"","","",32,0,0,[],""],["rm_t3-n5238",1,"Tengo pena y alegría,\nQue son dos males á un tiempo:\nCuando la pena me abate,\nLa alegría me da aliento.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,395,395,"5238","",0,"","","",1,0,0,[],""],["rm_t3-n5239",1,"Lo que me da más gusto\nMe da más pena;\nDe tormento me sirve\nLo que me alegra.",1,0,-1,8,"",6,4,"ea",-1,0,-1,0,395,395,"5239","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5240",1,"¿Quién ha visto en el mundo\nQuerer un ciego\nLa causa de su daño\nPara remedio?",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,396,396,"5240","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5241",1,"Corazon, que tu alivio\nPenando encuentras,\nSi en la pena descansas,\n¿De qué te quejas?",1,0,-1,8,"",6,4,"ea",-1,0,-1,0,396,396,"5241","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5242",1,"¡Cuántas y cuántas veces\nMi pensamiento\nSale á buscar alivios\nY halla tormentos!",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,396,396,"5242","",0,"","","",2,0,0,[],""],["rm_t3-n5243",1,"¡Oh, crüel, rigorosa\nFortuna mia!\n¿Cuándo de ser humana\nLlegará el dia?\n¿Cuándo tu rueda\nParará la inconstancia\nDe su carrera?",1,0,-1,8,"",4,7,"ea",-1,0,-1,0,396,396,"5243","",0,"","","",1,0,0,[],""],["rm_t3-n5244",1,"Cual nave combatida\nDe opuestos vientos,\nMi corazon fluctúa\nDentro del pecho.\nAllí navegan\nY sus tormentos nacen\nDe sus tormentas.",1,0,-1,8,"",4,7,"ea",-1,0,-1,0,396,396,"5244","",0,"","","",3,0,0,[],""],["rm_t3-n5245",1,"Como flores de almendro\nFueron mis bienes:\nQue nacieron temprano\nPara perderse.",1,0,-1,8,"",6,4,"ee",-1,0,-1,0,396,396,"5245","",0,"","","",1,0,0,[],""],["rm_t3-n5246",1,"Fueron mis ilusiones\nFlores de almendro,\nQue nacieron temprano,\nSe helaron presto.",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,397,397,"5246","",0,"","","",1,0,0,[],""],["rm_t3-n5247",1,"Siempre que miro al cangrejo\nMe pongo á considerar\nQue se parece á mis dichas,\nQue caminan hácia atrás.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,397,397,"5247","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5248",1,"Yo pienso que las dichas\nSe han escondido,\nPor no dar en el caso\nDe dar conmigo.\nCon las desdichas\nTropiezo á cada paso\nY en cada esquina.",1,0,-1,8,"",4,7,"ia",-1,0,-1,0,397,397,"5248","",0,"","","",2,0,0,[],""],["rm_t3-n5249",1,"Dicen que tras la alegría\nSuele venir el dolor;\nYo conozco los dolores,\nPero la alegría nó.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,397,397,"5249","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5250",1,"Cuando del bien no supe,\nViví contento;\nHoy que sé dónde mora,\nPor él me muero.\nY en tal conflicto,\nVoluntad y memoria\nSon mi cuchillo.",1,0,-1,8,"",4,7,"io",-1,0,-1,0,397,397,"5250","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5251",1,"Se queja y se lamenta.\nMi pensamiento,\nCuando hace memoria\nDe aquellos tiempos\nEn que lograba\nAmores repetidos\nDe quien amaba.",1,0,-1,8,"",4,7,"aa",28,0,-1,0,397,398,"5251","",0,"","","",1,0,0,[],""],["rm_t3-n5252",1,"Algun diafuí yo rey,\nY ahora soy un mal vasallo;\nAlgun dia gobernaba,\nY ahora me están gobernando.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,398,398,"5252","",0,"","","",1,0,0,[],""],["rm_t3-n5253",1,"Mil delicias amantes\nLogré algun tiempo,\nY ahora sólo pesares\nSon los que tengo.\nAmor tirano,\nHazme otra vez presentes\nTiempos pasados.",1,0,-1,8,"",4,7,"ao",-1,0,-1,0,398,398,"5253","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n5254",1,"Ya acabaron para mí\nGusto, placer y alegría,\nPorque no tiene consuelo\nPenita como la mia.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,398,398,"5254","",0,"","","",1,0,0,[],""],["rm_t3-n5255",1,"Ya yo no vivo con gusto;\nYa mi suerte se trocó;\nQuien perdió lo que bien quiso\nCuanto hay que perder perdió.",1,0,-1,8,"",0,4,"o",2,0,-1,0,398,398,"5255","",0,"","","",1,0,0,[],""],["rm_t3-n5256",1,"Ya no vivo yo en la calle\nDonde usté me conoció;\nQue vivo en la callejuela\nDel Desengaño mayor.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,398,398,"5256","",0,"","","",1,0,0,[],""],["rm_t3-n5257",1,"Los gustiyos que tenía\nSe m' han redusío á penas;\nVáyanse las horas malas\nPorlas qu'he pasao buenas.",1,0,-1,8,"",0,4,"ea",62,0,-1,0,398,399,"5257","",0,"","","",1,0,0,[],""],["rm_t3-n5258",1,"Engolfado en mis dichas\nYo estaba, cuando\nMi contraria fortuna\nMe volcó el carro.\n¡Quién talpensara,\nQue el carro de mis dichas\nMe lo volcara!",1,0,-1,8,"",4,7,"aa",57,0,-1,0,399,399,"5258","",0,"","","",1,0,0,[],""],["rm_t3-n5259",1,"Huyo con mucho gusto\nDe los contentos,\nPorque siento más pena\nCuando los dejo.\nY es muy constante\nMi desgracia, y mi dicha\nMuere al instante.",1,0,-1,8,"",4,7,"ae",47,0,-1,0,399,399,"5259","",0,"","","",1,0,0,[],""],["rm_t3-n5260",1,"Tengo una vana ilusion;\nTengo un loco pensamiento;\nTengo razon y no sé\nDar razon de lo que siento.",1,0,-1,8,"",0,4,"eo",94,0,-1,0,399,399,"5260","",0,"","","",1,0,0,[],""],["rm_t3-n5261",1,"Yo no sé lo que me pasa,\nNi tampoco lo que quiero;\nDigo, y no sé lo que digo;\nSiento, y no sé lo que siento.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,399,399,"5261","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5262",1,"Pienso y no sé lo que pienso;\nPienso, que soy desgraciado;\nPienso que siempre la soga\nQuiebra por lo más delgado.",1,0,-1,8,"",0,4,"ao",14,0,-1,0,399,399,"5262","",0,"","","",3,0,0,[],""],["rm_t3-n5263",1,"No le puedo ver el fin\nA este pensamiento mio;\nQue mientras más lo distraigo,\nMás grande es mi desvarío.",1,0,-1,8,"",0,4,"io",3,0,-1,0,400,400,"5263","",0,"","","",1,0,0,[],""],["rm_t3-n5265",1,"No hay males como mis males,\nNi penas como las mías;\nQue he perdío por mi gusto\nLo qu' en er mundo quería.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,400,400,"5265","",0,"","","",1,0,0,[],""],["rm_t3-n5266",1,"Nádie se duela de mí;\nSólo mis tormentos pase;\nQue el que busca el mal por sí\nA nádie debe quejarse.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,400,400,"5266","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5267",1,"De las penas que yo paso\nNádie tenga compasion;\nQue yo por mi propia mano\nMe busqué mi perdicion.",1,0,-1,8,"",0,4,"o",31,0,-1,0,400,400,"5267","",0,"","","",1,0,0,[],""],["rm_t3-n5270",1,"Porque soy desgraciada\nMi madre llora;\nNo llores, madre mia,\nQue no soy sola.",1,0,-1,8,"",6,4,"oa",-1,0,-1,0,400,401,"5270","",0,"","","",1,0,0,[],""],["rm_t3-n5271",1,"En un pozo muy profundo\nDepenas estoy nadando,\nY yo solo me confundo\nDe ver lo que estoy pasando.",1,0,-1,8,"",1,4,"ao",33,0,-1,0,401,401,"5271","",0,"","","",5,0,0,[],""],["rm_t3-n5272",1,"¡Bárgame Dios de los sielos,\nY qué peniya la mia,\nQue m' he caío en un poso\nY no encuentro la salía!",1,0,-1,8,"",0,4,"ia",0,0,-1,0,401,401,"5272","",0,"","","",3,0,0,[],""],["rm_t3-n5273",1,"Todo aquer que dise «¡ay!»\nEs señar que l'ha dolío;\nY yo digo:—¡Ay, ay,\nAy, probe corason mio\n[Cómo me lo martratais]!",1,0,-1,8,"",7,5,"aa",-1,0,-1,0,401,401,"5273","",0,"","","",1,0,0,[],""],["rm_t3-n5274",1,"De los que viven con pena\nNádie se iguale conmigo;\nQue estoy comiendo y bebiendo\nCon mi mayor enemigo.",1,0,-1,8,"",0,4,"io",106,0,-1,0,401,401,"5274","",0,"","","",1,0,0,[],""],["rm_t3-n5275",1,"Tengo yo un cofre lleno\nDe penas y ansias,\nDe ocasiones perdidas,\nTiempo y palabras.\nQue la fortuna\nTan sólo me enriquece\nDe desventuras.",1,0,-1,8,"",4,7,"ua",-1,0,-1,0,401,401,"5275","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5277",1,"Aquer que le paresiere\nQue mi penita no es nâ,\nMeta la mano en su pecho\nY se ponga en mi lugá.",1,0,-1,8,"",5,4,"a",-1,0,-1,0,402,402,"5277","",0,"","","",2,0,0,[],""],["rm_t3-n5278",1,"Las penas que pasó Cristo\nAyá en er monte Carbario\nLas tengo comparaítas\nCon las que yo estoy pasando.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,402,402,"5278","",0,"","","",1,0,0,[],""],["rm_t3-n5279",1,"Cuando er terremoto grande,\nEl agua yegó hasta 'rriba;\nPero no puo yegá\nAonde yegan mis fatigas.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,402,402,"5279","",0,"","","",2,0,0,[],""],["rm_t3-n5280",1,"Tengo el pecho atravesado,\nPor una espada cruel,\nUna herida en el costado,\nY en la garganta un cordel.",1,0,-1,8,"",1,4,"e",32,0,-1,0,402,402,"5280","",0,"","","",1,0,0,[],""],["rm_t3-n5281",1,"Tengo una pena, una pena,\nQue si esta pena me dura,\nYa me pueden preparar\nLa caja y la sepultura.",1,0,-1,8,"",0,4,"ua",17,0,-1,0,402,402,"5281","",0,"","","",4,0,0,[],""],["rm_t3-n5282",1,"Tengo una pena, ¡qué pena!\nTengo un doló, ¡qué doló!\nTengo un clabo remachao\nEn mitá der corason.",1,0,-1,8,"",5,4,"ao",-1,0,-1,0,402,402,"5282","",0,"","","",3,0,0,[],""],["rm_t3-n5283",1,"Me disen que los tormentos\nSon cosa de Inquisision,\nY yo digo qu' estos mios\nNo tienen comparasion.",1,0,-1,8,"",5,4,"ao",-1,0,-1,0,402,403,"5283","",0,"","","",1,0,0,[],""],["rm_t3-n5284",1,"Son tan grandes mis fatigas,\nQue me tiran á ajogá;\nSe siguen unas á otras,\nComo las olas der má.",1,0,-1,8,"",0,4,"a",9,0,-1,0,403,403,"5284","",0,"","","",4,0,0,[],""],["rm_t3-n5285",1,"Las penitas que yo siento\nSon cual las olas del mar:\nUnas penitas se vienen\nY otras penitas se van.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,403,403,"5285","",0,"","","",2,0,0,[],""],["rm_t3-n5286",1,"Las estrellitas del cielo\nY las arenas del mar\nSe parecen á mis penas\nEn lo largas de contar.",1,0,-1,8,"",0,4,"a",21,0,-1,0,403,403,"5286","",0,"carrizo_salta","","",25,0,0,[],""],["rm_t3-n5287",1,"Yo tiré un limon por arto,\nPor ber si coloreaba;\nSubió berde y bajó berde...\nMis penitas no se acaban.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,403,403,"5287","",0,"","","",1,0,0,[],""],["rm_t3-n5288",1,"Ya no puede ser el cuervo\nMás negro que son las alas;\nYa no pueden ser mis penas\nMás grandes que las pasadas.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,403,403,"5288","",0,"","","",1,0,0,[],""],["rm_t3-n5290",1,"Ni en Italia, ni en España,\nNi en Francia, ni en Berbería,\nNi en todo lo que el sol baña,\nHay pena como la mia.",1,0,-1,8,"",1,4,"a",0,0,-1,0,403,404,"5290","",0,"","","",2,0,0,[],""],["rm_t3-n5291",1,"Todas las penas del mundo\nNo igualan con esta mia;\nQue se me pasa llorando\nToda la flor de mi vida.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,404,404,"5291","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5292",1,"En lo profundo del mar\nTengo de enterrar mis penas;\nSon ya tantas mis fatigas,\nQue no caben en la tierra.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,404,404,"5292","",0,"","","",7,0,0,[],""],["rm_t3-n5293",1,"Yo no sé lo que me jaga;\nMe boy á la Morería,\nPorqu' en España no cabe\nToíta la peniya mia.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,404,404,"5293","",0,"","","",1,0,0,[],""],["rm_t3-n5294",1,"En la casa de las penas\nYa no me quieren á mí,\nPorque tengo yo más penas\nQue las que caben ayí.",1,0,-1,8,"",1,4,"i",23,0,-1,0,404,404,"5294","",0,"","","",1,0,0,[],""],["rm_t3-n5295",1,"Estoy ya jecho á bibí\nEn la casa de las penas;\nDesde 'r dia que nasí\nTomé posesion en ella.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,404,404,"5295","",0,"","","",1,0,0,[],""],["rm_t3-n5296",1,"Estoy tan hecho á penas,\nQue en no penando,\nParece que me falta\nLo necesario.",1,0,-1,8,"",6,4,"ao",-1,0,-1,0,404,404,"5296","",0,"","","",1,0,0,[],""],["rm_t3-n5297",1,"Estoy tan hecho á la pena,\nQue me sirve de compaña;\nY el dia que no la tengo\nMe parece cosa extraña.",1,0,-1,8,"",0,4,"aa",213,0,-1,0,404,405,"5297","",0,"carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["rm_t3-n5298",1,"Dicen al verme reir\nQue mi suerte es la mejor;\nTan hecho estoy á sufrir,\nQue me rio de dolor.",1,0,-1,8,"",1,4,"o",72,0,-1,0,405,405,"5298","",0,"","","",1,0,0,[],""],["rm_t3-n5300",1,"Penitas sobre penitas;\nSobre mis penas no hay nâ;\nEr que quiera tener penas,\nQue se ponga en mi lugar.",1,0,-1,8,"",5,4,"a",-1,0,-1,0,405,405,"5300","",0,"","","",2,0,0,[],""],["rm_t3-n5302",1,"A una piedra me arrimé\nA llorar mi. sentimiento,\nComo si fueran las piedras\nAlivio de mis tormentos.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,405,405,"5302","",0,"","","",1,0,0,[],""],["rm_t3-n5303",1,"En mitá der má\nHabía una piedra,\nY se sentaba mi compañerita\nA yorá sus penas.",1,0,-1,8,"",3,4,"ea",-1,0,-1,0,405,405,"5303","",0,"","","",1,0,0,[],""],["rm_t3-n5304",1,"A la cueba más profunda\nQue tiene 'r mar en su sentro,\nAyí me tengo de ir\nA yorar mi sentimiento.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,405,406,"5304","",0,"","","",2,0,0,[],""],["rm_t3-n5305",1,"En er mar hay una parra\nQue yega 'r sarmiento ar sielo,\nY ayí se ban á bibí\nLos que no tienen consuelo.",1,0,-1,8,"",0,4,"eo",10,0,-1,0,406,406,"5305","",0,"","","",1,0,0,[],""],["rm_t3-n5306",1,"Compañerita del alma,\n¿Qué quieres que yo te diga?\nQue con penillas me acuesto,\nMe levanto con penillas.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,406,406,"5306","",0,"palau_cantares, lafuente_madrid","","",20,0,0,[],""],["rm_t3-n5307",1,"Tengo un bestío de penas,\nCon mangas de sentimiento,\nY los faralares son\nDe lo qu' acarrea er tiempo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,406,406,"5307","",0,"","","",1,0,0,[],""],["rm_t3-n5308",1,"Tres cordeles á un tiempo\nMe están tirando,\nY el que ménos me tira\nMe está matando.\nTiran tan fuerte,\nQue el que ménos me tira\nMe da la muerte.",1,0,-1,8,"",4,7,"ee",134,0,-1,0,406,406,"5308","",0,"","","",1,0,0,[],""],["rm_t3-n5309",1,"¿Qué razon habrá en el mundo\nPara que yo esté pasando\nTantas penas y fatigas,\nY otros se estén alegrando?",1,0,-1,8,"",0,4,"ao",33,0,-1,0,406,406,"5309","",0,"","","",1,0,0,[],""],["rm_t3-n5310",1,"No sé si será desgrasia,\nO será sinito mio,\nQue toíto 'r mundo s' alegra\nDe lo que m' ha suseío.",1,0,-1,8,"",0,4,"io",3,0,-1,0,406,406,"5310","",0,"","","",1,0,0,[],""],["rm_t3-n5311",1,"Todo el mundo está empeñado\nEn dar tormento á mi cuerpo;\nNo sé qué motivo ha dado,\nPorque yo no se lo encuentro.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,407,407,"5311","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n5312",1,"Nádie se meta conmigo,\nQue yo con nadie me meto,\nY hasta las piedras que piso\nMe hacen pasar tormentos.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,407,407,"5312","",0,"","","",1,0,0,[],""],["rm_t3-n5313",1,"Ya no s' acuerda mi mare\nE los güesos e mi cuerpo;\nLos tengo apoliyaítos\nDe puro pasá tormentos.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,407,407,"5313","",0,"","","",1,0,0,[],""],["rm_t3-n5314",1,"La obejita es blanca\nY er praíto es berde;\nY er pastorsito - que la guarda, mare,\nDe peniya muere.",1,0,-1,8,"",3,4,"ee",-1,0,-1,0,407,407,"5314","",0,"","","",1,0,0,[],""],["rm_t3-n5315",1,"El dia que me case\nSerá en secreto,\nY dejaré las fiestas\nPara mi entierro.\nQue el desgraciado\nTan sólo estará alegre\nYa sepultado.",1,0,-1,8,"",4,7,"ao",14,0,-1,0,407,407,"5315","",0,"","","",2,0,0,[],""],["rm_t3-n5316",1,"Pâ los desgrasiaos\nHan jecho un combento,\nY er primerito - qu' ayí se metiere\nHa de sé mi cuerpo.",1,0,-1,8,"",3,4,"eo",-1,0,-1,0,407,407,"5316","",0,"","","",1,0,0,[],""],["rm_t3-n5317",1,"De pura bayeta negra\nMi cuerpo se ha de vestir;\nEsa es la mejor librea\nDe aquel que sabe sentir.",1,0,-1,8,"",0,4,"i",157,0,-1,0,408,408,"5317","",0,"","","",3,0,0,[],""],["rm_t3-n5318",1,"Las aves de la Arabia\nViven eternas;\nViven porque no saben\nLo que son penas.\nQue si penaran,\nEn el mundo no hubiera\nAves de Arabia.",1,0,-1,8,"",4,7,"aa",-1,0,-1,0,408,408,"5318","",0,"","","",2,0,0,[],""],["rm_t3-n5319",1,"Mi pensamiento al humo\nSe le parece:\nA medida que sube,\nSe desvanece.",1,0,-1,8,"",6,4,"ee",64,0,-1,0,408,408,"5319","",0,"","","",3,0,0,[],""],["rm_t3-n5320",1,"¡Pobres mulitas mias,\nSi mi cuidado\nComo pesa en el alma\nPesa en el carro!\nPues es preciso\nNos oprima y agobie\nUn peso mismo.",1,0,-1,8,"",4,7,"io",-1,0,-1,0,408,408,"5320","",0,"","","",1,0,0,[],""],["rm_t3-n5321",1,"¡Ay de aquella gitana\nQue se anda sola,\nSin la buena ventura\nQue tienen otras!",1,0,-1,8,"",6,4,"oa",-1,0,-1,0,408,408,"5321","",0,"","","",1,0,0,[],""],["rm_t3-n5322",1,"Anda y dile á quien yo quiero\nQue no se acuerde de mí;\nQue el que vive desgraciado\nNo necesita el vivir.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,408,409,"5322","",0,"","","",1,0,0,[],""],["rm_t3-n5323",1,"Soy el herido sin sangre;\nSoy el muerto sin acero;\nSoy el que penando vivo;\nSoy el que penando muero.",1,0,-1,8,"",0,4,"eo",38,0,-1,0,409,409,"5323","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5324",1,"Con el dolor que yo vivo\nEs imposible vivir;\nSi el mundo no da otra vuelta,\nDará de mi vida fin.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,409,409,"5324","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",5,0,0,[],""],["rm_t3-n5325",1,"Sin vida estoy por vivir\nLa vida que estoy viviendo;\nPues vivo, y no sé si vivo,\nPorque más que vivo, muero.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,409,409,"5325","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t3-n5326",1,"Cada vez que considero\nQue me tengo de morir,\nAlzo los ojos y digo:\n-Mi Dios, ¿para qué nací?",1,0,-1,8,"",0,4,"i",-1,0,-1,0,409,409,"5326","",0,"rm_t4","","",14,0,0,[],""],["rm_t3-n5327",1,"¿A qué santo llamaré\nPara aliviar esta pena,\nQue me ahoga la garganta,\nCual si fuera una cadena?",1,0,-1,8,"",0,4,"ea",59,0,-1,0,409,409,"5327","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5328",1,"Bírgen de Consolasion,\nLa qu' está en los olibares,\nConsuela mi corason,\nQu' está yeno de pesares.",1,0,-1,8,"",0,4,"ae",164,0,-1,0,409,409,"5328","",0,"","","",1,0,0,[],""],["rm_t3-n5329",1,"¡Ay de mí, que triste estoy\nY triste siempre estaré!\nYo nací para estar triste\nY triste me moriré.",1,0,-1,8,"",0,4,"e",77,0,-1,0,409,410,"5329","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5330",1,"Tristezas me ponen triste;\nTristezas salgo á buscar,\nPara ver si con tristezas\nTristezas puedo olvidar.",1,0,-1,8,"",0,4,"a",21,0,-1,0,410,410,"5330","",0,"machado_venezuela","","",2,0,0,[],""],["rm_t3-n5331",1,"En er queré no hay sabé;\nLo tengo esperimentao:\nDe lo que siempre he juío\nUndibé m' ha castigao.",1,0,-1,8,"",0,4,"ao",98,0,-1,0,410,410,"5331","",0,"","","",1,0,0,[],""],["rm_t3-n5332",1,"De lo que me reselaba\nBino Dios á castigarme:\nJuyendo der peregí,\nEn la frente bino á darme.",1,0,-1,8,"",0,4,"ae",35,0,-1,0,410,410,"5332","",0,"","","",1,0,0,[],""],["rm_t3-n5333",1,"La noche serró con agua;\nYa s' acabó mi bibí;\nS' han serraíyo las puertas\nDonde yo solia dí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,410,410,"5333","",0,"","","",1,0,0,[],""],["rm_t3-n5334",1,"No sé qué camino tome,\nQué senda ni qué berea;\nNo hay quien me dé un consejito,\nPara alibio de mis penas.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,410,410,"5334","",0,"","","",1,0,0,[],""],["rm_t3-n5335",1,"El corazon tengo triste\nY el alma tengo confusa;\nAlgo me va á suceder....\nTriste corazon, ¿qué anuncias?",1,0,-1,8,"",0,4,"ua",-1,0,-1,0,410,410,"5335","",0,"","","",3,0,0,[],""],["rm_t3-n5337",1,"¡Puñaladas en mi puerta!\n¡Cielos! ¿Qué sucede aquí?\nLos hombres se están matando...\nMadre, ¿si será por mí?",1,0,-1,8,"",0,4,"i",23,0,-1,0,411,411,"5337","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5339",1,"Toíto er mundo que me be\nMe pregunta que qué tengo:\nUn mar que no tiene cura\nY siempre m' estoy muriendo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,411,411,"5339","",0,"","","",1,0,0,[],""],["rm_t3-n5340",1,"¡Bárgame San Isidoro,\nPatron de Biyamartin!\nTodas las penas s' acaban;\nLamia no tiene fin.",1,0,-1,8,"",5,4,"i",-1,0,-1,0,411,411,"5340","",0,"","","",1,0,0,[],""],["rm_t3-n5341",1,"Yo me subí á la muraya\nY le dije ar murayero:\n-No me tir' usté chinitos;\nMi mar no tiene remedio.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,411,411,"5341","",0,"","","",2,0,0,[],""],["rm_t3-n5342",1,"Es mi pena tan fuerte,\nMi mal tan grave,\nQue acabaré la vida\nSin que él acabe.\nCurar podria,\nSi no fuese veneno\nLa medicina.",1,0,-1,8,"",4,7,"ia",-1,0,-1,0,411,411,"5342","",0,"","","",2,0,0,[],""],["rm_t3-n5343",1,"Yo pensé que con el tiempo\nMis penas se acabarian,\nY se me van aumentando,\nComo las horas del dia.",1,0,-1,8,"",5,4,"a",-1,0,-1,0,412,412,"5343","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5344",1,"Al infierno parecen\nMis pensamientos,\nEn el atormentarme\nY en ser eternos.",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,412,412,"5344","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n5345",1,"Pâ toítos los males\nManda Dios remedio;\nY pâ las ducas - que m' están matando\nNi lo hay ni lo espero.",1,0,-1,8,"",3,4,"eo",-1,0,-1,0,412,412,"5345","",0,"","","",1,0,0,[],""],["rm_t3-n5346",1,"Muerto estaré y enterrao\nY de gusanos roío,\nY no han de fartar le penas\nAr probe corason mio.",1,0,-1,8,"",0,4,"io",3,0,-1,0,412,412,"5346","",0,"","","",1,0,0,[],""],["rm_t3-n5347",1,"A mis enemigos\nNo le mande Dios\nEstas duquitas - negritas e muerte\nQu' á mí me mandó.",1,0,-1,8,"",3,4,"o",-1,0,-1,0,412,412,"5347","",0,"","","",1,0,0,[],""],["rm_t3-n5348",1,"Si esto que me pasa\nLe pasara á otro,\nEra cosita - de prebelicarse\nY gorberse loco.",1,0,-1,8,"",3,4,"oo",-1,0,-1,0,412,412,"5348","",0,"","","",1,0,0,[],""],["rm_t3-n5349",1,"No sé cómo ya no estoy\nCon caenas amarrao,\nMardisiendo mi fortuna,\nAr paraje qu' ha yegao.",1,0,-1,8,"",0,4,"ao",98,0,-1,0,412,412,"5349","",0,"","","",1,0,0,[],""],["rm_t3-n5350",1,"Yo digo que no hay locura;\nPorque si locura hubiera,\nAmarrao á una coluna\nMi cuerpesito estubiera.",1,0,-1,8,"",0,4,"ea",44,0,-1,0,413,413,"5350","",0,"","","",2,0,0,[],""],["rm_t3-n5351",1,"Tiro piedras por la caye;\nAr que le dé que perdone:\nTengo la cabesa loca,\nDe tantas cabilasiones.",1,0,-1,8,"",0,4,"oe",-1,0,-1,0,413,413,"5351","",0,"","","",2,0,0,[],""],["rm_t3-n5352",1,"Tiro piedras por la caye;\nPerdóneme ar que le diere:\nTengo la cabesa loca,\nDe pensar en tus quereles.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,413,413,"5352","",0,"","","",2,0,0,[],""],["rm_t3-n5353",1,"Nádie diga qu' estoy loco\nPorqu' he tiraíyo piedras:\nQue se ponga en mi lugá\nAquer que quiere de béras.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,413,413,"5353","",0,"","","",1,0,0,[],""],["rm_t3-n5354",1,"Ya viene la noche triste\nPara mí que estoy penando;\nDuerma quien tuviere sueño,\nQue yo la paso velando.",1,0,-1,8,"",0,4,"ao",33,0,-1,0,413,413,"5354","",0,"","","",2,0,0,[],""],["rm_t3-n5355",1,"Cuando biene 'r dia\nTengo argun consuelo;\nPero en yegando - á la nochesita,\nSiego yo y no beo.",1,0,-1,8,"",3,4,"eo",-1,0,-1,0,413,413,"5355","",0,"","","",1,0,0,[],""],["rm_t3-n5356",1,"A Undebé l' estoy pidiendo\nDe béras que benga 'l arba,\nPor bé si esta pena mía\nAr sueño se sujetaba.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,413,413,"5356","",0,"","","",3,0,0,[],""],["rm_t3-n5357",1,"El sueño tengo perdido\nY no sé dónde buscarlo;\nLo buscaré en el olvido...\n¿Y el olvido? ¿Dónde hallarlo?",1,0,-1,8,"",1,4,"ao",236,0,-1,0,414,414,"5357","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5358",1,"Er dia paso entre angustias;\nLa noche la paso en bela;\nSi yo no me güerbo loco,\nNo hay ya quien loco se güerba.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,414,414,"5358","",0,"","","",1,0,0,[],""],["rm_t3-n5360",1,"Enmedio de mis fatigas,\nPor vivir quise dormirme;\nQue el que vive como yo,\nCuando duerme es cuando vive.",1,0,-1,8,"",0,4,"ie",-1,0,-1,0,414,414,"5360","",0,"","","",3,0,0,[],""],["rm_t3-n5361",1,"Dicen que sueño es muerte,\nMas yo lo niego;\nPues cuando duermo, vivo;\nCuando nó, muero.",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,414,414,"5361","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n5362",1,"En la cama me siento\nA media noche,\nCansado de mis muchas\nCavilaciones.\nY aunque cavilo,\nPara mis tristes penas\nNo encuentro alivio.",1,0,-1,8,"",4,7,"io",-1,0,-1,0,414,414,"5362","",0,"","","",2,0,0,[],""],["rm_t3-n5363",1,"A llorar mi triste suerte\nEn la cama me senté,\nConsiderando tan léjos\nLo que tan cérca soñé.",1,0,-1,8,"",0,4,"e",77,0,-1,0,414,415,"5363","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5365",1,"Me siento sobre la cama,\nY te comienso á yamá,\nY á las paeres m' agarro...\n¡Si será... si no será!",1,0,-1,8,"",0,4,"a",9,0,-1,0,415,415,"5365","",0,"","","",2,0,0,[],""],["rm_t3-n5366",1,"Me siento sobre la cama,\nY repaso mi memoria,\nY con las paredes hablo,\nY no hallo quien me responda.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,415,415,"5366","",0,"","","",2,0,0,[],""],["rm_t3-n5368",1,"¿De qué te sirve, ¡ay, cielos!\nHacer memoria\nDe saber que has logrado,\nSi ya no logras;\nPues sólo queda\nUna memoria triste\nCuando se acuerda?",1,0,-1,8,"",4,7,"ea",-1,0,-1,0,415,415,"5368","",0,"","","",1,0,0,[],""],["rm_t3-n5369",1,"En el retrete oscuro\nDe la memoria,\nRepasaba un amante\nPasadas glorias.\nY así decia:\n-No quiero entristecerme\nCon alegrías.",1,0,-1,8,"",4,7,"ia",-1,0,-1,0,415,416,"5369","",0,"","","",1,0,0,[],""],["rm_t3-n5370",1,"Para aliviar mis penas\nYo necesito\nA cambio de memorias\nComprar olvidos.\nQue la memoria\nNo importa que se pierda\nCuando no importa.",1,0,-1,8,"",4,7,"oa",-1,0,-1,0,416,416,"5370","",0,"palau_cantares","","",3,0,0,[],""],["rm_t3-n5371",1,"Para saber que vivo\nSólo han quedado\nUnas memorias tristes\nDe lo pasado.\n¡Tristes memorias,\nFormadas con cenizas\nDe muertas glorias!",1,0,-1,8,"",4,7,"oa",237,0,-1,0,416,416,"5371","",0,"","","",1,0,0,[],""],["rm_t3-n5372",1,"Déjame, memoria triste,\nQue me estás atormentando;\nSi lo quise ó no lo quise,\nNo me lo estés recordando.",1,0,-1,8,"",0,4,"ao",33,0,-1,0,416,416,"5372","",0,"","","",2,0,0,[],""],["rm_t3-n5373",1,"Déjame, memoria triste,\nQue me atormentas el alma;\nNo traigas al pensamiento\nPenitas que son pasadas.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,416,416,"5373","",0,"","","",2,0,0,[],""],["rm_t3-n5374",1,"Pensamiento, tú me matas;\nTú me tiras á perder;\nTú me traes á la memoria\nCosas que no pueden ser.",1,0,-1,8,"",0,4,"e",20,0,-1,0,416,417,"5374","",0,"","","",1,0,0,[],""],["rm_t3-n5375",1,"Deja de atormentarme,\nCruda memoria,\nPoniéndome presentes\nPasadas glorias.\nMemoria triste,\n¿Para qué me presentas\nLo que no existe?",1,0,-1,8,"",4,7,"ie",153,0,-1,0,417,417,"5375","",0,"","","",1,0,0,[],""],["rm_t3-n5377",1,"Dentro de mi pecho tengo\nUn relicario de plata,\nY un poquito más adentro\nUn recuerdo que me mata.",1,0,-1,8,"",0,4,"aa",74,0,-1,0,417,417,"5377","",0,"","","",32,0,0,[],""],["rm_t3-n5378",1,"Las fatigas de un enfermo\nCuando está para morir,\nEsas mismas paso yo\nCuando me acuerdo de tí.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,417,417,"5378","",0,"","","",4,0,0,[],""],["rm_t3-n5379",1,"Los ojitos de mi cara,\n¿Quién los compra? que los vendo:\nTan pobre me voy quedando,\nQue ni ojitos tener puedo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,417,417,"5379","",0,"","","",13,0,0,[],""],["rm_t3-n5380",1,"Tengo unos ojiyos, mare,\nQue me costó un dinerá;\nAhora los quiero bendé\nPor lo que me quieran dá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,417,417,"5380","",0,"","","",1,0,0,[],""],["rm_t3-n5381",1,"Los ojitos de mi cara,\n¿Quién me los quiere comprar?\nLos vendo por traicioneros,\nPorque publican mi mal.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,418,418,"5381","",0,"carrizo_salta, palau_cantares","","",13,0,0,[],""],["rm_t3-n5383",1,"Yo me descubrí á un amigo,\nPor ver si me consolaba,\nY el amigo estaba enfermo\nDel mismo mal que yo estaba.",1,0,-1,8,"",0,4,"aa",28,0,-1,0,418,418,"5383","",0,"","","",1,0,0,[],""],["rm_t3-n5384",1,"Los males comunicados\nDicen que tienen consuelo;\nYo te he contado los mios\nY desde entónces me muero.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,418,418,"5384","",0,"","","",1,0,0,[],""],["rm_t3-n5385",1,"Por Dios te lo pido, niña,\nY te lo pido llorando,\nQue no le cuentes á nádie\nLo que á mí me está pasando.",1,0,-1,8,"",0,4,"ao",33,0,-1,0,418,418,"5385","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5386",1,"A aquel que tiene fatigas\nSe le conoce en la cara;\nA mí me están ahogando\nY no me conoces nada.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,418,418,"5386","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5387",1,"En er mundo no s' ha bisto\nMujé de mi caliá;\nQue tengo er semblante alegre\nY la sangre achicharrá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,418,418,"5387","",0,"","","",1,0,0,[],""],["rm_t3-n5388",1,"Dentro de mi pecho tengo\nUn arquita con dos llaves\nY en ella tengo metidas\nCositas que nádie sabe.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,419,419,"5388","",0,"","","",32,0,0,[],""],["rm_t3-n5389",1,"Todo el mundo me pregunta\nQué adelanto con llorar,\nY yo le respondo al mundo:\n-Algun dia se sabrá.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,419,419,"5389","",0,"","","",1,0,0,[],""],["rm_t3-n5390",1,"Corazon triste y lloroso,\nLleno de melancolía,\nLo que á tí te está pasando\nYo lo contaré algun dia.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,419,419,"5390","",0,"","","",1,0,0,[],""],["rm_t3-n5391",1,"Aunque tengo más fatigas\nQue cuando murió mi madre,\nLo callo y lo disimulo,\nPor que no lo advierta nádie.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,419,419,"5391","",0,"","","",1,0,0,[],""]]);
